const USAGE = `Usage: bun scripts/ui-check.ts --out <folder> [options]

  --out <folder>       where report.json and the screenshots go
  --port <port>        the test port the harness boots kitespan on, 7941 to 7949 (default ${DEFAULT_PORT})
  --dist <folder>      a built page to serve (default: build web/index.html into a scratch folder)
  --page <index.html>  build this page instead of web/index.html
  --base <url>         check a kitespan that runs already: no seed and no boot (the action checks press buttons, so a test copy)
  --chrome <binary>    the Chrome for Testing to start (default: CHROME_PATH, PATH, then the usual install caches)
  --cdp <endpoint>     use a Chrome that runs already (ws:// URL, http://host:port or a port) instead of starting one
  --routes <names>     only these routes or check ids, comma-separated (* matches any characters)
  --skip <names>       leave out the checks with these route names or check ids, comma-separated (* as in --routes),
                       for example --skip 'update*' leaves out the update action and the update flows only
  --scenes <list>      only checks in these scenes (${SCENES.join(", ")})
  --sizes <list>       laptop,medium,phone,m626,m768,large,large-land,phone-land (default: all eight; DESIGN-T1 3.1:
                       medium is 834x1194, m626 626x890, m768 768x1024, large 1024x1366 and large-land 1366x1024 with
                       touch, phone-land 844x390 with its safe areas)
  --themes <list>      dark,light (default: both)
  --checks <list>      routes,history,actions,flows (default: all four)
  --passes <list>      text-size,looks: the route checks once more at text size 1.3 (phone, m626, large) and in
                       Paper, Mono and Editor (m626, large), or none (default: both)
  --jobs <n>           pages checked at the same time (default 4, or 1 with --cdp)
  --action-wait <ms>   how long an action route stays open before its press (default 2000)
  --gap <s>            the slow-network flow's cut of the link, in seconds (default 30; 5 to 300)
  --keep               leave each scene's scratch folder (the seed and the server's logs) in place
  --server-env <list>  NAME=value pairs, comma-separated, added to each booted server's environment (for example
                       HTTP_PROXY and http_proxy at a port where nothing listens); never a name the seed sets`;

type Status = "pass" | "fail" | "warn";
type Kind = "route" | "history" | "action" | "flow";
interface Finding {
  code: string;
  text: string;
}
interface CheckResult {
  kind: Kind;
  /** The route's name, or the check's own id (an action variant, a flow). */
  name: string;
  route: string;
  scene: SeedSceneName | null;
  /** The size's label (sizeTag): its class where the size is one of --sizes' own. */
  size: string;
  theme: Theme;
  path: string;
  status: Status;
  failures: Finding[];
  warnings: Finding[];
  note: string;
  shot?: string;
  ms: number;
  details: Record<string, unknown>;
}

// ---------------------------------------------------------------------------------------------------------------
// Arguments

function fail(line: string, code = 2): never {
  console.error(`ui-check: ${line}`);
  process.exit(code);
}

function parseArgs(argv: string[]): Record<string, string> {
  const out: Record<string, string> = {};
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i]!;
    if (a === "-h" || a === "--help") out.help = "1";
    else if (a === "--keep") out.keep = "1";
    else if (a.startsWith("--")) {
      const eq = a.indexOf("=");
      if (eq > 0) out[a.slice(2, eq)] = a.slice(eq + 1);
      else {
        const v = argv[i + 1];
        if (v === undefined || v.startsWith("--")) fail(`${a} needs a value (see --help)`);
        out[a.slice(2)] = v;
        i++;
      }
    } else fail(`unexpected argument "${a}" (see --help)`);
  }
  return out;
}

const KNOWN = new Set(["help", "out", "port", "dist", "page", "base", "chrome", "cdp", "routes", "skip", "scenes", "sizes", "themes", "checks", "passes", "jobs", "action-wait", "gap", "keep", "server-env"]);
const args = parseArgs(process.argv.slice(2));
if (args.help) {
  console.log(USAGE);
  process.exit(0);
}
for (const k of Object.keys(args)) if (!KNOWN.has(k)) fail(`unknown option --${k} (see --help)`);
if (!args.out) fail("--out is required (see --help)");
if (args.chrome && args.cdp) fail("give --chrome or --cdp, not both");
if (args.base && (args.dist || args.page || args.port)) fail("--base checks a kitespan that runs already; --dist, --page and --port are for the harness");
if (args.dist && args.page) fail("give --dist or --page, not both");

function list<T extends string>(raw: string | undefined, all: readonly T[], what: string): T[] {
  if (!raw) return [...all];
  const items = raw.split(",").map((s) => s.trim()).filter(Boolean);
  for (const i of items) if (!all.includes(i as T)) fail(`unknown ${what} "${i}"; use ${all.join(", ")}`);
  return all.filter((a) => items.includes(a));
}

const SIZES = list(args.sizes, SIZE_LABELS, "size");
const THEMES = list(args.themes, ["dark", "light"] as const, "theme");
const CHECKS = list(args.checks, ["routes", "history", "actions", "flows"] as const, "check");
/** DESIGN-T1 3.2's two passes of the route checks (text size 1.3; the other looks); "none" leaves both out. */
const PASSES = args.passes === "none" ? [] : list(args.passes, ["text-size", "looks"] as const, "pass");
const ONLY_SCENES = list(args.scenes, SCENES, "scene");
const JOBS = args.jobs ? Number(args.jobs) : args.cdp ? 1 : 4;
if (!Number.isInteger(JOBS) || JOBS < 1 || JOBS > 16) fail("--jobs must be a whole number from 1 to 16");
const ACTION_WAIT = args["action-wait"] ? Number(args["action-wait"]) : 2000;
if (!Number.isFinite(ACTION_WAIT) || ACTION_WAIT < 0 || ACTION_WAIT > 60000) fail("--action-wait must be from 0 to 60000 ms");
const KEEP = Boolean(args.keep);
/** --server-env: names added to each booted server's environment (the harness refuses the seed's own). */
const SERVER_ENV: Record<string, string> = {};
for (const item of (args["server-env"] ?? "").split(",").filter(Boolean)) {
  const eq = item.indexOf("=");
  if (eq < 1) fail(`--server-env takes NAME=value pairs, not "${item}"`);
  SERVER_ENV[item.slice(0, eq)] = item.slice(eq + 1);
}
if (args.base && Object.keys(SERVER_ENV).length) fail("--server-env is for the servers the harness boots, not --base");

/** The kitespan under test when it runs already (--base); null: the harness boots one per scene. */
const BASE: string | null = (() => {
  if (!args.base) return null;
  let u: URL;
  try {
    u = new URL(args.base);
  } catch {
    fail(`--base must be an http or https URL, not "${args.base}"`);
  }
  if (u.protocol !== "http:" && u.protocol !== "https:") fail(`--base must be an http or https URL, not "${args.base}"`);
  // The other apps on this host are never touched; the demo copy on 7940 only by read-only checks.
  const port = Number(u.port || (u.protocol === "https:" ? 443 : 80));
  if ([7681, 7936, 7937].includes(port)) fail(`port ${port} is not kitespan's; the check never touches it`);
  if (port === 7940 && (CHECKS.includes("actions") || CHECKS.includes("flows"))) fail("port 7940 is the demo copy: the action checks and the flows press buttons there; give --checks routes,history, or use a test copy on 7941 to 7949");
  return u.origin;
})();
const PORT = args.port ? Number(args.port) : DEFAULT_PORT;
if (!BASE) {
  try {
    checkPort(PORT);
  } catch (e) {
    fail((e as Error).message);
  }
}
const OUT = resolve(args.out);

// Headless Chrome has no pointing device: it reports (pointer: none) and (hover: none), and setEmulatedMedia does not
// change those two. These Blink settings give its pages a fine, hovering pointer, as a laptop has; touch emulation
// still makes the tablet and phone pages coarse with no hover (a probe on Chrome for Testing 154 showed both).
const FINE_POINTER = "--blink-settings=primaryPointerType=4,availablePointerTypes=4,primaryHoverType=2,availableHoverTypes=2";

/**
 * The flows: the + menu and its file picker, in plain Chrome and with the iPhone's dropped history.back(); two pages
 * on one chat (D49, 8.3 check 26): a laptop page and a phone page, each in a browser context of its own; the phone's
 * Terminal page (shellPageFlow): a reload types nothing, the folder's name, one 5.4 line on a bad link; the phone's
 * swipe on a chat row (swipeFlow): Delete then Cancel goes back to /chats, and a tap on a group heading only closes
 * the swipe's actions; a link to a file that is not in the chat's folder (fileGoneFlow): the 5.4 line, with no
 * failed request and no console error, at each size; and a message that starts with "!" (bangMessageFlow): link text
 * edited and reloaded stays a message (the draft's mode is the store's field, never its text's first character);
 * composer links opened as new documents after the chat's page (sendNewDocumentFlow); Settings' facts after a
 * reload (settingsFactsFlow); New environment's folder finder (newEnvironmentFlow); and v0.3 search: the search pane on
 * a laptop (searchPaneFlow), Search's key from the places the user is (paletteFlow), the pane on the tablet and the
 * phone (searchTouchFlow), and the @ picker by keyboard (atPickerFlow) and by touch (atPickerTouchFlow); and the / menu
 * at a mid-line / (D57) by keyboard (slashMidlineFlow) and by touch (slashMidlineTouchFlow); and the reconnect and
 * restart flows on seeds of their own (resumeDropFlow, resumeReloadFlow, resumeSlowFlow, restartFlow), and part 1's
 * other paths (offlineSendAgainFlow, resumeBlackholeFlow, resumeTwoPagesFlow, resumeWakeFlow, resumeTailFlow,
 * resumeRttFlow, restartCancelFlow, restartNowFlow, endHereFlow, finishingFlow); and part 2's worktrees and an
 * environment's variables on the worktree scene's seeds (worktreeNewFlow, worktreeGoneFlow, worktreeArchiveDeleteFlow,
 * envEditorFlow, worktreeOffFlow); and row 99's environment menu (envRoutesFlow, envRenameFlow, envMoveFlow,
 * envRemoveFlow), with part 2's Remove of a worktree environment with variables (envRemoveWorktreeFlow); and row 102's
 * drag of a heading by a finger's long press (envMoveTouchFlow), and row 107's by a mouse's (envMoveLongPressFlow);
 * and row 111's Send now on a queued message (sendNowFlow) and its key, Ctrl+Enter (sendNowKeyFlow); and FIX-U6's
 * standalone mode in an app window (standaloneFlow) and the theme colour in the four looks (themeColorFlow); and row
 * 116's four dots and the seen flag on the dots scene's seed (unseenDotRun); and FIX-C1's phone message box with a
 * draft of several lines (composerLinesRun).
 */
const FLOW_IDS = ["menu-picker", "menu-picker-webkit", "two-pages", "shell-page", "row-menu", "row-swipe-delete", "row-swipe-heading", "file-gone", "bang-message", "send-new-document", "offline-send", "offline-send-again", "settings-facts", "settings-new-document", "keyboard", "card-keyboard", "files-pane", "new-environment", "search-pane", "search-pane-touch", "palette", "at-picker", "at-picker-ime", "at-picker-no-match", "at-picker-not-opened", "at-picker-touch", "slash-midline", "slash-midline-touch", "chip-layout", "form-slash", "form-at", "form-start", "session-settings", "smooth-text", "panes", "pane-slide", "logo-link", "settings-kept", "settings-kept-live", "held-box", "resume-drop", "resume-reload", "resume-slow", "resume-blackhole", "resume-two-pages", "resume-wake", "resume-tail", "resume-rtt", "restart", "restart-cancel", "restart-now", "end-here", "finishing", "worktree-new", "worktree-gone", "worktree-archive-delete", "env-editor", "worktree-off", "worktree-refused", "env-routes", "env-rename", "env-move", "env-move-touch", "env-move-longpress", "env-remove", "env-remove-worktree", "update-setting", "update-check-now", "update-run", "update-refused", "update-install", "update-brew", "send-now", "send-now-key", "standalone", "theme-color", "unseen-dot", "side-chat", "side-chat-running", "side-draft", "turn-fold", "turn-rail", "trust-folder", "background-session", "notify", "bring-back", "composer-lines", "search-text", "split-panel", "split-review", "changes-card", "claude-minimum", "send-follow", "browser-pane", "browser-looks", "browser-stop", "browser-cases", "browser-restart", "longpress-title", "longpress-tool", "longpress-file", "longpress-upload", "cut-output", "stream-hold", "menus-laptop", "stop-menu", "open-on-phone", "keyboard-release", "ime-touch", "composer-fit", "changes-over", "key-bar", "large-composer", "toast-hold", "shortcuts-touch", "browser-select", "d26", "copy-paste-touch", "copy-failed", "column-form", "parity-controls", "plus-pickers"] as const;
/** The flows on the chat list (picked by --routes chats too). */
