const SHOWN_ANY = (sel: string) => `(() => [...document.querySelectorAll(${JSON.stringify(sel)})].some((el) => el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden"))()`;

interface RouteCase {
  /** The route's name, or the variant's id. */
  id: string;
  route: RouteDef;
  scene: RouteSceneName | null;
  path: string;
  /** Test ids that must show. */
  ids: string[];
  /** The 5.4 line that must show, or null for none. */
  notice: string | null;
  /** A path the page may move to instead of the asked one (the 5.4 fallback). */
  fallback: string | null;
}

function expectedIds(r: RouteDef): string[] {
  const ids = EXPECT_CASE[r.name]?.ids ?? EXPECT[r.name]?.(paramsOf(r, r.example)) ?? [];
  return CHAT_FAMILY(r) ? ["chat", ...ids] : ids;
}

function routeCases(): RouteCase[] {
  const out: RouteCase[] = [];
  for (const r of ROUTES) {
    const scene = BASE ? null : sceneOfRoute(r.name);
    if (!picked([r.name], scene)) continue;
    const c = EXPECT_CASE[r.name];
    out.push({ id: r.name, route: r, scene, path: r.example, ids: expectedIds(r), notice: c?.notice ?? null, fallback: c?.fallback ?? null });
  }
  if (!BASE)
    for (const v of ROUTE_VARIANTS) {
      if (!picked([v.id, v.route], v.scene)) continue;
      const r = ROUTE[v.route]!;
      out.push({ id: v.id, route: r, scene: v.scene, path: v.path ?? r.example, ids: v.shows ?? expectedIds(r), notice: v.notice ?? null, fallback: v.fallback ?? null });
    }
  if (!BASE)
    for (const v of SPLIT_CASES) {
      if (!picked([v.id, v.route], "main")) continue;
      const r = ROUTE[v.route]!;
      out.push({ id: v.id, route: r, scene: "main", path: v.path, ids: v.shows, notice: v.notice ?? null, fallback: null });
    }
  return out;
}

/**
 * U4 (DESIGN-U4 6): the split side panel's URL form, as route cases on the main scene's example chat. Each shows the
 * URL's own view at every size (the flow split-panel checks the other half where the split shows: the laptop's column
 * and the tablet's docked pane); a refused pair shows that view alone with 5.4's one line.
 */
const SPLIT_CASES: { id: string; route: string; path: string; shows: string[]; notice?: string }[] = [
  { id: "split-file-shell", route: "files", path: `/c/${EX.chat}/files/${EX.file}?below=shell`, shows: ["file-download"] },
  { id: "split-shell-outputs", route: "shell", path: `/c/${EX.chat}/shell?above=outputs`, shows: ["terminal-pane", "terminal"] },
  { id: "split-search-shell", route: "chatSearch", path: `/c/${EX.chat}/search?q=upl&below=shell`, shows: ["search"] },
  { id: "split-context-btw", route: "context", path: `/c/${EX.chat}/context?below=btw`, shows: ["chat", "side-context"] },
  { id: "split-refused", route: "context", path: `/c/${EX.chat}/context?below=outputs`, shows: ["chat", "side-context"], notice: "Part of that link could not be read." },
];

const shownMatch = (want: string, ids: string[]) =>
  want.split("|").some((alt) => (alt.endsWith("*") ? ids.some((i) => i.startsWith(alt.slice(0, -1))) : ids.includes(alt)));
const describeWant = (want: string) => want.split("|").map((a) => (a.endsWith("*") ? `${a.slice(0, -1)}...` : a)).join(" or ");

// ---------------------------------------------------------------------------------------------------------------
// Comparing states

function urlKey(u: string): string {
  const url = new URL(u, "http://x");
  const path = url.pathname.split("/").map(safeDecode).join("/");
  const q = [...url.searchParams].map(([k, v]) => `${k}=${v}`).sort();
  return q.length ? `${path}?${q.join("&")}` : path;
}
const sameUrl = (a: string, b: string) => urlKey(a) === urlKey(b);
const samePath = (a: string, b: string) => new URL(a, "http://x").pathname === new URL(b, "http://x").pathname;
const sameList = (a: string[], b: string[]) => a.length === b.length && a.every((x, i) => x === b[i]);
const sameState = (a: PageState, b: PageState) => sameUrl(a.path, b.path) && sameList(a.ids, b.ids) && sameList(a.expanded, b.expanded);

function stateDiff(before: PageState, after: PageState): string[] {
  const out: string[] = [];
  if (!sameUrl(before.path, after.path)) out.push(`the URL became ${after.path}`);
  const gone = before.ids.filter((i) => !after.ids.includes(i));
  const added = after.ids.filter((i) => !before.ids.includes(i));
  if (gone.length) out.push(`gone: ${clipList(gone)}`);
  if (added.length) out.push(`new: ${clipList(added)}`);
  if (!sameList(before.expanded, after.expanded)) out.push(`open controls ${JSON.stringify(before.expanded)} became ${JSON.stringify(after.expanded)}`);
  return out;
}

function clipList(items: string[], max = 6): string {
  return items.length > max ? `${items.slice(0, max).join(", ")} and ${items.length - max} more` : items.join(", ");
}

function clip(s: string, max: number): string {
  return s.length > max ? `${s.slice(0, max - 1)}…` : s;
}

/** The findings that every page state gets (DESIGN.md 8.3 and 5.5 item 1); the recorder is quietFindings' part. */
function stateFindings(s: PageState, vp: Viewport, failures: Finding[], prefix = "") {
  if (s.stubs.length) failures.push({ code: "stub", text: `${prefix}${s.stubs.length} data-stub element${s.stubs.length > 1 ? "s" : ""}: ${clipList(s.stubs)}` });
  if (s.scrollWidth > s.clientWidth) failures.push({ code: "overflow", text: `${prefix}the page scrolls sideways (scrollWidth ${s.scrollWidth} > clientWidth ${s.clientWidth})` });
  if (s.offenders.length) failures.push({ code: "edge", text: `${prefix}past the right edge: ${s.offenders.join(", ")}` });
  if (s.size !== vp.name) failures.push({ code: "size", text: `${prefix}the app chose the size class "${s.size}" for ${vp.width}x${vp.height}` });
  if (s.touch !== vp.touch) failures.push({ code: "size", text: `${prefix}the body ${s.touch ? "has" : "lacks"} the touch class` });
}

function issueFindings(issues: { kind: string; text: string }[], failures: Finding[], prefix = "") {
  const seen = new Set<string>();
  for (const i of issues) {
    const key = `${i.kind} ${i.text}`;
    if (seen.has(key)) continue;
    seen.add(key);
    failures.push({ code: i.kind === "request" ? "request" : "error", text: `${prefix}${clip(i.text, 300)}` });
  }
}

function finish(r: Omit<CheckResult, "status">): CheckResult {
  const status: Status = r.failures.length ? "fail" : r.warnings.length ? "warn" : "pass";
  return { ...r, status };
}

// ---------------------------------------------------------------------------------------------------------------
// The wire: what the page sent and got, from the browser's own network events (DESIGN 8.4's recorder, read on the
// browser side because the real server records nothing for tests), and the page's own record, window.__kitespanFrames.

/**
 * The client frames that change nothing on the server (5.5 item 4); every other frame is mutating. on_screen (row 116)
 * is a view report, not an action: the page sends it with no click whenever a chat shows its end (web/net/frames.ts
 * READ_ONLY_FRAMES has it too).
 */
const READ_ONLY = new Set(["hello", "ping", "attach", "detach", "get", "on_screen"]);
const MUTATING_METHODS = new Set(["POST", "PUT", "PATCH", "DELETE"]);

interface WireFrame {
  n: number;
  t: string;
  rid: string | null;
  frame: Record<string, any>;
}
interface WireAck {
  n: number;
  rid: string;
  ok: boolean;
  code: string | null;
  /** An ok ack's `result`, else null. */
  result: unknown;
}
interface WireHttp {
  n: number;
  method: string;
  path: string;
  status: number | null;
}

class Wire {
  readonly frames: WireFrame[] = [];
  readonly acks: WireAck[] = [];
  readonly http: WireHttp[] = [];
  /** Frames to /ws/shell (keys and control frames of the Terminal pane): counted, not judged here. */
  shellFrames = 0;
  private n = 0;
  private readonly sockets = new Map<string, string>();
  private readonly requests = new Map<string, WireHttp>();
  private readonly off: () => void;

  constructor(cdp: Cdp, page: Page) {
    this.off = cdp.on((e) => {
      if (e.sessionId !== page.session) return;
      const p = e.params ?? {};
      switch (e.method) {
        case "Network.webSocketCreated":
          try {
            this.sockets.set(p.requestId, new URL(p.url).pathname);
          } catch {}
          break;
        case "Network.webSocketFrameSent": {
          const path = this.sockets.get(p.requestId);
          if (path === WIRE.shellPath) this.shellFrames++;
          if (path !== WIRE.path || p.response?.opcode !== 1) break;
          try {
            const f = JSON.parse(p.response.payloadData) as Record<string, any>;
            this.frames.push({ n: ++this.n, t: String(f.t), rid: typeof f.rid === "string" ? f.rid : null, frame: f });
          } catch {
            this.frames.push({ n: ++this.n, t: "(not JSON)", rid: null, frame: {} });
          }
          break;
        }
        case "Network.webSocketFrameReceived": {
          if (this.sockets.get(p.requestId) !== WIRE.path || p.response?.opcode !== 1) break;
          try {
            const f = JSON.parse(p.response.payloadData) as Record<string, any>;
            if (f.t === "ack" && typeof f.rid === "string") this.acks.push({ n: ++this.n, rid: f.rid, ok: f.ok === true, code: f.error?.code ?? null, result: f.ok === true ? (f.result ?? null) : null });
          } catch {}
          break;
        }
        case "Network.requestWillBeSent": {
          const method = String(p.request?.method ?? "GET").toUpperCase();
          let path = "";
          try {
            path = new URL(p.request?.url ?? "").pathname;
          } catch {}
          if (!path.startsWith("/api/") || !MUTATING_METHODS.has(method)) break;
          const rec: WireHttp = { n: ++this.n, method, path, status: null };
          this.http.push(rec);
          this.requests.set(p.requestId, rec);
          break;
        }
        case "Network.responseReceived": {
          const rec = this.requests.get(p.requestId);
          if (rec) rec.status = p.response?.status ?? null;
          break;
        }
      }
    });
  }

  /** A mark: what comes after it is newer. */
  mark(): number {
    return this.n;
  }
  framesSince(m: number): WireFrame[] {
    return this.frames.filter((f) => f.n > m);
  }
  httpSince(m: number): WireHttp[] {
    return this.http.filter((h) => h.n > m);
  }
  dispose(): void {
    this.off();
  }
}

const mutating = (frames: WireFrame[]) => frames.filter((f) => !READ_ONLY.has(f.t));
/** The request frames that act (a `rid`, not a `get`); a `draft` frame has no `rid` and is judged on its own. */
const acting = (frames: WireFrame[]) => frames.filter((f) => f.rid !== null && f.t !== "get");
const frameText = (f: WireFrame) => f.t;
const httpText = (h: WireHttp) => `${h.method} ${h.path}${h.status ? ` (${h.status})` : ""}`;

/** window.__kitespanFrames as a list of names; null when the page has recorded nothing yet (it makes the list then). */
async function recorder(page: Page): Promise<string[] | null> {
  return page
    .evaluate<string[] | null>(`(() => { const r = window.__kitespanFrames; return Array.isArray(r) ? r.map((f) => (f && typeof f === "object" ? String(f.t) : String(f))) : null; })()`)
    .catch(() => null);
}

/** D 8.4: nothing mutating went out and the page recorded nothing. */
function quietFindings(wire: Wire, since: number, rec: string[] | null, failures: Finding[], prefix = "") {
  const m = mutating(wire.framesSince(since));
  if (m.length) failures.push({ code: "frames", text: `${prefix}the page sent ${m.length} mutating frame${m.length > 1 ? "s" : ""} with no click: ${clipList(m.map(frameText))}` });
  const h = wire.httpSince(since);
  if (h.length) failures.push({ code: "frames", text: `${prefix}the page sent ${clipList(h.map(httpText))} with no click` });
  if (rec?.length) failures.push({ code: "recorder", text: `${prefix}window.__kitespanFrames holds ${clipList(rec)} with no click` });
}

/**
 * On touch sizes: shown, enabled controls on screen whose hit area is under 44 x 44 px (a warning). The hit area is
 * the box, grown by an absolute ::before or ::after that the control places with negative insets (base.css gives a
 * 32 px chip or segment a 44 px hit area this way: inset -6px 0).
 */
const SMALL_TARGETS = `(() => {
  const shown = (el) => { if (!el.getClientRects().length || el.closest('[hidden="until-found"]')) return false; const cs = getComputedStyle(el); return cs.visibility !== "hidden" && cs.visibility !== "collapse" && cs.pointerEvents !== "none"; };
  const grow = (v) => { const n = parseFloat(v); return Number.isFinite(n) && n < 0 ? -n : 0; };
  const hit = (el, r) => {
    let w = r.width, h = r.height;
    if (getComputedStyle(el).position === "static") return { w, h };
    for (const which of ["::before", "::after"]) {
      const p = getComputedStyle(el, which);
      if (p.content === "none" || p.content === "normal" || p.position !== "absolute" || p.pointerEvents === "none") continue;
      w = Math.max(w, r.width + grow(p.left) + grow(p.right));
      h = Math.max(h, r.height + grow(p.top) + grow(p.bottom));
    }
    return { w, h };
  };
  // DESIGN-T1 3.2 \`target\`: text areas and links too. A link inside running text (an inline box among words) is
  // the text's own, as WCAG's inline exception has it; a text area whose row takes a tap 5 px above and below it (the
  // composer's field in its slab) has the row's height.
  const sel = 'button, [role="button"], [role="menuitem"], [role="option"], [role="tab"], [role="switch"], [role="checkbox"], [role="radio"], input:not([type="hidden"]), select, summary, textarea, a[href]';
  const inline = (el) => el.tagName === "A" && getComputedStyle(el).display === "inline" && [...el.parentElement.childNodes].some((n) => n !== el && n.nodeType === 3 && n.textContent.trim());
  const rowTakes = (el, r) => { const mid = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2); if (mid !== el && !el.contains(mid)) return true; return [r.top - 5, r.bottom + 5].every((y) => { const at = document.elementFromPoint(r.left + r.width / 2, y); const row = el.parentElement && el.parentElement.closest(".cmp-slab, .sc-box, .field-row, label"); return !!at && (at === el || (!!row && row.contains(at) && !at.closest("button, a[href], input, textarea, select"))); }); };
  const out = [];
  for (const el of document.querySelectorAll(sel)) {
    if (!shown(el) || el.disabled || el.closest('[aria-hidden="true"], [inert]')) continue;
    const r = el.getBoundingClientRect();
    if (!r.width || !r.height || r.bottom <= 0 || r.top >= innerHeight || r.right <= 0 || r.left >= innerWidth) continue;
    // xterm's helper field sits at the cursor under the terminal, which takes the taps (TerminalPane).
    if (inline(el) || el.classList.contains("xterm-helper-textarea")) continue;
    const area = hit(el, r);
    if (area.w >= 44 && area.h >= 44) continue;
    if (el.tagName === "TEXTAREA" && area.w >= 44 && rowTakes(el, r)) continue;
    const id = el.getAttribute("data-testid");
    const label = (el.getAttribute("aria-label") || el.textContent || "").trim().replace(/\\s+/g, " ").slice(0, 24);
    out.push((id ? id : el.tagName.toLowerCase() + (label ? ' "' + label + '"' : "")) + " " + Math.round(r.width) + "x" + Math.round(r.height));
  }
  return out;
})()`;

/**
 * FIX-Q1: each answer row that shows (a card's, a dialog's) with two buttons or more: its buttons in the DOM's order
 * and in the order they show (top to bottom, then left to right on one line), when the two differ.
 */
const ACTION_ORDER = `(() => {
  const vis = (el) => el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden";
  const name = (el) => { const t = el.matches("[data-testid]") ? el : el.querySelector("[data-testid]"); return t ? t.getAttribute("data-testid") : (el.textContent || "").trim().replace(/\\s+/g, " ").slice(0, 24); };
  const out = [];
  for (const row of document.querySelectorAll(".chat-card-actions, .dialog-actions")) {
    if (!vis(row)) continue;
    const kids = [...row.children].filter(vis).map((el) => ({ el, r: el.getBoundingClientRect() }));
    if (kids.length < 2) continue;
    const line = (a, b) => Math.abs(a.r.top - b.r.top) < Math.min(a.r.height, b.r.height) / 2;
    const shown = [...kids].sort((a, b) => (line(a, b) ? a.r.left - b.r.left : a.r.top - b.r.top));
    const dom = kids.map((k) => name(k.el));
    const seen = shown.map((k) => name(k.el));
    if (dom.join("\\n") !== seen.join("\\n")) out.push({ row: row.className, dom, shown: seen });
  }
  return out;
})()`;

// ---------------------------------------------------------------------------------------------------------------
// The checks

let cdp: Cdp;
const shotsDir = join(OUT, "shots");

async function withPage<T>(vp: Viewport, theme: Theme, run: (page: Page, wire: Wire) => Promise<T>): Promise<T> {
  const page = await Page.open(cdp, vp, theme);
  const wire = new Wire(cdp, page);
  try {
    return await run(page, wire);
  } finally {
    wire.dispose();
    await page.close();
  }
}

/** Wait until every wanted test id shows (the screen may draw only after the server's first answer, 5.1 rule 5). */
async function waitShown(page: Page, want: string[], ms = 4000): Promise<PageState> {
  const end = Date.now() + ms;
  let s = await page.probe();
  while (Date.now() < end && !want.every((w) => shownMatch(w, s.ids))) {
    await sleep(100);
    s = await page.probe();
  }
  await page.settle();
  return page.probe();
}

const shotName = (scene: SeedSceneName | null, id: string, vp: Viewport, theme: Theme, step = "") => {
  const dir = join(shotsDir, scene ?? "base");
  mkdirSync(dir, { recursive: true });
  return join(dir, `${id}${step ? `-${step}` : ""}--${sizeTag(vp)}-${theme}.jpg`);
};

/**
 * DESIGN-T1 3.2's passes: every route check once more at Settings text size 1.3 (390, m626 and large) and in each other
 * look (m626 and large), both themes, with every measure. A device setting, set before the page's scripts run.
 */
interface RoutePass {
  id: "t13" | "paper" | "mono" | "editor";
  key: "textSize" | "look";
  value: number | string;
}
const TEXT_PASS: RoutePass = { id: "t13", key: "textSize", value: 1.3 };
const LOOK_PASSES: RoutePass[] = (["paper", "mono", "editor"] as const).map((l) => ({ id: l, key: "look", value: l }));
const TEXT_PASS_SIZES: readonly SizeLabel[] = ["phone", "m626", "large"];
const LOOK_PASS_SIZES: readonly SizeLabel[] = ["m626", "large"];

/** The findings of DESIGN-T1 3.2's touch measures (one read of the page), into failures. */
function touchFindings(m: TouchMeasures, failures: Finding[], prefix = "") {
  const add = (code: string, list: string[], what: string) => {
    if (list.length) failures.push({ code, text: `${prefix}${what}: ${clipList(list, 4)}` });
  };
  add("control-out", m.controlBox, `${m.controlBox.length} control${m.controlBox.length > 1 ? "s" : ""} out of the box ${m.controlBox.length > 1 ? "they sit" : "it sits"} in`);
  add("control-out", m.controlPoint, `${m.controlPoint.length} control${m.controlPoint.length > 1 ? "s" : ""} covered where a tap lands`);
  add("blur-touch", m.blur, "a bar, drawer, sheet or menu is not opaque on touch");
  add("name-cut", m.nameCut, "a name is cut");
  add("named-touch", m.named, "a bar's tool lacks its name on touch");
  add("opener-touch", m.opener, `${m.opener.length} long-press target${m.opener.length > 1 ? "s have" : " has"} no visible "..." on touch`);
  add("name-break", m.nameBreak, "a name breaks inside a word");
}

/**
 * DESIGN-T1 3.2 `safe-area`: with the phone's safe areas (390x844: top 47 and bottom 34; a phone on its side: its own,
 * left and right 47 and bottom 21), each bottom padding that follows the inset is max(base, inset), never their sum;
 * on its side, the bars' and sheets' controls clear the side insets.
 */
async function safeAreaFindings(page: Page, vp: Viewport, failures: Finding[], details: Record<string, unknown>, prefix = "") {
  const own: Insets | null = vp.insets ?? null;
  const ins: Insets = own ?? { top: 47, right: 0, bottom: 34, left: 0 };
  try {
    if (!own) {
      await page.insets(ins);
      await sleep(150);
    }
    const on = await page.evaluate<{ n: number; pads: number[]; names: string[] }>(`${SAFE_AREA_READ}(true)`);
    const sides = own ? await page.evaluate<string[]>(`${SAFE_AREA_SIDES}(${ins.left}, ${ins.right})`) : [];
    await page.insets(null);
    await sleep(150);
    const off = await page.evaluate<{ n: number; pads: number[] }>(`${SAFE_AREA_READ}(false)`);
    const bad: string[] = [];
    let follows = 0;
    on.pads.forEach((p1, i) => {
      const p0 = off.pads[i] ?? p1;
      if (Math.abs(p1 - p0) < 0.5) return;
      follows++;
      const want = Math.max(p0, ins.bottom);
      if (Math.abs(p1 - want) > 1) bad.push(`${on.names[i]} ${Math.round(p1)} px (base ${Math.round(p0)}, inset ${ins.bottom})`);
    });
    details.safeArea = { elements: on.n, follow: follows, bad, sides };
    if (bad.length) failures.push({ code: "safe-area", text: `${prefix}a bottom padding adds the inset to its base instead of max(): ${clipList(bad, 4)}` });
    if (sides.length) failures.push({ code: "safe-area", text: `${prefix}a control of a bar or a sheet lies under the side insets (${ins.left} and ${ins.right} px): ${clipList(sides, 4)}` });
  } finally {
    await page.insets(own).catch(() => {});
    await page.evaluate("delete window.__fdSafe").catch(() => {});
    await sleep(100);
  }
}

/** DESIGN.md 5.5 items 1, 2 and 4 (before the click): open the route directly, then reload. */
async function routeCheck(c: RouteCase, base: string, vp: Viewport, theme: Theme, pass?: RoutePass): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  let shot: string | undefined;
  try {
    await withPage(vp, theme, async (page, wire) => {
      if (pass) await page.send("Page.addScriptToEvaluateOnNewDocument", { source: DEVICE_SETTING(pass.key, pass.value) });
      await page.navigate(base + c.path);
      if (!page.lastSettle.settled) warnings.push({ code: "settle", text: `the page did not settle in ${page.lastSettle.ms} ms` });
      const s1 = await waitShown(page, c.ids);
      details.opened = s1;
      issueFindings(page.takeIssues(), failures);
      if (!sameUrl(s1.path, c.path) && !(c.fallback && samePath(s1.path, c.fallback))) failures.push({ code: "url", text: `the URL changed to ${s1.path}` });
      if (c.notice) {
        if (!s1.notices.some((n) => n.includes(c.notice!))) failures.push({ code: "notice", text: `the 5.4 line "${c.notice}" does not show${s1.notices.length ? ` (it shows: ${clipList(s1.notices)})` : ""}` });
        // Principle 0: one notice line at most.
        else if (s1.notices.length > 1) failures.push({ code: "notice", text: `${s1.notices.length} 5.4 lines show, not one: ${clipList(s1.notices)}` });
      } else if (s1.notices.length) failures.push({ code: "notice", text: `a 5.4 line shows: ${clipList(s1.notices)}` });
      const missing = c.ids.filter((w) => !shownMatch(w, s1.ids));
      if (missing.length) failures.push({ code: "shows", text: `not shown: ${missing.map(describeWant).join(", ")}` });
      if (!s1.ids.length) failures.push({ code: "shows", text: "no element with a data-testid shows" });
      stateFindings(s1, vp, failures);
      for (const o of await page.evaluate<{ row: string; dom: string[]; shown: string[] }[]>(ACTION_ORDER))
        failures.push({ code: "order", text: `the buttons of .${o.row.split(" ")[0]} are ${o.dom.join(", ")} in the DOM but show as ${o.shown.join(", ")}: Tab and a screen reader meet them in another order than the eye` });
      const sel = c.id === c.route.name ? SELECTORS[c.id] : undefined;
      for (const [css, why] of sel?.present ?? []) if (!(await page.evaluate<boolean>(SHOWN_ANY(css)))) failures.push({ code: "shows", text: why });
      for (const [css, why] of sel?.absent ?? []) if (await page.evaluate<boolean>(SHOWN_ANY(css))) failures.push({ code: "shows", text: why });
      quietFindings(wire, 0, await recorder(page), failures);
      if (vp.touch) {
        const small = await page.evaluate<string[]>(SMALL_TARGETS).catch(() => [] as string[]);
        details.smallTargets = small;
        if (small.length) warnings.push({ code: "target", text: `${small.length} control${small.length > 1 ? "s" : ""} under 44 px: ${clipList(small, 4)}` });
        const m = await page.evaluate<TouchMeasures>(TOUCH_MEASURES);
        details.touch = m;
        touchFindings(m, failures);
        if (vp.name === "phone") await safeAreaFindings(page, vp, failures, details);
      }
      shot = shotName(c.scene, c.id, vp, theme, pass?.id);
      // The reload below draws the page again, so the masked name never reaches the checks after it.
      await maskMachine(page);
      await page.screenshot(shot);

      const before = wire.mark();
      await page.reload();
      const s2 = await waitShown(page, c.ids);
      details.reloaded = s2;
      issueFindings(page.takeIssues(), failures, "after reload, ");
      const diff = stateDiff(s1, s2);
      if (diff.length) failures.push({ code: "reload", text: `after reload, ${diff.join("; ")}` });
      quietFindings(wire, before, await recorder(page), failures, "after reload, ");
      details.wire = { frames: wire.frames.map(frameText), http: wire.http.map(httpText), shellFrames: wire.shellFrames };
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const shown = (details.opened as PageState | undefined)?.ids.length ?? 0;
  return finish({ kind: "route", name: c.id, route: c.route.name, scene: c.scene, size: pass ? `${sizeTag(vp)}@${pass.id}` : sizeTag(vp), theme, path: c.path, failures, warnings, note: `${shown} test ids shown; nothing sent`, shot, ms: Date.now() - t0, details });
}

/** 5.4, the last row: a path outside every app route family gets the server's 404 page, never the app shell. */
async function notFoundCheck(base: string, scene: SceneName | null): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const path = `/chat/${EX.chat}`;
  try {
    const res = await fetch(base + path, { redirect: "manual", signal: AbortSignal.timeout(5000) });
    const body = await res.text();
    if (res.status !== 404) failures.push({ code: "url", text: `${path} answered HTTP ${res.status}, not 404` });
    if (!body.includes("There is no kitespan page at this address.")) failures.push({ code: "shows", text: `${path} does not say "There is no kitespan page at this address."` });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return finish({ kind: "route", name: "outside-family", route: "home", scene, size: "laptop", theme: "dark", path, failures, warnings: [], note: "the server's 404 page, not the app", ms: Date.now() - t0, details: {} });
}

// The history check walks the example chat: its composer's Model button (a waiting card takes the composer's place,
// 5.3) and a row that opens a block route. A step that the chat does not offer moves by script, with a warning.
const MODEL_BUTTON = '[data-testid="composer"] button[aria-label^="Model"]';
const BLOCK_TOGGLE = '[data-testid^="item-"] [aria-expanded="false"]';
const SUMMARY_TOGGLE = '[data-testid^="summary-"] [aria-expanded="false"]';
// U2: a finished turn is drawn folded, so its work (and the rows that push a block route) shows only once its line
// is open. The line opens in place, like a summary row.
const TURN_TOGGLE = '[data-testid^="turn-"] > .chat-row-line > button[aria-expanded="false"]';

const isBlockOf = (chat: string, p: string) => new RegExp(`^/c/${escapeRe(chat)}/(tool|agent|workflow|thinking)/[^/?]+$`).test(new URL(p, "http://x").pathname);

/**
 * Press closed rows until one pushes a block route. Rows that open in place (and summary rows that fold blocks) are
 * part of the chat's state; onLocal hears about each one. Returns the press that reached a block, or another URL.
 */
async function openBlock(page: Page, chat: string, onLocal: (how: string, s: PageState) => void): Promise<{ how: string; state: PageState } | null> {
  for (let tries = 0; tries < 8; tries++) {
    for (const sel of [BLOCK_TOGGLE, SUMMARY_TOGGLE, TURN_TOGGLE]) {
      const at = await page.locate(sel);
      if (!at) continue;
      await page.press(at.x, at.y);
      await sleep(60);
      await page.settle();
      const state = await page.probe();
      const how = `${page.vp.touch ? "tap" : "click"} ${at.label}`;
      if (!sameUrl(state.path, `/c/${chat}`)) return { how, state };
      onLocal(how, state);
      break;
    }
    if (!(await page.locate(`${BLOCK_TOGGLE}, ${SUMMARY_TOGGLE}, ${TURN_TOGGLE}`))) return null;
  }
  return null;
}

/** DESIGN.md 5.5 item 3: Home, a chat, a block, a picker, close the picker; then Back to Home and Forward to the end. */
async function historyCheck(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const steps: { label: string; how: string; path: string }[] = [];
  const details: Record<string, unknown> = { steps };
  const describeState = (s: PageState) => `${s.path}${s.ids.includes("picker-model") ? " (picker open)" : ""}`;
  const chat = EX.chat;
  const chatPath = `/c/${chat}`;
  const pickerPath = `${chatPath}/model`;

  try {
    await withPage(vp, "dark", async (page, wire) => {
      /** Press the first shown match of the selector; null when none shows. */
      const pressOn = async (sel: string) => {
        const at = await page.locate(sel);
        if (!at) return null;
        await page.press(at.x, at.y);
        await sleep(60);
        await page.settle();
        return { how: `${vp.touch ? "tap" : "click"} ${at.label}`, covered: at.covered, state: await page.probe() };
      };
      /** No control: move the way the router does (pushState, then popstate), so the rest of the check still runs. */
      const byScript = async (what: string, target: string) => {
        await page.evaluate(`(() => { history.pushState({ from: location.pathname + location.search }, "", ${JSON.stringify(target)}); dispatchEvent(new PopStateEvent("popstate", { state: history.state })); return true; })()`);
        await page.settle();
        warnings.push({ code: "history", text: `${what}: no link or button found, so the check moved by script` });
        return { how: "script", covered: null, state: await page.probe() };
      };

      // Home
      await page.navigate(base + "/");
      const A = await waitShown(page, ["home"]);
      steps.push({ label: "Home", how: "open", path: A.path });

      // A chat: its link on Home (the Recent list or the sidebar).
      const toChat = (await pressOn(`a[href="${chatPath}"]`)) ?? (await byScript("a chat", chatPath));
      steps.push({ label: "a chat", how: toChat.how, path: toChat.state.path });
      if (!sameUrl(toChat.state.path, chatPath)) failures.push({ code: "history", text: `a chat: ${toChat.how} went to ${toChat.state.path}, not ${chatPath}` });
      let B = await waitShown(page, ["chat"]);

      // A block: a closed row that pushes its route; summary rows that fold blocks open in place first (no URL).
      let C: PageState;
      const block = await openBlock(page, chat, (how, st) => {
        B = st; // a row that opens in place belongs to the chat's state, not to a history entry
        steps.push({ label: "open in place", how, path: st.path });
      });
      if (block && isBlockOf(chat, block.state.path)) {
        C = block.state;
        steps.push({ label: "a block", how: block.how, path: C.path });
      } else if (block) {
        C = block.state;
        steps.push({ label: "a block", how: block.how, path: C.path });
        failures.push({ code: "history", text: `a block: ${block.how} went to ${C.path}, not a block of ${chatPath}` });
      } else {
        C = (await byScript("a block", `${chatPath}/tool/${EX.toolUse}`)).state;
        steps.push({ label: "a block", how: "script", path: C.path });
      }

      // A picker: the composer's Model button.
      const toPicker = (await pressOn(MODEL_BUTTON)) ?? (await byScript("a picker", pickerPath));
      const D = toPicker.state;
      steps.push({ label: "a picker", how: toPicker.how, path: D.path });
      if (!sameUrl(D.path, pickerPath)) failures.push({ code: "history", text: `a picker: ${toPicker.how} went to ${D.path}, not ${pickerPath}` });
      if (!D.ids.includes("picker-model")) failures.push({ code: "history", text: "a picker: picker-model does not show" });

      // Close the picker.
      await page.key("Escape");
      await sleep(60);
      await page.settle();
      const E = await page.probe();
      steps.push({ label: "close the picker", how: "Escape", path: E.path });
      if (E.ids.includes("picker-model")) failures.push({ code: "history", text: "close the picker: Escape left picker-model open" });
      issueFindings(page.takeIssues(), failures);

      const hist = await page.history();
      const entries = hist.entries;
      details.entries = entries.map((e) => e.url.replace(base, ""));
      details.currentIndex = hist.currentIndex;
      const home = entries.findIndex((e) => e.url.startsWith(base) && sameUrl(e.url.slice(base.length) || "/", "/"));
      if (home < 0) {
        failures.push({ code: "history", text: `Home is not in the history any more: ${entries.map((e) => e.url.replace(base, "")).join(" , ")}` });
        return;
      }
      // Back, one entry at a time, to Home; then Forward, one entry at a time, to the last entry.
      const back = new Map<number, PageState>([[hist.currentIndex, E]]);
      for (let i = hist.currentIndex - 1; i >= home; i--) {
        await page.goToEntry(entries[i]!.id);
        back.set(i, await page.probe());
      }
      const fwd = new Map<number, PageState>([[home, back.get(home)!]]);
      for (let i = home + 1; i < entries.length; i++) {
        await page.goToEntry(entries[i]!.id);
        fwd.set(i, await page.probe());
      }
      issueFindings(page.takeIssues(), failures, "during Back and Forward, ");
      // Moving through history is not a click on an action: nothing mutating goes out (a link never acts by itself).
      quietFindings(wire, 0, await recorder(page), failures);

      // Back must restore each earlier state in turn; a closed picker that went back may stay as a Forward entry.
      const expected = sameState(E, C) ? [A, B, C] : [A, B, C, E];
      const actual = [...Array(hist.currentIndex - home + 1).keys()].map((k) => back.get(home + k)!);
      details.back = actual.map(describeState);
      if (actual.length !== expected.length || actual.some((st, k) => !sameState(st, expected[k]!))) {
        const why = actual.length === expected.length ? actual.map((st, k) => (sameState(st, expected[k]!) ? "" : `${describeState(st)}: ${stateDiff(expected[k]!, st).join("; ")}`)).filter(Boolean).join(" | ") : "";
        failures.push({ code: "history", text: `Back showed ${actual.map(describeState).reverse().join(" < ")}; expected ${expected.map(describeState).reverse().join(" < ")}${why ? ` (${why})` : ""}` });
      }
      for (let i = home; i < entries.length; i++) {
        const f = fwd.get(i)!;
        const b = back.get(i);
        if (b && !sameState(f, b)) failures.push({ code: "history", text: `Forward to entry ${i - home} showed ${describeState(f)}, Back showed ${describeState(b)}: ${stateDiff(b, f).join("; ")}` });
        if (i > hist.currentIndex && !f.ids.includes("picker-model")) failures.push({ code: "history", text: `a Forward entry after the closed picker shows ${describeState(f)}` });
        const prev = fwd.get(i - 1);
        if (prev && sameState(prev, f)) failures.push({ code: "history", text: `a dead history entry: entries ${i - 1 - home} and ${i - home} both show ${describeState(f)}` });
      }
      details.forward = [...fwd.values()].map(describeState);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const back = (details.back as string[] | undefined)?.length ?? 0;
  const fwd = (details.forward as string[] | undefined)?.length ?? 0;
  const route = steps.filter((st) => !st.label.startsWith("open")).map((st) => st.path).join(" > ");
  return finish({
    kind: "history", name: "history", route: "chat", scene, size: sizeTag(vp), theme: "dark", path: route || chatPath,
    failures, warnings, note: `Back over ${Math.max(0, back - 1)} entries and Forward over ${Math.max(0, fwd - 1)} restored each state`, ms: Date.now() - t0, details,
  });
}

/**
 * DESIGN.md 5.1 rule 4 after a reload: the chat list (Home on a laptop), a chat, its Model picker, a reload, then
 * Escape. The entries the page pushed before the reload share the reloaded entry's document, so Escape goes back to
 * the chat's entry in the same page (a mark set after the reload is still there) instead of replacing the picker's,
 * and Back from the chat shows the list: no dead entry. Nothing mutating goes out.
 */
async function historyReloadCheck(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const start = vp.name === "phone" ? "/chats" : "/";
  const chatPath = `/c/${EX.chat}`;
  const pickerPath = `${chatPath}/model`;
  try {
    await withPage(vp, "dark", async (page, wire) => {
      const pressOn = async (sel: string) => {
        const at = await page.locate(sel);
        if (!at) return false;
        await page.press(at.x, at.y);
        await sleep(60);
        await page.settle();
        return true;
      };
      await page.navigate(base + start);
      await waitShown(page, [vp.name === "phone" ? "chat-list" : "home"]);
      if (!(await pressOn(`a[href="${chatPath}"]`))) {
        failures.push({ code: "history", text: `no link to ${chatPath} on ${start}` });
        return;
      }
      await waitShown(page, ["chat", "composer"]);
      if (!(await pressOn(MODEL_BUTTON))) {
        failures.push({ code: "history", text: "no Model button in the composer" });
        return;
      }
      const open = await waitShown(page, ["picker-model"]);
      if (!sameUrl(open.path, pickerPath)) failures.push({ code: "history", text: `the Model button went to ${open.path}, not ${pickerPath}` });
      await page.reload();
      await waitShown(page, ["chat", "picker-model"]);
      await page.evaluate(`(() => { window.__kitespanSameDocument = "reloaded"; return true; })()`);
      const before = await page.history();
      details.before = { currentIndex: before.currentIndex, entries: before.entries.map((e) => e.url.replace(base, "")) };
      await page.key("Escape");
      await sleep(60);
      await page.settle();
      const closed = await page.probe();
      const same = await page.evaluate<boolean>(`window.__kitespanSameDocument === "reloaded"`);
      const after = await page.history();
      details.after = { path: closed.path, same, currentIndex: after.currentIndex, entries: after.entries.map((e) => e.url.replace(base, "")) };
      if (!sameUrl(closed.path, chatPath)) failures.push({ code: "history", text: `Escape after the reload went to ${closed.path}, not ${chatPath}` });
      if (closed.ids.includes("picker-model")) failures.push({ code: "history", text: "Escape after the reload left picker-model open" });
      if (!same) failures.push({ code: "history", text: "Escape after the reload left the document" });
      if (after.currentIndex !== before.currentIndex - 1) failures.push({ code: "history", text: `Escape after the reload replaced the picker's entry instead of going back to the chat's (entry ${before.currentIndex} to ${after.currentIndex})` });
      const prev = after.entries[after.currentIndex - 1];
      if (!prev) failures.push({ code: "history", text: "no entry before the chat's" });
      else {
        await page.goToEntry(prev.id);
        const back = await page.probe();
        details.back = back.path;
        if (!sameUrl(back.path, start)) failures.push({ code: "history", text: `Back from the chat showed ${back.path}, not ${start}${sameUrl(back.path, chatPath) ? " (a dead entry)" : ""}` });
      }
      issueFindings(page.takeIssues(), failures);
      quietFindings(wire, 0, await recorder(page), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return finish({
    kind: "history", name: "history-reload", route: "chat", scene, size: sizeTag(vp), theme: "dark", path: `${start} > ${chatPath} > ${pickerPath} > reload > Escape`,
    failures, warnings, note: "after a reload, Escape goes back to the chat in the same document, and Back shows the list", ms: Date.now() - t0, details,
  });
}

type Confirm = Awaited<ReturnType<Page["findConfirm"]>>;

/**
 * The button to press: the first named confirm button that shows and is on; for a check that names none, what the
 * confirm finder picks. A named check never presses another button (that could act on something else); `shown` lists
 * the confirm buttons that do show, for the report.
 */
async function findButton(page: Page, spec: ActionSpec): Promise<{ c: Confirm; off: string[]; shown: string[] }> {
  const off: string[] = [];
  for (const id of spec.button ?? []) {
    const c = await page.findConfirm(id);
    if (c.found) return { c, off, shown: c.candidates };
    off.push(...c.disabled);
  }
  // v0.6 touch (DESIGN-T1 2.7): under 23em of pane an upload's three buttons fold into its "...", whose menu holds
  // Remove; opening the menu sends nothing, so the press is the menu's row.
  if (spec.button?.includes("confirm-remove-upload")) {
    const more = await page.locate('[data-testid="uploads"] .side-up [data-testid="row-more"]');
    if (more) {
      await page.press(more.x, more.y);
      await sleep(400);
      const c = await page.findConfirm("row-remove");
      if (c.found) return { c, off, shown: c.candidates };
    }
  }
  const any = await page.findConfirm();
  if (!spec.button?.length) return { c: any, off: any.disabled, shown: any.candidates };
  return { c: { found: false, candidates: any.candidates, disabled: off }, off, shown: [...any.candidates, ...any.disabled] };
}

/** Wait until the press shows on the wire (an acting frame or a mutating request), then a little longer for a second one. */
async function waitSent(wire: Wire, since: number, ms = 2500): Promise<void> {
  const end = Date.now() + ms;
  while (Date.now() < end && !acting(wire.framesSince(since)).length && !wire.httpSince(since).length) await sleep(50);
  await sleep(400);
}

async function waitAck(wire: Wire, rid: string, ms = 3000): Promise<WireAck | null> {
  const end = Date.now() + ms;
  for (;;) {
    const a = wire.acks.find((x) => x.rid === rid);
    if (a) return a;
    if (Date.now() > end) return null;
    await sleep(50);
  }
}

/**
 * v0.6 touch: from a chat or a project, the way to the list's Settings link where no sidebar shows it: the band's chats
 * button (the tablet's drawer, the phone's /chats). A laptop's sidebar holds it already.
 */
async function reachSettings(page: Page, vp: Viewport) {
  if (!vp.touch || vp.name === "laptop") return;
  const sel = ".scr-bar-chats";
  for (let i = 0; i < 3; i++) {
    // A page under the band's own (a session's preview) goes Back first.
    const at = (await page.locate(sel)) ?? (await page.locate('[data-testid="topbar"] .scr-bar-back'));
    if (!at) return;
    await page.press(at.x, at.y);
    const end = Date.now() + 2500;
    while (Date.now() < end && !(await page.locate('a[href="/settings"]'))) await sleep(150);
    await page.settle();
    if (await page.locate('a[href="/settings"]')) return;
  }
}

/** The Copy variant of DESIGN.md 5.5 item 4: a press on Copy sends nothing, and the clipboard then holds the command. */
async function copyCheck(page: Page, wire: Wire, base: string, spec: ActionSpec, re: RegExp, failures: Finding[], warnings: Finding[], details: Record<string, unknown>): Promise<string> {
  await cdp.send("Browser.grantPermissions", { permissions: ["clipboardReadWrite", "clipboardSanitizedWrite"], origin: base, browserContextId: page.contextId }).catch(() => {});
  const { c } = await findButton(page, spec);
  details.confirm = c;
  if (!c.found || !c.id!.startsWith("confirm-copy")) {
    failures.push({ code: "confirm", text: c.found ? `the button to press is ${c.id}, not a Copy button` : "no Copy button shows" });
    return "no Copy button to press";
  }
  const since = wire.mark();
  const n0 = (await recorder(page))?.length ?? 0;
  await page.press(c.x!, c.y!);
  await sleep(300);
  await page.settle();
  const sent = mutating(wire.framesSince(since));
  const http = wire.httpSince(since);
  const rec = ((await recorder(page)) ?? []).slice(n0);
  if (sent.length || http.length) failures.push({ code: "click", text: `Copy (${c.id}) sent ${clipList([...sent.map(frameText), ...http.map(httpText)])}` });
  if (rec.length) failures.push({ code: "recorder", text: `Copy (${c.id}) recorded ${clipList(rec)} in window.__kitespanFrames` });
  const text = await page.evaluate<string | null>(`navigator.clipboard.readText().catch(() => null)`).catch(() => null);
  details.clipboard = text;
  if (text === null) {
    warnings.push({ code: "copy", text: "the clipboard could not be read back" });
    return `${c.id} sent nothing; the clipboard could not be read`;
  }
  if (!re.test(text)) failures.push({ code: "copy", text: `the clipboard holds "${clip(text.replace(/\s+/g, " "), 100)}", not the chat's command (${re.source})` });
  return `${c.id} sent nothing and copied "${clip(text.replace(/\s+/g, " "), 80)}"`;
}

/** DESIGN.md 5.5 item 4 and 8.4: nothing goes out before the press, and exactly the route's request after it. */
async function actionCheck(spec: ActionSpec, base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const path = spec.path ?? ROUTE[spec.route]!.example;
  let note = "";
  let shot: string | undefined;
  try {
    await withPage(vp, "dark", async (page, wire) => {
      const opened = Date.now();
      await page.navigate(base + path);
      await waitShown(page, expectedIds(ROUTE[spec.route]!), Math.max(1000, ACTION_WAIT));
      const rest = ACTION_WAIT - (Date.now() - opened);
      if (rest > 0) await sleep(rest);
      const rec0 = await recorder(page);
      quietFindings(wire, 0, rec0, failures, "before the press, ");
      const n0 = rec0?.length ?? 0;

      if ("copy" in spec.expect) {
        note = await copyCheck(page, wire, base, spec, spec.expect.copy, failures, warnings, details);
        issueFindings(page.takeIssues(), failures);
        return;
      }

      // No card may wait here (no dialog kind is declared): press nothing, and check that none shows.
      if (spec.noButton) {
        const card = await page.evaluate<string | null>(`(() => { const el = [...document.querySelectorAll('section.chat-card[data-testid^="card-"]')].find((e) => e.getClientRects().length > 0); return el ? el.getAttribute("data-testid") : null; })()`);
        if (card) failures.push({ code: "confirm", text: `${card} shows, though ${spec.noButton}` });
        note = `nothing sent; nothing to press: ${spec.noButton}`;
        issueFindings(page.takeIssues(), failures);
        return;
      }
      const found = await findButton(page, spec);
      let press = found.c;
      details.confirm = press;
      if (!press.found) {
        shot = shotName(scene, spec.id, vp, "dark", "no-button");
        await maskMachine(page);
        await page.screenshot(shot).catch(() => {});
        const others = found.shown.filter((id) => !found.off.includes(id));
        const why = found.off.length
          ? `every button to press is off: ${found.off.join(", ")}`
          : `no ${spec.button?.length ? spec.button.join(" or ") : "confirm-*"} button shows${others.length ? ` (the confirm buttons that show: ${clipList(others)})` : ""}`;
        if (spec.later) warnings.push({ code: "later", text: `${why} (${spec.later})` });
        else failures.push({ code: "confirm", text: why });
        note = "nothing sent; no button to press";
        issueFindings(page.takeIssues(), failures);
        return;
      }
      if (vp.touch && (press.w! < 44 || press.h! < 44)) warnings.push({ code: "target", text: `${press.id} is ${press.w}x${press.h} px, under the 44 px touch target` });

      // A flow of several steps (a card with several questions) keeps the same button until its last step; a step
      // whose button is off gets its first option picked, as a reader would.
      const since = wire.mark();
      let stepsTaken = 0;
      let stall = "";
      let around = await page.textAround(press.id!);
      for (; stepsTaken < 5; stepsTaken++) {
        await page.press(press.x!, press.y!);
        await sleep(150);
        await page.settle();
        if (acting(wire.framesSince(since)).length || wire.httpSince(since).length) break;
        const now = await page.textAround(press.id!);
        if (now === null) break; // the button went away (a dialog closed): what went out decides
        if (now === around) {
          stall = stepsTaken ? `press ${stepsTaken + 1} changed nothing on the page` : "the press changed nothing on the page";
          break;
        }
        around = now;
        let again = await page.findConfirm(press.id);
        if (!again.found && again.disabled.length) {
          const option = await page.locate('[data-testid^="option-"]');
          if (!option) {
            stall = `${press.id} is off and no option shows`;
            break;
          }
          await page.press(option.x, option.y);
          await sleep(60);
          await page.settle();
          again = await page.findConfirm(press.id);
        }
        if (!again.found) {
          stall = `${press.id} stays off`;
          break;
        }
        press = again;
      }
      await waitSent(wire, since);
      await page.settle();
      shot = shotName(scene, spec.id, vp, "dark", "after");
      await maskMachine(page);
      await page.screenshot(shot).catch(() => {});

      const frames = wire.framesSince(since);
      const sent = acting(frames);
      const drafts = frames.filter((f) => f.t === "draft");
      const http = wire.httpSince(since);
      const rec = ((await recorder(page)) ?? []).slice(n0);
      details.sent = sent.map((f) => f.frame);
      details.http = http.map(httpText);
      details.recorded = rec;
      details.steps = stepsTaken + 1;
      const how = `${vp.touch ? "a tap" : "a click"} on ${press.id}${stepsTaken ? ` (${stepsTaken + 1} steps)` : ""}`;
      const what = [...sent.map(frameText), ...http.map(httpText)];

      if (!what.length) {
        const text = `${how} sent nothing${stall ? `; ${stall}` : ""}${press.covered ? `; ${press.covered} covers the button` : ""}`;
        if (spec.later) warnings.push({ code: "later", text: `${text} (${spec.later})` });
        else failures.push({ code: "click", text });
        note = "nothing sent";
        issueFindings(page.takeIssues(), failures);
        return;
      }
      if (drafts.length) failures.push({ code: "click", text: `${how} also sent ${drafts.length} draft frame${drafts.length > 1 ? "s" : ""}; only the user's own input in the message box sends one (5.5 item 4)` });

      if ("ws" in spec.expect) {
        const want = spec.expect.ws;
        if (http.length) failures.push({ code: "click", text: `${how} also sent ${clipList(http.map(httpText))}` });
        if (sent.length !== 1 || sent[0]!.t !== want) failures.push({ code: "click", text: `${how} sent ${clipList(what)}; expected exactly one ${want}` });
        const f = sent.find((x) => x.t === want);
        if (f) {
          const bad = spec.expect.check?.(f.frame) ?? null;
          if (bad) failures.push({ code: "frame", text: `the ${want} frame: ${bad}` });
          const ackMs = spec.ackMs ?? 3000;
          const ack = await waitAck(wire, f.rid!, ackMs);
          details.ack = ack;
          if (!ack) warnings.push({ code: "ack", text: `no ack for the ${want} frame in ${ackMs / 1000} s` });
          else if (!ack.ok) failures.push({ code: "ack", text: `the server refused the ${want} frame: ${ack.code}` });
          else {
            const off = spec.ackResult?.(ack.result) ?? null;
            if (off) failures.push({ code: "ack", text: `the ${want} ack: ${off}` });
          }
          if (rec.filter((t) => t === want).length !== 1) failures.push({ code: "recorder", text: `window.__kitespanFrames recorded ${rec.length ? clipList(rec) : "nothing"} for the press; expected one ${want}` });
        }
      } else {
        const exp = spec.expect;
        const hit = http.filter((h) => exp.methods.includes(h.method) && exp.http.test(h.path));
        if (sent.length) failures.push({ code: "click", text: `${how} also sent ${clipList(sent.map(frameText))}` });
        if (http.length !== 1 || hit.length !== 1) failures.push({ code: "click", text: `${how} sent ${clipList(what)}; expected one ${exp.methods.join(" or ")} ${exp.http.source}` });
        if (hit[0]?.status && hit[0].status >= 400) failures.push({ code: "ack", text: `the server answered ${httpText(hit[0])}` });
        if (hit[0] && !rec.some((t) => t.startsWith(`${hit[0]!.method} /api/`))) failures.push({ code: "recorder", text: `window.__kitespanFrames recorded ${rec.length ? clipList(rec) : "nothing"} for ${hit[0].method} ${hit[0].path}` });
      }
      note = `nothing before the press; ${how} sent ${clipList(what)}`;
      issueFindings(page.takeIssues(), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return finish({ kind: "action", name: spec.id, route: spec.route, scene, size: sizeTag(vp), theme: "dark", path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

// ---------------------------------------------------------------------------------------------------------------
// The phone + menu flow (iteration 1's fix f3e538b; BUILD-CHECKLIST B9)

/**
 * The iPhone model of the owner's bug: while the browser's own file picker is up, the page's history.back() (and a
 * history.go back) is dropped, and the flag clears when the picked files arrive. Counted in window.__droppedBack.
 */
const WEBKIT_MODEL = `(() => {
  let picking = false; const click = HTMLInputElement.prototype.click; const back = history.back.bind(history); const go = history.go.bind(history);
  HTMLInputElement.prototype.click = function () { if (this.type === "file") picking = true; return click.call(this); };
  addEventListener("change", (e) => { if (e.target && e.target.type === "file") picking = false; }, true);
  history.back = () => { if (picking) { window.__droppedBack = (window.__droppedBack || 0) + 1; return; } back(); };
  history.go = (n) => { if (picking && n < 0) { window.__droppedBack = (window.__droppedBack || 0) + 1; return; } go(n); };
})();`;

const PLUS_BUTTON = '[data-testid="composer-plus"], [data-testid="composer"] button[aria-label="Add to this chat"]';
const MENU_STATE = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const input = document.querySelector('[data-testid="composer-input"]');
  return {
    path: location.pathname + location.search,
    menu: shown(document.querySelector('[data-testid="plus-menu"]')) || shown(document.querySelector('[data-testid="plus-attach"]')),
    chips: [...document.querySelectorAll('[data-testid^="attach-"]')].filter((e) => shown(e) && e.getAttribute("data-testid") !== "attach-remove").length,
    field: input ? (input.value ?? input.textContent ?? "") : null,
    droppedBack: window.__droppedBack || 0,
  };
})())`;

interface MenuState {
  path: string;
  menu: boolean;
  chips: number;
  field: string | null;
  droppedBack: number;
}

async function menuFlow(id: string, base: string, scene: SceneName | null, vp: Viewport, webkit: boolean): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const chatPath = `/c/${EX.chat}`;
  let shot: string | undefined;
  const file = join(OUT, "flow-upload.txt");
  writeFileSync(file, "hello from the click-through\n");
  try {
    await withPage(vp, "dark", async (page, wire) => {
      const state = async (label: string): Promise<MenuState> => {
        const s = JSON.parse(await page.evaluate<string>(MENU_STATE)) as MenuState;
        details[label] = s;
        await page.screenshot(shotName(scene, id, vp, "dark", label)).catch(() => {});
        return s;
      };
      let chooser: { backendNodeId: number } | null = null;
      const off = cdp.on((e) => {
        if (e.sessionId === page.session && e.method === "Page.fileChooserOpened") chooser = e.params;
      });
      try {
        await page.send("DOM.enable");
        await page.send("Page.setInterceptFileChooserDialog", { enabled: true });
        if (webkit) await page.send("Page.addScriptToEvaluateOnNewDocument", { source: WEBKIT_MODEL });
        await page.navigate(base + chatPath);
        await waitShown(page, ["chat", "composer"]);
        page.takeIssues();
        const since = wire.mark();
        // The draft is the server's (D49): an earlier flow's chip on this server life is still in it.
        const start = await state("start");

        // + opens the menu (its own route, /c/<chat>/add).
        const plus = await page.locate(PLUS_BUTTON);
        if (!plus) {
          failures.push({ code: "flow", text: "no + button (Add to this chat) shows in the composer" });
          return;
        }
        await page.press(plus.x, plus.y);
        await sleep(500);
        await page.settle();
        const open = await state("menu-open");
        if (!open.menu) failures.push({ code: "flow", text: "+ did not open the menu" });
        if (!samePath(open.path, `${chatPath}/add`)) warnings.push({ code: "flow", text: `the open menu's URL is ${open.path}, not ${chatPath}/add` });

        // Add files or photos: the menu closes as soon as the picker opens (the owner's iPhone bug, f3e538b).
        const attach = await page.locate('[data-testid="plus-attach"]');
        if (!attach) {
          failures.push({ code: "flow", text: "Add files or photos (plus-attach) does not show in the menu" });
          return;
        }
        await page.press(attach.x, attach.y);
        const t1 = Date.now();
        while (!chooser && Date.now() - t1 < 3000) await sleep(50);
        await sleep(300);
        const picking = await state("picker-open");
        if (!chooser) failures.push({ code: "flow", text: "Add files or photos opened no file picker" });
        if (picking.menu) failures.push({ code: "flow", text: `the menu stays open over the message box while the picker is up${webkit ? " (the browser dropped history.back())" : ""}` });

        // The pick: one file arrives.
        const picked = chooser as { backendNodeId: number } | null;
        if (picked) await page.send("DOM.setFileInputFiles", { files: [file], backendNodeId: picked.backendNodeId });
        await sleep(1200);
        await page.settle();
        const after = await state("after-pick");
        if (after.menu) failures.push({ code: "flow", text: "the menu is open again after the pick" });
        if (!samePath(after.path, chatPath)) failures.push({ code: "flow", text: `after the pick the URL is ${after.path}, not ${chatPath}${webkit ? " (the dropped history step was not taken again)" : ""}` });
        const added = after.chips - start.chips;
        if (added !== 1) failures.push({ code: "flow", text: `${added} new attachment chip${added === 1 ? "" : "s"} after the pick; expected one` });
        if (after.field && (after.field.includes(file) || after.field.includes("@/"))) failures.push({ code: "flow", text: "the message box holds the file's path; a file is a chip only (D50)" });
        if (webkit) details.droppedBack = after.droppedBack;

        // No history entry left behind: Back from here never lands on the menu.
        const hist = await page.history();
        const urls = hist.entries.map((e) => e.url.replace(base, ""));
        details.entries = urls;
        if (urls.slice(0, hist.currentIndex + 1).some((u) => u.startsWith("/") && samePath(u, `${chatPath}/add`))) failures.push({ code: "flow", text: `the menu left a history entry: ${urls.slice(0, hist.currentIndex + 1).join(" , ")}` });

        // Nothing sent: the upload (one POST under /api/uploads) and the draft that names its chip are the pick's own.
        const sent = acting(wire.framesSince(since));
        const http = wire.httpSince(since);
        details.http = http.map(httpText);
        if (sent.length) failures.push({ code: "click", text: `the flow sent ${clipList(sent.map(frameText))}` });
        const ups = http.filter((h) => h.method === "POST" && h.path === "/api/uploads");
        if (ups.length !== 1 || http.length !== 1) failures.push({ code: "click", text: `the pick sent ${http.length ? clipList(http.map(httpText)) : "no request"}; expected one POST /api/uploads` });
        else if (ups[0]!.status && ups[0]!.status >= 400) failures.push({ code: "ack", text: `the upload was refused: ${httpText(ups[0]!)}` });
        issueFindings(page.takeIssues(), failures);
        shot = shotName(scene, id, vp, "dark", "after-pick");
      } finally {
        off();
      }
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = webkit ? "the menu closed when the picker opened (history.back() dropped while it was up), one chip, nothing sent" : "the menu closed when the picker opened, one chip, nothing sent";
  return finish({ kind: "flow", name: id, route: "add", scene, size: sizeTag(vp), theme: "dark", path: `/c/${EX.chat}`, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/** A laptop window under 1,000 px wide: /chats opens the sidebar as a drawer there too (DESIGN.md 6.1, 5.3). */
const NARROW_LAPTOP: Viewport = { name: "laptop", width: 900, height: 800, scale: 1, mobile: false, touch: false };
/** A small phone (320 x 568): a message box too narrow for a long command chip and the field side by side (row 76). */
const SMALL_PHONE: Viewport = { name: "phone", width: 320, height: 568, scale: 2, mobile: true, touch: true };

/** The first chat row in the open list that is not the example chat (whose state the later flows need), by its id. */
const OTHER_ROW = (except: string) => `(() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  for (const li of document.querySelectorAll("li.scr-row-li")) {
    const a = li.querySelector("a.scr-row");
    const m = a && /\\/c\\/([a-z2-7]{20})$/.exec(new URL(a.href).pathname);
    if (m && m[1] !== ${JSON.stringify(except)} && shown(li.querySelector(".scr-row-more"))) return m[1];
  }
  return null;
})()`;

/**
 * A chat row's menu in the chat-list drawer (medium touch, and a laptop window under 1,000 px): the menu draws over
 * the drawer's scrim, so its items take the tap. "..." then Rename opens /c/<chat>/rename, with nothing sent; a
 * long-press (a right-click on the laptop) then Archive sends exactly one archive frame for that chat.
 */
async function rowMenuFlow(base: string, scene: SceneName | null, vp: Viewport, label: string): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const id = "row-menu";
  const tag = label === vp.name ? vp : { ...vp, name: label as SizeName };
  let shot: string | undefined;
  try {
    await withPage(vp, "dark", async (page, wire) => {
      const openList = async () => {
        await page.navigate(base + "/chats");
        await page.settle();
        const chat = await page.evaluate<string | null>(OTHER_ROW(EX.chat));
        if (!chat) failures.push({ code: "flow", text: "the chat list shows no row (other than the example chat) with a menu button" });
        return chat;
      };
      const item = async (selector: string, what: string) => {
        const at = await page.locate(selector);
        if (!at) failures.push({ code: "flow", text: `the row's menu shows no ${what}` });
        else if (at.covered) failures.push({ code: "flow", text: `the menu's ${what} is covered by ${at.covered}, so a tap lands there` });
        return at && !at.covered ? at : null;
      };
      const chat = await openList();
      if (!chat) return;
      page.takeIssues();
      details.chat = chat;
      const since = wire.mark();

      // "..." then Rename: the route of the rename dialog, nothing sent.
      const more = await page.locate(`li.scr-row-li:has(a.scr-row[href$="/c/${chat}"]) .scr-row-more`);
      if (!more) {
        failures.push({ code: "flow", text: "the row has no menu button" });
        return;
      }
      await page.press(more.x, more.y);
      await sleep(400);
      await page.settle();
      await page.screenshot(shotName(scene, id, tag, "dark", "menu")).catch(() => {});
      const rename = await item(`[data-testid="row-menu"] a[href$="/c/${chat}/rename"]`, "Rename");
      if (rename) {
        await page.press(rename.x, rename.y);
        await sleep(500);
        await page.settle();
        const path = await page.evaluate<string>("location.pathname");
        details.afterRename = path;
        if (path !== `/c/${chat}/rename`) failures.push({ code: "flow", text: `Rename in the row's menu opened ${path}, not /c/${chat}/rename` });
      }
      const quiet = acting(wire.framesSince(since));
      if (quiet.length) failures.push({ code: "click", text: `"..." and Rename sent ${clipList(quiet.map(frameText))}` });

      // A long-press (a right-click on the laptop) then Archive: one archive frame for this chat.
      if (!(await openList())) return;
      const row = await page.locate(`a.scr-row[href$="/c/${chat}"]`);
      if (!row) {
        failures.push({ code: "flow", text: "the row is gone from the list after Rename was closed" });
        return;
      }
      const mark = wire.mark();
      await page.hold(row.x, row.y);
      await sleep(400);
      await page.settle();
      const archive = await item('[data-testid="row-menu"] [data-testid="row-archive"]', "Archive");
      if (archive) {
        await page.press(archive.x, archive.y);
        await sleep(800);
        await page.settle();
        const sent = acting(wire.framesSince(mark));
        details.afterArchive = sent.map((f) => f.frame);
        const ok = sent.length === 1 && sent[0]!.t === "archive" && sent[0]!.frame.chat === chat && sent[0]!.frame.on === true;
        if (!ok) failures.push({ code: "click", text: `Archive in the long-press menu sent ${sent.length ? clipList(sent.map(frameText)) : "nothing"}; expected one archive frame for ${chat}` });
      }
      issueFindings(page.takeIssues(), failures);
      shot = shotName(scene, id, tag, "dark", "menu");
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return finish({ kind: "flow", name: id, route: "chats", scene, size: sizeTag(vp), theme: "dark", path: "/chats", failures, warnings, note: `${label}: "..." then Rename opens the rename route; a long-press then Archive sends one archive frame`, shot, ms: Date.now() - t0, details });
}

/** A chat row of the list by its chat id: the row's link, the swipe's actions and what shows (in the page). */
const SWIPE_STATE = (chat: string) => `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const li = [...document.querySelectorAll("li.scr-row-li")].find((x) => x.querySelector('a.scr-row[href$="/c/${chat}"]'));
  const swipe = li ? li.querySelector('[data-testid="row-swipe"]') : null;
  return {
    path: location.pathname + location.search,
    swiped: !!swipe && shown(swipe),
    swipedAny: [...document.querySelectorAll('[data-testid="row-swipe"]')].some(shown),
    dialog: shown(document.querySelector('[data-testid="dialog-delete"]')),
    list: shown(document.querySelector('[data-testid="chat-list"]')),
    groupsOpen: [...document.querySelectorAll(".scr-fold")].filter((b) => b.getAttribute("aria-expanded") === "true").length,
  };
})())`;

interface SwipeState {
  path: string;
  swiped: boolean;
  swipedAny: boolean;
  dialog: boolean;
  list: boolean;
  groupsOpen: number;
}

/** A finger's swipe to the left from (x, y): touch events in steps, as a phone sends them (7.7). */
async function swipeLeft(page: Page, x: number, y: number, dx = 220) {
  const point = (px: number) => [{ x: px, y, radiusX: 4, radiusY: 4, force: 1 }];
  await page.send("Input.dispatchTouchEvent", { type: "touchStart", touchPoints: point(x) });
  for (let i = 1; i <= 10; i++) {
    await page.send("Input.dispatchTouchEvent", { type: "touchMove", touchPoints: point(x - (dx * i) / 10) });
    await sleep(16);
  }
  await page.send("Input.dispatchTouchEvent", { type: "touchEnd", touchPoints: [] });
}

/**
 * The phone's swipe on a chat row (7.7, 6.10): a swipe to the left only shows the row's archive item and Delete.
 * row-swipe-delete: Delete opens the delete sheet over the list's chat, and Cancel, at the sheet's top right, goes
 * back to /chats. row-swipe-heading: a tap on a group heading's name (a link to the project) only closes the actions:
 * the page stays on /chats and the groups stay as they were. Neither sends a request.
 */
async function swipeFlow(id: "row-swipe-delete" | "row-swipe-heading", base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  let shot: string | undefined;
  try {
    await withPage(vp, theme, async (page, wire) => {
      await page.navigate(base + "/chats");
      await page.settle();
      const chat = await page.evaluate<string | null>(OTHER_ROW(EX.chat));
      if (!chat) {
        failures.push({ code: "flow", text: "the chat list shows no row (other than the example chat) to swipe" });
        return;
      }
      details.chat = chat;
      page.takeIssues();
      const since = wire.mark();
      const state = async (label: string): Promise<SwipeState> => {
        const st = JSON.parse(await page.evaluate<string>(SWIPE_STATE(chat))) as SwipeState;
        details[label] = st;
        await page.screenshot(shotName(scene, id, vp, theme, label)).catch(() => {});
        return st;
      };
      const row = await page.locate(`a.scr-row[href$="/c/${chat}"]`);
      if (!row) {
        failures.push({ code: "flow", text: "the row's link does not show" });
        return;
      }
      await swipeLeft(page, row.x + 60, row.y);
      await sleep(400);
      await page.settle();
      const swiped = await state("swiped");
      if (!swiped.swiped) {
        failures.push({ code: "flow", text: "a swipe to the left did not show the row's actions" });
        return;
      }
      if (!samePath(swiped.path, "/chats")) failures.push({ code: "flow", text: `the swipe moved the page to ${swiped.path}` });

      if (id === "row-swipe-delete") {
        const del = await page.locate(`li.scr-row-li [data-testid="row-swipe"] a[href$="/c/${chat}/delete"]`);
        if (!del) {
          failures.push({ code: "flow", text: "the swipe's actions show no Delete" });
          return;
        }
        if (del.covered) failures.push({ code: "flow", text: `the swipe's Delete is covered by ${del.covered}` });
        await page.press(del.x, del.y);
        await sleep(500);
        await page.settle();
        const open = await state("delete-open");
        if (!samePath(open.path, `/c/${chat}/delete`)) failures.push({ code: "flow", text: `Delete opened ${open.path}, not /c/${chat}/delete` });
        if (!open.dialog) failures.push({ code: "flow", text: "Delete did not open the delete sheet" });
        // The phone's sheet has Cancel at its top right; a tablet's dialog (v0.6 touch: the drawer, the sidebar) in its row.
        const cancel = await page.locate(vp.name === "phone" ? '[data-testid="dialog-delete"] [data-testid="sheet-cancel"]' : '[data-testid="dialog-delete"] .dialog-actions button:not(.primary)');
        if (!cancel) {
          failures.push({ code: "flow", text: vp.name === "phone" ? "the delete sheet shows no Cancel at its top right" : "the delete dialog shows no Cancel" });
          return;
        }
        await page.press(cancel.x, cancel.y);
        await sleep(600);
        await page.settle();
        const after = await state("after-cancel");
        if (!samePath(after.path, "/chats")) failures.push({ code: "flow", text: `Cancel went to ${after.path}, not back to /chats` });
        if (after.dialog) failures.push({ code: "flow", text: "the delete sheet is still open after Cancel" });
        if (!after.list) failures.push({ code: "flow", text: "the chat list does not show after Cancel" });
        const hist = await page.history();
        const urls = hist.entries.slice(0, hist.currentIndex + 1).map((e) => e.url.replace(base, ""));
        details.entries = urls;
        if (urls.some((u) => u.startsWith(`/c/${chat}`))) failures.push({ code: "flow", text: `Cancel left an entry of the chat behind /chats: ${urls.join(" , ")}` });
        shot = shotName(scene, id, vp, theme, "after-cancel");

        // The same from the row's long-press menu: Delete, then Cancel, back to /chats.
        const again = await page.locate(`a.scr-row[href$="/c/${chat}"]`);
        if (!again) {
          failures.push({ code: "flow", text: "the row is gone from the list after Cancel" });
          return;
        }
        await page.hold(again.x, again.y);
        await sleep(400);
        await page.settle();
        const menuDelete = await page.locate(`[data-testid="row-menu"] a[href$="/c/${chat}/delete"]`);
        if (!menuDelete) {
          failures.push({ code: "flow", text: "the long-press menu shows no Delete" });
          return;
        }
        await page.press(menuDelete.x, menuDelete.y);
        await sleep(500);
        await page.settle();
        const menuCancel = await page.locate(vp.name === "phone" ? '[data-testid="dialog-delete"] [data-testid="sheet-cancel"]' : '[data-testid="dialog-delete"] .dialog-actions button:not(.primary)');
        if (!menuCancel) {
          failures.push({ code: "flow", text: "Delete in the long-press menu opened no delete sheet with Cancel" });
          return;
        }
        await page.press(menuCancel.x, menuCancel.y);
        await sleep(600);
        await page.settle();
        const back = await state("after-menu-cancel");
        if (!samePath(back.path, "/chats") || back.dialog) failures.push({ code: "flow", text: `the long-press menu's Delete, then Cancel, left the page on ${back.path}${back.dialog ? " with the sheet open" : ""}, not on /chats` });
      } else {
        const heading = await page.locate(`.scr-group-head a.scr-group-name`);
        if (!heading) {
          failures.push({ code: "flow", text: "the list shows no group heading" });
          return;
        }
        await page.press(heading.x, heading.y);
        await sleep(600);
        await page.settle();
        const after = await state("after-tap");
        if (!samePath(after.path, "/chats")) failures.push({ code: "flow", text: `the tap on the group heading opened ${after.path}; it should only close the actions` });
        if (after.swipedAny) failures.push({ code: "flow", text: "the swipe's actions are still open after a tap on a group heading" });
        if (after.groupsOpen !== swiped.groupsOpen) failures.push({ code: "flow", text: `the tap folded or opened a group (${swiped.groupsOpen} open before, ${after.groupsOpen} after)` });
        shot = shotName(scene, id, vp, theme, "after-tap");
      }
      const sent = acting(wire.framesSince(since));
      const http = wire.httpSince(since);
      if (sent.length || http.length) failures.push({ code: "click", text: `the flow sent ${clipList([...sent.map(frameText), ...http.map(httpText)])}` });
      issueFindings(page.takeIssues(), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = id === "row-swipe-delete" ? "swipe (and the long-press menu), Delete, Cancel: back on /chats, nothing sent" : "swipe, then a tap on a group heading: the actions close, nothing opens, nothing sent";
  return finish({ kind: "flow", name: id, route: "chats", scene, size: sizeTag(vp), theme, path: "/chats", failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * A link to a file that is not in the chat's folder (5.4): the download view's one line, "That file is not in this
 * chat's folder.", with no Download, no failed request and no console error (the existence probe is a 200 read).
 */
async function fileGoneFlow(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const path = `/c/${EX.chat}/files/src/not-here-${Date.now().toString(36)}.ts`;
  let shot: string | undefined;
  try {
    await withPage(vp, "dark", async (page, wire) => {
      const since = wire.mark();
      await page.navigate(base + path);
      await waitShown(page, ["file-download"]);
      await sleep(300);
      const got = await page.evaluate<string>(`JSON.stringify((() => {
        const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
        const view = [...document.querySelectorAll('[data-testid="file-download"]')].find(shown);
        return {
          path: location.pathname,
          lines: view ? [...view.querySelectorAll('[data-testid="link-notice"]')].filter(shown).map((e) => e.textContent.trim()) : null,
          download: [...document.querySelectorAll('[data-testid="file-download-button"]')].some(shown),
        };
      })())`);
      const st = JSON.parse(got) as { path: string; lines: string[] | null; download: boolean };
      details.state = st;
      if (st.lines === null) failures.push({ code: "flow", text: "the file's view does not show" });
      else if (st.lines.length !== 1 || st.lines[0] !== "That file is not in this chat's folder.") failures.push({ code: "flow", text: `the view's lines are ${JSON.stringify(st.lines)}; expected the one 5.4 line` });
      if (st.download) failures.push({ code: "flow", text: "a gone file still offers Download" });
      if (st.path !== path) failures.push({ code: "flow", text: `the URL changed to ${st.path}` });
      issueFindings(page.takeIssues(), failures);
      const sent = acting(wire.framesSince(since));
      if (sent.length || wire.httpSince(since).length) failures.push({ code: "click", text: `opening the link sent ${clipList(sent.map(frameText))}` });
      shot = shotName(scene, "file-gone", vp, "dark");
      await page.screenshot(shot).catch(() => {});
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return finish({ kind: "flow", name: "file-gone", route: "files", scene, size: sizeTag(vp), theme: "dark", path, failures, warnings, note: "the 5.4 line, no Download, no failed request or console error", shot, ms: Date.now() - t0, details });
}

/** The composer's mode, its button and its field's text (in the page). */
const COMPOSER_STATE = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const box = [...document.querySelectorAll('[data-testid="composer"]')].find(shown);
  const input = box ? box.querySelector('[data-testid="composer-input"]') : null;
  return {
    mode: box ? box.getAttribute("data-mode") : null,
    field: input ? input.value : null,
    run: !!box && shown(box.querySelector('[data-testid="confirm-run"]')),
    send: !!box && [...box.querySelectorAll('[data-testid="confirm-send"], [data-testid="composer-send"]')].some(shown),
  };
})())`;

interface ComposerState {
  mode: string | null;
  field: string | null;
  run: boolean;
  send: boolean;
}

const FIELD = `document.querySelector('[data-testid="composer"] [data-testid="composer-input"]')`;

/**
 * A message that starts with "!" stays a message (D49, 5.1 rule 7): a send link's text "!echo ..." fills the field in
 * chat mode; typed at its end, it is saved as the user's own draft and is still a message; after a reload the draft
 * comes back in chat mode with Send, never in Bash mode with Run. The field is cleared at the end (the server keeps the
 * draft), and nothing but drafts goes out.
 */
async function bangMessageFlow(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const text = "!echo kitespan-bang";
  const path = `/c/${EX.chat}/send?text=${encodeURIComponent(text)}`;
  let shot: string | undefined;
  try {
    await withPage(vp, "dark", async (page, wire) => {
      const read = async (label: string): Promise<ComposerState> => {
        const st = JSON.parse(await page.evaluate<string>(COMPOSER_STATE)) as ComposerState;
        details[label] = st;
        return st;
      };
      const expectMessage = (st: ComposerState, when: string) => {
        if (st.mode !== "chat") failures.push({ code: "flow", text: `${when}, the composer is in ${st.mode ?? "no"} mode, not chat` });
        if (st.run || !st.send) failures.push({ code: "flow", text: `${when}, the composer offers ${st.run ? "Run" : "no Send"}` });
      };
      await page.navigate(base + path);
      await waitShown(page, ["chat", "composer"]);
      page.takeIssues();
      const since = wire.mark();
      const filled = await read("filled");
      if (filled.field !== text) failures.push({ code: "flow", text: `the send link filled ${JSON.stringify(filled.field)}, not ${JSON.stringify(text)}` });
      expectMessage(filled, "with the link's text");
      // Type at the end of the text: the user's own edit, which is saved as the chat's draft.
      await page.evaluate(`(() => { const el = ${FIELD}; el.focus(); el.setSelectionRange(el.value.length, el.value.length); })()`);
      await page.send("Input.insertText", { text: " ok" });
      await sleep(900);
      const edited = await read("edited");
      if (edited.field !== `${text} ok`) failures.push({ code: "flow", text: `after typing, the field holds ${JSON.stringify(edited.field)}` });
      expectMessage(edited, "after typing at the end");
      // Open the chat's own path in a new document: the draft comes from the server.
      await page.navigate(base + `/c/${EX.chat}`);
      await waitShown(page, ["chat", "composer"]);
      await sleep(600);
      const back = await read("reloaded");
      if (back.field !== `${text} ok`) failures.push({ code: "flow", text: `after a reload, the field holds ${JSON.stringify(back.field)}` });
      expectMessage(back, "after a reload");
      shot = shotName(scene, "bang-message", vp, "dark", "reloaded");
      await page.screenshot(shot).catch(() => {});
      const sent = acting(wire.framesSince(since));
      if (sent.length || wire.httpSince(since).length) failures.push({ code: "click", text: `the flow sent ${clipList(sent.map(frameText))}` });
      issueFindings(page.takeIssues(), failures);
      // Leave the chat's draft empty for the checks after this one: select all, then Backspace, then blur (a save).
      await page.evaluate(`(() => { const el = ${FIELD}; el.focus(); el.select(); })()`);
      const key = { key: "Backspace", code: "Backspace", windowsVirtualKeyCode: 8, nativeVirtualKeyCode: 8 };
      await page.send("Input.dispatchKeyEvent", { type: "keyDown", ...key });
      await page.send("Input.dispatchKeyEvent", { type: "keyUp", ...key });
      await page.evaluate(`(() => { const el = ${FIELD}; if (el) el.blur(); })()`);
      await sleep(600);
      const cleared = await read("cleared");
      if (cleared.field !== "") warnings.push({ code: "flow", text: `the field could not be cleared at the end (${JSON.stringify(cleared.field)})` });
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return finish({ kind: "flow", name: "bang-message", route: "send", scene, size: sizeTag(vp), theme: "dark", path, failures, warnings, note: 'a "!" message stays a message after an edit and a reload: Send, never Run', shot, ms: Date.now() - t0, details });
}

/** The fake claude's `user` lines whose content holds this text (a message, or a `!` command's record). */
function claudeSaw(b: Booted, text: string): number {
  return b.trace().filter((l) => l.t === "user" && JSON.stringify(l.content ?? null).includes(text)).length;
}

/**
 * How many turns the fake claude ran for a message, by the uuids it got it under: a message that came back from Claude
 * Code's queue (cancel_async_message, row 78's rule) and went again was got twice and ran once.
 */
function claudeRuns(b: Booted, text: string): number {
  const trace = b.trace();
  const uuids = new Set(trace.filter((l) => l.t === "user" && JSON.stringify(l.content ?? null).includes(text)).map((l) => l.uuid));
  return trace.filter((l) => l.t === "turn_start" && uuids.has(l.uuid)).length;
}

/** Whether a line sampler said something from `from` to `to`: its state at `from` (its last change before), or a change in between. */
function saidBetween(lines: LineSample[], from: number, to: number, ok: (x: LineSample) => boolean): boolean {
  const before = lines.filter((x) => x.t <= from).at(-1);
  return (!!before && ok(before)) || lines.some((x) => x.t > from && x.t <= to && ok(x));
}

/**
 * A composer link opened as a new document right after the chat's own page in the same tab (a link, a typed URL):
 * Send, and then Run on a `!` link, each go out once with an ok ack, the message reaches the fake claude exactly once,
 * the `!` command runs once, and the route closes to the chat in the same document (closing an action route never
 * goes back to the earlier document, which would unload the page with the frame still in it). Nothing goes out before
 * the press.
 */
async function sendNewDocumentFlow(t: Target, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const chatPath = `/c/${EX.chat}`;
  const tag = `${vp.name}-${Date.now().toString(36)}`;
  const text = `Sent from a new document ${tag}`;
  const cmd = `echo ran-from-a-new-document-${tag}`;
  const path = `${chatPath}/send?text=${encodeURIComponent(text)}`;
  let shot: string | undefined;
  if (!t.booted) warnings.push({ code: "flow", text: "with --base the fake claude's trace cannot be read" });
  /** Open `link` as a new document after the chat's page, press its button, and judge what went out and where it ended. */
  const pressOnce = async (page: Page, wire: Wire, link: string, button: string, frameT: "send" | "bash", token: string, label: string) => {
    await page.navigate(t.base + chatPath);
    await waitShown(page, ["chat", "composer"]);
    await page.navigate(t.base + link);
    await waitShown(page, ["chat", "composer", button]);
    await sleep(400);
    page.takeIssues();
    const since = wire.mark();
    const entry = await page.evaluate<{ from: string | null; length: number }>(`({ from: (history.state && history.state.from) || null, length: history.length })`);
    details[`${label}Entry`] = entry;
    if (entry.from !== chatPath) warnings.push({ code: "flow", text: `${label}: the link's entry does not name the chat's page as its from (${JSON.stringify(entry.from)}), so this run does not reproduce the finding` });
    // A mark in this document: a page that goes back to the chat's earlier document loses it.
    await page.evaluate(`(() => { window.__kitespanSameDocument = ${JSON.stringify(token)}; })()`);
    const before = t.booted ? claudeSaw(t.booted, token) : 0;
    const btn = await page.locate(`[data-testid="composer"] [data-testid="${button}"]`);
    if (!btn) {
      failures.push({ code: "flow", text: `${label}: no ${button} button on ${link}` });
      return;
    }
    await page.press(btn.x, btn.y);
    await waitSent(wire, since);
    const sent = acting(wire.framesSince(since));
    details[`${label}Frames`] = sent.map((f) => f.frame);
    const mine = sent.filter((f) => f.t === frameT);
    if (mine.length !== 1 || sent.length !== 1) failures.push({ code: "click", text: `${label}: the press sent ${clipList(sent.map(frameText)) || "nothing"}; expected one ${frameT} frame` });
    const ack = mine[0]?.rid ? await waitAck(wire, mine[0].rid, 8000) : null;
    if (mine[0] && !ack?.ok) failures.push({ code: "ack", text: `${label}: the ${frameT} frame got ${ack ? `a refusal (${ack.code})` : "no ack"}` });
    if (t.booted) {
      const end = Date.now() + 8000;
      while (Date.now() < end && claudeSaw(t.booted, token) === before) await sleep(100);
      await sleep(800); // room for a second copy
      const seen = claudeSaw(t.booted, token) - before;
      details[`${label}ClaudeSaw`] = seen;
      if (seen !== 1) failures.push({ code: "flow", text: `${label}: the fake claude saw it ${seen} times; expected once` });
    }
    await page.settle();
    const after = await page.evaluate<{ url: string; same: boolean; field: string | null }>(
      `({ url: location.pathname + location.search, same: window.__kitespanSameDocument === ${JSON.stringify(token)}, field: (${FIELD} || {}).value ?? null })`,
    );
    details[`${label}After`] = after;
    if (!after.same) failures.push({ code: "flow", text: `${label}: the press left the document (closing the route went back to the earlier page)` });
    if (after.url !== chatPath) failures.push({ code: "flow", text: `${label}: the route closed to ${after.url}, not ${chatPath}` });
    if (after.field) failures.push({ code: "flow", text: `${label}: the box still holds ${JSON.stringify(after.field)} after the ok ack` });
    issueFindings(page.takeIssues(), failures, `${label}: `);
  };
  try {
    await withPage(vp, "dark", async (page, wire) => {
      await pressOnce(page, wire, path, "confirm-send", "send", text, "send");
      await pressOnce(page, wire, `${chatPath}/bash?cmd=${encodeURIComponent(cmd)}`, "confirm-run", "bash", cmd, "run");
      shot = shotName(scene, "send-new-document", vp, "dark");
      await page.screenshot(shot).catch(() => {});
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = "a send and a ! link opened as new documents after the chat: one frame each, an ok ack, the fake claude saw each once, the same document after the close";
  return finish({ kind: "flow", name: "send-new-document", route: "send", scene, size: sizeTag(vp), theme: "dark", path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * Settings opened as a new document right after a chat's page (a typed URL, a link; 5.1 rule 4): Done replaces the
 * entry with the chat in the same document (a mark set on the Settings page is still there). It never steps back into
 * the chat's earlier document, which would unload the page with a Save still on its way. Nothing mutating goes out.
 */
async function settingsNewDocumentFlow(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const chatPath = `/c/${EX.chat}`;
  // The phone's Done is on the Settings list; a laptop's is beside each section.
  const path = vp.name === "phone" ? "/settings" : "/settings/chats";
  try {
    await withPage(vp, "dark", async (page, wire) => {
      await page.navigate(base + chatPath);
      await waitShown(page, ["chat"]);
      await page.navigate(base + path);
      await waitShown(page, ["settings", "settings-done"]);
      await sleep(300);
      page.takeIssues();
      const since = wire.mark();
      const entry = await page.evaluate<{ from: string | null; depth: number }>(`({ from: (history.state && history.state.from) || null, depth: (history.state && history.state.settingsDepth) || 0 })`);
      details.entry = entry;
      if (entry.from !== chatPath) warnings.push({ code: "flow", text: `Settings' entry does not name the chat's page as its from (${JSON.stringify(entry.from)}), so this run does not reproduce the case` });
      await page.evaluate(`(() => { window.__kitespanSameDocument = "settings"; return true; })()`);
      const before = await page.history();
      const done = await page.locate('[data-testid="settings-done"]');
      if (!done) {
        failures.push({ code: "flow", text: "no Done button on Settings" });
        return;
      }
      await page.press(done.x, done.y);
      await sleep(300);
      await page.settle();
      const after = await page.evaluate<{ url: string; same: boolean }>(`({ url: location.pathname + location.search, same: window.__kitespanSameDocument === "settings" })`);
      const hist = await page.history();
      details.after = { ...after, currentIndex: hist.currentIndex, before: before.currentIndex, entries: hist.entries.map((e) => e.url.replace(base, "")) };
      if (!after.same) failures.push({ code: "flow", text: "Done left the document (it went back into the chat's earlier page)" });
      if (after.url !== chatPath) failures.push({ code: "flow", text: `Done went to ${after.url}, not ${chatPath}` });
      if (hist.currentIndex !== before.currentIndex) failures.push({ code: "flow", text: `Done moved from entry ${before.currentIndex} to ${hist.currentIndex}; expected a replace` });
      issueFindings(page.takeIssues(), failures);
      quietFindings(wire, since, await recorder(page), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return finish({ kind: "flow", name: "settings-new-document", route: "settings", scene, size: sizeTag(vp), theme: "dark", path, failures, warnings, note: "Settings opened as a new document after a chat: Done replaces it with the chat, in the same document", ms: Date.now() - t0, details });
}

/**
 * An in-page switch for the offline flows: once window.__uiGoOffline() runs, the page's sockets close and every new one
 * is a stand-in that never opens (no network, no port), so the page's socket stays down until the next document or
 * window.__uiGoOnline(), which lets new sockets through again and wakes the page as the browser's online event does
 * (again every 200 ms until the page has made a real socket, since a wake while a stand-in still dials does nothing).
 */
const OFFLINE_SWITCH = `(() => {
  const Real = window.WebSocket;
  const made = [];
  function Switched(url, protocols) {
    if (window.__uiOffline) {
      const fake = { readyState: 3, url, send() {}, close() {}, onopen: null, onmessage: null, onclose: null, onerror: null };
      setTimeout(() => fake.onclose && fake.onclose({ code: 1006 }), 30);
      return fake;
    }
    const ws = new Real(url, protocols);
    made.push(ws);
    return ws;
  }
  Switched.prototype = Real.prototype;
  for (const k of ["CONNECTING", "OPEN", "CLOSING", "CLOSED"]) Switched[k] = Real[k];
  window.WebSocket = Switched;
  window.__uiGoOffline = () => {
    window.__uiOffline = true;
    for (const ws of made) try { ws.close(); } catch {}
    return true;
  };
  window.__uiGoOnline = () => {
    window.__uiOffline = false;
    const n = made.length;
    let tries = 0;
    const kick = () => {
      if (made.length > n || tries++ > 50) return;
      dispatchEvent(new Event("online"));
      setTimeout(kick, 200);
    };
    kick();
    return true;
  };
})();`;

/**
 * A send while the socket is down (4.3, 7.5), on a chat that sleeps: the box empties at once and the message shows
 * once, drawn as not sent yet, and nothing goes out; on the phone the chat says Reconnecting... above the composer.
 * Then the page reloads before the socket is back: the message is in the box again, its sent copy is gone, and no send
 * went out by itself. At the end the box is cleared (an empty draft) for the checks after this one.
 */
async function offlineSendFlow(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const chat = IDS.chats.parser;
  const path = `/c/${chat}`;
  const text = `Sent while offline ${vp.name}-${Date.now().toString(36)}`;
  const STATE = `JSON.stringify((() => {
    const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
    const field = ${FIELD};
    const rows = [...document.querySelectorAll(".chat-user")].filter((el) => (el.textContent || "").includes(${JSON.stringify(text)}));
    return {
      field: field ? field.value : null,
      bubbles: rows.length,
      unsent: rows.filter((el) => el.classList.contains("is-unsent")).length,
      line: [...document.querySelectorAll('[data-testid="chat-reconnecting"]')].some(shown),
      foot: [...document.querySelectorAll('[data-testid="connection"]')].some((el) => shown(el) && el.getAttribute("data-state") === "reconnecting"),
      copy: localStorage.getItem(${JSON.stringify(`kitespan.sent.${chat}`)}),
    };
  })())`;
  type Got = { field: string | null; bubbles: number; unsent: number; line: boolean; foot: boolean; copy: string | null };
  let shot: string | undefined;
  try {
    await withPage(vp, "dark", async (page, wire) => {
      await page.send("Page.addScriptToEvaluateOnNewDocument", { source: OFFLINE_SWITCH });
      await page.navigate(base + path);
      await waitShown(page, ["chat", "composer"]);
      page.takeIssues();
      const since = wire.mark();
      await page.evaluate(`window.__uiGoOffline()`);
      await sleep(400);
      await page.evaluate(`(() => { const el = ${FIELD}; el.focus(); el.setSelectionRange(el.value.length, el.value.length); return true; })()`);
      await page.send("Input.insertText", { text });
      await sleep(150);
      await page.key("Enter");
      await sleep(500);
      const down = JSON.parse(await page.evaluate<string>(STATE)) as Got;
      details.down = down;
      if (down.field !== "") failures.push({ code: "flow", text: `with the socket down, the box still holds ${JSON.stringify(down.field)} after Send (the text shows twice, and a second Send could send it again)` });
      if (down.bubbles !== 1) failures.push({ code: "flow", text: `with the socket down, ${down.bubbles} bubbles hold the message; expected one` });
      else if (down.unsent !== 1) failures.push({ code: "flow", text: "with the socket down, the message's bubble is drawn as sent" });
      if (vp.name === "phone" && !down.line) failures.push({ code: "flow", text: "with the socket down and the message waiting, the phone's chat shows no Reconnecting... line" });
      if (vp.name === "laptop" && !down.line && !down.foot) failures.push({ code: "flow", text: "with the socket down, no Reconnecting... line shows" });
      if (down.line && down.foot) failures.push({ code: "flow", text: "two Reconnecting... lines show (the chat's and the list's foot)" });
      if (!down.copy) failures.push({ code: "flow", text: "no copy of the waiting message is kept in local storage" });
      shot = shotName(scene, "offline-send", vp, "dark");
      await page.screenshot(shot).catch(() => {});
      const out = acting(wire.framesSince(since));
      if (out.length) failures.push({ code: "click", text: `with the socket down, the wire shows ${clipList(out.map(frameText))}` });
      // The page reloads before the socket comes back (the phone's browser drops the tab): the outbox is gone.
      await page.reload();
      await waitShown(page, ["chat", "composer"]);
      await sleep(900);
      const back = JSON.parse(await page.evaluate<string>(STATE)) as Got;
      details.reloaded = back;
      if (back.field !== text) failures.push({ code: "flow", text: `after the reload the box holds ${JSON.stringify(back.field)}, not the message that never went out` });
      if (back.bubbles) failures.push({ code: "flow", text: "after the reload the transcript shows the message that never went out" });
      if (back.copy) failures.push({ code: "flow", text: "after the reload the waiting message's copy is still kept" });
      const sentAgain = acting(wire.framesSince(since)).filter((f) => f.t === "send");
      if (sentAgain.length) failures.push({ code: "click", text: `the reload sent ${clipList(sentAgain.map(frameText))} by itself` });
      issueFindings(page.takeIssues(), failures);
      // Leave the chat's draft empty for the checks after this one: select all, then Backspace, then blur (a save).
      await page.evaluate(`(() => { const el = ${FIELD}; el.focus(); el.select(); return true; })()`);
      const key = { key: "Backspace", code: "Backspace", windowsVirtualKeyCode: 8, nativeVirtualKeyCode: 8 };
      await page.send("Input.dispatchKeyEvent", { type: "keyDown", ...key });
      await page.send("Input.dispatchKeyEvent", { type: "keyUp", ...key });
      await page.evaluate(`(() => { const el = ${FIELD}; if (el) el.blur(); return true; })()`);
      await sleep(600);
      const cleared = JSON.parse(await page.evaluate<string>(STATE)) as Got;
      if (cleared.field !== "") warnings.push({ code: "flow", text: `the field could not be cleared at the end (${JSON.stringify(cleared.field)})` });
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = "a send with the socket down: the box empties, one bubble drawn as not sent yet, Reconnecting...; a reload puts the message back in the box";
  return finish({ kind: "flow", name: "offline-send", route: "send", scene, size: sizeTag(vp), theme: "dark", path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * Settings opened from a chat whose Claude Code sleeps, while the example chat's runs (6.5, 6.8), then reloaded: the
 * Skills and plugins and Output style rows wait quietly ("...") and then show the live chat's facts; they never say
 * "Start a chat to read it.", and nothing mutating goes out (the read is an attach and a detach).
 */
async function settingsFactsFlow(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const from = `/c/${IDS.chats.search}`;
  const path = "/settings/claude-code";
  const START = "Start a chat to read it.";
  let shot: string | undefined;
  const ROWS = `JSON.stringify(["setting-skills", "setting-output-style"].map((id) => { const r = document.querySelector('[data-testid="' + id + '"]'); return r ? r.textContent.replace(/\\s+/g, " ").trim() : null; }))`;
  try {
    await withPage(vp, "dark", async (page, wire) => {
      await page.navigate(base + from);
      await waitShown(page, ["chat"]);
      const since = wire.mark();
      await reachSettings(page, vp);
      for (const sel of ['a[href="/settings"]', `a[href="${path}"]`]) {
        const link = await page.locate(sel);
        if (!link) {
          failures.push({ code: "flow", text: `no ${sel} link to press` });
          return;
        }
        await page.press(link.x, link.y);
        await sleep(600);
      }
      await waitShown(page, ["settings", "setting-skills"]);
      details.state = await page.evaluate(`history.state`);
      const seen: string[] = [];
      const load = cdp.expect("Page.loadEventFired", { sessionId: page.session, timeoutMs: 20000 });
      await page.send("Page.reload", {});
      await load.promise;
      await page.metrics();
      const end = Date.now() + 5000;
      while (Date.now() < end) {
        const v = await page.evaluate<string>(ROWS).catch(() => "[null,null]");
        if (seen[seen.length - 1] !== v) seen.push(v);
        await sleep(25);
      }
      details.seen = seen;
      const last = JSON.parse(seen[seen.length - 1] ?? "[null,null]") as (string | null)[];
      if (seen.some((v) => v.includes(START))) failures.push({ code: "flow", text: `a row said "${START}" while a chat runs: ${clipList(seen, 4)}` });
      if (last.some((v) => !v || v.endsWith("...") || v.includes(START))) failures.push({ code: "flow", text: `the rows end as ${JSON.stringify(last)}, not with a value` });
      quietFindings(wire, since, await recorder(page), failures);
      issueFindings(page.takeIssues(), failures);
      shot = shotName(scene, "settings-facts", vp, "dark");
      await page.screenshot(shot).catch(() => {});
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = "Settings from a sleeping chat, reloaded: a quiet wait, then the live chat's facts; never Start a chat";
  return finish({ kind: "flow", name: "settings-facts", route: "settingsSection", scene, size: sizeTag(vp), theme: "dark", path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/** Row 97: what Settings shows in a section: its rows' text, its kept lines, whether it says Start a chat. */
const KEPT_STATE = (section: string) => `JSON.stringify((() => {
  const sec = document.querySelector('[data-testid="settings-${section}"]');
  if (!sec) return null;
  const lines = [...sec.querySelectorAll('[data-testid="settings-kept"]')].filter((e) => e.getClientRects().length);
  return {
    text: sec.textContent.replace(/\\s+/g, " ").trim(),
    kept: lines.map((e) => e.textContent.trim()),
    dim: lines.map((e) => getComputedStyle(e).color),
    rows: [...sec.querySelectorAll(".set-row")].length,
    scrollWidth: document.documentElement.scrollWidth,
    clientWidth: document.documentElement.clientWidth,
  };
})())`;
interface KeptState {
  text: string;
  kept: string[];
  dim: string[];
  rows: number;
  scrollWidth: number;
  clientWidth: number;
}
const KEPT_LINE = "From the last chat, 3 h ago.";

/**
 * Row 97 at one size and theme, on the archived scene's seed, where no chat is live and the example project keeps what
 * its last chat reported 3 h ago (test/click/seed/write.ts): Settings > Claude Code shows the kept skills, plugin and
 * output style, Models the kept Fast mode, Account the kept provider; each of those sections has exactly one dim line,
 * "From the last chat, 3 h ago.", and none says "Start a chat to read it."; no sideways overflow, nothing mutating goes
 * out, and no chat's Claude Code starts. A screenshot of each section.
 */
async function settingsKeptFlow(t: Target, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  const START = "Start a chat to read it.";
  const want: Record<string, string[]> = { "claude-code": ["review-notes", "notes-tools 1.2.0", "Output style Explanatory"], models: ["Fast mode"], account: ["Provider Bedrock"] };
  let shot: string | undefined;
  try {
    await withPage(vp, theme, async (page, wire) => {
      const since = wire.mark();
      for (const section of ["claude-code", "models", "account"]) {
        await page.navigate(`${t.base}/settings/${section}`);
        await waitShown(page, ["settings", `settings-${section}`]);
        await sleep(400);
        const s = JSON.parse(await page.evaluate<string>(KEPT_STATE(section))) as KeptState | null;
        details[section] = s;
        if (!s) {
          fail(`Settings shows no ${section} section`, "shows");
          continue;
        }
        const bare = (x: string) => x.replace(/\s+/g, "");
        for (const w of want[section]!) if (!bare(s.text).includes(bare(w))) fail(`${section}: no "${w}" (the kept value): ${clip(s.text, 200)}`);
        if (s.text.includes(START)) fail(`${section} still says "${START}"`);
        if (s.kept.length !== 1 || s.kept[0] !== KEPT_LINE) fail(`${section}: its kept lines are ${JSON.stringify(s.kept)}, expected one "${KEPT_LINE}"`);
        if (s.scrollWidth > s.clientWidth) fail(`${section}: the page scrolls sideways (${s.scrollWidth} > ${s.clientWidth})`, "overflow");
        shot = shotName(t.scene, "settings-kept", vp, theme, section);
        await page.screenshot(shot);
      }
      stateFindings(await page.probe(), vp, failures);
      issueFindings(page.takeIssues(), failures);
      quietFindings(wire, since, await recorder(page), failures);
    });
    // No chat's Claude Code started for it (a start with a session: the model list's short read of row 81 has none).
    const starts = t.booted ? t.booted.trace().filter((l) => l.t === "start" && (l.args as string[]).some((a) => /^--(resume|session-id)/.test(a))).length : 0;
    details.chatStarts = starts;
    if (starts) fail(`Settings started ${starts} chat's Claude Code`);
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = `${vp.width}x${vp.height}${vp.touch ? " touch" : ""} ${theme}: no chat live; Claude Code, Models and Account show what the last chat reported, each with one "${KEPT_LINE}" line, no Start a chat; nothing sent, no Claude Code started`;
  return finish({ kind: "flow", name: "settings-kept", route: "settingsSection", scene: t.scene, size: sizeTag(vp), theme, path: "/settings/claude-code", failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * P1 (rows 118 (3), 119): the fake claude's three versions of the claude-minimum flow, one boot each: a stock build
 * below kitespan's minimum (2.1.296), a company's own build below it, and one above it.
 */
const CLAUDE_MINIMUM_RUNS = [
  { id: "stock", prints: "2.1.250 (Claude Code)", line: "Claude Code 2.1.250 runs here; kitespan supports 2.1.296 and later. Run claude update.", code: "claude update" },
  { id: "company", prints: "2.1.250-acme.2 (Acme Claude Code)", line: "Claude Code 2.1.250-acme.2 runs here; kitespan supports 2.1.296 and later. Update it the way your company provides it.", code: null },
  { id: "above", prints: "2.1.317 (Claude Code)", line: null, code: null },
] as const;
type ClaudeMinimumRun = (typeof CLAUDE_MINIMUM_RUNS)[number];
/** Above the minimum, Settings > Claude Code keeps the drift line (the SDK names 2.1.322). */
const CLAUDE_ABOVE_DRIFT = "Claude Code 2.1.317 runs here; this SDK was built for 2.1.322.";

/** The minimum's line in a screen (by its test id): its element, words, colour and code span; and Settings' drift line. */
const MINIMUM_STATE = (id: string) => `JSON.stringify((() => {
  const shown = (e) => e.getClientRects().length > 0;
  const lines = [...document.querySelectorAll('[data-testid="${id}"]')].filter(shown);
  const el = lines[0];
  let line = null;
  if (el) {
    const probe = document.createElement("span");
    probe.style.color = "var(--warn)";
    el.appendChild(probe);
    const warn = getComputedStyle(probe).color;
    probe.remove();
    const code = el.querySelector("code");
    const cs = code ? getComputedStyle(code) : null;
    const r = el.getBoundingClientRect();
    line = {
      tag: el.tagName.toLowerCase(),
      cls: el.className,
      role: el.getAttribute("role"),
      text: el.textContent.replace(/\\s+/g, " ").trim(),
      color: getComputedStyle(el).color,
      warn,
      code: code && cs ? { text: code.textContent, select: cs.userSelect || cs.webkitUserSelect, font: cs.fontFamily, color: cs.color } : null,
      left: Math.round(r.left),
      right: Math.round(r.right),
      height: Math.round(r.height),
    };
  }
  const drift = [...document.querySelectorAll('[data-testid="setting-claude"] .set-drift')].filter(shown).map((e) => e.textContent.trim());
  return { count: lines.length, line, drift, path: location.pathname, scrollWidth: document.documentElement.scrollWidth, clientWidth: document.documentElement.clientWidth };
})())`;
interface MinimumState {
  count: number;
  line: { tag: string; cls: string; role: string | null; text: string; color: string; warn: string; code: { text: string; select: string; font: string; color: string } | null; left: number; right: number; height: number } | null;
  drift: string[];
  path: string;
  scrollWidth: number;
  clientWidth: number;
}

/**
 * P1, the minimum Claude Code version's line (rows 118 (3), 119), on the archived scene's seed (no warm-up), with the
 * fake claude reporting `run`'s version: Settings > Claude Code shows the one line in the drift line's place (a span in
 * the row line's look, the look's --warn colour) and Home's new-chat form under its box (a note in the form's under-box
 * look); a stock build's `claude update` is a code span that selects whole (on the laptop one click selects exactly
 * the command), a company's build gets the company's way with no command; above the minimum neither line shows and
 * Settings keeps the drift line. No sideways overflow, nothing mutating goes out, no chat's Claude Code starts. A
 * screenshot of each screen.
 */
async function claudeMinimumFlow(t: Target, run: ClaudeMinimumRun, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = { run: run.id, prints: run.prints };
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  let shot: string | undefined;
  const checkLine = (where: string, s: MinimumState, want: { tag: string; cls: string; role: string | null }) => {
    if (s.scrollWidth > s.clientWidth) fail(`${where}: the page scrolls sideways (${s.scrollWidth} > ${s.clientWidth})`, "overflow");
    if (run.line === null) {
      if (s.count) fail(`${where}: the minimum's line shows for ${run.prints}: "${s.line?.text ?? ""}"`);
      return;
    }
    const l = s.line;
    if (s.count !== 1 || !l) return fail(`${where}: ${s.count} minimum lines for ${run.prints}, expected one`, "shows");
    if (l.text !== run.line) fail(`${where}: the line reads "${l.text}", expected "${run.line}"`);
    if (l.tag !== want.tag || l.cls !== want.cls || l.role !== want.role) fail(`${where}: the line is ${l.tag}.${l.cls} (role ${l.role}), expected ${want.tag}.${want.cls} (role ${want.role})`, "layout");
    if (l.color !== l.warn) fail(`${where}: the line's colour ${l.color} is not the look's --warn (${l.warn})`, "look");
    if (run.code) {
      if (!l.code || l.code.text !== run.code) fail(`${where}: no code span "${run.code}" in the line`);
      else if (l.code.select !== "all") fail(`${where}: the code span's user-select is ${l.code.select}, not all`, "look");
    } else if (l.code) fail(`${where}: a company's build gets a command (${l.code.text})`);
    if (l.left < 0 || l.right > s.clientWidth) fail(`${where}: the line runs past the edge (${l.left} to ${l.right} of ${s.clientWidth})`, "edge");
  };
  try {
    await withPage(vp, theme, async (page, wire) => {
      const since = wire.mark();
      await page.navigate(`${t.base}/settings/claude-code`);
      await waitShown(page, ["settings", "settings-claude-code", "setting-claude"]);
      await sleep(400);
      const set = JSON.parse(await page.evaluate<string>(MINIMUM_STATE("setting-claude-minimum"))) as MinimumState;
      details.settings = set;
      checkLine("Settings > Claude Code", set, { tag: "span", cls: "set-row-line", role: null });
      // One line per row: below the minimum the drift line goes; above it the drift line shows as before.
      if (run.line !== null && set.drift.length) fail(`Settings > Claude Code: the drift line shows beside the minimum's: ${set.drift.join(" | ")}`);
      if (run.line === null && (set.drift.length !== 1 || set.drift[0] !== CLAUDE_ABOVE_DRIFT)) fail(`Settings > Claude Code: the drift line is ${JSON.stringify(set.drift)}, expected "${CLAUDE_ABOVE_DRIFT}"`);
      if (set.path !== "/settings/claude-code") fail(`Settings > Claude Code: the URL became ${set.path}`, "url");
      shot = shotName(t.scene, "claude-minimum", vp, theme, `${run.id}-settings`);
      await page.screenshot(shot);
      // One click on the command selects exactly the command (the laptop; on touch the selection is the browser's).
      if (run.code && !vp.touch) {
        const at = await page.locate('[data-testid="setting-claude-minimum"] code');
        if (!at) fail("Settings > Claude Code: the command's code span is not there to click");
        else {
          if (at.covered) fail(`Settings > Claude Code: the command is covered by ${at.covered}`, "covered");
          await page.press(at.x, at.y);
          await sleep(150);
          const picked = await page.evaluate<string>("String(getSelection())");
          details.selected = picked;
          if (picked !== run.code) fail(`one click on the command selected "${picked}", not "${run.code}"`);
        }
      }
      stateFindings(await page.probe(), vp, failures, "Settings: ");

      await page.navigate(`${t.base}/`);
      await waitShown(page, ["confirm-start"]);
      await sleep(400);
      const home = JSON.parse(await page.evaluate<string>(MINIMUM_STATE("form-claude-minimum"))) as MinimumState;
      details.home = home;
      checkLine("Home", home, { tag: "p", cls: "cmp-ext", role: "note" });
      if (home.path !== "/") fail(`Home: the URL became ${home.path}`, "url");
      shot = shotName(t.scene, "claude-minimum", vp, theme, `${run.id}-home`);
      await page.screenshot(shot);
      stateFindings(await page.probe(), vp, failures, "Home: ");
      issueFindings(page.takeIssues(), failures);
      quietFindings(wire, since, await recorder(page), failures);
    });
    // No chat's Claude Code started for it (a start with a session; the model list's short read of row 81 has none).
    const starts = t.booted ? t.booted.trace().filter((l) => l.t === "start" && (l.args as string[]).some((a) => /^--(resume|session-id)/.test(a))).length : 0;
    details.chatStarts = starts;
    if (starts) fail(`the flow started ${starts} chat's Claude Code`);
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const said = run.line === null ? "no minimum line, the drift line in Settings" : `"${run.line}" in Settings and under the form's box`;
  const note = `claude --version ${run.prints}, ${vp.width}x${vp.height}${vp.touch ? " touch" : ""} ${theme}: ${said}; nothing sent, no Claude Code started`;
  return finish({ kind: "flow", name: "claude-minimum", route: "settingsSection", scene: t.scene, size: sizeTag(vp), theme, path: "/settings/claude-code", failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * Row 97 on the main seed, where the example chat runs (its warm-up turn): Settings opened from it shows its live
 * start facts and provider, which replace the kept ones (the seed keeps others, 3 h old): no kept line in Claude Code,
 * Models or Account, and the kept skill and provider do not show.
 */
async function settingsKeptLiveFlow(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  let shot: string | undefined;
  try {
    await withPage(vp, "dark", async (page, wire) => {
      await page.navigate(`${base}/c/${EX.chat}`);
      await waitShown(page, ["chat"]);
      const since = wire.mark();
      await reachSettings(page, vp);
      for (const sel of ['a[href="/settings"]', 'a[href="/settings/claude-code"]']) {
        const link = await page.locate(sel);
        if (!link) return fail(`no ${sel} link to press`);
        await page.press(link.x, link.y);
        await sleep(600);
      }
      for (const section of ["claude-code", "models", "account"]) {
        if (section !== "claude-code") {
          // The phone's section is a page of its own: Back to Settings' list first (v0.6 touch: 390).
          if (vp.name === "phone" && !(await page.locate(`a[href="/settings/${section}"]`))) {
            const back = await page.locate('[data-testid="topbar"] .scr-bar-back');
            if (back) {
              await page.press(back.x, back.y);
              await sleep(600);
            }
          }
          const link = await page.locate(`a[href="/settings/${section}"]`);
          if (!link) return fail(`no link to ${section}`);
          await page.press(link.x, link.y);
          await sleep(600);
        }
        // Until the live chat's facts come, the rows wait quietly ("..."); then its own.
        let s: KeptState | null = null;
        for (let i = 0; i < 40; i++) {
          s = JSON.parse(await page.evaluate<string>(KEPT_STATE(section))) as KeptState | null;
          if (s && !s.text.includes("...")) break;
          await sleep(100);
        }
        details[section] = s;
        if (!s) {
          fail(`Settings shows no ${section} section`, "shows");
          continue;
        }
        if (s.kept.length) fail(`${section}: a kept line shows while a chat is live: ${JSON.stringify(s.kept)}`);
        if (s.text.includes("review-notes") || s.text.includes("Bedrock")) fail(`${section}: the kept value shows while a chat is live: ${clip(s.text, 200)}`);
      }
      shot = shotName(scene, "settings-kept-live", vp, "dark");
      await page.screenshot(shot);
      issueFindings(page.takeIssues(), failures);
      quietFindings(wire, since, await recorder(page), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = `${vp.width}x${vp.height}: Settings from the live example chat shows its own facts and provider, no kept line; nothing sent`;
  return finish({ kind: "flow", name: "settings-kept-live", route: "settingsSection", scene, size: sizeTag(vp), theme: "dark", path: "/settings/claude-code", failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/** Row 77: the session preview's line while Show sessions open in another app is off and another app has the session. */
const HIDDEN_OPEN_LINE = "Another app has this session open now, and Show sessions open in another app is off in Settings, so it does not show here.";
/** Row 77: the session preview's line while Show sessions from other apps is off. */
const HIDDEN_ALL_LINE = "Show sessions from other apps is off in Settings, so this session does not show here.";

/** A stand-in process for "the terminal" (row 77's check): `sleep`, ended by its pid only while it is still that sleep. */
function standIn(): { pid: number; stop(): void } {
  const proc = Bun.spawn(["sleep", "300"], { stdin: "ignore", stdout: "ignore", stderr: "ignore" });
  return {
    pid: proc.pid,
    stop() {
      let cmd = "";
      try {
        cmd = readFileSync(`/proc/${proc.pid}/cmdline`, "utf8").split("\0")[0] ?? "";
      } catch {}
      if (proc.exitCode === null && cmd.endsWith("sleep")) proc.kill("SIGTERM");
    },
  };
}

/**
 * Row 77, Settings > Chats > Show sessions from other apps and Show sessions open in another app, at 1100 x 800 on the
 * main seed. A record in the seed's registry of running sessions (test/click/seed/running.ts) opens the notes
 * project's terminal session in "the terminal" (a `sleep` stands in for it). By default Home and the notes project's
 * page leave that session out, and its preview says in one line that Show sessions open in another app hides it, with
 * the setting's link; nothing mutating goes out. Then, in one document: the project's page, Settings > Chats, the
 * switch (one POST /api/settings), Done back to the project's page, whose list now shows the session marked "Open in
 * the terminal now", and its preview offers Continue in a copy. Then Show sessions from other apps, off, the same way:
 * Done back to the preview, which says the setting hides it, and Home and the example project show no From the
 * terminal. At the end the two settings are back at their defaults, and the record and its process are gone.
 */
async function sessionSettingsFlow(t: Target, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const base = t.base;
  const notes = IDS.projects.notes;
  const open = IDS.sessions.terminalNotes;
  const projectPath = `/p/${notes}`;
  const previewPath = `/p/${notes}/session/${open}`;
  const path = "/settings/chats";
  const rowOf = (project: string, session: string) => `a[href="/p/${project}/session/${session}"]`;
  const shownSel = (sel: string) => `(() => [...document.querySelectorAll(${JSON.stringify(sel)})].some((el) => el.getClientRects().length > 0))()`;
  const noticeText = `(() => { const el = document.querySelector('[data-testid="link-notice"]'); return el ? el.textContent.replace(/\\s+/g, " ").trim() : null; })()`;
  const noticeLink = `(() => { const a = document.querySelector('[data-testid="link-notice"] a'); return a ? a.getAttribute("href") : null; })()`;
  const finishIt = (shot?: string) =>
    finish({ kind: "flow", name: "session-settings", route: "setting", scene, size: sizeTag(vp), theme: "dark", path, failures, warnings, note: "the two session settings: the lists, the preview's line and its link, a switch and Done in one document", shot, ms: Date.now() - t0, details });
  if (!t.booted) {
    warnings.push({ code: "flow", text: "a --base run has no seed folder for the registry record, so this check did not run" });
    return finishIt();
  }
  let shot: string | undefined;
  const terminal = standIn();
  const record = writeRunningRecord(t.booted.seed.claudeConfig, { pid: terminal.pid, sessionId: open, entrypoint: "cli", status: "idle" });
  const save = (change: Record<string, unknown>) =>
    fetch(`${base}/api/settings`, { method: "POST", headers: { origin: base, "x-kitespan": "1", "content-type": "application/json" }, body: JSON.stringify(change) });
  try {
    if (!record) {
      warnings.push({ code: "flow", text: "the stand-in process's start time could not be read (no /proc), so this check did not run" });
      return finishIt();
    }
    // The server keeps one look at the registry for about 2 s (server/agents/claude/running.ts).
    await sleep(2_200);
    await withPage(vp, "dark", async (page, wire) => {
      /** Wait until an in-page condition holds; false when it did not within `ms`. */
      const until = async (expr: string, ms = 4000) => {
        const end = Date.now() + ms;
        while (Date.now() < end) {
          if (await page.evaluate<boolean>(expr).catch(() => false)) return true;
          await sleep(100);
        }
        return false;
      };
      const press = async (sel: string, what: string) => {
        const at = await page.locate(sel);
        if (!at) {
          failures.push({ code: "flow", text: `no ${what} to press (${sel}) at ${await page.evaluate<string>("location.pathname + location.search")}` });
          return false;
        }
        await page.press(at.x, at.y);
        await sleep(400);
        await page.settle();
        return true;
      };

      // 1. The defaults: the open session is left out of both lists, and its preview says why.
      const quiet = wire.mark();
      await page.navigate(base + "/");
      await waitShown(page, ["home"]);
      if (!(await until(shownSel(rowOf(EX.project, EX.session))))) failures.push({ code: "flow", text: "Home's From the terminal does not list the example session (a closed one)" });
      if (await page.evaluate<boolean>(shownSel(rowOf(notes, open)))) failures.push({ code: "flow", text: "Home lists the session that the terminal has open, while Show sessions open in another app is off" });
      await page.navigate(base + projectPath);
      await waitShown(page, ["project"]);
      await sleep(300);
      if (await page.evaluate<boolean>(shownSel(rowOf(notes, open)))) failures.push({ code: "flow", text: "the project's page lists the session that the terminal has open, while Show sessions open in another app is off" });
      await page.navigate(base + previewPath);
      await until(`!!document.querySelector('[data-testid="link-notice"]')`);
      details.hiddenOpen = { line: await page.evaluate<string | null>(noticeText), link: await page.evaluate<string | null>(noticeLink) };
      if ((details.hiddenOpen as { line: string | null }).line !== HIDDEN_OPEN_LINE) failures.push({ code: "flow", text: `the open session's preview says ${JSON.stringify((details.hiddenOpen as { line: string | null }).line)}, not "${HIDDEN_OPEN_LINE}"` });
      if ((details.hiddenOpen as { link: string | null }).link !== "/settings/chats/sessions-open-elsewhere") failures.push({ code: "flow", text: "the open session's preview line has no link to Show sessions open in another app" });
      quietFindings(wire, quiet, await recorder(page), failures, "before any click: ");
      issueFindings(page.takeIssues(), failures, "the defaults: ");

      // 2. In one document: Settings > Chats, the switch, Done; the project's list follows.
      await page.navigate(base + projectPath);
      await waitShown(page, ["project"]);
      await page.evaluate(`(() => { window.__kitespanSameDocument = "sessions"; return true; })()`);
      // v0.6 touch: with no sidebar (the phone, the tablet) Settings opens from the chat list, so Done goes back to the
      // list; there the flow opens the page it came from by its URL (back is the list's own entry), and the
      // same-document checks are the laptop's.
      const listed = vp.touch && vp.name !== "laptop";
      const toggle = async (key: string, label: string, back: string) => {
        if (!(await page.locate('a[href="/settings"]'))) await reachSettings(page, vp);
        if (!(await press('a[href="/settings"]', "Settings link"))) return false;
        if (!(await press('a[href="/settings/chats"]', "Chats section"))) return false;
        await waitShown(page, ["settings-chats", `setting-${key}`]);
        const since = wire.mark();
        if (!(await press(`[data-testid="setting-${key}"] input[role="switch"]`, `${label} switch`))) return false;
        const end = Date.now() + 4000;
        while (Date.now() < end && !wire.httpSince(since).some((h) => h.status !== null)) await sleep(50);
        const sent = wire.httpSince(since);
        details[`${key}Sent`] = sent.map(httpText);
        if (sent.length !== 1 || sent[0]!.method !== "POST" || sent[0]!.path !== "/api/settings" || sent[0]!.status !== 200) failures.push({ code: "click", text: `${label}'s switch sent ${clipList(sent.map(httpText)) || "nothing"}, not one POST /api/settings with 200` });
        if (acting(wire.framesSince(since)).length) failures.push({ code: "click", text: `${label}'s switch sent ${clipList(acting(wire.framesSince(since)).map(frameText))} on the socket` });
        // The phone's section is a page of its own with Back to Settings' list, where Done is (v0.6 touch: 390).
        if (vp.name === "phone" && !(await page.locate('[data-testid="settings-done"]')) && !(await press('[data-testid="topbar"] .scr-bar-back', "Back to Settings"))) return false;
        if (!(await press('[data-testid="settings-done"]', "Done"))) return false;
        if (listed) {
          const at = await page.evaluate<string>("location.pathname");
          // The phone's list is a page; the tablet's drawer lies over the page under it, which Done shows again (where the
          // flow came from, so not a check of the app's).
          details[`doneTo-${key}`] = at;
          if (at !== back) await page.navigate(base + back);
          await page.evaluate(`(() => { window.__kitespanSameDocument = "sessions"; return true; })()`);
        }
        return true;
      };
      if (await toggle("sessions-open-elsewhere", "Show sessions open in another app", projectPath)) {
        const at = await page.evaluate<{ url: string; same: boolean }>(`({ url: location.pathname, same: window.__kitespanSameDocument === "sessions" })`);
        details.afterOpenOn = at;
        if (!at.same || at.url !== projectPath) failures.push({ code: "flow", text: `Done went to ${at.url}${at.same ? "" : " in another document"}, not back to ${projectPath} in the same document` });
        if (!(await until(shownSel(rowOf(notes, open))))) failures.push({ code: "flow", text: "with Show sessions open in another app on, the project's page does not list the open session" });
        else {
          const mark = await page.evaluate<string | null>(`(() => { const a = document.querySelector(${JSON.stringify(rowOf(notes, open))}); const m = a && a.querySelector('[data-testid="session-open"]'); return m ? m.textContent.trim() : null; })()`);
          details.mark = mark;
          if (mark !== "Open in the terminal now") failures.push({ code: "flow", text: `the open session's row says ${JSON.stringify(mark)}, not "Open in the terminal now"` });
          await press(rowOf(notes, open), "the open session's row");
          await waitShown(page, ["session-preview", "session-open"]);
          const button = await page.evaluate<string | null>(`(() => { const b = document.querySelector('[data-testid="confirm-continue"]'); return b ? b.textContent.trim() : null; })()`);
          if (button !== "Continue in a copy") failures.push({ code: "flow", text: `the open session's preview offers ${JSON.stringify(button)}, not Continue in a copy` });
        }
      }

      // 3. Show sessions from other apps, off: Done back to the preview, which says the setting hides it; no lists.
      if (await toggle("sessions-from-other-apps", "Show sessions from other apps", previewPath)) {
        await until(`!!document.querySelector('[data-testid="link-notice"]')`);
        details.hiddenAll = { url: await page.evaluate<string>("location.pathname"), line: await page.evaluate<string | null>(noticeText), link: await page.evaluate<string | null>(noticeLink) };
        const h = details.hiddenAll as { url: string; line: string | null; link: string | null };
        if (h.url !== previewPath) warnings.push({ code: "flow", text: `Done went to ${h.url}, not back to the preview` });
        if (h.line !== HIDDEN_ALL_LINE) failures.push({ code: "flow", text: `with Show sessions from other apps off, the preview says ${JSON.stringify(h.line)}, not "${HIDDEN_ALL_LINE}"` });
        if (h.link !== "/settings/chats/sessions-from-other-apps") failures.push({ code: "flow", text: "the preview's line has no link to Show sessions from other apps" });
        shot = shotName(scene, "session-settings", vp, "dark");
        await page.screenshot(shot).catch(() => {});
        for (const [where, heading] of [["/", "scr-terminal-h"], [`/p/${EX.project}`, "scr-pterm-h"]] as const) {
          await page.navigate(base + where);
          await sleep(500);
          if (await page.evaluate<boolean>(`!!document.getElementById(${JSON.stringify(heading)})`)) failures.push({ code: "flow", text: `with Show sessions from other apps off, ${where} still shows From the terminal` });
        }
        // W19e: with no lists, the second switch is disabled; its row and its link stay.
        await page.navigate(base + "/settings/chats");
        await waitShown(page, ["settings-chats", "setting-sessions-open-elsewhere"]);
        const second = await page.evaluate<{ disabled: boolean | null; link: boolean }>(
          `(() => { const row = document.querySelector('[data-testid="setting-sessions-open-elsewhere"]'); const sw = row && row.querySelector('input[role="switch"]'); return { disabled: sw ? sw.disabled : null, link: !!(row && row.querySelector('a[href="/settings/chats/sessions-open-elsewhere"]')) }; })()`,
        );
        details.secondSwitch = second;
        if (second.disabled !== true) failures.push({ code: "flow", text: `with Show sessions from other apps off, Show sessions open in another app's switch is not disabled (${JSON.stringify(second)})` });
        if (!second.link) failures.push({ code: "flow", text: "with Show sessions from other apps off, Show sessions open in another app's row lost its link" });
      }
      issueFindings(page.takeIssues(), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  } finally {
    // The checks after this one see the defaults, and no session open elsewhere.
    const r = await save({ "chats.sessionsFromOtherApps": true, "chats.sessionsOpenElsewhere": false }).catch(() => null);
    if (!r || r.status !== 200) warnings.push({ code: "flow", text: `the two settings could not be put back to their defaults (${r?.status ?? "no answer"})` });
    removeRunningRecord(record);
    terminal.stop();
  }
  return finishIt(shot);
}

// ---------------------------------------------------------------------------------------------------------------
// Row 80 (FIX-W19f): the message box of a chat whose session another app has open

/** Row 78's line under a held box, in the terminal's words (web/composer/HeldLine.tsx heldLine). */
const HELD_TERMINAL_LINE = "This session is open in the terminal. You can send here again when it is closed there.";
// The held box runs at the owner's window size, WIDE_LAPTOP (1280 x 800, a fine pointer), below.

/** The composer of a held chat as the page draws it (row 80), and what shows over it. */
const HELD_BOX = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const box = [...document.querySelectorAll('[data-testid="composer"]')].find(shown);
  const q = (sel) => (box ? box.querySelector(sel) : null);
  const btn = (el) => (el ? { shown: shown(el), off: !!el.disabled } : null);
  const input = q('[data-testid="composer-input"]');
  const held = q('[data-testid="composer-held"]');
  const slab = q(".cmp-slab");
  return {
    path: location.pathname + location.search,
    mode: box ? box.getAttribute("data-mode") : null,
    field: input ? input.value : null,
    readOnly: input ? input.readOnly : null,
    disabled: input ? input.disabled : null,
    focused: !!input && document.activeElement === input,
    plus: btn(q('[data-testid="composer-plus"]')),
    at: btn(q('[data-testid="composer-at"]')),
    modeButton: btn(q('button[aria-label^="Permission mode"]')),
    model: btn(q('button[aria-label^="Model"]')),
    copy: btn(q('[data-testid="composer-copy"]')),
    send: btn([...(box ? box.querySelectorAll('[data-testid="composer-send"], [data-testid="confirm-send"], [data-testid="confirm-run"]') : [])].find(shown) || null),
    chips: box ? box.querySelectorAll('[data-testid="mention-chip"], .cmp-file-chip').length : 0,
    held: shown(held) ? held.textContent.replace(/\\s+/g, " ").trim() : null,
    lines: box ? [...box.querySelectorAll(".cmp-lines > *")].filter(shown).map((el) => el.textContent.replace(/\\s+/g, " ").trim()) : [],
    open: [...document.querySelectorAll('[data-testid="slash-menu"], [data-testid="mention-menu"], .menu, .sheet, [role="dialog"], [role="listbox"]')].filter(shown).map((el) => el.getAttribute("data-testid") || el.getAttribute("role") || el.className),
    expanded: box ? [...box.querySelectorAll('[aria-expanded="true"]')].filter(shown).length : 0,
    notices: [...document.querySelectorAll('[data-testid="link-notice"], [data-testid="external-link-line"]')].filter(shown).map((el) => el.textContent.replace(/\\s+/g, " ").trim()),
    halo: slab ? getComputedStyle(slab).boxShadow : null,
    rim: slab ? getComputedStyle(slab).borderTopColor : null,
    placeholder: input ? input.getAttribute("placeholder") : null,
  };
})())`;

interface HeldBox {
  path: string;
  mode: string | null;
  field: string | null;
  readOnly: boolean | null;
  disabled: boolean | null;
  focused: boolean;
  plus: { shown: boolean; off: boolean } | null;
  at: { shown: boolean; off: boolean } | null;
  modeButton: { shown: boolean; off: boolean } | null;
  model: { shown: boolean; off: boolean } | null;
  copy: { shown: boolean; off: boolean } | null;
  send: { shown: boolean; off: boolean } | null;
  chips: number;
  held: string | null;
  lines: string[];
  open: string[];
  expanded: number;
  notices: string[];
  halo: string | null;
  rim: string | null;
  placeholder: string | null;
}

/** A key with Ctrl and Shift (Cmd+Shift on macOS; headless Linux has Ctrl), as the composer's window keys read it. */
async function ctrlShift(page: Page, letter: string) {
  const up = letter.toUpperCase();
  const base = { key: up, code: `Key${up}`, windowsVirtualKeyCode: up.charCodeAt(0), nativeVirtualKeyCode: up.charCodeAt(0), modifiers: 2 | 8 };
  await page.send("Input.dispatchKeyEvent", { type: "rawKeyDown", ...base });
  await page.send("Input.dispatchKeyEvent", { type: "keyUp", ...base });
  await sleep(250);
}

/** A drag from outside the page that ends with a drop at (x, y): text, or a file of the disk (CDP Input.dispatchDragEvent). */
async function dropAt(page: Page, x: number, y: number, data: { items?: { mimeType: string; data: string }[]; files?: string[] }) {
  const drag = { items: data.items ?? [], files: data.files, dragOperationsMask: 1 };
  for (const type of ["dragEnter", "dragOver", "drop"] as const) await page.send("Input.dispatchDragEvent", { type, x, y, data: drag });
  await sleep(400);
}

/**
 * Row 80 at 1280 x 800 and at 390 x 844 (touch), on the main seed's "Summarize the server logs", whose draft the server
 * holds (seed/demo.ts HELD_DRAFT). A record in the seed's registry of running sessions (test/click/seed/running.ts)
 * opens the chat's session in "the terminal" (a `sleep` stands in for it), so the server holds the chat. Then, with the
 * chat open: the held line shows under the box; the field shows the draft, read-only (not disabled, not removed), with
 * no placeholder; +, @ (touch), the mode and model buttons are shown and off; Continue in a copy is on; no Send. Typed
 * text, a "/" or "@", Backspace at the start and Enter change nothing; a paste of a file uploads nothing, and neither
 * does a file that the file picker's input hands over while held (a picker opened before the hold); on the laptop
 * Shift+Tab reaches the field and the box shows the keyboard's focus; on the laptop a dropped text
 * and a dropped file change nothing, and Ctrl+Shift+M, I and E open no picker. Each composer route (send, bash, the /
 * menu, a command row, mention, add, model, effort, mode), opened on the held chat, keeps its URL and shows the draft
 * with the held line as the box's one line: nothing fills, nothing opens. Nothing mutating goes out. Then Continue in
 * a copy sends one continue_session frame with the fork, gets an ok ack and opens the copy (the second size opens the
 * same copy). Back on the held chat, the record and its process go: in the same document the line goes, the field
 * takes typing again with the draft as it was, Send is back and +, @ and the pickers are on.
 */
async function heldBoxFlow(t: Target, scene: SceneName | null, vp: Viewport, copies: string[]): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const base = t.base;
  const chat = IDS.chats.logs;
  const path = `/c/${chat}`;
  const finishIt = (shot?: string) =>
    finish({ kind: "flow", name: "held-box", route: "send", scene, size: sizeTag(vp), theme: "dark", path, failures, warnings, note: "a held chat's box: the draft read-only, the controls off, every composer link shows the held line only, Continue in a copy; all back when the hold ends", shot, ms: Date.now() - t0, details });
  if (!t.booted) {
    warnings.push({ code: "flow", text: "a --base run has no seed folder for the registry record, so this check did not run" });
    return finishIt();
  }
  let shot: string | undefined;
  const terminal = standIn();
  let record: string | null = writeRunningRecord(t.booted.seed.claudeConfig, { pid: terminal.pid, sessionId: IDS.sessions.logs, entrypoint: "cli", status: "idle" });
  const drops = mkdtempSync(join(tmpdir(), "ui-check-held-"));
  const dropped = join(drops, "held-drop.txt");
  writeFileSync(dropped, "a file dropped on a held chat\n");
  const release = () => {
    removeRunningRecord(record);
    record = null;
    terminal.stop();
  };
  try {
    if (!record) {
      warnings.push({ code: "flow", text: "the stand-in process's start time could not be read (no /proc), so this check did not run" });
      return finishIt();
    }
    await withPage(vp, "dark", async (page, wire) => {
      const fail = (text: string, code = "flow") => failures.push({ code, text });
      const until = async (expr: string, ms = 12_000) => {
        const end = Date.now() + ms;
        while (Date.now() < end) {
          if (await page.evaluate<boolean>(expr).catch(() => false)) return true;
          await sleep(150);
        }
        return false;
      };
      const read = async (label?: string): Promise<HeldBox> => {
        const s = JSON.parse(await page.evaluate<string>(HELD_BOX)) as HeldBox;
        if (label) details[label] = s;
        return s;
      };
      const heldShown = `!!document.querySelector('[data-testid="composer-held"]')`;
      const field = async () => page.locate('[data-testid="composer"] [data-testid="composer-input"]');
      /** The box as row 80 draws it while held; `when` names the step. */
      const expectHeld = (s: HeldBox, when: string) => {
        if (s.held !== HELD_TERMINAL_LINE) fail(`${when}, the line under the box is ${JSON.stringify(s.held)}, not "${HELD_TERMINAL_LINE}"`);
        if (s.lines.length !== 1) fail(`${when}, the box has ${s.lines.length} lines under it (${clipList(s.lines)}), not the held line alone`);
        if (s.notices.length) fail(`${when}, ${clipList(s.notices)} shows`);
        if (s.field !== HELD_DRAFT.text) fail(`${when}, the field holds ${JSON.stringify(s.field)}, not the draft ${JSON.stringify(HELD_DRAFT.text)}`);
        if (s.mode !== "chat") fail(`${when}, the box is in ${s.mode ?? "no"} mode, not the draft's chat mode`);
        if (s.readOnly !== true || s.disabled !== false) fail(`${when}, the field is ${s.readOnly ? "" : "not "}read-only and ${s.disabled ? "" : "not "}disabled (read-only and not disabled expected)`);
        const offs: [string, HeldBox["plus"]][] = [["+", s.plus], ["the mode button", s.modeButton], ["the model button", s.model]];
        if (vp.touch) offs.push(["@", s.at]);
        for (const [name, b] of offs) if (!b || !b.shown || !b.off) fail(`${when}, ${name} is ${!b || !b.shown ? "not shown" : "on"}, not shown and off`);
        if (!s.copy || !s.copy.shown || s.copy.off) fail(`${when}, Continue in a copy is ${!s.copy || !s.copy.shown ? "not shown" : "off"}`);
        if (s.send?.shown) fail(`${when}, Send or Run shows`);
        if (s.open.length || s.expanded) fail(`${when}, ${clipList(s.open) || `${s.expanded} control(s) marked open`} shows over the chat`);
        if (s.placeholder) fail(`${when}, the held field's placeholder reads ${JSON.stringify(s.placeholder)} (it invites typing)`);
      };
      const loud = (since: number, when: string) => {
        const m = mutating(wire.framesSince(since));
        const h = wire.httpSince(since);
        if (m.length || h.length) fail(`${when}: the page sent ${clipList([...m.map(frameText), ...h.map(httpText)])}`, "frames");
      };

      // 1. The hold: the chat's page shows the line once the server sees the record (a check about every 2 s). Then
      // the chat opens again, held from its first draw.
      await page.navigate(base + path);
      await waitShown(page, ["chat", "composer"]);
      if (!(await until(heldShown))) {
        fail("the chat was not held within 12 s of the registry record (no held line under the box)");
        return;
      }
      await page.navigate(base + path);
      await waitShown(page, ["chat", "composer"]);
      await until(heldShown, 4000);
      await page.settle();
      page.takeIssues();
      const start = wire.mark();
      const first = await read("held");
      expectHeld(first, "while held");
      if (first.focused) fail("the held field took the focus by itself");
      shot = shotName(scene, "held-box", vp, "dark", "held");
      await page.screenshot(shot).catch(() => {});

      // 2. No typing: text, "/" and "@", Backspace at the start, Enter.
      const at = await field();
      if (!at) fail("no message field to press");
      else {
        await page.press(at.x, at.y);
        await sleep(200);
        await insertSlow(page, " more");
        await insertSlow(page, "@");
        await insertSlow(page, "/");
        await page.evaluate(`(() => { const f = ${FIELD}; f.focus(); f.setSelectionRange(0, 0); })()`);
        await keyCode(page, "Backspace", 8);
        await page.key("Enter");
        await sleep(500);
        const typed = await read("typed");
        expectHeld(typed, "after typing, Backspace and Enter");
        details.focusRim = typed.halo;
      }
      // A paste of a file (a synthetic paste: headless Chrome has no clipboard): nothing uploads, no chip.
      const pasted = await page.evaluate<boolean>(`(() => {
        const f = ${FIELD};
        const dt = new DataTransfer();
        dt.items.add(new File(["pasted on a held chat"], "held-paste.txt", { type: "text/plain" }));
        f.dispatchEvent(new ClipboardEvent("paste", { clipboardData: dt, bubbles: true, cancelable: true }));
        return true;
      })()`).catch(() => false);
      if (!pasted) warnings.push({ code: "flow", text: "the paste could not be dispatched" });
      await sleep(800);
      const afterPaste = await read("pasted");
      if (afterPaste.chips !== first.chips) fail(`a pasted file added a chip to the held box (${first.chips} before, ${afterPaste.chips} after)`);
      // A file picker opened before the hold began hands its file over while held (the input's change): nothing uploads.
      const picked = await page.evaluate<boolean>(`(() => {
        const input = document.querySelector('[data-testid="composer-file-input"]');
        if (!input) return false;
        const dt = new DataTransfer();
        dt.items.add(new File(["picked on a held chat"], "held-pick.txt", { type: "text/plain" }));
        input.files = dt.files;
        input.dispatchEvent(new Event("change", { bubbles: true }));
        return true;
      })()`).catch(() => false);
      if (!picked) fail("no file input (composer-file-input) to hand a picked file to");
      await sleep(800);
      const afterPick = await read("picked");
      if (afterPick.chips !== first.chips) fail(`a file picked while held added a chip to the held box (${first.chips} before, ${afterPick.chips} after): the picker's change uploads`);
      // The keyboard reaches the read-only field (Shift+Tab back from Continue in a copy), and the box shows that it has
      // the focus: its rim or its halo differs from the unfocused box's.
      if (!vp.touch) {
        await page.evaluate(`(() => { if (document.activeElement) document.activeElement.blur(); return true; })()`);
        await sleep(400); // the rim's transition back
        const calm = await page.evaluate<{ rim: string; halo: string } | null>(`(() => { const s = document.querySelector('[data-testid="composer"] .cmp-slab'); return s ? { rim: getComputedStyle(s).borderTopColor, halo: getComputedStyle(s).boxShadow } : null; })()`);
        await page.evaluate(`(() => { const c = document.querySelector('[data-testid="composer-copy"]'); if (c) c.focus(); return true; })()`);
        let reached = false;
        for (let i = 0; i < 8 && !reached; i++) {
          const tab = { key: "Tab", code: "Tab", windowsVirtualKeyCode: 9, nativeVirtualKeyCode: 9, modifiers: 8 };
          await page.send("Input.dispatchKeyEvent", { type: "rawKeyDown", ...tab });
          await page.send("Input.dispatchKeyEvent", { type: "keyUp", ...tab });
          await sleep(150);
          reached = await page.evaluate<boolean>(`document.activeElement === ${FIELD}`);
        }
        await sleep(300); // the rim's transition
        const k = await read("keyboardFocus");
        details.keyboardFocus = { calm, focused: { rim: k.rim, halo: k.halo } };
        if (!reached) fail("Shift+Tab from Continue in a copy never reached the held field: it is no longer a Tab stop");
        else if (calm && k.rim === calm.rim && k.halo === calm.halo) fail("the held field has the keyboard's focus and the box shows no mark (its rim and halo are as unfocused)");
      }
      // On the laptop: a dropped text and a dropped file; and the three picker keys.
      if (!vp.touch) {
        const spot = await field();
        if (spot) {
          // A drop that nothing takes fires no drop event (a read-only field refuses text, the window's guard refuses a
          // file), so the drag's dragover tells that it was dispatched.
          await page.evaluate(`(() => { window.__heldDrags = 0; window.addEventListener("dragover", () => { window.__heldDrags++; }, true); return true; })()`);
          await dropAt(page, spot.x, spot.y, { items: [{ mimeType: "text/plain", data: "dropped text" }] });
          await dropAt(page, spot.x, spot.y, { files: [dropped] });
          await sleep(800);
          if (!(await page.evaluate<number>("window.__heldDrags || 0"))) warnings.push({ code: "flow", text: "the drags did not reach the page, so the drops were not checked" });
          const afterDrop = await read("dropped");
          if (afterDrop.field !== HELD_DRAFT.text) fail(`a dropped text changed the held field to ${JSON.stringify(afterDrop.field)}`);
          if (afterDrop.chips !== first.chips) fail(`a file dropped on the held field added a chip (web/chat/ChatScreen.tsx's drop zone stays on while the chat is held)`);
        }
        for (const letter of ["m", "i", "e"]) {
          await ctrlShift(page, letter);
          const s = await read();
          if (s.path !== path || s.open.length) fail(`Ctrl+Shift+${letter.toUpperCase()} on the held chat went to ${s.path}${s.open.length ? ` and opened ${clipList(s.open)}` : ""}`);
        }
      }
      quietFindings(wire, start, await recorder(page), failures, "while held: ");
      issueFindings(page.takeIssues(), failures, "while held: ");
      // The box as the hold leaves it (a drop zone that took a file shows here once, not again at the end).
      const chipsHeld = (await read()).chips;

      // 3. The composer's routes on the held chat: each keeps its URL and shows the held line only.
      const routes: [string, string][] = [
        ["send", `${path}/send?text=${encodeURIComponent("Run the tests again")}`],
        ["bash", `${path}/bash?cmd=${encodeURIComponent("git status")}`],
        ["slashMenu", `${path}/slash`],
        ["slash", `${path}/slash/compact?args=${encodeURIComponent("keep the test plan")}`],
        ["mention", `${path}/mention?q=upl`],
        ["add", `${path}/add`],
        ["model", `${path}/model?pick=${encodeURIComponent(EX.model)}`],
        ["effort", `${path}/effort?pick=high`],
        ["mode", `${path}/mode?pick=acceptEdits`],
      ];
      const routeMark = wire.mark();
      const seen: Record<string, HeldBox> = {};
      for (const [name, url] of routes) {
        await page.navigate(base + url);
        await waitShown(page, ["chat", "composer"]);
        await until(heldShown, 4000);
        await sleep(300);
        const s = await read();
        seen[name] = s;
        if (s.path !== url) fail(`${name}: the link went to ${s.path}, not ${url}`);
        expectHeld(s, `on ${name}'s link`);
      }
      details.routes = Object.fromEntries(Object.entries(seen).map(([k, s]) => [k, { path: s.path, field: s.field, lines: s.lines, open: s.open, notices: s.notices }]));
      loud(routeMark, "on the composer's links to the held chat");
      issueFindings(page.takeIssues(), failures, "the links: ");

      // 4. Continue in a copy: one continue_session with the fork, an ok ack, and the copy opens (the same copy at the
      // second size).
      await page.navigate(base + path);
      await waitShown(page, ["chat", "composer"]);
      await until(heldShown, 4000);
      const copyAt = await page.locate('[data-testid="composer-copy"]');
      if (!copyAt) fail("no Continue in a copy to press");
      else {
        const since = wire.mark();
        await page.press(copyAt.x, copyAt.y);
        await waitSent(wire, since);
        const sent = acting(wire.framesSince(since));
        details.copySent = sent.map((f) => ({ t: f.t, fork: f.frame.fork, session: f.frame.session }));
        const one = sent.length === 1 && sent[0]!.t === "continue_session" && sent[0]!.frame.fork === true && sent[0]!.frame.session === IDS.sessions.logs ? sent[0]! : null;
        if (!one) fail(`Continue in a copy sent ${clipList(sent.map(frameText)) || "nothing"}, not one continue_session with the fork for the chat's session`, "click");
        else {
          const ack = await waitAck(wire, one.rid!);
          if (!ack?.ok) fail(`Continue in a copy got ${ack ? `a refusal (${ack.code})` : "no ack"}`, "click");
        }
        const opened = await until(`location.pathname !== ${JSON.stringify(path)} && /^\\/c\\/[a-z2-7]{20}$/.test(location.pathname)`, 6000);
        const copy = (await page.evaluate<string>("location.pathname")).slice(3);
        details.copy = copy;
        if (!opened) fail(`Continue in a copy did not open another chat (at ${copy})`);
        else {
          await waitShown(page, ["chat", "composer"]);
          const s = await read("copyBox");
          if (s.held || !s.send?.shown || s.readOnly) fail(`the copy's box is not a usable box (${s.held ? "the held line shows" : !s.send?.shown ? "no Send" : "read-only"})`);
          if (copies.length && copies[0] !== copy) fail(`this size's Continue in a copy opened ${copy}, the first size's ${copies[0]}: two copies`);
          copies.push(copy);
        }
      }

      // 5. The hold ends while the held chat is open: in the same document, everything comes back with the draft.
      await page.navigate(base + path);
      await waitShown(page, ["chat", "composer"]);
      await until(heldShown, 4000);
      await page.evaluate(`(() => { window.__kitespanSameDocument = "held"; return true; })()`);
      const endMark = wire.mark();
      release();
      if (!(await until(`!document.querySelector('[data-testid="composer-held"]')`))) fail("the held line stayed 12 s after the other app's record and process went");
      await page.settle();
      const back = await read("released");
      details.sameDocument = await page.evaluate<boolean>(`window.__kitespanSameDocument === "held"`);
      if (!details.sameDocument) fail("the page reloaded when the hold ended");
      if (back.field !== HELD_DRAFT.text) fail(`after the hold, the field holds ${JSON.stringify(back.field)}, not the draft as it was`);
      if (back.readOnly !== false || back.disabled) fail("after the hold, the field still takes no typing");
      if (back.chips !== chipsHeld) fail(`after the hold, the box has ${back.chips} chips, ${chipsHeld} while held`);
      if (!back.send?.shown || back.send.off) fail(`after the hold, Send is ${back.send?.shown ? "off" : "not back"}`);
      if (back.copy?.shown) fail("after the hold, Continue in a copy still shows");
      const ons: [string, HeldBox["plus"]][] = [["+", back.plus], ["the mode button", back.modeButton], ["the model button", back.model]];
      if (vp.touch) ons.push(["@", back.at]);
      for (const [name, b] of ons) if (!b || !b.shown || b.off) fail(`after the hold, ${name} is ${!b || !b.shown ? "not shown" : "still off"}`);
      if (back.lines.length) fail(`after the hold, ${clipList(back.lines)} shows under the box`);
      loud(endMark, "when the hold ended");
      const shotBack = shotName(scene, "held-box", vp, "dark", "released");
      await page.screenshot(shotBack).catch(() => {});
      issueFindings(page.takeIssues(), failures, "after the hold: ");
      // A file that a drop zone took while held (a failure above) leaves the box as seeded for the next size and flow.
      if (back.chips > first.chips) {
        await page.evaluate(`document.querySelectorAll('[data-testid="composer"] [data-testid="attach-remove"]').forEach((b) => b.click())`);
        await sleep(800);
      }
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  } finally {
    release();
    rmSync(dropped, { force: true });
    rmdirSync(drops);
  }
  return finishIt(shot);
}

/** The fake claude's chat processes from its trace (a `--version` probe is not one), and which of them are alive. */
function claudeProcesses(b: Booted): { started: number; alive: number[] } {
  const starts = b.trace().filter((l) => l.t === "start" && Array.isArray(l.args) && !(l.args as string[]).includes("--version"));
  const alive = starts
    .map((l) => Number(l.pid))
    .filter((pid) => {
      try {
        return readFileSync(`/proc/${pid}/cmdline`, "utf8").includes("fake-claude");
      } catch {
        return false;
      }
    });
  return { started: starts.length, alive };
}

/**
 * D49 and 8.3 check 26: page A (the laptop) and page B (the phone, touch), each in a browser context of its own, on
 * the one chat. Text typed in A's message box is saved as one draft frame; B, opened and then reloaded, shows that
 * text in its box and sends nothing; and the one claude process of the chat serves both pages.
 */
async function twoPagesFlow(t: Target, scene: SceneName | null): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const chatPath = `/c/${EX.chat}`;
  const text = `Typed on page A, read on page B ${Date.now().toString(36)}`;
  const laptop = VIEWPORTS.find((v) => v.name === "laptop")!;
  const phone = VIEWPORTS.find((v) => v.name === "phone")!;
  const fieldValue = (page: Page) => page.evaluate<string | null>(`(() => { const f = document.querySelector('[data-testid="composer-input"]'); return f ? f.value : null; })()`);
  let shot: string | undefined;
  const before = t.booted ? claudeProcesses(t.booted) : null;
  details.claudeBefore = before;
  if (!t.booted) warnings.push({ code: "flow", text: "with --base the claude processes cannot be counted" });
  try {
    await withPage(laptop, "dark", async (a, wireA) => {
      await a.navigate(t.base + chatPath);
      await waitShown(a, ["chat", "composer"]);
      a.takeIssues();
      const sinceA = wireA.mark();
      const field = await a.locate('[data-testid="composer-input"]');
      if (!field) {
        failures.push({ code: "flow", text: "page A shows no message box (composer-input)" });
        return;
      }
      await a.press(field.x, field.y);
      await a.send("Input.insertText", { text });
      await sleep(900); // the 250 ms save, with room
      const drafts = wireA.framesSince(sinceA).filter((f) => f.t === "draft");
      details.draftsA = drafts.map((f) => f.frame);
      if (!drafts.some((f) => f.frame.text === text)) failures.push({ code: "flow", text: `page A sent no draft frame with the typed text (${drafts.length} draft frames)` });
      const actingA = acting(wireA.framesSince(sinceA));
      if (actingA.length) failures.push({ code: "click", text: `typing on page A sent ${clipList(actingA.map(frameText))}` });
      const recA = await recorder(a);
      details.recorderA = recA;
      if (!recA || recA.some((x) => x !== "draft")) failures.push({ code: "click", text: `page A recorded ${recA ? clipList(recA) : "nothing"}; expected its draft only` });
      issueFindings(a.takeIssues(), failures, "page A: ");

      await withPage(phone, "light", async (b, wireB) => {
        await b.navigate(t.base + chatPath);
        await waitShown(b, ["chat", "composer"]);
        await b.reload();
        await waitShown(b, ["chat", "composer"]);
        await sleep(500);
        const got = await fieldValue(b);
        details.fieldB = got;
        if (got !== text) failures.push({ code: "flow", text: `after its reload page B's message box holds ${JSON.stringify(got)}, not page A's text` });
        const m = mutating(wireB.framesSince(0));
        if (m.length) failures.push({ code: "frames", text: `page B sent ${clipList(m.map(frameText))} with no click` });
        const recB = await recorder(b);
        if (recB && recB.length) failures.push({ code: "frames", text: `page B recorded ${clipList(recB)} with no click` });
        issueFindings(b.takeIssues(), failures, "page B: ");
        shot = shotName(scene, "two-pages", phone, "light", "page-b");
        await b.screenshot(shot).catch(() => {});
      });
      const still = await fieldValue(a);
      if (still !== text) failures.push({ code: "flow", text: `page A's box changed to ${JSON.stringify(still)} while page B opened` });
      await a.screenshot(shotName(scene, "two-pages", laptop, "dark", "page-a")).catch(() => {});
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  if (t.booted && before) {
    const after = claudeProcesses(t.booted);
    details.claudeAfter = after;
    if (after.started !== before.started) failures.push({ code: "flow", text: `${after.started - before.started} claude process(es) started while the two pages were open` });
    if (after.alive.length !== 1) failures.push({ code: "flow", text: `${after.alive.length} claude processes are alive for the chat; expected one for both pages` });
  }
  const note = `page B showed page A's draft after its reload; one claude process (${before ? `${before.started} started in the seed` : "not counted"})`;
  return finish({ kind: "flow", name: "two-pages", route: "chat", scene, size: "laptop", theme: "dark", path: chatPath, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

// ---------------------------------------------------------------------------------------------------------------
// The phone's Terminal page (D38; DESIGN.md 6.10, 7.2 and 5.4)

/** Bad links to the pane: each shows its one 5.4 line (the chat, which shows it at other sizes, is hidden here). */
const SHELL_BAD_LINKS: [suffix: string, line: string][] = [
  ["?type=bogus", "Part of that link could not be read."],
  ["?view=bogus", "Part of that link could not be read."],
  ["/extra", "That link could not be read."],
];

/**
 * The Terminal pane as the phone's own page over the chat. Open in terminal's link (?type=resume) asks the server to
 * type the command once per history entry: one type_resume control frame on /ws/shell, then the line about the typed
 * command; a reload (a phone browser restoring its tab) asks nothing more, keeps the URL, and shows the line again
 * (5.5 item 2). The title bar names the folder by its name, not a cut path. A link with a bad value or a bad extra
 * segment shows exactly one 5.4 line under the title bar and types nothing. No mutating /ws frame and no record in
 * window.__kitespanFrames at any step: nothing here is a click.
 */
async function shellPageFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const shellPath = `/c/${EX.chat}/shell`;
  const open = `${shellPath}?type=resume`;
  let shot: string | undefined;
  try {
    await withPage(vp, theme, async (page, wire) => {
      // The pane's control frames on /ws/shell (JSON text), as the browser saw them go out; keys are binary, not read.
      const shellSockets = new Set<string>();
      const control: string[] = [];
      const off = cdp.on((e) => {
        if (e.sessionId !== page.session) return;
        const p = e.params ?? {};
        if (e.method === "Network.webSocketCreated") {
          try {
            if (new URL(p.url).pathname === WIRE.shellPath) shellSockets.add(p.requestId);
          } catch {}
        } else if (e.method === "Network.webSocketFrameSent" && shellSockets.has(p.requestId) && p.response?.opcode === 1) {
          try {
            control.push(String(JSON.parse(p.response.payloadData).t));
          } catch {
            control.push("(not JSON)");
          }
        }
      });
      const asked = () => control.filter((t) => t === "type_resume").length;
      const opens = () => control.filter((t) => t === "open").length;
      const noteShown = () => page.evaluate<boolean>(SHOWN_ANY('[data-testid="terminal-note"]'));
      const until = async (ok: () => boolean | Promise<boolean>, ms: number) => {
        const end = Date.now() + ms;
        while (Date.now() < end && !(await ok())) await sleep(100);
      };
      try {
        // Open in terminal's link: the server types the command once, and the pane says what it typed.
        await page.navigate(base + open);
        await waitShown(page, ["terminal-pane", "terminal"]);
        await until(async () => asked() > 0 && (await noteShown()), 8000);
        await sleep(500);
        const s1 = await page.probe();
        details.opened = { path: s1.path, control: [...control], notices: s1.notices };
        if (asked() !== 1) failures.push({ code: "flow", text: `the link asked the server to type the command ${asked()} times; expected once` });
        if (!(await noteShown())) failures.push({ code: "flow", text: "the line about the typed command (terminal-note) does not show" });
        const folder = await page.evaluate<string | null>(`(() => { const el = [...document.querySelectorAll('[data-testid="topbar"] .term-folder')].find((e) => e.getClientRects().length); return el ? el.textContent : null; })()`);
        details.folder = folder;
        if (folder === null) failures.push({ code: "shows", text: "the title bar does not name the folder" });
        else if (folder.includes("/") || folder.startsWith("…")) failures.push({ code: "shows", text: `the title bar shows a path, ${JSON.stringify(folder)}, not the folder's name` });
        if (s1.notices.length) failures.push({ code: "notice", text: `a 5.4 line shows: ${clipList(s1.notices)}` });
        stateFindings(s1, vp, failures);
        issueFindings(page.takeIssues(), failures);
        quietFindings(wire, 0, await recorder(page), failures);
        await page.screenshot(shotName(scene, "shell-page", vp, theme, "opened"));

        // A reload of the same entry is not a click: no second type_resume, the same URL, the same line.
        const mark = wire.mark();
        const [askedBefore, opensBefore] = [asked(), opens()];
        await page.reload();
        await waitShown(page, ["terminal-pane", "terminal"]);
        await until(() => opens() > opensBefore, 6000);
        await until(noteShown, 4000);
        await sleep(1500); // a type_resume goes out right after the shell's `opened`: give a late one time to show
        const s2 = await page.probe();
        details.reloaded = { path: s2.path, control: [...control], notices: s2.notices };
        if (opens() === opensBefore) warnings.push({ code: "flow", text: "after reload, the pane opened no /ws/shell socket in 6 s" });
        if (asked() !== askedBefore) failures.push({ code: "flow", text: `after reload, the page asked the server to type the command again (${asked() - askedBefore} type_resume); a reload is not a click` });
        if (!sameUrl(s2.path, open)) failures.push({ code: "url", text: `after reload, the URL became ${s2.path}` });
        if (!(await noteShown())) failures.push({ code: "reload", text: "after reload, the line about the typed command is gone (5.5 item 2: the same state comes back)" });
        stateFindings(s2, vp, failures, "after reload, ");
        issueFindings(page.takeIssues(), failures, "after reload, ");
        quietFindings(wire, mark, await recorder(page), failures, "after reload, ");

        // Bad links: one 5.4 line under the title bar, nothing typed.
        const bad: Record<string, unknown> = {};
        details.badLinks = bad;
        for (const [suffix, line] of SHELL_BAD_LINKS) {
          const at = wire.mark();
          const before = asked();
          await page.navigate(base + shellPath + suffix);
          await waitShown(page, ["terminal-pane", "link-notice"]);
          await sleep(800);
          const s = await page.probe();
          bad[suffix] = { path: s.path, notices: s.notices };
          const pre = `${suffix}: `;
          if (s.notices.length !== 1 || s.notices[0] !== line) failures.push({ code: "notice", text: `${pre}expected the one line "${line}", the page shows ${s.notices.length ? clipList(s.notices.map((n) => JSON.stringify(n))) : "none"}` });
          if (!s.ids.includes("terminal-pane")) failures.push({ code: "shows", text: `${pre}the Terminal page does not show` });
          if (asked() !== before) failures.push({ code: "flow", text: `${pre}the page asked the server to type the command` });
          stateFindings(s, vp, failures, pre);
          issueFindings(page.takeIssues(), failures, pre);
          quietFindings(wire, at, await recorder(page), failures, pre);
          if (suffix === SHELL_BAD_LINKS[0]![0]) {
            shot = shotName(scene, "shell-page", vp, theme, "bad-link");
            await page.screenshot(shot);
          }
        }
      } finally {
        off();
      }
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = "one type_resume for the link, none on the reload, the line back after it; the folder's name; one 5.4 line on each bad link; nothing sent";
  return finish({ kind: "flow", name: "shell-page", route: "shell", scene, size: sizeTag(vp), theme, path: open, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

// ---------------------------------------------------------------------------------------------------------------
// The on-screen keyboard (DESIGN.md 7.7, 7.8)

/**
 * A stand-in visualViewport, put in before the page loads: headless Chrome has no on-screen keyboard, so
 * window.__standInKeyboard(px) makes the visual viewport that much shorter than the layout viewport (0: down) and
 * fires its resize, as a phone or tablet does when its keyboard comes up. The page reads it as it reads the real one.
 */
const STAND_IN_KEYBOARD = `(() => {
  const real = window.visualViewport;
  const vv = new EventTarget();
  let height = null;
  Object.defineProperty(vv, "height", { get: () => (height === null ? (real ? real.height : innerHeight) : height) });
  Object.defineProperty(vv, "width", { get: () => innerWidth });
  Object.defineProperty(vv, "offsetTop", { get: () => 0 });
  Object.defineProperty(vv, "offsetLeft", { get: () => 0 });
  Object.defineProperty(vv, "pageTop", { get: () => scrollY });
  Object.defineProperty(vv, "scale", { get: () => 1 });
  Object.defineProperty(window, "visualViewport", { value: vv, configurable: true });
  window.__standInKeyboard = (px) => { height = px ? innerHeight - px : null; vv.dispatchEvent(new Event("resize")); };
})()`;

/** Where the parts that must clear the keyboard are, in CSS px from the top (null: not shown). */
const KEYBOARD_STATE = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const box = (sel, root) => { const el = [...(root || document).querySelectorAll(sel)].find(shown); if (!el) return null; const r = el.getBoundingClientRect(); return [Math.round(r.top), Math.round(r.bottom)]; };
  const sheet = [...document.querySelectorAll('[data-testid="dialog-rename"]')].find(shown);
  const at = document.activeElement;
  return {
    visual: Math.round(visualViewport.height),
    layout: innerHeight,
    focus: at ? (at.closest(".term-pane") ? "terminal" : at.closest('[data-testid="composer"]') ? "composer" : at.closest('[data-testid="dialog-rename"]') ? "rename" : at.tagName.toLowerCase()) : null,
    keys: box('[data-testid="terminal-keys"]'),
    composer: box('[data-testid="composer"] .cmp-slab') || box('[data-testid="composer"]'),
    riding: !!document.querySelector(".shell.term-riding"),
    sheet: sheet ? box('[data-testid="dialog-rename"]') : null,
    field: sheet ? box("input", sheet) : null,
    save: sheet ? box('button[type="submit"]', sheet) : null,
    corner: sheet ? (sheet.querySelector(".sheet-head .sheet-done") || {}).textContent || null : null,
  };
})())`;

interface KeyboardState {
  visual: number;
  layout: number;
  focus: string | null;
  keys: [number, number] | null;
  composer: [number, number] | null;
  riding: boolean;
  sheet: [number, number] | null;
  field: [number, number] | null;
  save: [number, number] | null;
  corner: string | null;
}

/**
 * The on-screen keyboard on a touch size, with the stand-in visualViewport (STAND_IN_KEYBOARD): a tap in the Terminal
 * pane and a keyboard 336 px (phone) or 400 px (tablet) high; the key bar's foot is at the keyboard's top, not under it
 * (7.7: a tablet with no hardware keyboard still has Esc, Tab, Ctrl and the arrows), and goes back to the page's foot
 * when the keyboard goes down. On the tablet a tap in the composer beside the pane leaves the shell as it is: the
 * composer rides on its own (7.8). On the phone the rename sheet's field and Save stay above the keyboard, with Cancel
 * at its top right. Opening and tapping send nothing.
 */
async function keyboardFlow(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const phone = vp.name === "phone";
  const kbPx = phone ? 336 : 400;
  const path = `/c/${EX.chat}/shell`;
  let shot: string | undefined;
  const above = (what: string, b: [number, number] | null, st: KeyboardState, step: string) => {
    if (!b) failures.push({ code: "shows", text: `${step}: ${what} does not show` });
    else if (b[1] > st.visual + 1) failures.push({ code: "keyboard", text: `${step}: ${what} ends at ${b[1]} px, under the keyboard that starts at ${st.visual} px` });
    else if (b[0] < 0) failures.push({ code: "keyboard", text: `${step}: ${what} starts above the screen (${b[0]} px)` });
  };
  try {
    await withPage(vp, "light", async (page, wire) => {
      await page.send("Page.addScriptToEvaluateOnNewDocument", { source: STAND_IN_KEYBOARD });
      const read = async () => JSON.parse(await page.evaluate<string>(KEYBOARD_STATE)) as KeyboardState;
      const keyboard = async (px: number) => {
        await page.evaluate(`window.__standInKeyboard(${px})`);
        await sleep(400);
        await page.settle();
      };
      const tap = async (sel: string) => {
        const at = await page.locate(sel);
        if (!at) return false;
        await page.press(at.x, at.y);
        await sleep(300);
        await page.settle();
        return true;
      };
      const since = wire.mark();
      await page.navigate(base + path);
      await waitShown(page, ["terminal-pane", "terminal", "terminal-keys"]);
      await sleep(500);

      // The Terminal pane has the focus: its key bar rides above the keyboard.
      if (!(await tap(".term-pane .xterm-screen"))) failures.push({ code: "shows", text: "the terminal does not show" });
      await keyboard(kbPx);
      const up = await read();
      details.terminalUp = up;
      if (up.focus !== "terminal") failures.push({ code: "flow", text: `a tap in the terminal put the focus on ${up.focus ?? "nothing"}` });
      above("the key bar", up.keys, up, "terminal, keyboard up");
      shot = shotName(scene, "keyboard", vp, "light", "terminal");
      await page.screenshot(shot);
      await keyboard(0);
      const down = await read();
      details.terminalDown = down;
      if (down.riding) failures.push({ code: "keyboard", text: "terminal, keyboard down: the shell still rides it" });
      // v0.6 touch (T-15): on the large tablet the Terminal over the chat ends 8 px above the composer's dock at rest, so
      // its key bar ends at the pane's foot, not at the page's.
      const foot = vp.name === "laptop" ? await page.evaluate<number | null>(`(() => { const p = document.querySelector('[data-testid="terminal-pane"]'); const a = p && p.closest("aside"); return a ? Math.round(a.getBoundingClientRect().bottom) : null; })()`) : null;
      const end = foot ?? down.layout;
      if (!down.keys || Math.abs(down.keys[1] - end) > 1) failures.push({ code: "keyboard", text: `terminal, keyboard down: the key bar ends at ${down.keys?.[1] ?? "nothing"}, not at ${foot !== null ? "the pane's" : "the page's"} foot (${end} px)` });

      if (!phone) {
        // The composer beside the pane has the focus: it rides on its own, and the shell stays as it is.
        if (!(await tap('[data-testid="composer"] [data-testid="composer-input"]'))) failures.push({ code: "shows", text: "the composer does not show beside the pane" });
        await keyboard(kbPx);
        const c = await read();
        details.composerUp = c;
        if (c.focus !== "composer") failures.push({ code: "flow", text: `a tap in the composer put the focus on ${c.focus ?? "nothing"}` });
        if (c.riding) failures.push({ code: "keyboard", text: "composer, keyboard up: the shell rides the keyboard too, so the composer's own ride is moved twice" });
        above("the composer", c.composer, c, "composer, keyboard up");
        await page.screenshot(shotName(scene, "keyboard", vp, "light", "composer"));
        await keyboard(0);
      } else {
        // The phone's rename sheet: its field has the focus as it opens; the field and Save stay above the keyboard.
        await page.navigate(`${base}/c/${EX.chat}/rename`);
        await waitShown(page, ["dialog-rename"]);
        await sleep(300);
        await keyboard(kbPx);
        const r = await read();
        details.renameUp = r;
        if (r.focus !== "rename") failures.push({ code: "flow", text: `the rename sheet opened with the focus on ${r.focus ?? "nothing"}, not its field` });
        above("the rename field", r.field, r, "rename, keyboard up");
        above("Save", r.save, r, "rename, keyboard up");
        if (r.corner?.trim() !== "Cancel") failures.push({ code: "shows", text: `the rename sheet's top right says ${JSON.stringify(r.corner)}, not Cancel` });
        await page.screenshot(shotName(scene, "keyboard", vp, "light", "rename"));
        await keyboard(0);
      }
      issueFindings(page.takeIssues(), failures);
      quietFindings(wire, since, await recorder(page), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = phone ? "the key bar and the rename sheet above a 336 px keyboard, back at the foot after it; nothing sent" : "the key bar above a 400 px keyboard while the pane has the focus; the composer beside it rides alone; nothing sent";
  return finish({ kind: "flow", name: "keyboard", route: "shell", scene, size: sizeTag(vp), theme: "light", path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/** Where a waiting card's field and its buttons are, in CSS px from the top (null: not shown). */
const CARD_KEYBOARD_STATE = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const box = (el) => { if (!shown(el)) return null; const r = el.getBoundingClientRect(); return [Math.round(r.top), Math.round(r.bottom)]; };
  const card = [...document.querySelectorAll('[data-testid="card-elicitation"]')].find(shown);
  const at = document.activeElement;
  return {
    visual: Math.round(visualViewport.height),
    layout: innerHeight,
    focus: at ? (card && card.contains(at) ? "card " + at.tagName.toLowerCase() : at.tagName.toLowerCase()) : null,
    field: card ? box(card.querySelector("input.field")) : null,
    submit: card ? box(card.querySelector('[data-testid="confirm-accept"]')) : null,
    decline: card ? box(card.querySelector('[data-testid="confirm-decline"]')) : null,
    cancel: card ? box(card.querySelector('[data-testid="confirm-cancel"]')) : null,
    riding: !!document.querySelector(".chat-dock.is-riding"),
  };
})())`;

interface CardKeyboardState {
  visual: number;
  layout: number;
  focus: string | null;
  field: [number, number] | null;
  submit: [number, number] | null;
  decline: [number, number] | null;
  cancel: [number, number] | null;
  riding: boolean;
}

/**
 * A waiting card's field and the on-screen keyboard (7.8; 7.2: the card takes the composer's place), with the stand-in
 * visualViewport (STAND_IN_KEYBOARD): a tap in the elicitation card's field and a keyboard 336 px (phone) or 400 px
 * (tablet) high; the field and the card's Submit, Decline and Cancel end above the keyboard, not under it, and the card
 * is back in its place once the keyboard goes down. The tap sends nothing.
 */
async function cardKeyboardFlow(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const kbPx = vp.name === "phone" ? 336 : 400;
  const path = `/c/${EX.chat}`;
  let shot: string | undefined;
  const above = (what: string, b: [number, number] | null, st: CardKeyboardState) => {
    if (!b) failures.push({ code: "shows", text: `keyboard up: ${what} does not show` });
    else if (b[1] > st.visual + 1) failures.push({ code: "keyboard", text: `keyboard up: ${what} ends at ${b[1]} px, under the keyboard that starts at ${st.visual} px` });
    else if (b[0] < 0) failures.push({ code: "keyboard", text: `keyboard up: ${what} starts above the screen (${b[0]} px)` });
  };
  try {
    await withPage(vp, "light", async (page, wire) => {
      await page.send("Page.addScriptToEvaluateOnNewDocument", { source: STAND_IN_KEYBOARD });
      const read = async () => JSON.parse(await page.evaluate<string>(CARD_KEYBOARD_STATE)) as CardKeyboardState;
      const keyboard = async (px: number) => {
        await page.evaluate(`window.__standInKeyboard(${px})`);
        await sleep(400);
        await page.settle();
      };
      const since = wire.mark();
      await page.navigate(base + path);
      await waitShown(page, ["card-elicitation"]);
      await sleep(500);
      const at = await page.locate('[data-testid="card-elicitation"] input.field');
      if (!at) failures.push({ code: "shows", text: "the elicitation card has no text field" });
      else {
        await page.press(at.x, at.y);
        await sleep(300);
        await page.settle();
        await keyboard(kbPx);
        const up = await read();
        details.up = up;
        if (up.focus !== "card input") failures.push({ code: "flow", text: `a tap in the card's field put the focus on ${up.focus ?? "nothing"}` });
        above("the field", up.field, up);
        above("Submit", up.submit, up);
        above("Decline", up.decline, up);
        above("Cancel", up.cancel, up);
        shot = shotName(scene, "card-keyboard", vp, "light");
        await page.screenshot(shot);
        await keyboard(0);
        const down = await read();
        details.down = down;
        if (down.riding) failures.push({ code: "keyboard", text: "keyboard down: the card still rides it" });
        if (!down.cancel || down.cancel[1] > down.layout) failures.push({ code: "keyboard", text: `keyboard down: the card's last button ends at ${down.cancel?.[1] ?? "nothing"}, past the page's foot (${down.layout} px)` });
      }
      issueFindings(page.takeIssues(), failures);
      quietFindings(wire, since, await recorder(page), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = `the card's field, Submit, Decline and Cancel above a ${kbPx} px keyboard, in place after it; nothing sent`;
  return finish({ kind: "flow", name: "card-keyboard", route: "elicitation", scene, size: sizeTag(vp), theme: "light", path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/** The pane bar, the docked pane's head and the session menu (in the page). */
const PANE_STATE = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const panel = [...document.querySelectorAll('[data-testid="side-panel"]')].find(shown);
  return {
    path: location.pathname,
    search: location.search,
    lit: [...document.querySelectorAll(".pane-bar-btn.on")].filter(shown).map((b) => (b.querySelector(".pane-bar-name") || b).textContent.trim()),
    headLinks: panel ? [...panel.querySelectorAll(".side-pane-head a[href]")].filter(shown).map((a) => a.getAttribute("href")) : null,
    backs: panel ? [...panel.querySelectorAll(".side-back")].filter(shown).length : null,
    close: panel ? [...panel.querySelectorAll(".side-pane-head button")].filter(shown).map((b) => b.getAttribute("aria-label")) : null,
    // U4: every shown side panel, since the docked pane may hold two (the Details half sits below the Files half).
    uploadsRow: panel ? [...document.querySelectorAll('[data-testid="side-panel"] [data-testid="side-uploads"]')].some(shown) : null,
    menu: [...document.querySelectorAll('[data-testid="session-menu"] a, [data-testid="session-menu"] button')].filter(shown).map((b) => b.textContent.trim()),
  };
})())`;

interface PaneState {
  path: string;
  search: string;
  lit: string[];
  headLinks: string[] | null;
  backs: number | null;
  close: string[] | null;
  uploadsRow: boolean | null;
  menu: string[];
}

/**
 * The pane bar's Files pane on a tablet (7.3, D51, M34): Files opens /c/<chat>/uploads with Files lit and only the
 * close button in the pane's head (no back link that would light another bar button); Details lists no Uploads row,
 * since the bar's Files button opens that list; and the session menu has no Details item beside the bar's Details
 * button (6.2, principle 0). U4 (DESIGN-U4 4.2 rule 3, 8): a tap on Details while Files shows opens Details below it
 * in the one docked pane (/c/<chat>/details?above=uploads), and both buttons light. The taps send nothing.
 */
async function filesPaneFlow(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const chat = `/c/${EX.chat}`;
  let shot: string | undefined;
  try {
    await withPage(vp, "light", async (page, wire) => {
      const read = async () => JSON.parse(await page.evaluate<string>(PANE_STATE)) as PaneState;
      const tap = async (sel: string) => {
        const at = await page.locate(sel);
        if (!at) return false;
        await page.press(at.x, at.y);
        await sleep(400);
        await page.settle();
        return true;
      };
      const since = wire.mark();
      await page.navigate(base + chat);
      await waitShown(page, ["conversation"]);
      await sleep(400);
      if (!(await tap('.pane-bar-btn[title="Files"]'))) failures.push({ code: "shows", text: "the pane bar has no Files button" });
      const files = await read();
      details.files = files;
      if (files.path !== `${chat}/uploads`) failures.push({ code: "flow", text: `Files opened ${files.path}, not the chat's uploads` });
      if (files.lit.join() !== "Files") failures.push({ code: "flow", text: `with the Files pane open the lit bar buttons are ${JSON.stringify(files.lit)}` });
      if (files.headLinks === null) failures.push({ code: "shows", text: "the Files pane does not show" });
      else if (files.headLinks.length || files.backs) failures.push({ code: "flow", text: `the Files pane's head has a link of its own (${clipList(files.headLinks)}); a tap there would light another bar button` });
      if (files.close && files.close.join() !== "Close Uploads") failures.push({ code: "flow", text: `the Files pane's head holds ${JSON.stringify(files.close)}; expected its close button only` });
      shot = shotName(scene, "files-pane", vp, "light");
      await page.screenshot(shot);
      if (!(await tap('.pane-bar-btn[title="Details"]'))) failures.push({ code: "shows", text: "the pane bar has no Details button" });
      const det = await read();
      details.details = det;
      // v0.6 touch: the large tablet in portrait shows one view over the chat, so Details takes Files' place.
      const one = vp.name === "laptop";
      if (det.path !== `${chat}/details` || (one ? det.search !== "" : new URLSearchParams(det.search).get("above") !== "uploads")) failures.push({ code: "flow", text: `Details with Files open gave ${det.path}${det.search}, not Details ${one ? "alone over the chat" : "below Files"}` });
      if (det.lit.join() !== (one ? "Details" : "Details,Files")) failures.push({ code: "flow", text: `with Details ${one ? "over the chat" : "below Files"} the lit bar buttons are ${JSON.stringify(det.lit)}` });
      if (det.uploadsRow) failures.push({ code: "flow", text: "Details lists an Uploads row beside the pane bar's Files button" });
      if (!(await tap('[aria-label="Session menu"]'))) failures.push({ code: "shows", text: "the title bar has no session menu" });
      const menu = await read();
      details.menu = menu.menu;
      if (!menu.menu.length) failures.push({ code: "shows", text: "the session menu does not open" });
      else if (menu.menu.includes("Details")) failures.push({ code: "flow", text: "the session menu repeats the pane bar's Details" });
      await page.key("Escape");
      await sleep(200);
      issueFindings(page.takeIssues(), failures);
      quietFindings(wire, since, await recorder(page), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = "Files lit with only its close button; Details below Files with both lit; no Uploads row in Details and no Details in the session menu; nothing sent";
  return finish({ kind: "flow", name: "files-pane", route: "uploads", scene, size: sizeTag(vp), theme: "light", path: `${chat}/uploads`, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

// ---------------------------------------------------------------------------------------------------------------
// Row 82 (W19f): the panes' width handles and the sidebar's Hide sidebar and Show sidebar

/**
 * A laptop window wider than the default one, the owner's 1280 x 800: the sidebar's handle reaches its own maximum
 * (480 px) there. The held box's flow (row 80) runs at it too.
 */
const WIDE_LAPTOP: Viewport = { name: "laptop", width: 1280, height: 800, scale: 1, mobile: false, touch: false };
/**
 * DESIGN-T1 3.1: the large tablet in portrait with Hide sidebar (the device's view, seeded before the page's scripts):
 * the column form, with the side column and its split beside a 604 px title band.
 */
const LARGE_COL: Viewport = { ...VIEWPORTS.find((v) => v.label === "large")!, tag: "large-col", preload: `localStorage.setItem("kitespan.view", JSON.stringify({ sidebarHidden: true }))` };
/** A large touch tablet in landscape (the laptop's size class with touch): the sidebar docks beside the chat there. */
const TOUCH_LAPTOP: Viewport = { name: "laptop", width: 1366, height: 1024, scale: 2, mobile: true, touch: true };
/** The sidebar's narrowest and default widths and the side pane's (web/layout/panes.ts; the script reads no web code). */
const PANE_SIDEBAR = { min: 240, def: 248, max: 480 };
const PANE_SIDE = { min: 280, def: 320, max: 720 };
/**
 * v0.6 touch (DESIGN-T1 T-30, G-48; web/layout/panes.ts, read as its rule): the medium pane's default (40% of the window
 * under 800 px, else 320) and its handle's reach, or null where the pane cannot change width (under 702 px). A drag
 * keeps the chat 420 px, so the pane reaches the window less the pane bar and 420 px, or its default if that is more.
 */
const mediumHandle = (w: number): { def: number; max: number } | null => {
  const def = w < 800 ? Math.round(w * 0.4) : PANE_SIDE.def;
  const max = Math.max(def, w - 56 - 420);
  return max > PANE_SIDE.min ? { def, max } : null;
};

interface PaneHandleState {
  id: string | null;
  now: number;
  min: number;
  max: number;
  x: number;
  y: number;
  focused: boolean;
  controls: string | null;
}
interface PaneBox {
  left: number;
  right: number;
  width: number;
}
interface PanesState {
  path: string;
  form: string | null;
  handles: PaneHandleState[];
  sidebar: PaneBox | null;
  side: PaneBox | null;
  main: PaneBox | null;
  composer: PaneBox | null;
  bar: PaneBox | null;
  hide: boolean;
  show: boolean;
  focus: string | null;
  view: { sidebarHidden?: boolean; widths?: Record<string, number> } | null;
  resizing: boolean;
  /** The conversation is scrolled to its end. */
  atEnd: boolean | null;
  /** The message box's field has the focus. */
  fieldFocused: boolean;
  scrollWidth: number;
  clientWidth: number;
  /** The controls (a link, a button, a field) that a handle lies over, as "<handle> over <control>". */
  covered: string[];
  /** Each shown handle's grip: shown (at least 3 x 24 px, painted) or not. */
  grips: { id: string | null; shown: boolean }[];
  /** The sidebar's filter segments whose label takes two lines, and the parts of its head that run into each other. */
  fit: { wraps: string[]; overlap: string[] } | null;
  /** Show sidebar's visible text (its name on touch), or null while it is not shown. */
  showText: string | null;
  /** The length of the page's text selection (a drag selects none). */
  selected: number;
}

/** The panes as the page shows them: the handles, the columns' boxes, Hide and Show, the stored choice, the URL. */
const PANES_STATE = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && !el.closest('[hidden="until-found"]');
  const box = (el) => {
    if (!shown(el)) return null;
    const r = el.getBoundingClientRect();
    return { left: Math.round(r.left), right: Math.round(r.right), width: Math.round(r.width) };
  };
  const shell = document.querySelector(".shell");
  const handles = [...document.querySelectorAll('.pane-handle[role="separator"]')].filter(shown).map((h) => {
    const r = h.getBoundingClientRect();
    return {
      id: h.getAttribute("data-testid"),
      now: Number(h.getAttribute("aria-valuenow")),
      min: Number(h.getAttribute("aria-valuemin")),
      max: Number(h.getAttribute("aria-valuemax")),
      x: r.left + r.width / 2,
      y: r.top + r.height / 2,
      focused: document.activeElement === h,
      controls: h.getAttribute("aria-controls"),
    };
  });
  let view = null;
  try { view = JSON.parse(localStorage.getItem("kitespan.view") || "null"); } catch {}
  const at = document.activeElement;
  return {
    path: location.pathname + location.search,
    form: shell ? shell.getAttribute("data-sidebar") : null,
    handles,
    sidebar: box(document.getElementById("fd-sidebar")),
    side: box(document.getElementById("fd-side")),
    main: box(document.querySelector(".shell > .main-col")),
    composer: box([...document.querySelectorAll('[data-testid="composer"]')].find(shown) || null),
    bar: box(document.querySelector(".pane-bar")),
    hide: shown(document.querySelector('[data-testid="sidebar-hide"]')),
    show: shown(document.querySelector('[data-testid="sidebar-show"]')),
    focus: at && at !== document.body ? at.getAttribute("data-testid") || at.tagName.toLowerCase() : null,
    view,
    resizing: !!shell && shell.hasAttribute("data-resizing"),
    atEnd: (() => {
      const el = [...document.querySelectorAll(".chat-scroll")].find(shown);
      return el ? el.scrollHeight - el.scrollTop - el.clientHeight < 3 : null;
    })(),
    fieldFocused: !!at && !!at.closest && !!at.closest('[data-testid="composer-input"]'),
    scrollWidth: document.documentElement.scrollWidth,
    clientWidth: document.documentElement.clientWidth,
    covered: (() => {
      const control = 'a[href], button, input, textarea, select, [role="button"], summary';
      const out = new Set();
      for (const h of document.querySelectorAll('.pane-handle[role="separator"]')) {
        if (!shown(h)) continue;
        const r = h.getBoundingClientRect();
        for (let y = Math.ceil(r.top) + 1; y < r.bottom - 1; y += 6)
          for (const x of [r.left + 0.5, r.left + r.width / 2, r.right - 0.5]) {
            const stack = document.elementsFromPoint(x, y);
            const i = stack.indexOf(h);
            if (i < 0) continue;
            const under = stack.slice(i + 1).find((e) => e.matches(control));
            if (under) {
              const u = under.getBoundingClientRect();
              out.add(h.getAttribute("data-testid") + " over " + (under.getAttribute("aria-label") || under.getAttribute("data-testid") || under.textContent.trim().slice(0, 24) || under.tagName.toLowerCase()) + " (" + Math.round(u.left) + " to " + Math.round(u.right) + ")");
            }
          }
      }
      return [...out];
    })(),
    grips: [...document.querySelectorAll('.pane-handle[role="separator"]')].filter(shown).map((h) => {
      const g = h.querySelector(".pane-grip");
      const r = g ? g.getBoundingClientRect() : null;
      return { id: h.getAttribute("data-testid"), shown: !!r && r.width >= 3 && r.height >= 24 && getComputedStyle(g).backgroundColor !== "rgba(0, 0, 0, 0)" && getComputedStyle(g).visibility !== "hidden" };
    }),
    fit: (() => {
      const sb = document.getElementById("fd-sidebar");
      if (!shown(sb)) return null;
      const lines = (el) => { const rg = document.createRange(); rg.selectNodeContents(el); return new Set([...rg.getClientRects()].filter((q) => q.width > 0).map((q) => Math.round(q.top))).size; };
      const wraps = [...sb.querySelectorAll(".scr-filter .seg-item")].filter(shown).filter((it) => lines(it.querySelector(".seg-label") || it) > 1).map((it) => it.textContent.trim());
      const head = sb.querySelector(".scr-list-head");
      const parts = [sb.querySelector(".sidebar-hide"), head && head.querySelector(".scr-brand"), ...(head ? head.querySelectorAll("button, a") : [])].filter((e, i, a) => e && shown(e) && a.indexOf(e) === i);
      const boxes = parts.map((e) => {
        const q = e.getBoundingClientRect();
        // The brand's own words, not its flexible box: the words are what would run into Search.
        let right = q.right;
        if (e.classList.contains("scr-brand")) { const rg = document.createRange(); rg.selectNodeContents(e); right = q.left + rg.getBoundingClientRect().width; }
        return { name: e.getAttribute("aria-label") || e.textContent.trim() || e.className.split(" ")[0], left: q.left, right, top: q.top, bottom: q.bottom };
      });
      // v0.6 touch: the head's tools take a row of their own under the brand, so two parts overlap only where their
      // boxes meet in both directions.
      const overlap = [];
      for (let i = 0; i < boxes.length; i++)
        for (let j = i + 1; j < boxes.length; j++)
          if (boxes[i].left < boxes[j].right - 0.5 && boxes[j].left < boxes[i].right - 0.5 && boxes[i].top < boxes[j].bottom - 0.5 && boxes[j].top < boxes[i].bottom - 0.5) overlap.push(boxes[i].name + " and " + boxes[j].name);
      return { wraps, overlap };
    })(),
    showText: (() => { const b = document.querySelector('[data-testid="sidebar-show"]'); return shown(b) ? b.textContent.replace(/\\s+/g, " ").trim() : null; })(),
    selected: String(window.getSelection() || "").length,
  };
})())`;

const PANE_KEYS: Record<string, number> = { ArrowLeft: 37, ArrowRight: 39, Home: 36, End: 35 };

/** Start a record of the page's DOM changes (what changed and on what), for the moves of one drag. */
const WATCH_DOM = `(() => {
  window.__paneDom = [];
  const name = (n) => (n && n.nodeType === 1 ? n.getAttribute("data-testid") || (n.getAttribute("class") || n.tagName).split(" ")[0] : "text");
  const mo = new MutationObserver((list) => {
    for (const m of list) window.__paneDom.push(m.type === "attributes" ? name(m.target) + " " + m.attributeName : m.type + " in " + name(m.target));
  });
  mo.observe(document.body, { subtree: true, childList: true, attributes: true, characterData: true });
  window.__paneWatch = mo;
})()`;
/** End the record: each kind of change with its count. */
const WATCHED_DOM = `JSON.stringify((() => {
  if (window.__paneWatch) window.__paneWatch.disconnect();
  const out = {};
  for (const k of window.__paneDom || []) out[k] = (out[k] || 0) + 1;
  return out;
})())`;
/** What a drag's moves may change: the shell's style (the width variable) and its resizing mark, the handle's value, its own place (its style) and its dragging mark. */
const DRAG_DOM_OK = new Set(["shell style", "shell data-resizing", "pane-handle-sidebar aria-valuenow", "pane-handle-side aria-valuenow", "pane-handle-sidebar style", "pane-handle-side style", "pane-handle-sidebar data-dragging", "pane-handle-side data-dragging"]);

/** A drag's style work per move on a long chat stays under this (a move restyles the shell and its handle only). */
const DRAG_STYLE_MS = 4;
/** Clone the conversation's own blocks under it until the page holds about 10,000 elements: a long chat, for a drag's cost. */
const LONG_CHAT = `(() => {
  const col = [...document.querySelectorAll(".chat-col")].find((e) => e.getClientRects().length);
  const src = col ? [...col.children].filter((e) => e.getClientRects().length) : [];
  if (!src.length) return 0;
  const box = document.createElement("div");
  box.setAttribute("data-ui-check-long", "");
  let n = document.querySelectorAll("*").length;
  for (let i = 0; n < 10000 && i < 20000; i++) {
    const c = src[i % src.length].cloneNode(true);
    n += c.querySelectorAll("*").length + 1;
    box.appendChild(c);
  }
  col.appendChild(box);
  return document.querySelectorAll("*").length;
})()`;
const LONG_CHAT_GONE = `(() => { document.querySelectorAll("[data-ui-check-long]").forEach((e) => e.remove()); return true; })()`;

/**
 * A drag's cost (row 82: a drag never janks the transcript): on a long chat, a mouse drag of a handle in 30 moves a
 * frame apart, each one changing the width; the style recalculation and layout per move from CDP's Performance
 * metrics (the start of the drag, which marks the shell and the handle, counts in). The clones go again after.
 */
async function dragCost(page: Page, id: string): Promise<{ elements: number; moves: number; styleMs: number; layoutMs: number; recalcs: number } | null> {
  const elements = await page.evaluate<number>(LONG_CHAT);
  try {
    if (!elements) return null;
    await sleep(400);
    const h = await page.evaluate<{ x: number; y: number } | null>(`(() => { const h = document.querySelector('[data-testid="${id}"]'); if (!h) return null; const r = h.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 }; })()`);
    if (!h) return null;
    const metric = async () => Object.fromEntries((await page.send<{ metrics: { name: string; value: number }[] }>("Performance.getMetrics")).metrics.map((m) => [m.name, m.value])) as Record<string, number>;
    await page.send("Performance.enable");
    const dir = id === "pane-handle-sidebar" ? 1 : -1;
    const moves = 30;
    await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: h.x, y: h.y });
    await page.send("Input.dispatchMouseEvent", { type: "mousePressed", x: h.x, y: h.y, button: "left", buttons: 1, clickCount: 1 });
    await sleep(50);
    const m0 = await metric();
    for (let i = 1; i <= moves; i++) {
      await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: h.x + dir * 3 * i, y: h.y, button: "left", buttons: 1 });
      await sleep(20);
    }
    await sleep(100);
    const m1 = await metric();
    await page.send("Input.dispatchMouseEvent", { type: "mouseReleased", x: h.x + dir * 3 * moves, y: h.y, button: "left", buttons: 0, clickCount: 1 });
    await sleep(200);
    await page.send("Performance.disable");
    const per = (k: string) => Math.round(((((m1[k] ?? 0) - (m0[k] ?? 0)) * 1000) / moves) * 100) / 100;
    return { elements, moves, styleMs: per("RecalcStyleDuration"), layoutMs: per("LayoutDuration"), recalcs: (m1.RecalcStyleCount ?? 0) - (m0.RecalcStyleCount ?? 0) };
  } finally {
    await page.evaluate(LONG_CHAT_GONE).catch(() => {});
  }
}

/**
 * A drag on a handle: a mouse on a laptop, a finger on touch, in steps a frame apart (pointer capture keeps it).
 * `held` runs after the last move, before the pointer goes up.
 */
async function dragHandle(page: Page, x: number, y: number, dx: number, steps = 10, held?: () => Promise<void>) {
  if (page.vp.touch) {
    const point = (px: number) => [{ x: px, y, radiusX: 4, radiusY: 4, force: 1 }];
    await page.send("Input.dispatchTouchEvent", { type: "touchStart", touchPoints: point(x) });
    for (let i = 1; i <= steps; i++) {
      await page.send("Input.dispatchTouchEvent", { type: "touchMove", touchPoints: point(x + (dx * i) / steps) });
      await sleep(16);
    }
    await sleep(50);
    await held?.();
    await page.send("Input.dispatchTouchEvent", { type: "touchEnd", touchPoints: [] });
  } else {
    await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x, y });
    await page.send("Input.dispatchMouseEvent", { type: "mousePressed", x, y, button: "left", buttons: 1, clickCount: 1 });
    for (let i = 1; i <= steps; i++) {
      await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: x + (dx * i) / steps, y, button: "left", buttons: 1 });
      await sleep(16);
    }
    await sleep(50);
    await held?.();
    await page.send("Input.dispatchMouseEvent", { type: "mouseReleased", x: x + dx, y, button: "left", buttons: 0, clickCount: 1 });
  }
  await sleep(200);
}

/** A double-click on a laptop; on touch two taps 80 ms apart. */
async function doublePress(page: Page, x: number, y: number) {
  if (page.vp.touch) {
    for (let i = 0; i < 2; i++) {
      await page.send("Input.dispatchTouchEvent", { type: "touchStart", touchPoints: [{ x, y, radiusX: 4, radiusY: 4, force: 1 }] });
      await page.send("Input.dispatchTouchEvent", { type: "touchEnd", touchPoints: [] });
      await sleep(80);
    }
  } else {
    await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x, y });
    for (const clickCount of [1, 2]) {
      await page.send("Input.dispatchMouseEvent", { type: "mousePressed", x, y, button: "left", buttons: 1, clickCount });
      await page.send("Input.dispatchMouseEvent", { type: "mouseReleased", x, y, button: "left", buttons: 0, clickCount });
    }
  }
  await sleep(200);
}

/**
 * Row 82 at one size. A laptop (1280x800 and 1100x800, on the example chat with its side panel's column): one handle on
 * each inner edge, a focusable separator with its value and range; a drag of each moves its pane's edge with the
 * pointer, within the range, a long drag stops at the maximum with the chat column at least 420 px, and the composer
 * stays inside the chat column; the sidebar at its minimum with the side pane at its largest keeps its handle, and its
 * double-click takes its default's room back from the side pane; the arrow keys move a handle 16 px (Left and Right as
 * the pane grows), Home and End go to the ends; a reload keeps the widths; Hide sidebar hides it (its room goes to the
 * chat, the focus to Show sidebar in the title bar), a reload keeps it hidden, and Show sidebar brings it back at its
 * width; a double-click puts each default back; on a long chat a drag's style work per move stays under DRAG_STYLE_MS.
 * The tablet (834x1194, touch, the docked Details pane): its handle, a finger's drag, a reload keeping the width, a
 * double tap for the default, and last a tap on the lit Details right after a quick drag closing the pane; no sidebar
 * handle and no Hide sidebar (the chat list is a drawer). The large touch tablet (1366x1024): both handles, a finger's
 * drag of the sidebar to its minimum, Show sidebar with its name, a double tap for the default. On touch each handle
 * shows its grip, and a laptop's none. The phone (390x844): no handle, no Hide or Show, as before. Every size: no handle
 * lies over a control, the sidebar's filter stays on one line and its head's parts apart, the URL never changes (until
 * the tablet's last tap), no sideways overflow, nothing goes out.
 */
async function panesFlow(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const size = `${vp.width}x${vp.height}`;
  const laptop = vp.name === "laptop";
  const path = vp.name === "medium" ? `/c/${EX.chat}/details` : `/c/${EX.chat}`;
  let shot: string | undefined;
  try {
    await withPage(vp, "dark", async (page, wire) => {
      const read = async () => JSON.parse(await page.evaluate<string>(PANES_STATE)) as PanesState;
      const steps: Record<string, unknown>[] = [];
      const check = (step: string, s: PanesState) => {
        steps.push({ step, form: s.form, handles: s.handles.map((h) => `${h.id} ${h.now} (${h.min} to ${h.max})`), sidebar: s.sidebar?.width ?? null, side: s.side?.width ?? null, main: s.main?.width ?? null, view: s.view, field: s.fieldFocused, atEnd: s.atEnd });
        if (s.scrollWidth > s.clientWidth) failures.push({ code: "overflow", text: `${step}: the page scrolls sideways (${s.scrollWidth} > ${s.clientWidth})` });
        if (!sameUrl(s.path, path)) failures.push({ code: "flow", text: `${step}: the URL became ${s.path}` });
        if (s.resizing) failures.push({ code: "flow", text: `${step}: the shell is still marked as resizing` });
        if (s.main && s.composer && (s.composer.left < s.main.left - 1 || s.composer.right > s.main.right + 1)) failures.push({ code: "flow", text: `${step}: the composer (${s.composer.left} to ${s.composer.right}) runs out of the chat column (${s.main.left} to ${s.main.right})` });
        if (s.bar && s.bar.right !== vp.width) failures.push({ code: "edge", text: `${step}: the pane bar ends at ${s.bar.right}, not at the window's edge` });
        if (laptop && s.main && s.handles.length && s.main.width < 419) failures.push({ code: "flow", text: `${step}: the chat column is ${s.main.width} px, under 420` });
        if (s.covered.length) failures.push({ code: "cover", text: `${step}: a pane handle lies over ${clipList(s.covered)}` });
        if (s.selected) failures.push({ code: "flow", text: `${step}: ${s.selected} characters of the page are selected` });
        for (const g of s.grips) if (g.shown !== vp.touch) failures.push({ code: "shows", text: `${step}: ${g.id} ${vp.touch ? "shows no grip on touch" : "shows a grip on a laptop"}` });
        if (s.fit?.wraps.length) failures.push({ code: "fit", text: `${step}: at ${s.sidebar?.width} px the sidebar's filter puts ${clipList(s.fit.wraps)} on two lines` });
        if (s.fit?.overlap.length) failures.push({ code: "fit", text: `${step}: at ${s.sidebar?.width} px the sidebar's head runs ${clipList(s.fit.overlap)} together` });
      };
      const handle = (s: PanesState, id: string) => s.handles.find((h) => h.id === id);
      const paneOf = (s: PanesState, id: string) => (id === "pane-handle-sidebar" ? s.sidebar : s.side);
      /** One drag of `dx` on a handle: it must land where the pointer went, within the range it showed. */
      const drag = async (id: string, dx: number, step: string) => {
        const before = handle(await read(), id);
        if (!before) {
          failures.push({ code: "shows", text: `${step}: no ${id}` });
          return;
        }
        const grow = id === "pane-handle-sidebar" ? 1 : -1;
        const want = Math.min(before.max, Math.max(before.min, Math.round(before.now + grow * dx)));
        const start = await read();
        await page.evaluate(WATCH_DOM);
        let moved: Record<string, number> = {};
        await dragHandle(page, before.x, before.y, dx, 10, async () => {
          moved = JSON.parse(await page.evaluate<string>(WATCHED_DOM)) as Record<string, number>;
        });
        domDuringDrags[step] = moved;
        const others = Object.keys(moved).filter((k) => !DRAG_DOM_OK.has(k));
        if (others.length) warnings.push({ code: "drag-dom", text: `${step}: the moves changed more than the width variable: ${clipList(others.map((k) => `${k} (${moved[k]})`))}` });
        const s = await read();
        check(step, s);
        if (start.fieldFocused && !s.fieldFocused) failures.push({ code: "flow", text: `${step}: the message box lost the focus (now ${s.focus})` });
        if (start.atEnd && s.atEnd === false) failures.push({ code: "flow", text: `${step}: the conversation was at its end and is not after the drag` });
        const after = handle(s, id);
        const box = paneOf(s, id);
        if (!after || after.now !== want) failures.push({ code: "flow", text: `${step}: ${id} reads ${after?.now ?? "nothing"}, expected ${want} (from ${before.now}, ${dx} px, ${before.min} to ${before.max})` });
        if (!box || Math.abs(box.width - want) > 1) failures.push({ code: "flow", text: `${step}: the pane is ${box?.width ?? "not"} px wide, expected ${want}` });
        const kept = s.view?.widths?.[id === "pane-handle-sidebar" ? "sidebar" : "side"];
        if (want !== before.now && kept !== want) failures.push({ code: "flow", text: `${step}: the device keeps ${kept ?? "nothing"}, expected ${want}` });
      };
      const domDuringDrags: Record<string, Record<string, number>> = {};
      details.domDuringDrags = domDuringDrags;
      const since = wire.mark();
      await page.navigate(base + path);
      await waitShown(page, ["conversation"]);
      await sleep(300);
      // The message box has the focus while the panes move (a drag never takes it).
      await page.evaluate(`(() => { const f = document.querySelector('[data-testid="composer-input"]'); if (f && !${vp.touch}) f.focus(); })()`);
      const s0 = await read();
      check("open", s0);
      details.open = s0.handles;

      if (vp.name === "phone") {
        if (s0.handles.length) failures.push({ code: "flow", text: `the phone shows ${s0.handles.length} pane handle(s)` });
        if (s0.hide || s0.show) failures.push({ code: "flow", text: "the phone shows Hide sidebar or Show sidebar" });
        if (s0.form !== "screen") failures.push({ code: "flow", text: `the phone's shell says its chat list is "${s0.form}", not its own screen` });
        await page.navigate(base + `/c/${EX.chat}/details`);
        await sleep(300);
        const det = await read();
        if (det.handles.length) failures.push({ code: "flow", text: "the phone's Details sheet has a pane handle" });
        shot = shotName(scene, "panes", vp, "dark", String(vp.width));
        await page.screenshot(shot);
      } else if (vp.name === "medium" && mediumHandle(vp.width) === null) {
        // DESIGN-T1 T-30 (G-48): under 702 px the medium pane cannot change width, so it has no handle.
        const ids = s0.handles.map((h) => h.id);
        if (ids.length) failures.push({ code: "flow", text: `at ${vp.width} px the docked pane has handles ${JSON.stringify(ids)}; it cannot change width` });
        if (s0.side && Math.abs(s0.side.width - mediumPane(vp.width)) > 2) failures.push({ code: "flow", text: `the docked pane is ${s0.side.width} px, not ${mediumPane(vp.width)}` });
        shot = shotName(scene, "panes", vp, "dark", String(vp.width));
        await page.screenshot(shot);
      } else if (vp.name === "medium") {
        const ids = s0.handles.map((h) => h.id);
        if (ids.join() !== "pane-handle-side") failures.push({ code: "flow", text: `the tablet's handles are ${JSON.stringify(ids)}, expected the docked pane's only` });
        if (s0.hide || s0.show) failures.push({ code: "flow", text: "the tablet shows Hide sidebar or Show sidebar (its chat list is a drawer)" });
        const h = handle(s0, "pane-handle-side");
        const want = mediumHandle(vp.width)!;
        if (h && (h.now !== want.def || h.min !== PANE_SIDE.min || h.max !== want.max)) failures.push({ code: "flow", text: `the docked pane's handle reads ${h.now} (${h.min} to ${h.max}), expected ${want.def} (${PANE_SIDE.min} to ${want.max})` });
        await drag("pane-handle-side", -30, "touch drag");
        shot = shotName(scene, "panes", vp, "dark", String(vp.width));
        await page.screenshot(shot);
        const dragged = handle(await read(), "pane-handle-side")?.now;
        await page.reload();
        await waitShown(page, ["conversation"]);
        await sleep(300);
        const again = await read();
        check("reload", again);
        if (handle(again, "pane-handle-side")?.now !== dragged) failures.push({ code: "flow", text: `after a reload the docked pane reads ${handle(again, "pane-handle-side")?.now}, not ${dragged}` });
        const at = handle(again, "pane-handle-side");
        if (at) await doublePress(page, at.x, at.y);
        const back = await read();
        check("double tap", back);
        if (handle(back, "pane-handle-side")?.now !== mediumPane(vp.width)) failures.push({ code: "flow", text: `a double tap left the docked pane at ${handle(back, "pane-handle-side")?.now}, not its default ${mediumPane(vp.width)}` });
        if (back.view?.widths && Object.keys(back.view.widths).length) failures.push({ code: "flow", text: `after the double tap the device still keeps ${JSON.stringify(back.view.widths)}` });
        // A quick drag to the narrowest (330 px in 10 moves, the finger lifted as it moves), then at once a tap on the lit
        // Details: the tap closes the pane. Chrome takes such a release for a fling and spends the next tap on stopping
        // it, unless the handle cancels its touchstart (ui/PaneHandle.tsx).
        const quick = handle(await read(), "pane-handle-side");
        if (quick) {
          const finger = (x: number) => [{ x, y: quick.y, radiusX: 4, radiusY: 4, force: 1 }];
          await page.send("Input.dispatchTouchEvent", { type: "touchStart", touchPoints: finger(quick.x) });
          for (let i = 1; i <= 10; i++) {
            await page.send("Input.dispatchTouchEvent", { type: "touchMove", touchPoints: finger(quick.x + 33 * i) });
            await sleep(16);
          }
          await page.send("Input.dispatchTouchEvent", { type: "touchEnd", touchPoints: [] });
          await sleep(300);
          const s = await read();
          check("quick touch drag", s);
          if (handle(s, "pane-handle-side")?.now !== PANE_SIDE.min) failures.push({ code: "flow", text: `the quick drag left the docked pane at ${handle(s, "pane-handle-side")?.now}, not its minimum ${PANE_SIDE.min}` });
        }
        const lit = await page.locate('.pane-bar-btn.on[title="Close Details"]');
        if (!lit) failures.push({ code: "shows", text: "after the quick drag the pane bar shows no lit Details" });
        else {
          await page.press(lit.x, lit.y);
          await sleep(600);
          const closed = await read();
          if (!sameUrl(closed.path, `/c/${EX.chat}`) || closed.side) failures.push({ code: "flow", text: `a tap on the lit Details right after a quick drag of the handle left ${closed.path} with the pane ${closed.side ? "open" : "closed"} (the tap was lost)` });
        }
      } else if (vp.touch && vp.height > vp.width) {
        // v0.6 touch: the large tablet in portrait, the laptop's layout with its panes over the chat (one view, no handle
        // on an over-pane): the sidebar's handle only.
        const ids = s0.handles.map((h) => h.id);
        if (ids.join() !== "pane-handle-sidebar") failures.push({ code: "shows", text: `the large tablet's handles in portrait are ${JSON.stringify(ids)}, expected the sidebar's only` });
        if (!s0.hide || s0.show) failures.push({ code: "shows", text: "the sidebar has no Hide sidebar, or the title bar shows Show sidebar" });
        await drag("pane-handle-sidebar", -2000, "touch drag of the sidebar to its minimum");
        if (handle(await read(), "pane-handle-sidebar")?.now !== PANE_SIDEBAR.min) failures.push({ code: "flow", text: `the sidebar did not reach its minimum of ${PANE_SIDEBAR.min} px by touch` });
        const h = handle(await read(), "pane-handle-sidebar");
        if (h) await doublePress(page, h.x, h.y);
        const s = await read();
        check("sidebar double tap", s);
        if (handle(s, "pane-handle-sidebar")?.now !== PANE_SIDEBAR.def) failures.push({ code: "flow", text: `a double tap left the sidebar at ${handle(s, "pane-handle-sidebar")?.now}, not its default ${PANE_SIDEBAR.def}` });
        shot = shotName(scene, "panes", vp, "dark", `${vp.width}-touch`);
        await page.screenshot(shot);
      } else if (vp.touch) {
        // The large touch tablet: the laptop's layout with a finger.
        const ids = s0.handles.map((h) => h.id);
        if (ids.join() !== "pane-handle-sidebar,pane-handle-side") failures.push({ code: "shows", text: `the large touch tablet's handles are ${JSON.stringify(ids)}` });
        if (!s0.hide || s0.show) failures.push({ code: "shows", text: "the sidebar has no Hide sidebar at its top, or the title bar shows Show sidebar" });
        await drag("pane-handle-sidebar", -2000, "touch drag of the sidebar to its minimum");
        if (handle(await read(), "pane-handle-sidebar")?.now !== PANE_SIDEBAR.min) failures.push({ code: "flow", text: `the sidebar did not reach its minimum of ${PANE_SIDEBAR.min} px by touch` });
        await drag("pane-handle-side", -60, "touch drag of the side pane");
        shot = shotName(scene, "panes", vp, "dark", `${vp.width}-touch-min`);
        await page.screenshot(shot);
        const hide = await page.locate('[data-testid="sidebar-hide"]');
        if (!hide) failures.push({ code: "shows", text: "no Hide sidebar" });
        else {
          await page.press(hide.x, hide.y);
          await sleep(300);
          const hidden = await read();
          check("hide sidebar", hidden);
          if (hidden.form !== "hidden" || hidden.sidebar) failures.push({ code: "flow", text: `Hide sidebar left the shell "${hidden.form}"` });
          if (hidden.showText !== "Show sidebar") failures.push({ code: "shows", text: `on touch Show sidebar shows ${JSON.stringify(hidden.showText)}, not its name` });
          shot = shotName(scene, "panes", vp, "dark", `${vp.width}-touch-hidden`);
          await page.screenshot(shot);
          const show = await page.locate('[data-testid="sidebar-show"]');
          if (show) {
            await page.press(show.x, show.y);
            await sleep(300);
            const shown = await read();
            check("show sidebar", shown);
            if (shown.form !== "docked" || handle(shown, "pane-handle-sidebar")?.now !== PANE_SIDEBAR.min) failures.push({ code: "flow", text: `Show sidebar brought the sidebar back ${shown.form}, ${handle(shown, "pane-handle-sidebar")?.now ?? "with no handle"}` });
          }
        }
        for (const [id, def] of [["pane-handle-sidebar", PANE_SIDEBAR.def], ["pane-handle-side", PANE_SIDE.def]] as const) {
          const h = handle(await read(), id);
          if (h) await doublePress(page, h.x, h.y);
          const s = await read();
          check(`${id} double tap`, s);
          if (handle(s, id)?.now !== def) failures.push({ code: "flow", text: `a double tap left ${id} at ${handle(s, id)?.now}, not its default ${def}` });
        }
        const end = await read();
        if (end.view?.widths && Object.keys(end.view.widths).length) failures.push({ code: "flow", text: `after the double taps the device still keeps ${JSON.stringify(end.view.widths)}` });
      } else {
        const ids = s0.handles.map((h) => h.id);
        if (ids.join() !== "pane-handle-sidebar,pane-handle-side") failures.push({ code: "shows", text: `the laptop's handles are ${JSON.stringify(ids)}` });
        const sb = handle(s0, "pane-handle-sidebar");
        const sd = handle(s0, "pane-handle-side");
        if (sb && (sb.now !== PANE_SIDEBAR.def || sb.min !== PANE_SIDEBAR.min || sb.max !== Math.min(PANE_SIDEBAR.max, vp.width - 420 - PANE_SIDE.def) || sb.controls !== "fd-sidebar")) failures.push({ code: "flow", text: `the sidebar's handle reads ${sb.now} (${sb.min} to ${sb.max}, controls ${sb.controls})` });
        if (sd && (sd.now !== PANE_SIDE.def || sd.min !== PANE_SIDE.min || sd.max !== Math.min(PANE_SIDE.max, vp.width - 420 - PANE_SIDEBAR.def) || sd.controls !== "fd-side")) failures.push({ code: "flow", text: `the side pane's handle reads ${sd.now} (${sd.min} to ${sd.max}, controls ${sd.controls})` });
        if (!s0.hide || s0.show) failures.push({ code: "shows", text: "the sidebar has no Hide sidebar at its top, or the title bar shows Show sidebar" });
        // Drags: each edge follows the pointer; a long drag stops at the maximum, the chat keeping 420 px.
        await drag("pane-handle-sidebar", 60, "sidebar drag");
        await drag("pane-handle-side", -100, "side pane drag");
        await drag("pane-handle-side", -2000, "side pane long drag");
        await drag("pane-handle-sidebar", 2000, "sidebar long drag");
        await drag("pane-handle-sidebar", -2000, "sidebar drag to its minimum");
        shot = shotName(scene, "panes", vp, "dark", String(vp.width));
        await page.screenshot(shot);
        // The side pane takes all the room: the sidebar at its minimum keeps its handle (one width, still focusable),
        // and its double-click puts its default back, the side pane giving the room.
        await drag("pane-handle-side", -2000, "side pane to its largest beside the narrowest sidebar");
        const held = await read();
        const pinned = handle(held, "pane-handle-sidebar");
        details.heldAtMinimum = pinned ?? null;
        if (!pinned) failures.push({ code: "shows", text: "with the side pane at its largest, the sidebar's handle is gone (the edge looks dead)" });
        else {
          if (pinned.min !== pinned.max || pinned.now !== PANE_SIDEBAR.min) failures.push({ code: "flow", text: `the pinned sidebar's handle reads ${pinned.now} (${pinned.min} to ${pinned.max}), expected ${PANE_SIDEBAR.min} with a one-width range` });
          await doublePress(page, pinned.x, pinned.y);
          const back = await read();
          check("double-click on the pinned sidebar", back);
          const sideNow = handle(back, "pane-handle-side")?.now;
          if (handle(back, "pane-handle-sidebar")?.now !== PANE_SIDEBAR.def || sideNow !== vp.width - 420 - PANE_SIDEBAR.def) failures.push({ code: "flow", text: `the pinned sidebar's double-click left it at ${handle(back, "pane-handle-sidebar")?.now} beside the side pane at ${sideNow}, expected ${PANE_SIDEBAR.def} beside ${vp.width - 420 - PANE_SIDEBAR.def}` });
        }
        // Keys: each on the focused separator, by 16 px or to the ends.
        for (const id of ["pane-handle-sidebar", "pane-handle-side"]) {
          await page.evaluate(`document.querySelector('[data-testid="${id}"]').focus()`);
          const [wider, narrower] = id === "pane-handle-sidebar" ? ["ArrowRight", "ArrowLeft"] : ["ArrowLeft", "ArrowRight"];
          for (const key of ["End", wider, narrower, narrower, "Home", narrower, wider]) {
            const before = handle(await read(), id);
            if (!before) break;
            const grow = id === "pane-handle-sidebar" ? 1 : -1;
            const want = key === "Home" ? before.min : key === "End" ? before.max : Math.min(before.max, Math.max(before.min, before.now + (key === "ArrowRight" ? 16 : -16) * grow));
            const vk = PANE_KEYS[key]!;
            await page.send("Input.dispatchKeyEvent", { type: "rawKeyDown", key, code: key, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk });
            await page.send("Input.dispatchKeyEvent", { type: "keyUp", key, code: key, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk });
            await sleep(120);
            const s = await read();
            check(`${id} ${key}`, s);
            const after = handle(s, id);
            if (!after?.focused) failures.push({ code: "flow", text: `${id} ${key}: the separator lost the focus (${s.focus})` });
            if (after?.now !== want) failures.push({ code: "flow", text: `${id} ${key}: reads ${after?.now}, expected ${want} (from ${before.now}, ${before.min} to ${before.max})` });
          }
        }
        // A reload keeps the widths.
        const kept = await read();
        await page.reload();
        await waitShown(page, ["conversation"]);
        await sleep(300);
        const again = await read();
        check("reload", again);
        for (const id of ["pane-handle-sidebar", "pane-handle-side"])
          if (handle(again, id)?.now !== handle(kept, id)?.now) failures.push({ code: "flow", text: `after a reload ${id} reads ${handle(again, id)?.now}, not ${handle(kept, id)?.now}` });
        // Hide sidebar, a reload, Show sidebar.
        const sbWidth = again.sidebar?.width ?? null;
        const mainBefore = again.main?.width ?? 0;
        const hide = await page.locate('[data-testid="sidebar-hide"]');
        if (!hide) failures.push({ code: "shows", text: "no Hide sidebar" });
        else {
          await page.press(hide.x, hide.y);
          await sleep(300);
          const hidden = await read();
          check("hide sidebar", hidden);
          if (hidden.form !== "hidden" || hidden.sidebar || !hidden.show || hidden.hide) failures.push({ code: "flow", text: `Hide sidebar left the shell "${hidden.form}", the sidebar ${hidden.sidebar ? "shown" : "gone"}, Show sidebar ${hidden.show ? "shown" : "missing"}` });
          if (hidden.handles.some((h) => h.id === "pane-handle-sidebar")) failures.push({ code: "flow", text: "the hidden sidebar's handle still shows" });
          if (!hidden.main || hidden.main.width <= mainBefore) failures.push({ code: "flow", text: `the chat column did not get the sidebar's room (${mainBefore} then ${hidden.main?.width})` });
          if (hidden.focus !== "sidebar-show") failures.push({ code: "flow", text: `after Hide sidebar the focus is on ${hidden.focus}, not Show sidebar` });
          if (hidden.view?.sidebarHidden !== true) failures.push({ code: "flow", text: "the device does not keep the hidden sidebar" });
          await page.reload();
          await waitShown(page, ["conversation"]);
          await sleep(300);
          const still = await read();
          check("reload hidden", still);
          if (still.form !== "hidden" || still.sidebar) failures.push({ code: "flow", text: "after a reload the sidebar is back" });
          shot = shotName(scene, "panes", vp, "dark", `${vp.width}-hidden`);
          await page.screenshot(shot);
          const show = await page.locate('[data-testid="sidebar-show"]');
          if (!show) failures.push({ code: "shows", text: "no Show sidebar in the title bar" });
          else {
            await page.press(show.x, show.y);
            await sleep(300);
            const shown = await read();
            check("show sidebar", shown);
            if (shown.form !== "docked" || !shown.sidebar || shown.show) failures.push({ code: "flow", text: `Show sidebar left the shell "${shown.form}"` });
            if (shown.sidebar && sbWidth !== null && shown.sidebar.width !== sbWidth) failures.push({ code: "flow", text: `the sidebar came back ${shown.sidebar.width} px wide, not ${sbWidth}` });
            if (shown.focus !== "sidebar-hide") failures.push({ code: "flow", text: `after Show sidebar the focus is on ${shown.focus}, not Hide sidebar` });
          }
        }
        // A double-click puts each default back, and the device keeps no width.
        for (const [id, def] of [["pane-handle-sidebar", 248], ["pane-handle-side", 320]] as const) {
          const h = handle(await read(), id);
          if (h) await doublePress(page, h.x, h.y);
          const s = await read();
          check(`${id} double-click`, s);
          if (handle(s, id)?.now !== def) failures.push({ code: "flow", text: `a double-click left ${id} at ${handle(s, id)?.now}, not its default ${def}` });
        }
        const end = await read();
        if (end.view?.widths && Object.keys(end.view.widths).length) failures.push({ code: "flow", text: `after the double-clicks the device still keeps ${JSON.stringify(end.view.widths)}` });
        // A drag on a long chat: the style work per move stays small (a move restyles the shell and its handle only).
        const cost = await dragCost(page, "pane-handle-side");
        details.dragCost = cost;
        if (!cost) warnings.push({ code: "cost", text: "the long chat could not be built, so a drag's cost was not measured" });
        else if (cost.styleMs > DRAG_STYLE_MS) failures.push({ code: "cost", text: `on a long chat (${cost.elements} elements) a drag's style work is ${cost.styleMs} ms a move (${cost.recalcs} recalculations in ${cost.moves} moves), over ${DRAG_STYLE_MS} ms: each move restyles the transcript` });
        const after = await read();
        const h = handle(after, "pane-handle-side");
        if (h && h.now !== PANE_SIDE.def) await doublePress(page, h.x, h.y);
        const clean = await read();
        check("after the long chat's drag", clean);
        if (clean.view?.widths && Object.keys(clean.view.widths).length) failures.push({ code: "flow", text: `after the long chat's drag and a double-click the device still keeps ${JSON.stringify(clean.view.widths)}` });
      }
      details.steps = steps;
      stateFindings(await page.probe(), vp, failures);
      issueFindings(page.takeIssues(), failures);
      quietFindings(wire, since, await recorder(page), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note =
    vp.name === "phone"
      ? `${size}: no handle and no Hide or Show sidebar, as before; nothing sent`
      : vp.name === "medium"
        ? `${size}: the docked pane's handle by touch, with its grip, over no control, a reload keeping its width, a double tap for the default, a tap right after a quick drag; no overflow, nothing sent`
        : vp.touch
          ? `${size} touch: both handles by touch with their grips, over no control, the sidebar's filter and head fitting at its minimum, Show sidebar with its name, double taps for the defaults; no overflow, nothing sent`
          : `${size}: both handles by drag and by keys within their ranges (the chat 420 px or more), over no control, a pinned sidebar's handle kept, a reload keeping them, Hide sidebar and Show sidebar across a reload, double-clicks for the defaults, a drag's style work on a long chat under ${DRAG_STYLE_MS} ms a move; no overflow, nothing sent`;
  return finish({ kind: "flow", name: "panes", route: "chat", scene, size: sizeTag(vp), theme: "dark", path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

// ---------------------------------------------------------------------------------------------------------------
// U4 (FIX-U4 section 2, DESIGN-U4): split-panel, two views in the side panel, one above the other

/** The split side panel as the page shows it: the column, its halves and divider, the chat column, the Terminal's rows. */
interface SplitState {
  path: string;
  split: string | null;
  sideClass: string | null;
  side: { left: number; top: number; width: number; height: number } | null;
  halves: { slot: string; kind: string; top: number; height: number }[];
  divider: { label: string; now: number; min: number; max: number; controls: string | null; x: number; y: number; focused: boolean; grip: boolean } | null;
  /** The chat column's width. */
  main: number | null;
  over: boolean;
  terminal: boolean;
  /** The terminal's rows (xterm's DOM rows), or null when none shows. */
  rows: number | null;
  lit: string[];
  view: { split?: number } | null;
  focus: string | null;
  scrollWidth: number;
  clientWidth: number;
  notices: number;
}

const SPLIT_STATE = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0;
  const side = document.getElementById("fd-side");
  const r = (el) => { const b = el.getBoundingClientRect(); return { left: Math.round(b.left), top: Math.round(b.top), width: Math.round(b.width), height: Math.round(b.height) }; };
  const d = document.querySelector('[data-testid="split-divider"]');
  const db = d ? d.getBoundingClientRect() : null;
  const term = [...document.querySelectorAll('[data-testid="terminal-pane"]')].find(shown);
  const rows = term ? term.querySelectorAll(".xterm-rows > div").length : null;
  let view = null;
  try { view = JSON.parse(localStorage.getItem("kitespan.view") || "null"); } catch {}
  const at = document.activeElement;
  const main = document.querySelector(".shell > .main-col");
  return {
    path: location.pathname + location.search,
    split: document.querySelector(".shell")?.getAttribute("data-split") ?? null,
    sideClass: side ? side.className : null,
    side: shown(side) ? r(side) : null,
    halves: side ? [...side.querySelectorAll(":scope > .split-half[data-half]")].map((h) => ({ slot: h.getAttribute("data-half"), kind: h.getAttribute("data-kind"), top: Math.round(h.getBoundingClientRect().top), height: Math.round(h.getBoundingClientRect().height) })) : [],
    divider: d && shown(d) ? { label: d.getAttribute("aria-label"), now: Number(d.getAttribute("aria-valuenow")), min: Number(d.getAttribute("aria-valuemin")), max: Number(d.getAttribute("aria-valuemax")), controls: d.getAttribute("aria-controls"), x: db.left + db.width / 2, y: db.top + db.height / 2, focused: at === d, grip: shown(d.querySelector(".split-grip")) } : null,
    main: shown(main) ? Math.round(main.getBoundingClientRect().width) : null,
    over: !!document.querySelector(".side-over"),
    terminal: !!term,
    rows,
    // A named tool on touch has no title and no aria-label: its word is its name.
    lit: [...document.querySelectorAll(".pane-bar-btn.on, .scr-bar-tools > .on")].filter(shown).map((b) => b.getAttribute("title") || b.getAttribute("aria-label") || b.textContent.trim()),
    view,
    focus: at && at !== document.body ? at.getAttribute("data-testid") || at.getAttribute("aria-label") || at.tagName.toLowerCase() : null,
    scrollWidth: document.documentElement.scrollWidth,
    clientWidth: document.documentElement.clientWidth,
    notices: [...document.querySelectorAll('[data-testid="link-notice"], [data-testid="chat-gone"]')].filter(shown).length,
  };
})())`;

/** A file of the example chat's folder (the files route's example). */
const SPLIT_FILE = EX.file;
/** The tablet in landscape (medium touch, DESIGN-U4 8) and a wider laptop (DESIGN-U4 15.2). */
const SPLIT_TABLET: Viewport = { name: "medium", width: 1194, height: 834, scale: 2, mobile: true, touch: true };
const SPLIT_WIDE: Viewport = { name: "laptop", width: 1440, height: 900, scale: 1, mobile: false, touch: false };
const SPLIT_KEYS: Record<string, number> = { ArrowUp: 38, ArrowDown: 40, Home: 36, End: 35 };

/** One drag of the divider by `dy` px (a mouse on a laptop, a finger on touch). */
async function dragDivider(page: Page, x: number, y: number, dy: number, steps = 10) {
  if (page.vp.touch) {
    const point = (py: number) => [{ x, y: py, radiusX: 4, radiusY: 4, force: 1 }];
    await page.send("Input.dispatchTouchEvent", { type: "touchStart", touchPoints: point(y) });
    for (let i = 1; i <= steps; i++) {
      await page.send("Input.dispatchTouchEvent", { type: "touchMove", touchPoints: point(y + (dy * i) / steps) });
      await sleep(16);
    }
    await sleep(50);
    await page.send("Input.dispatchTouchEvent", { type: "touchEnd", touchPoints: [] });
  } else {
    await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x, y });
    await page.send("Input.dispatchMouseEvent", { type: "mousePressed", x, y, button: "left", buttons: 1, clickCount: 1 });
    for (let i = 1; i <= steps; i++) {
      await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x, y: y + (dy * i) / steps, button: "left", buttons: 1 });
      await sleep(16);
    }
    await sleep(50);
    await page.send("Input.dispatchMouseEvent", { type: "mouseReleased", x, y: y + dy, button: "left", buttons: 0, clickCount: 1 });
  }
  await sleep(250);
}

/** Set the window's width (and height) as a narrower or wider window would be, without a reload. */
async function splitWindow(page: Page, width: number, height = page.vp.height) {
  await page.send("Emulation.setDeviceMetricsOverride", { width, height, deviceScaleFactor: page.vp.scale, mobile: page.vp.mobile, screenWidth: width, screenHeight: height });
  await sleep(400);
}

/** Put the page in a look (glass: no data-look on the root, as Settings > Appearance > Look sets it). */
async function splitLook(page: Page, look: P2LookId) {
  await page.evaluate(`(() => { const r = document.documentElement; ${look === "glass" ? `r.removeAttribute("data-look")` : `r.setAttribute("data-look", ${JSON.stringify(look)})`}; return true; })()`);
  await sleep(250);
}

/** A still with no hover under the pointer and the machine's name masked. */
async function splitShot(page: Page, file: string) {
  if (!page.vp.touch) await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: 4, y: Math.round(page.vp.height / 2) });
  await sleep(150);
  await maskMachine(page);
  await page.screenshot(file).catch(() => {});
}

/**
 * U4 at one size and theme (FIX-U4 section 2; DESIGN-U4 20). The laptop (1280x800): on the example chat, the
 * Terminal alone; Show session rail brings the cards in above it; Outputs, then a file of the chat's folder open in the
 * upper half (the URL names the pair: the file, below=shell); the divider is a focusable horizontal separator named
 * "Files height" with its value and its range, the column is the Terminal's 512 px and the chat keeps 520; a drag
 * moves it within its range, the device keeps the share, the chat's width does not change and xterm's rows follow;
 * Up, Down, Home and End move it, a double-click gives equal halves; a reload keeps the pair, Back gives the pair before
 * (Outputs above the Terminal) and Forward the file again; Ctrl+K swaps the file's half for search; its Close gives the
 * whole column to the Terminal; then the window narrows (1200, 1088: the column narrows, the chat at 520; 1050: one
 * view over the chat, the path's alone lit; 900: the pair again beside a drawer sidebar; 700: the tablet's size class,
 * the pair in its docked pane; 560: the phone's, no panel beside the chat) and widens again. The tablet (1194x834 touch): a link to the pair, both pane bar buttons lit, the divider's grip, a finger's
 * drag, a tap on the lit Files closing its half. With `look` (1280x800 light): the pair in that look, a still. The
 * phone (390x844): the same link shows the file's own page with no divider and no second view. Every step: no sideways
 * overflow, no 5.4 line, nothing mutating sent.
 */
async function splitPanelFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme, look?: P2LookId): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const chat = EX.chat;
  const P = (rest: string) => `/c/${chat}/${rest}`;
  const pair = P(`files/${SPLIT_FILE}?below=shell`);
  let path = vp.name === "laptop" && !vp.touch && !look ? P("shell") : pair;
  let shot: string | undefined;
  const steps: Record<string, unknown>[] = [];
  const step = (label: string) => shotName(scene, "split-panel", vp, theme, look ? `${look}-${vp.width}-${label}` : `${vp.width}-${label}`);
  // v0.6 touch: the large tablet in portrait has one view over the chat; with its sidebar hidden, and in landscape, the
  // side column with its split, as on a laptop but with a finger (DESIGN-T1 3.1).
  const largeOver = vp.touch && vp.name === "laptop" && vp.height > vp.width && vp.tag !== "large-col";
  try {
    await withPage(vp, theme, async (page, wire) => {
      const read = async () => JSON.parse(await page.evaluate<string>(SPLIT_STATE)) as SplitState;
      const until = async (ok: (s: SplitState) => boolean, ms = 6000) => {
        const end = Date.now() + ms;
        let s = await read();
        while (!ok(s) && Date.now() < end) {
          await sleep(100);
          s = await read();
        }
        return s;
      };
      const check = (label: string, s: SplitState) => {
        steps.push({ step: label, path: s.path, split: s.split, side: s.side?.width ?? null, main: s.main, halves: s.halves.map((h) => `${h.slot} ${h.kind} ${h.height}`), divider: s.divider ? `${s.divider.label} ${s.divider.now} (${s.divider.min} to ${s.divider.max})` : null, rows: s.rows, lit: s.lit, focus: s.focus });
        if (s.scrollWidth > s.clientWidth) failures.push({ code: "overflow", text: `${label}: the page scrolls sideways (${s.scrollWidth} > ${s.clientWidth})` });
        if (s.notices) failures.push({ code: "notice", text: `${label}: a 5.4 line shows` });
      };
      const pairShown = (label: string, s: SplitState, upper: string, lower: string) => {
        const kinds = s.halves.map((h) => `${h.slot} ${h.kind}`);
        if (kinds.join() !== `upper ${upper},lower ${lower}`) failures.push({ code: "shows", text: `${label}: the halves are ${JSON.stringify(kinds)}, not ${upper} above ${lower}` });
        if (!s.divider) failures.push({ code: "shows", text: `${label}: no divider between the halves` });
        const up = s.halves.find((h) => h.slot === "upper");
        if (s.divider && up && Math.abs(up.height - s.divider.now) > 1) failures.push({ code: "flow", text: `${label}: the upper half is ${up.height} px, the divider says ${s.divider.now}` });
        if (s.divider && s.divider.controls !== "fd-split-upper") failures.push({ code: "a11y", text: `${label}: the divider controls ${s.divider.controls}` });
        if (s.divider && s.divider.grip !== vp.touch) failures.push({ code: "shows", text: `${label}: the divider ${vp.touch ? "shows no grip on touch" : "shows a grip on a laptop"}` });
      };
      const since = wire.mark();
      await page.navigate(base + path);
      await waitShown(page, vp.name === "phone" ? ["file-download"] : ["terminal-pane"]);
      await sleep(400);

      if (vp.name === "phone") {
        const s = await read();
        check("phone", s);
        if (s.divider || s.halves.length || s.terminal) failures.push({ code: "flow", text: `the phone shows ${s.divider ? "a divider" : s.halves.length ? "two halves" : "the Terminal"} for a pair's link (row 115: no split on the phone)` });
        if (!sameUrl(s.path, pair)) failures.push({ code: "url", text: `the phone rewrote the link to ${s.path}` });
        shot = step("phone");
        await splitShot(page, shot);
      } else if (look) {
        await splitLook(page, look);
        const s = await until((x) => x.halves.length === 2);
        check(look, s);
        pairShown(look, s, "files", "terminal");
        shot = step("pair");
        await splitShot(page, shot);
      } else if (largeOver) {
        // One view over the chat: the URL's own (the file), no Terminal, Files lit in the pane bar.
        const s = await read();
        check("link", s);
        if (s.halves.length || s.divider) failures.push({ code: "flow", text: "over the chat the pair shows two halves; only the URL's own view shows" });
        if (s.terminal) failures.push({ code: "flow", text: "over the chat the Terminal shows; only the URL's own view shows" });
        if (!s.lit.includes("Close Files")) failures.push({ code: "shows", text: `the pane bar lights ${JSON.stringify(s.lit)}, not Files` });
        if (!sameUrl(s.path, pair)) failures.push({ code: "url", text: `the large tablet rewrote the pair's link to ${s.path}` });
        shot = step("over");
        await splitShot(page, shot);
      } else if (vp.touch && vp.name === "laptop") {
        // The column with its split by touch: the halves, the divider with its grip, a finger's drag.
        let s = await until((x) => x.halves.length === 2);
        check("link", s);
        pairShown("link", s, "files", "terminal");
        if (s.divider?.label !== "Files height") failures.push({ code: "a11y", text: `the divider is named ${JSON.stringify(s.divider?.label)}, not "Files height"` });
        if (!s.lit.some((l) => /terminal/i.test(l))) failures.push({ code: "shows", text: `the title bar lights ${JSON.stringify(s.lit)}, not the Terminal` });
        shot = step("pair");
        await splitShot(page, shot);
        if (s.divider) {
          const before = s.divider.now;
          await dragDivider(page, s.divider.x, s.divider.y, -60);
          s = await until((x) => x.divider?.now !== before);
          check("touch drag", s);
          if (s.divider?.now !== Math.max(s.divider?.min ?? 0, before - 60)) failures.push({ code: "flow", text: `a finger's drag of 60 px up left the divider at ${s.divider?.now}, from ${before}` });
          if (typeof s.view?.split !== "number") failures.push({ code: "flow", text: "the device keeps no divider place after the drag" });
          const d = await page.evaluate<{ x: number; y: number } | null>(`(() => { const d = document.querySelector('[data-testid="split-divider"]'); if (!d) return null; const b = d.getBoundingClientRect(); return { x: b.left + b.width / 2, y: b.top + b.height / 2 }; })()`);
          if (d) await doublePress(page, d.x, d.y);
          await sleep(300);
          const back = await read();
          check("double tap", back);
          if (back.view && typeof back.view.split === "number") failures.push({ code: "flow", text: `after a double tap the device still keeps the share ${back.view.split}` });
        }
      } else if (vp.name === "medium") {
        let s = await until((x) => x.halves.length === 2);
        check("link", s);
        pairShown("link", s, "files", "terminal");
        if (s.divider && (s.divider.min !== 240 || s.divider.label !== "Files height")) failures.push({ code: "flow", text: `the tablet's divider reads ${s.divider.label}, ${s.divider.min} to ${s.divider.max}` });
        if (s.lit.join() !== "Close Files,Close Terminal") failures.push({ code: "shows", text: `the pane bar lights ${JSON.stringify(s.lit)}, not Files and Terminal` });
        shot = step("pair");
        await splitShot(page, shot);
        if (s.divider) {
          const before = s.divider.now;
          const rows = s.rows;
          await dragDivider(page, s.divider.x, s.divider.y, -60);
          s = await until((x) => x.divider?.now !== before);
          check("touch drag", s);
          if (s.divider?.now !== Math.max(s.divider?.min ?? 0, before - 60)) failures.push({ code: "flow", text: `a finger's drag of 60 px up left the divider at ${s.divider?.now}, from ${before}` });
          if (typeof s.view?.split !== "number") failures.push({ code: "flow", text: "the device keeps no divider place after the drag" });
          await sleep(300);
          const later = await read();
          if (rows !== null && later.rows !== null && later.rows <= rows) warnings.push({ code: "rows", text: `the terminal kept ${later.rows} rows after its half grew (from ${rows})` });
          shot = step("dragged");
          await splitShot(page, shot);
        }
        const lit = await page.locate('.pane-bar-btn.on[title="Close Files"]');
        if (!lit) failures.push({ code: "shows", text: "no lit Files in the pane bar" });
        else {
          await page.press(lit.x, lit.y);
          s = await until((x) => x.halves.length !== 2);
          check("close files", s);
          if (!sameUrl(s.path, P("shell")) || s.divider) failures.push({ code: "flow", text: `a tap on the lit Files left ${s.path}${s.divider ? " with the divider" : ""}, not the Terminal alone` });
        }
      } else {
        // The laptop: the Terminal alone, then the cards above it, Outputs, a file.
        let s = await read();
        check("terminal", s);
        if (s.divider || s.halves.length) failures.push({ code: "flow", text: "the Terminal alone shows a divider" });
        const rail = await page.locate('[data-testid="topbar-rail"]');
        if (!rail || !(await page.evaluate<boolean>(`document.querySelector('[data-testid="topbar-rail"]')?.getAttribute("aria-label") === "Show session rail"`))) failures.push({ code: "shows", text: "with the Terminal alone the title bar has no Show session rail" });
        if (rail) await page.press(rail.x, rail.y);
        s = await until((x) => x.halves.length === 2);
        check("cards above the Terminal", s);
        pairShown("cards above the Terminal", s, "details", "terminal");
        if (!sameUrl(s.path, P("details?below=shell"))) failures.push({ code: "url", text: `Show session rail gave ${s.path}, not the cards above the Terminal` });
        await splitShot(page, step("cards"));
        const outputs = await page.locate('#fd-split-upper a.side-card-title[href*="/outputs"]');
        if (outputs) await page.press(outputs.x, outputs.y);
        else await page.evaluate(`history.pushState(history.state, "", ${JSON.stringify(P("outputs?below=shell"))}); dispatchEvent(new PopStateEvent("popstate")); true`);
        s = await until((x) => x.path.includes("/outputs"));
        if (!sameUrl(s.path, P("outputs?below=shell"))) failures.push({ code: "url", text: `Outputs in the upper half gave ${s.path}` });
        const file = await page.locate(`#fd-split-upper a[href^="/c/${chat}/files/"]`);
        if (file) await page.press(file.x, file.y);
        else {
          warnings.push({ code: "flow", text: "Outputs lists no file of the chat's folder; the flow opens the file's link" });
          await page.navigate(base + pair);
        }
        s = await until((x) => x.halves.some((h) => h.kind === "files"));
        path = s.path;
        check("file above the Terminal", s);
        pairShown("file above the Terminal", s, "files", "terminal");
        if (!/^\/c\/[^/]+\/files\/.+\?below=shell$/.test(s.path)) failures.push({ code: "url", text: `the file opened at ${s.path}, not in the half above the Terminal` });
        if (s.divider?.label !== "Files height") failures.push({ code: "a11y", text: `the divider is named ${JSON.stringify(s.divider?.label)}, not "Files height"` });
        if (vp.width === 1280 && (s.side?.width !== 512 || (s.main ?? 0) < 519)) failures.push({ code: "flow", text: `at 1280 px the column is ${s.side?.width} px and the chat ${s.main} px, not 512 and 520` });
        if (s.lit.join() !== "Close terminal") failures.push({ code: "shows", text: `the title bar lights ${JSON.stringify(s.lit)}, not Close terminal` });
        shot = step("pair");
        await splitShot(page, shot);
        // The drag: the divider moves, the chat's width does not, the device keeps the share, xterm follows.
        if (s.divider) {
          // xterm refits 60 ms after its box last changed: read its rows once they hold.
          await sleep(500);
          s = await read();
          const before = s.divider!.now;
          const main = s.main;
          const rows = s.rows;
          await dragDivider(page, s.divider!.x, s.divider!.y, -120);
          s = await until((x) => x.divider?.now !== before);
          check("drag", s);
          const want = Math.max(s.divider?.min ?? 0, before - 120);
          if (s.divider?.now !== want) failures.push({ code: "flow", text: `a drag of 120 px up left the divider at ${s.divider?.now}, expected ${want}` });
          if (s.main !== main) failures.push({ code: "flow", text: `the drag changed the chat's width from ${main} to ${s.main}` });
          if (typeof s.view?.split !== "number") failures.push({ code: "flow", text: "the device keeps no divider place after the drag" });
          await sleep(400);
          const later = await read();
          details.rows = { before: rows, after: later.rows };
          if (rows !== null && later.rows !== null && later.rows <= rows) failures.push({ code: "flow", text: `the terminal kept ${later.rows} rows after its half grew by 120 px (from ${rows})` });
          shot = step("dragged");
          await splitShot(page, shot);
          // The keys on the focused divider, then the double-click.
          await page.evaluate(`document.querySelector('[data-testid="split-divider"]').focus()`);
          for (const key of ["ArrowDown", "ArrowUp", "ArrowUp", "Home", "End", "ArrowDown"]) {
            const b = (await read()).divider;
            if (!b) break;
            const wantKey = key === "Home" ? b.min : key === "End" ? b.max : Math.min(b.max, Math.max(b.min, b.now + (key === "ArrowDown" ? 16 : -16)));
            const vk = SPLIT_KEYS[key]!;
            await page.send("Input.dispatchKeyEvent", { type: "rawKeyDown", key, code: key, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk });
            await page.send("Input.dispatchKeyEvent", { type: "keyUp", key, code: key, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk });
            await sleep(150);
            const a = await read();
            check(`key ${key}`, a);
            if (a.divider?.now !== wantKey) failures.push({ code: "flow", text: `${key} left the divider at ${a.divider?.now}, expected ${wantKey}` });
            if (!a.divider?.focused) failures.push({ code: "flow", text: `${key}: the divider lost the focus (${a.focus})` });
          }
          shot = step("focus");
          await maskMachine(page);
          await page.screenshot(shot).catch(() => {});
          const d = (await read()).divider;
          if (d) await doublePress(page, d.x, d.y);
          s = await read();
          check("double-click", s);
          if (s.divider && s.divider.now !== Math.round((s.side?.height ?? 0) / 2)) failures.push({ code: "flow", text: `a double-click left the divider at ${s.divider.now}, not equal halves (${Math.round((s.side?.height ?? 0) / 2)})` });
          if (s.view && typeof s.view.split === "number") failures.push({ code: "flow", text: `after the double-click the device still keeps the share ${s.view.split}` });
        }
        // A reload keeps the pair; Back gives the pair before, Forward the file again.
        await page.reload();
        await waitShown(page, ["terminal-pane", "file-download"]);
        s = await until((x) => x.halves.length === 2);
        check("reload", s);
        pairShown("reload", s, "files", "terminal");
        if (!sameUrl(s.path, path)) failures.push({ code: "url", text: `the reload moved to ${s.path}` });
        const hist = await page.history();
        const back = hist.entries[hist.currentIndex - 1];
        if (back) {
          await page.goToEntry(back.id);
          s = await until((x) => x.path.includes("/outputs"));
          check("back", s);
          pairShown("back", s, "details", "terminal");
          if (!sameUrl(s.path, P("outputs?below=shell"))) failures.push({ code: "url", text: `Back gave ${s.path}, not Outputs above the Terminal` });
          const fwd = (await page.history()).entries;
          const next = fwd[hist.currentIndex];
          if (next) await page.goToEntry(next.id);
          s = await until((x) => x.halves.some((h) => h.kind === "files"));
          check("forward", s);
          pairShown("forward", s, "files", "terminal");
        } else failures.push({ code: "flow", text: "no history entry before the file's pair" });
        // Swap: Ctrl+K puts search in the half that is not the Terminal; its Close gives the column to the Terminal.
        await page.evaluate(`document.querySelector('[data-testid="composer-input"]')?.focus()`);
        await page.send("Input.dispatchKeyEvent", { type: "rawKeyDown", key: "k", code: "KeyK", modifiers: 2, windowsVirtualKeyCode: 75, nativeVirtualKeyCode: 75 });
        await page.send("Input.dispatchKeyEvent", { type: "keyUp", key: "k", code: "KeyK", modifiers: 2, windowsVirtualKeyCode: 75, nativeVirtualKeyCode: 75 });
        s = await until((x) => x.halves.some((h) => h.kind === "search"));
        check("swap", s);
        pairShown("swap", s, "search", "terminal");
        if (!sameUrl(s.path, P("search?below=shell"))) failures.push({ code: "url", text: `Ctrl+K gave ${s.path}, not search above the Terminal` });
        if (s.focus !== "search-input" && !(await page.evaluate<boolean>(`!!document.activeElement?.closest('[data-testid="search"]')`))) failures.push({ code: "flow", text: `after Ctrl+K the focus is on ${s.focus}, not the search field` });
        if (s.divider?.label !== "Search height") failures.push({ code: "a11y", text: `the divider is named ${JSON.stringify(s.divider?.label)}, not "Search height"` });
        shot = step("swap");
        await splitShot(page, shot);
        const close = await page.locate('#fd-split-upper [aria-label="Close search"]');
        if (!close) failures.push({ code: "shows", text: "the search half has no Close search" });
        else {
          await page.press(close.x, close.y);
          s = await until((x) => x.halves.length !== 2);
          check("close search", s);
          if (s.divider || !s.terminal || !s.path.startsWith(P("shell"))) failures.push({ code: "flow", text: `Close search left ${s.path}${s.divider ? " with the divider" : ""}, not the Terminal alone` });
        }
        // The window narrows step by step, on the file's pair.
        await page.navigate(base + path);
        await until((x) => x.halves.length === 2);
        const narrow: Record<string, unknown> = {};
        // The laptop's column from 1,088 px (the sidebar docked) and from 840 px (the sidebar a drawer); over the chat
        // from 1,000 to 1,087 px; a window from 600 to 839 px is the tablet's size class, its docked pane holding the
        // pair (the chat as narrow as the tablet's rule makes it); under 600 px the phone's, with no panel beside the chat.
        for (const w of [1200, 1088, 1050, 900, 700, 560, vp.width]) {
          await splitWindow(page, w);
          s = await read();
          check(`${w} px`, s);
          narrow[w] = { split: s.split, side: s.side?.width ?? null, main: s.main, over: s.over, lit: s.lit };
          const column = w >= 1088 || (w < 1000 && w >= 840);
          if (column) {
            pairShown(`${w} px`, s, "files", "terminal");
            if ((s.main ?? 0) < 519) failures.push({ code: "flow", text: `at ${w} px the chat is ${s.main} px, under 520` });
            const col = w >= 1000 ? Math.min(Math.max(420, Math.round(w * 0.4)), 720, w - 248 - 520) : Math.min(Math.max(420, Math.round(w * 0.4)), 720, w - 520);
            if (s.side?.width !== Math.max(320, col)) failures.push({ code: "flow", text: `at ${w} px the column is ${s.side?.width} px, expected ${Math.max(320, col)}` });
          } else if (w >= 1000) {
            if (s.halves.length || s.divider) failures.push({ code: "flow", text: `at ${w} px (over the chat) the panel still shows two halves` });
            if (s.terminal) failures.push({ code: "flow", text: `at ${w} px the Terminal shows; over the chat only the URL's own view shows` });
            if (s.lit.join() !== "Close Files") failures.push({ code: "shows", text: `at ${w} px the pane bar lights ${JSON.stringify(s.lit)}, not Files alone` });
          } else if (w >= 600) {
            pairShown(`${w} px`, s, "files", "terminal");
            if (!s.sideClass?.startsWith("side-pane split")) failures.push({ code: "flow", text: `at ${w} px the pair is not in the docked pane (${s.sideClass})` });
          } else {
            if (s.side || s.halves.length || s.divider || s.terminal) failures.push({ code: "flow", text: `at ${w} px (the phone's size class) the panel still shows beside the chat` });
          }
          if (!sameUrl(s.path, path)) failures.push({ code: "url", text: `at ${w} px the URL became ${s.path}` });
          if ([1088, 1050, 900, 700, 560].includes(w)) await splitShot(page, step(`narrow-${w}`));
        }
        details.narrow = narrow;
      }
      details.steps = steps;
      stateFindings(await page.probe(), { ...vp }, failures);
      issueFindings(page.takeIssues(), failures);
      quietFindings(wire, since, await recorder(page), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note =
    vp.name === "phone"
      ? `${vp.width}x${vp.height}: a pair's link shows the file's own page, no divider, no second view; nothing sent`
      : look
        ? `${vp.width}x${vp.height} ${look}: the file above the Terminal`
        : vp.name === "medium"
          ? `${vp.width}x${vp.height} touch: the pair from a link, both buttons lit, the grip, a finger's drag, the lit Files closing its half; nothing sent`
          : `${vp.width}x${vp.height}: the Terminal, the cards above it, Outputs, a file; the divider by drag and keys, a double-click; reload, Back and Forward; Ctrl+K swaps; Close search; the window narrowed to 700 px and back; nothing sent`;
  return finish({ kind: "flow", name: "split-panel", route: "shell", scene, size: sizeTag(vp), theme, path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * Review U4 (FIX-U4's fixer round): the rules the review found and this round fixed, on the real page. The laptop
 * (1280x800): Ctrl+backslash with the divider focused, and after a mouse drag of it (the focus on the body), closes
 * nothing, and with the focus in the file's half it closes that half; from /c/<chat>/details (the cards at rest)
 * Ctrl+backtick opens the Terminal alone, as from /c/<chat>; Show session rail from the side chat alone puts the cards
 * above it, its box at the column's foot; a letter in the side box of the half that is not the URL's own view makes it
 * that view (a replace, no new entry) and Ctrl+K then takes the other half; a back row whose target's kind the other
 * half shows gives the target the whole column; the search pane as the other half keeps its text and its scope; a
 * 1280x380 window folds the file's half to a head with the file's name; Settings' shortcut list says where Close
 * focused pane acts. The tablet (1194x834 touch): a file's half and the Terminal's below it have no empty pane head,
 * and Context's head keeps its back row and Close. Nothing acts (the side box's draft frames only).
 */
async function splitReviewFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const chat = EX.chat;
  const P = (rest: string) => `/c/${chat}/${rest}`;
  const pair = P(`files/${SPLIT_FILE}?below=shell`);
  const fileName = SPLIT_FILE.slice(SPLIT_FILE.lastIndexOf("/") + 1);
  let path = pair;
  let shot: string | undefined;
  const steps: Record<string, unknown>[] = [];
  const step = (label: string) => shotName(scene, "split-review", vp, theme, `${vp.width}-${label}`);
  try {
    await withPage(vp, theme, async (page, wire) => {
      const read = async () => JSON.parse(await page.evaluate<string>(SPLIT_STATE)) as SplitState;
      const until = async (ok: (s: SplitState) => boolean, ms = 6000) => {
        const end = Date.now() + ms;
        let s = await read();
        while (!ok(s) && Date.now() < end) {
          await sleep(100);
          s = await read();
        }
        return s;
      };
      const halves = (s: SplitState) => s.halves.map((h) => `${h.slot} ${h.kind}`).join();
      const check = (label: string, s: SplitState) => {
        steps.push({ step: label, path: s.path, halves: halves(s), divider: s.divider?.now ?? null, focus: s.focus });
        if (s.scrollWidth > s.clientWidth) fail(`${label}: the page scrolls sideways (${s.scrollWidth} > ${s.clientWidth})`, "overflow");
        if (s.notices) fail(`${label}: a 5.4 line shows`, "notice");
      };
      const open = async (to: string, want: string[]) => {
        path = to;
        await page.navigate(base + to);
        await waitShown(page, want);
        await sleep(300);
      };
      /** One key with Ctrl (Linux: the page's Cmd is Ctrl here). */
      const ctrlKey = async (key: string, code: string, vk: number) => {
        await page.send("Input.dispatchKeyEvent", { type: "rawKeyDown", key, code, modifiers: 2, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk });
        await page.send("Input.dispatchKeyEvent", { type: "keyUp", key, code, modifiers: 2, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk });
        await sleep(400);
      };
      const backslash = () => ctrlKey("\\", "Backslash", 220);

      // v0.6 touch: the large tablet's column form is the laptop's layout (its keys with a hardware keyboard).
      if (vp.touch && vp.name !== "laptop") {
        // The tablet: no head that would hold only Close in a half; a back row keeps its head.
        await open(pair, ["terminal-pane"]);
        let s = await until((x) => x.halves.length === 2);
        check("file and Terminal", s);
        const heads = JSON.parse(await page.evaluate<string>(`JSON.stringify([...document.querySelectorAll("#fd-side > .split-half")].map((h) => h.getAttribute("data-kind") + " " + !!h.querySelector(".side-pane-head")))`)) as string[];
        details.heads = heads;
        if (heads.join() !== "files false,terminal false") fail(`the file's half and the Terminal's below it show ${JSON.stringify(heads)}: a side panel view's pane head that holds only Close is still drawn`);
        if (s.lit.join() !== "Close Files,Close Terminal") fail(`the pane bar lights ${JSON.stringify(s.lit)}, not Files and Terminal (the lit Files closes the half)`, "shows");
        shot = step("no-empty-head");
        await splitShot(page, shot);
        await open(P("context?below=shell"), ["terminal-pane"]);
        s = await until((x) => x.halves.length === 2);
        check("Context and Terminal", s);
        const ctx = await page.evaluate<boolean>(`!!document.querySelector('#fd-split-upper .side-pane-head > .side-back') && !!document.querySelector('#fd-split-upper .side-pane-head [aria-label="Close Context"]')`);
        if (!ctx) fail("Context's half on the tablet lost its head with the back row and Close");
        await splitShot(page, step("context-head"));
      } else {
        // 1. Close focused pane on the divider: nothing closes; in the file's half: that half.
        await open(pair, ["terminal-pane"]);
        let s = await until((x) => x.halves.length === 2);
        check("pair", s);
        await page.evaluate(`document.querySelector('[data-testid="split-divider"]')?.focus(); true`);
        await backslash();
        s = await read();
        check("divider focused, Ctrl+backslash", s);
        if (!sameUrl(s.path, pair) || halves(s) !== "upper files,lower terminal") fail(`Ctrl+backslash on the focused divider left ${s.path} (${halves(s)}), not the pair`);
        if (s.divider) {
          await dragDivider(page, s.divider.x, s.divider.y, -40);
          await page.evaluate(`document.activeElement instanceof HTMLElement && document.activeElement.blur(); true`);
          s = await read();
          const focusAfterDrag = s.focus;
          await backslash();
          s = await read();
          check("after a drag, Ctrl+backslash", s);
          details.afterDrag = { focus: focusAfterDrag, path: s.path };
          if (!sameUrl(s.path, pair) || halves(s) !== "upper files,lower terminal") fail(`Ctrl+backslash after a drag of the divider left ${s.path} (${halves(s)}), not the pair`);
        } else fail("the pair shows no divider", "shows");
        const inFile = await page.evaluate<boolean>(`(() => { const el = document.querySelector('#fd-split-upper a, #fd-split-upper button'); el?.focus(); return !!el && document.activeElement === el; })()`);
        if (!inFile) fail("no control in the file's half takes the focus");
        await backslash();
        s = await until((x) => x.halves.length !== 2);
        check("file's half focused, Ctrl+backslash", s);
        if (!sameUrl(s.path, P("shell")) || !s.terminal) fail(`Ctrl+backslash in the file's half left ${s.path}, not the Terminal alone`);

        // 2. The cards at rest at /c/<chat>/details: Ctrl+backtick opens the Terminal alone, as from /c/<chat>.
        await open(P("details"), ["side-panel"]);
        await page.evaluate(`document.querySelector('[data-testid="composer-input"]')?.focus(); true`);
        await ctrlKey("`", "Backquote", 192);
        s = await until((x) => x.terminal);
        check("Ctrl+backtick from the cards", s);
        if (!sameUrl(s.path, P("shell")) || s.halves.length) fail(`Ctrl+backtick from /c/<chat>/details gave ${s.path} (${halves(s) || "one view"}), not the Terminal alone`);

        // 3. Show session rail from the side chat alone: the cards above it, its box at the column's foot.
        await open(P("btw"), ["side-chat"]);
        const rail = await page.locate('[data-testid="topbar-rail"]');
        if (!rail) fail("with the side chat alone the title bar has no session rail toggle", "shows");
        else {
          await page.press(rail.x, rail.y);
          s = await until((x) => x.halves.length === 2);
          check("Show session rail from the side chat", s);
          if (!sameUrl(s.path, P("details?below=btw")) || halves(s) !== "upper details,lower side") fail(`Show session rail from the side chat gave ${s.path} (${halves(s)}), not the cards above the side chat`);
          const foot = JSON.parse(await page.evaluate<string>(`JSON.stringify((() => { const box = document.querySelector('#fd-split-lower [data-testid="side-box"]'); const side = document.getElementById("fd-side"); return box && side ? { box: Math.round(box.getBoundingClientRect().bottom), side: Math.round(side.getBoundingClientRect().bottom) } : null; })())`)) as { box: number; side: number } | null;
          details.sideFoot = foot;
          if (!foot || foot.side - foot.box > 24) fail(`the side chat's box ends at ${foot?.box} px, not at the column's foot (${foot?.side} px)`);
          shot = step("rail-above-side");
          await splitShot(page, shot);
        }

        // 4. A letter in the side box of the other half makes it the URL's own view; Ctrl+K then takes the other half.
        await open(P("context?above=btw"), ["side-chat"]);
        s = await until((x) => x.halves.length === 2);
        check("Context with the side chat above", s);
        const before = (await page.history()).entries.length;
        await scPress(page, '#fd-split-upper [data-testid="side-input"]');
        const markTyping = wire.mark();
        await page.send("Input.insertText", { text: "Which file holds the cap" });
        s = await until((x) => x.path.includes("/btw"));
        check("typed in the side box", s);
        if (!sameUrl(s.path, P("btw?below=context")) || halves(s) !== "upper side,lower details") fail(`typing in the side box of the other half gave ${s.path} (${halves(s)}), not the side chat as the URL's own view in its place`);
        const after = (await page.history()).entries.length;
        if (after !== before) fail(`typing in the side box added ${after - before} history entries (a replace adds none)`);
        const typedActs = acting(wire.framesSince(markTyping));
        if (typedActs.length) fail(`typing in the side box sent ${clipList(typedActs.map(frameText))}`, "frames");
        await ctrlKey("k", "KeyK", 75);
        s = await until((x) => x.halves.some((h) => h.kind === "search"));
        check("Ctrl+K after typing", s);
        if (!sameUrl(s.path, P("search?above=btw")) || halves(s) !== "upper side,lower search") fail(`Ctrl+K after typing in the side chat gave ${s.path} (${halves(s)}), not search in place of Context with the side chat kept`);
        shot = step("used-last");
        await splitShot(page, shot);
        // The side box's draft goes back to empty (the server holds it for the scene's later checks).
        await scPress(page, '#fd-split-upper [data-testid="side-input"]');
        await page.send("Input.dispatchKeyEvent", { type: "rawKeyDown", key: "a", code: "KeyA", modifiers: 2, windowsVirtualKeyCode: 65, nativeVirtualKeyCode: 65 });
        await page.send("Input.dispatchKeyEvent", { type: "keyUp", key: "a", code: "KeyA", modifiers: 2, windowsVirtualKeyCode: 65, nativeVirtualKeyCode: 65 });
        await page.send("Input.dispatchKeyEvent", { type: "rawKeyDown", key: "Backspace", code: "Backspace", windowsVirtualKeyCode: 8, nativeVirtualKeyCode: 8 });
        await page.send("Input.dispatchKeyEvent", { type: "keyUp", key: "Backspace", code: "Backspace", windowsVirtualKeyCode: 8, nativeVirtualKeyCode: 8 });
        await sleep(1200);
        const left = await page.evaluate<string>(`document.querySelector('[data-testid="side-input"]')?.value ?? ""`);
        if (left !== "") fail(`the side box still holds ${JSON.stringify(left)} after it was emptied`);

        // 5. A back row whose target's kind the other half shows: the target alone.
        await open(P("details?below=uploads"), ["side-panel"]);
        s = await until((x) => x.halves.length === 2);
        check("cards above Uploads", s);
        const back = await page.locate("#fd-split-lower a.side-back");
        if (!back) fail("the Uploads half has no back row", "shows");
        else {
          await page.press(back.x, back.y);
          s = await until((x) => x.halves.length !== 2);
          check("Uploads' back row", s);
          if (!sameUrl(s.path, P("details")) || s.halves.length) fail(`"< Uploads" below the cards gave ${s.path} (${halves(s) || "one view"}), not the cards alone`);
        }
        await open(P(`details?below=files/${SPLIT_FILE}`), ["side-panel"]);
        s = await until((x) => x.halves.length === 2);
        const fileBack = await page.locate("#fd-split-lower a.side-back");
        const fileBackName = await page.evaluate<string>(`document.querySelector("#fd-split-lower a.side-back")?.getAttribute("aria-label") ?? ""`);
        if (!fileBack) fail("the file's half has no back row", "shows");
        else {
          await page.press(fileBack.x, fileBack.y);
          s = await until((x) => x.halves.length !== 2);
          check("the file's back row", s);
          const want = fileBackName === "Back to Outputs" ? P("outputs") : P("details");
          details.fileBack = { name: fileBackName, path: s.path };
          if (!sameUrl(s.path, want) || s.halves.length) fail(`the file's back row (${fileBackName}) below the cards gave ${s.path} (${halves(s) || "one view"}), not ${want} alone`);
        }

        // 6. The search pane as the other half keeps its text and its scope.
        await open(P("search?q=upl&scope=files&above=outputs"), ["search"]);
        s = await until((x) => x.halves.length === 2);
        check("search below Outputs", s);
        const searchState = `JSON.stringify({ q: document.querySelector('#fd-side [data-testid="search-input"]')?.value ?? null, files: document.querySelector('#fd-side [data-testid="search-scope-files"]')?.getAttribute("aria-checked") ?? null })`;
        const was = JSON.parse(await page.evaluate<string>(searchState)) as { q: string | null; files: string | null };
        const pick = await page.locate(`#fd-split-upper a[href^="/c/${chat}/files/"]`);
        if (!pick) fail("Outputs lists no file to press", "shows");
        else {
          await page.press(pick.x, pick.y);
          s = await until((x) => x.path.includes("/files/"));
          check("a file from Outputs", s);
          await sleep(300);
          const now = JSON.parse(await page.evaluate<string>(searchState)) as { q: string | null; files: string | null };
          details.scope = { was, now, path: s.path };
          if (!/\/files\/.+\?below=search$/.test(s.path)) fail(`a file from Outputs gave ${s.path}, not the file above search`);
          if (was.q !== "upl" || was.files !== "true") fail(`the link's search shows ${JSON.stringify(was)}, not upl with Files on`);
          if (now.q !== "upl" || now.files !== "true") fail(`as the other half the search pane shows ${JSON.stringify(now)}, not its text and its scope kept (upl, Files on)`);
        }

        // 7. A short window folds the file's half to a head with the file's own name.
        // (A navigation puts the viewport's own size back, so the window is made short after it.)
        await open(P(`shell?above=files/${SPLIT_FILE}`), ["terminal-pane"]);
        await splitWindow(page, vp.width, 380);
        s = await until((x) => x.split === "folded-upper");
        check("1280x380", s);
        const head = JSON.parse(await page.evaluate<string>(`JSON.stringify((() => { const h = document.querySelector("#fd-split-upper.is-folded .split-fold-head"); if (!h) return null; const r = h.getBoundingClientRect(); const half = h.parentElement.getBoundingClientRect(); return { text: h.textContent, height: Math.round(r.height), inside: r.top >= half.top - 1 && r.bottom <= half.bottom + 1, link: !!h.closest("a") }; })())`)) as { text: string; height: number; inside: boolean; link: boolean } | null;
        details.foldHead = head;
        if (s.split !== "folded-upper") fail(`at 1280x380 the split is ${s.split}, not the file's half folded`);
        if (!head || head.text !== fileName || head.link || head.height < 30) fail(`the folded file's half shows ${JSON.stringify(head)}, not a head with ${fileName}`);
        shot = step("fold-head");
        await splitShot(page, shot);
        await splitWindow(page, vp.width, vp.height);

        // 8. Settings' shortcut list: off macOS, Close focused pane says where it acts.
        await page.navigate(`${base}/settings/general/shortcuts`);
        await waitShown(page, ["settings"], 6000);
        const keys = JSON.parse(await page.evaluate<string>(`JSON.stringify([...document.querySelectorAll(".set-keys .set-key")].map((r) => ({ words: (r.querySelector("dt")?.firstChild?.textContent || "").trim(), note: (r.querySelector(".set-key-note")?.textContent || "").trim(), keys: [...r.querySelectorAll(".set-combo")].map((c) => [...c.querySelectorAll("kbd")].map((k) => k.textContent)) })))`)) as { words: string; note: string; keys: string[][] }[];
        const row = keys.find((r) => r.words === "Close focused pane");
        details.shortcut = row ?? null;
        if (!row || JSON.stringify(row.keys) !== JSON.stringify([["Ctrl", "\\"]]) || row.note !== "Outside the terminal pane") fail(`Settings' shortcut list has ${row ? JSON.stringify(row) : "no row"} for Close focused pane, not Ctrl backslash with "Outside the terminal pane"`);
        await maskMachine(page);
        await page.screenshot(step("shortcuts")).catch(() => {});
      }
      details.steps = steps;
      stateFindings(await page.probe(), { ...vp }, failures);
      issueFindings(page.takeIssues(), failures);
      const acts = acting(wire.framesSince(0));
      if (acts.length) fail(`the page sent ${clipList(acts.map(frameText))}`, "frames");
      const posts = wire.httpSince(0).filter((h) => MUTATING_METHODS.has(h.method));
      if (posts.length) fail(`the page sent ${clipList(posts.map(httpText))}`, "frames");
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = vp.touch
    ? `${vp.width}x${vp.height} touch: no empty pane head in a half, Context's head kept; nothing acts`
    : `${vp.width}x${vp.height}: Ctrl+backslash on the divider closes nothing; the cards at rest open alone; Show session rail above the side chat; typing makes a half the URL's own view; back rows; the search scope kept; the fold's head; the shortcut's note; nothing acts`;
  return finish({ kind: "flow", name: "split-review", route: "shell", scene, size: sizeTag(vp), theme, path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

// ---------------------------------------------------------------------------------------------------------------
// Row 93: the docked panes slide as they open and close; row 92: "kitespan" at the top left is the link to Home

/**
 * Every animation frame while window.__slide.on: when it came (t, the frame's time), how long the page worked on it
 * (from its animation-frame callback to the end of its style, layout and paint: a task posted from the callback runs
 * after them), the shell's data-slide, and with `geo` the docked panes' boxes (the sidebar, the pane on the right, a box
 * that slides out), the chat column's and the pane bar's, and the handles' visibility. And every data-slide that an
 * element wears from the document's start (a load or a reload must show none).
 */
const SLIDE_SAMPLER = `(() => {
  const S = (window.__slide = { on: false, geo: true, frames: [], marks: 0 });
  new MutationObserver((list) => {
    for (const m of list) if (m.target.getAttribute && m.target.getAttribute("data-slide")) S.marks++;
  }).observe(document, { subtree: true, attributes: true, attributeFilter: ["data-slide"] });
  const ch = new MessageChannel();
  ch.port1.onmessage = (e) => {
    const f = S.frames[e.data.i];
    if (f) f.work = Math.round((performance.now() - e.data.s) * 100) / 100;
  };
  const box = (el) => {
    if (!el) return null;
    const r = el.getBoundingClientRect();
    return { left: Math.round(r.left * 10) / 10, right: Math.round(r.right * 10) / 10 };
  };
  const pane = (el) => {
    if (!el) return null;
    const m = /inset\\(\\S+ ([\\d.]+)px/.exec(getComputedStyle(el).clipPath);
    return { ...box(el), w: el.offsetWidth, clip: m ? parseFloat(m[1]) : 0, ghost: el.inert, hidden: el.getAttribute("aria-hidden") === "true", ids: el.querySelectorAll("[id], [data-testid]").length + (el.id ? 1 : 0) };
  };
  const loop = (t) => {
    if (S.on) {
      const s = performance.now();
      const shell = document.querySelector(".shell");
      const f = { t, slide: (shell && shell.getAttribute("data-slide")) || "" };
      if (S.geo && shell) {
        const kids = [...shell.children];
        f.nav = pane(kids.find((e) => e.matches("nav.sidebar")));
        f.side = pane(kids.find((e) => e.matches("aside.side-col, aside.side-pane:not(.side-over)")));
        const col = kids.find((e) => e.classList.contains("main-col"));
        f.main = box(col);
        const chat = col && col.querySelector(":scope > main");
        f.chat = chat ? { ...box(chat), w: chat.offsetWidth } : null;
        f.bar = box(kids.find((e) => e.classList.contains("pane-bar")));
        f.handles = kids.filter((e) => e.classList.contains("pane-handle")).map((h) => (h.classList.contains("pane-handle-start") ? "start " : "end ") + getComputedStyle(h).visibility);
        f.ghosts = kids.filter((e) => e.inert).length;
      }
      ch.port2.postMessage({ i: S.frames.push(f) - 1, s });
    }
    requestAnimationFrame(loop);
  };
  requestAnimationFrame(loop);
})()`;

interface SlideBox {
  left: number;
  right: number;
  w: number;
  clip: number;
  ghost: boolean;
  hidden: boolean;
  ids: number;
}
interface SlideFrame {
  t: number;
  work?: number;
  slide: string;
  nav?: SlideBox | null;
  side?: SlideBox | null;
  main?: { left: number; right: number } | null;
  /** The chat (the shell's main) in its column. */
  chat?: { left: number; right: number; w: number } | null;
  bar?: { left: number; right: number } | null;
  handles?: string[];
  ghosts?: number;
}
/**
 * A slide's frames (from the first that wore the mark to the first after it): how many, their spacing (ms) and the
 * page's work per frame (ms); then the frame after the slide, where the chat takes its new width once (after a pane
 * closed), with its work and whether the frame after it came late.
 */
interface SlideCost {
  frames: number;
  ms: number;
  gapMax: number;
  gapMean: number;
  /** Frames more than 20 ms after the one before (a dropped frame). */
  late: number;
  workMax: number;
  workMean: number;
  endWork: number;
  endLate: boolean;
  /** The page's work on the frames after the slide (from its third on), for comparison. */
  idleMean: number;
  /** CDP Performance.getMetrics over the toggle (the click's render and the slide), per slide frame. */
  taskPerFrame: number;
  layoutPerFrame: number;
  stylePerFrame: number;
}

const r2 = (n: number) => Math.round(n * 100) / 100;

/** The frames of a slide: from the first that wears `word` in data-slide to the first after it (the end state). */
function slideSpan(frames: SlideFrame[], word: string): { during: SlideFrame[]; after: SlideFrame | null; before: SlideFrame | null } {
  const on = (f: SlideFrame) => f.slide.split(" ").includes(word);
  const a = frames.findIndex(on);
  if (a < 0) return { during: [], after: frames.at(-1) ?? null, before: frames[0] ?? null };
  let b = a;
  while (b < frames.length && on(frames[b]!)) b++;
  return { during: frames.slice(a, b), after: frames[b] ?? null, before: frames[a - 1] ?? null };
}

function slideCost(frames: SlideFrame[], word: string, m0: Record<string, number>, m1: Record<string, number>): SlideCost | null {
  const { during, after } = slideSpan(frames, word);
  if (!during.length) return null;
  const slide = after ? [...during, after] : during;
  const gaps = slide.slice(1).map((f, i) => f.t - slide[i]!.t);
  const work = during.map((f) => f.work ?? 0);
  const next = after ? frames[frames.indexOf(after) + 1] : undefined;
  const idle = frames.slice(frames.indexOf(slide.at(-1)!) + 3).map((f) => f.work ?? 0);
  const mean = (l: number[]) => r2(l.reduce((a, b) => a + b, 0) / Math.max(1, l.length));
  const per = (k: string) => r2(((m1[k] ?? 0) - (m0[k] ?? 0)) * 1000 / slide.length);
  return {
    frames: slide.length,
    ms: r2(slide.at(-1)!.t - slide[0]!.t),
    gapMax: r2(Math.max(0, ...gaps)),
    gapMean: mean(gaps),
    late: gaps.filter((g) => g > 20).length,
    workMax: r2(Math.max(0, ...work)),
    workMean: mean(work),
    endWork: r2(after?.work ?? 0),
    endLate: !!(after && next && next.t - after.t > 20),
    idleMean: mean(idle),
    taskPerFrame: per("TaskDuration"),
    layoutPerFrame: per("LayoutDuration"),
    stylePerFrame: per("RecalcStyleDuration"),
  };
}

/**
 * One slide's frames judged: `which` pane ("nav", the sidebar, or "side", the pane on the right) goes `open` or shut,
 * `w` px wide, its outer edge at the shell's left or at `edge` (the pane bar's left edge, or the window's right). It
 * slides: at least five frames between shut and open, its edge moving one way only, in about 200 ms; the chat column's
 * edge rides with the pane's; the pane keeps its own width all the way (so nothing in it wraps again), and the right
 * one shows nothing past its edge; a pane that closes slides out as an inert box hidden from assistive tech, with no id
 * or test id; its handle does not show meanwhile; at the end the box is gone and nothing is marked.
 */
function judgeSlide(label: string, frames: SlideFrame[], which: "nav" | "side", open: boolean, w: number, edge: number, fail: (text: string) => void) {
  const word = which === "nav" ? "sidebar" : "side";
  const { during, after } = slideSpan(frames, word);
  if (!during.length) return fail(`${label}: no slide (the shell never marked one)`);
  const inner = (b: SlideBox) => (which === "nav" ? b.right : b.left);
  const shut = which === "nav" ? 0 : edge;
  const full = which === "nav" ? w : edge - w;
  const mid = during.filter((f) => {
    const b = f[which];
    if (!b) return false;
    const x = inner(b);
    return x > Math.min(shut, full) + 1 && x < Math.max(shut, full) - 1;
  });
  if (mid.length < 5) fail(`${label}: only ${mid.length} frames between shut and open`);
  const ms = (after ?? during.at(-1)!).t - during[0]!.t;
  if (ms < 150 || ms > 320) fail(`${label}: the slide took ${Math.round(ms)} ms, not about 200`);
  let back = 0;
  for (let i = 1; i < mid.length; i++) {
    const d = inner(mid[i]![which]!) - inner(mid[i - 1]![which]!);
    const toward = (which === "nav") === open ? d : -d;
    if (toward < -0.5) back++;
  }
  if (back) fail(`${label}: the pane's edge moved back ${back} times`);
  // The chat keeps one width for the slide (it lays out once), inside its column.
  const chatWidths = new Set(mid.map((f) => f.chat?.w));
  if (chatWidths.size > 1) fail(`${label}: the chat took ${chatWidths.size} widths while the pane slid (${clipList([...chatWidths].map(String))})`);
  for (const f of mid) {
    if (f.chat && f.main && (f.chat.left < f.main.left - 1 || f.chat.right > f.main.right + 1)) fail(`${label}: at ${Math.round(f.t - during[0]!.t)} ms the chat (${f.chat.left} to ${f.chat.right}) runs out of its column (${f.main.left} to ${f.main.right})`);
    const b = f[which]!;
    if (b.w !== w) fail(`${label}: at ${Math.round(f.t - during[0]!.t)} ms the pane is ${b.w} px wide, not ${w} (its content would wrap again)`);
    if (f.main && Math.abs((which === "nav" ? f.main.left : f.main.right) - inner(b)) > 1) fail(`${label}: at ${Math.round(f.t - during[0]!.t)} ms the chat column's edge (${which === "nav" ? f.main.left : f.main.right}) is not the pane's (${inner(b)})`);
    if (which === "side" && b.right - b.clip > edge + 1) fail(`${label}: at ${Math.round(f.t - during[0]!.t)} ms the pane shows up to ${r2(b.right - b.clip)}, past its edge at ${edge}`);
    if (open && b.ghost) fail(`${label}: the pane that opens is inert`);
    if (!open && !(b.ghost && b.hidden && b.ids === 0)) fail(`${label}: the box that slides out is ${b.ghost ? "" : "not inert, "}${b.hidden ? "" : "not hidden from assistive tech, "}${b.ids ? `with ${b.ids} ids or test ids` : ""}`.replace(/, $/, ""));
    const h = f.handles?.find((x) => x.startsWith(which === "nav" ? "start" : "end"));
    if (h && !h.endsWith("hidden")) fail(`${label}: the pane's handle shows while it slides`);
  }
  if (!after) return fail(`${label}: the slide had not ended when the record did`);
  if (after.slide || after.ghosts) fail(`${label}: after the slide the shell is marked "${after.slide}" with ${after.ghosts} inert box(es)`);
  const end = after[which];
  if (open ? !end || Math.abs(inner(end) - full) > 1 || end.ghost : end) fail(`${label}: after the slide the pane is ${end ? `at ${inner(end)}` : "gone"}, expected ${open ? `at ${full}` : "gone"}`);
}

/** No slide at all: the shell never marked one, and no frame shows a pane between shut and open. */
function judgeNoSlide(label: string, frames: SlideFrame[], marks: number, fail: (text: string) => void) {
  const marked = frames.filter((f) => f.slide).length;
  if (marks || marked) fail(`${label}: the shell marked a slide (${marks} mark(s), ${marked} frame(s))`);
  if (frames.some((f) => f.ghosts)) fail(`${label}: an inert box slid out`);
}

/**
 * Row 93 at one size. A laptop (1100x800 dark; 1280x800 dark and light, with screenshots mid-slide and after): Hide
 * sidebar, Show sidebar, Hide session rail and Show session rail each slide (judgeSlide), the focus where it went
 * before (Show sidebar after Hide sidebar and back); a load and a reload slide nothing; a toggle while a handle drags
 * slides nothing; then on a long chat (about 10,000 elements) the four toggles again, each slide's frames and the page's
 * work per frame reported; then with Settings > Appearance > Reduce motion On and with the system's reduced motion, a
 * page whose toggles slide nothing (on the long chat, the instant toggle's own cost as the reference). The tablet
 * (834x1194, touch): the pane bar's Details opens the docked pane with a slide and a second tap closes it, the pane
 * never showing under the bar, and on the long chat the same with its frames. The phone (390x844): the Details sheet
 * slides no pane. Every size: no sideways overflow, nothing sent.
 */
async function paneSlideFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  const chat = `/c/${EX.chat}`;
  const shots = vp.width === WIDE_LAPTOP.width;
  let shot: string | undefined;
  const costs: Record<string, SlideCost | null> = {};
  details.costs = costs;
  const open = async (page: Page, reduce: "settings" | "system" | null = null) => {
    if (reduce === "settings")
      await page.send("Page.addScriptToEvaluateOnNewDocument", {
        source: `try { const k = "kitespan.settings"; const s = JSON.parse(localStorage.getItem(k) || "{}"); s.reduceMotion = "on"; localStorage.setItem(k, JSON.stringify(s)); } catch (e) {}`,
      });
    if (reduce === "system") await page.send("Emulation.setEmulatedMedia", { media: "screen", features: [{ name: "prefers-color-scheme", value: page.theme }, { name: "prefers-reduced-motion", value: "reduce" }] });
    await page.send("Page.addScriptToEvaluateOnNewDocument", { source: SLIDE_SAMPLER });
    await page.send("Performance.enable", {});
    await page.navigate(base + chat);
    await waitShown(page, ["conversation"]);
    await sleep(400);
  };
  const marks = (page: Page) => page.evaluate<number>("window.__slide.marks");
  /**
   * Press `sel` (or Ctrl+backtick, the Terminal pane's key, for "key") and record the frames of the next 500 ms (with
   * the panes' boxes when `geo`), and the CDP metrics.
   */
  const toggle = async (page: Page, sel: string, geo = true) => {
    const at = sel === "key" ? null : await page.locate(sel);
    if (!at && sel !== "key") {
      fail(`no ${sel} to press`, "shows");
      return null;
    }
    await page.evaluate(`(() => { const S = window.__slide; S.frames = []; S.geo = ${geo}; S.on = true; })()`);
    await sleep(50);
    const m0 = await mainThread(page);
    if (at) await page.press(at.x, at.y);
    else
      for (const type of ["rawKeyDown", "keyUp"]) await page.send("Input.dispatchKeyEvent", { type, key: "`", code: "Backquote", windowsVirtualKeyCode: 192, nativeVirtualKeyCode: 192, modifiers: 2 });
    await sleep(500);
    const m1 = await mainThread(page);
    const frames = JSON.parse(await page.evaluate<string>(`(() => { const S = window.__slide; S.on = false; return JSON.stringify(S.frames); })()`)) as SlideFrame[];
    return { frames, m0, m1 };
  };
  const focusOn = (page: Page) => page.evaluate<string | null>(`(() => { const a = document.activeElement; return a && a !== document.body ? a.getAttribute("data-testid") || a.getAttribute("aria-label") || a.tagName.toLowerCase() : null; })()`);
  /** The slide frozen at `ms` for a screenshot, then let go. */
  const shootMid = async (page: Page, sel: string, step: string) => {
    const at = await page.locate(sel);
    if (!at) return;
    await page.press(at.x, at.y);
    await page.evaluate(`new Promise((ok) => requestAnimationFrame(() => { for (const a of document.getAnimations()) { const t = a.effect && a.effect.target; if (t && t.matches && t.matches(".shell > .main-col, .shell > nav.sidebar, .shell > aside")) { a.pause(); a.currentTime = 90; } } ok(true); }))`);
    await sleep(50);
    await page.screenshot(shotName(scene, "pane-slide", vp, theme, `${step}-mid`));
    await page.evaluate(`(() => { for (const a of document.getAnimations()) if (a.playState === "paused") a.play(); })()`);
    await sleep(400);
    await page.screenshot((shot = shotName(scene, "pane-slide", vp, theme, `${step}-after`)));
  };
  try {
    await withPage(vp, theme, async (page, wire) => {
      const since = wire.mark();
      await open(page);
      if (await marks(page)) fail("the first paint marked a slide");
      if (vp.name === "phone") {
        const ring = await page.locate(".scr-ring");
        if (!ring) fail("the phone's header has no context ring to open Details", "shows");
        else {
          await page.evaluate(`(() => { const S = window.__slide; S.frames = []; S.on = true; })()`);
          await page.press(ring.x, ring.y);
          await sleep(500);
          const frames = JSON.parse(await page.evaluate<string>(`(() => { const S = window.__slide; S.on = false; return JSON.stringify(S.frames); })()`)) as SlideFrame[];
          judgeNoSlide("the phone's Details sheet", frames, await marks(page), fail);
          await page.key("Escape");
          await sleep(400);
        }
      } else if (vp.name === "medium") {
        const bar = (await page.evaluate<number | null>(`(() => { const b = document.querySelector(".pane-bar"); return b ? b.getBoundingClientRect().left : null; })()`)) ?? vp.width;
        // v0.6 touch: the pane's own width at this window (40% under 800 px).
        const paneW = mediumPane(vp.width);
        const opened = await toggle(page, '.pane-bar-btn[title="Details"]');
        if (opened) judgeSlide("Details opens", opened.frames, "side", true, paneW, bar, fail);
        const shut = await toggle(page, '.pane-bar-btn[title="Close Details"]');
        if (shut) judgeSlide("Details closes", shut.frames, "side", false, paneW, bar, fail);
        if (!sameUrl((await page.probe()).path, chat)) fail(`after Details closed the URL is ${(await page.probe()).path}`);
        if ((await page.evaluate<number>(LONG_CHAT)) < 9000) warnings.push({ code: "cost", text: "the long chat could not be built" });
        await sleep(400);
        for (const [sel, word, label] of [['.pane-bar-btn[title="Details"]', "side", "long chat: Details opens"], ['.pane-bar-btn[title="Close Details"]', "side", "long chat: Details closes"]] as const) {
          const r = await toggle(page, sel, false);
          costs[label] = r ? slideCost(r.frames, word, r.m0, r.m1) : null;
          if (r && !costs[label]) fail(`${label}: no slide`);
        }
        await page.evaluate(LONG_CHAT_GONE);
      } else if (vp.touch) {
        // v0.6 touch: the large tablet, the laptop's layout with no session rail and no keys: Hide and Show sidebar slide,
        // a reload slides nothing.
        const R = vp.width;
        const hid = await toggle(page, '[data-testid="sidebar-hide"]');
        if (hid) judgeSlide("Hide sidebar", hid.frames, "nav", false, 248, R, fail);
        await page.reload();
        await waitShown(page, ["conversation"]);
        await sleep(400);
        if (await marks(page)) fail("the reload marked a slide");
        const shown = await toggle(page, '[data-testid="sidebar-show"]');
        if (shown) judgeSlide("Show sidebar", shown.frames, "nav", true, 248, R, fail);
      } else {
        const R = vp.width;
        // Hide sidebar and Show sidebar: the focus goes to the other one, as before.
        const hid = await toggle(page, '[data-testid="sidebar-hide"]');
        if (hid) judgeSlide("Hide sidebar", hid.frames, "nav", false, 248, R, fail);
        if ((await focusOn(page)) !== "sidebar-show") fail(`after Hide sidebar the focus is on ${await focusOn(page)}, not Show sidebar`);
        // A reload with the sidebar hidden slides nothing.
        await page.reload();
        await waitShown(page, ["conversation"]);
        await sleep(400);
        if (await marks(page)) fail("the reload marked a slide");
        const shown = await toggle(page, '[data-testid="sidebar-show"]');
        if (shown) judgeSlide("Show sidebar", shown.frames, "nav", true, 248, R, fail);
        if ((await focusOn(page)) !== "sidebar-hide") fail(`after Show sidebar the focus is on ${await focusOn(page)}, not Hide sidebar`);
        const railOff = await toggle(page, '[data-testid="topbar-rail"]');
        if (railOff) judgeSlide("Hide session rail", railOff.frames, "side", false, 320, R, fail);
        // The Terminal pane where no other pane shows: Ctrl+backtick from the message box slides it in, and again from
        // the terminal slides it out, the focus back in the message box as before.
        await page.evaluate(`(() => { const f = ${FIELD}; if (f) f.focus(); })()`);
        const termIn = await toggle(page, "key");
        const termW = termIn?.frames.at(-1)?.side?.w ?? 0;
        details.terminalWidth = termW;
        if (termIn) judgeSlide("the Terminal pane opens", termIn.frames, "side", true, termW, R, fail);
        await sleep(600);
        const termOut = await toggle(page, "key");
        if (termOut) judgeSlide("the Terminal pane closes", termOut.frames, "side", false, termW, R, fail);
        if (!(await page.evaluate<boolean>(`document.activeElement === ${FIELD}`))) fail(`after the Terminal pane closed the focus is on ${await focusOn(page)}, not the message box`);
        const railOn = await toggle(page, '[data-testid="topbar-rail"]');
        if (railOn) judgeSlide("Show session rail", railOn.frames, "side", true, 320, R, fail);
        // A toggle while a handle drags (the rail's button by its key, the pointer down on the sidebar's handle):
        // the side pane goes at once.
        const h = await page.locate('[data-testid="pane-handle-sidebar"]');
        const before = await marks(page);
        if (h) {
          await page.evaluate(`document.querySelector('[data-testid="topbar-rail"]').focus()`);
          await page.evaluate(`(() => { const S = window.__slide; S.frames = []; S.on = true; })()`);
          await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: h.x, y: h.y });
          await page.send("Input.dispatchMouseEvent", { type: "mousePressed", x: h.x, y: h.y, button: "left", buttons: 1, clickCount: 1 });
          for (let i = 1; i <= 4; i++) {
            await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: h.x + 3 * i, y: h.y, button: "left", buttons: 1 });
            await sleep(16);
          }
          await page.key("Enter");
          await sleep(400);
          await page.send("Input.dispatchMouseEvent", { type: "mouseReleased", x: h.x + 12, y: h.y, button: "left", buttons: 0, clickCount: 1 });
          await sleep(200);
          const frames = JSON.parse(await page.evaluate<string>(`(() => { const S = window.__slide; S.on = false; return JSON.stringify(S.frames); })()`)) as SlideFrame[];
          judgeNoSlide("Hide session rail while the sidebar's handle drags", frames, (await marks(page)) - before, fail);
          if (frames.at(-1)?.side) fail("Hide session rail while a handle dragged left the side pane open");
          const back = await page.locate('[data-testid="pane-handle-sidebar"]');
          if (back) await doublePress(page, back.x, back.y);
          const again = await page.locate('[data-testid="topbar-rail"]');
          if (again) await page.press(again.x, again.y);
          await sleep(400);
        } else fail("no sidebar handle to drag", "shows");
        if (shots) {
          await shootMid(page, '[data-testid="sidebar-hide"]', "hide");
          await shootMid(page, '[data-testid="sidebar-show"]', "show");
        }
        // The long chat: each toggle's frames and the page's work per frame.
        const n = await page.evaluate<number>(LONG_CHAT);
        details.longChatElements = n;
        if (n < 9000) warnings.push({ code: "cost", text: `the long chat holds only ${n} elements` });
        await sleep(400);
        for (const [sel, word, label] of [['[data-testid="sidebar-hide"]', "sidebar", "long chat: Hide sidebar"], ['[data-testid="sidebar-show"]', "sidebar", "long chat: Show sidebar"], ['[data-testid="topbar-rail"]', "side", "long chat: Hide session rail"], ['[data-testid="topbar-rail"]', "side", "long chat: Show session rail"]] as const) {
          const r = await toggle(page, sel, false);
          costs[label] = r ? slideCost(r.frames, word, r.m0, r.m1) : null;
          if (r && !costs[label]) fail(`${label}: no slide`);
        }
        await page.evaluate(LONG_CHAT_GONE);
      }
      for (const [label, c] of Object.entries(costs)) if (c && (c.workMax > 16 || c.late)) warnings.push({ code: "cost", text: `${label}: a frame of the slide took ${c.workMax} ms of the page's work (mean ${c.workMean} ms, ${c.late} late frames in ${c.frames})` });
      const s = await page.probe();
      stateFindings(s, vp, failures);
      issueFindings(page.takeIssues(), failures);
      quietFindings(wire, since, await recorder(page), failures);
    });
    // Reduce motion, the app's and the system's: nothing slides (a laptop and the tablet).
    if (vp.name !== "phone" && !shots)
      for (const reduce of ["settings", "system"] as const)
        await withPage(vp, theme, async (page) => {
          await open(page, reduce);
          const sel = vp.name === "medium" ? '.pane-bar-btn[title="Details"]' : '[data-testid="sidebar-hide"]';
          const r = await toggle(page, sel);
          if (r) judgeNoSlide(`Reduce motion (${reduce === "settings" ? "Settings" : "the system's"})`, r.frames, await marks(page), fail);
          if (reduce === "settings") {
            // The instant toggle's own cost on the long chat, as the reference for the slides' frames.
            const back = vp.name === "medium" ? '.pane-bar-btn[title="Close Details"]' : '[data-testid="sidebar-show"]';
            const b = await page.locate(back);
            if (b) await page.press(b.x, b.y);
            await sleep(400);
            await page.evaluate(LONG_CHAT);
            await sleep(400);
            const ref = await toggle(page, sel, false);
            if (ref) {
              const all = ref.frames.filter((f) => f.work !== undefined);
              const ms = (k: string) => r2(((ref.m1[k] ?? 0) - (ref.m0[k] ?? 0)) * 1000);
              details.instantToggleOnLongChat = { workMax: r2(Math.max(0, ...all.map((f) => f.work!))), taskMs: ms("TaskDuration"), layoutMs: ms("LayoutDuration"), styleMs: ms("RecalcStyleDuration") };
            }
          }
          issueFindings(page.takeIssues(), failures, `reduce motion (${reduce}): `);
        });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const costText = Object.entries(costs)
    .filter((e): e is [string, SlideCost] => !!e[1])
    .map(([k, c]) => `${k.replace("long chat: ", "")} ${c.frames} frames in ${c.ms} ms, ${c.late} late, work ${c.workMean}/${c.workMax} ms, then ${c.endWork} ms`)
    .join("; ");
  const note =
    vp.name === "phone"
      ? `${vp.width}x${vp.height}: the Details sheet slides no pane; nothing sent`
      : `${vp.width}x${vp.height}${vp.touch ? " touch" : ""} ${theme}: ${vp.name === "medium" ? "Details opens and closes" : "Hide and Show sidebar, Hide and Show session rail"} with a slide (the pane at its width, the chat's edge with it, the closing box inert), none on a load, a reload${vp.name === "medium" ? "" : ", a drag"} or with Reduce motion; long chat: ${costText || "not measured"}`;
  return finish({ kind: "flow", name: "pane-slide", route: "chat", scene, size: sizeTag(vp), theme, path: chat, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * Row 92 (and row 91, the tab's name) at one size. A laptop (1100x800): on a chat the tab says "kitespan"; the
 * sidebar's "kitespan" is a link to / named "kitespan, home", after Hide sidebar in the keyboard's order, and its focus
 * ring shows whole; a middle-click and a Ctrl-click each open / in a new tab and leave this page where it was; a plain
 * click opens Home in this document (one entry more; Back goes to the chat), where the tab says "kitespan" too. The
 * tablet (834x1194, touch): the chats button opens the drawer, whose "kitespan" is a 44 px target; a tap opens Home in
 * this document with the drawer closed, in the drawer's entry (Back goes to the chat). Nothing sent.
 */
async function logoLinkFlow(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  const chat = `/c/${EX.chat}`;
  let shot: string | undefined;
  const BRAND = `(() => {
    const els = [...document.querySelectorAll(".scr-list-head .scr-brand")].filter((e) => e.getClientRects().length);
    const el = els[0];
    if (!el) return null;
    const r = el.getBoundingClientRect();
    const cs = getComputedStyle(el);
    const nav = el.closest("nav, .scr-drawer");
    const n = nav ? nav.getBoundingClientRect() : null;
    return { count: els.length, tag: el.tagName.toLowerCase(), href: el.getAttribute("href"), name: el.getAttribute("aria-label"), text: el.textContent.trim(), x: r.left + r.width / 2, y: r.top + r.height / 2, h: r.height, focused: document.activeElement === el, ring: el.matches(":focus-visible") ? cs.outlineStyle + " " + cs.outlineWidth + " " + cs.outlineColor : null, ringOff: parseFloat(cs.outlineOffset) || 0, ringW: parseFloat(cs.outlineWidth) || 0, box: { left: r.left, right: r.right, top: r.top, bottom: r.bottom }, nav: n && { left: n.left, right: n.right, top: n.top, bottom: n.bottom }, underline: cs.textDecorationLine };
  })()`;
  type Rect = { left: number; right: number; top: number; bottom: number };
  type Brand = { count: number; tag: string; href: string | null; name: string | null; text: string; x: number; y: number; h: number; focused: boolean; ring: string | null; ringOff: number; ringW: number; box: Rect; nav: Rect | null; underline: string };
  const brand = (page: Page) => page.evaluate<Brand | null>(BRAND);
  const pages = async (page: Page) => ((await cdp.send<{ targetInfos: { type: string; url: string; browserContextId?: string; targetId: string }[] }>("Target.getTargets")).targetInfos ?? []).filter((x) => x.type === "page" && x.browserContextId === page.contextId && x.targetId !== page.targetId);
  try {
    await withPage(vp, "dark", async (page, wire) => {
      const since = wire.mark();
      await page.navigate(base + chat);
      await waitShown(page, ["conversation"]);
      await sleep(300);
      const title = await page.evaluate<string>("document.title");
      if (title !== "kitespan") fail(`on a chat the tab says ${JSON.stringify(title)}, not "kitespan"`);
      await page.evaluate("window.__sameDocument = true");
      const entries0 = (await page.history()).entries.length;
      if (vp.name === "medium") {
        const chats = await page.locate(".scr-bar-chats");
        if (!chats) return fail("the title bar has no chats button", "shows");
        await page.press(chats.x, chats.y);
        await sleep(500);
        const b = await brand(page);
        details.drawer = b;
        if (!b) return fail("the drawer shows no kitespan", "shows");
        if (b.tag !== "a" || b.href !== "/" || b.name !== "kitespan, home" || b.text !== "kitespan") fail(`the drawer's kitespan is <${b.tag} href=${b.href}> named ${JSON.stringify(b.name)}`);
        if (b.h < 44) fail(`the drawer's kitespan is ${Math.round(b.h)} px high, under 44`);
        shot = shotName(scene, "logo-link", vp, "dark", "drawer");
        await page.screenshot(shot);
        await page.press(b.x, b.y);
        await sleep(600);
        const s = await page.probe();
        if (!sameUrl(s.path, "/")) fail(`a tap on kitespan left ${s.path}, not /`);
        if (!(await page.evaluate<boolean>("window.__sameDocument === true"))) fail("a tap on kitespan loaded a new document");
        if (await page.evaluate<boolean>(`!!document.querySelector(".scr-drawer")`)) fail("the drawer is still open on Home");
        if (!s.ids.includes("home")) fail("Home does not show after the tap");
        const h = await page.history();
        details.entries = h.entries.map((e) => e.url.replace(base, ""));
        if (h.entries.length !== entries0 + 1) fail(`after the drawer and the tap the tab has ${h.entries.length} entries, expected ${entries0 + 1} (Home in the drawer's entry)`);
        const prev = h.entries[h.currentIndex - 1];
        if (!prev || !sameUrl(prev.url.replace(base, ""), chat)) fail(`Back from Home goes to ${prev?.url ?? "nothing"}, not the chat`);
      } else {
        const b = await brand(page);
        details.sidebar = b;
        if (!b) return fail("the sidebar shows no kitespan", "shows");
        if (b.count !== 1 || b.tag !== "a" || b.href !== "/" || b.name !== "kitespan, home" || b.text !== "kitespan") fail(`the sidebar's kitespan is <${b.tag} href=${b.href}> named ${JSON.stringify(b.name)} (${b.count} shown)`);
        if (b.underline !== "none") fail(`the sidebar's kitespan is underlined (${b.underline})`);
        // The keyboard: Tab from Hide sidebar reaches it, and its ring shows whole. v0.6 touch (T-11, G-32): the brand
        // has the head's line to itself and the tools take a row under it, so Shift+Tab from Search reaches it.
        const from = vp.touch ? '[data-testid="head-tools"] .scr-search' : '[data-testid="sidebar-hide"]';
        const shift = vp.touch ? 8 : 0;
        await page.evaluate(`document.querySelector(${JSON.stringify(from)}).focus()`);
        await page.send("Input.dispatchKeyEvent", { type: "rawKeyDown", key: "Tab", code: "Tab", windowsVirtualKeyCode: 9, nativeVirtualKeyCode: 9, modifiers: shift });
        await page.send("Input.dispatchKeyEvent", { type: "keyUp", key: "Tab", code: "Tab", windowsVirtualKeyCode: 9, nativeVirtualKeyCode: 9, modifiers: shift });
        await sleep(150);
        const f = await brand(page);
        details.focused = f;
        if (!f?.focused) fail(vp.touch ? "Shift+Tab from the head's Search does not reach kitespan" : "Tab from Hide sidebar does not reach kitespan");
        else if (!f.ring || !/^solid 2px /.test(f.ring) || / rgba\(0, 0, 0, 0\)$/.test(f.ring)) fail(`kitespan's focus shows no ring (${f.ring})`);
        else if (f.nav) {
          const o = f.ringOff + f.ringW;
          if (f.box.left - o < f.nav.left || f.box.right + o > f.nav.right || f.box.top - o < f.nav.top) fail("kitespan's focus ring is cut by the sidebar's edge");
        }
        shot = shotName(scene, "logo-link", vp, "dark", "focus");
        await page.screenshot(shot);
        // A middle-click and a Ctrl-click: a new tab with Home, this page where it was.
        for (const [label, press] of [
          ["a middle-click", { button: "middle", buttons: 4, modifiers: 0 }],
          ["a Ctrl-click", { button: "left", buttons: 1, modifiers: 2 }],
        ] as const) {
          const had = new Set((await pages(page)).map((x) => x.targetId));
          await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: b.x, y: b.y });
          await page.send("Input.dispatchMouseEvent", { type: "mousePressed", x: b.x, y: b.y, button: press.button, buttons: press.buttons, clickCount: 1, modifiers: press.modifiers });
          await page.send("Input.dispatchMouseEvent", { type: "mouseReleased", x: b.x, y: b.y, button: press.button, buttons: 0, clickCount: 1, modifiers: press.modifiers });
          await sleep(800);
          const added = (await pages(page)).filter((x) => !had.has(x.targetId));
          if (added.length !== 1) fail(`${label} on kitespan opened ${added.length} new tab(s), not one`);
          else if (!/\/$/.test(added[0]!.url)) warnings.push({ code: "flow", text: `${label}'s new tab shows ${added[0]!.url}` });
          const here = await page.probe();
          if (!sameUrl(here.path, chat)) fail(`${label} on kitespan moved this page to ${here.path}`);
          for (const t of added) await cdp.send("Target.closeTarget", { targetId: t.targetId }).catch(() => {});
        }
        // A plain click: Home in this document.
        await page.press(b.x, b.y);
        await sleep(600);
        const s = await page.probe();
        if (!sameUrl(s.path, "/")) fail(`a click on kitespan left ${s.path}, not /`);
        if (!(await page.evaluate<boolean>("window.__sameDocument === true"))) fail("a click on kitespan loaded a new document");
        if (!s.ids.includes("home")) fail("Home does not show after the click");
        const h = await page.history();
        if (h.entries.length !== entries0 + 1) fail(`after the click the tab has ${h.entries.length} entries, expected ${entries0 + 1}`);
        const home = await page.evaluate<string>("document.title");
        if (home !== "kitespan") fail(`on Home the tab says ${JSON.stringify(home)}`);
        const prev = h.entries[h.currentIndex - 1];
        if (prev) await page.goToEntry(prev.id);
        if (!sameUrl((await page.probe()).path, chat)) fail(`Back from Home showed ${(await page.probe()).path}, not the chat`);
      }
      stateFindings(await page.probe(), vp, failures);
      issueFindings(page.takeIssues(), failures);
      quietFindings(wire, since, await recorder(page), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note =
    vp.name === "medium"
      ? `${vp.width}x${vp.height} touch: the drawer's kitespan links to /, 44 px high; a tap opens Home in the same document, in the drawer's entry; the tab says kitespan; nothing sent`
      : `${vp.width}x${vp.height}: the sidebar's kitespan links to / as "kitespan, home", with its ring by the keyboard; a middle-click and a Ctrl-click open a new tab, a click opens Home in the same document; the tab says kitespan on a chat and on Home; nothing sent`;
  return finish({ kind: "flow", name: "logo-link", route: "home", scene, size: sizeTag(vp), theme: "dark", path: chat, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

// ---------------------------------------------------------------------------------------------------------------
// Row 99: an environment's menu (Rename, Move up, Move down, Remove), its two paths, the heading's drag, and Remove

/** The environments' headings in the list on screen, in order: id, name, the "..." button, the name's centre. */
const ENV_HEADS = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  return [...document.querySelectorAll(".scr-group-head[data-env]")].filter(shown).map((h) => {
    const name = h.querySelector(".scr-group-name");
    const more = h.querySelector('[data-testid="env-more"]');
    const b = h.getBoundingClientRect();
    const m = more ? more.getBoundingClientRect() : null;
    const n = name ? name.getBoundingClientRect() : null;
    return { id: h.dataset.env, name: name ? name.textContent.trim() : "", more: m && { x: m.left + m.width / 2, y: m.top + m.height / 2, w: m.width, h: m.height }, at: n && { x: n.left + Math.min(30, n.width / 2), y: n.top + n.height / 2 }, top: b.top, bottom: b.bottom };
  });
})())`;
interface EnvHead {
  id: string;
  name: string;
  more: { x: number; y: number; w: number; h: number } | null;
  at: { x: number; y: number } | null;
  top: number;
  bottom: number;
}
const envHeads = async (page: Page) => JSON.parse(await page.evaluate<string>(ENV_HEADS)) as EnvHead[];
const envOrder = async (page: Page) => (await envHeads(page)).map((h) => h.id);

/** The open environment menu's rows, the focused element, and the heading drag's line and dimmed heading. */
const ENV_MENU = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const box = [...document.querySelectorAll('[data-testid="env-menu"]')].find(shown);
  const a = document.activeElement;
  const env = a && a.closest ? a.closest("[data-env]") : null;
  return {
    open: !!box,
    rows: box ? [...box.querySelectorAll('[role="menuitem"]')].filter(shown).map((r) => r.textContent.trim()) : [],
    focus: a && a !== document.body ? { text: (a.textContent || "").trim().slice(0, 40), id: a.getAttribute("data-testid"), env: env ? env.dataset.env : null } : null,
    drop: [...document.querySelectorAll(".scr-group[data-drop]")].map((g) => g.dataset.drop + " " + ((g.querySelector("[data-env]") || {}).dataset || {}).env),
    dragging: [...document.querySelectorAll(".scr-group-head[data-dragging]")].map((h) => h.dataset.env),
  };
})())`;
interface EnvMenuState {
  open: boolean;
  rows: string[];
  focus: { text: string; id: string | null; env: string | null } | null;
  drop: string[];
  dragging: string[];
}
const envMenu = async (page: Page) => JSON.parse(await page.evaluate<string>(ENV_MENU)) as EnvMenuState;

/** A key as a hardware keyboard sends it: the arrows and Esc with no text, Space and Enter with theirs. */
async function envKey(page: Page, key: "ArrowDown" | "ArrowUp" | "Escape" | " " | "Enter") {
  const codes = { ArrowDown: [40, "ArrowDown"], ArrowUp: [38, "ArrowUp"], Escape: [27, "Escape"], " ": [32, "Space"], Enter: [13, "Enter"] } as const;
  const [vk, code] = codes[key];
  const keys = { key, code, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk };
  const text = key === " " ? { text: " " } : key === "Enter" ? { text: "\r" } : {};
  await page.send("Input.dispatchKeyEvent", { type: "text" in text ? "keyDown" : "rawKeyDown", ...keys, ...text });
  await page.send("Input.dispatchKeyEvent", { type: "keyUp", ...keys });
}

/** A mouse drag from (x, y) to (x, y2) in steps; `mid` runs before the release, and `escape` presses Esc there. */
async function mouseDrag(page: Page, x: number, y: number, y2: number, mid?: () => Promise<void>, escape = false) {
  await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x, y });
  await page.send("Input.dispatchMouseEvent", { type: "mousePressed", x, y, button: "left", buttons: 1, clickCount: 1 });
  for (let i = 1; i <= 12; i++) {
    await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x, y: y + ((y2 - y) * i) / 12, button: "left", buttons: 1 });
    await sleep(16);
  }
  await sleep(100);
  await mid?.();
  if (escape) await envKey(page, "Escape");
  await page.send("Input.dispatchMouseEvent", { type: "mouseReleased", x, y: y2, button: "left", buttons: 0, clickCount: 1 });
}

/** Wait waitUntil `pred` holds (polled), up to `ms`; the last value either way. */
async function waitUntil<T>(read: () => Promise<T>, pred: (v: T) => boolean, ms = 4000): Promise<T> {
  const end = Date.now() + ms;
  let v = await read();
  while (!pred(v) && Date.now() < end) {
    await sleep(80);
    v = await read();
  }
  return v;
}

const pathOf = (page: Page) => page.evaluate<string>("location.pathname + location.search");
const postsSince = (wire: Wire, since: number) => wire.httpSince(since).filter((h) => h.method === "POST");

/** The environment's "..." on its heading (the list on screen), pressed: its menu opens. */
async function openEnvMenu(page: Page, env: string, fail: (t: string) => void): Promise<EnvMenuState | null> {
  // A drawer or a sheet that still slides, or a menu that still pops in, is not where it will be: wait for it.
  await page.settle();
  const h = (await envHeads(page)).find((x) => x.id === env);
  if (!h?.more) {
    fail(`the heading of ${env} shows no "..." button`);
    return null;
  }
  await page.press(h.more.x, h.more.y);
  const m = await waitUntil(() => envMenu(page), (x) => x.open);
  if (!m.open) fail(`the "..." of ${env} opened no menu`);
  await page.settle();
  return m.open ? m : null;
}

/** A row of the open environment menu, pressed. */
async function pressEnvRow(page: Page, testId: string, fail: (t: string) => void): Promise<boolean> {
  const at = await page.locate(`[data-testid="env-menu"] [data-testid="${testId}"]`);
  if (!at) {
    fail(`the environment menu shows no ${testId}`);
    return false;
  }
  if (at.covered) fail(`the menu's ${testId} is covered by ${at.covered}`);
  await page.press(at.x, at.y);
  await sleep(300);
  return true;
}

const touchSmall = async (page: Page, warnings: Finding[], where: string) => {
  const small = await page.evaluate<string[]>(SMALL_TARGETS);
  if (small.length) warnings.push({ code: "target", text: `${where}: under 44 px: ${clipList(small)}` });
};

/**
 * Row 99, Rename (env-rename). A laptop (1280x800) from a chat's page: the sidebar heading's "..." opens the
 * environment's menu by the keyboard (Space, the focus on Rename; the arrows move it; Esc closes the menu and gives the
 * focus back to the button), by a click and by a right-click on the heading; Rename opens /p/<project>/rename with the
 * name in a focused field; Esc keeps the old name and goes back to the chat; a new name and Enter send one POST
 * /api/projects/:project/rename and go back to the chat, whose sidebar shows the new name. Touch (834x1194 and 390x844),
 * from /chats: the 44 px "..." opens the menu (a sheet on the phone); Rename then Cancel, then Rename and Save. Each run
 * puts the seed's name back with Save. No sideways overflow.
 */
async function envRenameFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  const env = IDS.projects.notes;
  const start = vp.touch ? "/chats" : `/c/${EX.chat}`;
  const tag = vp.width === WIDE_LAPTOP.width ? "1280" : "";
  let shot: string | undefined;
  try {
    await withPage(vp, theme, async (page, wire) => {
      await page.navigate(base + start);
      await waitShown(page, [vp.touch ? "chat-list" : "conversation"]);
      page.takeIssues();
      const nameOf = async () => (await envHeads(page)).find((h) => h.id === env)?.name ?? null;
      const before = await nameOf();
      details.name = before;
      if (!before) return fail(`the list shows no heading for ${env}`, "shows");
      const since = wire.mark();

      if (!vp.touch) {
        // The keyboard: Space opens it, the focus on its first row; the arrows move; Esc closes and gives the focus back.
        await page.evaluate(`document.querySelector('[data-env="${env}"] [data-testid="env-more"]').focus()`);
        await envKey(page, " ");
        const k = await waitUntil(() => envMenu(page), (m) => m.open && m.focus?.text === "Rename");
        details.keyboard = k;
        if (!k.open) fail("Space on the heading's \"...\" opened no menu");
        else {
          if (k.focus?.text !== "Rename") fail(`the menu opened with the focus on ${JSON.stringify(k.focus)}, not Rename`);
          await envKey(page, "ArrowDown");
          const down = await envMenu(page);
          if (down.focus?.text !== k.rows[1]) fail(`ArrowDown moved the focus to ${JSON.stringify(down.focus?.text)}, not ${k.rows[1]}`);
          await envKey(page, "ArrowUp");
          if ((await envMenu(page)).focus?.text !== "Rename") fail("ArrowUp did not bring the focus back to Rename");
          await envKey(page, "Escape");
          const shut = await waitUntil(() => envMenu(page), (m) => !m.open && m.focus?.id === "env-more");
          if (shut.open) fail("Esc did not close the menu");
          else if (shut.focus?.id !== "env-more" || shut.focus.env !== env) fail(`after Esc the focus is on ${JSON.stringify(shut.focus)}, not the heading's "..."`);
        }
      }
      // A press on "...": the menu (its screenshot), Rename, the field; Esc (a laptop) or Cancel (touch) keeps the name.
      const m = await openEnvMenu(page, env, fail);
      if (!m) return;
      details.rows = m.rows;
      if (!m.rows.includes("Rename") || !m.rows.includes("Remove")) fail(`the menu's rows are ${m.rows.join(", ")}`);
      if (vp.touch) await touchSmall(page, warnings, "the environment menu");
      await page.screenshot(shotName(scene, "env-rename", vp, theme, `${tag}menu`)).catch(() => {});
      if (!(await pressEnvRow(page, "env-rename", fail))) return;
      const opened = await waitUntil(() => pathOf(page), (p) => p === `/p/${env}/rename`);
      if (opened !== `/p/${env}/rename`) return fail(`Rename opened ${opened}, not /p/${env}/rename`);
      const field = await waitUntil(
        () => page.evaluate<{ focused: boolean; value: string } | null>(`(() => { const f = document.getElementById("scr-env-name"); return f ? { focused: document.activeElement === f, value: f.value } : null; })()`),
        (f) => !!f?.focused,
      );
      details.field = field;
      if (!field) return fail("Rename shows no name field", "shows");
      if (!field.focused || field.value !== before) fail(`the field holds ${JSON.stringify(field.value)}${field.focused ? "" : ", not focused"}; expected the name ${JSON.stringify(before)}, focused`);
      stateFindings(await page.probe(), vp, failures, "the rename box: ");
      if (vp.touch) await touchSmall(page, warnings, "the rename box");
      shot = shotName(scene, "env-rename", vp, theme, `${tag}box`);
      await page.screenshot(shot).catch(() => {});
      if (vp.touch) {
        const cancel = await page.locate('[data-testid="project-rename"] button[type="button"]');
        if (!cancel) return fail("the rename box shows no Cancel");
        await page.press(cancel.x, cancel.y);
      } else await envKey(page, "Escape");
      const back = await waitUntil(() => pathOf(page), (p) => p === start);
      if (back !== start) fail(`${vp.touch ? "Cancel" : "Esc"} went to ${back}, not back to ${start}`);
      if ((await nameOf()) !== before) fail(`${vp.touch ? "Cancel" : "Esc"} changed the name to ${await nameOf()}`);
      if (postsSince(wire, since).length || acting(wire.framesSince(since)).length) fail(`the menu, Rename and ${vp.touch ? "Cancel" : "Esc"} sent ${clipList([...postsSince(wire, since).map(httpText), ...acting(wire.framesSince(since)).map(frameText)])}`, "click");

      // A new name, saved (Enter on the laptop, after a right-click on the heading; Save on touch); then the old name.
      for (const [name, how] of [
        ["notes service", vp.touch ? "save" : "enter"],
        [before, "save"],
      ] as const) {
        const mark = wire.mark();
        if (!vp.touch && how === "enter") {
          const h = (await envHeads(page)).find((x) => x.id === env);
          if (!h?.at) return fail("the heading has no name to right-click");
          await page.hold(h.at.x, h.at.y);
          if (!(await waitUntil(() => envMenu(page), (x) => x.open)).open) return fail("a right-click on the heading opened no menu");
        } else if (!(await openEnvMenu(page, env, fail))) return;
        if (!(await pressEnvRow(page, "env-rename", fail))) return;
        await waitUntil(() => page.evaluate<boolean>(`document.activeElement === document.getElementById("scr-env-name")`), (x) => x);
        await page.send("Input.insertText", { text: name });
        if (how === "enter") await envKey(page, "Enter");
        else {
          const save = await page.locate('[data-testid="confirm-save-name"]');
          if (!save) return fail("the rename box shows no Save");
          await page.press(save.x, save.y);
        }
        const done = await waitUntil(() => pathOf(page), (p) => p === start);
        if (done !== start) fail(`${how === "enter" ? "Enter" : "Save"} left the page on ${done}, not ${start}`);
        const shown = await waitUntil(nameOf, (n) => n === name);
        if (shown !== name) fail(`after ${how === "enter" ? "Enter" : "Save"} the heading says ${JSON.stringify(shown)}, not ${JSON.stringify(name)}`);
        const sent = postsSince(wire, mark);
        if (sent.length !== 1 || sent[0]!.path !== `/api/projects/${env}/rename` || sent[0]!.status !== 200) fail(`saving ${JSON.stringify(name)} sent ${sent.length ? clipList(sent.map(httpText)) : "nothing"}; expected one POST /api/projects/${env}/rename (200)`, "click");
      }
      stateFindings(await page.probe(), vp, failures);
      issueFindings(page.takeIssues(), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = vp.touch
    ? `${vp.width}x${vp.height} touch, /chats: the 44 px "..." opens the menu; Rename opens the focused field; Cancel keeps the name; Save sends one rename and shows it`
    : `${vp.width}x${vp.height}, a chat's page: the menu by Space (the arrows, Esc and the focus back), a click and a right-click; Rename's field; Esc keeps the name; Enter sends one rename and shows it`;
  return finish({ kind: "flow", name: "env-rename", route: "projectRename", scene, size: sizeTag(vp), theme, path: start, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * Row 99, Move (env-move). A laptop (1100x800) on a chat's page: the last environment's menu has Move up and no Move
 * down, and Move up sends one POST /api/projects/:project/move and moves the heading; by the keyboard (Enter, the arrows
 * to Move down, Enter) it goes back, with the focus on its "..."; a mouse drag of the first heading below the last shows
 * the drop line under the last one, dims the heading, and its release sends one move, opens nothing and moves it there;
 * a drag that Esc stops leaves no line and sends nothing; a reload and a second page show the same order; a drag back to
 * the top puts the seed's order back. Touch (834x1194 and 390x844), on /chats: the middle one's Move down and then
 * Move up, one move each; a quick finger's drag on a heading (no long press, so a scroll) moves nothing and sends
 * nothing; the long press's drag is env-move-touch's (row 102). No sideways overflow.
 */
async function envMoveFlow(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  const start = vp.touch ? "/chats" : `/c/${EX.chat}`;
  let shot: string | undefined;
  const oneMove = (wire: Wire, mark: number, env: string, what: string) => {
    const sent = postsSince(wire, mark);
    if (sent.length !== 1 || sent[0]!.path !== `/api/projects/${env}/move` || sent[0]!.status !== 200) fail(`${what} sent ${sent.length ? clipList(sent.map(httpText)) : "nothing"}; expected one POST /api/projects/${env}/move (200)`, "click");
  };
  try {
    await withPage(vp, "dark", async (page, wire) => {
      await page.navigate(base + start);
      await waitShown(page, [vp.touch ? "chat-list" : "conversation"]);
      page.takeIssues();
      const o0 = await envOrder(page);
      details.start = o0;
      if (o0.length < 3) return fail(`the list shows ${o0.length} environments; the seed has 3`, "shows");
      const same = (a: string[], b: string[]) => a.join() === b.join();
      const wait = (want: string[]) => waitUntil(() => envOrder(page), (o) => same(o, want));
      const step = async (env: string, row: "env-move-up" | "env-move-down", want: string[], what: string) => {
        const mark = wire.mark();
        const m = await openEnvMenu(page, env, fail);
        if (!m) return false;
        if (!(await pressEnvRow(page, row, fail))) return false;
        const got = await wait(want);
        if (!same(got, want)) fail(`${what} left the order ${got.join(", ")}, not ${want.join(", ")}`);
        await sleep(300);
        oneMove(wire, mark, env, what);
        return true;
      };
      if (vp.touch) {
        const mid = o0[1]!;
        const m = await openEnvMenu(page, mid, fail);
        if (!m) return;
        if (!m.rows.includes("Move up") || !m.rows.includes("Move down")) fail(`the middle environment's menu has ${m.rows.join(", ")}`);
        await touchSmall(page, warnings, "the environment menu");
        shot = shotName(scene, "env-move", vp, "dark", "menu");
        await page.screenshot(shot).catch(() => {});
        await envKey(page, "Escape");
        await waitUntil(() => envMenu(page), (x) => !x.open);
        if (!(await step(mid, "env-move-down", [o0[0]!, o0[2]!, mid], "Move down"))) return;
        if (!(await step(mid, "env-move-up", o0, "Move up"))) return;
        // A quick finger's drag on a heading, with no long press (row 102's lift is env-move-touch's): a scroll, so
        // nothing moves and nothing goes out.
        const mark = wire.mark();
        const h = (await envHeads(page))[0]!;
        if (h.at) {
          const pt = (y: number) => [{ x: h.at!.x, y, radiusX: 4, radiusY: 4, force: 1 }];
          await page.send("Input.dispatchTouchEvent", { type: "touchStart", touchPoints: pt(h.at.y) });
          for (let i = 1; i <= 10; i++) {
            await page.send("Input.dispatchTouchEvent", { type: "touchMove", touchPoints: pt(h.at.y + i * 15) });
            await sleep(16);
          }
          const mid2 = await envMenu(page);
          await page.send("Input.dispatchTouchEvent", { type: "touchEnd", touchPoints: [] });
          await sleep(600);
          if (mid2.dragging.length || mid2.drop.length) fail("a finger's drag on a heading started a heading drag");
          if (!same(await envOrder(page), o0)) fail("a finger's drag on a heading moved it");
          if (postsSince(wire, mark).length) fail(`a finger's drag on a heading sent ${clipList(postsSince(wire, mark).map(httpText))}`, "click");
        }
      } else {
        const last = o0[2]!;
        const m = await openEnvMenu(page, last, fail);
        if (!m) return;
        details.lastRows = m.rows;
        if (m.rows.includes("Move down") || !m.rows.includes("Move up")) fail(`the last environment's menu has ${m.rows.join(", ")}`);
        await envKey(page, "Escape");
        await waitUntil(() => envMenu(page), (x) => !x.open);
        if (!(await step(last, "env-move-up", [o0[0]!, last, o0[1]!], "Move up"))) return;
        // The keyboard: Enter on its "...", the arrows to Move down, Enter; the focus stays on its "...".
        const mark = wire.mark();
        await page.evaluate(`document.querySelector('[data-env="${last}"] [data-testid="env-more"]').focus()`);
        await envKey(page, "Enter");
        const k = await waitUntil(() => envMenu(page), (x) => x.open && x.focus?.text === "Rename");
        if (!k.open) return fail("Enter on the heading's \"...\" opened no menu");
        for (let i = 0; i < k.rows.indexOf("Move down"); i++) await envKey(page, "ArrowDown");
        if ((await envMenu(page)).focus?.text !== "Move down") fail(`the arrows did not reach Move down (rows ${k.rows.join(", ")})`);
        await envKey(page, "Enter");
        const got = await wait(o0);
        if (!same(got, o0)) fail(`Move down by the keyboard left the order ${got.join(", ")}`);
        await sleep(300);
        oneMove(wire, mark, last, "Move down by the keyboard");
        const f = await waitUntil(() => envMenu(page), (x) => x.focus?.id === "env-more");
        if (f.focus?.id !== "env-more" || f.focus.env !== last) fail(`after Move down the focus is on ${JSON.stringify(f.focus)}, not the environment's "..."`);

        // The drag: the first heading below the last; the line under the last, the heading dimmed; one move.
        const drag = async (env: string, toY: number, escape: boolean, label: string) => {
          const h = (await envHeads(page)).find((x) => x.id === env);
          if (!h?.at) return null;
          const seen: { state: EnvMenuState | null } = { state: null };
          await mouseDrag(page, h.at.x, h.at.y, toY, async () => {
            seen.state = await envMenu(page);
            if (label) await page.screenshot((shot = shotName(scene, "env-move", vp, "dark", label))).catch(() => {});
          }, escape);
          await sleep(400);
          return seen.state;
        };
        const first = o0[0]!;
        const heads = await envHeads(page);
        const below = heads[heads.length - 1]!.bottom + 6;
        let mark2 = wire.mark();
        const seen = await drag(first, below, false, "drag");
        details.drag = seen;
        if (!seen) return fail("the first heading has no name to drag");
        if (!seen.dragging.includes(first)) fail("the dragged heading is not dimmed while it moves");
        if (seen.drop.join() !== `after ${o0[2]}`) fail(`mid-drag the drop line is at ${JSON.stringify(seen.drop)}, not under the last environment`);
        const dropped = [o0[1]!, o0[2]!, first];
        const got2 = await wait(dropped);
        if (!same(got2, dropped)) fail(`the drop left the order ${got2.join(", ")}, not ${dropped.join(", ")}`);
        await sleep(300);
        oneMove(wire, mark2, first, "the drop");
        if ((await pathOf(page)) !== start) fail(`the drop opened ${await pathOf(page)}`);
        if ((await envMenu(page)).drop.length) fail("the drop line stays after the drop");
        // Esc puts it back: no line, no move.
        mark2 = wire.mark();
        const top = (await envHeads(page))[0]!;
        const esc = await drag(dropped[0]!, below + 40, true, "");
        if (!esc?.drop.length) warnings.push({ code: "flow", text: "the drag that Esc stops showed no line before Esc" });
        const after = await envMenu(page);
        if (after.drop.length || after.dragging.length) fail("after Esc the drag's line or its dimmed heading stays");
        if (!same(await envOrder(page), dropped)) fail("a drag stopped with Esc moved the heading");
        if (postsSince(wire, mark2).length) fail(`a drag stopped with Esc sent ${clipList(postsSince(wire, mark2).map(httpText))}`, "click");
        if ((await pathOf(page)) !== start) fail(`a drag stopped with Esc opened ${await pathOf(page)}`);
        // The server holds the order: a reload, and a second page.
        await page.reload();
        await waitShown(page, ["conversation"]);
        const reloaded = await wait(dropped);
        if (!same(reloaded, dropped)) fail(`after a reload the order is ${reloaded.join(", ")}, not ${dropped.join(", ")}`);
        await withPage(vp, "light", async (other) => {
          await other.navigate(base + "/chats");
          await waitShown(other, ["chat-list"]);
          const o = await waitUntil(() => envOrder(other), (x) => same(x, dropped));
          if (!same(o, dropped)) fail(`a second page shows the order ${o.join(", ")}, not ${dropped.join(", ")}`);
        });
        // Back to the seed's order: the moved heading dragged to the top.
        mark2 = wire.mark();
        const moved = (await envHeads(page)).find((x) => x.id === first);
        if (moved?.at) {
          await mouseDrag(page, moved.at.x, moved.at.y, top.top + 2);
          const back = await wait(o0);
          if (!same(back, o0)) fail(`the drag to the top left the order ${back.join(", ")}, not ${o0.join(", ")}`);
          await sleep(300);
          oneMove(wire, mark2, first, "the drag to the top");
        }
      }
      stateFindings(await page.probe(), vp, failures);
      issueFindings(page.takeIssues(), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = vp.touch
    ? `${vp.width}x${vp.height} touch: Move down, then Move up, one move each; a quick finger's drag (no long press) moves nothing`
    : `${vp.width}x${vp.height}: Move up (no Move down on the last), Move down by the keyboard with the focus kept, a mouse drag with its line (one move, nothing opened), Esc stops a drag, the order after a reload and on a second page`;
  return finish({ kind: "flow", name: "env-move", route: "chats", scene, size: sizeTag(vp), theme: "dark", path: start, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/** Row 102: the page's own count of touchmoves on the window, and of those whose default a handler prevented. */
const ENV_TOUCH_RECORDER = `(() => {
  const r = (window.__envTouch = { moves: 0, held: 0 });
  if (window.__envTouchOn) return;
  window.__envTouchOn = true;
  window.addEventListener("touchmove", (e) => { window.__envTouch.moves++; if (e.defaultPrevented) window.__envTouch.held++; }, { passive: true });
})()`;
/** The scroll box of the first heading on screen, the lifted heading's surface (its ::before), and the touchmove count. */
const ENV_TOUCH_STATE = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const head = [...document.querySelectorAll(".scr-group-head[data-env]")].find(shown);
  const s = head ? head.closest(".scr-list-scroll") : null;
  const r = s ? s.getBoundingClientRect() : null;
  const lifted = document.querySelector('.scr-group-head[data-dragging="touch"]');
  const cs = lifted ? getComputedStyle(lifted, "::before") : null;
  return {
    scroll: s ? { top: s.scrollTop, room: s.scrollHeight - s.clientHeight, top0: r.top, bottom: r.bottom } : null,
    look: cs ? { opacity: cs.opacity, shadow: cs.boxShadow, bg: cs.backgroundColor } : null,
    select: head ? getComputedStyle(head).userSelect : null,
    touch: window.__envTouch || null,
  };
})())`;
interface EnvTouchState {
  scroll: { top: number; room: number; top0: number; bottom: number } | null;
  look: { opacity: string; shadow: string; bg: string } | null;
  select: string | null;
  touch: { moves: number; held: number } | null;
}

/**
 * Row 102, a finger's drag of a heading (env-move-touch): 834x1194 touch in dark, and 390x844 touch in dark and light
 * (with the screenshots of the lifted heading and of its drop line), on /chats with Chrome's touch emulation (CDP
 * touch events, a held press). With the list's box made 240 px high (the seed's list fits the screen): a short swipe
 * on a heading scrolls the list, lifts nothing, holds back no touchmove and sends nothing; a lifted heading's move
 * holds the list still and its release in its own place sends nothing; a lifted heading held at the list's bottom
 * edge scrolls it by itself. Then at full height: a press held 600 ms lifts the heading (the raised surface; no text
 * selection) and opens no menu, and its release with no move sends nothing and opens nothing; a held press and a move
 * below the last heading holds back every move, shows the drop line under the last one, and the release sends one
 * move, opens nothing and puts it last, as a second page shows; a second finger ends a lifted drag with nothing sent;
 * a drag back to the top puts the seed's order back with one move; and a quick tap on a heading's name still opens
 * its page. Chrome's emulation cannot show iOS Safari's callout or its link preview.
 */
async function envMoveTouchFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  const start = "/chats";
  let shot: string | undefined;
  const pt = (x: number, y: number, id = 0) => ({ x, y, radiusX: 4, radiusY: 4, force: 1, id });
  const oneMove = (wire: Wire, mark: number, env: string, what: string) => {
    const sent = postsSince(wire, mark);
    if (sent.length !== 1 || sent[0]!.path !== `/api/projects/${env}/move` || sent[0]!.status !== 200) fail(`${what} sent ${sent.length ? clipList(sent.map(httpText)) : "nothing"}; expected one POST /api/projects/${env}/move (200)`, "click");
  };
  const none = (wire: Wire, mark: number, what: string) => {
    const sent = postsSince(wire, mark);
    if (sent.length) fail(`${what} sent ${clipList(sent.map(httpText))}`, "click");
  };
  try {
    await withPage(vp, theme, async (page, wire) => {
      const touch = (type: "touchStart" | "touchMove" | "touchEnd", points: ReturnType<typeof pt>[] = []) => page.send("Input.dispatchTouchEvent", { type, touchPoints: points });
      const read = async () => JSON.parse(await page.evaluate<string>(ENV_TOUCH_STATE)) as EnvTouchState;
      const count = () => page.evaluate(ENV_TOUCH_RECORDER);
      /** A finger down at (x, y), held `hold` ms, moved to y2 in `steps` steps 16 ms apart; `mid` runs before it lifts. */
      const finger = async (x: number, y: number, hold: number, y2: number, steps: number, mid?: () => Promise<void>) => {
        await touch("touchStart", [pt(x, y)]);
        await sleep(hold);
        for (let i = 1; i <= steps; i++) {
          await touch("touchMove", [pt(x, y + ((y2 - y) * i) / steps)]);
          await sleep(16);
        }
        await sleep(100);
        await mid?.();
        await touch("touchEnd");
        await sleep(400);
      };
      const same = (a: string[], b: string[]) => a.join() === b.join();
      const wait = (want: string[]) => waitUntil(() => envOrder(page), (o) => same(o, want));
      const atRest = async (what: string) => {
        const m = await envMenu(page);
        if (m.dragging.length || m.drop.length) fail(`after ${what} the lifted heading or its line stays`);
        if (m.open) fail(`${what} opened the environment's menu`);
        if ((await pathOf(page)) !== start) fail(`${what} opened ${await pathOf(page)}`);
      };

      await page.navigate(base + start);
      await waitShown(page, ["chat-list"]);
      await page.settle();
      page.takeIssues();
      const o0 = await envOrder(page);
      details.start = o0;
      if (o0.length < 3) return fail(`the list shows ${o0.length} environments; the seed has 3`, "shows");
      const heads0 = await envHeads(page);
      if (heads0.some((h) => !h.at)) return fail("a heading shows no name to press");
      const s0 = await read();
      details.scroll = s0.scroll;
      details.select = s0.select;
      if (s0.select !== "none") fail(`a heading's text can be selected (user-select ${s0.select}), so a long press would select it`);

      const seen: { swipe: EnvMenuState | null; held: { menu: EnvMenuState; look: EnvTouchState["look"] } | null; mid: { menu: EnvMenuState; st: EnvTouchState } | null } = { swipe: null, held: null, mid: null };
      // The seed's list fits the screen, so for the scroll checks the list's box is 240 px high; then it is put back.
      const listBox = (js: string) => page.evaluate<number | null>(`(() => { const h = [...document.querySelectorAll(".scr-group-head[data-env]")].find((el) => el.getClientRects().length > 0); const s = h && h.closest(".scr-list-scroll"); if (!s) return null; ${js} })()`);
      const room = await listBox(`s.style.flex = "none"; s.style.height = "240px"; s.scrollTop = 0; return s.scrollHeight - s.clientHeight;`);
      await sleep(200);
      details.room = room;
      let mark = wire.mark();
      if (!room || room < 60) warnings.push({ code: "flow", text: `the list's box has ${room ?? "no"} px to scroll at 240 px high, so the scroll checks did not run` });
      else {
        const hs = (await envHeads(page))[0]!;
        const box = (await read()).scroll!;
        // A short swipe up on a heading: the list scrolls; no lift, no touchmove held back, nothing sent.
        await count();
        await finger(hs.at!.x, hs.at!.y, 0, hs.at!.y - 100, 6, async () => {
          seen.swipe = await envMenu(page);
        });
        const s1 = await read();
        details.swipe = { menu: seen.swipe, scroll: s1.scroll, touch: s1.touch };
        if (seen.swipe?.dragging.length || seen.swipe?.drop.length) fail("a short swipe on a heading lifted it");
        if (!s1.touch?.moves) fail("the page saw no touchmove of the swipe");
        else if (s1.touch.held) fail(`a short swipe on a heading held back ${s1.touch.held} of its ${s1.touch.moves} touchmoves`);
        if (!s1.scroll || s1.scroll.top <= 0) fail(`a short swipe on a heading did not scroll the list (scrollTop ${s1.scroll?.top})`);
        none(wire, mark, "a short swipe");
        await atRest("a short swipe");
        await listBox("s.scrollTop = 0; return 0;");
        await sleep(200);
        // Lifted, a move up holds the list still (a scroll would move it down); the release in its own place sends nothing.
        await count();
        mark = wire.mark();
        await finger(hs.at!.x, hs.at!.y, 600, hs.at!.y - 60, 6);
        const s2 = await read();
        details.still = { scroll: s2.scroll, touch: s2.touch };
        if (s2.scroll && s2.scroll.top !== 0) fail(`a lifted heading's move scrolled the list by the finger (scrollTop ${s2.scroll.top})`);
        if (!s2.touch?.moves || s2.touch.held !== s2.touch.moves) fail(`a lifted heading's move held back ${s2.touch?.held ?? 0} of its ${s2.touch?.moves ?? 0} touchmoves`);
        none(wire, mark, "a lifted heading released in its own place");
        await atRest("a lifted heading released in its own place");
        // Lifted and held at the list's bottom edge: the list scrolls by itself; a second finger then ends it.
        mark = wire.mark();
        await touch("touchStart", [pt(hs.at!.x, hs.at!.y)]);
        await sleep(600);
        for (let i = 1; i <= 6; i++) {
          await touch("touchMove", [pt(hs.at!.x, hs.at!.y + ((box.bottom - 8 - hs.at!.y) * i) / 6)]);
          await sleep(16);
        }
        await sleep(500);
        const s3 = await read();
        const edge = await envMenu(page);
        await touch("touchStart", [pt(hs.at!.x, box.bottom - 8), pt(hs.at!.x + 80, box.top0 + 20, 1)]);
        await sleep(150);
        await touch("touchEnd");
        await sleep(400);
        details.edge = { scroll: s3.scroll, menu: edge };
        if (!s3.scroll || s3.scroll.top <= 0) fail(`a lifted heading held at the list's bottom edge did not scroll it (scrollTop ${s3.scroll?.top})`);
        if (edge.dragging.join() !== o0[0]) fail(`while the list scrolled by itself the lifted heading was ${JSON.stringify(edge.dragging)}`);
        none(wire, mark, "a drag at the edge that a second finger ended");
        await atRest("a drag at the edge that a second finger ended");
      }
      await listBox(`s.style.flex = ""; s.style.height = ""; s.scrollTop = 0; return 0;`);
      await sleep(300);
      if (!same(await envOrder(page), o0)) return fail(`the scroll checks moved a heading: ${(await envOrder(page)).join(", ")}`);

      // A long press with no move: the heading lifts on the raised surface, no menu; its release sends nothing.
      const first = o0[0]!;
      const last = o0[2]!;
      const hf = (await envHeads(page)).find((x) => x.id === first)!;
      mark = wire.mark();
      await finger(hf.at!.x, hf.at!.y, 600, hf.at!.y, 0, async () => {
        seen.held = { menu: await envMenu(page), look: (await read()).look };
        await page.screenshot(shotName(scene, "env-move-touch", vp, theme, "lifted")).catch(() => {});
      });
      const held = seen.held;
      details.held = held;
      if (!held) return fail("the long press could not be read");
      if (held.menu.dragging.join() !== first) fail(`a 600 ms press on the first heading lifted ${JSON.stringify(held.menu.dragging)}, not it`);
      if (held.menu.open) fail("a long press on a heading opened its menu; on touch the long press is the drag's");
      if (!held.look || held.look.opacity !== "1" || held.look.shadow === "none" || held.look.bg === "rgba(0, 0, 0, 0)") fail(`the lifted heading is not on the raised surface (${JSON.stringify(held.look)})`);
      none(wire, mark, "a long press released with no move");
      await atRest("a long press released with no move");

      // A long press and a move below the last heading: every move held back, the line under the last; one move.
      const heads = await envHeads(page);
      const below = heads[heads.length - 1]!.bottom + 6;
      await count();
      mark = wire.mark();
      const before = (await read()).scroll;
      await finger(hf.at!.x, hf.at!.y, 600, below, 10, async () => {
        seen.mid = { menu: await envMenu(page), st: await read() };
        await page.screenshot((shot = shotName(scene, "env-move-touch", vp, theme, "drop"))).catch(() => {});
      });
      const m = seen.mid;
      details.drag = m;
      if (!m) return fail("the drag could not be read");
      if (m.menu.dragging.join() !== first) fail(`mid-drag the lifted heading is ${JSON.stringify(m.menu.dragging)}, not the first`);
      if (m.menu.drop.join() !== `after ${last}`) fail(`mid-drag the drop line is at ${JSON.stringify(m.menu.drop)}, not under the last environment`);
      if (!m.st.touch?.moves || m.st.touch.held !== m.st.touch.moves) fail(`a lifted heading's drag held back ${m.st.touch?.held ?? 0} of its ${m.st.touch?.moves ?? 0} touchmoves; the list must not scroll by the finger`);
      const nearEdge = !!before && (below > before.bottom - 44 || below < before.top0 + 44);
      if (before && m.st.scroll && !nearEdge && m.st.scroll.top !== before.top) fail(`the list scrolled by the finger during the drag (scrollTop ${before.top} then ${m.st.scroll.top})`);
      const dropped = [o0[1]!, o0[2]!, first];
      const got = await wait(dropped);
      if (!same(got, dropped)) fail(`the drop left the order ${got.join(", ")}, not ${dropped.join(", ")}`);
      await sleep(300);
      oneMove(wire, mark, first, "the drop");
      await atRest("the drop");

      // The server holds the order: a second page.
      await withPage(vp, theme === "dark" ? "light" : "dark", async (other) => {
        await other.navigate(base + start);
        await waitShown(other, ["chat-list"]);
        const o = await waitUntil(() => envOrder(other), (x) => same(x, dropped));
        if (!same(o, dropped)) fail(`a second page shows the order ${o.join(", ")}, not ${dropped.join(", ")}`);
      });

      // A second finger ends a lifted drag: no line, nothing sent, the order kept.
      const moved = (await envHeads(page)).find((x) => x.id === first)!;
      const top = (await envHeads(page))[0]!;
      mark = wire.mark();
      await touch("touchStart", [pt(moved.at!.x, moved.at!.y)]);
      await sleep(600);
      for (let i = 1; i <= 8; i++) {
        await touch("touchMove", [pt(moved.at!.x, moved.at!.y + ((top.top + 2 - moved.at!.y) * i) / 8)]);
        await sleep(16);
      }
      await sleep(100);
      const aimed = await envMenu(page);
      await touch("touchStart", [pt(moved.at!.x, top.top + 2), pt(moved.at!.x + 80, top.top + 200, 1)]);
      await sleep(150);
      const two = await envMenu(page);
      await touch("touchEnd");
      await sleep(400);
      details.secondFinger = { aimed, two };
      if (!aimed.drop.length) warnings.push({ code: "flow", text: "the drag that a second finger ends showed no line before it" });
      if (two.dragging.length || two.drop.length) fail("a second finger did not end the lifted drag");
      if (!same(await envOrder(page), dropped)) fail("a drag that a second finger ended moved the heading");
      none(wire, mark, "a drag that a second finger ended");
      await atRest("a drag that a second finger ended");

      // Back to the seed's order: the moved heading dragged to the top.
      mark = wire.mark();
      const again = (await envHeads(page)).find((x) => x.id === first)!;
      await finger(again.at!.x, again.at!.y, 600, top.top + 2, 10);
      const back = await wait(o0);
      if (!same(back, o0)) fail(`the drag to the top left the order ${back.join(", ")}, not ${o0.join(", ")}`);
      await sleep(300);
      oneMove(wire, mark, first, "the drag to the top");
      stateFindings(await page.probe(), vp, failures);

      // A quick tap on a heading's name keeps its link: the project page.
      mark = wire.mark();
      const tap = (await envHeads(page))[0]!;
      await page.press(tap.at!.x, tap.at!.y);
      const went = await waitUntil(() => pathOf(page), (p) => p === `/p/${tap.id}`);
      if (went !== `/p/${tap.id}`) fail(`a quick tap on a heading's name opened ${went}, not /p/${tap.id}`);
      none(wire, mark, "a quick tap on a heading's name");
      issueFindings(page.takeIssues(), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = `${vp.width}x${vp.height} touch: a short swipe scrolls and lifts nothing; a lifted heading holds the list still and scrolls it at its edge; a 600 ms press lifts a heading (no menu) and its release sends nothing; a held drag holds the list, shows the line, and sends one move (a second page agrees); a second finger ends a drag; a quick tap opens the heading's page`;
  return finish({ kind: "flow", name: "env-move-touch", route: "chats", scene, size: sizeTag(vp), theme, path: start, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/** Row 107: the page's own record of the presses: the dragstart events that reached the window (and those that no
 *  handler prevented), and any text that was selected. */
const ENV_PRESS_RECORDER = `(() => {
  if (window.__envPress) return;
  const r = (window.__envPress = { starts: 0, open: 0, selected: [] });
  window.addEventListener("dragstart", (e) => { r.starts++; if (!e.defaultPrevented) r.open++; });
  document.addEventListener("selectionchange", () => { const s = String(getSelection() || "").trim(); if (s && r.selected.length < 5) r.selected.push(s.slice(0, 40)); });
})()`;
/** The moving heading's look (its data-dragging and its raised surface, the ::before), the text selected now, and the
 *  record. */
const ENV_PRESS_STATE = `JSON.stringify((() => {
  const h = document.querySelector(".scr-group-head[data-dragging]");
  const cs = h ? getComputedStyle(h, "::before") : null;
  return {
    how: h ? h.dataset.dragging : null,
    look: cs ? { opacity: cs.opacity, shadow: cs.boxShadow, bg: cs.backgroundColor } : null,
    selected: String(getSelection() || ""),
    rec: window.__envPress || null,
  };
})())`;
interface EnvPressState {
  how: string | null;
  look: { opacity: string; shadow: string; bg: string } | null;
  selected: string;
  rec: { starts: number; open: number; selected: string[] } | null;
}
/** A plain link over the conversation, for the native drag check's own proof: its centre, or null when covered. */
const DRAG_PROOF_LINK = `JSON.stringify((() => {
  const a = document.createElement("a");
  a.id = "ui-check-drag-proof";
  a.href = "#ui-check-drag-proof";
  a.textContent = "a plain link";
  a.style.cssText = "position:fixed;left:60%;top:40%;z-index:2147483647;padding:12px;background:#888;color:#000";
  a.addEventListener("click", (e) => e.preventDefault());
  document.body.append(a);
  const r = a.getBoundingClientRect();
  const x = r.left + r.width / 2, y = r.top + r.height / 2;
  return document.elementFromPoint(x, y) === a ? { x, y } : null;
})())`;

/**
 * Row 107, a mouse's long press on a heading (env-move-longpress): 1280x800 and 1100x800, dark and light (with the
 * screenshots of the lifted heading and of its line), on a chat's page, with CDP Input.setInterceptDrags on, so that a
 * native drag that Chrome starts is reported (Input.dragIntercepted); a mouse drag of a plain link must be reported
 * first, or the check proves nothing. Then: a press held 700 ms with a 5 px jitter (under the 8 px slop) is not lifted
 * at 250 ms, and then is lifted on the raised surface (not dimmed as the plain drag), opens no menu, and its release
 * sends nothing and opens nothing; a held press moved below the last heading shows the line under it, and its release
 * sends one move, opens nothing and puts it last, as a second page shows; Esc during a lifted drag puts it back, and
 * the release over its own name sends nothing and opens nothing; row 99's plain drag (a move at once) dims it and puts
 * the seed's order back with one move; and a short click on a heading's name opens its page. No native drag comes
 * during any of them, no dragstart goes unprevented, and no text is selected.
 */
async function envMoveLongPressFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  const start = `/c/${EX.chat}`;
  const tag = vp.width === WIDE_LAPTOP.width ? "-1280" : "";
  let shot: string | undefined;
  const oneMove = (wire: Wire, mark: number, env: string, what: string) => {
    const sent = postsSince(wire, mark);
    if (sent.length !== 1 || sent[0]!.path !== `/api/projects/${env}/move` || sent[0]!.status !== 200) fail(`${what} sent ${sent.length ? clipList(sent.map(httpText)) : "nothing"}; expected one POST /api/projects/${env}/move (200)`, "click");
  };
  const none = (wire: Wire, mark: number, what: string) => {
    const sent = postsSince(wire, mark);
    if (sent.length) fail(`${what} sent ${clipList(sent.map(httpText))}`, "click");
  };
  try {
    await withPage(vp, theme, async (page, wire) => {
      const hover = (x: number, y: number) => page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x, y });
      const down = (x: number, y: number) => page.send("Input.dispatchMouseEvent", { type: "mousePressed", x, y, button: "left", buttons: 1, clickCount: 1 });
      const to = (x: number, y: number) => page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x, y, button: "left", buttons: 1 });
      const release = (x: number, y: number) => page.send("Input.dispatchMouseEvent", { type: "mouseReleased", x, y, button: "left", buttons: 0, clickCount: 1 });
      /** The pressed mouse moved from (x, y) to (x, y2) in `steps` steps 16 ms apart. */
      const slide = async (x: number, y: number, y2: number, steps: number) => {
        for (let i = 1; i <= steps; i++) {
          await to(x, y + ((y2 - y) * i) / steps);
          await sleep(16);
        }
      };
      const read = async () => JSON.parse(await page.evaluate<string>(ENV_PRESS_STATE)) as EnvPressState;
      const seen: { data: { items?: { mimeType: string; data: string }[] } }[] = [];
      const offDrags = cdp.on((e) => {
        if (e.sessionId === page.session && e.method === "Input.dragIntercepted") seen.push({ data: e.params.data ?? {} });
      });
      /** No native drag since `mark`: else a failure that names what started it. */
      const noNative = (mark: number, what: string) => {
        const got = seen.slice(mark);
        if (got.length) fail(`${what} started the browser's own drag (${got.length} Input.dragIntercepted: ${clipList(got.flatMap((g) => (g.data.items ?? []).map((i) => `${i.mimeType} ${String(i.data).slice(0, 60)}`)))})`);
      };
      const same = (a: string[], b: string[]) => a.join() === b.join();
      const wait = (want: string[]) => waitUntil(() => envOrder(page), (o) => same(o, want));
      const atRest = async (what: string) => {
        const m = await envMenu(page);
        if (m.dragging.length || m.drop.length) fail(`after ${what} the moving heading or its line stays`);
        if (m.open) fail(`${what} opened the environment's menu`);
        if ((await pathOf(page)) !== start) fail(`${what} opened ${await pathOf(page)}`);
        const s = (await read()).selected.trim();
        if (s) fail(`after ${what} text is selected: ${JSON.stringify(s.slice(0, 40))}`);
      };
      try {
        await page.navigate(base + start);
        await waitShown(page, ["conversation"]);
        await page.settle();
        page.takeIssues();
        await page.send("Input.setInterceptDrags", { enabled: true });
        const o0 = await envOrder(page);
        details.start = o0;
        if (o0.length < 3) return fail(`the list shows ${o0.length} environments; the seed has 3`, "shows");

        // The check's own proof: a mouse drag of a plain link is a native drag, and Chrome reports it.
        const proof = JSON.parse(await page.evaluate<string>(DRAG_PROOF_LINK)) as { x: number; y: number } | null;
        if (!proof) return fail("the plain link of the native drag check is covered");
        await hover(proof.x, proof.y);
        await down(proof.x, proof.y);
        await slide(proof.x, proof.y, proof.y + 48, 8);
        await sleep(250);
        details.proof = seen.length;
        if (seen[0]) await page.send("Input.dispatchDragEvent", { type: "dragCancel", x: proof.x, y: proof.y + 48, data: seen[0].data });
        await release(proof.x, proof.y + 48);
        await page.evaluate(`document.getElementById("ui-check-drag-proof").remove()`);
        await sleep(200);
        if (!seen.length) return fail("a mouse drag of a plain link was not reported as a native drag, so this check could not see one on a heading");
        await page.evaluate(ENV_PRESS_RECORDER);

        // A press held 700 ms with a 5 px jitter: not lifted at 250 ms, then lifted on the raised surface; no menu;
        // its release sends nothing and opens nothing.
        const first = o0[0]!;
        const last = o0[2]!;
        const hf = (await envHeads(page)).find((x) => x.id === first);
        if (!hf?.at) return fail("the first heading shows no name to press");
        let mark = wire.mark();
        let m0 = seen.length;
        await hover(hf.at.x, hf.at.y);
        await down(hf.at.x, hf.at.y);
        await sleep(150);
        await to(hf.at.x + 3, hf.at.y + 4);
        await sleep(100);
        const early = await read();
        await sleep(450);
        const held = { menu: await envMenu(page), st: await read() };
        await page.screenshot((shot = shotName(scene, "env-move-longpress", vp, theme, `lifted${tag}`))).catch(() => {});
        await release(hf.at.x + 3, hf.at.y + 4);
        await sleep(400);
        details.early = early;
        details.held = held;
        if (early.how) fail(`250 ms into a press the heading is already ${early.how === "mouse" ? "in the plain drag (a 5 px jitter is under the 8 px slop)" : "lifted"}; it lifts at 450 ms`);
        if (held.st.how !== "lift" || held.menu.dragging.join() !== first) fail(`a 700 ms press with a 5 px jitter shows ${JSON.stringify(held.menu.dragging)} as ${JSON.stringify(held.st.how)}, not the first heading lifted`);
        if (!held.st.look || held.st.look.opacity !== "1" || held.st.look.shadow === "none" || held.st.look.bg === "rgba(0, 0, 0, 0)") fail(`the lifted heading is not on the raised surface (${JSON.stringify(held.st.look)})`);
        if (held.menu.open) fail("a long press on a heading opened its menu");
        if (held.st.selected.trim()) fail(`a long press selected text: ${JSON.stringify(held.st.selected.trim().slice(0, 40))}`);
        none(wire, mark, "a long press released with no move");
        noNative(m0, "a long press");
        await atRest("a long press released with no move");

        // A held press moved below the last heading: the line under the last; the release sends one move.
        const heads = await envHeads(page);
        const below = heads[heads.length - 1]!.bottom + 6;
        mark = wire.mark();
        m0 = seen.length;
        await hover(hf.at.x, hf.at.y);
        await down(hf.at.x, hf.at.y);
        await sleep(600);
        await slide(hf.at.x, hf.at.y, below, 10);
        await sleep(100);
        const mid = { menu: await envMenu(page), st: await read() };
        await page.screenshot(shotName(scene, "env-move-longpress", vp, theme, `drop${tag}`)).catch(() => {});
        await release(hf.at.x, below);
        await sleep(400);
        details.drag = mid;
        if (mid.menu.dragging.join() !== first || mid.st.how !== "lift") fail(`mid-drag the moving heading is ${JSON.stringify(mid.menu.dragging)} as ${JSON.stringify(mid.st.how)}, not the first one lifted`);
        if (mid.menu.drop.join() !== `after ${last}`) fail(`mid-drag the drop line is at ${JSON.stringify(mid.menu.drop)}, not under the last environment`);
        if (mid.st.selected.trim()) fail(`a long press's drag selected text: ${JSON.stringify(mid.st.selected.trim().slice(0, 40))}`);
        const dropped = [o0[1]!, o0[2]!, first];
        const got = await wait(dropped);
        if (!same(got, dropped)) fail(`the drop left the order ${got.join(", ")}, not ${dropped.join(", ")}`);
        await sleep(300);
        oneMove(wire, mark, first, "the long press's drop");
        noNative(m0, "a long press's drag");
        await atRest("the long press's drop");

        // The server holds the order: a second page.
        await withPage(vp, theme === "dark" ? "light" : "dark", async (other) => {
          await other.navigate(base + "/chats");
          await waitShown(other, ["chat-list"]);
          const o = await waitUntil(() => envOrder(other), (x) => same(x, dropped));
          if (!same(o, dropped)) fail(`a second page shows the order ${o.join(", ")}, not ${dropped.join(", ")}`);
        });

        // Esc during a lifted drag puts it back; the release over its own name sends nothing and opens nothing.
        const moved = (await envHeads(page)).find((x) => x.id === first);
        const top = (await envHeads(page))[0]!;
        if (!moved?.at) return fail("the moved heading shows no name to press");
        mark = wire.mark();
        m0 = seen.length;
        await hover(moved.at.x, moved.at.y);
        await down(moved.at.x, moved.at.y);
        await sleep(600);
        await slide(moved.at.x, moved.at.y, top.top + 2, 8);
        await sleep(100);
        const aimed = await envMenu(page);
        await slide(moved.at.x, top.top + 2, moved.at.y, 8);
        await envKey(page, "Escape");
        await sleep(100);
        const stopped = await envMenu(page);
        await release(moved.at.x, moved.at.y);
        await sleep(500);
        details.esc = { aimed, stopped };
        if (!aimed.drop.length) warnings.push({ code: "flow", text: "the long press's drag that Esc stops showed no line before Esc" });
        if (stopped.dragging.length || stopped.drop.length) fail("Esc did not put the lifted heading back");
        if (!same(await envOrder(page), dropped)) fail("a long press's drag stopped with Esc moved the heading");
        none(wire, mark, "a long press's drag stopped with Esc");
        noNative(m0, "a long press's drag stopped with Esc");
        await atRest("a long press's drag stopped with Esc and released over its own name");

        // Row 99's plain drag (a move at once) dims the heading and puts the seed's order back with one move.
        mark = wire.mark();
        m0 = seen.length;
        const plain: { st: EnvPressState | null } = { st: null };
        await mouseDrag(page, moved.at.x, moved.at.y, top.top + 2, async () => {
          plain.st = await read();
        });
        details.plain = plain.st;
        if (plain.st?.how !== "mouse") fail(`row 99's plain drag shows the heading as ${JSON.stringify(plain.st?.how)}, not dimmed`);
        const back = await wait(o0);
        if (!same(back, o0)) fail(`row 99's plain drag to the top left the order ${back.join(", ")}, not ${o0.join(", ")}`);
        await sleep(300);
        oneMove(wire, mark, first, "row 99's plain drag to the top");
        noNative(m0, "row 99's plain drag");
        await atRest("row 99's plain drag");
        stateFindings(await page.probe(), vp, failures);

        // A short click on a heading's name keeps its link: the environment's page.
        mark = wire.mark();
        m0 = seen.length;
        const tap = (await envHeads(page))[0]!;
        await page.press(tap.at!.x, tap.at!.y);
        const went = await waitUntil(() => pathOf(page), (p) => p === `/p/${tap.id}`);
        if (went !== `/p/${tap.id}`) fail(`a short click on a heading's name opened ${went}, not /p/${tap.id}`);
        none(wire, mark, "a short click on a heading's name");
        noNative(m0, "a short click on a heading's name");
        const rec = (await read()).rec;
        details.record = rec;
        details.native = seen.length - (details.proof as number);
        if (!rec) fail("the page's record of the presses is gone");
        else {
          if (rec.open) fail(`${rec.open} of the page's ${rec.starts} dragstart events were not prevented`);
          if (rec.selected.length) fail(`text was selected during the presses: ${clipList(rec.selected)}`);
        }
        issueFindings(page.takeIssues(), failures);
      } finally {
        offDrags();
      }
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = `${vp.width}x${vp.height}, native drags reported (a plain link's proved it): a 700 ms press with a 5 px jitter lifts the heading on the raised surface (no menu, nothing sent); a held drag shows the line and sends one move (a second page agrees); Esc puts it back and its release opens nothing; row 99's plain drag dims it and moves it back; a short click opens its page; no native drag, no text selected`;
  return finish({ kind: "flow", name: "env-move-longpress", route: "chats", scene, size: sizeTag(vp), theme, path: start, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * Row 99, the two paths (env-routes): /p/<project>/rename and /p/<project>/remove, each opened as a new document and
 * reloaded, show the field (the name in it) and the confirm; from the project page's "...", Rename and Remove push their
 * path, Back takes the field or the confirm away and Forward brings it back. Nothing is sent.
 */
async function envRoutesFlow(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  const env = IDS.projects.notes;
  const page0 = `/p/${env}`;
  let shot: string | undefined;
  const STATE = `JSON.stringify((() => {
    const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
    const f = document.getElementById("scr-env-name");
    return { path: location.pathname + location.search, field: shown(f) ? f.value : null, confirm: shown(document.querySelector('[data-testid="dialog-remove-project"]')), title: (document.querySelector(".scr-h1") || {}).textContent || null, notice: shown(document.querySelector('[data-testid="link-notice"]')) };
  })())`;
  type St = { path: string; field: string | null; confirm: boolean; title: string | null; notice: boolean };
  try {
    await withPage(vp, "dark", async (page, wire) => {
      const since = wire.mark();
      const st = async () => JSON.parse(await page.evaluate<string>(STATE)) as St;
      const expect = async (label: string, want: Partial<St>) => {
        const s = await waitUntil(st, (x) => Object.entries(want).every(([k, v]) => x[k as keyof St] === v));
        details[label] = s;
        for (const [k, v] of Object.entries(want)) if (s[k as keyof St] !== v) fail(`${label}: ${k} is ${JSON.stringify(s[k as keyof St])}, not ${JSON.stringify(v)}`);
        if (s.notice) fail(`${label}: a 5.4 line shows`);
        return s;
      };
      for (const [path, want] of [
        [`/p/${env}/rename`, { field: "notes-api", confirm: false }],
        [`/p/${env}/rename?name=notes%20service`, { field: "notes service", confirm: false }],
        [`/p/${env}/remove`, { field: null, confirm: true }],
      ] as const) {
        await page.navigate(base + path);
        await waitShown(page, ["project"]);
        await expect(`${path} opened`, { path, ...want });
        await page.reload();
        await waitShown(page, ["project"]);
        await expect(`${path} reloaded`, { path, ...want });
      }
      shot = shotName(scene, "env-routes", vp, "dark", "remove");
      await page.screenshot(shot).catch(() => {});
      for (const [row, path, want] of [
        ["env-rename", `/p/${env}/rename`, { field: "notes-api" }],
        ["env-remove", `/p/${env}/remove`, { confirm: true }],
      ] as const) {
        await page.navigate(base + page0);
        await waitShown(page, ["project"]);
        const more = await page.locate('[data-testid="project-more"]');
        if (!more) return fail("the project page shows no \"...\" beside New chat here", "shows");
        await page.press(more.x, more.y);
        if (!(await waitUntil(() => envMenu(page), (x) => x.open)).open) return fail("the project page's \"...\" opened no menu");
        await page.settle();
        const rows = (await envMenu(page)).rows;
        if (rows.join() !== "Rename,Remove") fail(`the project page's menu has ${rows.join(", ")}, not Rename and Remove`);
        if (!(await pressEnvRow(page, row, fail))) return;
        await expect(`${row} from the page's menu`, { path, ...want });
        const h = await page.history();
        const prev = h.entries[h.currentIndex - 1];
        if (!prev || new URL(prev.url).pathname !== page0) {
          fail(`${row} did not push its path after the project page (the entry before is ${prev?.url})`);
          continue;
        }
        await page.goToEntry(prev.id);
        await expect(`Back from ${row}`, { path: page0, field: null, confirm: false, title: "notes-api" });
        const fwd = (await page.history()).entries.find((e) => new URL(e.url).pathname === path);
        if (fwd) {
          await page.goToEntry(fwd.id);
          await expect(`Forward to ${row}`, { path, ...want });
        } else fail(`no entry to go Forward to ${path}`);
      }
      stateFindings(await page.probe(), vp, failures);
      issueFindings(page.takeIssues(), failures);
      quietFindings(wire, since, await recorder(page), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return finish({ kind: "flow", name: "env-routes", route: "projectRename", scene, size: sizeTag(vp), theme: "dark", path: `/p/${env}/rename`, failures, warnings, note: `${vp.width}x${vp.height}: the rename and remove paths as new documents, reloaded, and from the page's menu with Back and Forward; nothing sent`, shot, ms: Date.now() - t0, details });
}

/**
 * Row 99, Remove (env-remove), on the running scene's seed (the example chat's turn runs, in the example project), at
 * 1280x800 and 390x844 touch, dark and light. The example project's Remove opens /p/<project>/remove with the one line
 * that a chat there works or needs input, and no Remove; Close (Cancel on the phone's sheet) goes back. notes-api's
 * Remove says that its 3 chats leave kitespan and the folder stays; in the first theme Cancel goes back with nothing
 * sent; in the last, with a second page on one of its chats, Remove sends one POST /api/projects/:project/remove: this
 * page goes to /, the heading and its chats leave the list, and the second page goes to / with no 5.4 line at any time.
 */
async function envRemoveFlow(t: Target, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  const base = t.base;
  const scene = t.scene;
  const env = IDS.projects.notes;
  const start = vp.touch ? "/chats" : `/c/${EX.chat}`;
  const tag = vp.width === WIDE_LAPTOP.width ? "1280" : "";
  const busyLine = "A chat here is working or needs input. Remove this environment when it is done.";
  const removeLine = "Its 3 chats leave kitespan. Their conversations stay in Claude Code, and the folder is not changed.";
  let shot: string | undefined;
  const DIALOG = `JSON.stringify((() => {
    const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
    const box = [...document.querySelectorAll('[data-testid="dialog-remove-project"]')].find(shown);
    return { open: !!box, text: box ? box.textContent.replace(/\\s+/g, " ").trim() : "", busy: shown(document.querySelector('[data-testid="remove-busy"]')), remove: shown(document.querySelector('[data-testid="confirm-remove"]')), path: location.pathname };
  })())`;
  type Dlg = { open: boolean; text: string; busy: boolean; remove: boolean; path: string };
  try {
    for (const theme of THEMES) {
      const last = theme === THEMES[THEMES.length - 1];
      await withPage(vp, theme, async (page, wire) => {
        const dlg = async () => JSON.parse(await page.evaluate<string>(DIALOG)) as Dlg;
        await page.navigate(base + start);
        await waitShown(page, [vp.touch ? "chat-list" : "conversation"]);
        page.takeIssues();
        const since = wire.mark();
        const close = async (what: string) => {
          const sel = vp.name === "phone" ? '[data-testid="dialog-remove-project"] [data-testid="sheet-cancel"]' : '[data-testid="dialog-remove-project"] .dialog-actions button:not([data-testid])';
          const at = await page.locate(sel);
          if (!at) return fail(`${what} shows no ${vp.name === "phone" ? "Cancel at the top right" : "Close or Cancel"}`);
          await page.press(at.x, at.y);
          const p = await waitUntil(() => pathOf(page), (x) => x === start);
          if (p !== start) fail(`closing ${what} went to ${p}, not back to ${start}`);
        };
        // The refusal: a chat of the example project runs.
        if (!(await openEnvMenu(page, EX.project, fail))) return;
        if (!(await pressEnvRow(page, "env-remove", fail))) return;
        const r = await waitUntil(dlg, (x) => x.open);
        details[`${theme} refusal`] = r;
        if (r.path !== `/p/${EX.project}/remove`) fail(`Remove opened ${r.path}, not /p/${EX.project}/remove`);
        if (!r.open || !r.busy || !r.text.includes(busyLine)) fail(`with the example chat running, Remove shows ${JSON.stringify(r.text)}, not the line ${JSON.stringify(busyLine)}`);
        if (r.remove) fail("with the example chat running, the confirm still offers Remove");
        stateFindings(await page.probe(), vp, failures, "the refusal: ");
        await page.screenshot(shotName(scene, "env-remove", vp, theme, `${tag}refusal`)).catch(() => {});
        await close("the refusal");
        // The confirm of an environment whose chats sleep.
        if (!(await openEnvMenu(page, env, fail))) return;
        if (!(await pressEnvRow(page, "env-remove", fail))) return;
        const c = await waitUntil(dlg, (x) => x.open);
        details[`${theme} confirm`] = c;
        if (!c.open || c.busy || !c.remove || !c.text.includes(removeLine) || !c.text.includes("Remove notes-api?")) fail(`notes-api's Remove shows ${JSON.stringify(c.text)} (Remove ${c.remove ? "shown" : "missing"}); expected "Remove notes-api?" and ${JSON.stringify(removeLine)}`);
        stateFindings(await page.probe(), vp, failures, "the confirm: ");
        if (vp.touch) await touchSmall(page, warnings, "the confirm");
        shot = shotName(scene, "env-remove", vp, theme, `${tag}confirm`);
        await page.screenshot(shot).catch(() => {});
        if (!last) {
          await close("the confirm");
          if (postsSince(wire, since).length || acting(wire.framesSince(since)).length) fail(`the menu, the refusal and the confirm sent ${clipList([...postsSince(wire, since).map(httpText), ...acting(wire.framesSince(since)).map(frameText)])}`, "click");
          issueFindings(page.takeIssues(), failures);
          return;
        }
        // Remove, with a second page on one of its chats: both go to /, the second with no 5.4 line.
        await withPage(vp, theme, async (other) => {
          await other.navigate(base + `/c/${IDS.chats.search}`);
          await waitShown(other, ["chat"]);
          other.takeIssues();
          await other.evaluate(`(() => {
            window.__flash = [];
            const look = () => { const t = document.body ? document.body.innerText : ""; for (const w of ["is not here", "could not be read"]) if (t.includes(w) && !window.__flash.includes(w)) window.__flash.push(w); };
            new MutationObserver(look).observe(document.documentElement, { subtree: true, childList: true, characterData: true });
          })()`);
          const mark = wire.mark();
          const at = await page.locate('[data-testid="confirm-remove"]');
          if (!at) return fail("the confirm shows no Remove");
          await page.press(at.x, at.y);
          const p = await waitUntil(() => pathOf(page), (x) => x === "/", 8000);
          if (p !== "/") fail(`after Remove this page is on ${p}, not /`);
          await sleep(500);
          const sent = postsSince(wire, mark);
          details.sent = sent.map(httpText);
          if (sent.length !== 1 || sent[0]!.path !== `/api/projects/${env}/remove` || sent[0]!.status !== 200) fail(`Remove sent ${sent.length ? clipList(sent.map(httpText)) : "nothing"}; expected one POST /api/projects/${env}/remove (200)`, "click");
          const heads = await waitUntil(() => envOrder(page), (o) => !o.includes(env));
          if (heads.includes(env)) fail("the removed environment's heading is still in this page's list");
          const op = await waitUntil(() => pathOf(other), (x) => x === "/", 8000);
          if (op !== "/") fail(`the second page, on a chat of the removed environment, is on ${op}, not /`);
          await sleep(500);
          const flash = await other.evaluate<string[]>("window.__flash || []");
          details.flash = flash;
          if (flash.length) fail(`the second page showed a line while it left: ${flash.join(", ")}`);
          const otherState = await other.probe();
          if (otherState.ids.includes("link-notice")) fail("the second page shows a 5.4 line on /");
          if ((await other.evaluate<number>(`document.querySelectorAll('a[href="/c/${IDS.chats.search}"]').length`)) > 0) fail("the second page still lists a chat of the removed environment");
          issueFindings(other.takeIssues(), failures, "the second page: ");
          await page.screenshot(shotName(scene, "env-remove", vp, theme, `${tag}after`)).catch(() => {});
        });
        stateFindings(await page.probe(), vp, failures);
        issueFindings(page.takeIssues(), failures);
      });
    }
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = `${vp.width}x${vp.height}${vp.touch ? " touch" : ""}: Remove refused with its line while the example chat runs; notes-api's confirm; Remove sends one request, both pages go to / with no line`;
  return finish({ kind: "flow", name: "env-remove", route: "projectRemove", scene, size: sizeTag(vp), theme: THEMES[THEMES.length - 1]!, path: start, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

// ---------------------------------------------------------------------------------------------------------------
// v0.3 search: the search pane and its key (DESIGN.md 9.3, 6.7, 6.11, 7.2, 7.3, 8.3; BUILD-CHECKLIST C4, C5, D3)

/** The search pane as the page shows it: its place, the field, the list's query and rows, the bar, the lines. */
const SEARCH_STATE = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const root = [...document.querySelectorAll('[data-testid="search"]')].find(shown);
  const field = root ? root.querySelector('[data-testid="search-input"]') : null;
  const list = root ? root.querySelector('[data-testid="search-results"]') : null;
  const rows = list ? [...list.querySelectorAll('[role="option"]')] : [];
  const active = rows.findIndex((r) => r.getAttribute("aria-selected") === "true");
  const chip = [...document.querySelectorAll('[data-testid="composer"] .cmp-chip.is-slash')].find(shown);
  return {
    path: location.pathname + location.search,
    open: !!root,
    place: root ? root.getAttribute("data-place") : null,
    focused: !!field && document.activeElement === field,
    selected: !!field && document.activeElement === field && field.value.length > 0 && field.selectionStart === 0 && field.selectionEnd === field.value.length,
    value: field ? field.value : null,
    q: list ? list.getAttribute("data-q") : null,
    count: list ? Number(list.getAttribute("data-count")) : null,
    rows: rows.length,
    kinds: rows.map((r) => r.getAttribute("data-kind")),
    texts: rows.slice(0, 40).map((r) => r.textContent.trim()),
    active,
    activeOk: active < 0 || (!!field && field.getAttribute("aria-activedescendant") === rows[active].id),
    heights: rows.filter(shown).slice(0, 20).map((r) => Math.round(r.getBoundingClientRect().height)),
    empty: root && shown(root.querySelector('[data-testid="search-empty"]')) ? root.querySelector('[data-testid="search-empty"]').textContent.trim() : null,
    notices: [...document.querySelectorAll('[data-testid="link-notice"]')].filter(shown).map((e) => e.textContent.trim()),
    lit: [...document.querySelectorAll(".pane-bar-btn.on")].filter(shown).map((b) => (b.querySelector(".pane-bar-name") || b).getAttribute("aria-label") || (b.querySelector(".pane-bar-name") || b).textContent.trim()),
    bar: (() => { const b = [...document.querySelectorAll('[data-testid="topbar"]')].find(shown); return b ? [...b.children].filter(shown).map((c) => c.textContent.replace(/\\s+/g, " ").trim()).filter(Boolean).join(" ") : ""; })(),
    heading: !!root && [...root.querySelectorAll("h1, h2, h3")].some(shown),
    chatShown: [...document.querySelectorAll('[data-testid="chat"]')].some(shown),
    chip: chip ? chip.textContent.trim() : null,
    scope: [...document.querySelectorAll('[data-testid="search"] [role="radio"][aria-checked="true"]')].map((r) => r.getAttribute("data-value")),
  };
})())`;

interface SearchState {
  path: string;
  open: boolean;
  place: string | null;
  focused: boolean;
  selected: boolean;
  value: string | null;
  q: string | null;
  count: number | null;
  rows: number;
  kinds: string[];
  texts: string[];
  active: number;
  activeOk: boolean;
  heights: number[];
  empty: string | null;
  notices: string[];
  lit: string[];
  bar: string;
  heading: boolean;
  chatShown: boolean;
  chip: string | null;
  scope: string[];
}

const readSearch = async (page: Page) => JSON.parse(await page.evaluate<string>(SEARCH_STATE)) as SearchState;

/** Poll the pane until `ok` holds (or `ms` passes); the last state either way. */
async function untilSearch(page: Page, ok: (s: SearchState) => boolean, ms = 4000): Promise<SearchState> {
  const end = Date.now() + ms;
  let s = await readSearch(page);
  while (!ok(s) && Date.now() < end) {
    await sleep(60);
    s = await readSearch(page);
  }
  return s;
}

const SEARCH_KEYS: Record<string, [code: string, vk: number]> = { ArrowDown: ["ArrowDown", 40], ArrowUp: ["ArrowUp", 38], Enter: ["Enter", 13], Escape: ["Escape", 27], Backspace: ["Backspace", 8] };

/** One key press over CDP (Page.key has Escape and Enter only): a named key, or a letter with Ctrl or Cmd. */
async function pressKey(page: Page, key: string, mods: { ctrl?: boolean; meta?: boolean } = {}) {
  const [code, vk] = SEARCH_KEYS[key] ?? [`Key${key.toUpperCase()}`, key.toUpperCase().charCodeAt(0)];
  const modifiers = (mods.ctrl ? 2 : 0) | (mods.meta ? 4 : 0);
  const base = { key, code, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk, modifiers };
  await page.send("Input.dispatchKeyEvent", { type: modifiers ? "rawKeyDown" : "keyDown", ...base, ...(key === "Enter" && !modifiers ? { text: "\r" } : {}) });
  await page.send("Input.dispatchKeyEvent", { type: "keyUp", ...base });
}

/** Search's key as headless Linux has it: Ctrl+K (the page's macOS rule, Cmd+K, is a unit test's). */
const searchKey = (page: Page) => pressKey(page, "k", { ctrl: true });

/** Type into the focused field one character at a time, as a person does (each one its own input event). */
async function typeText(page: Page, text: string) {
  for (const ch of text) {
    await page.send("Input.insertText", { text: ch });
    await sleep(25);
  }
}

/** Put this text in the pane's field as one replacement of what it holds (select all, then type over it). */
async function replaceQuery(page: Page, text: string) {
  await page.evaluate(`(() => { const f = [...document.querySelectorAll('[data-testid="search-input"]')].find((e) => e.getClientRects().length); f.focus(); f.select(); })()`);
  await page.send("Input.insertText", { text });
}

/** The centre of the first shown result row whose text holds `needle` (scrolled into view), or null. */
async function searchRowAt(page: Page, needle: string, kind?: string): Promise<{ x: number; y: number; index: number } | null> {
  return page.evaluate(`(() => {
    const rows = [...document.querySelectorAll('[data-testid="search"] [role="option"]')].filter((r) => r.getClientRects().length);
    const index = rows.findIndex((r) => r.textContent.includes(${JSON.stringify(needle)}) && (${JSON.stringify(kind ?? null)} === null || r.getAttribute("data-kind") === ${JSON.stringify(kind ?? null)}));
    if (index < 0) return null;
    rows[index].scrollIntoView({ block: "center", behavior: "instant" });
    const b = rows[index].getBoundingClientRect();
    return { x: b.left + b.width / 2, y: b.top + b.height / 2, index };
  })()`);
}

/** The shown search list scrolled to its end: its box, its last row's, the field's (CSS px from the top), the visual height. */
const LIST_AT_END = `(() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && !el.closest('[hidden="until-found"]');
  const box = (el) => { const r = el.getBoundingClientRect(); return [Math.round(r.top), Math.round(r.bottom)]; };
  const root = [...document.querySelectorAll('[data-testid="search"]')].find(shown);
  const list = root ? root.querySelector('[data-testid="search-results"]') : null;
  const field = root ? root.querySelector('[data-testid="search-input"]') : null;
  const visual = Math.round(visualViewport.height);
  if (!list || !shown(list)) return { visual, list: null, last: null, field: field && shown(field) ? box(field) : null, scrolls: false };
  list.scrollTop = list.scrollHeight;
  const rows = [...list.querySelectorAll('[role="option"]')].filter(shown);
  return { visual, list: box(list), last: rows.length ? box(rows[rows.length - 1]) : null, field: field && shown(field) ? box(field) : null, scrolls: list.scrollHeight > list.clientHeight + 1 };
})()`;

interface ListAtEnd {
  visual: number;
  list: [number, number] | null;
  last: [number, number] | null;
  field: [number, number] | null;
  scrolls: boolean;
}

/** The element that has the focus, by name: "composer" (the message box's field), "search" (the pane's), else its tag. */
const FOCUS_NAME = `(() => {
  const a = document.activeElement;
  if (!a || a === document.body) return "body";
  if (a.matches('[data-testid="composer-input"]')) return "composer";
  if (a.matches('[data-testid="search-input"]')) return "search";
  return a.tagName.toLowerCase() + (a.getAttribute("data-testid") ? "[" + a.getAttribute("data-testid") + "]" : "");
})()`;

/** Back, as the browser's button does, and the page settled. */
async function goBack(page: Page) {
  const h = await page.history();
  const prev = h.entries[h.currentIndex - 1];
  if (prev) await page.goToEntry(prev.id);
}

const TOO_LONG_LINE = "That link's text is too long to fill in (the limit is 5,000 characters, or 120 for a title or a setting).";
const PART_UNREAD_LINE = "Part of that link could not be read.";

/**
 * The search pane on a laptop (1100 x 800, a fine pointer; 9.3, 6.7, C4): Ctrl+K from the composer field opens the
 * chat's pane in the side panel's column with its field focused and the URL as it is (no q); typing narrows; Down
 * twice, then one more letter, and the active row is the first again (aria-activedescendant follows it); the typed
 * query reaches the URL with replaceState (no new entry); Esc goes back to the chat, with the focus back in the composer
 * field that opened the pane (6.7 "back to where the user was"); Enter on a chat, a file, an upload and a command each
 * navigates (the command fills the composer's chip), Back returns to the results with q, and a
 * reload keeps q and scope; a bad scope and an over-cap q each show their one 5.4 line. Nothing mutating goes out.
 */
async function searchPaneFlow(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const chat = `/c/${EX.chat}`;
  const pane = `${chat}/search`;
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  let shot: string | undefined;
  try {
    await withPage(vp, "light", async (page, wire) => {
      await page.navigate(base + chat);
      await waitShown(page, ["chat"]);
      page.takeIssues();
      const since = wire.mark();
      await page.evaluate(`(() => { const el = ${FIELD}; if (el) el.focus(); })()`);
      await searchKey(page);
      let s = await untilSearch(page, (x) => x.open && x.rows > 0);
      details.opened = s;
      if (!s.open) fail("Ctrl+K from the composer field opened no search pane");
      if (s.path !== pane) fail(`Ctrl+K opened ${s.path}, not ${pane} as it is`);
      // v0.6 touch: the large tablet in portrait has every pane over the chat (DESIGN 7.4).
      const place = vp.touch && vp.height > vp.width ? "over" : "column";
      if (s.place !== place) fail(`the pane is in the "${s.place}" place, not ${place === "over" ? "over the chat" : "the side panel's column"}`);
      if (!s.focused) fail("the field does not have the focus on a laptop");
      const entries = (await page.history()).entries.length;
      // Type: the list narrows and its root says the query it shows.
      await typeText(page, "th");
      s = await untilSearch(page, (x) => x.q === "th" && x.value === "th");
      if (s.q !== "th") fail(`after typing "th" the list shows ${JSON.stringify(s.q)}`);
      if (s.rows < 3) fail(`"th" gives ${s.rows} rows; the seed's chat titles give more than 3`);
      if (s.rows > 120) fail(`the list draws ${s.rows} rows, over 120`);
      await pressKey(page, "ArrowDown");
      await pressKey(page, "ArrowDown");
      s = await untilSearch(page, (x) => x.active === 2);
      if (s.active !== 2) fail(`after Down twice the active row is ${s.active}, not the third`);
      if (!s.activeOk) fail("aria-activedescendant does not name the active row");
      await typeText(page, "e");
      s = await untilSearch(page, (x) => x.q === "the");
      details.reset = { active: s.active, rows: s.rows };
      if (s.active !== 0) fail(`after one more letter the active row is ${s.active}, not the first (the highlight resets on each query)`);
      await sleep(500);
      s = await readSearch(page);
      if (s.path !== `${pane}?q=the`) fail(`once the typing paused the URL is ${s.path}, not ${pane}?q=the`);
      if ((await page.history()).entries.length !== entries) fail("typing added a history entry (q is written with replaceState)");
      // Esc: back to where the user was, with the focus back in the composer field that opened the pane.
      await pressKey(page, "Escape");
      s = await untilSearch(page, (x) => !x.open);
      if (s.open || s.path !== chat) fail(`Esc left ${s.path}${s.open ? " with the pane open" : ""}; expected ${chat}`);
      const escFocus = await page.evaluate<string>(FOCUS_NAME);
      details.escFocus = escFocus;
      if (escFocus !== "composer") fail(`after Esc the focus is on ${escFocus}, not back in the composer field that opened the pane`);
      // Enter on each kind.
      const picks: Record<string, string> = {};
      const enterOn = async (query: string, kind: string, needle: string, want: (p: string) => boolean, label: string) => {
        await searchKey(page);
        await untilSearch(page, (x) => x.open && x.focused);
        await replaceQuery(page, query);
        s = await untilSearch(page, (x) => x.q === query && x.texts.some((t, i) => x.kinds[i] === kind && t.includes(needle)));
        const at = s.kinds.findIndex((k, i) => k === kind && s.texts[i]!.includes(needle));
        if (at < 0) {
          fail(`"${query}" shows no ${label} row with ${JSON.stringify(needle)} (kinds ${JSON.stringify([...new Set(s.kinds)])})`);
          await pressKey(page, "Escape");
          return;
        }
        for (let i = 0; i < at; i++) await pressKey(page, "ArrowDown");
        await untilSearch(page, (x) => x.active === at);
        await pressKey(page, "Enter");
        const end = Date.now() + 3000;
        let path = (await readSearch(page)).path;
        while (!want(path) && Date.now() < end) {
          await sleep(60);
          path = (await readSearch(page)).path;
        }
        picks[label] = path;
        if (!want(path)) fail(`Enter on the ${label} row went to ${path}`);
        await page.settle();
      };
      await enterOn("plan the", "chats", "Plan the search index", (p) => p === `/c/${IDS.chats.search}`, "chat");
      await goBack(page);
      s = await untilSearch(page, (x) => x.open && x.q === "plan the");
      if (s.path !== `${pane}?q=plan%20the` || s.value !== "plan the") fail(`Back after a pick shows ${s.path} with ${JSON.stringify(s.value)}; expected the results with q`);
      await page.reload();
      s = await untilSearch(page, (x) => x.open && x.q === "plan the");
      if (s.value !== "plan the" || s.q !== "plan the") fail(`a reload of the results shows ${JSON.stringify(s.value)}, not "plan the"`);
      await pressKey(page, "Escape");
      await untilSearch(page, (x) => !x.open);
      await enterOn("upload.ts", "files", "upload.ts", (p) => p.startsWith(`${chat}/files/`), "file");
      await page.navigate(base + chat);
      await waitShown(page, ["chat"]);
      await enterOn("flaky-run", "uploads", "flaky-run", (p) => p === `${chat}/uploads`, "upload");
      await page.navigate(base + chat);
      await waitShown(page, ["chat"]);
      await enterOn("compact", "commands", "/compact", (p) => p === `${chat}/slash/compact`, "command");
      s = await untilSearch(page, (x) => x.chip === "/compact");
      if (s.chip !== "/compact") fail(`a command's pick leaves the composer's chip ${JSON.stringify(s.chip)}, not /compact`);
      details.picks = picks;
      // A reload keeps q and scope; a bad scope drops that key alone; an over-cap q fills nothing.
      await page.navigate(base + `${pane}?q=upload&scope=files`);
      await page.reload();
      s = await untilSearch(page, (x) => x.open && x.q === "upload");
      if (s.value !== "upload" || s.scope.join() !== "files") fail(`a reload of ?q=upload&scope=files shows ${JSON.stringify(s.value)} with scope ${JSON.stringify(s.scope)}`);
      if (s.kinds.some((k) => k !== "files" && k !== "uploads")) fail(`scope=files shows rows of ${JSON.stringify([...new Set(s.kinds)])}`);
      // The scope control: a click on the segment that is on shows every kind again; another kind's segment keeps it.
      const seg = async (value: string) => {
        const at = await page.locate(`[data-testid="search"] [role="radio"][data-value="${value}"]`);
        if (!at) return fail(`the scope control has no ${value} segment`, "shows");
        await page.press(at.x, at.y);
      };
      await seg("files");
      s = await untilSearch(page, (x) => !x.path.includes("scope="));
      if (s.path !== `${pane}?q=upload` || s.scope.length) fail(`a click on the Files segment that is on left ${s.path} with ${JSON.stringify(s.scope)} on`);
      await seg("chats");
      s = await untilSearch(page, (x) => x.path.includes("scope=chats"));
      if (s.path !== `${pane}?q=upload&scope=chats` || s.kinds.some((k) => k !== "chats")) fail(`the Chats segment left ${s.path} with rows of ${JSON.stringify([...new Set(s.kinds)])}`);
      await page.navigate(base + `${pane}?q=upload&scope=bogus`);
      s = await untilSearch(page, (x) => x.open && x.q === "upload");
      if (s.value !== "upload" || s.notices.join() !== PART_UNREAD_LINE) fail(`?scope=bogus shows ${JSON.stringify(s.value)} and the lines ${JSON.stringify(s.notices)}`);
      await page.navigate(base + `${pane}?q=${"a".repeat(5001)}`);
      s = await untilSearch(page, (x) => x.open);
      if (s.value !== "" || s.notices.join() !== TOO_LONG_LINE) fail(`an over-cap q shows ${JSON.stringify(s.value?.slice(0, 20))} and the lines ${JSON.stringify(s.notices)}`);
      shot = shotName(scene, "search-pane", vp, "light");
      await page.screenshot(shot).catch(() => {});
      stateFindings(await page.probe(), vp, failures);
      issueFindings(page.takeIssues(), failures);
      quietFindings(wire, since, await recorder(page), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = "Ctrl+K opens the focused pane; it narrows, the highlight resets per query, Esc closes with the focus back in the composer; each kind's Enter navigates; Back, reload, scope and the 5.4 lines hold; nothing sent";
  return finish({ kind: "flow", name: "search-pane", route: "chatSearch", scene, size: sizeTag(vp), theme: "light", path: pane, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * Search's key from the places the user is (6.11, C5), on a laptop: from the chat list it opens /search with its field
 * focused and Enter there opens the chat; from a chat it opens the chat's pane, and Esc there (nothing had the focus
 * before) puts the focus in the composer field, not on the page; with the pane open and its field blurred it focuses
 * the field and selects its text; while a dialog is open it does nothing; inside the Terminal pane it is the shell's
 * key (the shell gets it, and no pane opens). Nothing mutating goes out.
 */
async function paletteFlow(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const chat = `/c/${EX.chat}`;
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  try {
    await withPage(vp, "dark", async (page, wire) => {
      await page.navigate(base + "/chats");
      await waitShown(page, ["chat-list"]);
      page.takeIssues();
      const since = wire.mark();
      await searchKey(page);
      let s = await untilSearch(page, (x) => x.open && x.focused);
      details.fromList = { path: s.path, focused: s.focused, place: s.place };
      if (s.path !== "/search" || !s.focused) fail(`Ctrl+K on the chat list opened ${s.path}${s.focused ? "" : " with the field not focused"}; expected /search`);
      await typeText(page, "plan");
      s = await untilSearch(page, (x) => x.q === "plan" && x.rows > 0);
      if (s.kinds.some((k) => k !== "chats")) fail(`/search shows rows of ${JSON.stringify([...new Set(s.kinds)])}; it finds chats only`);
      await pressKey(page, "Enter");
      s = await untilSearch(page, (x) => !x.open);
      if (s.path !== `/c/${IDS.chats.search}`) fail(`Enter on /search went to ${s.path}`);
      // From a chat with the focus on nothing: the chat's own pane.
      await page.navigate(base + chat);
      await waitShown(page, ["chat"]);
      await page.evaluate(`(() => { const a = document.activeElement; if (a && a !== document.body) a.blur(); })()`);
      await searchKey(page);
      s = await untilSearch(page, (x) => x.open && x.focused);
      if (s.path !== `${chat}/search` || !s.focused) fail(`Ctrl+K in a chat opened ${s.path}${s.focused ? "" : " with the field not focused"}; expected ${chat}/search`);
      // Esc from there: nothing had the focus before, so on a laptop it goes to the composer field, not to the page.
      await pressKey(page, "Escape");
      s = await untilSearch(page, (x) => !x.open);
      const escFocus = await page.evaluate<string>(FOCUS_NAME);
      details.escFocus = { path: s.path, focus: escFocus };
      if (s.open || s.path !== chat) fail(`Esc in the chat's pane left ${s.path}`);
      // On touch (the large tablet with a hardware keyboard) Esc refocuses no field: the on-screen keyboard would rise.
      if (escFocus !== "composer" && !vp.touch) fail(`after Esc the focus is on ${escFocus}, not in the composer field`);
      if (vp.touch && escFocus === "composer") fail("on touch Esc put the focus in the composer field (the on-screen keyboard would rise)");
      // The pane open with its field blurred: the key focuses it and selects its text.
      await page.navigate(base + `${chat}/search?q=fix`);
      s = await untilSearch(page, (x) => x.open && x.q === "fix");
      await page.evaluate(`(() => { const f = document.querySelector('[data-testid="search-input"]'); if (f) f.blur(); })()`);
      await searchKey(page);
      s = await untilSearch(page, (x) => x.focused);
      details.refocus = { focused: s.focused, selected: s.selected, path: s.path };
      if (!s.focused || !s.selected) fail(`with the pane open, Ctrl+K ${s.focused ? "focused the field but did not select its text" : "did not focus the field"}`);
      if (s.path !== `${chat}/search?q=fix`) fail(`with the pane open, Ctrl+K changed the URL to ${s.path}`);
      // A dialog keeps its keys.
      await page.navigate(base + `${chat}/delete`);
      await waitShown(page, ["dialog-delete"]);
      await searchKey(page);
      await sleep(500);
      s = await readSearch(page);
      if (s.open || s.path !== `${chat}/delete`) fail(`Ctrl+K over the delete dialog opened ${s.path}`);
      // Inside the Terminal pane the key is the shell's.
      await page.navigate(base + `${chat}/shell`);
      await waitShown(page, ["terminal-pane", "terminal"]);
      const at = await page.locate(".term-host");
      if (!at) fail("the Terminal pane shows no terminal", "shows");
      else {
        await page.press(at.x, at.y);
        await sleep(1200);
        const before = wire.shellFrames;
        await searchKey(page);
        await sleep(800);
        s = await readSearch(page);
        details.terminal = { before, after: wire.shellFrames, path: s.path };
        if (s.open || s.path !== `${chat}/shell`) fail(`Ctrl+K inside the Terminal pane opened ${s.path}`);
        if (wire.shellFrames <= before) fail("Ctrl+K inside the Terminal pane did not reach the shell");
      }
      issueFindings(page.takeIssues(), failures);
      quietFindings(wire, since, await recorder(page), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = "Ctrl+K: /search from the list, Esc back to the composer, the field again with the pane open, nothing over a dialog, the shell's inside the terminal; nothing sent";
  return finish({ kind: "flow", name: "palette", route: "search", scene, size: sizeTag(vp), theme: "dark", path: "/chats", failures, warnings, note, ms: Date.now() - t0, details });
}

/**
 * The search pane on touch (7.2, 7.3, D3, L12). The tablet (834 x 1194): the pane bar's Search opens the docked pane,
 * lit, with its close button and no title, and gives no first focus; a tap on the field, typing, 44 px rows, a tap on a
 * chat row opens it and Back returns to the results; the 300-character path shows with no sideways overflow; the lit
 * button closes it. The phone (390 x 844): the /chats bar's Search opens /search (Back and "Search" in the bar), a row
 * tap opens the chat; in a chat the session menu's Search opens the chat's pane as its own screen over the chat (Back
 * "Chat" and "Search"), the CJK, emoji and long names show with no overflow, and Back returns to the chat. On both, with
 * the stand-in keyboard (STAND_IN_KEYBOARD: 400 px on the tablet, 336 px on the phone) up while the field has the
 * focus, the list ends at the keyboard's top and its last row, scrolled to, ends above it (7.8; the tablet's pane, the
 * phone's pane and the phone's /search), the field stays above it, and with it down the list ends where it did. Nothing
 * mutating goes out.
 */
async function searchTouchFlow(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const chat = `/c/${EX.chat}`;
  const pane = `${chat}/search`;
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  let shot: string | undefined;
  try {
    await withPage(vp, "light", async (page, wire) => {
      const tap = async (sel: string, what: string) => {
        const at = await page.locate(sel);
        if (!at) {
          fail(`no ${what} to tap`, "shows");
          return false;
        }
        await page.press(at.x, at.y);
        await sleep(350);
        await page.settle();
        return true;
      };
      const tapRow = async (needle: string, kind?: string) => {
        const at = await searchRowAt(page, needle, kind);
        if (!at) {
          fail(`no result row with ${JSON.stringify(needle)}`);
          return false;
        }
        await page.press(at.x, at.y);
        await sleep(350);
        await page.settle();
        return true;
      };
      const checkRows = (st: SearchState, when: string) => {
        const short = st.heights.filter((h) => h < 44);
        if (short.length) fail(`${when}: rows under 44 px (${short.join(", ")})`);
      };
      const small = async (when: string) => {
        const list = await page.evaluate<string[]>(SMALL_TARGETS);
        if (list.length) warnings.push({ code: "small", text: `${when}: under 44 px: ${clipList(list)}` });
      };
      const overflow = async (query: string, needle: string) => {
        await replaceQuery(page, query);
        const st = await untilSearch(page, (x) => x.q === query && x.texts.some((t) => t.includes(needle)));
        if (!st.texts.some((t) => t.includes(needle))) fail(`"${query}" shows no row with ${JSON.stringify(needle)}`);
        stateFindings(await page.probe(), vp, failures, `with "${query}": `);
      };
      // The on-screen keyboard (7.8, with the stand-in visualViewport): while it is up and the user types, the end of a
      // long list scrolls up above it, and the field stays above it; with it down the list has the whole height again.
      const kbPx = vp.name === "phone" ? 336 : 400;
      const keyboardEnd = async (query: string, when: string) => {
        await replaceQuery(page, query);
        await untilSearch(page, (x) => x.q === query && x.rows > 0);
        const down = await page.evaluate<ListAtEnd>(LIST_AT_END);
        await page.evaluate(`window.__standInKeyboard(${kbPx})`);
        await sleep(400);
        const up = await page.evaluate<ListAtEnd>(LIST_AT_END);
        await page.evaluate("window.__standInKeyboard(0)");
        await sleep(400);
        const after = await page.evaluate<ListAtEnd>(LIST_AT_END);
        details[`keyboard ${when}`] = { down, up, after };
        if (!up.list || !up.last) fail(`${when}: with the keyboard up the list shows no row`, "shows");
        else if (up.list[1] > up.visual + 1) fail(`${when}: with the keyboard up the list ends at ${up.list[1]} px, under the keyboard at ${up.visual} px`, "keyboard");
        else if (up.last[1] > up.visual + 1) fail(`${when}: with the keyboard up and the list scrolled to its end, its last row ends at ${up.last[1]} px, under the keyboard at ${up.visual} px`, "keyboard");
        if (!up.field || up.field[0] < 0 || up.field[1] > up.visual + 1) fail(`${when}: with the keyboard up the field is at ${JSON.stringify(up.field)}, not above the keyboard at ${up.visual} px`, "keyboard");
        if (after.list && down.list && Math.abs(after.list[1] - down.list[1]) > 1) fail(`${when}: with the keyboard down again the list ends at ${after.list[1]} px, not ${down.list[1]} px as before`, "keyboard");
      };
      await page.send("Page.addScriptToEvaluateOnNewDocument", { source: STAND_IN_KEYBOARD });
      let since = 0;
      // v0.6 touch: the large tablet (the laptop's layout with touch) opens the pane over the chat from the pane bar.
      const large = vp.name === "laptop";
      if (vp.name === "medium" || large) {
        await page.navigate(base + chat);
        await waitShown(page, ["chat"]);
        page.takeIssues();
        since = wire.mark();
        await tap('.pane-bar-btn[title="Search"]', "pane bar Search button");
        let s = await untilSearch(page, (x) => x.open);
        details.opened = s;
        const place = large ? "over" : "pane";
        if (s.path !== pane || s.place !== place) fail(`the bar's Search opened ${s.path} in the "${s.place}" place; expected the ${large ? "pane over the chat" : "docked pane"} at ${pane}`);
        if (s.lit.join() !== "Search") fail(`with the pane open the lit bar buttons are ${JSON.stringify(s.lit)}`);
        if (s.heading) fail("the docked pane has a title beside the lit Search button");
        if (s.focused) fail("the pane gave its field the first focus on touch");
        if (!(await page.locate('[data-testid="search-close"]'))) fail("the docked pane has no close button", "shows");
        await tap('[data-testid="search-input"]', "search field");
        await typeText(page, "the");
        s = await untilSearch(page, (x) => x.q === "the" && x.rows > 1);
        checkRows(s, "the tablet's rows");
        await small("the tablet's pane");
        await tapRow("Pick the test layers", "chats");
        s = await readSearch(page);
        if (s.path !== `/c/${IDS.chats.layers}`) fail(`a tap on a chat row went to ${s.path}`);
        await goBack(page);
        s = await untilSearch(page, (x) => x.open && x.q === "the");
        if (s.value !== "the") fail(`Back after the tap shows ${s.path} with ${JSON.stringify(s.value)}`);
        await overflow("upload-retry", "upload-retry-schedule.ts");
        shot = shotName(scene, "search-pane-touch", vp, "light");
        await page.screenshot(shot).catch(() => {});
        await keyboardEnd("e", "the tablet's pane");
        await tap('.pane-bar-btn.on[title="Close Search"]', "lit Search button");
        s = await untilSearch(page, (x) => !x.open);
        if (s.open || s.path !== chat) fail(`the lit Search button left ${s.path}`);
      } else {
        await page.navigate(base + "/chats");
        await waitShown(page, ["chat-list"]);
        page.takeIssues();
        since = wire.mark();
        await tap('[data-testid="topbar"] a[aria-label="Search"]', "Search button in the /chats bar");
        let s = await untilSearch(page, (x) => x.open);
        if (s.path !== "/search") fail(`the /chats bar's Search opened ${s.path}`);
        if (s.bar !== "Back Search") fail(`the /search bar reads ${JSON.stringify(s.bar)}, not Back and Search`);
        if (s.focused) fail("/search gave its field the first focus on touch");
        await tap('[data-testid="search-input"]', "search field");
        await typeText(page, "plan");
        s = await untilSearch(page, (x) => x.q === "plan" && x.rows > 0);
        checkRows(s, "/search's rows");
        await tapRow("Plan the search index");
        s = await readSearch(page);
        if (s.path !== `/c/${IDS.chats.search}`) fail(`a row tap on /search went to ${s.path}`);
        await goBack(page);
        s = await untilSearch(page, (x) => x.open && x.q === "plan");
        if (s.path !== "/search?q=plan") fail(`Back after the tap shows ${s.path}`);
        await keyboardEnd("e", "the phone's /search");
        // In a chat: the session menu's Search, as its Details.
        await page.navigate(base + chat);
        await waitShown(page, ["chat"]);
        await tap('[data-testid="topbar"] [aria-label="Session menu"]', "session menu button");
        const item = await page.evaluate<boolean>(`(() => { const it = [...document.querySelectorAll('[data-testid="session-menu"] a, [data-testid="session-menu"] button')].find((e) => e.getClientRects().length && e.textContent.trim() === "Search"); if (it) it.setAttribute("data-search-item", ""); return !!it; })()`);
        if (!item) fail("the phone's session menu has no Search item", "shows");
        else await tap("[data-search-item]", "session menu Search item");
        s = await untilSearch(page, (x) => x.open);
        details.chatPane = { path: s.path, place: s.place, bar: s.bar, chatShown: s.chatShown, focused: s.focused };
        if (s.path !== pane || s.place !== "page") fail(`the session menu's Search opened ${s.path} in the "${s.place}" place; expected the chat's pane as its own screen`);
        if (!s.bar.startsWith("Chat") || !s.bar.endsWith("Search")) fail(`the bar over the pane reads ${JSON.stringify(s.bar)}, not Back "Chat" and "Search"`);
        if (s.chatShown) fail("the chat shows under the phone's search screen");
        if (s.focused) fail("the phone's pane gave its field the first focus");
        await tap('[data-testid="search-input"]', "search field");
        await overflow("会議", "会議メモ 2026.md");
        await overflow("launch", "🚀 launch plan.md");
        await overflow("upload-retry", "upload-retry-schedule.ts");
        s = await readSearch(page);
        checkRows(s, "the phone's rows");
        await small("the phone's pane");
        shot = shotName(scene, "search-pane-touch", vp, "light");
        await page.screenshot(shot).catch(() => {});
        await keyboardEnd("e", "the phone's pane");
        await tap('[data-testid="topbar"] .scr-bar-back', "Back button");
        s = await untilSearch(page, (x) => !x.open);
        if (s.open || s.path !== chat) fail(`Back over the phone's pane left ${s.path}`);
      }
      issueFindings(page.takeIssues(), failures);
      quietFindings(wire, since, await recorder(page), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = vp.name !== "phone" ? "the bar's Search opens the lit pane (docked, or over the chat on the large tablet) with no first focus; 44 px rows; a tap opens a chat, Back returns; no overflow; the list ends above the keyboard; nothing sent" : "/search from the /chats bar and the chat's pane from the session menu, each its own screen; 44 px rows; no overflow; the list ends above the keyboard; nothing sent";
  return finish({ kind: "flow", name: "search-pane-touch", route: "chatSearch", scene, size: sizeTag(vp), theme: "light", path: vp.name !== "phone" ? pane : "/chats", failures, warnings, note, shot, ms: Date.now() - t0, details });
}

// ---------------------------------------------------------------------------------------------------------------
// v0.3 search: the @ picker (DESIGN.md 9.3, 6.4, 7.2, 7.5; BUILD-CHECKLIST C6, C7, D1, D2)

/** The @ picker and the message box around it, as the page shows them. */
const MENTION_STATE = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && getComputedStyle(el).display !== "none" && !el.closest('[hidden="until-found"]');
  const box = (el) => { if (!shown(el)) return null; const r = el.getBoundingClientRect(); return [Math.round(r.top), Math.round(r.bottom), Math.round(r.height)]; };
  const menu = document.querySelector('[data-testid="mention-menu"]');
  const field = document.querySelector('[data-testid="composer"] [data-testid="composer-input"]');
  const rows = menu ? [...menu.querySelectorAll('[role="option"]')] : [];
  const at = document.activeElement;
  const empty = menu ? menu.querySelector('[data-testid="mention-empty"]') : null;
  const composer = document.querySelector('[data-testid="composer"]');
  return {
    menu: !!menu, menuShown: shown(menu), q: menu ? menu.getAttribute("data-q") : null, count: menu ? menu.getAttribute("data-count") : null,
    rows: rows.map((r) => r.getAttribute("data-path")), active: rows.findIndex((r) => r.getAttribute("aria-selected") === "true"),
    empty: empty ? empty.textContent : null,
    chips: [...document.querySelectorAll('[data-testid="mention-chip"]')].map((c) => c.getAttribute("data-path")),
    value: field ? field.value : null, caret: field ? field.selectionStart : null,
    focus: at === field ? "field" : at ? at.tagName.toLowerCase() + (at.getAttribute("data-testid") ? "#" + at.getAttribute("data-testid") : "") : null,
    mode: composer ? composer.getAttribute("data-mode") : null,
    activedesc: field ? field.getAttribute("aria-activedescendant") : null,
    menuBox: box(menu), rowBoxes: rows.slice(0, 3).map(box), fieldBox: box(field), sendBox: box(document.querySelector('[data-testid="composer-send"], [data-testid="confirm-send"]')),
    atBox: box(document.querySelector('[data-testid="composer-at"]')),
    scrollTop: menu ? menu.scrollTop : null, scrollable: menu ? menu.scrollHeight > menu.clientHeight + 1 : null,
    visual: Math.round(visualViewport.height),
    tiles: [...document.querySelectorAll('[data-testid="download-mention"]')].map((t) => t.getAttribute("data-path")),
    path: location.pathname + location.search,
  };
})())`;

/** A box on screen in CSS px: its top, its bottom and its height. */
type Box = [top: number, bottom: number, height: number];

interface MentionState {
  menu: boolean;
  menuShown: boolean;
  q: string | null;
  count: string | null;
  rows: string[];
  active: number;
  empty: string | null;
  chips: string[];
  value: string | null;
  caret: number | null;
  focus: string | null;
  mode: string | null;
  activedesc: string | null;
  menuBox: Box | null;
  rowBoxes: (Box | null)[];
  fieldBox: Box | null;
  sendBox: Box | null;
  atBox: Box | null;
  scrollTop: number | null;
  scrollable: boolean | null;
  visual: number;
  tiles: string[];
  path: string;
}

const readMention = async (page: Page) => JSON.parse(await page.evaluate<string>(MENTION_STATE)) as MentionState;

/** Poll the picker until `ok` holds (or `ms` passes); the last state either way. */
async function untilMention(page: Page, ok: (s: MentionState) => boolean, ms = 4000): Promise<MentionState> {
  const end = Date.now() + ms;
  let s = await readMention(page);
  while (!ok(s) && Date.now() < end) {
    await sleep(80);
    s = await readMention(page);
  }
  return s;
}

/** Text into the focused field one character at a time, each an input event with no key event (RG-U2: an input
 *  method's or an Android keyboard's `@` comes so), then a pause for the deferred list. */
async function insertSlow(page: Page, text: string) {
  for (const ch of text) {
    await page.send("Input.insertText", { text: ch });
    await sleep(40);
  }
  await sleep(120);
}

/** A key down and up with its key code (229 is an input method's), then a pause. */
async function keyCode(page: Page, key: string, code: number, extra: Record<string, unknown> = {}) {
  await page.send("Input.dispatchKeyEvent", { type: "keyDown", key, code: key, windowsVirtualKeyCode: code, nativeVirtualKeyCode: code, ...extra });
  await page.send("Input.dispatchKeyEvent", { type: "keyUp", key, code: key, windowsVirtualKeyCode: code, nativeVirtualKeyCode: code });
  await sleep(150);
}

/** Select the field's text and delete it, as the user's own edit (a draft frame follows). */
async function clearBox(page: Page) {
  await page.evaluate(`(() => { const f = ${FIELD}; if (!f) return; f.focus(); f.select(); document.execCommand("delete"); })()`);
  await sleep(150);
}

/**
 * Empty the example chat's message box (the server keeps a draft across pages, D49): its mention chips removed, its
 * text cleared, Backspace in the empty field out of Bash or / mode, and the focus off it. The state after; the caller
 * checks it.
 */
async function emptyBox(page: Page): Promise<MentionState> {
  await page.evaluate(`document.querySelectorAll('[data-testid="mention-remove"]').forEach((b) => b.click())`);
  await clearBox(page);
  for (let i = 0; i < 3 && (await readMention(page)).mode !== "chat"; i++) await keyCode(page, "Backspace", 8);
  await page.evaluate(`document.activeElement && document.activeElement.blur()`);
  await sleep(400);
  return readMention(page);
}

const PICKER_FLOW_NOTE: Record<string, string> = {
  "at-picker": "a typed @ opens the picker; it narrows, the highlight resets per filter, Enter adds one chip and sends nothing; Send sends the mention and the tile shows",
  "at-picker-ime": "while an input method composes, Enter, Down and Esc are its own; after it commits, Enter picks",
  "at-picker-no-match": 'one line, "No file matches @<filter>."; Enter with no row adds no chip and sends nothing',
  "at-picker-not-opened": "no picker for an @ inside a word, in Bash mode, or in a /send link's text",
};

/**
 * The @ picker by keyboard on a laptop (1100 x 800, a fine pointer; R-gate section 3's flows), on the example chat
 * with its message box emptied first and left empty after:
 * - at-picker: an @ inserted as text (no key event) at the start of the field opens the picker over the folder's files
 *   and the focus stays in the field; "upl" narrows; Down twice, then one more letter, and the first row is active
 *   again (aria-activedescendant follows it); Enter adds that row's one chip, takes "@uplo" out and closes the picker;
 *   Esc closes the picker and keeps the text; nothing acting goes out; then Send sends one `send` frame with the
 *   mention and an ok ack, the fake claude gets the path's reference (messageRef) once, and the message shows the file's tile.
 * - at-picker-ime: while an input method composes, Enter neither picks nor sends, Down does not move and Esc does
 *   not close; Enter with key code 229 does not pick; after the commit, Enter picks.
 * - at-picker-no-match: "@zzzz" shows the one line "No file matches @zzzz." and no row; Enter adds no chip, keeps the
 *   text and sends nothing.
 * - at-picker-not-opened: no picker for "me@x", for an @ in Bash mode, or for a /send link's text "@upl".
 */
async function atPickerFlow(id: keyof typeof PICKER_FLOW_NOTE, t: Target, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const chat = `/c/${EX.chat}`;
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  let shot: string | undefined;
  try {
    await withPage(vp, "light", async (page, wire) => {
      await page.navigate(t.base + chat);
      await waitShown(page, ["chat", "composer"]);
      await sleep(400);
      const start = await emptyBox(page);
      if (start.mode !== "chat" || start.value !== "" || start.chips.length) throw new Error(`could not empty the message box: ${JSON.stringify({ mode: start.mode, value: start.value, chips: start.chips })}`);
      page.takeIssues();
      const m = wire.mark();
      const sentActing = (from: number, when: string) => {
        const a = acting(wire.framesSince(from));
        if (a.length || wire.httpSince(from).length) fail(`${when} sent ${clipList([...a.map(frameText), ...wire.httpSince(from).map(httpText)])}`, "click");
      };
      if (id === "at-picker") {
        const at = await page.locate('[data-testid="composer-input"]');
        if (!at) throw new Error("no composer field");
        await page.press(at.x, at.y);
        await sleep(150);
        await insertSlow(page, "@");
        let s = await untilMention(page, (x) => x.menuShown && x.rows.length > 0);
        details.open = { q: s.q, count: s.count, rows: s.rows.length, focus: s.focus };
        if (!s.menuShown || s.q !== "") fail(`a typed @ (inserted text, no key event) did not open the picker over the folder's files: ${JSON.stringify(details.open)}`);
        if (s.focus !== "field") fail(`the focus left the field: ${s.focus}`);
        await insertSlow(page, "upl");
        s = await untilMention(page, (x) => x.q === "upl");
        details.narrowed = { q: s.q, count: s.count, rows: s.rows };
        shot = shotName(scene, id, vp, "light", "open");
        await page.screenshot(shot).catch(() => {});
        if (s.q !== "upl" || !s.rows.length || s.rows.some((r) => !/u.*p.*l/i.test(r))) fail(`"upl" did not narrow the rows: ${JSON.stringify(details.narrowed)}`);
        await keyCode(page, "ArrowDown", 40);
        await keyCode(page, "ArrowDown", 40);
        s = await readMention(page);
        details.afterDown = s.active;
        if (s.rows.length >= 3 && s.active !== 2) fail(`two Down presses left row ${s.active + 1} active, not row 3`);
        if (s.activedesc !== `cmp-mention-${EX.chat}-${s.active}`) fail(`the field's aria-activedescendant is ${s.activedesc}`);
        await insertSlow(page, "o");
        s = await untilMention(page, (x) => x.q === "uplo");
        details.afterLetter = s.active;
        if (s.active !== 0) fail(`after one more letter row ${s.active + 1} is active, not row 1`);
        const picked = s.rows[0];
        await keyCode(page, "Enter", 13, { text: "\r" });
        s = await untilMention(page, (x) => x.chips.length === 1);
        details.afterEnter = { chips: s.chips, value: s.value, caret: s.caret, menu: s.menu };
        if (s.chips.length !== 1 || s.chips[0] !== picked) fail(`Enter did not add the one chip of ${picked}: ${JSON.stringify(s.chips)}`);
        if (s.value !== "" || s.caret !== 0) fail(`the field holds ${JSON.stringify(s.value)} (caret ${s.caret}) after the pick, not the text without "@uplo"`);
        if (s.menu) fail("the picker stayed open after the pick");
        await insertSlow(page, "see @r");
        s = await untilMention(page, (x) => x.menuShown);
        await keyCode(page, "Escape", 27);
        s = await readMention(page);
        details.afterEsc = { menu: s.menu, value: s.value };
        if (s.menu || s.value !== "see @r") fail(`Esc: picker ${s.menu ? "still open" : "closed"}, text ${JSON.stringify(s.value)}`);
        sentActing(m, "the picks");
        // Send: one send frame with the mention; the fake claude gets its reference (messageRef); the message shows the tile.
        await clearBox(page);
        await insertSlow(page, "Read it");
        // v0.6 touch: the large tablet sends the same mention on this seed after the laptop, so the count starts here.
        const abs0 = t.booted && picked ? claudeSaw(t.booted, messageRef(`${t.booted.seed.folders.kitespan}/${picked}`)) : 0;
        const m2 = wire.mark();
        await keyCode(page, "Enter", 13, { text: "\r" });
        await waitSent(wire, m2);
        const sends = wire.framesSince(m2).filter((f) => f.t === "send");
        details.send = sends.map((f) => ({ text: f.frame.text, mentions: f.frame.mentions }));
        if (sends.length !== 1 || JSON.stringify(sends[0]!.frame.mentions) !== JSON.stringify([picked])) fail(`Send sent ${JSON.stringify(details.send)}, not one send with the mention`);
        const ack = sends[0]?.rid ? await waitAck(wire, sends[0].rid) : null;
        if (!ack?.ok) fail(`the send's ack: ${JSON.stringify(ack)}`);
        if (t.booted && picked) {
          const abs = messageRef(`${t.booted.seed.folders.kitespan}/${picked}`);
          const end = Date.now() + 5000;
          let saw = claudeSaw(t.booted, abs) - abs0;
          while (saw < 1 && Date.now() < end) {
            await sleep(100);
            saw = claudeSaw(t.booted, abs) - abs0;
          }
          details.claudeSaw = saw;
          if (saw !== 1) fail(`the fake claude saw the message with @<the seed folder>/${picked} ${saw} times, not once`);
        } else warnings.push({ code: "flow", text: "no seed of this run's own (--base): the fake claude's trace was not read" });
        s = await untilMention(page, (x) => !!picked && x.tiles.includes(picked), 6000);
        details.tiles = s.tiles;
        if (!picked || !s.tiles.includes(picked)) fail(`the sent message shows no tile for ${picked}`);
        await page.screenshot(shotName(scene, id, vp, "light", "sent")).catch(() => {});
      } else if (id === "at-picker-ime") {
        await page.evaluate(`(() => { const f = ${FIELD}; if (f) f.focus(); })()`);
        await insertSlow(page, "@");
        await untilMention(page, (x) => x.menuShown && x.rows.length > 0);
        await page.send("Input.imeSetComposition", { text: "up", selectionStart: 2, selectionEnd: 2 });
        await sleep(200);
        let s = await untilMention(page, (x) => x.q === "up");
        const before = s.active;
        details.composing = { q: s.q, rows: s.rows.length, value: s.value };
        await keyCode(page, "Enter", 13);
        s = await readMention(page);
        if (s.chips.length !== 0 || !s.menu) fail(`Enter while composing: chips ${JSON.stringify(s.chips)}, picker ${s.menu ? "open" : "closed"}`);
        await keyCode(page, "ArrowDown", 40);
        s = await readMention(page);
        if (s.active !== before) fail(`Down while composing moved the highlight from row ${before + 1} to row ${s.active + 1}`);
        await keyCode(page, "Escape", 27);
        s = await readMention(page);
        if (!s.menu) fail("Esc while composing closed the picker");
        await page.send("Input.insertText", { text: "up" });
        await sleep(250);
        s = await untilMention(page, (x) => x.q === "up");
        details.committed = { q: s.q, value: s.value, rows: s.rows.length };
        await keyCode(page, "Enter", 229);
        s = await readMention(page);
        if (vp.touch) {
          // v0.6 touch (T-18, Q3): on touch only marked text holds Enter; key code 229 with no composition is dictation's
          // Enter, 250 ms after the commit, so it picks.
          s = await untilMention(page, (x) => x.chips.length === 1);
          details.picked = s.chips;
          if (s.chips.length !== 1) fail(`on touch Enter with key code 229 and no composition did not pick: ${JSON.stringify(s.chips)}`);
        } else {
          if (s.chips.length !== 0) fail(`Enter with key code 229 picked: ${JSON.stringify(s.chips)}`);
          await keyCode(page, "Enter", 13, { text: "\r" });
          s = await untilMention(page, (x) => x.chips.length === 1);
          details.picked = s.chips;
          if (s.chips.length !== 1) fail(`Enter after the composition ended did not pick: ${JSON.stringify(s.chips)}`);
        }
        sentActing(m, "the flow");
      } else if (id === "at-picker-no-match") {
        await page.evaluate(`(() => { const f = ${FIELD}; if (f) f.focus(); })()`);
        await insertSlow(page, "@zzzz");
        let s = await untilMention(page, (x) => x.q === "zzzz" && x.empty !== null);
        details.empty = s.empty;
        if (s.empty !== "No file matches @zzzz." || s.rows.length) fail(`no match shows ${JSON.stringify(s.empty)} and ${s.rows.length} rows`);
        shot = shotName(scene, id, vp, "light");
        await page.screenshot(shot).catch(() => {});
        await keyCode(page, "Enter", 13, { text: "\r" });
        s = await readMention(page);
        if (s.chips.length || s.value !== "@zzzz") fail(`Enter with no row: ${s.chips.length} chips, text ${JSON.stringify(s.value)}`);
        sentActing(m, "Enter with no row");
      } else {
        await page.evaluate(`(() => { const f = ${FIELD}; if (f) f.focus(); })()`);
        await insertSlow(page, "mail me@x");
        let s = await readMention(page);
        if (s.menu) fail("an @ inside a word opened the picker");
        await clearBox(page);
        await insertSlow(page, "!");
        await insertSlow(page, "echo @b");
        s = await readMention(page);
        details.bash = { mode: s.mode, menu: s.menu };
        if (s.mode !== "bash" || s.menu) fail(`Bash mode: mode ${s.mode}, picker ${s.menu ? "open" : "closed"}`);
        await emptyBox(page);
        await page.navigate(`${t.base}${chat}/send?text=${encodeURIComponent("@upl")}`);
        s = await untilMention(page, (x) => x.value === "@upl", 5000);
        details.link = { value: s.value, menu: s.menu };
        if (s.value !== "@upl" || s.menu) fail(`/send?text=@upl: text ${JSON.stringify(s.value)}, picker ${s.menu ? "open" : "closed"}`);
        sentActing(m, "the flow");
      }
      issueFindings(page.takeIssues(), failures);
      // Leave the message box empty for the checks after this one.
      if (id === "at-picker-not-opened") {
        await page.navigate(t.base + chat);
        await waitShown(page, ["chat", "composer"]);
      }
      const end = await emptyBox(page);
      if (end.value !== "" || end.chips.length || end.mode !== "chat") warnings.push({ code: "flow", text: `the message box could not be emptied at the end (${JSON.stringify({ value: end.value, chips: end.chips, mode: end.mode })})` });
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return finish({ kind: "flow", name: id, route: "mention", scene, size: sizeTag(vp), theme: "light", path: chat, failures, warnings, note: PICKER_FLOW_NOTE[id]!, shot, ms: Date.now() - t0, details });
}

/**
 * The @ picker on touch (834 x 1194 and 390 x 844, D1, D2, L3, L4), with the stand-in keyboard (STAND_IN_KEYBOARD): a
 * tap on the field and the keyboard up; the @ button (44 px, beside +) opens the picker with "@" in the field and the
 * focus kept; the picker, the field and Send end above the keyboard, its rows are 44 px or more; a touch drag over the
 * rows scrolls them, picks nothing and leaves the highlight; a row tap adds its chip and keeps the focus in the field;
 * a typed @ opens it again and it closes when the keyboard goes down; with the keyboard down the @ button focuses the
 * field and opens the picker within the same tap. No sideways overflow; nothing acting goes out.
 */
async function atPickerTouchFlow(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const chat = `/c/${EX.chat}`;
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  const kbPx = vp.name === "phone" ? 336 : 400;
  let shot: string | undefined;
  try {
    await withPage(vp, "light", async (page, wire) => {
      await page.send("Page.addScriptToEvaluateOnNewDocument", { source: STAND_IN_KEYBOARD });
      await page.navigate(base + chat);
      await waitShown(page, ["chat", "composer"]);
      await sleep(400);
      const start = await emptyBox(page);
      if (start.mode !== "chat" || start.value !== "" || start.chips.length) throw new Error(`could not empty the message box: ${JSON.stringify({ mode: start.mode, value: start.value, chips: start.chips })}`);
      page.takeIssues();
      const m = wire.mark();
      const keyboard = async (px: number) => {
        await page.evaluate(`window.__standInKeyboard(${px})`);
        await sleep(400);
      };
      const tap = async (sel: string) => {
        const at = await page.locate(sel);
        if (!at) return false;
        await page.press(at.x, at.y);
        await sleep(250);
        return true;
      };
      if (!(await tap('[data-testid="composer-input"]'))) fail("no composer field", "shows");
      await keyboard(kbPx);
      let s = await readMention(page);
      if (s.focus !== "field") fail(`a tap on the field put the focus on ${s.focus}`);
      // The @ button with the keyboard up opens the picker and keeps the focus.
      if (!(await tap('[data-testid="composer-at"]'))) fail("no @ button on touch", "shows");
      s = await untilMention(page, (x) => x.menuShown && x.rows.length > 0);
      details.open = { value: s.value, rows: s.rows.length, focus: s.focus, at: s.atBox, menu: s.menuBox, field: s.fieldBox, send: s.sendBox, visual: s.visual };
      if (!s.menuShown || s.value !== "@") fail(`the @ button: picker ${s.menuShown ? "open" : "closed"}, text ${JSON.stringify(s.value)}`);
      if (s.focus !== "field") fail(`the @ button took the focus: ${s.focus}`);
      const above = (what: string, bx: Box | null) => {
        if (!bx) fail(`${what} does not show`, "shows");
        else if (bx[1] > s.visual + 1) fail(`${what} ends at ${bx[1]} px, under the keyboard at ${s.visual} px`, "keyboard");
        else if (bx[0] < 0) fail(`${what} starts above the screen (${bx[0]} px)`, "keyboard");
      };
      above("the picker", s.menuBox);
      above("the field", s.fieldBox);
      above("Send", s.sendBox);
      const small = await page.evaluate<string[]>(SMALL_TARGETS);
      details.smallTargets = small;
      const rowHeights = s.rowBoxes.map((x) => x?.[2]);
      details.rowHeights = rowHeights;
      if (s.rowBoxes.some((x) => !x || x[2] < 44)) fail(`rows under 44 px: ${JSON.stringify(rowHeights)}`);
      if (s.atBox && s.atBox[2] < 44) fail(`the @ button is ${s.atBox[2]} px high`);
      const atSmall = small.filter((x) => /^composer-at /.test(x));
      if (atSmall.length) fail(`small targets: ${atSmall.join(", ")}`);
      else if (small.length) warnings.push({ code: "target", text: `under 44 px: ${clipList(small, 4)}` });
      shot = shotName(scene, "at-picker-touch", vp, "light", "open");
      await page.screenshot(shot).catch(() => {});
      // A touch drag over the rows scrolls them, picks nothing and leaves the active row as it was.
      const active0 = s.active;
      const row = await page.locate('[data-testid="mention-menu"] [role="option"]');
      if (row) {
        let y = row.y + 60;
        await page.send("Input.dispatchTouchEvent", { type: "touchStart", touchPoints: [{ x: row.x, y, radiusX: 4, radiusY: 4, force: 1, id: 1 }] });
        for (let i = 0; i < 12; i++) {
          y -= 15;
          await page.send("Input.dispatchTouchEvent", { type: "touchMove", touchPoints: [{ x: row.x, y, radiusX: 4, radiusY: 4, force: 1, id: 1 }] });
          await sleep(16);
        }
        await page.send("Input.dispatchTouchEvent", { type: "touchEnd", touchPoints: [] });
        await sleep(400);
      }
      s = await readMention(page);
      details.drag = { scrollTop: s.scrollTop, scrollable: s.scrollable, chips: s.chips, active: s.active };
      if (s.chips.length) fail(`a drag over the rows picked ${JSON.stringify(s.chips)}`);
      if (s.active !== active0) fail(`a drag moved the highlight from row ${active0 + 1} to row ${s.active + 1}`);
      if (s.scrollable && !s.scrollTop) fail("a drag over the rows did not scroll them");
      if (s.focus !== "field") fail(`after the drag the focus is on ${s.focus}`);
      // A tap on a row adds its chip and keeps the focus in the field.
      const target = s.rows[1] ?? s.rows[0];
      if (!target || !(await tap(`[data-testid="mention-menu"] [data-path="${target}"]`))) fail("no row to tap");
      s = await untilMention(page, (x) => x.chips.length === 1);
      details.tap = { target, chips: s.chips, focus: s.focus, value: s.value, menu: s.menu };
      if (s.chips.length !== 1 || s.chips[0] !== target) fail(`a row tap added ${JSON.stringify(s.chips)}, not ${target}`);
      if (s.focus !== "field") fail(`a row tap moved the focus to ${s.focus}`);
      if (s.value !== "" || s.menu) fail(`after the tap: text ${JSON.stringify(s.value)}, picker ${s.menu ? "open" : "closed"}`);
      await page.screenshot(shotName(scene, "at-picker-touch", vp, "light", "chip")).catch(() => {});
      stateFindings(await page.probe(), vp, failures, "with the chip: ");
      // A typed @ on touch, then the keyboard goes down: the picker closes with it, nothing over the composer.
      await insertSlow(page, "@");
      s = await untilMention(page, (x) => x.menuShown);
      if (!s.menuShown) fail("a typed @ on touch did not open the picker");
      await keyboard(0);
      await sleep(700);
      s = await readMention(page);
      details.down = { menu: s.menu, focus: s.focus };
      if (s.menu) fail("the keyboard went down and the picker stayed over the composer");
      // The @ button with the keyboard down focuses the field inside the same tap.
      if (!(await tap('[data-testid="composer-at"]'))) fail("no @ button after the keyboard went down", "shows");
      s = await untilMention(page, (x) => x.menuShown);
      details.downTap = { menu: s.menuShown, focus: s.focus, value: s.value };
      if (!s.menuShown || s.focus !== "field") fail(`the @ button with the keyboard down: picker ${s.menuShown ? "open" : "closed"}, focus ${s.focus}`);
      stateFindings(await page.probe(), vp, failures);
      const a = acting(wire.framesSince(m));
      if (a.length || wire.httpSince(m).length) fail(`the flow sent ${clipList([...a.map(frameText), ...wire.httpSince(m).map(httpText)])}`, "click");
      details.drafts = wire.framesSince(m).filter((f) => f.t === "draft").length;
      issueFindings(page.takeIssues(), failures);
      await keyCode(page, "Escape", 27);
      const end = await emptyBox(page);
      if (end.value !== "" || end.chips.length || end.mode !== "chat") warnings.push({ code: "flow", text: `the message box could not be emptied at the end (${JSON.stringify({ value: end.value, chips: end.chips, mode: end.mode })})` });
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = "the @ button keeps the focus; picker, field and Send above the keyboard; 44 px rows; a drag scrolls and picks nothing; a tap adds the chip; it closes with the keyboard; nothing acting sent";
  return finish({ kind: "flow", name: "at-picker-touch", route: "mention", scene, size: sizeTag(vp), theme: "light", path: chat, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

// ---------------------------------------------------------------------------------------------------------------
// The `/` menu at a mid-line `/` (D57, DESIGN.md 6.4): a `/` typed at a word start in the middle of a message.

/** The / menu and the message box around it, as the page shows them. */
const SLASH_STATE = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && getComputedStyle(el).display !== "none" && !el.closest('[hidden="until-found"]');
  const box = (el) => { if (!shown(el)) return null; const r = el.getBoundingClientRect(); return [Math.round(r.top), Math.round(r.bottom), Math.round(r.height)]; };
  const menu = document.querySelector('[data-testid="slash-menu"]');
  const field = document.querySelector('[data-testid="composer"] [data-testid="composer-input"]');
  const rows = menu ? [...menu.querySelectorAll('[role="option"]')] : [];
  const at = document.activeElement;
  const empty = menu ? menu.querySelector(".cmp-slash-empty") : null;
  const composer = document.querySelector('[data-testid="composer"]');
  const chip = composer ? composer.querySelector(".cmp-chip.is-slash") : null;
  return {
    menu: !!menu, menuShown: shown(menu), rows: rows.map((r) => r.getAttribute("data-command")), active: rows.findIndex((r) => r.getAttribute("aria-selected") === "true"),
    empty: empty ? empty.textContent : null, value: field ? field.value : null, caret: field ? field.selectionStart : null,
    focus: at === field ? "field" : at ? at.tagName.toLowerCase() + (at.getAttribute("data-testid") ? "#" + at.getAttribute("data-testid") : "") : null,
    mode: composer ? composer.getAttribute("data-mode") : null, chip: chip ? chip.textContent : null,
    activedesc: field ? field.getAttribute("aria-activedescendant") : null,
    menuBox: box(menu), rowBoxes: rows.slice(0, 3).map(box), fieldBox: box(field), slabBox: box(composer && composer.querySelector(".cmp-slab")),
    sendBox: box(document.querySelector('[data-testid="composer-send"], [data-testid="confirm-send"]')),
    visual: Math.round(visualViewport.height), path: location.pathname + location.search,
  };
})())`;

interface SlashState {
  menu: boolean;
  menuShown: boolean;
  rows: string[];
  active: number;
  empty: string | null;
  value: string | null;
  caret: number | null;
  focus: string | null;
  mode: string | null;
  chip: string | null;
  activedesc: string | null;
  menuBox: Box | null;
  rowBoxes: (Box | null)[];
  fieldBox: Box | null;
  slabBox: Box | null;
  sendBox: Box | null;
  visual: number;
  path: string;
}

const readSlash = async (page: Page) => JSON.parse(await page.evaluate<string>(SLASH_STATE)) as SlashState;

/** Poll the / menu until `ok` holds (or `ms` passes); the last state either way. */
async function untilSlash(page: Page, ok: (s: SlashState) => boolean, ms = 4000): Promise<SlashState> {
  const end = Date.now() + ms;
  let s = await readSlash(page);
  while (!ok(s) && Date.now() < end) {
    await sleep(80);
    s = await readSlash(page);
  }
  return s;
}

/** The menu rises from the slab with no room between them (row 39) and stays in view. */
function slashMenuPlace(s: SlashState, fail: (text: string, code?: string) => void) {
  if (!s.menuBox || !s.slabBox) return fail(`the menu or the message box does not show: ${JSON.stringify({ menu: s.menuBox, slab: s.slabBox })}`, "shows");
  const gap = s.slabBox[0] - s.menuBox[1];
  if (gap < 0 || gap > 8) fail(`the menu ends ${gap} px from the message box, not right above it`, "layout");
  if (s.menuBox[0] < 0) fail(`the menu starts above the screen (${s.menuBox[0]} px)`, "layout");
}

/**
 * The mid-line / menu by keyboard on a laptop (1100 x 800, a fine pointer), on the example chat with its message box
 * emptied first and left empty after: "test /" (inserted text, no key event) opens the / menu's rows with the focus in
 * the field; "co" narrows them; Down, then Enter puts "/<that row's name> " in place of "/co" with the caret after
 * it, in Chat mode with no chip, and the menu closes; nothing acting goes out. "and /zzz" matches no row, so no menu
 * shows (W19b: its keys are the field's); " /" opens it again, and Esc closes it and keeps the text. No menu for
 * src/app, http://, or in Bash mode. In a command's arguments after its chip ("/compact " then "keep /co") Tab picks
 * and the chip stays. Then a pick, " then read /etc/hosts" (a path at the end: no row, no menu) and Enter send the
 * text as typed: one send frame, and the fake claude gets it once.
 */
async function slashMidlineFlow(t: Target, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const chat = `/c/${EX.chat}`;
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  let shot: string | undefined;
  try {
    await withPage(vp, "light", async (page, wire) => {
      await page.navigate(t.base + chat);
      await waitShown(page, ["chat", "composer"]);
      await sleep(400);
      const start = await emptyBox(page);
      if (start.mode !== "chat" || start.value !== "" || start.chips.length) throw new Error(`could not empty the message box: ${JSON.stringify({ mode: start.mode, value: start.value, chips: start.chips })}`);
      page.takeIssues();
      const m = wire.mark();
      const field = await page.locate('[data-testid="composer-input"]');
      if (!field) throw new Error("no composer field");
      await page.press(field.x, field.y);
      await sleep(150);
      await insertSlow(page, "test /");
      let s = await untilSlash(page, (x) => x.menuShown && x.rows.length > 0, 6000);
      details.open = { rows: s.rows, focus: s.focus, mode: s.mode, path: s.path };
      if (!s.menuShown || !s.rows.length) fail(`a / typed after "test " did not open the menu with rows: ${JSON.stringify(details.open)}`);
      if (s.focus !== "field") fail(`the focus left the field: ${s.focus}`);
      if (s.mode !== "chat" || s.chip !== null) fail(`the menu changed the mode: ${s.mode}, chip ${JSON.stringify(s.chip)}`);
      if (s.path !== chat) fail(`the menu changed the URL to ${s.path}`, "route");
      slashMenuPlace(s, fail);
      await insertSlow(page, "co");
      s = await untilSlash(page, (x) => x.rows.length > 0 && x.rows.every((r) => r.includes("co")));
      details.narrowed = s.rows;
      if (!s.rows.length || s.rows.some((r) => !r.includes("co"))) fail(`"co" did not narrow the rows: ${JSON.stringify(s.rows)}`);
      shot = shotName(scene, "slash-midline", vp, "light", "open");
      await page.screenshot(shot).catch(() => {});
      await keyCode(page, "ArrowDown", 40);
      s = await readSlash(page);
      if (s.rows.length > 1 && s.active !== 1) fail(`Down left row ${s.active + 1} active, not row 2`);
      if (s.activedesc !== `cmp-slash-${EX.chat}-${s.active}`) fail(`the field's aria-activedescendant is ${s.activedesc}`);
      const name = s.rows[s.active] ?? s.rows[0] ?? "";
      await keyCode(page, "Enter", 13, { text: "\r" });
      s = await untilSlash(page, (x) => !x.menu);
      details.picked = { name, value: s.value, caret: s.caret, menu: s.menu, mode: s.mode, chip: s.chip };
      const want = `test /${name} `;
      if (s.value !== want || s.caret !== want.length) fail(`Enter left ${JSON.stringify(s.value)} (caret ${s.caret}), not ${JSON.stringify(want)} with the caret at its end`);
      if (s.menu) fail("the menu stayed open after the pick");
      if (s.mode !== "chat" || s.chip !== null) fail(`the pick changed the mode: ${s.mode}, chip ${JSON.stringify(s.chip)}`);
      // A filter with no row shows no menu (W19b): its keys are the field's then (Enter sends, at the end of the flow).
      await insertSlow(page, "and /zzz");
      s = await untilSlash(page, (x) => !x.menu && x.value === `${want}and /zzz`);
      details.noRow = { menu: s.menu, empty: s.empty, value: s.value };
      if (s.menu || s.value !== `${want}and /zzz`) fail(`"/zzz" (no row): menu ${s.menu ? `shown (${JSON.stringify(s.empty)})` : "none"}, text ${JSON.stringify(s.value)}`);
      // A new / at a word start opens it again; Esc closes it and keeps the text.
      await insertSlow(page, " /");
      s = await untilSlash(page, (x) => x.menuShown && x.rows.length > 0);
      if (!s.menuShown || !s.rows.length) fail(`a / after "/zzz " opened no rows: ${JSON.stringify(s.rows)}`);
      await keyCode(page, "Escape", 27);
      s = await readSlash(page);
      details.afterEsc = { menu: s.menu, value: s.value };
      if (s.menu || s.value !== `${want}and /zzz /`) fail(`Esc: menu ${s.menu ? "still open" : "closed"}, text ${JSON.stringify(s.value)}`);
      // Never inside a word, never in Bash mode.
      await clearBox(page);
      for (const text of ["see src/", "open http://"]) {
        await insertSlow(page, text);
        s = await readSlash(page);
        if (s.menu) fail(`the menu opened inside a word: ${JSON.stringify(s.value)}`);
        await clearBox(page);
      }
      await insertSlow(page, "!");
      await insertSlow(page, "ls /");
      s = await readSlash(page);
      details.bash = { mode: s.mode, menu: s.menu };
      if (s.mode !== "bash" || s.menu) fail(`Bash mode: mode ${s.mode}, menu ${s.menu ? "open" : "closed"}`);
      await emptyBox(page);
      await page.evaluate(`(() => { const f = ${FIELD}; if (f) f.focus(); })()`);
      // In a command's arguments after its chip: Tab picks, the chip stays.
      await insertSlow(page, `/${EX.command} `);
      s = await untilSlash(page, (x) => x.chip === `/${EX.command}`);
      if (s.chip !== `/${EX.command}` || s.value !== "") fail(`"/${EX.command} " gave chip ${JSON.stringify(s.chip)} and text ${JSON.stringify(s.value)}`);
      await insertSlow(page, "keep /co");
      s = await untilSlash(page, (x) => x.menuShown && x.rows.length > 0);
      const first = s.rows[0] ?? "";
      details.args = { rows: s.rows, chip: s.chip };
      if (!s.menuShown || !first) fail(`a / in the arguments after the chip opened no rows: ${JSON.stringify(details.args)}`);
      await keyCode(page, "Tab", 9);
      s = await untilSlash(page, (x) => !x.menu);
      details.argsPicked = { value: s.value, chip: s.chip, mode: s.mode };
      if (s.value !== `keep /${first} ` || s.chip !== `/${EX.command}` || s.mode !== "slash") fail(`Tab in the arguments: ${JSON.stringify(details.argsPicked)}`);
      noActing(wire, m, "the picks", fail);
      // Send sends the text as typed: a path at the end of the message ("/etc/hosts", no row) shows no menu, so Enter
      // sends: one send frame, and the fake claude gets it once.
      await emptyBox(page);
      await page.evaluate(`(() => { const f = ${FIELD}; if (f) f.focus(); })()`);
      await insertSlow(page, "test /cont");
      s = await untilSlash(page, (x) => x.rows[0] === "context");
      await keyCode(page, "Enter", 13, { text: "\r" });
      s = await untilSlash(page, (x) => x.value === "test /context ");
      if (s.value !== "test /context ") fail(`the pick of /context left ${JSON.stringify(s.value)}`);
      const sent = "test /context then read /etc/hosts";
      await insertSlow(page, "then read /etc/hosts");
      s = await untilSlash(page, (x) => !x.menu && x.value === sent);
      details.path = { menu: s.menu, value: s.value };
      if (s.menu || s.value !== sent) fail(`a path at the end of the message: menu ${s.menu ? "shown" : "none"}, text ${JSON.stringify(s.value)}`);
      const sent0 = t.booted ? claudeSaw(t.booted, sent) : 0;
      const m2 = wire.mark();
      await keyCode(page, "Enter", 13, { text: "\r" });
      await waitSent(wire, m2);
      const sends = wire.framesSince(m2).filter((f) => f.t === "send");
      details.send = sends.map((f) => f.frame.text);
      if (sends.length !== 1 || sends[0]!.frame.text !== sent) fail(`Enter sent ${JSON.stringify(details.send)}, not one send of ${JSON.stringify(sent)}`);
      const ack = sends[0]?.rid ? await waitAck(wire, sends[0].rid) : null;
      if (!ack?.ok) fail(`the send's ack: ${JSON.stringify(ack)}`);
      if (t.booted) {
        const end = Date.now() + 5000;
        let saw = claudeSaw(t.booted, sent) - sent0;
        while (saw < 1 && Date.now() < end) {
          await sleep(100);
          saw = claudeSaw(t.booted, sent) - sent0;
        }
        details.claudeSaw = saw;
        if (saw !== 1) fail(`the fake claude saw ${JSON.stringify(sent)} ${saw} times, not once`);
      } else warnings.push({ code: "flow", text: "no seed of this run's own (--base): the fake claude's trace was not read" });
      stateFindings(await page.probe(), vp, failures);
      issueFindings(page.takeIssues(), failures);
      const end = await emptyBox(page);
      if (end.value !== "" || end.mode !== "chat") warnings.push({ code: "flow", text: `the message box could not be emptied at the end (${JSON.stringify({ value: end.value, mode: end.mode })})` });
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = 'a mid-line / opens the / menu\'s rows; Enter picks "/<name> " as plain text and never sends; no row: no menu; Esc keeps the text; none inside a word or in Bash mode; Tab picks in a command\'s arguments; Enter after a path at the end sends the text as typed';
  return finish({ kind: "flow", name: "slash-midline", route: "slashMenu", scene, size: sizeTag(vp), theme: "light", path: chat, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * The mid-line / menu on touch (834 x 1194 and 390 x 844), with the stand-in keyboard: a tap on the field and the
 * keyboard up; "test /" opens the / menu's rows right above the message box, with the menu, the field and Send above
 * the keyboard and 44 px rows; a tap on a row (a terminal-only one on the phone) puts "/<name> " in the field as plain
 * text, the focus stays in the field and the URL stays; Enter picks at once ("and /co"); the menu goes with the
 * keyboard. No sideways overflow, no console error, nothing acting sent.
 */
async function slashMidlineTouchFlow(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const chat = `/c/${EX.chat}`;
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  const kbPx = vp.name === "phone" ? 336 : 400;
  // The phone taps the terminal-only row: its pick is text too, with no Terminal pane.
  const [typedName, tapName] = vp.name === "phone" ? ["doc", "doctor"] : ["rev", "review"];
  let shot: string | undefined;
  try {
    await withPage(vp, "light", async (page, wire) => {
      await page.send("Page.addScriptToEvaluateOnNewDocument", { source: STAND_IN_KEYBOARD });
      await page.navigate(base + chat);
      await waitShown(page, ["chat", "composer"]);
      await sleep(400);
      const start = await emptyBox(page);
      if (start.mode !== "chat" || start.value !== "" || start.chips.length) throw new Error(`could not empty the message box: ${JSON.stringify({ mode: start.mode, value: start.value, chips: start.chips })}`);
      page.takeIssues();
      const m = wire.mark();
      const tap = async (sel: string) => {
        const at = await page.locate(sel);
        if (!at) return false;
        await page.press(at.x, at.y);
        await sleep(250);
        return true;
      };
      if (!(await tap('[data-testid="composer-input"]'))) fail("no composer field", "shows");
      await page.evaluate(`window.__standInKeyboard(${kbPx})`);
      await sleep(400);
      await insertSlow(page, "test /");
      let s = await untilSlash(page, (x) => x.menuShown && x.rows.length > 0, 6000);
      details.open = { rows: s.rows, focus: s.focus, menu: s.menuBox, slab: s.slabBox, field: s.fieldBox, send: s.sendBox, visual: s.visual };
      if (!s.menuShown || !s.rows.length) fail(`a / typed after "test " did not open the menu with rows: ${JSON.stringify(details.open)}`);
      if (s.focus !== "field") fail(`the focus left the field: ${s.focus}`);
      slashMenuPlace(s, fail);
      const above = (what: string, bx: Box | null) => {
        if (!bx) fail(`${what} does not show`, "shows");
        else if (bx[1] > s.visual + 1) fail(`${what} ends at ${bx[1]} px, under the keyboard at ${s.visual} px`, "keyboard");
      };
      above("the menu", s.menuBox);
      above("the field", s.fieldBox);
      above("Send", s.sendBox);
      const rowHeights = s.rowBoxes.map((x) => x?.[2]);
      details.rowHeights = rowHeights;
      if (s.rowBoxes.some((x) => !x || x[2] < 44)) fail(`rows under 44 px: ${JSON.stringify(rowHeights)}`);
      shot = shotName(scene, "slash-midline-touch", vp, "light", "open");
      await page.screenshot(shot).catch(() => {});
      stateFindings(await page.probe(), vp, failures, "with the menu open: ");
      await insertSlow(page, typedName);
      s = await untilSlash(page, (x) => x.rows.includes(tapName));
      if (!s.rows.includes(tapName) || !(await tap(`[data-testid="slash-menu"] [data-command="${tapName}"]`))) fail(`no /${tapName} row to tap: ${JSON.stringify(s.rows)}`);
      s = await untilSlash(page, (x) => !x.menu);
      const want = `test /${tapName} `;
      details.tap = { value: s.value, caret: s.caret, focus: s.focus, mode: s.mode, chip: s.chip, path: s.path };
      if (s.value !== want || s.caret !== want.length) fail(`the tap left ${JSON.stringify(s.value)} (caret ${s.caret}), not ${JSON.stringify(want)}`);
      if (s.focus !== "field") fail(`the tap moved the focus to ${s.focus}`);
      if (s.mode !== "chat" || s.chip !== null || s.path !== chat) fail(`the tap changed the box or the route: ${JSON.stringify(details.tap)}`);
      // Enter on touch picks at once.
      await insertSlow(page, "and /co");
      s = await untilSlash(page, (x) => x.menuShown && x.rows.length > 0);
      const first = s.rows[0] ?? "";
      await keyCode(page, "Enter", 13, { text: "\r" });
      s = await untilSlash(page, (x) => !x.menu);
      details.enter = { first, value: s.value };
      if (!first || s.value !== `${want}and /${first} `) fail(`Enter on touch left ${JSON.stringify(s.value)}, not the pick of /${first}`);
      // The menu goes with the keyboard.
      await insertSlow(page, "/");
      s = await untilSlash(page, (x) => x.menuShown);
      if (!s.menuShown) fail("a typed / on touch did not open the menu");
      await page.evaluate("window.__standInKeyboard(0)");
      await sleep(1100);
      s = await readSlash(page);
      details.down = { menu: s.menu };
      if (s.menu) fail("the keyboard went down and the menu stayed over the composer");
      stateFindings(await page.probe(), vp, failures);
      noActing(wire, m, "the flow", fail);
      issueFindings(page.takeIssues(), failures);
      const end = await emptyBox(page);
      if (end.value !== "" || end.mode !== "chat") warnings.push({ code: "flow", text: `the message box could not be emptied at the end (${JSON.stringify({ value: end.value, mode: end.mode })})` });
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = 'a mid-line / opens the menu right above the box and the keyboard, 44 px rows; a tap puts "/<name> " as plain text, focus kept; Enter picks; it goes with the keyboard; nothing acting sent';
  return finish({ kind: "flow", name: "slash-midline-touch", route: "slashMenu", scene, size: sizeTag(vp), theme: "light", path: chat, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

// ---------------------------------------------------------------------------------------------------------------
// Row 76 (DECISIONS-OWNER, W19d): the command chip never takes more of its row than leaves the field about 8em; a
// longer name is cut with an ellipsis and the whole name is its title; a field that must wrap starts flush left on
// its own line; Send never leaves the box; nothing is centred; text typed key by key goes in as typed.

/** A message box's parts as the page lays them out: `root` holds them; `slab` is the box, `field` the text field. */
const BOX_LAYOUT = (root: string, slab: string, field: string, send: string) => `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && getComputedStyle(el).display !== "none" && !el.closest('[hidden="until-found"]');
  const rect = (el) => { if (!shown(el)) return null; const r = el.getBoundingClientRect(); const k = (n) => Math.round(n * 10) / 10; return { left: k(r.left), right: k(r.right), top: k(r.top), bottom: k(r.bottom), width: k(r.width), height: k(r.height) }; };
  const box = [...document.querySelectorAll(${JSON.stringify(root)})].find(shown) || null;
  const pick = (sel) => (box ? [...box.querySelectorAll(sel)].find(shown) || null : null);
  const chip = pick(".cmp-chip.is-slash");
  const name = chip ? chip.querySelector(".cmp-chip-name") || chip : null;
  const f = pick(${JSON.stringify(field)});
  const cs = f ? getComputedStyle(f) : null;
  return {
    slab: rect(box && (box.matches(${JSON.stringify(slab)}) ? box : pick(${JSON.stringify(slab)}))),
    chip: rect(chip), chipText: chip ? chip.textContent : null, chipTitle: chip ? chip.getAttribute("title") : null,
    chipCut: name ? name.scrollWidth > name.clientWidth + 1 : null, chipOverflow: name ? getComputedStyle(name).textOverflow : null,
    field: rect(f), line: rect(f && f.parentElement), fieldFont: cs ? parseFloat(cs.fontSize) : null, fieldAlign: cs ? cs.textAlign : null,
    value: f ? f.value : null, caret: f ? f.selectionStart : null,
    send: rect(pick(${JSON.stringify(send)})),
    mentions: box ? [...box.querySelectorAll('[data-testid="mention-chip"]')].map((c) => c.getAttribute("data-path")) : [],
    attach: (() => {
      const a = pick(".cmp-attach, .scr-attachments");
      if (!a) return null;
      const chips = [...a.children].filter(shown);
      return { scroll: a.scrollHeight, client: a.clientHeight, chips: chips.length, rows: new Set(chips.map((c) => Math.round(c.getBoundingClientRect().top))).size };
    })(),
    visual: Math.round(visualViewport ? visualViewport.height : innerHeight),
    menu: !!document.querySelector('[data-testid="slash-menu"], [data-testid="mention-menu"]'),
    path: location.pathname + location.search,
  };
})())`;

interface Rect {
  left: number;
  right: number;
  top: number;
  bottom: number;
  width: number;
  height: number;
}

interface BoxLayout {
  slab: Rect | null;
  chip: Rect | null;
  chipText: string | null;
  chipTitle: string | null;
  chipCut: boolean | null;
  chipOverflow: string | null;
  field: Rect | null;
  line: Rect | null;
  fieldFont: number | null;
  fieldAlign: string | null;
  value: string | null;
  caret: number | null;
  send: Rect | null;
  mentions: string[];
  /** The chips' row over the field: its scroll and client heights, its chips and their rows (distinct tops). */
  attach: { scroll: number; client: number; chips: number; rows: number } | null;
  /** The visual viewport's height (the stand-in keyboard's top on touch). */
  visual: number;
  menu: boolean;
  path: string;
}

/** W19d: one row of chips never scrolls inside its box (the touch Remove's hit area stuck out of a 44 px chip). */
function oneRowFindings(s: BoxLayout, fail: (text: string, code?: string) => void) {
  if (s.attach && s.attach.rows === 1 && s.attach.scroll > s.attach.client + 1) fail(`one row of chips scrolls inside its box: ${JSON.stringify(s.attach)}`, "layout");
}

const COMPOSER_BOX = BOX_LAYOUT('[data-testid="composer"]', ".cmp-slab", '[data-testid="composer-input"]', '[data-testid="composer-send"], [data-testid="confirm-send"]');

/**
 * Row 76's rules for a box that holds the command chip of `command` and the field with `typed`: the chip inside the
 * box, cut with an ellipsis when it is cut, its whole name in its title; the field at least about 8em wide (7.5em),
 * inside the box, beside the chip or flush left on a line of its own, its text not centred; Send inside the box; the
 * text as typed, key by key.
 */
function boxLayoutFindings(s: BoxLayout, command: string, typedText: string, fail: (text: string, code?: string) => void) {
  const name = `/${command}`;
  const { slab, chip, field, send, line } = s;
  if (!slab || !chip || !field) return fail(`the box, the chip or the field does not show: ${JSON.stringify({ slab, chip, field })}`, "shows");
  const inside = (r: Rect, what: string) => {
    if (r.left < slab.left - 0.5 || r.right > slab.right + 0.5 || r.top < slab.top - 0.5 || r.bottom > slab.bottom + 0.5) fail(`${what} leaves the box: ${JSON.stringify(r)} in ${JSON.stringify(slab)}`, "layout");
  };
  if (s.chipText !== name) fail(`the chip reads ${JSON.stringify(s.chipText)}, not ${JSON.stringify(name)}`);
  if (s.chipTitle !== name) fail(`the chip's title is ${JSON.stringify(s.chipTitle)}, not the whole name ${JSON.stringify(name)}`);
  if (s.chipCut && s.chipOverflow !== "ellipsis") fail(`the chip is cut with no ellipsis (text-overflow ${s.chipOverflow})`, "layout");
  inside(chip, "the chip");
  inside(field, "the field");
  if (send) inside(send, "Send");
  else fail("Send does not show", "shows");
  const em = s.fieldFont ?? 16;
  const ownLine = field.top >= chip.bottom - 1;
  if (ownLine) {
    if (line && Math.abs(field.left - line.left) > 1) fail(`the field wrapped to its own line but starts ${Math.round(field.left - line.left)} px from the line's left`, "layout");
  } else {
    if (field.width < 7.5 * em) fail(`the field beside the chip is ${field.width} px wide, under 8em (${Math.round(8 * em)} px)`, "layout");
    if (field.left < chip.right - 0.5) fail(`the field (left ${field.left}) starts under the chip (right ${chip.right})`, "layout");
  }
  if (s.fieldAlign !== "start" && s.fieldAlign !== "left") fail(`the field's text is aligned ${s.fieldAlign}`, "layout");
  if (s.value !== typedText) fail(`the field holds ${JSON.stringify(s.value)}, not ${JSON.stringify(typedText)} as typed`);
  oneRowFindings(s, fail);
}

/** A / menu row's name for `command`, the row and the menu, as the page lays them out. */
const MENU_NAME = (command: string) => `JSON.stringify((() => {
  const rect = (el) => { if (!el) return null; const r = el.getBoundingClientRect(); return { left: Math.round(r.left), right: Math.round(r.right), top: Math.round(r.top), bottom: Math.round(r.bottom), width: Math.round(r.width), height: Math.round(r.height) }; };
  const menu = document.querySelector('[data-testid="slash-menu"]');
  const row = menu ? menu.querySelector('[data-command="' + CSS.escape(${JSON.stringify(command)}) + '"]') : null;
  const name = row ? row.querySelector(".cmp-slash-name") : null;
  return { menu: rect(menu), row: rect(row), name: rect(name), text: name ? name.textContent : null, cut: name ? name.scrollWidth > name.clientWidth + 1 : null };
})())`;

interface MenuName {
  menu: Rect | null;
  row: Rect | null;
  name: Rect | null;
  text: string | null;
  cut: boolean | null;
}

/** The / menu shows the whole name (row 76): not cut, inside its row and the menu, on every size. */
function menuNameFindings(s: MenuName, command: string, fail: (text: string, code?: string) => void) {
  if (!s.menu || !s.row || !s.name) return fail(`the / menu has no row for /${command}: ${JSON.stringify(s)}`, "shows");
  if (s.text !== `/${command}`) fail(`the menu row reads ${JSON.stringify(s.text)}, not the whole name /${command}`);
  if (s.cut) fail("the menu row's name is cut", "layout");
  if (s.name.left < s.menu.left - 0.5 || s.name.right > s.menu.right + 0.5) fail(`the menu row's name leaves the menu: ${JSON.stringify(s.name)} in ${JSON.stringify(s.menu)}`, "layout");
}

/** A device setting in this page's local storage before its first script (the page reads it at load). */
const DEVICE_SETTING = (key: string, value: unknown) =>
  `(() => { try { const k = "kitespan.settings"; const v = JSON.parse(localStorage.getItem(k) || "{}"); v[${JSON.stringify(key)}] = ${JSON.stringify(value)}; localStorage.setItem(k, JSON.stringify(v)); } catch {} })()`;

/**
 * Row 76 in a chat's box (the owner's report of 2026-11-02): on the example chat with its box emptied first and left
 * empty after, "@READ" and Enter add the README.md mention chip, "/acme" and Enter pick the seed's long plugin command
 * (40 characters with a colon) as the chip, and "all tests" typed key by key are its arguments. At 1100 x 800, a
 * narrow laptop box (900 x 800 at the largest text size), 834 x 1194, 390 x 844 and a small phone's 320 x 568 (touch,
 * the stand-in keyboard up; there the field goes to its own line): boxLayoutFindings, no sideways overflow, no console
 * error, nothing acting sent.
 */
async function chipLayoutFlow(base: string, scene: SceneName | null, vp: Viewport, variant: "" | "narrow" | "small" = ""): Promise<CheckResult> {
  const narrow = variant === "narrow";
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const chat = `/c/${EX.chat}`;
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  const id = variant ? `chip-layout-${variant}` : "chip-layout";
  let shot: string | undefined;
  try {
    await withPage(vp, "light", async (page, wire) => {
      if (vp.touch) await page.send("Page.addScriptToEvaluateOnNewDocument", { source: STAND_IN_KEYBOARD });
      if (narrow) await page.send("Page.addScriptToEvaluateOnNewDocument", { source: DEVICE_SETTING("textSize", 1.3) });
      await page.navigate(base + chat);
      await waitShown(page, ["chat", "composer"]);
      await sleep(400);
      const start = await emptyBox(page);
      if (start.mode !== "chat" || start.value !== "" || start.chips.length) throw new Error(`could not empty the message box: ${JSON.stringify({ mode: start.mode, value: start.value, chips: start.chips })}`);
      page.takeIssues();
      const m = wire.mark();
      const field = await page.locate('[data-testid="composer-input"]');
      if (!field) throw new Error("no composer field");
      await page.press(field.x, field.y);
      await sleep(250);
      if (vp.touch) {
        await page.evaluate(`window.__standInKeyboard(${vp.name === "phone" ? 336 : 400})`);
        await sleep(400);
      }
      await insertSlow(page, "@READ");
      const ms = await untilMention(page, (x) => x.rows.includes("README.md"), 6000);
      if (!ms.rows.includes("README.md")) throw new Error(`"@READ" found no README.md row: ${JSON.stringify(ms.rows)}`);
      await keyCode(page, "Enter", 13, { text: "\r" });
      const mc = await untilMention(page, (x) => x.chips.includes("README.md"));
      if (!mc.chips.includes("README.md")) fail(`Enter added no README.md chip: ${JSON.stringify(mc.chips)}`);
      await insertSlow(page, "/acme");
      const sl = await untilSlash(page, (x) => x.rows.includes(LONG_COMMAND), 6000);
      if (!sl.rows.includes(LONG_COMMAND)) throw new Error(`"/acme" found no /${LONG_COMMAND} row: ${JSON.stringify(sl.rows)}`);
      const row = JSON.parse(await page.evaluate<string>(MENU_NAME(LONG_COMMAND))) as MenuName;
      details.menuRow = row;
      menuNameFindings(row, LONG_COMMAND, fail);
      await keyCode(page, "Enter", 13, { text: "\r" });
      await untilSlash(page, (x) => x.chip === `/${LONG_COMMAND}`);
      // Key by key, as the owner typed (the field 0 px wide took each key in front of the last: "stset lla").
      for (const ch of "all tests") {
        await page.send("Input.insertText", { text: ch });
        await sleep(90);
      }
      await sleep(400);
      const s = JSON.parse(await page.evaluate<string>(COMPOSER_BOX)) as BoxLayout;
      details.layout = s;
      boxLayoutFindings(s, LONG_COMMAND, "all tests", fail);
      if (!s.mentions.includes("README.md")) fail(`the README.md chip is gone: ${JSON.stringify(s.mentions)}`);
      shot = shotName(scene, id, vp, "light");
      await page.screenshot(shot).catch(() => {});
      stateFindings(await page.probe(), vp, failures);
      noActing(wire, m, "the flow", fail);
      issueFindings(page.takeIssues(), failures);
      if (vp.touch) await page.evaluate("window.__standInKeyboard(0)");
      const end = await emptyBox(page);
      if (end.value !== "" || end.mode !== "chat" || end.chips.length) warnings.push({ code: "flow", text: `the message box could not be emptied at the end (${JSON.stringify({ value: end.value, mode: end.mode, chips: end.chips })})` });
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = "a mention chip, the long command chip and its arguments: the chip cut with an ellipsis and its name in its title, the field 8em or on its own line flush left, Send in the box, nothing centred, the text as typed";
  return finish({ kind: "flow", name: id, route: "slashMenu", scene, size: sizeTag(vp), theme: "light", path: chat, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

// ---------------------------------------------------------------------------------------------------------------
// D59 (DECISIONS-OWNER row 75): the new-chat form's box is a chat's composer: the / menu over the project's commands
// ("/" in the empty field: the command chip; mid-line: text), the @ picker over the project's folder with mention
// chips, the same keys and the IME guard; Start sends the mentions in the new_chat frame, and a command chip's command
// as the first message.

const FORM_BOX = BOX_LAYOUT('[data-testid="new-chat"] .scr-box', ".scr-box", "#scr-prompt", '[data-testid="confirm-start"]');

/** The form's box, its menus and its chips, as the page shows them. */
const FORM_STATE = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && getComputedStyle(el).display !== "none" && !el.closest('[hidden="until-found"]');
  const rect = (el) => { if (!shown(el)) return null; const r = el.getBoundingClientRect(); return { left: Math.round(r.left), right: Math.round(r.right), top: Math.round(r.top), bottom: Math.round(r.bottom), width: Math.round(r.width), height: Math.round(r.height) }; };
  const form = document.querySelector('[data-testid="new-chat"]');
  const box = form ? form.querySelector(".scr-box") : null;
  const field = document.getElementById("scr-prompt");
  const slash = form ? form.querySelector('[data-testid="slash-menu"]') : null;
  const mention = form ? form.querySelector('[data-testid="mention-menu"]') : null;
  const chip = box ? box.querySelector(".cmp-chip.is-slash") : null;
  const rowsOf = (menu, attr) => (menu ? [...menu.querySelectorAll('[role="option"]')] : []);
  const sRows = rowsOf(slash);
  const mRows = rowsOf(mention);
  const at = document.activeElement;
  const vv = window.visualViewport;
  const start = document.querySelector('[data-testid="confirm-start"]');
  return {
    form: !!form, value: field ? field.value : null, caret: field ? field.selectionStart : null,
    mode: box ? box.getAttribute("data-mode") : null, chip: chip ? chip.textContent : null, chipTitle: chip ? chip.getAttribute("title") : null,
    slash: !!slash, slashShown: shown(slash), slashRows: sRows.map((r) => r.getAttribute("data-command")), slashActive: sRows.findIndex((r) => r.getAttribute("aria-selected") === "true"),
    slashEmpty: slash && slash.querySelector(".cmp-slash-empty") ? slash.querySelector(".cmp-slash-empty").textContent : null,
    mention: !!mention, mentionShown: shown(mention), mentionRows: mRows.map((r) => r.getAttribute("data-path")), mentionActive: mRows.findIndex((r) => r.getAttribute("aria-selected") === "true"),
    mentionEmpty: mention && mention.querySelector('[data-testid="mention-empty"]') ? mention.querySelector('[data-testid="mention-empty"]').textContent : null,
    mentions: form ? [...form.querySelectorAll('[data-testid="mention-chip"]')].map((c) => c.getAttribute("data-path")) : [],
    menuBox: rect(shown(slash) ? slash : shown(mention) ? mention : null), rowBoxes: [...sRows, ...mRows].slice(0, 3).map(rect), boxRect: rect(box), fieldBox: rect(field), startBox: rect(start),
    view: { top: Math.round(vv ? vv.offsetTop : 0), bottom: Math.round(vv ? vv.offsetTop + vv.height : innerHeight) },
    focus: at === field ? "field" : at ? at.tagName.toLowerCase() + (at.getAttribute("data-testid") ? "#" + at.getAttribute("data-testid") : "") : null,
    activedesc: field ? field.getAttribute("aria-activedescendant") : null,
    startOff: start ? start.disabled : null,
    path: location.pathname + location.search,
  };
})())`;

interface FormState {
  form: boolean;
  value: string | null;
  caret: number | null;
  mode: string | null;
  chip: string | null;
  chipTitle: string | null;
  slash: boolean;
  slashShown: boolean;
  slashRows: string[];
  slashActive: number;
  slashEmpty: string | null;
  mention: boolean;
  mentionShown: boolean;
  mentionRows: string[];
  mentionActive: number;
  mentionEmpty: string | null;
  mentions: string[];
  menuBox: Rect | null;
  rowBoxes: (Rect | null)[];
  boxRect: Rect | null;
  fieldBox: Rect | null;
  startBox: Rect | null;
  view: { top: number; bottom: number };
  focus: string | null;
  activedesc: string | null;
  startOff: boolean | null;
  path: string;
}

const readForm = async (page: Page) => JSON.parse(await page.evaluate<string>(FORM_STATE)) as FormState;

async function untilForm(page: Page, ok: (s: FormState) => boolean, ms = 4000): Promise<FormState> {
  const end = Date.now() + ms;
  let s = await readForm(page);
  while (!ok(s) && Date.now() < end) {
    await sleep(80);
    s = await readForm(page);
  }
  return s;
}

/** The form's open menu: right under or over the box, inside the visual viewport (the keyboard's top), 44 px rows on touch. */
function formMenuPlace(s: FormState, vp: Viewport, fail: (text: string, code?: string) => void) {
  const m = s.menuBox;
  const b = s.boxRect;
  if (!m || !b) return fail(`the menu or the box does not show: ${JSON.stringify({ menu: m, box: b })}`, "shows");
  const under = m.top - b.bottom;
  const over = b.top - m.bottom;
  if (!(under >= 0 && under <= 10) && !(over >= 0 && over <= 10)) fail(`the menu is not right under or over the box: ${JSON.stringify({ menu: m, box: b })}`, "layout");
  if (m.top < s.view.top - 1 || m.bottom > s.view.bottom + 1) fail(`the menu (${m.top} to ${m.bottom} px) leaves the visible part of the page (${s.view.top} to ${s.view.bottom} px)`, "layout");
  if (m.left < b.left - 1 || m.right > b.right + 1) fail(`the menu is wider than the box: ${JSON.stringify({ menu: m, box: b })}`, "layout");
  if (vp.touch && s.rowBoxes.some((r) => r && r.height < 44)) fail(`rows under 44 px: ${JSON.stringify(s.rowBoxes.map((r) => r?.height))}`, "target");
}

/** Open the form for the example project at /new, focus its field (touch: a tap, with the stand-in keyboard up). */
async function openForm(page: Page, base: string, vp: Viewport): Promise<void> {
  if (vp.touch) await page.send("Page.addScriptToEvaluateOnNewDocument", { source: STAND_IN_KEYBOARD });
  await page.navigate(`${base}/new?project=${EX.project}`);
  await waitShown(page, ["new-chat"]);
  await sleep(300);
  const field = await page.locate("#scr-prompt");
  if (!field) throw new Error("no prompt field on the form");
  await page.press(field.x, field.y);
  await sleep(250);
  if (vp.touch) {
    await page.evaluate(`window.__standInKeyboard(${vp.name === "phone" ? 336 : 400})`);
    await sleep(400);
  }
}

/** A pick in the form's open menu: Enter on a laptop, a tap on the row on touch. */
async function formPick(page: Page, vp: Viewport, row: string): Promise<boolean> {
  if (!vp.touch) {
    await keyCode(page, "Enter", 13, { text: "\r" });
    return true;
  }
  const at = await page.locate(row);
  if (!at) return false;
  await page.press(at.x, at.y);
  await sleep(250);
  return true;
}

const FORM_FIELD = `document.getElementById("scr-prompt")`;

/** Select the form's text and delete it, as the user's own edit. */
async function clearForm(page: Page) {
  await page.evaluate(`(() => { const f = ${FORM_FIELD}; if (!f) return; f.focus(); f.select(); document.execCommand("delete"); })()`);
  await sleep(150);
}

/**
 * The form's / menu (D59) at /new for the example project, at 1100 x 800 and on touch at 834 x 1194 and 390 x 844
 * (the stand-in keyboard up): "/" in the empty field opens the / menu over the project's commands (the server's read,
 * asked again once while it had none) with no /clear or /compact row (they need a conversation, W19d), right under or
 * over the box and inside the visible page, with the focus kept
 * in the field and the URL kept; "acme" narrows it to the seed's long plugin command, and Enter (a tap on touch) makes
 * it the chip, its whole name in its title; "all tests" typed key by key are its arguments, and the chip, the field
 * and Start keep row 76's layout. Backspace at the start takes the chip, then the / mode, away. Mid-line, "test /co"
 * opens the same rows, and a pick puts "/<name> " in the text, in Chat mode with no chip; Esc keeps the text. A "!" is
 * text. On the laptop, a /new?text=/compact link fills the plain text "/compact" (no chip, no menu), and an edit keeps it
 * so. Nothing acting goes out; no console error, no sideways overflow.
 */
async function formSlashFlow(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const path = `/new?project=${EX.project}`;
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  let shot: string | undefined;
  try {
    await withPage(vp, "light", async (page, wire) => {
      await openForm(page, base, vp);
      page.takeIssues();
      const m = wire.mark();
      await insertSlow(page, "/");
      // The server reads the project's commands with a short Claude Code process the first time; the page asks again.
      let s = await untilForm(page, (x) => x.slashShown && x.slashRows.length > 0, 15_000);
      details.open = { rows: s.slashRows, empty: s.slashEmpty, mode: s.mode, chip: s.chip, focus: s.focus, path: s.path, menu: s.menuBox, box: s.boxRect, view: s.view };
      if (!s.slashShown || !s.slashRows.length) throw new Error(`"/" in the empty field opened no / menu with rows: ${JSON.stringify(details.open)}`);
      if (s.mode !== "slash" || s.chip !== "/") fail(`"/" did not pick the / mode: mode ${s.mode}, chip ${JSON.stringify(s.chip)}`);
      if (s.focus !== "field") fail(`the focus left the field: ${s.focus}`);
      if (s.path !== path) fail(`the menu changed the URL to ${s.path}`, "route");
      // The start menu leaves out the built-in commands that act on a conversation that exists (W19d).
      for (const gone of ["clear", "compact"]) if (s.slashRows.includes(gone)) fail(`the start menu has a /${gone} row, which needs a conversation: ${JSON.stringify(s.slashRows)}`);
      if (!s.slashRows.includes("context")) fail(`the menu has no /context row: ${JSON.stringify(s.slashRows)}`);
      formMenuPlace(s, vp, fail);
      shot = shotName(scene, "form-slash", vp, "light", "open");
      await page.screenshot(shot).catch(() => {});
      stateFindings(await page.probe(), vp, failures, "with the menu open: ");
      await insertSlow(page, "acme");
      s = await untilForm(page, (x) => x.slashRows.includes(LONG_COMMAND) && x.slashRows.every((r) => r.includes("acme")));
      details.narrowed = s.slashRows;
      if (!s.slashRows.includes(LONG_COMMAND)) throw new Error(`"/acme" found no /${LONG_COMMAND} row: ${JSON.stringify(s.slashRows)}`);
      if (!s.slashRows.every((r) => r.includes("acme"))) fail(`"acme" did not narrow the rows: ${JSON.stringify(s.slashRows)}`);
      const row = JSON.parse(await page.evaluate<string>(MENU_NAME(LONG_COMMAND))) as MenuName;
      menuNameFindings(row, LONG_COMMAND, fail);
      if (!(await formPick(page, vp, `[data-testid="new-chat"] [data-testid="slash-menu"] [data-command="${LONG_COMMAND}"]`))) fail("no row to tap");
      s = await untilForm(page, (x) => x.chip === `/${LONG_COMMAND}` && !x.slash);
      details.picked = { chip: s.chip, title: s.chipTitle, value: s.value, menu: s.slash, focus: s.focus };
      if (s.chip !== `/${LONG_COMMAND}` || s.value !== "" || s.slash) fail(`the pick left ${JSON.stringify(details.picked)}, not the chip with an empty field and no menu`);
      if (s.focus !== "field") fail(`the pick moved the focus to ${s.focus}`);
      for (const ch of "all tests") {
        await page.send("Input.insertText", { text: ch });
        await sleep(90);
      }
      await sleep(300);
      const layout = JSON.parse(await page.evaluate<string>(FORM_BOX)) as BoxLayout;
      details.layout = layout;
      boxLayoutFindings(layout, LONG_COMMAND, "all tests", fail);
      s = await readForm(page);
      if (s.startOff !== false) fail("Start is off with a command chip and its arguments");
      await page.screenshot(shotName(scene, "form-slash", vp, "light", "chip")).catch(() => {});
      // The chip is the draft's: a reload brings it back with its arguments (this device's draft, until Start).
      await page.reload();
      await waitShown(page, ["new-chat"]);
      s = await untilForm(page, (x) => x.chip === `/${LONG_COMMAND}`);
      details.reloaded = { chip: s.chip, value: s.value, mode: s.mode };
      if (s.chip !== `/${LONG_COMMAND}` || s.value !== "all tests") fail(`after a reload the box holds ${JSON.stringify(details.reloaded)}, not the chip and "all tests"`);
      await page.evaluate(`(() => { const f = ${FORM_FIELD}; if (f) { f.focus(); f.setSelectionRange(f.value.length, f.value.length); } })()`);
      if (vp.touch) {
        await page.evaluate(`window.__standInKeyboard(${vp.name === "phone" ? 336 : 400})`);
        await sleep(300);
      }
      // Backspace at the start: the chip goes (the field is the command filter again), then the / mode.
      await clearForm(page);
      await keyCode(page, "Backspace", 8);
      s = await untilForm(page, (x) => x.chip === "/");
      details.unchip = { mode: s.mode, chip: s.chip, value: s.value };
      if (s.mode !== "slash" || s.chip !== "/") fail(`Backspace at the start did not take the chip away: ${JSON.stringify(details.unchip)}`);
      await keyCode(page, "Backspace", 8);
      s = await untilForm(page, (x) => x.mode === "chat");
      if (s.mode !== "chat" || s.chip !== null || s.value !== "") fail(`a second Backspace left ${JSON.stringify({ mode: s.mode, chip: s.chip, value: s.value })}, not an empty message`);
      // Mid-line (D57): the same rows; a pick is text.
      await insertSlow(page, "test /co");
      s = await untilForm(page, (x) => x.slashShown && x.slashRows.length > 0 && x.slashRows.every((r) => r.includes("co")));
      const name = s.slashRows[0] ?? "";
      details.midline = { rows: s.slashRows, mode: s.mode };
      if (!s.slashShown || !name) fail(`"test /co" opened no rows: ${JSON.stringify(details.midline)}`);
      else formMenuPlace(s, vp, fail);
      if (name && !(await formPick(page, vp, `[data-testid="new-chat"] [data-testid="slash-menu"] [data-command="${name}"]`))) fail("no mid-line row to tap");
      s = await untilForm(page, (x) => !x.slash);
      const want = `test /${name} `;
      details.midPicked = { value: s.value, caret: s.caret, mode: s.mode, chip: s.chip };
      if (s.value !== want || s.caret !== want.length || s.mode !== "chat" || s.chip !== null) fail(`the mid-line pick left ${JSON.stringify(details.midPicked)}, not ${JSON.stringify(want)} as text`);
      await insertSlow(page, "and /");
      s = await untilForm(page, (x) => x.slashShown);
      await keyCode(page, "Escape", 27);
      s = await readForm(page);
      if (s.slash || s.value !== `${want}and /`) fail(`Esc: menu ${s.slash ? "still open" : "closed"}, text ${JSON.stringify(s.value)}`);
      // A "!" is text: the form has no Bash mode.
      await clearForm(page);
      await insertSlow(page, "!");
      s = await readForm(page);
      if (s.mode !== "chat" || s.value !== "!") fail(`"!" in the empty field gave mode ${s.mode} and text ${JSON.stringify(s.value)}, not the text "!"`);
      // A link only pre-fills: /new?text=/compact is the text "/compact", with no chip and no menu, and stays text.
      if (!vp.touch) {
        await page.navigate(`${base}/new?project=${EX.project}&text=${encodeURIComponent(`/${EX.command}`)}`);
        await waitShown(page, ["new-chat"]);
        await sleep(300);
        s = await readForm(page);
        details.link = { value: s.value, mode: s.mode, chip: s.chip, menu: s.slash, focus: s.focus };
        if (s.value !== `/${EX.command}` || s.mode !== "chat" || s.chip !== null || s.slash) fail(`a /new?text=/${EX.command} link gave ${JSON.stringify(details.link)}, not the plain text`);
        await page.evaluate(`(() => { const f = ${FORM_FIELD}; if (f) { f.focus(); f.setSelectionRange(f.value.length, f.value.length); } })()`);
        await insertSlow(page, " now");
        s = await readForm(page);
        if (s.mode !== "chat" || s.chip !== null || s.slash || s.value !== `/${EX.command} now`) fail(`an edit of the link's text gave ${JSON.stringify({ value: s.value, mode: s.mode, chip: s.chip, menu: s.slash })}`);
      }
      noActing(wire, m, "the flow", fail);
      stateFindings(await page.probe(), vp, failures);
      issueFindings(page.takeIssues(), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = '"/" in the empty field opens the project\'s / menu next to the box; a pick is the chip, cut with its name in its title, the field 8em; Backspace unchips; mid-line "/" picks as text; Esc keeps the text; "!" is text; nothing sent';
  return finish({ kind: "flow", name: "form-slash", route: "new", scene, size: sizeTag(vp), theme: "light", path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * The form's @ picker (D59) at /new for the example project, at 1100 x 800 (typed "@", text with no key event) and on
 * touch at 834 x 1194 and 390 x 844 (the @ button beside +, the focus kept, the stand-in keyboard up): it opens over
 * the project's folder (the project corpus routes) right under or over the box, inside the visible page; "READ"
 * narrows to README.md, and Enter (a tap on touch) adds its mention chip and takes "@READ" out of the field; "@zzzz"
 * shows "No file matches @zzzz." and Enter adds nothing and starts nothing; Esc closes it and keeps the text. On the
 * laptop, while an input method composes, Enter neither picks nor starts. One row of chips does not scroll, and 12
 * chips (put in this device's draft) are capped at about two rows that scroll inside the box, so on touch the field
 * and Start stay above the stand-in keyboard (W19d). Nothing acting goes out.
 */
async function formAtFlow(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const path = `/new?project=${EX.project}`;
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  let shot: string | undefined;
  try {
    await withPage(vp, "light", async (page, wire) => {
      await openForm(page, base, vp);
      page.takeIssues();
      const m = wire.mark();
      if (vp.touch) {
        const at = await page.locate('[data-testid="new-chat"] [data-testid="composer-at"]');
        if (!at) throw new Error("no @ button beside + on touch");
        await page.press(at.x, at.y);
        await sleep(250);
        const s = await readForm(page);
        if (s.focus !== "field") fail(`the @ button moved the focus to ${s.focus}`);
        if (s.value !== "@") fail(`the @ button left ${JSON.stringify(s.value)} in the field, not "@"`);
        await insertSlow(page, "READ");
      } else await insertSlow(page, "@READ");
      let s = await untilForm(page, (x) => x.mentionShown && x.mentionRows.includes("README.md"), 8000);
      details.open = { rows: s.mentionRows, focus: s.focus, menu: s.menuBox, box: s.boxRect, view: s.view, path: s.path };
      if (!s.mentionRows.includes("README.md")) throw new Error(`"@READ" found no README.md row: ${JSON.stringify(details.open)}`);
      if (s.focus !== "field") fail(`the focus left the field: ${s.focus}`);
      if (s.path !== path) fail(`the picker changed the URL to ${s.path}`, "route");
      if (s.activedesc !== `form-mention-${s.mentionActive}`) fail(`the field's aria-activedescendant is ${s.activedesc}`);
      formMenuPlace(s, vp, fail);
      shot = shotName(scene, "form-at", vp, "light", "open");
      await page.screenshot(shot).catch(() => {});
      if (!vp.touch) {
        // The IME guard: while an input method composes, Enter is its own.
        await page.send("Input.imeSetComposition", { text: "x", selectionStart: 1, selectionEnd: 1 });
        await sleep(200);
        await keyCode(page, "Enter", 13);
        s = await readForm(page);
        if (s.mentions.length || !s.mention) fail(`Enter while composing: chips ${JSON.stringify(s.mentions)}, picker ${s.mention ? "open" : "closed"}`);
        // The commit is the composed text, inserted (as the at-picker-ime flow does); then it goes again.
        await page.send("Input.insertText", { text: "x" });
        await sleep(150);
        await keyCode(page, "Backspace", 8);
        s = await untilForm(page, (x) => x.mentionRows.includes("README.md"));
      }
      const target = s.mentionRows.indexOf("README.md");
      if (!vp.touch) for (let i = 0; i < target; i++) await keyCode(page, "ArrowDown", 40);
      if (!(await formPick(page, vp, '[data-testid="new-chat"] [data-testid="mention-menu"] [data-path="README.md"]'))) fail("no README.md row to tap");
      s = await untilForm(page, (x) => x.mentions.includes("README.md"));
      details.picked = { chips: s.mentions, value: s.value, caret: s.caret, menu: s.mention, focus: s.focus };
      if (JSON.stringify(s.mentions) !== JSON.stringify(["README.md"])) fail(`the pick did not add the one README.md chip: ${JSON.stringify(s.mentions)}`);
      if (s.value !== "" || s.mention) fail(`after the pick the field holds ${JSON.stringify(s.value)} and the picker is ${s.mention ? "open" : "closed"}`);
      if (s.focus !== "field") fail(`the pick moved the focus to ${s.focus}`);
      // No match: the one line, and Enter adds nothing and starts nothing.
      await insertSlow(page, "see @zzzz");
      s = await untilForm(page, (x) => x.mentionEmpty !== null, 6000);
      if (s.mentionEmpty !== "No file matches @zzzz.") fail(`"@zzzz" shows ${JSON.stringify(s.mentionEmpty)}, not "No file matches @zzzz."`);
      await keyCode(page, "Enter", 13, { text: "\r" });
      s = await readForm(page);
      if (s.mentions.length !== 1 || s.value !== "see @zzzz" || !s.path.startsWith("/new")) fail(`Enter with no row: ${JSON.stringify({ chips: s.mentions, value: s.value, path: s.path })}`);
      await keyCode(page, "Escape", 27);
      s = await readForm(page);
      if (s.mention || s.value !== "see @zzzz") fail(`Esc: picker ${s.mention ? "still open" : "closed"}, text ${JSON.stringify(s.value)}`);
      await page.screenshot(shotName(scene, "form-at", vp, "light", "chip")).catch(() => {});
      // The mention chips are the draft's: a reload brings them back.
      await page.reload();
      await waitShown(page, ["new-chat"]);
      s = await untilForm(page, (x) => x.mentions.length > 0);
      if (JSON.stringify(s.mentions) !== JSON.stringify(["README.md"]) || s.value !== "see @zzzz") fail(`after a reload: chips ${JSON.stringify(s.mentions)}, text ${JSON.stringify(s.value)}`);
      // W19d: one row of chips does not scroll; many chips (12, put in this device's draft) are capped at about two
      // rows and scroll inside the box, so on touch the field and Start stay above the stand-in keyboard.
      const one = JSON.parse(await page.evaluate<string>(FORM_BOX)) as BoxLayout;
      details.oneRow = one.attach;
      oneRowFindings(one, fail);
      const kept = JSON.parse((await page.evaluate<string>(`localStorage.getItem("kitespan.newchat") || "null"`)) || "null") as Record<string, unknown> | null;
      if (!kept) fail("the form kept no draft on this device");
      else {
        const paths = ["README.md", ...Array.from({ length: 11 }, (_, i) => `docs/meeting-notes/2026-11-${String(i + 1).padStart(2, "0")}-planning.md`)];
        await page.evaluate(`localStorage.setItem("kitespan.newchat", ${JSON.stringify(JSON.stringify({ ...kept, mentions: { project: EX.project, paths } }))})`);
        await page.reload();
        await waitShown(page, ["new-chat"]);
        await untilForm(page, (x) => x.mentions.length === paths.length);
        await page.evaluate(`(() => { const f = ${FORM_FIELD}; if (f) { f.focus(); f.setSelectionRange(f.value.length, f.value.length); } })()`);
        if (vp.touch) await page.evaluate(`window.__standInKeyboard(${vp.name === "phone" ? 336 : 400})`);
        await sleep(400);
        const many = JSON.parse(await page.evaluate<string>(FORM_BOX)) as BoxLayout;
        details.many = { attach: many.attach, field: many.field, start: many.send, visual: many.visual };
        if (!many.attach || many.attach.chips !== paths.length) fail(`the box shows ${many.attach?.chips ?? 0} chips, not ${paths.length}`, "shows");
        else if (many.attach.rows > 2 && many.attach.scroll <= many.attach.client + 1) fail(`${many.attach.rows} rows of chips do not scroll inside the box: ${JSON.stringify(many.attach)}`, "layout");
        if (vp.touch) {
          if (!many.field || many.field.bottom > many.visual + 0.5) fail(`with ${paths.length} chips the field ends at ${many.field?.bottom}, under the keyboard's top at ${many.visual}`, "layout");
          if (!many.send || many.send.bottom > many.visual + 0.5) fail(`with ${paths.length} chips Start ends at ${many.send?.bottom}, under the keyboard's top at ${many.visual}`, "layout");
        }
        await page.screenshot(shotName(scene, "form-at", vp, "light", "many")).catch(() => {});
      }
      noActing(wire, m, "the flow", fail);
      stateFindings(await page.probe(), vp, failures);
      issueFindings(page.takeIssues(), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = vp.touch ? "the @ button keeps the focus; the picker over the project's folder next to the box, 44 px rows; a tap adds the chip; no match: one line; Esc keeps the text; nothing sent" : "a typed @ opens the picker over the project's folder next to the box; the IME guard; Enter adds the chip; no match: one line, Enter starts nothing; Esc keeps the text; nothing sent";
  return finish({ kind: "flow", name: "form-at", route: "new", scene, size: sizeTag(vp), theme: "light", path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * Start from the form (D59) on a laptop (1100 x 800): with the command chip ("/acme", Enter, "all tests"), one new_chat
 * frame whose text is the command with its arguments, an ok ack, the chat's page in the same document, and the fake
 * claude gets the text once; with a mention chip (README.md) and "Read it", one new_chat frame with
 * mentions ["README.md"], an ok ack, the fake claude gets the file's reference (messageRef of its absolute path) once,
 * and the new chat's message shows the file's tile. Each Start adds one chat to the example project.
 */
async function formStartFlow(t: Target, scene: SceneName | null, vp: Viewport, variant: "command" | "mention"): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const path = `/new?project=${EX.project}`;
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  const id = `form-start-${variant}`;
  let shot: string | undefined;
  try {
    await withPage(vp, "light", async (page, wire) => {
      await openForm(page, t.base, vp);
      page.takeIssues();
      let text: string;
      if (variant === "command") {
        await insertSlow(page, "/acme");
        const s = await untilForm(page, (x) => x.slashRows.includes(LONG_COMMAND), 15_000);
        if (!s.slashRows.includes(LONG_COMMAND)) throw new Error(`"/acme" found no /${LONG_COMMAND} row: ${JSON.stringify(s.slashRows)}`);
        await keyCode(page, "Enter", 13, { text: "\r" });
        await untilForm(page, (x) => x.chip === `/${LONG_COMMAND}`);
        await insertSlow(page, "all tests");
        text = `/${LONG_COMMAND} all tests`;
      } else {
        await insertSlow(page, "@READ");
        const s = await untilForm(page, (x) => x.mentionRows[0] === "README.md", 8000);
        if (s.mentionRows[0] !== "README.md") throw new Error(`"@READ" did not put README.md first: ${JSON.stringify(s.mentionRows)}`);
        await keyCode(page, "Enter", 13, { text: "\r" });
        await untilForm(page, (x) => x.mentions.includes("README.md"));
        await insertSlow(page, "Read it");
        text = "Read it";
      }
      const m = wire.mark();
      // v0.6 touch: the same Start runs at more than one size on this seed, so the fake's count starts from here.
      const lookFor = variant === "mention" && t.booted ? messageRef(`${t.booted.seed.folders.kitespan}/README.md`) : text;
      const saw0 = t.booted ? claudeSaw(t.booted, lookFor) : 0;
      const start = await page.locate('[data-testid="confirm-start"]');
      if (!start) throw new Error("no Start button");
      await page.press(start.x, start.y);
      await waitSent(wire, m);
      const frames = wire.framesSince(m).filter((f) => f.t === "new_chat");
      details.frames = frames.map((f) => ({ text: f.frame.text, mentions: f.frame.mentions }));
      if (frames.length !== 1 || frames[0]!.frame.text !== text) fail(`Start sent ${JSON.stringify(details.frames)}, not one new_chat with ${JSON.stringify(text)}`);
      if (variant === "mention" && JSON.stringify(frames[0]?.frame.mentions) !== JSON.stringify(["README.md"])) fail(`the new_chat frame's mentions are ${JSON.stringify(frames[0]?.frame.mentions)}, not ["README.md"]`);
      if (variant === "command" && frames[0]?.frame.mentions !== undefined) fail(`the new_chat frame names mentions: ${JSON.stringify(frames[0]?.frame.mentions)}`);
      const ack = frames[0]?.rid ? await waitAck(wire, frames[0].rid, 8000) : null;
      details.ack = ack;
      if (!ack?.ok) fail(`the new_chat ack: ${JSON.stringify(ack)}`);
      const end = Date.now() + 6000;
      let at = await page.evaluate<string>("location.pathname");
      while (!/^\/c\/[a-z0-9]{20}$/.test(at) && Date.now() < end) {
        await sleep(100);
        at = await page.evaluate<string>("location.pathname");
      }
      details.path = at;
      if (!/^\/c\/[a-z0-9]{20}$/.test(at)) fail(`Start left the page at ${at}, not the new chat`, "route");
      if (t.booted) {
        const look = variant === "mention" ? messageRef(`${t.booted.seed.folders.kitespan}/README.md`) : text;
        const until = Date.now() + 8000;
        let saw = claudeSaw(t.booted, look) - saw0;
        while (saw < 1 && Date.now() < until) {
          await sleep(100);
          saw = claudeSaw(t.booted, look) - saw0;
        }
        details.claudeSaw = saw;
        if (saw !== 1) fail(`the fake claude saw ${variant === "mention" ? "the README.md reference" : JSON.stringify(text)} ${saw} times, not once`);
      } else warnings.push({ code: "flow", text: "no seed of this run's own (--base): the fake claude's trace was not read" });
      if (variant === "mention") {
        const shown = await untilMention(page, (x) => x.tiles.includes("README.md"), 8000);
        details.tiles = shown.tiles;
        if (!shown.tiles.includes("README.md")) fail("the new chat's first message shows no README.md tile");
      }
      shot = shotName(scene, id, vp, "light");
      await page.screenshot(shot).catch(() => {});
      issueFindings(page.takeIssues(), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = variant === "command" ? "Start with the command chip: one new_chat whose text is the command with its arguments; the chat opens; the fake claude gets it once" : "Start with a mention chip: one new_chat with the mention; the fake claude gets the file's reference once; the message shows the tile";
  return finish({ kind: "flow", name: id, route: "new", scene, size: sizeTag(vp), theme: "light", path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/** A check that nothing acting went out since `from` (draft frames and reads only). */
function noActing(wire: Wire, from: number, when: string, fail: (text: string, code?: string) => void) {
  const a = acting(wire.framesSince(from));
  const http = wire.httpSince(from);
  if (a.length || http.length) fail(`${when} sent ${clipList([...a.map(frameText), ...http.map(httpText)])}`, "click");
}

/** New environment's state in the page (D54): the sheet or dialog, its lines, its rows, and then the form's folder. */
const ENV_STATE = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const name = (r) => (r.querySelector(".scr-pick-name") || r).textContent.trim();
  const rect = (el) => { if (!shown(el)) return null; const b = el.getBoundingClientRect(); return [Math.round(b.top), Math.round(b.bottom)]; };
  const box = [...document.querySelectorAll('[data-testid="dialog-new-environment"]')].find(shown);
  const form = [...document.querySelectorAll('[data-testid="new-chat"]')].find(shown);
  const chip = form ? form.querySelector('[data-pick="project"] .scr-chip-text') : null;
  const greeting = form ? form.querySelector(".scr-greeting") : null;
  const out = { open: !!box, chip: chip ? chip.textContent.trim() : null, greeting: greeting ? greeting.textContent.trim() : null };
  if (!box) return out;
  const rows = [...box.querySelectorAll('[data-testid="env-row"]')].filter(shown);
  const of = (from) => rows.filter((r) => r.getAttribute("data-from") === from).map(name);
  const use = box.querySelector('[data-testid="confirm-use-folder"]');
  const field = box.querySelector('[data-testid="env-filter"]');
  const r = box.getBoundingClientRect();
  return Object.assign(out, {
    sheet: box.classList.contains("sheet"),
    riding: box.classList.contains("is-riding"),
    top: Math.round(r.top),
    height: Math.round(r.height),
    innerHeight: innerHeight,
    visual: Math.round(visualViewport ? visualViewport.height : innerHeight),
    host: shown(box.querySelector('[data-testid="env-host"]')) ? box.querySelector('[data-testid="env-host"]').textContent.trim() : null,
    lines: [...box.querySelectorAll("p")].filter(shown).filter((p) => !p.closest('[data-testid="env-options"]')).map((p) => p.textContent.trim()),
    optionLines: [...box.querySelectorAll('[data-testid="env-options"] p')].filter(shown).map((p) => p.textContent.trim()),
    suggested: of("suggested"),
    browse: of("browse"),
    active: rows.filter((x) => x.getAttribute("aria-selected") === "true").map(name),
    git: rows.filter((x) => shown(x.querySelector(".scr-env-git"))).map(name),
    crumbs: [...box.querySelectorAll('[data-testid="env-crumbs"] li')].filter(shown).map((li) => li.textContent.trim()),
    rowHeights: rows.map((x) => Math.round(x.getBoundingClientRect().height)),
    cancelTop: shown(box.querySelector('[data-testid="sheet-cancel"]')),
    focus: document.activeElement ? document.activeElement.getAttribute("data-testid") : null,
    field: field ? field.value : null,
    fieldBox: rect(field),
    useBox: rect(use),
    cancelBox: rect(box.querySelector('[data-testid="sheet-cancel"]')),
    useShown: shown(use),
    useDisabled: !!use && use.disabled,
    useTitle: use ? use.getAttribute("title") : null,
  });
})())`;

interface EnvState {
  open: boolean;
  chip: string | null;
  greeting: string | null;
  sheet?: boolean;
  riding?: boolean;
  top?: number;
  height?: number;
  innerHeight?: number;
  visual?: number;
  host?: string | null;
  lines?: string[];
  /** Part 2's rows under the finder (row 73, D60): the Worktree option's one line while it is off, if any. */
  optionLines?: string[];
  suggested?: string[];
  browse?: string[];
  active?: string[];
  git?: string[];
  crumbs?: string[];
  rowHeights?: number[];
  cancelTop?: boolean;
  focus?: string | null;
  field?: string | null;
  fieldBox?: [number, number] | null;
  useBox?: [number, number] | null;
  cancelBox?: [number, number] | null;
  useShown?: boolean;
  useDisabled?: boolean;
  useTitle?: string | null;
}

/** The names in the new-chat form's folder picker while it is open: kitespan's projects. */
const PICKER_PROJECTS = `[...document.querySelectorAll('[data-testid="form-picker-project"] [role="menuitemradio"] .scr-pick-name')].map((e) => e.textContent.trim())`;

/** The seed's folders that New environment suggests while no project has them: the terminal session's, then the repository. */
const ENV_SUGGESTED = ["website", "infra"];

/**
 * New environment (D54) at 1100x800, 834x1194 and 390x844: the new-chat form's folder chip, then New environment...,
 * opens a dialog (on touch a full-height sheet with Cancel at the top right, 44 px rows and no first focus, so the
 * keyboard stays down) whose one line names the machine by the server's hostname, never the page's address; Suggested
 * lists the seed's session folder and repository that no kitespan project has (the folder picker lists the projects),
 * and Browse the home folder's folders. A filter that matches no row ("zzz") leaves no row and Use this folder off. On
 * touch, with the stand-in keyboard (STAND_IN_KEYBOARD: 336 px on the phone, 400 px on the tablet) up while the field
 * has the focus, the sheet rides it: the field, Use this folder and Cancel end above the keyboard. A tap on code goes
 * in (the breadcrumb / > ~ > code); the filter narrows the rows and highlights the first. The laptop also goes to / by
 * the breadcrumb (Use this folder off there) and back with ~ and Enter, opens website with Enter, types the path
 * ~/code/in (Browse shows ~/code with infra) and clears it, then uses the folder it is in; the phone types "inf" and
 * uses the highlighted row; the tablet types "inf" and closes the sheet with Cancel, which sends nothing. Nothing
 * mutating goes out before Use this folder; then one POST /api/projects, and the form selects the project.
 */
async function newEnvironmentFlow(base: string, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const phone = vp.name === "phone";
  const touch = vp.touch;
  const kbPx = phone ? 336 : 400;
  const want = touch ? { filter: "inf", folder: "infra" } : { filter: "web", folder: "website" };
  const ends: "use" | "cancel" = vp.name === "medium" ? "cancel" : "use";
  const machine = machineName();
  let shot: string | undefined;
  try {
    await withPage(vp, "light", async (page, wire) => {
      if (touch) await page.send("Page.addScriptToEvaluateOnNewDocument", { source: STAND_IN_KEYBOARD });
      const read = async () => JSON.parse(await page.evaluate<string>(ENV_STATE)) as EnvState;
      const until = async (ok: (s: EnvState) => boolean, ms = 4000) => {
        const end = Date.now() + ms;
        let s = await read();
        while (!ok(s) && Date.now() < end) {
          await sleep(100);
          s = await read();
        }
        return s;
      };
      const tap = async (sel: string, what: string) => {
        const at = await page.locate(sel);
        if (!at) failures.push({ code: "shows", text: `no ${what} to press` });
        else if (at.covered) failures.push({ code: "flow", text: `the ${what} is covered by ${at.covered}` });
        if (!at || at.covered) return false;
        await page.press(at.x, at.y);
        await sleep(300);
        return true;
      };
      const keyboard = async (px: number) => {
        await page.evaluate(`window.__standInKeyboard(${px})`);
        await sleep(400);
        await page.settle();
      };
      const back = { key: "Backspace", code: "Backspace", windowsVirtualKeyCode: 8, nativeVirtualKeyCode: 8 };
      const erase = async (n: number) => {
        for (let i = 0; i < n; i++) {
          await page.send("Input.dispatchKeyEvent", { type: "keyDown", ...back });
          await page.send("Input.dispatchKeyEvent", { type: "keyUp", ...back });
        }
      };
      // The field, Use this folder and the top-right Cancel between the screen's top and the keyboard's.
      const aboveKeyboard = (s: EnvState, step: string) => {
        const parts: [string, [number, number] | null | undefined][] = [["the filter field", s.fieldBox], ["Use this folder", s.useBox], ["Cancel", s.cancelBox]];
        for (const [what, b] of parts) {
          if (!b) failures.push({ code: "shows", text: `${step}: ${what} does not show` });
          else if (b[1] > (s.visual ?? 0) + 1) failures.push({ code: "keyboard", text: `${step}: ${what} ends at ${b[1]} px, under the keyboard that starts at ${s.visual} px` });
          else if (b[0] < 0) failures.push({ code: "keyboard", text: `${step}: ${what} starts above the screen (${b[0]} px)` });
        }
        if (!s.riding) failures.push({ code: "keyboard", text: `${step}: the sheet does not ride the keyboard` });
      };
      // A Browse row by its name: marked in the page for one press (rows carry no name attribute of their own).
      const row = async (name: string) => {
        const found = await page.evaluate<boolean>(`(() => {
          const rows = [...document.querySelectorAll('[data-testid="dialog-new-environment"] [data-testid="env-row"]')];
          for (const r of rows) r.removeAttribute("data-check");
          const r = rows.find((x) => x.getAttribute("data-from") === "browse" && (x.querySelector(".scr-pick-name") || x).textContent.trim() === ${JSON.stringify(name)});
          if (r) r.setAttribute("data-check", "row");
          return !!r;
        })()`);
        return found ? '[data-check="row"]' : `[data-testid="env-row"][data-missing="${name}"]`;
      };
      await page.navigate(base + "/");
      await waitShown(page, ["new-chat"]);
      page.takeIssues();
      const since = wire.mark();

      if (!(await tap('[data-testid="new-chat"] [data-pick="project"]', "folder chip"))) return;
      // Suggested leaves out the folders that kitespan's projects have: the picker lists those (an earlier size may
      // have added one of the seed's folders).
      const projects = await page.evaluate<string[]>(PICKER_PROJECTS);
      details.projects = projects;
      if (!projects.includes("kitespan")) failures.push({ code: "shows", text: `the folder picker lists ${JSON.stringify(projects)}, without the seed's kitespan` });
      const expected = ENV_SUGGESTED.filter((n) => !projects.includes(n));
      if (!(await tap('[data-testid="form-new-environment"]', "New environment... row in the folder picker"))) return;
      const opened = await until((s) => s.open && (s.browse?.length ?? 0) > 0 && (s.suggested?.length ?? 0) >= expected.length);
      details.opened = opened;
      if (!opened.open) {
        failures.push({ code: "shows", text: "New environment does not open" });
        return;
      }
      shot = shotName(scene, "new-environment", vp, "light", "open");
      await page.screenshot(shot).catch(() => {});
      // One line names the machine by the server's hostname; no other line (principle 0).
      if (!machine) warnings.push({ code: "flow", text: "this host gives no name to show, so the line is not checked" });
      else if (opened.host !== `On ${machine}`) failures.push({ code: "flow", text: `the machine's line reads ${JSON.stringify(opened.host)}, not "On ${machine}"` });
      if ((opened.lines ?? []).length !== (machine ? 1 : 0)) failures.push({ code: "flow", text: `the dialog shows the lines ${JSON.stringify(opened.lines)}; expected only the machine's` });
      // Under the finder, part 2's rows: the Worktree option is off for the folder Use this folder takes (Browse starts
      // at the home folder, which is no git repository here), with its one line (W2) once its read answers; no other.
      const optionLines = opened.optionLines ?? [];
      if (optionLines.length > 1 || optionLines.some((l) => l !== "This folder is not a git repository.")) failures.push({ code: "flow", text: `the Worktree and variables rows show the lines ${JSON.stringify(optionLines)}; expected at most the Worktree option's "This folder is not a git repository." for the home folder` });
      if (touch) {
        if (!opened.sheet || (opened.height ?? 0) < 0.85 * (opened.innerHeight ?? vp.height)) failures.push({ code: "flow", text: `the ${vp.name} shows ${opened.sheet ? `a sheet ${opened.height} px tall of ${opened.innerHeight}` : "no sheet"}; expected a full-height sheet` });
        if (!opened.cancelTop) failures.push({ code: "flow", text: `the ${vp.name}'s sheet has no Cancel at the top right` });
        const low = (opened.rowHeights ?? []).filter((h) => h < 44);
        if (low.length) failures.push({ code: "flow", text: `rows under 44 px on the ${vp.name}: ${clipList(low.map(String))}` });
        if (opened.focus === "env-filter") failures.push({ code: "flow", text: `the ${vp.name}'s field takes the focus as the sheet opens, so the keyboard comes up before a tap` });
      } else {
        if (opened.sheet) failures.push({ code: "flow", text: "the laptop shows a sheet, not a dialog" });
        if (opened.focus !== "env-filter") failures.push({ code: "flow", text: `the laptop's focus is on ${opened.focus}, not the filter field` });
      }
      if (JSON.stringify(opened.suggested) !== JSON.stringify(expected)) failures.push({ code: "flow", text: `Suggested lists ${JSON.stringify(opened.suggested)}, not ${JSON.stringify(expected)} (the folders no project has; the folder picker lists the projects)` });
      if (JSON.stringify(opened.browse) !== JSON.stringify(["code", "Documents"])) failures.push({ code: "flow", text: `Browse at the home folder lists ${JSON.stringify(opened.browse)}, not code and Documents` });
      if (JSON.stringify(opened.crumbs) !== JSON.stringify(["/", "~"])) failures.push({ code: "flow", text: `Browse starts at ${JSON.stringify(opened.crumbs)}, not the home folder` });

      // On touch the keyboard comes up with a tap in the field, and the sheet rides it.
      if (touch) {
        if (!(await tap('[data-testid="dialog-new-environment"] [data-testid="env-filter"]', "filter field"))) return;
        await keyboard(kbPx);
        const up = await read();
        details.keyboardUp = up;
        if (up.focus !== "env-filter") failures.push({ code: "flow", text: `a tap in the field put the focus on ${up.focus ?? "nothing"}` });
        aboveKeyboard(up, `keyboard up (${kbPx} px)`);
        await page.screenshot(shotName(scene, "new-environment", vp, "light", "keyboard")).catch(() => {});
      }
      // A filter that matches no row: no row, and Use this folder is off (it never takes the folder behind the filter).
      await page.send("Input.insertText", { text: "zzz" });
      const none = await until((s) => s.field === "zzz" && !(s.browse ?? []).length && !(s.suggested ?? []).length);
      details.noMatch = none;
      if ((none.browse ?? []).length || (none.suggested ?? []).length) failures.push({ code: "flow", text: `"zzz" leaves the rows ${JSON.stringify([...(none.suggested ?? []), ...(none.browse ?? [])])}` });
      if (!none.useDisabled) failures.push({ code: "flow", text: `with "zzz" typed and no row, Use this folder is on and would add ${JSON.stringify(none.useTitle)}` });
      if (touch) aboveKeyboard(none, `"zzz", keyboard up`);
      await erase(3);
      const cleared = await until((s) => s.field === "" && (s.browse ?? []).length === 2);
      if (cleared.field !== "" || JSON.stringify(cleared.browse) !== JSON.stringify(["code", "Documents"])) failures.push({ code: "flow", text: `with "zzz" erased Browse lists ${JSON.stringify(cleared.browse)}` });
      if (cleared.useDisabled) failures.push({ code: "flow", text: "with the field empty again, Use this folder is off at the home folder" });
      if (touch) {
        await keyboard(0);
        const down = await read();
        details.keyboardDown = down;
        if (down.riding) failures.push({ code: "keyboard", text: "keyboard down: the sheet still rides it" });
      } else {
        // The top of the disk is no folder to use: at / Use this folder is off. Then ~ and Enter go home again.
        if (!(await tap('[data-testid="dialog-new-environment"] [data-testid="env-crumbs"] li:first-child button', "/ in the breadcrumb"))) return;
        const top = await until((s) => (s.crumbs ?? []).join(" ") === "/" && (s.browse ?? []).length > 0);
        details.top = { crumbs: top.crumbs, useDisabled: top.useDisabled, useTitle: top.useTitle };
        if ((top.crumbs ?? []).join(" ") !== "/") failures.push({ code: "flow", text: `the breadcrumb's / leaves it at ${JSON.stringify(top.crumbs)}` });
        if (!top.useDisabled) failures.push({ code: "flow", text: `at / Use this folder is on (${JSON.stringify(top.useTitle)})` });
        await page.send("Input.insertText", { text: "~" });
        await page.key("Enter");
        const home = await until((s) => (s.crumbs ?? []).join(" ") === "/ ~" && s.field === "" && (s.browse ?? []).length === 2);
        if ((home.crumbs ?? []).join(" ") !== "/ ~" || home.field !== "") failures.push({ code: "flow", text: `~ and Enter leave the breadcrumb at ${JSON.stringify(home.crumbs)} with ${JSON.stringify(home.field)} in the field` });
      }

      // A tap goes in.
      if (!(await tap(await row("code"), "code row"))) return;
      const inCode = await until((s) => (s.crumbs ?? []).join(" ") === "/ ~ code" && (s.browse ?? []).length === 2);
      details.inCode = inCode;
      if ((inCode.crumbs ?? []).join(" ") !== "/ ~ code") failures.push({ code: "flow", text: `after a tap on code the breadcrumb reads ${JSON.stringify(inCode.crumbs)}` });
      if (JSON.stringify(inCode.browse) !== JSON.stringify(["infra", "website"])) failures.push({ code: "flow", text: `code lists ${JSON.stringify(inCode.browse)}, not infra and website` });
      if ((inCode.suggested ?? []).length) failures.push({ code: "flow", text: "Suggested still shows inside a folder" });
      if (JSON.stringify(inCode.git) !== JSON.stringify(["infra", "website"])) failures.push({ code: "flow", text: `the git marks are on ${JSON.stringify(inCode.git)}` });

      // The filter narrows the rows and highlights the first.
      if (!(await tap('[data-testid="dialog-new-environment"] [data-testid="env-filter"]', "filter field"))) return;
      await page.send("Input.insertText", { text: want.filter });
      const narrowed = await until((s) => JSON.stringify(s.browse) === JSON.stringify([want.folder]));
      details.narrowed = narrowed;
      if (JSON.stringify(narrowed.browse) !== JSON.stringify([want.folder])) failures.push({ code: "flow", text: `"${want.filter}" leaves ${JSON.stringify(narrowed.browse)}, not ${want.folder} alone` });
      if (JSON.stringify(narrowed.active) !== JSON.stringify([want.folder])) failures.push({ code: "flow", text: `with "${want.filter}" typed the highlighted rows are ${JSON.stringify(narrowed.active)}` });
      if (!touch) {
        // Enter opens the highlighted folder; Use this folder then takes the folder Browse is in.
        await page.key("Enter");
        const inside = await until((s) => (s.crumbs ?? []).join(" ") === `/ ~ code ${want.folder}`);
        details.inside = inside;
        if ((inside.crumbs ?? []).join(" ") !== `/ ~ code ${want.folder}`) failures.push({ code: "flow", text: `Enter on ${want.folder} leaves the breadcrumb at ${JSON.stringify(inside.crumbs)}` });
        if (inside.field !== "") failures.push({ code: "flow", text: `the field still holds ${JSON.stringify(inside.field)} inside the folder` });
        // A typed path browses there as it is typed: its folder listed, the rest narrowing it; cleared, back in website.
        const typed = "~/code/in";
        await page.send("Input.insertText", { text: typed });
        const there = await until((s) => (s.crumbs ?? []).join(" ") === "/ ~ code" && JSON.stringify(s.browse) === JSON.stringify(["infra"]));
        details.typed = there;
        if ((there.crumbs ?? []).join(" ") !== "/ ~ code" || JSON.stringify(there.browse) !== JSON.stringify(["infra"])) failures.push({ code: "flow", text: `"${typed}" shows ${JSON.stringify(there.crumbs)} with ${JSON.stringify(there.browse)}, not ~/code with infra` });
        await erase(typed.length);
        const empty = await until((s) => s.field === "" && (s.crumbs ?? []).join(" ") === `/ ~ code ${want.folder}`);
        if (empty.field !== "" || (empty.crumbs ?? []).join(" ") !== `/ ~ code ${want.folder}`) failures.push({ code: "flow", text: `with the field cleared Browse shows ${JSON.stringify(empty.crumbs)}, not ${want.folder} again` });
      }
      await page.screenshot(shotName(scene, "new-environment", vp, "light", "picked")).catch(() => {});
      issueFindings(page.takeIssues(), failures);
      quietFindings(wire, since, await recorder(page), failures, "before Use this folder: ");

      const mark = wire.mark();
      if (ends === "cancel") {
        // The sheet's Cancel at the top right closes it and sends nothing.
        if (!(await tap('[data-testid="dialog-new-environment"] [data-testid="sheet-cancel"]', "sheet's Cancel"))) return;
        const closed = await until((s) => !s.open);
        details.closed = closed;
        if (closed.open) failures.push({ code: "flow", text: "Cancel left the sheet open" });
        await page.settle();
        quietFindings(wire, mark, await recorder(page), failures, "Cancel: ");
        issueFindings(page.takeIssues(), failures);
        return;
      }
      // The one click that acts.
      if (!(await tap('[data-testid="dialog-new-environment"] [data-testid="confirm-use-folder"]', "Use this folder button"))) return;
      const done = await until((s) => !s.open && s.chip === want.folder);
      details.done = done;
      await page.settle();
      if (done.open) failures.push({ code: "flow", text: "Use this folder left the dialog open" });
      if (done.chip !== want.folder) failures.push({ code: "flow", text: `the form's folder is ${JSON.stringify(done.chip)}, not the new project ${want.folder}` });
      if (done.greeting !== `What should we work on in ${want.folder}?`) failures.push({ code: "flow", text: `the greeting reads ${JSON.stringify(done.greeting)}` });
      const posts = wire.httpSince(mark);
      details.sent = posts.map(httpText);
      if (posts.length !== 1 || posts[0]!.method !== "POST" || posts[0]!.path !== "/api/projects" || ![200, 201].includes(posts[0]!.status ?? 0)) failures.push({ code: "click", text: `Use this folder sent ${posts.length ? clipList(posts.map(httpText)) : "nothing"}; expected one POST /api/projects` });
      const frames = mutating(wire.framesSince(mark));
      if (frames.length) failures.push({ code: "click", text: `Use this folder also sent ${clipList(frames.map(frameText))}` });
      const rec = await recorder(page);
      if (JSON.stringify(rec) !== JSON.stringify(["POST /api/projects"])) failures.push({ code: "recorder", text: `window.__kitespanFrames holds ${JSON.stringify(rec)}; expected the one POST /api/projects` });
      issueFindings(page.takeIssues(), failures);
      await page.screenshot(shotName(scene, "new-environment", vp, "light", "done")).catch(() => {});
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const keys = touch ? `, the sheet above a ${kbPx} px keyboard` : ", Use this folder off at /";
  const end = ends === "cancel" ? "then Cancel closes the sheet" : `then Use this folder selects ${want.folder}`;
  const note = `the hostname line, Suggested without the projects and Browse, "zzz" with no row and Use this folder off${keys}, a tap into code, "${want.filter}", ${end}; nothing sent before the click`;
  return finish({ kind: "flow", name: "new-environment", route: "home", scene, size: sizeTag(vp), theme: "light", path: "/", failures, warnings, note, shot, ms: Date.now() - t0, details });
}

// ---------------------------------------------------------------------------------------------------------------
// Row 79, smooth text

/**
 * The page's own record for the smooth-text flow, set before the page's scripts on each document of a page: the time
 * and length of each piece of reply text that came on the chat socket (the socket is wrapped for it), and per animation
 * frame the newest reply's shown length, its fading words, whether its Copy shows (its turn ended), whether a fence or
 * a table's separator row shows as text, the chat's distance from its end and its scroll; and each user message as it
 * came into the column, with its classes and its animation. W19e adds, per frame, over the reply's last top blocks: the
 * characters whose fade went back (a word that showed and then faded in again: its span's fade restarted, or plain
 * text went back into a span), the elements with parts of their own (a list item, an inline code pill, a quote) drawn
 * with no text that shows yet (all of it in spans less than 50 ms into their fade) while they do not fade in whole, and
 * whether a half-parsed mark (a backtick, "](" or "**") shows in the text outside code. S1: each frame's sample is read
 * in a task after that frame's rendering, with one getAnimations(), so the sampler forces no style or layout of its
 * own (at the frame's start it added 0.7 to 1.2 ms per frame of its own). Its script still runs in every frame, so the
 * cost figures below are the page's plus about 0.2 to 0.4 ms per frame of the sampler's own. And each sample reads the
 * frame that was just drawn, not the next frame's start, so worstLagMs reads about one frame (15 ms) lower than before
 * S1 for the same page.
 */
const REVEAL_SAMPLER = `(() => {
  if (window.__rv) return true;
  const rv = (window.__rv = { frames: [], deltas: [], users: [], lastUser: null });
  const Real = window.WebSocket;
  if (Real && !Real.__rv) {
    const Wrapped = function (url, protocols) {
      const ws = protocols === undefined ? new Real(url) : new Real(url, protocols);
      ws.addEventListener("message", (e) => {
        if (typeof e.data !== "string" || e.data.indexOf('"block_delta"') < 0) return;
        try {
          const f = JSON.parse(e.data);
          if (f.t === "ev" && f.e && f.e.k === "block_delta") rv.deltas.push({ t: performance.now(), n: f.e.text.length });
        } catch (err) {}
      });
      return ws;
    };
    Wrapped.prototype = Real.prototype;
    for (const k of ["CONNECTING", "OPEN", "CLOSING", "CLOSED"]) Wrapped[k] = Real[k];
    Wrapped.__rv = true;
    window.WebSocket = Wrapped;
  }
  const fence = String.fromCharCode(96, 96, 96);
  const tick = String.fromCharCode(96);
  const sep = new RegExp("[|] *-{3}");
  const FADE = 160;
  let seen = { md: null, spans: new Map(), lens: new Map() };
  // Each fading span's animation, from one getAnimations() per sample (taken after the frame's own style update, so
  // it finds the style clean and flushes nothing). A play that is still pending has not started: 0 ms into its fade.
  let anims = null;
  const animOf = (sp) => {
    if (!anims) {
      anims = new Map();
      for (const a of document.getAnimations()) {
        const fx = a.effect;
        if (fx && fx.target && !fx.pseudoElement && !anims.has(fx.target)) anims.set(fx.target, a);
      }
    }
    return anims.get(sp) || null;
  };
  const inkOf = (sp) => {
    const a = animOf(sp);
    const t = a ? (typeof a.currentTime === "number" ? a.currentTime : a.pending ? 0 : FADE) : FADE;
    return Math.min(1, t / FADE);
  };
  /** The reply's live end: its last top blocks, and the spans of each with where they start in its text. */
  const look = (md) => {
    const tops = [];
    for (let el = md.lastElementChild; el && tops.length < 4; el = el.previousElementSibling) if (el.hasAttribute("data-b")) tops.unshift(el);
    const lens = new Map();
    const spans = new Map();
    let restarts = 0;
    let empty = 0;
    let prose = "";
    for (const b of tops) {
      const bi = b.getAttribute("data-b");
      const walk = document.createTreeWalker(b, NodeFilter.SHOW_TEXT);
      let off = 0;
      const startOf = new Map();
      for (let n = walk.nextNode(); n; n = walk.nextNode()) {
        const parent = n.parentElement;
        const sp = parent ? parent.closest(".chat-word-in") : null;
        if (sp && !startOf.has(sp)) startOf.set(sp, off);
        if (parent && !parent.closest("pre, code")) prose += n.data;
        off += n.length;
      }
      lens.set(bi, off);
      const list = [];
      for (const [sp, at] of startOf) list.push({ s: at, e: at + (sp.textContent || "").length, p: inkOf(sp) });
      spans.set(bi, list);
      for (const el of b.querySelectorAll("li, code, blockquote")) {
        if (el.closest("pre") || el.closest(".chat-block-in")) continue;
        let shown = "";
        const w = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
        for (let n = w.nextNode(); n; n = w.nextNode()) {
          const sp = n.parentElement ? n.parentElement.closest(".chat-word-in") : null;
          if (!sp || !el.contains(sp) || inkOf(sp) * FADE >= 50) shown += n.data;
        }
        if (!shown.trim()) empty++;
      }
    }
    if (seen.md === md)
      for (const [bi, list] of spans) {
        const had = seen.lens.get(bi);
        if (had === undefined) continue;
        const before = seen.spans.get(bi) || [];
        for (const c of list)
          for (let i = c.s; i < Math.min(c.e, had); i++) {
            const was = before.find((x) => x.s <= i && i < x.e);
            if (c.p < (was ? was.p : 1) - 0.05) restarts++;
          }
      }
    seen = { md, spans, lens };
    return { restarts, empty, half: prose.indexOf(tick) >= 0 || prose.indexOf("](") >= 0 || prose.indexOf("**") >= 0 };
  };
  // The conversation's replies and messages: their count and the last of each, counted again only when one came, went,
  // moved or changed its class (a MutationObserver on the conversation says so), not by a walk of the whole transcript
  // every frame; and the reply's fading words as a live list of its own.
  let conv = null;
  let mo = null;
  let dirty = true;
  let replies = { n: 0, last: null };
  let messages = { n: 0, last: null };
  let words = null;
  let wordsOf = null;
  const ROWS = ".chat-assistant, .chat-user";
  const holds = (n) => n.nodeType === 1 && (n.matches(ROWS) || !!n.querySelector(ROWS));
  const was = (v) => typeof v === "string" && v.split(" ").some((c) => c === "chat-assistant" || c === "chat-user");
  const listOf = (c, cls) => {
    const l = c ? c.getElementsByClassName(cls) : [];
    return { n: l.length, last: l.length ? l[l.length - 1] : null };
  };
  const sample = () => {
    anims = null;
    const c = document.querySelector('[data-testid="conversation"]');
    if (c !== conv) {
      conv = c;
      dirty = true;
      if (mo) mo.disconnect();
      mo = null;
      if (c) {
        mo = new MutationObserver((list) => {
          if (dirty) return;
          for (const r of list) {
            if (r.type === "attributes") {
              if (was(r.oldValue) || r.target.matches(ROWS)) dirty = true;
            } else {
              for (const n of r.addedNodes) if (holds(n)) dirty = true;
              for (const n of r.removedNodes) if (holds(n)) dirty = true;
            }
            if (dirty) return;
          }
        });
        mo.observe(c, { childList: true, subtree: true, attributes: true, attributeFilter: ["class"], attributeOldValue: true });
      }
    }
    if (dirty) {
      dirty = false;
      replies = listOf(conv, "chat-assistant");
      messages = listOf(conv, "chat-user");
    }
    const last = replies.last;
    const md = last ? last.querySelector(".chat-md") : null;
    if (md !== wordsOf) {
      wordsOf = md;
      words = md ? md.getElementsByClassName("chat-word-in") : null;
    }
    const text = md ? md.textContent || "" : "";
    const sc = conv ? conv.querySelector(".chat-scroll") : null;
    const lu = messages.last;
    const now = performance.now();
    const live = md ? look(md) : { restarts: 0, empty: 0, half: false };
    if (lu && lu !== rv.lastUser) {
      rv.lastUser = lu;
      rv.users.push({ t: now, n: messages.n, cls: lu.className, anim: getComputedStyle(lu).animationName });
    }
    // Jump to latest sits beside the scroller, in its wrap.
    const wrap = sc ? sc.parentElement : null;
    let jump = false;
    if (wrap) for (let el = wrap.firstElementChild; el && !jump; el = el.nextElementSibling) jump = el.classList.contains("chat-jump");
    rv.frames.push({
      t: now,
      rows: replies.n,
      n: text.length,
      words: words ? words.length : 0,
      done: !!(last && last.querySelector('[data-testid="copy-reply"]')),
      bad: text.indexOf(fence) >= 0 || sep.test(text),
      gap: sc ? Math.round(sc.scrollHeight - sc.scrollTop - sc.clientHeight) : -1,
      top: sc ? Math.round(sc.scrollTop) : -1,
      restarts: live.restarts,
      empty: live.empty,
      half: live.half,
      jump,
    });
  };
  // One sample per animation frame, in a task after the frame's rendering: what the frame showed, read with its
  // style and layout already up to date, so the sampler forces none of its own (S1: at the frame's start its
  // getAnimations() and scroll reads ran style and layout once more, and the checks counted that as the page's). Its
  // own script still counts in the cost figures (about 0.2 to 0.4 ms per frame).
  const after = new MessageChannel();
  after.port1.onmessage = sample;
  const step = () => {
    after.port2.postMessage(0);
    requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
  return true;
})()`;

interface RvFrame {
  t: number;
  rows: number;
  n: number;
  words: number;
  done: boolean;
  bad: boolean;
  gap: number;
  top: number;
  /** Characters whose fade went back since the last frame (W19e). */
  restarts: number;
  /** Elements with parts of their own drawn with no text that shows yet, while they do not fade in whole (W19e). */
  empty: number;
  /** A backtick, "](" or "**" shows in the live end's text outside code (W19e). */
  half: boolean;
  /** Jump to latest shows. */
  jump: boolean;
}
interface RvDelta {
  t: number;
  n: number;
}
interface RvUser {
  t: number;
  n: number;
  cls: string;
  anim: string;
}
interface RvMark {
  f: number;
  d: number;
  u: number;
  rows: number;
}
interface RvRun {
  frames: RvFrame[];
  deltas: RvDelta[];
  users: RvUser[];
  /** The newest reply's text at the end. */
  text: string;
  /** The reply's rows before the send. */
  rows0: number;
  /** Main-thread time per animation frame over the run (ms): CDP Performance.getMetrics, from the send to the end. */
  cost: { task: number; script: number; layout: number; style: number };
}

/** The page's record from here on; its first frame after the mark is the first after this call. */
function rvMark(page: Page): Promise<RvMark> {
  return page.evaluate<RvMark>(
    `(() => { const r = window.__rv; const c = document.querySelector('[data-testid="conversation"]'); return { f: r.frames.length, d: r.deltas.length, u: r.users.length, rows: c ? c.querySelectorAll(".chat-assistant").length : 0 }; })()`,
  );
}

async function rvSince(page: Page, m: RvMark): Promise<{ frames: RvFrame[]; deltas: RvDelta[]; users: RvUser[]; text: string }> {
  const raw = await page.evaluate<string>(
    `(() => { const r = window.__rv; const c = document.querySelector('[data-testid="conversation"]'); const mds = c ? c.querySelectorAll(".chat-assistant .chat-md") : []; return JSON.stringify({ frames: r.frames.slice(${m.f}), deltas: r.deltas.slice(${m.d}), users: r.users.slice(${m.u}), text: mds.length ? mds[mds.length - 1].textContent || "" : "" }); })()`,
  );
  return JSON.parse(raw);
}

async function mainThread(page: Page): Promise<Record<string, number>> {
  const r = await page.send<{ metrics: { name: string; value: number }[] }>("Performance.getMetrics");
  return Object.fromEntries(r.metrics.map((x) => [x.name, x.value]));
}

/** Type `prompt` in the example chat's box and send it with Enter (a laptop), then wait for its reply's turn to end. */
async function streamReply(page: Page, prompt: string, timeoutMs = 60_000): Promise<RvRun> {
  await page.send("Performance.enable", {});
  const m = await rvMark(page);
  const before = await mainThread(page);
  await page.evaluate(`(() => { const f = ${FIELD}; if (f) f.focus(); return !!f; })()`);
  await page.send("Input.insertText", { text: prompt });
  await sleep(150);
  await keyCode(page, "Enter", 13, { text: "\r" });
  const end = Date.now() + timeoutMs;
  for (;;) {
    const s = await page.evaluate<{ rows: number; done: boolean }>(`(() => { const f = window.__rv.frames; const l = f[f.length - 1]; return l ? { rows: l.rows, done: l.done } : { rows: 0, done: false }; })()`);
    if (s.rows > m.rows && s.done) break;
    if (Date.now() > end) throw new Error(`the reply to "${prompt}" did not end in ${timeoutMs / 1000} s`);
    await sleep(200);
  }
  // The last words' fade.
  await sleep(700);
  const after = await mainThread(page);
  const got = await rvSince(page, m);
  const per = (k: string) => Math.round((((after[k] ?? 0) - (before[k] ?? 0)) * 1000 * 100) / Math.max(1, got.frames.length)) / 100;
  return { ...got, rows0: m.rows, cost: { task: per("TaskDuration"), script: per("ScriptDuration"), layout: per("LayoutDuration"), style: per("RecalcStyleDuration") } };
}

/** The reply's frames: from the first that shows its text to the first after its turn ended (its Copy shows). */
function replySpan(run: Pick<RvRun, "frames" | "rows0">): { start: number; end: number } {
  const start = run.frames.findIndex((f) => f.rows > run.rows0 && f.n > 0);
  const end = run.frames.findIndex((f, i) => i >= start && f.rows > run.rows0 && f.done);
  return { start, end: end < 0 ? run.frames.length : end };
}

/**
 * What shows of the reply with no reveal once `chars` characters of its markdown came, from the reference run (system
 * Reduce motion: the page draws each piece as it comes): per piece, the shown length in the last frame before the next.
 */
function shownAfter(ref: RvRun): { chars: number; shown: number }[] {
  const out: { chars: number; shown: number }[] = [];
  const { end } = replySpan(ref);
  const endT = ref.frames[Math.min(end, ref.frames.length - 1)]?.t ?? Infinity;
  let chars = 0;
  ref.deltas.forEach((d, k) => {
    chars += d.n;
    const next = ref.deltas[k + 1]?.t ?? endT;
    const inside = ref.frames.filter((f) => f.t > d.t && f.t <= next && f.rows > ref.rows0);
    const f = inside[inside.length - 1] ?? ref.frames.find((x) => x.t > d.t && x.rows > ref.rows0);
    if (f) out.push({ chars, shown: f.n });
  });
  return out;
}

/** The reference's shown length once `chars` characters came (0 before the first piece). */
function shownAt(map: { chars: number; shown: number }[], chars: number): number {
  let n = 0;
  for (const e of map) if (e.chars <= chars) n = e.shown;
  return n;
}

/** The characters of markdown that had come by time `t` in a run. */
const cameBy = (deltas: RvDelta[], t: number) => deltas.reduce((a, d) => (d.t <= t ? a + d.n : a), 0);

const quantile = (xs: number[], p: number) => {
  const s = [...xs].sort((a, b) => a - b);
  return s.length ? s[Math.min(s.length - 1, Math.floor(p * s.length))]! : 0;
};

/** The pace of a run while its reply streams (after its first 300 ms, until its last piece): growth per frame. */
function paceOf(run: RvRun) {
  const { start } = replySpan(run);
  const t0 = (run.frames[start]?.t ?? 0) + 300;
  const t1 = run.deltas[run.deltas.length - 1]?.t ?? 0;
  const steps: number[] = [];
  for (let i = Math.max(1, start); i < run.frames.length; i++) {
    const f = run.frames[i]!;
    if (f.t < t0 || f.t > t1) continue;
    steps.push(f.n - run.frames[i - 1]!.n);
  }
  const zero = steps.filter((s) => s === 0).length;
  return { frames: steps.length, still: steps.length ? Math.round((zero / steps.length) * 100) / 100 : 0, median: quantile(steps, 0.5), p95: quantile(steps, 0.95), max: steps.length ? Math.max(...steps) : 0 };
}

/**
 * How far behind what came a run's reply was, at its worst frame while it streamed (ms): at each frame, the oldest
 * piece whose text does not show yet (by the reference) came this long ago.
 */
function worstLag(run: RvRun, map: { chars: number; shown: number }[]): { ms: number; at: number } {
  const { start, end } = replySpan(run);
  let worst = { ms: 0, at: -1 };
  let chars = 0;
  // What the reference showed once each piece of this run had come.
  const need = run.deltas.map((d) => shownAt(map, (chars += d.n)));
  for (let i = start; i >= 0 && i < end; i++) {
    const f = run.frames[i]!;
    // The oldest piece that came whose text does not show yet (40 characters of room: whole words, a held row).
    const k = need.findIndex((n, j) => run.deltas[j]!.t <= f.t && n > f.n + 40);
    if (k < 0) continue;
    const ms = Math.round(f.t - run.deltas[k]!.t);
    if (ms > worst.ms) worst = { ms, at: i };
  }
  return worst;
}

/**
 * Row 79 at the laptop size, on the example chat, with the fake claude's paced stream (a 20,000-character markdown
 * reply in 160 pieces, 80 ms apart): first with the system's Reduce motion (the page draws each piece as it comes, so
 * this run is the reference), then without it, with a second page on the chat. Then:
 * - the pace: the reveal grows on nearly every frame while the reply streams (the reference stands still between
 *   pieces), with no frame that jumps far past the rest; it is never more than about half a second behind what came;
 *   words fade in while it streams (.chat-word-in), and none is left fading after the end;
 * - the end: the reply shows whole at its turn's end, the same text as the reference's; no fence or table separator
 *   ever shows as text; the chat follows the end (within 90 px of it) and its scroll never moves back;
 * - the user's message enters with its fade and rise (chat-rise) on this page and, live, on the second page; under
 *   Reduce motion it has no animation;
 * - a load shows at once: the second page reloads in the middle of the stream and shows what came with no fading word,
 *   and this page reloads after the end and shows the whole reply at once;
 * - no word fades in twice (no fade goes back, frame to frame), no list item, code pill or quote shows ahead of its
 *   text, and no half-parsed mark (a backtick, "](" or "**") shows outside code, in every run (W19e);
 * - a stream that pauses (4,000 characters in 10 pieces 900 ms apart): what shows only grows, and the scroll never
 *   moves back (W19e);
 * - a finger's drag up the column while a reply reveals (390x844, touch: 300 px in steps of 60 px a frame apart): the
 *   view stays where the finger took it, Jump to latest shows, and the end does not pull it back (W19e);
 * - Settings > Appearance > Reduce motion On (a third page, this device's setting): a short paced reply shows with no
 *   fading word, and the message has no animation;
 * - the cost: the main thread's time per animation frame over each run (CDP Performance.getMetrics), reported, with a
 *   warning above 4 ms.
 */
async function smoothTextFlow(t: Target, scene: SceneName | null, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const chat = `/c/${EX.chat}`;
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  const BIG = pacedPrompt(20000, 160, 80);
  const SMALL = pacedPrompt(4000, 40, 60);
  // W19e: a stream that pauses, and a reply long enough to drag in.
  const PAUSED = pacedPrompt(4000, 10, 900);
  const DRAG = pacedPrompt(8000, 64, 80);
  let shot: string | undefined;
  const open = async (page: Page, reduce: "system" | "settings" | null) => {
    if (reduce === "settings")
      await page.send("Page.addScriptToEvaluateOnNewDocument", {
        source: `try { const k = "kitespan.settings"; const s = JSON.parse(localStorage.getItem(k) || "{}"); s.reduceMotion = "on"; localStorage.setItem(k, JSON.stringify(s)); } catch (e) {}`,
      });
    await page.send("Page.addScriptToEvaluateOnNewDocument", { source: REVEAL_SAMPLER });
    if (reduce === "system") await page.send("Emulation.setEmulatedMedia", { media: "screen", features: [{ name: "prefers-color-scheme", value: page.theme }, { name: "prefers-reduced-motion", value: "reduce" }] });
    await page.navigate(t.base + chat);
    await waitShown(page, ["chat", "composer"]);
    await sleep(400);
    const box = await emptyBox(page);
    if (box.mode !== "chat" || box.value !== "" || box.chips.length) throw new Error(`could not empty the message box: ${JSON.stringify(box)}`);
    page.takeIssues();
  };
  const common = (run: RvRun, label: string, grows = false) => {
    const { start, end } = replySpan(run);
    if (start < 0) return fail(`${label}: the reply never showed`);
    const during = run.frames.slice(start, end);
    if (during.some((f) => f.bad)) fail(`${label}: a fence or a table's separator row showed as text while the reply streamed`);
    const far = Math.max(0, ...during.map((f) => f.gap));
    let back = 0;
    for (let i = 1; i < during.length; i++) back = Math.max(back, during[i - 1]!.top - during[i]!.top);
    const off = during.findIndex((f) => f.gap > 90);
    const around = off < 0 ? [] : during.slice(Math.max(0, off - 3), off + 3).map((f) => ({ t: Math.round(f.t), n: f.n, gap: f.gap, top: f.top }));
    details[`${label}Scroll`] = { farFromEnd: far, movedBack: back, ...(off < 0 ? {} : { firstFar: off, around, startGap: during[0]?.gap }) };
    if (far > 90) fail(`${label}: the chat did not follow the end while the reply streamed (${far} px from it)`);
    if (back > 2) fail(`${label}: the chat's scroll moved back by ${back} px while the reply streamed`);
    form(run, label, grows);
  };
  /** W19e: no fade goes back, no element shows ahead of its text, no half-parsed mark shows; and, for a run that asks, what shows only grows. */
  const form = (run: RvRun, label: string, grows = false) => {
    const { start, end } = replySpan(run);
    if (start < 0) return;
    const during = run.frames.slice(start, Math.min(run.frames.length, end + 1));
    const restarts = during.reduce((a, f) => a + (f.restarts ?? 0), 0);
    const empty = during.filter((f) => (f.empty ?? 0) > 0).length;
    const half = during.filter((f) => f.half).length;
    let shrank = 0;
    for (let i = 1; i < during.length; i++) if (during[i]!.n < during[i - 1]!.n) shrank++;
    details[`${label}Form`] = { restarts, emptyFrames: empty, halfFrames: half, ...(grows ? { shrank } : {}) };
    if (restarts > 0) fail(`${label}: ${restarts} characters faded in again after they showed (a span's fade restarted)`);
    if (empty > 0) fail(`${label}: on ${empty} frames a list item, a code pill or a quote showed with no text that shows yet`);
    if (half > 0) fail(`${label}: on ${half} frames a backtick, "](" or "**" showed in the text outside code`);
    if (grows && shrank > 0) fail(`${label}: the text that shows got shorter ${shrank} times while the reply streamed`);
  };
  try {
    // 1. The reference: the system's Reduce motion.
    const ref = await withPage(vp, "dark", async (page) => {
      await open(page, "system");
      const run = await streamReply(page, BIG);
      issueFindings(page.takeIssues(), failures, "reduce motion (system): ");
      return run;
    });
    const map = shownAfter(ref);
    const refPace = paceOf(ref);
    details.reference = { pieces: ref.deltas.length, shown: ref.text.length, pace: refPace, cost: ref.cost, user: ref.users.at(-1) };
    common(ref, "reduce motion (system)");
    if (ref.frames.some((f) => f.words > 0)) fail("reduce motion (system): a word faded in");
    if (ref.users.at(-1)?.anim !== "none") fail(`reduce motion (system): the sent message has the animation ${JSON.stringify(ref.users.at(-1)?.anim)}`);
    if (ref.deltas.length < 100 || ref.text.length < 15000) throw new Error(`the paced stream did not come as asked: ${ref.deltas.length} pieces, ${ref.text.length} characters shown`);

    // 2. The reveal, with a second page on the chat that reloads in the middle of the stream.
    await withPage(vp, "dark", async (page) => {
      await open(page, null);
      await withPage(vp, "dark", async (other) => {
        await open(other, null);
        const o = await rvMark(other);
        const running = streamReply(page, BIG);
        // The second page sees the message come live, then reloads with the reply half there.
        const until = Date.now() + 15_000;
        let half = false;
        while (Date.now() < until) {
          const l = await other.evaluate<{ rows: number; n: number }>(`(() => { const f = window.__rv.frames; return f.length ? { rows: f[f.length - 1].rows, n: f[f.length - 1].n } : { rows: 0, n: 0 }; })()`);
          if (l.rows > o.rows && l.n > ref.text.length * 0.35) {
            half = true;
            break;
          }
          await sleep(100);
        }
        const live = await rvSince(other, o);
        details.otherLiveUser = live.users.at(-1);
        if (!live.users.at(-1)?.cls.includes("is-entering")) fail(`the second page: the message that came live did not enter (${JSON.stringify(live.users.at(-1))})`);
        if (!half) fail("the second page never showed a third of the reply");
        const reloadAt = Date.now();
        await other.send("Page.reload", {});
        // The new document's record: wait for its reply to show.
        let first: { frames: RvFrame[]; deltas: RvDelta[]; users: RvUser[] } | null = null;
        while (Date.now() - reloadAt < 10_000) {
          await sleep(150);
          const s = await other.evaluate<string>(`(() => { const r = window.__rv; if (!r) return ""; const f = r.frames; return f.length && f[f.length - 1].rows > ${o.rows} && f[f.length - 1].n > 0 ? "yes" : ""; })()`).catch(() => "");
          if (s) {
            await sleep(300);
            first = JSON.parse(await other.evaluate<string>(`JSON.stringify({ frames: window.__rv.frames, deltas: window.__rv.deltas, users: window.__rv.users })`));
            break;
          }
        }
        if (!first) fail("the second page: after its reload the reply did not show");
        else {
          const i = first.frames.findIndex((f) => f.rows > o.rows && f.n > 0);
          const f = first.frames[i]!;
          const came = cameBy(first.deltas, f.t);
          const want = shownAt(map, came);
          const soon = first.frames.filter((x) => x.t >= f.t && x.t <= f.t + 300);
          details.otherReload = { firstShown: f.n, cameChars: came, referenceShown: want, fadingSoon: Math.max(0, ...soon.map((x) => x.words)), users: first.users.map((u) => u.cls) };
          if (soon.some((x) => x.words > 0)) fail("the second page: after its reload, words faded in (a load shows at once)");
          if (f.n < want - 60) fail(`the second page: after its reload it first showed ${f.n} characters of the ${want} that came (a load shows at once)`);
          if (first.users.some((u) => u.cls.includes("is-entering"))) fail("the second page: after its reload a message entered (a load shows at once)");
        }
        issueFindings(other.takeIssues(), failures, "the second page: ");
        const run = await running;
        const pace = paceOf(run);
        const lag = worstLag(run, map);
        const fading = Math.max(0, ...run.frames.map((x) => x.words));
        details.reveal = { pieces: run.deltas.length, shown: run.text.length, pace, worstLagMs: lag.ms, fadingWordsAtMost: fading, cost: run.cost, user: run.users.at(-1) };
        common(run, "reveal");
        if (run.deltas.length !== ref.deltas.length) warnings.push({ code: "flow", text: `the reveal's stream came in ${run.deltas.length} pieces, the reference's in ${ref.deltas.length}` });
        if (pace.still > 0.35) fail(`reveal: the reply stood still on ${Math.round(pace.still * 100)}% of the frames while it streamed (the reference: ${Math.round(refPace.still * 100)}%)`);
        if (pace.p95 > Math.max(3 * pace.median, pace.median + 60)) fail(`reveal: uneven: the 95th percentile frame grew by ${pace.p95} characters, the median by ${pace.median}`);
        if (lag.ms > 600) fail(`reveal: it fell ${lag.ms} ms behind what came (frame ${lag.at}); at most about 500 ms`);
        if (fading === 0) fail("reveal: no word faded in while the reply streamed");
        if ((run.frames.at(-1)?.words ?? 0) > 0) fail("reveal: words still fade after the end");
        if (run.text !== ref.text) fail(`reveal: the reply at its end is not the reference's (${run.text.length} and ${ref.text.length} characters)`);
        const u = run.users.at(-1);
        if (!u?.cls.includes("is-entering") || u.anim !== "chat-rise") fail(`reveal: the sent message did not fade and rise in (${JSON.stringify(u)})`);
      });
      shot = shotName(scene, "smooth-text", vp, "dark", "end");
      await page.screenshot(shot).catch(() => {});
      // A reload after the end: the whole reply at once (the new document's own record).
      await page.send("Page.reload", {});
      await sleep(2500);
      const after = JSON.parse(await page.evaluate<string>(`JSON.stringify({ frames: window.__rv.frames, users: window.__rv.users })`)) as { frames: RvFrame[]; users: RvUser[] };
      const shownFrames = after.frames.filter((f) => f.n > 0);
      const firstN = shownFrames[0]?.n ?? 0;
      details.reload = { firstShown: firstN, final: ref.text.length, fading: Math.max(0, ...after.frames.map((f) => f.words)) };
      if (firstN !== ref.text.length) fail(`after a reload the reply first showed ${firstN} characters, not all ${ref.text.length} at once`);
      if (after.frames.some((f) => f.words > 0)) fail("after a reload, words faded in");
      if (after.users.some((x) => x.cls.includes("is-entering"))) fail("after a reload, a message entered");
      issueFindings(page.takeIssues(), failures, "reveal: ");
    });

    // 2b. A stream that pauses (W19e): the reveal catches up with what came at each pause, and the live end waits.
    await withPage(vp, "dark", async (page) => {
      await open(page, null);
      const run = await streamReply(page, PAUSED);
      details.paused = { pieces: run.deltas.length, shown: run.text.length };
      common(run, "paused", true);
      if (run.deltas.length < 5) fail(`paused: the stream came in ${run.deltas.length} pieces`);
      issueFindings(page.takeIssues(), failures, "paused: ");
    });

    // 2c. A finger's drag up the column while a reply reveals (W19e), on the phone.
    const phone = VIEWPORTS.find((v) => v.name === "phone");
    if (phone && SIZES.includes("phone"))
      await withPage(phone, "dark", async (page) => {
        await open(page, null);
        const m = await rvMark(page);
        const running = streamReply(page, DRAG);
        // 1.8 s into the reply.
        const until = Date.now() + 15_000;
        let started = 0;
        while (Date.now() < until) {
          const l = await page.evaluate<{ rows: number; n: number }>(`(() => { const f = window.__rv.frames; return f.length ? { rows: f[f.length - 1].rows, n: f[f.length - 1].n } : { rows: 0, n: 0 }; })()`);
          if (l.rows > m.rows && l.n > 0) {
            started = Date.now();
            break;
          }
          await sleep(50);
        }
        if (!started) fail("touch drag: the reply never showed");
        else {
          await sleep(Math.max(0, 1800 - (Date.now() - started)));
          const point = (y: number) => [{ x: phone.width / 2, y, radiusX: 4, radiusY: 4, force: 1, id: 1 }];
          const dragAt = await rvMark(page);
          await page.send("Input.dispatchTouchEvent", { type: "touchStart", touchPoints: point(300) });
          for (let y = 360; y <= 600; y += 60) {
            await sleep(16);
            await page.send("Input.dispatchTouchEvent", { type: "touchMove", touchPoints: point(y) });
          }
          await page.send("Input.dispatchTouchEvent", { type: "touchEnd", touchPoints: [] });
          await sleep(1000);
          const after = await rvSince(page, dragAt);
          const gaps = after.frames.map((f) => f.gap);
          const settledGaps = after.frames.filter((f) => f.t >= (after.frames[0]?.t ?? 0) + 250).map((f) => f.gap);
          const least = settledGaps.length ? Math.min(...settledGaps) : 0;
          const jump = after.frames.some((f) => f.jump);
          details.touchDrag = { framesAfter: gaps.length, gapAfter250ms: least, gapAtEnd: gaps.at(-1), jump };
          if (least < 200) fail(`touch drag: the end pulled the view back while the reply revealed (it came within ${least} px of the end)`);
          if (!jump) fail("touch drag: Jump to latest did not show while the view was away from the end");
          await page.screenshot(shotName(scene, "smooth-text", phone, "dark", "drag")).catch(() => {});
        }
        await running;
        issueFindings(page.takeIssues(), failures, "touch drag: ");
      });
    else warnings.push({ code: "flow", text: "touch drag: left out (the phone size is not in --sizes)" });

    // 3. Settings > Appearance > Reduce motion On.
    await withPage(vp, "dark", async (page) => {
      await open(page, "settings");
      const motion = await page.evaluate<string | null>(`document.documentElement.getAttribute("data-motion")`);
      if (motion !== "reduce") fail(`reduce motion (Settings): the page does not wear it (data-motion ${JSON.stringify(motion)})`);
      const run = await streamReply(page, SMALL);
      details.settings = { shown: run.text.length, fading: Math.max(0, ...run.frames.map((f) => f.words)), user: run.users.at(-1), cost: run.cost };
      common(run, "reduce motion (Settings)");
      if (run.frames.some((f) => f.words > 0)) fail("reduce motion (Settings): a word faded in");
      if (run.users.at(-1)?.anim !== "none") fail(`reduce motion (Settings): the sent message has the animation ${JSON.stringify(run.users.at(-1)?.anim)}`);
      if (run.text.length < 3000) fail(`reduce motion (Settings): the reply shows ${run.text.length} characters`);
      issueFindings(page.takeIssues(), failures, "reduce motion (Settings): ");
    });
    const cost = (details.reveal as { cost?: { task: number } } | undefined)?.cost?.task ?? 0;
    if (cost > 4) warnings.push({ code: "cost", text: `the main thread took ${cost} ms per frame while the 20,000-character reply revealed (the reference without the reveal: ${ref.cost.task} ms)` });
  } catch (e) {
    fail(`the check could not run: ${(e as Error).message}`, "run");
  }
  const r = details.reveal as { pace?: { still: number; median: number }; worstLagMs?: number; cost?: { task: number } } | undefined;
  const ref = details.reference as { pace?: { still: number }; cost?: { task: number } } | undefined;
  const note = r?.pace
    ? `a 20,000-character reply revealed with ${Math.round(r.pace.still * 100)}% still frames (the reference without the reveal: ${Math.round((ref?.pace?.still ?? 0) * 100)}%), at most ${r.worstLagMs} ms behind, ${r.cost?.task} ms of main thread per frame (reference ${ref?.cost?.task}); the end whole, the message's fade and rise here and live elsewhere, a load at once, Reduce motion at once`
    : "the smooth-text flow";
  return finish({ kind: "flow", name: "smooth-text", route: "chat", scene, size: sizeTag(vp), theme: "dark", path: chat, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

// ---------------------------------------------------------------------------------------------------------------
// The reconnect and restart flows (build checklist R19, S14 and L2; DESIGN.md 9.4 done checks 3, 4, 5 and 9). Each
// runs on a seed of its own, since it drops the socket, reloads mid-turn, cuts the link or restarts the server.

/** The flows that boot a seed of their own (after the main scene's flows, so they touch no other check's state). */
const OWN_BOOT_FLOWS = new Set<string>(["settings-kept", "offline-send-again", "resume-drop", "resume-reload", "resume-slow", "resume-blackhole", "resume-two-pages", "resume-wake", "resume-tail", "resume-rtt", "restart", "restart-cancel", "restart-now", "end-here", "finishing", "worktree-new", "worktree-gone", "worktree-archive-delete", "env-editor", "worktree-off", "worktree-refused", "env-remove", "env-remove-worktree", "update-setting", "update-check-now", "update-run", "update-refused", "update-install", "update-brew", "send-now", "send-now-key", "unseen-dot", "side-chat", "side-chat-running", "side-draft", "turn-fold", "turn-rail", "trust-folder", "background-session", "notify", "bring-back", "composer-lines", "search-text", "changes-card", "claude-minimum", "send-follow", "browser-pane", "browser-looks", "browser-stop", "browser-cases", "browser-restart", "cut-output", "stream-hold", "stop-menu", "open-on-phone", "browser-select"]);

/** A frame from /ws: its order, when it came, which socket brought it (the browser's request id) and its size. */
type InFrame = { n: number; at: number; f: Record<string, any>; sock: string; bytes: number };

/**
 * What the page got and asked for over the network, from the browser's own events: every frame from /ws in order with
 * the time it came and its socket, the URL of every request and socket it made, and the body of each mutating /api/
 * request. `onFrame` sees each frame as it comes (a flow that acts at a frame, such as a cut right after a snapshot).
 */
class Inbox {
  readonly frames: InFrame[] = [];
  readonly urls: string[] = [];
  /** When the page made each socket to /ws. */
  readonly dialsAt: number[] = [];
  readonly posts: { at: number; method: string; path: string; body: string | null }[] = [];
  onFrame: ((x: InFrame) => void) | null = null;
  private n = 0;
  private readonly sockets = new Map<string, string>();
  private readonly off: () => void;

  constructor(c: Cdp, page: Page) {
    this.off = c.on((e) => {
      if (e.sessionId !== page.session) return;
      const p = e.params ?? {};
      if (e.method === "Network.webSocketCreated") {
        this.urls.push(String(p.url ?? ""));
        try {
          this.sockets.set(p.requestId, new URL(p.url).pathname);
          if (new URL(p.url).pathname === WIRE.path) this.dialsAt.push(Date.now());
        } catch {}
      } else if (e.method === "Network.requestWillBeSent") {
        const url = String(p.request?.url ?? "");
        this.urls.push(url);
        const method = String(p.request?.method ?? "GET").toUpperCase();
        try {
          const path = new URL(url).pathname;
          if (path.startsWith("/api/") && MUTATING_METHODS.has(method)) this.posts.push({ at: Date.now(), method, path, body: p.request?.postData ?? null });
        } catch {}
      } else if (e.method === "Network.webSocketFrameReceived" && this.sockets.get(p.requestId) === WIRE.path && p.response?.opcode === 1) {
        let x: InFrame;
        try {
          const data = String(p.response.payloadData);
          x = { n: ++this.n, at: Date.now(), f: JSON.parse(data) as Record<string, any>, sock: String(p.requestId), bytes: data.length };
        } catch {
          return;
        }
        this.frames.push(x);
        try {
          this.onFrame?.(x);
        } catch {}
      }
    });
  }

  mark(): number {
    return this.n;
  }
  /** The sockets to /ws the page has made so far. */
  wsCount(): number {
    return [...this.sockets.values()].filter((p) => p === WIRE.path).length;
  }
  since(m: number, ok: (f: Record<string, any>) => boolean = () => true): Record<string, any>[] {
    return this.frames.filter((x) => x.n > m && ok(x.f)).map((x) => x.f);
  }
  async waitFor(ok: (f: Record<string, any>) => boolean, ms: number, from = 0): Promise<InFrame | null> {
    const end = Date.now() + ms;
    for (;;) {
      const hit = this.frames.find((x) => x.n > from && ok(x.f));
      if (hit) return hit;
      if (Date.now() > end) return null;
      await sleep(50);
    }
  }
  dispose(): void {
    this.off();
  }
}

/** One chat's page as the reconnect flows judge it (CHAT_LOOK). */
interface ChatLook {
  path: string;
  /** The rows drawn, by item id, in order. */
  rows: string[];
  /** Item ids drawn more than once. */
  dups: string[];
  /** Each of Claude's replies by its item id: its text, spaces folded. */
  texts: Record<string, string>;
  users: { id: string; text: string; queued: boolean; unsent: boolean; foot: string; again: boolean; takeBack: boolean }[];
  /** The waiting cards that show: kind and text. */
  cards: { kind: string; text: string }[];
  /** The message box's text, or null while it does not show (a card waits). */
  field: string | null;
  reconnecting: string | null;
  /** The chat list foot's connection state, where it shows (a laptop). */
  conn: string | null;
  drain: string | null;
  /** Working marks and spinners that show. */
  working: number;
  spin: number;
  /** A line of a turn that a stop cut (D32, 4.10), anywhere in the conversation. */
  stopLine: boolean;
}

const CHAT_LOOK = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const fold = (s) => (s || "").replace(/\\s+/g, " ").trim();
  const conv = document.querySelector('[data-testid="conversation"]');
  const items = conv ? [...conv.querySelectorAll('[data-testid^="item-"]')] : [];
  const idOf = (el) => el.getAttribute("data-testid").slice(5);
  const rows = items.map(idOf);
  const count = new Map();
  for (const id of rows) count.set(id, (count.get(id) || 0) + 1);
  const texts = {};
  for (const el of items) {
    const prose = el.querySelector(".chat-assistant > div:first-child");
    if (prose) texts[idOf(el)] = fold(prose.textContent);
  }
  const users = items.filter((el) => el.querySelector(".chat-user")).map((el) => {
    const u = el.querySelector(".chat-user");
    const b = u.querySelector(".chat-bubble");
    const foot = u.querySelector(".chat-queued");
    return { id: idOf(el), text: fold(b ? b.textContent : ""), queued: u.classList.contains("is-queued"), unsent: u.classList.contains("is-unsent"), foot: fold(foot ? foot.textContent : ""), again: !!u.querySelector('[data-testid="send-again"]'), takeBack: !!u.querySelector('[data-testid="confirm-take-back"]') };
  });
  const cards = [...document.querySelectorAll('section.chat-card[data-testid^="card-"]')].filter(shown).map((el) => ({ kind: el.getAttribute("data-testid").slice(5), text: fold(el.textContent).slice(0, 300) }));
  const box = [...document.querySelectorAll('[data-testid="composer"]')].find(shown);
  const input = box ? box.querySelector('[data-testid="composer-input"]') : null;
  const line = [...document.querySelectorAll('[data-testid="chat-reconnecting"]')].find(shown);
  const conn = [...document.querySelectorAll('[data-testid="connection"]')].find(shown);
  const drain = [...document.querySelectorAll('[data-testid="drain-line"]')].find(shown);
  const said = fold(conv ? conv.textContent : "");
  return {
    path: location.pathname + location.search,
    rows,
    dups: [...count].filter(([, n]) => n > 1).map(([id]) => id),
    texts,
    users,
    cards,
    field: input ? input.value : null,
    reconnecting: line ? fold(line.textContent) : null,
    conn: conn ? conn.getAttribute("data-state") : null,
    drain: drain ? fold(drain.textContent) : null,
    working: [...document.querySelectorAll(".chat-working")].filter(shown).length,
    spin: [...document.querySelectorAll(".chat-spin")].filter(shown).length,
    stopLine: /kitespan (stopped|restarted) (while|during) this (chat|turn)|when kitespan (stopped|restarted)/.test(said),
  };
})())`;

const lookChat = async (page: Page) => JSON.parse(await page.evaluate<string>(CHAT_LOOK)) as ChatLook;

async function untilLook(page: Page, ok: (s: ChatLook) => boolean, ms: number): Promise<{ s: ChatLook; ok: boolean }> {
  const end = Date.now() + ms;
  for (;;) {
    const s = await lookChat(page).catch(() => null);
    if (s && ok(s)) return { s, ok: true };
    if (Date.now() > end) return { s: s ?? (await lookChat(page)), ok: false };
    await sleep(100);
  }
}

async function untilTrue(ok: () => boolean, ms: number): Promise<boolean> {
  const end = Date.now() + ms;
  while (!ok()) {
    if (Date.now() > end) return false;
    await sleep(100);
  }
  return true;
}

const fold = (s: string) => s.replace(/\s+/g, " ").trim();
const SEND_BUTTON = '[data-testid="composer"] [data-testid="composer-send"], [data-testid="composer"] [data-testid="confirm-send"]';

/** Type a message at the end of the chat's box and press Send (a click, or a tap on touch), as a user does. */
async function sendFromBox(page: Page, text: string): Promise<boolean> {
  const ok = await page.evaluate<boolean>(`(() => { const el = ${FIELD}; if (!el) return false; el.focus(); el.setSelectionRange(el.value.length, el.value.length); return true; })()`);
  if (!ok) return false;
  await page.send("Input.insertText", { text });
  await sleep(150);
  const btn = await page.locate(SEND_BUTTON);
  if (!btn) return false;
  await page.press(btn.x, btn.y);
  return true;
}

/** Empty the chat's box (select all, Backspace, blur: a save), so the server keeps no draft for the checks after. */
async function emptyChatBox(page: Page): Promise<string | null> {
  const there = await page.evaluate<boolean>(`(() => { const el = ${FIELD}; if (!el) return false; el.focus(); el.select(); return true; })()`);
  if (!there) return null;
  const key = { key: "Backspace", code: "Backspace", windowsVirtualKeyCode: 8, nativeVirtualKeyCode: 8 };
  await page.send("Input.dispatchKeyEvent", { type: "keyDown", ...key });
  await page.send("Input.dispatchKeyEvent", { type: "keyUp", ...key });
  await page.evaluate(`(() => { const el = ${FIELD}; if (el) el.blur(); return true; })()`);
  await sleep(600);
  return page.evaluate<string | null>(`(() => { const el = ${FIELD}; return el ? el.value : null; })()`);
}

/** Press a shown element by its selector; false when none shows. */
async function pressOn(page: Page, selector: string): Promise<boolean> {
  const at = await page.locate(selector);
  if (!at) return false;
  await page.press(at.x, at.y);
  return true;
}

/** The fake claude asked the SDK about this tool call (its permission card is on its way). */
const fakeAsked = (b: Booted, toolUse: string) => b.trace().some((l) => l.t === "ask" && (l.request as { tool_use_id?: unknown } | undefined)?.tool_use_id === toolUse);

/** In-page: the time each mark first shows (a selector, and the text it must hold); window.__uiSeen. */
const WATCH = (marks: { key: string; sel: string; text?: string }[]) => `(() => {
  const marks = ${JSON.stringify(marks)};
  const seen = (window.__uiSeen = {});
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const fold = (s) => (s || "").replace(/\\s+/g, " ").trim();
  const tick = () => {
    for (const m of marks) {
      if (seen[m.key]) continue;
      const el = [...document.querySelectorAll(m.sel)].find(shown);
      if (el && (m.text === undefined || fold(el.textContent) === m.text)) seen[m.key] = Date.now();
    }
  };
  clearInterval(window.__uiSeenTimer);
  window.__uiSeenTimer = setInterval(tick, 15);
  tick();
  return true;
})()`;
const SEEN = `JSON.stringify(window.__uiSeen || {})`;

/** The restart's lines on the page (web/settings/restart.ts RESTART_WORDS; 4.10). */
const RESTARTING_LINE = "Restarting kitespan...";
const RESTARTED_LINE = "kitespan restarted.";

/** In-page: each change of the restart's lines (the dialog's line, the list foot's state, the chat's line); window.__uiLines. */
const LINE_SAMPLER = `(() => {
  const seen = (window.__uiLines = []);
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const text = (sel) => { const el = [...document.querySelectorAll(sel)].find(shown); return el ? el.textContent.replace(/\\s+/g, " ").trim() : null; };
  let last = "";
  const tick = () => {
    const conn = [...document.querySelectorAll('[data-testid="connection"]')].find(shown);
    const v = JSON.stringify({ dialog: text('[data-testid="restart-line"]'), conn: conn ? conn.getAttribute("data-state") : null, chat: text('[data-testid="chat-reconnecting"]') });
    if (v !== last) { last = v; seen.push({ t: Date.now(), ...JSON.parse(v) }); }
  };
  clearInterval(window.__uiLinesTimer);
  window.__uiLinesTimer = setInterval(tick, 20);
  tick();
  return true;
})()`;
type LineSample = { t: number; dialog: string | null; conn: string | null; chat: string | null };
const LINES = `JSON.stringify(window.__uiLines || [])`;

/** The checks every look of a reconnect flow gets: no row twice, and each named reply whole (no block drawn twice). */
function rowFindings(s: ChatLook, whole: Record<string, string>, when: string, fail: (text: string) => void) {
  if (s.dups.length) fail(`${when}, rows drawn twice: ${clipList(s.dups)}`);
  for (const [id, text] of Object.entries(whole)) {
    const got = s.texts[id];
    if (got === undefined) fail(`${when}, the reply ${id} does not show`);
    else if (got !== fold(text)) fail(`${when}, the reply ${id} reads ${JSON.stringify(clip(got, 120))} (${got.length} characters), not its ${fold(text).length} characters once`);
  }
}

/** A user's message drawn exactly once, by its text. */
function oneUser(s: ChatLook, text: string, when: string, fail: (text: string) => void) {
  const n = s.users.filter((u) => u.text === fold(text)).length;
  if (n !== 1) fail(`${when}, the message ${JSON.stringify(clip(text, 60))} shows ${n} times, not once`);
  return s.users.find((u) => u.text === fold(text)) ?? null;
}

/** No working mark, spinner or reconnect line stays once the chat is idle and the socket is back. */
function quietFindingsAtEnd(s: ChatLook, when: string, fail: (text: string) => void) {
  if (s.working || s.spin) fail(`${when}, ${s.working + s.spin} working mark${s.working + s.spin > 1 ? "s" : ""} or spinner${s.working + s.spin > 1 ? "s" : ""} still show`);
  if (s.reconnecting) fail(`${when}, the chat still says ${JSON.stringify(s.reconnecting)}`);
  if (s.conn && s.conn !== "connected") fail(`${when}, the list's foot is still ${s.conn}`);
  const stuck = s.users.filter((u) => u.unsent || u.queued);
  if (stuck.length) fail(`${when}, ${stuck.length} message${stuck.length > 1 ? "s are" : " is"} still drawn ${stuck.map((u) => (u.unsent ? "not sent yet" : u.foot || "queued")).join(", ")}`);
}

/** The messages that the fake claude ran, in the order it ran them (each by the first turn it started for it). */
function claudeRanOrder(b: Booted, texts: string[]): string[] {
  const trace = b.trace();
  const firstTurn = (text: string) => {
    const uuids = new Set(trace.filter((l) => l.t === "user" && JSON.stringify(l.content ?? null).includes(text)).map((l) => l.uuid));
    return trace.findIndex((l) => l.t === "turn_start" && uuids.has(l.uuid));
  };
  return texts.map((text) => ({ text, at: firstTurn(text) })).filter((x) => x.at >= 0).sort((x, y) => x.at - y.at).map((x) => x.text);
}

/**
 * The conversation as an order of turns: each of `msgs` as "<name> message" (`names`, in the same order), and each run
 * of replies that are not in `known` (rows drawn before the sends) as one "reply", wherever it is drawn.
 */
function turnOrder(s: ChatLook, msgs: string[], names: string[], known: ReadonlySet<string>): string[] {
  const nameOf = new Map(s.users.map((u) => [u.id, names[msgs.map(fold).indexOf(u.text)]]));
  const out: string[] = [];
  for (const id of s.rows) {
    const name = nameOf.get(id);
    if (name) out.push(`${name} message`);
    else if (!known.has(id) && s.texts[id] !== undefined && out.at(-1) !== "reply") out.push("reply");
  }
  return out;
}

/** The rows from the first of these ids on (the part of the conversation that a flow's sends made). */
function rowsFrom(s: ChatLook, ids: string[]): string[] {
  const i = s.rows.findIndex((id) => ids.includes(id));
  return i < 0 ? [] : s.rows.slice(i);
}

/**
 * R19 resume-drop (done check 4): the socket drops mid-reply (the in-page switch); while it is down the fake claude
 * ends the reply, starts a Bash call and asks for its permission; then the socket is back: one `attached` with replay
 * "events" and the card among its cards, no snapshot, each row once and the reply whole (no delta drawn twice), the
 * card open, no console error. Then Allow once: the turn's last reply comes whole and nothing keeps working.
 */
async function resumeDropFlow(t: Target, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow"): void => void failures.push({ code, text });
  const turn = resumeTurn(vp.label === "m626" ? "drop-m626" : vp.label === "large" ? "drop-large" : vp.name === "phone" ? "drop-phone" : "drop-laptop");
  const a = `${turn.ids.a}-0`;
  const c = `${turn.ids.c}-0`;
  const chat = EX.chat;
  const path = `/c/${chat}`;
  let shot: string | undefined;
  try {
    await withPage(vp, "dark", async (page) => {
      const inbox = new Inbox(cdp, page);
      try {
        await page.send("Page.addScriptToEvaluateOnNewDocument", { source: OFFLINE_SWITCH });
        await page.navigate(t.base + path);
        await waitShown(page, ["chat", "composer"]);
        page.takeIssues();
        if (!(await sendFromBox(page, turn.text))) return fail("the chat shows no message box with Send");
        // The socket drops after the reply's first words.
        const started = await untilLook(page, (s) => (s.texts[a] ?? "").length > 0, 10_000);
        if (!started.ok) return fail("the reply did not start");
        await page.evaluate("window.__uiGoOffline()");
        details.offlineAt = started.s.texts[a]!.length;
        if (!(await untilTrue(() => fakeAsked(t.booted!, turn.ids.tool), 20_000))) return fail("the fake claude never asked for the Bash call's permission");
        await sleep(400);
        const down = await lookChat(page);
        details.whileDown = { reply: down.texts[a]?.length ?? 0, cards: down.cards.length };
        if (down.cards.length) fail("with the socket down, the card already shows");
        const mark = inbox.mark();
        await page.evaluate("window.__uiGoOnline()");
        const back = await untilLook(page, (s) => s.cards.length > 0 && s.texts[a] === fold(RESUME_A), 15_000);
        await sleep(800); // room for a second copy
        const s1 = await lookChat(page);
        details.back = s1;
        const got = inbox.since(mark, (f) => f.chat === chat);
        const attached = got.filter((f) => f.t === "attached");
        details.attached = attached.map((f) => ({ replay: f.replay, cursor: f.cursor, seq: f.seq, cards: (f.cards ?? []).map((k: { id: string }) => k.id) }));
        details.after = { frames: got.length, snapshots: got.filter((f) => f.t === "snapshot").length, evs: got.filter((f) => f.t === "ev").length };
        if (attached.length !== 1) fail(`after the socket came back the chat got ${attached.length} attached frames, not one`);
        else {
          if (attached[0]!.replay !== "events") fail(`the attach after the drop got replay ${JSON.stringify(attached[0]!.replay)}, not "events"`);
          if (!(attached[0]!.cards ?? []).some((k: { id: string }) => k.id === turn.ids.tool)) fail("the attached frame does not give the waiting card back");
        }
        const snaps = got.filter((f) => f.t === "snapshot").length;
        if (snaps) fail(`after the drop the chat got ${snaps} snapshot frame${snaps > 1 ? "s" : ""}; a replay sends none`);
        if (!back.ok) fail(`after the socket came back, ${s1.cards.length ? "the reply is not whole" : "no card shows"}`);
        rowFindings(s1, { [a]: RESUME_A }, "after the replay", fail);
        oneUser(s1, turn.text, "after the replay", fail);
        if (s1.cards.length !== 1 || s1.cards[0]!.kind !== "permission") fail(`after the replay ${s1.cards.length} cards show (${s1.cards.map((k) => k.kind).join(", ")}), not the one permission card`);
        issueFindings(page.takeIssues(), failures, "after the replay, ");
        shot = shotName(t.scene, "resume-drop", vp, "dark", "back");
        await page.screenshot(shot).catch(() => {});
        // Allow once: the turn goes on to its last reply and ends.
        if (!(await pressOn(page, '[data-testid="card-permission"] [data-testid="confirm-once"]'))) return fail("the card shows no Allow once");
        const end = await untilLook(page, (s) => s.texts[c] === fold(RESUME_C) && !s.cards.length && !s.working, 15_000);
        details.end = end.s;
        if (!end.ok) fail("after Allow once the turn did not end with its last reply whole");
        rowFindings(end.s, { [a]: RESUME_A, [c]: RESUME_C }, "at the turn's end", fail);
        quietFindingsAtEnd(end.s, "at the turn's end", fail);
        issueFindings(page.takeIssues(), failures);
      } finally {
        inbox.dispose();
      }
    });
  } catch (e) {
    fail(`the check could not run: ${(e as Error).message}`, "run");
  }
  const note = "a drop mid-reply, the reply's end and its card while down, then back: one attached (replay events, the card first), no snapshot, each row once";
  return finish({ kind: "flow", name: "resume-drop", route: "chat", scene: t.scene, size: sizeTag(vp), theme: "dark", path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * R19 resume-reload (done check 5): mid-turn, with the card open, a message queued behind the turn and a draft in the
 * box, the page reloads (touch): each row once and the reply whole, the card back, no sideways overflow, no console
 * error; then Allow once and the stream goes on (the last reply grows piece by piece and ends whole), the queued
 * message runs, and the box holds the draft again. The box is emptied at the end.
 */
async function resumeReloadFlow(t: Target, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow"): void => void failures.push({ code, text });
  const tag = vp.label === "m626" ? "reload-m626" : vp.label === "large" ? "reload-large" : vp.name === "medium" ? "reload-medium" : "reload-phone";
  const turn = resumeTurn(tag);
  const a = `${turn.ids.a}-0`;
  const c = `${turn.ids.c}-0`;
  const queued = `Queued behind the resume check ${tag}`;
  const draft = `A draft kept across the reload ${tag}`;
  const chat = EX.chat;
  const path = `/c/${chat}`;
  let shot: string | undefined;
  try {
    await withPage(vp, "dark", async (page) => {
      await page.navigate(t.base + path);
      await waitShown(page, ["chat", "composer"]);
      page.takeIssues();
      if (!(await sendFromBox(page, turn.text))) return fail("the chat shows no message box with Send");
      if (!(await untilLook(page, (s) => (s.texts[a] ?? "").length > 0, 10_000)).ok) return fail("the reply did not start");
      if (!(await sendFromBox(page, queued))) return fail("no Send while the turn runs");
      const q = await untilLook(page, (s) => s.users.some((u) => u.text === fold(queued) && u.queued), 8000);
      if (!q.ok) fail("the message sent while the turn runs is not drawn queued");
      // The draft: typed and kept, never sent.
      await page.evaluate(`(() => { const el = ${FIELD}; if (!el) return false; el.focus(); return true; })()`);
      await page.send("Input.insertText", { text: draft });
      await sleep(1200);
      const open = await untilLook(page, (s) => s.cards.length > 0, 15_000);
      if (!open.ok) return fail("no card opened");
      details.beforeReload = open.s;
      await page.reload();
      await waitShown(page, ["chat"], 10_000);
      const back = await untilLook(page, (s) => s.cards.length > 0 && s.texts[a] === fold(RESUME_A) && s.users.some((u) => u.text === fold(queued)), 10_000);
      await sleep(800);
      const s1 = await lookChat(page);
      details.afterReload = s1;
      if (!back.ok) fail(`after the reload ${s1.cards.length ? "the reply is not whole or the queued message is gone" : "the card is not back"}`);
      rowFindings(s1, { [a]: RESUME_A }, "after the reload", fail);
      oneUser(s1, turn.text, "after the reload", fail);
      const qu = oneUser(s1, queued, "after the reload", fail);
      // Row 111: a queued message is the plain bubble with no word under it (a foot word here would be Not sent).
      if (qu && (!qu.queued || qu.foot)) fail(`after the reload the message behind the turn is drawn ${qu.foot ? `"${qu.foot}"` : "as sent"}, not queued`);
      if (s1.cards.length !== 1) fail(`after the reload ${s1.cards.length} cards show, not one`);
      const lost = open.s.rows.filter((id) => !s1.rows.includes(id));
      if (lost.length) fail(`the reload lost rows: ${clipList(lost)}`);
      const st = await page.probe();
      stateFindings(st, vp, failures, "after the reload, ");
      issueFindings(page.takeIssues(), failures, "after the reload, ");
      shot = shotName(t.scene, "resume-reload", vp, "dark", "reloaded");
      await page.screenshot(shot).catch(() => {});
      // Allow once: the stream goes on.
      if (!(await pressOn(page, '[data-testid="card-permission"] [data-testid="confirm-once"]'))) return fail("the card shows no Allow once after the reload");
      const lengths: number[] = [];
      const end = Date.now() + 15_000;
      let last: ChatLook = s1;
      while (Date.now() < end) {
        last = await lookChat(page);
        const n = last.texts[c]?.length ?? 0;
        if (n && n !== lengths[lengths.length - 1]) lengths.push(n);
        if (last.texts[c] === fold(RESUME_C)) break;
        await sleep(60);
      }
      details.streamLengths = lengths;
      if (last.texts[c] !== fold(RESUME_C)) fail("after Allow once the last reply did not come whole");
      else if (lengths.length < 3) fail(`after the reload the last reply came in ${lengths.length} step${lengths.length === 1 ? "" : "s"}, not as a stream`);
      // The queued message runs once the turn ends; then the box is back with the draft.
      const done = await untilLook(page, (s) => !s.cards.length && !s.working && s.users.some((u) => u.text === fold(queued) && !u.queued) && s.field !== null, 20_000);
      details.end = done.s;
      if (!done.ok) fail("the queued message did not run after the turn, or the box did not come back");
      if (done.s.field !== draft) fail(`after the card the box holds ${JSON.stringify(done.s.field)}, not the draft`);
      rowFindings(done.s, { [a]: RESUME_A, [c]: RESUME_C }, "at the end", fail);
      oneUser(done.s, queued, "at the end", fail);
      quietFindingsAtEnd(done.s, "at the end", fail);
      stateFindings(await page.probe(), vp, failures, "at the end, ");
      issueFindings(page.takeIssues(), failures);
      const left = await emptyChatBox(page);
      if (left) warnings.push({ code: "flow", text: `the box could not be emptied at the end (${JSON.stringify(left)})` });
    });
  } catch (e) {
    fail(`the check could not run: ${(e as Error).message}`, "run");
  }
  const note = "a reload mid-turn with the card open, a queued message and a draft: each row once, the card back, the stream goes on, the draft back";
  return finish({ kind: "flow", name: "resume-reload", route: "chat", scene: t.scene, size: sizeTag(vp), theme: "dark", path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/** The slow-network flow's gap, in seconds (--gap; DESIGN 9.4 done check 9 asks for 30 to 120). */
const GAP_S = args.gap ? Number(args.gap) : 30;
if (!Number.isFinite(GAP_S) || GAP_S < 5 || GAP_S > 300) fail("--gap must be from 5 to 300 seconds");

/**
 * R19 resume-slow (DC9): the page reaches kitespan only through the proxy of scripts/net-proxy.ts (250 ms each way,
 * 1 Mbit/s each way). Mid-reply a message goes out and the link is cut just after the server took it, so its ack is
 * lost; during the gap the fake claude ends the reply and its card waits, and a message is typed and sent. After the
 * gap: the card is drawn first, the missed events come by replay (no snapshot), each message runs exactly once (the
 * resend gets the stored ack), and once the turns end no spinner or reconnect line stays. Then the never-sent case of
 * R1: a message sent while the link is cut, and the page reloads before it could go: it is back in the box, its copy
 * is gone, nothing sent it, and the fake claude never saw it.
 */
async function resumeSlowFlow(t: Target, proxy: NetProxy, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = { gapS: GAP_S, link: proxy.profile };
  const fail = (text: string, code = "flow"): void => void failures.push({ code, text });
  const tag = vp.name === "phone" ? "slow-phone" : "slow-laptop";
  const turn = resumeTurn(tag);
  const a = `${turn.ids.a}-0`;
  const c = `${turn.ids.c}-0`;
  const lostAck = `Sent just before the link went ${tag}`;
  const typed = `Typed during the gap ${tag}`;
  const never = `Never sent ${tag}-${Date.now().toString(36)}`;
  const chat = EX.chat;
  const via = `http://127.0.0.1:${proxy.port}`;
  const path = `/c/${chat}`;
  const b = t.booted!;
  let shot: string | undefined;
  try {
    await withPage(vp, "dark", async (page, wire) => {
      const inbox = new Inbox(cdp, page);
      try {
        await page.send("Page.addScriptToEvaluateOnNewDocument", { source: OFFLINE_SWITCH });
        await page.navigate(via + path);
        await waitShown(page, ["chat", "composer"], 30_000);
        page.takeIssues();
        if (!(await sendFromBox(page, turn.text))) return fail("the chat shows no message box with Send");
        if (!(await untilLook(page, (s) => (s.texts[a] ?? "").length > 0, 15_000)).ok) return fail("the reply did not start");
        // A message, and the cut just after the server took it: its ack is lost on the way back.
        const sentMark = wire.mark();
        if (!(await sendFromBox(page, lostAck))) return fail("no Send while the turn runs");
        await sleep(proxy.profile.delayMs + 170);
        await page.evaluate(WATCH([
          { key: "card", sel: 'section[data-testid="card-permission"]' },
          { key: "reply", sel: `[data-testid="item-${a}"] .chat-assistant > div:first-child`, text: fold(RESUME_A) },
        ]));
        const cutAt = Date.now();
        const cutMark = inbox.mark();
        const wireCut = wire.mark();
        const issuesBefore = page.takeIssues();
        const gap = proxy.cut(GAP_S * 1000);
        const lostRid = acting(wire.framesSince(sentMark)).find((f) => f.t === "send" && String(f.frame.text ?? "") === lostAck)?.rid ?? null;
        const sawBefore = b.trace().some((l) => l.t === "user" && JSON.stringify(l.content ?? null).includes(lostAck) && l.at <= cutAt);
        const ackBefore = wire.acks.some((x) => x.rid === lostRid && x.n <= wireCut);
        details.lostAck = { rid: lostRid, serverTookIt: sawBefore, ackCame: ackBefore };
        if (!lostRid) fail("the message sent before the cut never went out");
        else if (!sawBefore || ackBefore) warnings.push({ code: "flow", text: `${ackBefore ? "the ack came before the cut" : "the cut came before the server took the message"}, so this run lost no ack` });
        issueFindings(issuesBefore, failures, "before the cut, ");
        // During the gap: the card waits on the server; a message typed here waits in the outbox.
        await sleep(3000);
        if (!(await sendFromBox(page, typed))) fail("during the gap the box shows no Send");
        await sleep(800);
        const down = await lookChat(page);
        details.duringGap = down;
        // Neither has an ack: each waits in the page's outbox, so each is drawn as not sent yet (4.3, 6.2).
        for (const [m, what] of [[lostAck, "the message whose ack the cut lost"], [typed, "the message typed during the gap"]] as const) {
          const du = down.users.find((u) => u.text === fold(m));
          if (!du) fail(`during the gap ${what} does not show`);
          else if (!du.unsent) fail(`during the gap ${what} is drawn ${du.foot ? `"${du.foot}"${du.takeBack ? " with Take back" : ""}` : "as sent"}, not as not sent yet, though it waits in the page's outbox`);
        }
        if (down.field) fail(`during the gap the box still holds ${JSON.stringify(down.field)} after Send`);
        if (!down.reconnecting && down.conn !== "reconnecting") fail("during the gap no Reconnecting... line shows");
        if (down.cards.length) fail("during the gap a card shows (the page cannot know of it)");
        await gap;
        const backAt = Date.now();
        // The link is back: the page dials again after its backoff (at most about 12 s).
        const welcome = await inbox.waitFor((f) => f.t === "welcome", 30_000, cutMark);
        if (!welcome) return fail(`no welcome within 30 s after the ${GAP_S} s gap`);
        details.backMs = welcome.at - backAt;
        const settled = await untilLook(page, (s) => s.cards.length > 0 && s.texts[a] === fold(RESUME_A) && [lostAck, typed].every((m) => s.users.some((u) => u.text === fold(m) && !u.unsent)), 20_000);
        await sleep(1500);
        const s1 = await lookChat(page);
        details.afterGap = s1;
        const frames = inbox.since(welcome.n, (f) => f.chat === chat);
        const firstOfChat = frames.find((f) => f.t === "attached" || f.t === "ev" || f.t === "snapshot");
        const attached = frames.filter((f) => f.t === "attached");
        details.attached = attached.map((f) => ({ replay: f.replay, cursor: f.cursor, seq: f.seq, cards: (f.cards ?? []).map((k: { id: string }) => k.id) }));
        if (!firstOfChat || firstOfChat.t !== "attached") fail(`after the gap the chat's first frame is ${firstOfChat?.t ?? "none"}, not attached`);
        else if (!(firstOfChat.cards ?? []).some((k: { id: string }) => k.id === turn.ids.tool)) fail("after the gap the attached frame does not give the waiting card back first");
        if (attached.length !== 1 || attached[0]!.replay !== "events") fail(`after the gap the chat got ${attached.map((f) => `attached (${f.replay})`).join(", ") || "no attached"}, not one replay of its events`);
        const snaps = frames.filter((f) => f.t === "snapshot").length;
        if (snaps) fail(`after the gap the chat got ${snaps} snapshot frame${snaps > 1 ? "s" : ""}`);
        const seen = JSON.parse(await page.evaluate<string>(SEEN)) as Record<string, number>;
        details.seen = seen;
        if (!seen.card) fail("after the gap the card never showed");
        else if (seen.reply && seen.card > seen.reply) fail(`after the gap the reply was drawn ${seen.card - seen.reply} ms before the waiting card`);
        if (!settled.ok) fail("after the gap the card, the whole reply or the two messages did not all show");
        if (s1.reconnecting || s1.conn === "reconnecting") fail(`after the gap the page still says ${JSON.stringify(s1.reconnecting ?? "Reconnecting...")}`);
        rowFindings(s1, { [a]: RESUME_A }, "after the gap", fail);
        for (const m of [turn.text, lostAck, typed]) oneUser(s1, m, "after the gap", fail);
        shot = shotName(t.scene, "resume-slow", vp, "dark", "back");
        await page.screenshot(shot).catch(() => {});
        // Allow once: the turn ends, then the two messages run, each once.
        if (!(await pressOn(page, '[data-testid="card-permission"] [data-testid="confirm-once"]'))) return fail("the card shows no Allow once after the gap");
        const done = await untilLook(page, (s) => s.texts[c] === fold(RESUME_C) && !s.cards.length && !s.working && !s.spin && s.users.filter((u) => [lostAck, typed].includes(u.text)).every((u) => !u.queued && !u.unsent), 30_000);
        await sleep(1500);
        const s2 = await lookChat(page);
        details.end = s2;
        if (!done.ok) fail("after Allow once the turn and the two messages did not all end");
        rowFindings(s2, { [a]: RESUME_A, [c]: RESUME_C }, "at the end", fail);
        for (const m of [turn.text, lostAck, typed]) oneUser(s2, m, "at the end", fail);
        quietFindingsAtEnd(s2, "at the end", fail);
        const saw = Object.fromEntries([lostAck, typed].map((m) => [m, claudeSaw(b, m)]));
        details.claudeSaw = saw;
        for (const [m, n] of Object.entries(saw)) if (n !== 1) fail(`the fake claude saw ${JSON.stringify(clip(m, 50))} ${n} times, not once`);
        const gapIssues = page.takeIssues();
        // A request that the cut ended is the cut's, not the page's; anything else counts.
        const expected = gapIssues.filter((i) => i.kind === "request" && /ERR_(CONNECTION|EMPTY_RESPONSE|NETWORK)/.test(i.text));
        details.cutRequests = expected.map((i) => i.text);
        issueFindings(gapIssues.filter((i) => !expected.includes(i)), failures, "around the gap, ");

        // R1's never-sent case: sent while the link is cut, then a reload before it could go.
        const neverMark = wire.mark();
        const cut2 = proxy.cut(4000);
        await sleep(300);
        if (!(await sendFromBox(page, never))) fail("with the link cut the box shows no Send");
        await sleep(700);
        const pending = await lookChat(page);
        if (!pending.users.some((u) => u.text === fold(never) && u.unsent)) fail("with the link cut the message is not drawn as not sent yet");
        // This document never dials again: the reload comes before the link would carry the message.
        await page.evaluate("window.__uiGoOffline()");
        await cut2;
        await page.reload();
        await waitShown(page, ["chat", "composer"], 30_000);
        const r = await untilLook(page, (s) => s.field === never, 10_000);
        await sleep(800);
        const s3 = await lookChat(page);
        const copy = await page.evaluate<string | null>(`localStorage.getItem(${JSON.stringify(`kitespan.sent.${chat}`)})`);
        details.neverSent = { field: s3.field, bubbles: s3.users.filter((u) => u.text === fold(never)).length, copy };
        if (!r.ok) fail(`after the reload the box holds ${JSON.stringify(s3.field)}, not the message that never went out`);
        if (s3.users.some((u) => u.text === fold(never))) fail("after the reload the message that never went out shows in the chat");
        if (copy && copy.includes(never)) fail("after the reload the never-sent message's copy is still kept");
        const sentNever = acting(wire.framesSince(neverMark)).filter((f) => f.t === "send" && String(f.frame.text ?? "").includes(never));
        if (sentNever.length) fail(`the never-sent message went out ${sentNever.length} time${sentNever.length > 1 ? "s" : ""} by itself`);
        if (claudeSaw(b, never)) fail("the fake claude saw the never-sent message");
        rowFindings(s3, {}, "after the reload", fail);
        stateFindings(await page.probe(), vp, failures, "after the reload, ");
        const reloadIssues = page.takeIssues();
        issueFindings(reloadIssues.filter((i) => !(i.kind === "request" && /ERR_(CONNECTION|EMPTY_RESPONSE|NETWORK)/.test(i.text))), failures, "after the reload, ");
        const left = await emptyChatBox(page);
        if (left) warnings.push({ code: "flow", text: `the box could not be emptied at the end (${JSON.stringify(left)})` });

        // Chrome reached the page only through the proxy.
        const web = inbox.urls.filter((u) => /^(https?|wss?):/.test(u));
        const direct = web.filter((u) => new URL(u).host !== `127.0.0.1:${proxy.port}`);
        details.urls = { total: web.length, direct: direct.slice(0, 5) };
        if (!web.length) fail("the page made no request through the proxy");
        if (direct.length) fail(`the page reached ${clipList([...new Set(direct.map((u) => new URL(u).host))])} without the proxy`);
        details.proxy = proxy.stats();
      } finally {
        inbox.dispose();
      }
    });
  } catch (e) {
    fail(`the check could not run: ${(e as Error).message}`, "run");
  }
  const note = `through the proxy (${proxy.profile.delayMs} ms each way, ${proxy.profile.kbit} kbit/s, a ${GAP_S} s gap): the card first, a replay, each message once, no spinner left; the never-sent message back in the box`;
  return finish({ kind: "flow", name: "resume-slow", route: "chat", scene: t.scene, size: sizeTag(vp), theme: "dark", path: via + path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * S14 restart (DESIGN.md 4.10, done check 3): a paced fake turn runs in the example chat (page B); the restart dialog
 * (page A, /settings/about/restart) lists it, and Restart when they finish sends one POST /api/restart {when: "finish"}
 * (202) and waits with Cancel restart; a send on page B while it waits is held queued and never reaches Claude
 * Code; the turn ends, the server restarts: the Restarting line shows between `bye` and the new `welcome` (the
 * dialog's line, and on the chat's page at every size: the list's foot where it shows, else the chat's own line),
 * the pages keep their URLs, page B shows the chat's history with no row lost or twice and no line of a cut turn,
 * and the held message is Not sent with Send again; Send again sends one send_queued and the new server's Claude Code
 * gets the message once. Page C, on a second chat that sleeps, sends two messages while the restart waits (each held
 * queued); after the restart both are Not sent, in order, and a plain send there (Send, not Send again) sends one
 * `send`: Claude Code runs the two held messages first, in order, then the new one, each once, and page C draws each
 * message with its reply below it in that order, as a reload of the chat (the server's history) does.
 */
async function restartFlow(t: Target, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow"): void => void failures.push({ code, text });
  const chatPath = `/c/${EX.chat}`;
  const secondPath = `/c/${IDS.chats.parser}`;
  const dialogPath = "/settings/about/restart";
  const stem = `${vp.name}-${Date.now().toString(36)}`;
  const held = `Held while kitespan restarts ${stem}`;
  const heldC = [`Held in a second chat, first ${stem}`, `Held in a second chat, second ${stem}`];
  const plain = `Sent after the restart into the second chat ${stem}`;
  // About 18 s: room for the held sends on two pages before the turn ends and the server restarts.
  const prompt = pacedPrompt(3000, 120, 150);
  const b = t.booted!;
  let shot: string | undefined;
  const pages: { page: Page; wire: Wire; inbox: Inbox }[] = [];
  const open = async () => {
    const page = await Page.open(cdp, vp, "dark");
    const p = { page, wire: new Wire(cdp, page), inbox: new Inbox(cdp, page) };
    pages.push(p);
    return p;
  };
  const who = new Map<Page, string>();
  const body = async (): Promise<void> => {
    const B = await open();
    who.set(B.page, "the chat's page: ");
    const C = await open();
    who.set(C.page, "the second chat's page: ");
    await C.page.navigate(t.base + secondPath);
    await waitShown(C.page, ["chat", "composer"]);
    C.page.takeIssues();
    await B.page.navigate(t.base + chatPath);
    await waitShown(B.page, ["chat", "composer"]);
    const epoch0 = (await B.inbox.waitFor((f) => f.t === "welcome", 5000))?.f.epoch as string | undefined;
    if (!epoch0) return fail("the chat's page got no welcome");
    B.page.takeIssues();
    if (!(await sendFromBox(B.page, prompt))) return fail("the chat shows no message box with Send");
    if (!(await untilLook(B.page, (s) => s.working > 0 || Object.values(s.texts).some((x) => x.startsWith("Part 1")), 10_000)).ok) return fail("the paced turn did not start");

    const A = await open();
    who.set(A.page, "the dialog's page: ");
    await A.page.navigate(t.base + dialogPath);
    await waitShown(A.page, ["dialog-restart", "confirm-restart"], 8000);
    const dialog = await A.page.evaluate<{ running: string | null; finish: string | null; now: boolean; clause: string | null }>(`(() => {
      const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
      const one = (id) => [...document.querySelectorAll('[data-testid="' + id + '"]')].find(shown);
      const t = (id) => { const el = one(id); return el ? el.textContent.replace(/\\s+/g, " ").trim() : null; };
      return { running: t("restart-running"), finish: t("confirm-restart"), now: !!one("confirm-restart-now"), clause: t("restart-clause") };
    })()`);
    details.dialog = dialog;
    if (!dialog.running) fail("the dialog does not list the running turn");
    if (dialog.finish !== "Restart when they finish") fail(`the dialog's default button says ${JSON.stringify(dialog.finish)}, not "Restart when they finish"`);
    if (!dialog.now) fail("the dialog shows no Restart now");
    if (!dialog.clause) fail("the dialog shows no clause under Restart now");
    for (const p of pages) await p.page.evaluate(LINE_SAMPLER);
    const httpMark = A.wire.mark();
    if (!(await pressOn(A.page, '[data-testid="confirm-restart"]'))) return fail("no Restart when they finish to press");
    await waitSent(A.wire, httpMark);
    const asked = A.wire.httpSince(httpMark);
    const post = A.inbox.posts.filter((x) => x.path === "/api/restart");
    details.asked = { http: asked.map(httpText), body: post.map((x) => x.body) };
    if (asked.length !== 1 || asked[0]!.path !== "/api/restart" || asked[0]!.method !== "POST") fail(`Restart when they finish sent ${clipList(asked.map(httpText)) || "nothing"}; expected one POST /api/restart`);
    else if (asked[0]!.status !== 202) fail(`POST /api/restart answered ${asked[0]!.status}, not 202`);
    if (post[0] && post[0].body && JSON.parse(post[0].body).when !== "finish") fail(`POST /api/restart asked ${post[0].body}, not {"when":"finish"}`);
    let waits = false;
    for (const until = Date.now() + 5000; !waits && Date.now() < until; await sleep(100))
      waits = await A.page.evaluate<boolean>(`!!document.querySelector('[data-testid="confirm-cancel-restart"]') && !!document.querySelector('[data-testid="restart-line"]')`);
    if (!waits) fail("while the restart waits the dialog shows no line with Cancel restart");
    const drain = await untilLook(B.page, (s) => !!s.drain, 5000);
    if (!drain.ok) fail("while the restart waits the chat's page shows no drain line");

    // A send while the restart waits: held, queued, never given to Claude Code.
    const sendMark = B.wire.mark();
    if (!(await sendFromBox(B.page, held))) return fail("no Send while the restart waits");
    await waitSent(B.wire, sendMark);
    const sendFrame = acting(B.wire.framesSince(sendMark)).find((f) => f.t === "send");
    const ack = sendFrame?.rid ? await B.inbox.waitFor((f) => f.t === "ack" && f.rid === sendFrame.rid, 5000) : null;
    details.heldAck = ack?.f ?? null;
    if (!ack?.f.ok) fail(`the send while the restart waits got ${ack ? `a refusal (${ack.f.error?.code})` : "no ack"}`);
    else if (ack.f.result?.queued !== true) fail(`the send while the restart waits was not held (ack ${JSON.stringify(ack.f.result)})`);
    const q = await untilLook(B.page, (s) => s.users.some((u) => u.text === fold(held) && u.queued && !u.foot), 5000);
    if (!q.ok) fail("the held message is not drawn queued");
    if (claudeSaw(b, held)) fail("Claude Code got the held message before the restart");
    // Two sends in a second chat that sleeps: each held as well.
    for (const m of heldC) {
      const mk = C.wire.mark();
      if (!(await sendFromBox(C.page, m))) {
        fail("while the restart waits the second chat shows no Send");
        break;
      }
      await waitSent(C.wire, mk);
      const f = acting(C.wire.framesSince(mk)).find((x) => x.t === "send");
      const a = f?.rid ? await C.inbox.waitFor((x) => x.t === "ack" && x.rid === f.rid, 5000) : null;
      if (!a?.f.ok) fail(`a send in the second chat while the restart waits got ${a ? `a refusal (${a.f.error?.code})` : "no ack"}`);
      else if (a.f.result?.queued !== true) fail(`a send in the second chat while the restart waits was not held (ack ${JSON.stringify(a.f.result)})`);
    }
    const qc = await untilLook(C.page, (s) => heldC.every((m) => s.users.some((u) => u.text === fold(m) && u.queued && !u.foot)), 5000);
    details.secondHeld = qc.s.users.filter((u) => heldC.map(fold).includes(u.text));
    if (!qc.ok) fail("the second chat's two held messages are not both drawn queued");
    for (const m of heldC) if (claudeSaw(b, m)) fail("Claude Code got a message held in the second chat before the restart");

    // The turn ends; the server restarts. The last look before the bye is the history to keep.
    let before: ChatLook | null = null;
    const byeMark = B.inbox.mark();
    const end = Date.now() + 90_000;
    while (Date.now() < end) {
      const s = await lookChat(B.page).catch(() => null);
      if (B.inbox.since(byeMark, (f) => f.t === "bye").length) break;
      if (s) before = s;
      await sleep(150);
    }
    const bye = B.inbox.since(byeMark, (f) => f.t === "bye")[0];
    details.bye = bye ?? null;
    if (!bye) return fail("no bye within 90 s: the restart did not happen");
    if (bye.reason !== "restart") fail(`the bye says ${JSON.stringify(bye.reason)}, not restart`);
    if (claudeSaw(b, held)) fail("Claude Code got the held message before the restart");
    const welcomes = await Promise.all(pages.map((p) => p.inbox.waitFor((f) => f.t === "welcome" && f.epoch !== epoch0, 40_000)));
    if (welcomes.some((w) => !w)) return fail("a page got no welcome from the new server within 40 s");
    details.epochs = { before: epoch0, after: welcomes[0]!.f.epoch };
    await sleep(1500);
    await B.page.settle();
    details.successors = b.successors();
    if (!b.successors().length) warnings.push({ code: "flow", text: "no successor of the boot shows on the port (the harness could not find the new server)" });
    const out = b.output().out;
    details.oldServerLine = out.split("\n").find((l) => l.startsWith("kitespan restarted as process")) ?? null;

    // The Restarting line between bye and the new welcome.
    const linesA = JSON.parse(await A.page.evaluate<string>(LINES)) as LineSample[];
    const linesB = JSON.parse(await B.page.evaluate<string>(LINES)) as LineSample[];
    details.lines = { dialog: linesA, chat: linesB };
    const byeAt = B.inbox.frames.find((x) => x.f === bye)!.at;
    const restartingA = linesA.some((x) => x.dialog === RESTARTING_LINE);
    if (!restartingA) fail(`the dialog never said "${RESTARTING_LINE}" between bye and the new welcome`);
    // The chat's page says it at every size: the list's foot where the list shows (a laptop), else the chat's own line.
    if (!saidBetween(linesB, byeAt, welcomes[0]!.at + 2000, (x) => x.conn === "restarting" || x.chat === RESTARTING_LINE))
      fail(`the chat's page never said "${RESTARTING_LINE}" between bye and the new welcome (${vp.name === "laptop" ? "the list's foot" : "the chat's line"})`);
    const dialogEnd = await A.page.evaluate<string | null>(`(() => { const el = document.querySelector('[data-testid="restart-line"]'); return el ? el.textContent.trim() : null; })()`);
    const pathA = await A.page.evaluate<string>("location.pathname + location.search");
    details.dialogEnd = { path: pathA, line: dialogEnd };
    if (pathA !== dialogPath) fail(`after the restart the dialog's page moved to ${pathA}`);
    if (dialogEnd !== RESTARTED_LINE) fail(`after the restart the dialog says ${JSON.stringify(dialogEnd)}, not "${RESTARTED_LINE}"`);

    // Page B: the same URL, the chat's history, the held message Not sent with Send again.
    const after = await untilLook(B.page, (s) => s.users.some((u) => u.text === fold(held) && u.foot === "Not sent"), 10_000);
    const s1 = after.s;
    details.before = before;
    details.after = s1;
    if (s1.path !== chatPath) fail(`after the restart the chat's page moved to ${s1.path}`);
    const lost = (before?.rows ?? []).filter((id) => !s1.rows.includes(id));
    if (!before?.rows.length) fail("no rows were read before the restart");
    if (lost.length) fail(`after the restart the chat lost rows: ${clipList(lost)}`);
    if (s1.dups.length) fail(`after the restart rows show twice: ${clipList(s1.dups)}`);
    if (s1.stopLine) fail("after Restart when they finish the chat shows the line of a cut turn");
    const h = oneUser(s1, held, "after the restart", fail);
    if (h && (h.foot !== "Not sent" || !h.again || !h.takeBack)) fail(`after the restart the held message shows ${JSON.stringify(h.foot)}${h.again ? "" : " with no Send again"}${h.takeBack ? "" : " with no Take back"}, not Not sent with Send again and Take back`);
    shot = shotName(t.scene, "restart", vp, "dark", "after");
    await B.page.screenshot(shot).catch(() => {});
    for (const p of pages) issueFindings(p.page.takeIssues(), failures, who.get(p.page));

    // Send again: one send_queued, and the new server's Claude Code gets the message once.
    const againMark = B.wire.mark();
    if (!(await pressOn(B.page, `[data-testid="send-again"]`))) return fail("no Send again to press");
    await waitSent(B.wire, againMark);
    const again = acting(B.wire.framesSince(againMark));
    details.sendAgain = again.map((f) => f.frame);
    if (again.length !== 1 || again[0]!.t !== "send_queued") fail(`Send again sent ${clipList(again.map(frameText)) || "nothing"}; expected one send_queued`);
    else {
      const ack2 = await waitAck(B.wire, again[0]!.rid!, 8000);
      if (!ack2?.ok) fail(`send_queued got ${ack2 ? `a refusal (${ack2.code})` : "no ack"}`);
    }
    await untilTrue(() => claudeSaw(b, held) > 0, 15_000);
    const ran = await untilLook(B.page, (s) => s.users.some((u) => u.text === fold(held) && !u.queued) && !s.working, 15_000);
    await sleep(800);
    const saw = claudeSaw(b, held);
    details.claudeSaw = saw;
    if (saw !== 1) fail(`Claude Code got the held message ${saw} times, not once`);
    if (!ran.ok) fail("after Send again the held message did not run");
    else quietFindingsAtEnd(ran.s, "after Send again", fail);
    for (const p of pages) issueFindings(p.page.takeIssues(), failures, who.get(p.page));

    // Page C: the two held messages Not sent, in order; then a plain send (Send, not Send again).
    const all = [...heldC, plain];
    const names = ["the first held", "the second held", "the new"];
    const restored = await untilLook(C.page, (s) => heldC.every((m) => s.users.some((u) => u.text === fold(m) && u.foot === "Not sent")), 10_000);
    details.secondRestored = restored.s.users.filter((u) => heldC.map(fold).includes(u.text));
    if (!restored.ok) fail("after the restart the second chat's two held messages are not both Not sent");
    const drawn = restored.s.users.filter((u) => heldC.map(fold).includes(u.text)).map((u) => names[heldC.map(fold).indexOf(u.text)]);
    if (drawn.join() !== names.slice(0, 2).join()) fail(`after the restart the second chat draws ${drawn.join(", ") || "none"} of its held messages, not the first then the second`);
    const known = new Set(restored.s.rows);
    const plainMark = C.wire.mark();
    if (!(await sendFromBox(C.page, plain))) return fail("after the restart the second chat shows no message box with Send");
    await waitSent(C.wire, plainMark);
    const went = acting(C.wire.framesSince(plainMark));
    details.plainSend = went.map((f) => f.frame);
    if (went.length !== 1 || went[0]!.t !== "send") fail(`Send in the second chat sent ${clipList(went.map(frameText)) || "nothing"}; expected one send`);
    else {
      const ack3 = await waitAck(C.wire, went[0]!.rid!, 8000);
      if (!ack3?.ok) fail(`the send in the second chat got ${ack3 ? `a refusal (${ack3.code})` : "no ack"}`);
    }
    await untilTrue(() => all.every((m) => claudeRuns(b, m) > 0), 20_000);
    const want = names.flatMap((n) => [`${n} message`, "reply"]);
    const settledC = await untilLook(C.page, (s) => all.every((m) => s.users.some((u) => u.text === fold(m) && !u.queued && !u.unsent)) && !s.working && !s.spin && turnOrder(s, all, names, known).filter((x) => x === "reply").length >= 3, 20_000);
    await sleep(1000);
    const live = await lookChat(C.page);
    details.secondEnd = { rows: live.rows, users: live.users, order: turnOrder(live, all, names, known) };
    if (!settledC.ok) fail("after the send in the second chat, its three messages and their replies did not all come");
    const ranOrder = claudeRanOrder(b, all);
    details.secondClaude = { order: ranOrder.map((m) => names[all.indexOf(m)]), runs: all.map((m) => claudeRuns(b, m)) };
    for (const m of all) if (claudeRuns(b, m) !== 1) fail(`Claude Code ran ${names[all.indexOf(m)]} message of the second chat ${claudeRuns(b, m)} times, not once`);
    if (ranOrder.join("\n") !== all.join("\n")) fail(`Claude Code ran the second chat's messages in the order ${ranOrder.map((m) => names[all.indexOf(m)]).join(", ") || "none"}, not the held ones first, in order, then the new one`);
    const liveOrder = turnOrder(live, all, names, known);
    if (liveOrder.join() !== want.join()) fail(`after the send the second chat's page draws ${liveOrder.join(" > ")}, not ${want.join(" > ")}`);
    rowFindings(live, {}, "after the send in the second chat", fail);
    for (const m of all) oneUser(live, m, "after the send in the second chat", fail);
    quietFindingsAtEnd(live, "after the send in the second chat", fail);
    // The server's order: a reload draws the chat's history as the server holds it.
    await C.page.reload();
    await waitShown(C.page, ["chat", "composer"], 10_000);
    const fresh = (await untilLook(C.page, (s) => all.every((m) => s.users.some((u) => u.text === fold(m))), 10_000)).s;
    const freshOrder = turnOrder(fresh, all, names, known);
    details.secondReloaded = { rows: fresh.rows, order: freshOrder };
    if (freshOrder.join() !== want.join()) fail(`after a reload the second chat draws ${freshOrder.join(" > ")}, not ${want.join(" > ")}`);
    const ids = live.users.filter((u) => all.map(fold).includes(u.text)).map((u) => u.id);
    const liveRows = rowsFrom(live, ids);
    const freshRows = rowsFrom(fresh, ids);
    if (liveRows.join() !== freshRows.join()) fail(`from the first held message on, the second chat's page drew the rows ${clipList(liveRows)}, but its reload (the server's order) draws ${clipList(freshRows)}`);
    await C.page.screenshot(shotName(t.scene, "restart", vp, "dark", "second-chat")).catch(() => {});
    for (const p of pages) issueFindings(p.page.takeIssues(), failures, who.get(p.page));
  };
  try {
    await body();
  } catch (e) {
    fail(`the check could not run: ${(e as Error).message}`, "run");
  } finally {
    for (const p of pages) {
      p.inbox.dispose();
      p.wire.dispose();
      await p.page.close();
    }
  }
  const note = "Restart when they finish during a paced turn: the held sends queued, the Restarting line, the same URLs, the history, Not sent with Send again, one send_queued; a plain send after Not sent: the held ones first, in order, as the server's history";
  return finish({ kind: "flow", name: "restart", route: "restart", scene: t.scene, size: sizeTag(vp), theme: "dark", path: `${dialogPath} and ${chatPath}`, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * Send again with the socket down (4.3, 6.3; RD-8 and PT-10), on the not-sent scene's seed, a fresh one per size (the
 * press uses up the Not sent message): the example chat's message that waited when kitespan stopped shows Not sent with
 * Send again; the socket goes down (the in-page switch) and Send again is pressed, then once more if it still shows and
 * is on (a phone that shows no change gets a second tap). Nothing goes out, and a Reconnecting... line shows: the
 * chat's own on the phone, the chat's or the list's foot on the laptop, never both. Then the socket is back: exactly
 * one send_queued goes, with an ok ack, Claude Code runs the message once, and its mark clears.
 */
async function offlineSendAgainFlow(t: Target, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow"): void => void failures.push({ code, text });
  const chat = EX.chat;
  const path = `/c/${chat}`;
  const text = WARM.notSent;
  const b = t.booted!;
  const again = '[data-testid="send-again"]';
  let shot: string | undefined;
  try {
    await withPage(vp, "dark", async (page, wire) => {
      const inbox = new Inbox(cdp, page);
      try {
        await page.send("Page.addScriptToEvaluateOnNewDocument", { source: OFFLINE_SWITCH });
        await page.navigate(t.base + path);
        await waitShown(page, ["chat", "composer"]);
        page.takeIssues();
        const first = await untilLook(page, (s) => s.users.some((u) => u.text === fold(text) && u.foot === "Not sent" && u.again), 8000);
        details.before = first.s.users.find((u) => u.text === fold(text)) ?? null;
        if (!first.ok) return fail("the message that waited when kitespan stopped does not show Not sent with Send again");
        const since = wire.mark();
        await page.evaluate("window.__uiGoOffline()");
        await sleep(400);
        if (!(await pressOn(page, again))) return fail("with the socket down no Send again shows to press");
        await sleep(600);
        const down = await lookChat(page);
        const second = await page.evaluate<string>(`(() => { const el = [...document.querySelectorAll(${JSON.stringify(again)})].find((e) => e.getClientRects().length > 0); return !el ? "gone" : el.disabled ? "off" : "on"; })()`);
        let presses = 1;
        if (second === "on" && (await pressOn(page, again))) {
          presses++;
          await sleep(600);
        }
        details.down = { reconnecting: down.reconnecting, conn: down.conn, message: down.users.find((u) => u.text === fold(text)) ?? null, sendAgainAfterPress: second, presses };
        if (vp.name === "phone" && !down.reconnecting) fail("with the socket down and Send again pressed, the phone's chat shows no Reconnecting... line");
        if (vp.name !== "phone" && !down.reconnecting && down.conn !== "reconnecting") fail("with the socket down and Send again pressed, no Reconnecting... line shows");
        if (down.reconnecting && down.conn === "reconnecting") fail("two Reconnecting... lines show (the chat's and the list's foot)");
        oneUser(await lookChat(page), text, "with the socket down", fail);
        const out = acting(wire.framesSince(since));
        if (out.length) fail(`with the socket down, the wire shows ${clipList(out.map(frameText))}`, "click");
        if (claudeSaw(b, text)) fail("Claude Code got the message with the socket down");
        shot = shotName(t.scene, "offline-send-again", vp, "dark", "down");
        await page.screenshot(shot).catch(() => {});
        // The socket is back: one send_queued, and the message runs once.
        const back = wire.mark();
        const im = inbox.mark();
        await page.evaluate("window.__uiGoOnline()");
        if (!(await inbox.waitFor((f) => f.t === "welcome", 15_000, im))) return fail("no welcome within 15 s after the socket came back");
        await untilTrue(() => claudeRuns(b, text) > 0, 15_000);
        const ran = await untilLook(page, (s) => s.users.some((u) => u.text === fold(text) && !u.queued && !u.unsent) && !s.working && !s.spin, 15_000);
        await sleep(1000);
        const sent = acting(wire.framesSince(back));
        details.afterReconnect = sent.map((f) => f.frame);
        const sq = sent.filter((f) => f.t === "send_queued");
        if (sq.length !== 1) fail(`after the reconnect the page sent ${sq.length} send_queued frames, not one (Send again was pressed ${presses} time${presses > 1 ? "s" : ""} with the socket down)`);
        else {
          if (sq[0]!.frame.chat !== chat) fail(`the send_queued frame names the chat ${JSON.stringify(sq[0]!.frame.chat)}`);
          const ack = await waitAck(wire, sq[0]!.rid!, 5000);
          if (!ack?.ok) fail(`send_queued got ${ack ? `a refusal (${ack.code})` : "no ack"}`);
        }
        const other = sent.filter((f) => f.t !== "send_queued");
        if (other.length) fail(`after the reconnect the page also sent ${clipList(other.map(frameText))}`, "click");
        const runs = claudeRuns(b, text);
        details.claudeRuns = runs;
        if (runs !== 1) fail(`Claude Code ran the message ${runs} times, not once`);
        if (!ran.ok) fail("after the reconnect the message did not run, or its Not sent mark stays");
        const end = await lookChat(page);
        oneUser(end, text, "at the end", fail);
        quietFindingsAtEnd(end, "at the end", fail);
        issueFindings(page.takeIssues(), failures);
      } finally {
        inbox.dispose();
      }
    });
  } catch (e) {
    fail(`the check could not run: ${(e as Error).message}`, "run");
  }
  const note = "Send again with the socket down: nothing goes out, Reconnecting...; back: one send_queued, the message runs once";
  return finish({ kind: "flow", name: "offline-send-again", route: "message", scene: t.scene, size: sizeTag(vp), theme: "dark", path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

// ---------------------------------------------------------------------------------------------------------------
// Part 1's other paths (build checklist S9, S10, S16, R16 and L2; DESIGN.md 4.10, 6.10 and 9.4 done checks 3, 6 and
// 9): End it here and copy, Cancel restart and Restart now, kitespan's own Claude Code that a kill -9 left running, and
// the slow link's black hole, a wake while a snapshot is on its way, a cut inside a snapshot's tail, and long round
// trips. Each runs on a seed of its own, or on the slow link's, as the flows above do.

/** End it here and copy's lines (web/dialogs/endHere.ts) and kitespan's own two holds (web/composer/HeldLine.tsx). */
const END_WAIT_LINE = "Wait: this chat's Claude Code is still running.";
const END_ENDED_LINE = "Ended. Paste the command in your terminal now.";
const HANDED_LINE = "This chat's session was handed to your terminal.";
const FINISHING_LINE = "Claude Code is finishing the turn that was running when kitespan stopped.";
/** The D32 lines that a stop leaves under the cut turn (server/store/types.ts stopLine; 4.10). */
const STOP_LINE = {
  crash: "kitespan stopped while this chat was running. Send a message to continue.",
  restart: "kitespan restarted during this turn. Send a message to continue.",
  restartCard: "This chat was waiting for your answer when kitespan restarted. Send a message to continue.",
} as const;
const DRAIN_SEL = '[data-testid="drain-line"]';
/** The requests that a cut or a kill ends: the link's, not the page's (a flow leaves them out of its console check). */
const CUT_REQUEST = /ERR_(CONNECTION|EMPTY_RESPONSE|NETWORK|ABORTED)/;
const notCut = (issues: { kind: string; text: string }[]) => issues.filter((i) => !(i.kind === "request" && CUT_REQUEST.test(i.text)));

/** In-page: how many times a line shows in the chat's conversation (a line drawn twice counts twice). */
const LINE_COUNT = (text: string) => `(() => {
  const conv = document.querySelector('[data-testid="conversation"]');
  return (conv ? conv.textContent : "").replace(/\\s+/g, " ").split(${JSON.stringify(text)}).length - 1;
})()`;
/** In-page: how many elements of a selector show. */
const SHOWN_COUNT = (sel: string) => `[...document.querySelectorAll(${JSON.stringify(sel)})].filter((el) => el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden").length`;
/** In-page: a shown element's text, or null. */
const TEXT_OF = (sel: string) => `(() => { const el = [...document.querySelectorAll(${JSON.stringify(sel)})].find((e) => e.getClientRects().length > 0 && getComputedStyle(e).visibility !== "hidden"); return el ? el.textContent.replace(/\\s+/g, " ").trim() : null; })()`;

/** In-page: each new text of the first shown element of a selector (null while none shows), in window.__uiTexts. */
const TEXT_SAMPLER = (sel: string) => `(() => {
  const seen = (window.__uiTexts = []);
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  let last;
  const tick = () => {
    const el = [...document.querySelectorAll(${JSON.stringify(sel)})].find(shown);
    const v = el ? el.textContent.replace(/\\s+/g, " ").trim() : null;
    if (v !== last) { last = v; seen.push(v); }
  };
  clearInterval(window.__uiTextsTimer);
  window.__uiTextsTimer = setInterval(tick, 20);
  tick();
  return true;
})()`;
const TEXTS = `JSON.stringify(window.__uiTexts || [])`;

/** In-page: the message box as a hold draws it (row 80; HeldLine.tsx): the line, the field's lock and the key in Send's place. */
const HOLD_LOOK = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const one = (id) => [...document.querySelectorAll('[data-testid="' + id + '"]')].find(shown) || null;
  const field = one("composer-input");
  const held = one("composer-held");
  return {
    held: held ? held.textContent.replace(/\\s+/g, " ").trim() : null,
    field: field ? field.value : null,
    locked: field ? field.readOnly || field.disabled : null,
    send: !!(one("composer-send") || one("confirm-send")),
    again: !!one("composer-send-again"),
    stop: !!one("composer-stop"),
    copy: !!one("composer-copy"),
  };
})())`;
type HoldLook = { held: string | null; field: string | null; locked: boolean | null; send: boolean; again: boolean; stop: boolean; copy: boolean };
const lookHold = async (page: Page) => JSON.parse(await page.evaluate<string>(HOLD_LOOK)) as HoldLook;
async function untilHold(page: Page, ok: (s: HoldLook) => boolean, ms: number): Promise<{ s: HoldLook; ok: boolean }> {
  const end = Date.now() + ms;
  for (;;) {
    const s = await lookHold(page).catch(() => null);
    if (s && ok(s)) return { s, ok: true };
    if (Date.now() > end) return { s: s ?? (await lookHold(page)), ok: false };
    await sleep(100);
  }
}

/** Typing into a locked box changes nothing and sends no draft (row 80). */
async function typingFindings(page: Page, wire: Wire, when: string, fail: (text: string) => void) {
  const before = await lookHold(page);
  const m = wire.mark();
  await page.evaluate(`(() => { const el = ${FIELD}; if (el) el.focus(); return true; })()`);
  await page.send("Input.insertText", { text: "typed while held" });
  await sleep(500);
  const after = await lookHold(page);
  if (after.field !== before.field) fail(`${when}, typing changed the locked box to ${JSON.stringify(clip(after.field ?? "", 60))}`);
  const drafts = wire.framesSince(m).filter((f) => f.t === "draft").length;
  if (drafts) fail(`${when}, typing into the locked box sent ${drafts} draft frame${drafts > 1 ? "s" : ""}`);
}

/** The press of one shown button, and what it sent: its acting frames and its mutating requests. */
async function pressAndSee(page: Page, wire: Wire, selector: string): Promise<{ pressed: boolean; frames: WireFrame[]; http: WireHttp[] }> {
  const m = wire.mark();
  if (!(await pressOn(page, selector))) return { pressed: false, frames: [], http: [] };
  await waitSent(wire, m);
  return { pressed: true, frames: acting(wire.framesSince(m)), http: wire.httpSince(m) };
}

/** Open a page and wait for its load with a long deadline (a slow link), with no settle. */
async function openSlow(page: Page, url: string, ms: number): Promise<boolean> {
  const load = cdp.expect("Page.loadEventFired", { sessionId: page.session, timeoutMs: ms });
  const r = await page.send("Page.navigate", { url });
  if (r.errorText) {
    load.cancel();
    return false;
  }
  const ok = (await load.promise) !== null;
  await page.metrics();
  return ok;
}

/**
 * A message sent over a socket of the check's own, never a page's, and the end of its turn: a flow's setup, as the
 * harness's warm-up is (a long reply in a chat that no page has open).
 */
/** A setup socket sends `text` to `chat` and waits for the turn's end, or (`end` "exit") for Claude Code's exit line. */
async function serverTurn(t: Target, chat: string, text: string, ms = 60_000, end: "turn_end" | "exit" = "turn_end"): Promise<void> {
  const ws = new WebSocket(`${t.base.replace(/^http/, "ws")}${WIRE.path}`, { headers: { origin: t.base } });
  const frames: Record<string, any>[] = [];
  ws.onmessage = (m) => {
    if (typeof m.data !== "string") return;
    try {
      frames.push(JSON.parse(m.data) as Record<string, any>);
    } catch {}
  };
  await new Promise<void>((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error("the setup socket did not open")), 5000);
    ws.onopen = () => {
      clearTimeout(timer);
      resolve();
    };
    ws.onerror = () => {
      clearTimeout(timer);
      reject(new Error("the setup socket did not open"));
    };
  });
  const wait = async (ok: (f: Record<string, any>) => boolean, what: string) => {
    const end = Date.now() + ms;
    for (;;) {
      const hit = frames.find(ok);
      if (hit) return hit;
      if (Date.now() > end) throw new Error(`the setup socket got no ${what} in ${ms / 1000} s`);
      await sleep(50);
    }
  };
  try {
    ws.send(JSON.stringify({ t: "hello", v: PROTOCOL_VERSION, tab: "ui-check-setup" }));
    await wait((f) => f.t === "welcome", "welcome");
    ws.send(JSON.stringify({ t: "attach", chat, since: 0, epoch: null }));
    await wait((f) => f.t === "attached" && f.chat === chat, "attached");
    const uuid = crypto.randomUUID();
    ws.send(JSON.stringify({ t: "send", rid: uuid, chat, uuid, text, draftRev: null, uploads: [] }));
    const ack = await wait((f) => f.t === "ack" && f.rid === uuid, "ack");
    if (!ack.ok) throw new Error(`the setup message was refused: ${ack.error?.code}`);
    await wait((f) => f.t === "ev" && f.chat === chat && f.e?.k === end, end === "exit" ? "exit line" : "end of the turn");
  } finally {
    try {
      ws.close();
    } catch {}
  }
}

/** In-page: Copy the command's dialog: its line, its command, and each button's place (scrolled into view first). */
const TERMINAL_LOOK = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const fold = (s) => (s || "").replace(/\\s+/g, " ").trim();
  const dlg = [...document.querySelectorAll('[data-testid="dialog-terminal"]')].find(shown) || null;
  const button = (id) => {
    const el = [...document.querySelectorAll('[data-testid="' + id + '"]')].find(shown);
    if (!el) return null;
    el.scrollIntoView({ block: "nearest", inline: "nearest", behavior: "instant" });
    const r = el.getBoundingClientRect();
    const d = dlg ? dlg.getBoundingClientRect() : null;
    const at = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
    const row = el.parentElement;
    return {
      text: fold(el.textContent), w: Math.round(r.width), h: Math.round(r.height), disabled: !!el.disabled,
      inView: r.left >= -0.5 && r.top >= -0.5 && r.right <= innerWidth + 0.5 && r.bottom <= innerHeight + 0.5,
      inDialog: !d || (r.left >= d.left - 0.5 && r.right <= d.right + 0.5 && r.top >= d.top - 0.5 && r.bottom <= d.bottom + 0.5),
      textCut: el.scrollWidth > el.clientWidth + 1,
      rowCut: !!row && row.scrollWidth > row.clientWidth + 1,
      covered: !!at && !(at === el || el.contains(at)),
    };
  };
  const line = dlg ? dlg.querySelector('[data-testid="end-here-line"]') : null;
  const code = dlg ? dlg.querySelector("pre code") : null;
  const notice = dlg ? dlg.querySelector('[data-testid="dialog-notice"]') : null;
  // Every button of the dialog, Close among them: a row that overflows to the left cuts a button with no scroll width.
  const d = dlg ? dlg.getBoundingClientRect() : null;
  const cut = (dlg ? [...dlg.querySelectorAll("button")].filter(shown) : []).filter((el) => {
    const r = el.getBoundingClientRect();
    return !(r.left >= d.left - 0.5 && r.right <= d.right + 0.5 && r.left >= -0.5 && r.right <= innerWidth + 0.5) || el.scrollWidth > el.clientWidth + 1;
  }).map((el) => fold(el.getAttribute("aria-label") || el.textContent) || el.getAttribute("data-testid") || "a button");
  return { dialog: !!dlg, line: line ? fold(line.textContent) : null, command: code ? fold(code.textContent) : null, notice: notice ? fold(notice.textContent) : null, fork: button("confirm-copy-fork"), end: button("confirm-end-here"), copy: button("confirm-copy"), cut };
})())`;
type DlgButton = { text: string; w: number; h: number; disabled: boolean; inView: boolean; inDialog: boolean; textCut: boolean; rowCut: boolean; covered: boolean };
type TerminalLook = { dialog: boolean; line: string | null; command: string | null; notice: string | null; fork: DlgButton | null; end: DlgButton | null; copy: DlgButton | null; cut: string[] };
const lookTerminal = async (page: Page) => JSON.parse(await page.evaluate<string>(TERMINAL_LOOK)) as TerminalLook;
async function untilTerminal(page: Page, ok: (s: TerminalLook) => boolean, ms: number): Promise<{ s: TerminalLook; ok: boolean }> {
  const end = Date.now() + ms;
  for (;;) {
    const s = await lookTerminal(page).catch(() => null);
    if (s && ok(s)) return { s, ok: true };
    if (Date.now() > end) return { s: s ?? (await lookTerminal(page)), ok: false };
    await sleep(100);
  }
}

/** A dialog button shows whole: inside the window and the dialog, its words not cut, its row not cut, nothing over it. */
function buttonFindings(b: DlgButton | null, name: string, vp: Viewport, fail: (text: string) => void, warn: (text: string) => void) {
  if (!b) return fail(`the dialog shows no ${name}`);
  if (b.text !== name) fail(`the dialog's ${name} button reads ${JSON.stringify(b.text)}`);
  const bad = [!b.inView && "past the window's edge", !b.inDialog && "outside the dialog", b.textCut && "its words cut", b.rowCut && "its row cut", b.covered && "covered"].filter(Boolean);
  if (bad.length) fail(`${name} is ${bad.join(", ")} (${b.w}x${b.h} px)`);
  if (b.disabled) fail(`${name} is off`);
  if (vp.touch && (b.w < 44 || b.h < 44)) warn(`${name} is ${b.w}x${b.h} px, under the 44 px touch target`);
}

/**
 * S16 end-here (done check 6), at 1100x800, 834x1194 and 390x844 (touch), one seed: during a paced turn,
 * /c/<chat>/terminal opened as its own document shows Copy a fork command and End it here and copy, each whole and
 * inside the dialog. A press copies the plain resume command inside the click and sends one end_here (ack: ending);
 * the dialog says Wait while the chat's Claude Code still runs, then Ended once its row sleeps, and a reload of the
 * dialog says Ended again and sends nothing. On the chat, the hand-over hold: its line, the box locked (typing changes
 * nothing) and Send again in Send's place, also after a reload; Send again sends one send_queued, and then the line
 * goes and Send is back.
 */
async function endHereFlow(t: Target, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow"): void => void failures.push({ code, text });
  const warn = (text: string, code = "target"): void => void warnings.push({ code, text });
  const chat = EX.chat;
  const chatPath = `/c/${chat}`;
  const termPath = `${chatPath}/terminal`;
  // About 18 s: the turn still runs for a while after the press, so Wait shows and the box can be read meanwhile.
  const prompt = pacedPrompt(6000, 120, 150);
  const plain = new RegExp(`^cd .+ && claude --resume ${IDS.sessions.upload}$`);
  let shot: string | undefined;
  try {
    await withPage(vp, "dark", async (page, wire) => {
      const inbox = new Inbox(cdp, page);
      try {
        await cdp.send("Browser.grantPermissions", { permissions: ["clipboardReadWrite", "clipboardSanitizedWrite"], origin: t.base, browserContextId: page.contextId }).catch(() => {});
        await page.navigate(t.base + chatPath);
        await waitShown(page, ["chat", "composer"]);
        page.takeIssues();
        if (!(await sendFromBox(page, prompt))) return fail("the chat shows no message box with Send");
        if (!(await untilLook(page, (s) => s.working > 0 || Object.values(s.texts).some((x) => x.startsWith("Part 1")), 10_000)).ok) return fail("the paced turn did not start");
        // The dialog's own route as a new document, while the turn runs.
        const opened = wire.mark();
        await page.navigate(t.base + termPath);
        await waitShown(page, ["dialog-terminal", "confirm-end-here"], 8000);
        const d0 = await lookTerminal(page);
        details.dialog = d0;
        buttonFindings(d0.fork, "Copy a fork command", vp, fail, warn);
        buttonFindings(d0.end, "End it here and copy", vp, fail, warn);
        if (d0.cut.length) fail(`the dialog cuts ${clipList(d0.cut.map((x) => JSON.stringify(x)))} at its edge or the window's`);
        stateFindings(await page.probe(), vp, failures, "the dialog, ");
        quietFindings(wire, opened, null, failures, "the dialog before a press, ");
        shot = shotName(t.scene, "end-here", vp, "dark", "dialog");
        await page.screenshot(shot).catch(() => {});
        await page.evaluate(TEXT_SAMPLER('[data-testid="end-here-line"]'));

        // The press: the plain command on the clipboard, then one end_here.
        const im = inbox.mark();
        const press = await pressAndSee(page, wire, '[data-testid="confirm-end-here"]');
        if (!press.pressed) return fail("no End it here and copy to press");
        details.sent = press.frames.map((f) => f.frame);
        if (press.http.length) fail(`End it here and copy also sent ${clipList(press.http.map(httpText))}`);
        // Wait while the turn runs: the box behind the dialog offers no Send again yet (it would invite a second writer).
        const waiting = await untilTerminal(page, (d) => d.line === END_WAIT_LINE || d.line === END_ENDED_LINE, 8000);
        if (waiting.s.line === END_WAIT_LINE) {
          const hw = await lookHold(page);
          details.holdWhileWait = hw;
          if (hw.again) fail("while the chat's Claude Code still runs, the box offers Send again (a second writer before the paste)");
          if (hw.send) fail("while the chat's Claude Code still runs after End it here, the box offers Send");
        } else warnings.push({ code: "flow", text: "the chat's Claude Code ended before the box could be read during Wait" });
        const end = press.frames.find((f) => f.t === "end_here");
        if (press.frames.length !== 1 || !end) fail(`End it here and copy sent ${clipList(press.frames.map(frameText)) || "nothing"}; expected one end_here`);
        if (end) {
          if (end.frame.chat !== chat) fail(`the end_here frame names the chat ${JSON.stringify(end.frame.chat)}`);
          const ack = await inbox.waitFor((f) => f.t === "ack" && f.rid === end.rid, 5000, im);
          details.ack = ack?.f ?? null;
          if (!ack?.f.ok) fail(`end_here got ${ack ? `a refusal (${ack.f.error?.code})` : "no ack"}`);
          else if (ack.f.result?.ending !== true) fail(`end_here during a turn answered ${JSON.stringify(ack.f.result)}, not ending`);
        }
        const copied = await page.evaluate<string | null>(`navigator.clipboard.readText().catch(() => null)`).catch(() => null);
        details.clipboard = copied;
        if (copied === null) warn("the clipboard could not be read back", "copy");
        else if (!plain.test(copied.trim())) fail(`the clipboard holds ${JSON.stringify(clip(copied, 120))}, not the plain resume command`);

        // Then Ended once the chat's row sleeps.
        const ended = await untilTerminal(page, (d) => d.line === END_ENDED_LINE, 40_000);
        const said = JSON.parse(await page.evaluate<string>(TEXTS)) as (string | null)[];
        details.lines = said;
        details.ended = ended.s;
        if (!said.includes(END_WAIT_LINE)) fail(`while the turn ran the dialog never said "${END_WAIT_LINE}" (it said ${clipList(said.map((x) => JSON.stringify(x)))})`);
        if (!ended.ok) fail(`40 s after the press the dialog says ${JSON.stringify(ended.s.line)}, not "${END_ENDED_LINE}"`);
        // The order only where the sampler saw both lines: it can miss the last one when the dialog's line is redrawn (the
        // phone), and the check above has already read Ended from the dialog itself.
        else if (said.includes(END_WAIT_LINE) && said.includes(END_ENDED_LINE) && said.indexOf(END_WAIT_LINE) > said.indexOf(END_ENDED_LINE)) fail("the dialog said Ended before Wait");
        if (ended.s.command !== null && !plain.test(ended.s.command)) fail(`after End it here the dialog shows ${JSON.stringify(ended.s.command)}, not the plain command`);
        const more = acting(wire.framesSince(opened)).filter((f) => f.t !== "send");
        if (more.length !== 1) fail(`from the dialog's open to Ended the page sent ${clipList(more.map(frameText))}, not one end_here`);
        stateFindings(await page.probe(), vp, failures, "the dialog after Ended, ");
        await page.screenshot(shotName(t.scene, "end-here", vp, "dark", "ended")).catch(() => {});

        // A reload of /c/<chat>/terminal while the chat is handed to the terminal: Ended again, nothing sent.
        const r1 = wire.mark();
        await page.reload();
        await waitShown(page, ["dialog-terminal"], 8000);
        const d1 = await untilTerminal(page, (d) => d.line === END_ENDED_LINE, 6000);
        details.dialogReloaded = d1.s;
        if (d1.s.cut.length) fail(`after the reload the dialog cuts ${clipList(d1.s.cut.map((x) => JSON.stringify(x)))} at its edge or the window's`);
        if (!d1.ok) fail(`after a reload of ${termPath} the dialog says ${JSON.stringify(d1.s.line)}, not "${END_ENDED_LINE}"`);
        if (d1.s.command !== null && !plain.test(d1.s.command)) fail(`after the reload the dialog shows ${JSON.stringify(d1.s.command)}, not the plain command`);
        quietFindings(wire, r1, null, failures, "after the dialog's reload, ");

        // The chat: the hand-over hold, also after a reload.
        await page.navigate(t.base + chatPath);
        await waitShown(page, ["chat", "composer"]);
        for (const when of ["on the chat", "after a reload of the chat"]) {
          if (when !== "on the chat") {
            await page.reload();
            await waitShown(page, ["chat", "composer"]);
          }
          const h = await untilHold(page, (x) => x.held !== null, 6000);
          details[when === "on the chat" ? "hold" : "holdReloaded"] = h.s;
          if (h.s.held !== HANDED_LINE) fail(`${when} the box's line is ${JSON.stringify(h.s.held)}, not "${HANDED_LINE}"`);
          if (!h.s.locked) fail(`${when} the handed chat's box takes typing`);
          if (!h.s.again) fail(`${when} no Send again shows in Send's place`);
          if (h.s.send) fail(`${when} Send shows while the chat is handed to the terminal`);
          if (h.s.copy) fail(`${when} Continue in a copy shows in place of Send again`);
          stateFindings(await page.probe(), vp, failures, `${when}, `);
        }
        await typingFindings(page, wire, "while handed", fail);
        await page.screenshot(shotName(t.scene, "end-here", vp, "dark", "handed")).catch(() => {});

        // Send again: one send_queued; the hold ends and Send is back.
        const im2 = inbox.mark();
        const again = await pressAndSee(page, wire, '[data-testid="composer-send-again"]');
        if (!again.pressed) return fail("no Send again to press");
        details.sendAgain = again.frames.map((f) => f.frame);
        const sq = again.frames.find((f) => f.t === "send_queued");
        if (again.frames.length !== 1 || !sq) fail(`Send again sent ${clipList(again.frames.map(frameText)) || "nothing"}; expected one send_queued`);
        else {
          if (sq.frame.chat !== chat) fail(`the send_queued frame names the chat ${JSON.stringify(sq.frame.chat)}`);
          const ack = await inbox.waitFor((f) => f.t === "ack" && f.rid === sq.rid, 5000, im2);
          if (!ack?.f.ok) fail(`send_queued got ${ack ? `a refusal (${ack.f.error?.code})` : "no ack"}`);
        }
        const free = await untilHold(page, (x) => x.held === null && x.send && !x.again && x.locked === false, 8000);
        details.afterSendAgain = free.s;
        if (!free.ok) fail(`after Send again the box shows ${JSON.stringify(free.s)}, not the box with Send and no line`);
        quietFindingsAtEnd(await lookChat(page), "after Send again", fail);
        stateFindings(await page.probe(), vp, failures, "at the end, ");
        issueFindings(page.takeIssues(), failures);
        const left = await emptyChatBox(page);
        if (left) warnings.push({ code: "flow", text: `the box could not be emptied at the end (${JSON.stringify(left)})` });
      } finally {
        inbox.dispose();
      }
    });
  } catch (e) {
    fail(`the check could not run: ${(e as Error).message}`, "run");
  }
  const note = "End it here and copy during a turn: both buttons whole, the plain command copied, one end_here, Wait then Ended (and after a reload), the hand-over hold with Send again, one send_queued";
  return finish({ kind: "flow", name: "end-here", route: "terminal", scene: t.scene, size: sizeTag(vp), theme: "dark", path: termPath, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/** One page of a two-page flow: the page, what it sent and what it got. */
type FlowPage = { page: Page; wire: Wire; inbox: Inbox };
async function openFlowPage(vp: Viewport, pages: FlowPage[]): Promise<FlowPage> {
  const page = await Page.open(cdp, vp, "dark");
  const p = { page, wire: new Wire(cdp, page), inbox: new Inbox(cdp, page) };
  pages.push(p);
  return p;
}
async function closeFlowPages(pages: FlowPage[]) {
  for (const p of pages) {
    p.inbox.dispose();
    p.wire.dispose();
    await p.page.close();
  }
}

/** The restart dialog's default button says it waits ("Restart when they finish"): a press then never restarts at once. */
const restartWaits = async (page: Page) => (await page.evaluate<string | null>(TEXT_OF('[data-testid="confirm-restart"]'))) === "Restart when they finish";

/** Press Restart when they finish in the dialog: one POST /api/restart {when: "finish"}, 202, and the drain line. */
async function askRestart(A: FlowPage, when: string, fail: (text: string) => void): Promise<boolean> {
  if (!(await restartWaits(A.page))) {
    fail(`${when}, the dialog's button does not say Restart when they finish (nothing runs any more), so the check presses nothing`);
    return false;
  }
  const at = A.inbox.posts.length;
  const r = await pressAndSee(A.page, A.wire, '[data-testid="confirm-restart"]');
  const asked = r.http;
  if (asked.length !== 1 || asked[0]!.path !== "/api/restart" || asked[0]!.method !== "POST") fail(`${when}, Restart when they finish sent ${clipList(asked.map(httpText)) || "nothing"}; expected one POST /api/restart`);
  else if (asked[0]!.status !== 202) fail(`${when}, POST /api/restart answered ${asked[0]!.status}, not 202`);
  const body = A.inbox.posts.slice(at).find((x) => x.path === "/api/restart")?.body ?? null;
  if (body && JSON.parse(body).when !== "finish") fail(`${when}, POST /api/restart asked ${body}, not {"when":"finish"}`);
  return asked.length === 1;
}

/** The drain line on a page: exactly one shows (by the list or on the chat), within `ms`. */
async function drainFindings(page: Page, when: string, fail: (text: string) => void, ms = 5000): Promise<number> {
  let n = 0;
  for (const end = Date.now() + ms; Date.now() < end; await sleep(100)) {
    n = await page.evaluate<number>(SHOWN_COUNT(DRAIN_SEL));
    if (n > 0) break;
  }
  await sleep(300);
  n = await page.evaluate<number>(SHOWN_COUNT(DRAIN_SEL));
  if (n !== 1) fail(`${when}, the chat's page shows ${n} drain lines, not one`);
  return n;
}

/**
 * S9 restart-cancel (done check 3), at 1100x800 and 390x844 (touch), one seed: during a paced turn the restart dialog
 * (page A) asks Restart when they finish; the chat's page (B) shows one drain line, and a send there is held queued and
 * never reaches Claude Code; then Cancel restart, from the dialog the first time and from the chat's drain line the
 * second: one POST /api/restart/cancel, the drain line goes from both pages, the dialog asks again, and the held
 * message reaches Claude Code exactly once, with the same server (no bye, no new epoch). At the end every turn is done
 * and nothing keeps working.
 */
async function restartCancelFlow(t: Target, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow"): void => void failures.push({ code, text });
  const chatPath = `/c/${EX.chat}`;
  const dialogPath = "/settings/about/restart";
  const prompt = pacedPrompt(8000, 200, 150);
  const held = ["the dialog", "the drain line"].map((_, i) => `Held while a restart waits ${vp.name}-${i + 1}-${Date.now().toString(36)}`);
  const b = t.booted!;
  const pages: FlowPage[] = [];
  let shot: string | undefined;
  const body = async (): Promise<void> => {
    const B = await openFlowPage(vp, pages);
    await B.page.navigate(t.base + chatPath);
    await waitShown(B.page, ["chat", "composer"]);
    const epoch0 = (await B.inbox.waitFor((f) => f.t === "welcome", 5000))?.f.epoch as string | undefined;
    if (!epoch0) return fail("the chat's page got no welcome");
    B.page.takeIssues();
    if (!(await sendFromBox(B.page, prompt))) return fail("the chat shows no message box with Send");
    if (!(await untilLook(B.page, (s) => s.working > 0 || Object.values(s.texts).some((x) => x.startsWith("Part 1")), 10_000)).ok) return fail("the paced turn did not start");
    const A = await openFlowPage(vp, pages);
    await A.page.navigate(t.base + dialogPath);
    await waitShown(A.page, ["dialog-restart", "confirm-restart"], 8000);
    const rounds: Record<string, unknown>[] = [];
    details.rounds = rounds;
    for (const [i, from] of (["the dialog", "the chat's drain line"] as const).entries()) {
      const when = `cancel ${i + 1} (${from})`;
      const round: Record<string, unknown> = { from };
      rounds.push(round);
      if (!(await askRestart(A, when, fail))) break;
      round.drainLines = await drainFindings(B.page, `${when}, while the restart waits`, fail);
      let cancelShows = false;
      for (const end = Date.now() + 5000; !cancelShows && Date.now() < end; await sleep(100)) cancelShows = (await A.page.evaluate<number>(SHOWN_COUNT('[data-testid="confirm-cancel-restart"]'))) > 0;
      if (!cancelShows) fail(`${when}, the dialog shows no Cancel restart while the restart waits`);
      // A send while the restart waits: held queued, never given to Claude Code.
      const im = B.inbox.mark();
      const sent = await (async () => {
        const m = B.wire.mark();
        if (!(await sendFromBox(B.page, held[i]!))) return null;
        await waitSent(B.wire, m);
        return acting(B.wire.framesSince(m)).find((f) => f.t === "send") ?? null;
      })();
      if (!sent) {
        fail(`${when}, no Send while the restart waits`);
        break;
      }
      const ack = await B.inbox.waitFor((f) => f.t === "ack" && f.rid === sent.rid, 5000, im);
      round.heldAck = ack?.f ?? null;
      if (!ack?.f.ok) fail(`${when}, the send while the restart waits got ${ack ? `a refusal (${ack.f.error?.code})` : "no ack"}`);
      else if (ack.f.result?.queued !== true) fail(`${when}, the send while the restart waits was not held (ack ${JSON.stringify(ack.f.result)})`);
      if (!(await untilLook(B.page, (s) => s.users.some((u) => u.text === fold(held[i]!) && u.queued && !u.foot), 5000)).ok) fail(`${when}, the held message is not drawn queued`);
      if (claudeSaw(b, held[i]!)) fail(`${when}, Claude Code got the held message before Cancel restart`);
      // Cancel restart.
      const P = i === 0 ? A : B;
      const sel = i === 0 ? '[data-testid="confirm-cancel-restart"]' : `${DRAIN_SEL} [data-testid="drain-cancel"]`;
      const c = await pressAndSee(P.page, P.wire, sel);
      round.cancel = { pressed: c.pressed, http: c.http.map(httpText), frames: c.frames.map(frameText) };
      if (!c.pressed) {
        fail(`${when}, no Cancel restart to press on ${i === 0 ? "the dialog" : "the chat's drain line"}`);
        break;
      }
      if (c.http.length !== 1 || c.http[0]!.path !== "/api/restart/cancel" || c.http[0]!.method !== "POST") fail(`${when}, Cancel restart sent ${clipList(c.http.map(httpText)) || "nothing"}; expected one POST /api/restart/cancel`);
      else if (c.http[0]!.status !== 200) fail(`${when}, POST /api/restart/cancel answered ${c.http[0]!.status}`);
      if (c.frames.length) fail(`${when}, Cancel restart also sent ${clipList(c.frames.map(frameText))}`);
      // The drain line goes from both pages; the dialog asks again; the held message reaches Claude Code once.
      let gone = false;
      for (const end = Date.now() + 5000; !gone && Date.now() < end; await sleep(100)) gone = (await B.page.evaluate<number>(SHOWN_COUNT(DRAIN_SEL))) + (await A.page.evaluate<number>(SHOWN_COUNT(DRAIN_SEL))) === 0;
      if (!gone) fail(`${when}, the drain line still shows after Cancel restart`);
      let asks = false;
      for (const end = Date.now() + 5000; !asks && Date.now() < end; await sleep(100)) asks = await A.page.evaluate<boolean>(`!!document.querySelector('[data-testid="confirm-restart"]') && !document.querySelector('[data-testid="restart-line"]')`);
      if (!asks) fail(`${when}, after Cancel restart the dialog does not ask again`);
      await untilTrue(() => claudeSaw(b, held[i]!) > 0, 10_000);
      round.claudeSaw = claudeSaw(b, held[i]!);
      if (!claudeSaw(b, held[i]!)) fail(`${when}, Claude Code never got the held message after Cancel restart`);
    }
    shot = shotName(t.scene, "restart-cancel", vp, "dark", "after");
    await B.page.screenshot(shot).catch(() => {});
    // The end: the turn and the held messages ran, each once, on the same server.
    const done = await untilLook(B.page, (s) => !s.working && !s.spin && held.every((h) => s.users.some((u) => u.text === fold(h) && !u.queued && !u.unsent)), 60_000);
    await sleep(800);
    const s1 = await lookChat(B.page);
    details.end = s1;
    if (!done.ok) fail("the turn and the held messages did not all end within 60 s");
    for (const h of held) oneUser(s1, h, "at the end", fail);
    details.claude = held.map((h) => ({ got: claudeSaw(b, h), ran: claudeRuns(b, h) }));
    for (const h of held) if (claudeRuns(b, h) !== 1) fail(`at the end Claude Code ran ${JSON.stringify(clip(h, 50))} ${claudeRuns(b, h)} times, not once`);
    quietFindingsAtEnd(s1, "at the end", fail);
    for (const p of pages) {
      const byes = p.inbox.since(0, (f) => f.t === "bye").length;
      const epochs = [...new Set(p.inbox.since(0, (f) => f.t === "welcome").map((f) => f.epoch))];
      if (byes) fail(`a page got ${byes} bye frame${byes > 1 ? "s" : ""}, though every restart was cancelled`);
      if (epochs.some((e) => e !== epoch0)) fail("a page got a welcome from another server, though every restart was cancelled");
    }
    stateFindings(await B.page.probe(), vp, failures, "the chat at the end, ");
    for (const [i, p] of pages.entries()) issueFindings(p.page.takeIssues(), failures, i === 0 ? "the chat's page: " : "the dialog's page: ");
  };
  try {
    await body();
  } catch (e) {
    fail(`the check could not run: ${(e as Error).message}`, "run");
  } finally {
    await closeFlowPages(pages);
  }
  const note = "Restart when they finish twice during a paced turn, each held send queued; Cancel restart from the dialog, then from the chat's drain line: each held message reaches Claude Code once, the same server";
  return finish({ kind: "flow", name: "restart-cancel", route: "restart", scene: t.scene, size: sizeTag(vp), theme: "dark", path: `${dialogPath} and ${chatPath}`, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * S10 restart-now (done check 3), at 1100x800 and 390x844 (touch), a fresh seed each: one chat (C) runs a paced turn,
 * the example chat (B) waits on a permission card, and the dialog (A) lists both. B's socket goes down and its Allow
 * once waits in its outbox (an old card's answer). Restart when they finish, then Restart now: from the chat's drain
 * line on the laptop, from the dialog on the phone: one POST /api/restart {when: "now"} (202), the turn is
 * interrupted, the chat's page says Restarting between bye and the new welcome, and the dialog says kitespan restarted.
 * After the new welcome C shows the turn's stop line once and nothing keeps working; B comes back, its old answer gets
 * `stale`, the card is gone and the card's stop line shows once; a reload of each chat still shows each line once.
 */
async function restartNowFlow(t: Target, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow"): void => void failures.push({ code, text });
  const turn = resumeTurn(vp.name === "phone" ? "now-phone" : "now-laptop");
  const cardChat = EX.chat;
  const runChat = IDS.chats.layers;
  const dialogPath = "/settings/about/restart";
  const prompt = pacedPrompt(8000, 200, 150);
  const fromDrain = vp.name !== "phone";
  const b = t.booted!;
  const pages: FlowPage[] = [];
  let shot: string | undefined;
  const body = async (): Promise<void> => {
    const B = await openFlowPage(vp, pages);
    await B.page.send("Page.addScriptToEvaluateOnNewDocument", { source: OFFLINE_SWITCH });
    await B.page.navigate(t.base + `/c/${cardChat}`);
    await waitShown(B.page, ["chat", "composer"]);
    B.page.takeIssues();
    if (!(await sendFromBox(B.page, turn.text))) return fail("the example chat shows no message box with Send");
    if (!(await untilLook(B.page, (s) => s.cards.length > 0, 20_000)).ok) return fail("the example chat's permission card did not open");
    const C = await openFlowPage(vp, pages);
    await C.page.navigate(t.base + `/c/${runChat}`);
    await waitShown(C.page, ["chat", "composer"]);
    const epoch0 = (await C.inbox.waitFor((f) => f.t === "welcome", 5000))?.f.epoch as string | undefined;
    if (!epoch0) return fail("the running chat's page got no welcome");
    C.page.takeIssues();
    if (!(await sendFromBox(C.page, prompt))) return fail("the second chat shows no message box with Send");
    if (!(await untilLook(C.page, (s) => s.working > 0 || Object.values(s.texts).some((x) => x.startsWith("Part 1")), 10_000)).ok) return fail("the paced turn did not start");
    const A = await openFlowPage(vp, pages);
    await A.page.navigate(t.base + dialogPath);
    await waitShown(A.page, ["dialog-restart", "confirm-restart-now"], 8000);
    const lists = { running: await A.page.evaluate<string | null>(TEXT_OF('[data-testid="restart-running"]')), cards: await A.page.evaluate<string | null>(TEXT_OF('[data-testid="restart-cards"]')) };
    details.lists = lists;
    if (!lists.running?.includes("Pick the test layers")) fail(`the dialog's Running list is ${JSON.stringify(lists.running)}, not the running chat`);
    if (!lists.cards?.includes("Fix the flaky upload test")) fail(`the dialog's Waiting for your answer list is ${JSON.stringify(lists.cards)}, not the chat with the card`);
    // An old card's answer: B's socket is down, and its Allow once waits in its outbox.
    await B.page.evaluate("window.__uiGoOffline()");
    await sleep(300);
    if (!(await pressOn(B.page, '[data-testid="card-permission"] [data-testid="confirm-once"]'))) fail("the card shows no Allow once");
    await sleep(300);
    for (const p of [A, C]) await p.page.evaluate(LINE_SAMPLER);
    // Restart when they finish, then Restart now.
    if (!(await askRestart(A, "before Restart now", fail))) return;
    if (fromDrain) await drainFindings(C.page, "while the restart waits", fail);
    const nowPage = fromDrain ? C : A;
    const nowSel = fromDrain ? `${DRAIN_SEL} [data-testid="drain-now"]` : '[data-testid="dialog-restart"] [data-testid="confirm-restart-now"]';
    const postsAt = nowPage.inbox.posts.length;
    const pressAt = Date.now();
    const byeMark = C.inbox.mark();
    const now = await pressAndSee(nowPage.page, nowPage.wire, nowSel);
    details.restartNow = { from: fromDrain ? "the drain line" : "the dialog", http: now.http.map(httpText), body: nowPage.inbox.posts.slice(postsAt).map((x) => x.body) };
    if (!now.pressed) return fail(`no Restart now to press on ${fromDrain ? "the chat's drain line" : "the dialog"}`);
    const post = now.http.filter((h) => h.path === "/api/restart" && h.method === "POST");
    if (now.http.length !== 1 || post.length !== 1) fail(`Restart now sent ${clipList(now.http.map(httpText)) || "nothing"}; expected one POST /api/restart`);
    else if (post[0]!.status !== null && post[0]!.status !== 202) fail(`POST /api/restart answered ${post[0]!.status}, not 202`);
    const nowBody = nowPage.inbox.posts.slice(postsAt).find((x) => x.path === "/api/restart")?.body ?? null;
    if (nowBody && JSON.parse(nowBody).when !== "now") fail(`Restart now asked ${nowBody}, not {"when":"now"}`);
    details.focusAfterNow = await nowPage.page.evaluate<string>(`(() => { const a = document.activeElement; return a ? (a.getAttribute("data-testid") || a.tagName.toLowerCase()) : "none"; })()`).catch(() => "unknown");
    const bye = await C.inbox.waitFor((f) => f.t === "bye", 20_000, byeMark);
    if (!bye) return fail("no bye within 20 s of Restart now");
    if (bye.f.reason !== "restart") fail(`the bye says ${JSON.stringify(bye.f.reason)}, not restart`);
    if (!b.trace().some((l) => l.t === "control" && (l as { subtype?: unknown }).subtype === "interrupt" && Number(l.at) >= pressAt)) fail("Claude Code saw no interrupt after Restart now");
    const welcomes = await Promise.all([A, C].map((p) => p.inbox.waitFor((f) => f.t === "welcome" && f.epoch !== epoch0, 40_000)));
    if (welcomes.some((w) => !w)) return fail("a page got no welcome from the new server within 40 s");
    details.epochs = { before: epoch0, after: welcomes[0]!.f.epoch };
    await sleep(1500);
    // The Restarting line on the chat's page and the dialog's line.
    const linesA = JSON.parse(await A.page.evaluate<string>(LINES)) as LineSample[];
    const linesC = JSON.parse(await C.page.evaluate<string>(LINES)) as LineSample[];
    details.lines = { dialog: linesA, chat: linesC };
    if (!saidBetween(linesC, bye.at, welcomes[1]!.at + 2000, (x) => x.conn === "restarting" || x.chat === RESTARTING_LINE)) fail(`the chat's page never said "${RESTARTING_LINE}" between bye and the new welcome`);
    if (!linesA.some((x) => x.dialog === RESTARTING_LINE)) fail(`the dialog never said "${RESTARTING_LINE}"`);
    const dialogEnd = await A.page.evaluate<string | null>(TEXT_OF('[data-testid="restart-line"]'));
    if (dialogEnd !== RESTARTED_LINE) fail(`after the restart the dialog says ${JSON.stringify(dialogEnd)}, not "${RESTARTED_LINE}"`);
    // C: the turn's stop line once, nothing working.
    const cEnd = await untilLook(C.page, (s) => s.stopLine && !s.working && !s.spin, 15_000);
    details.running = cEnd.s;
    const nRun = await C.page.evaluate<number>(LINE_COUNT(STOP_LINE.restart));
    if (nRun !== 1) fail(`after Restart now the running chat shows "${STOP_LINE.restart}" ${nRun} times, not once`);
    quietFindingsAtEnd(cEnd.s, "the running chat after Restart now", fail);
    shot = shotName(t.scene, "restart-now", vp, "dark", "after");
    await C.page.screenshot(shot).catch(() => {});
    // B comes back: its old answer gets stale, the card is gone, the card's line once.
    const bMark = B.wire.mark();
    const bIn = B.inbox.mark();
    await B.page.evaluate("window.__uiGoOnline()");
    const bWelcome = await B.inbox.waitFor((f) => f.t === "welcome" && f.epoch !== epoch0, 30_000, bIn);
    if (!bWelcome) return fail("the page with the old card got no welcome from the new server within 30 s");
    await sleep(1500);
    const answers = acting(B.wire.framesSince(bMark)).filter((f) => f.t === "answer");
    const answerAck = answers[0] ? await B.inbox.waitFor((f) => f.t === "ack" && f.rid === answers[0]!.rid, 5000, bIn) : null;
    details.oldAnswer = { sent: answers.length, ack: answerAck?.f ?? null };
    if (answers.length !== 1) fail(`after the restart the old card's answer went ${answers.length} times, not once`);
    else if (!answerAck) fail("the old card's answer got no ack from the new server");
    else if (answerAck.f.ok || answerAck.f.error?.code !== "stale") fail(`the old card's answer got ${answerAck.f.ok ? "an ok ack" : `a refusal (${answerAck.f.error?.code})`}, not stale`);
    const bEnd = await untilLook(B.page, (s) => !s.cards.length && s.stopLine, 10_000);
    details.card = bEnd.s;
    if (bEnd.s.cards.length) fail("after the restart the old card still shows");
    const nCard = await B.page.evaluate<number>(LINE_COUNT(STOP_LINE.restartCard));
    if (nCard !== 1) fail(`after Restart now the chat that waited on its card shows "${STOP_LINE.restartCard}" ${nCard} times, not once`);
    // A reload of each chat: each line still once.
    for (const [p, line, what] of [[B, STOP_LINE.restartCard, "the card's chat"], [C, STOP_LINE.restart, "the running chat"]] as const) {
      await p.page.reload();
      await waitShown(p.page, ["chat", "composer"], 8000);
      await untilLook(p.page, (s) => s.stopLine, 5000);
      const n = await p.page.evaluate<number>(LINE_COUNT(line));
      if (n !== 1) fail(`after a reload ${what} shows its stop line ${n} times, not once`);
      stateFindings(await p.page.probe(), vp, failures, `${what} after a reload, `);
    }
    for (const [i, p] of pages.entries()) issueFindings(notCut(p.page.takeIssues()), failures, ["the card's page: ", "the running chat's page: ", "the dialog's page: "][i]);
  };
  try {
    await body();
  } catch (e) {
    fail(`the check could not run: ${(e as Error).message}`, "run");
  } finally {
    await closeFlowPages(pages);
  }
  const note = `Restart now from ${fromDrain ? "the chat's drain line" : "the dialog"} with a running turn and a waiting card: one POST, an interrupt, Restarting then kitespan restarted, each stop line once (and after a reload), the old card's answer stale`;
  return finish({ kind: "flow", name: "restart-now", route: "restart", scene: t.scene, size: sizeTag(vp), theme: "dark", path: `${dialogPath}, /c/${runChat} and /c/${cardChat}`, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * R16 finishing (done check 2), at 1100x800 and 390x844 (touch), one seed whose fake claude finishes its turn after its
 * host is gone (finishTurnOnStdinEnd, as Claude Code 2.1.317 does): during a paced turn the server gets a kill -9 and
 * starts again on the same state. The page dials the new server; the chat shows kitespan's own hold ("Claude Code is
 * finishing ..."), its box locked (typing changes nothing) with Stop in Send's place and no Continue in a copy. Stop
 * sends one interrupt (turn 0): the old Claude Code gets SIGTERM and ends, the hold ends, the history is read again (a
 * snapshot), the cut turn's stop line shows once, also after a reload, and nothing keeps working.
 */
async function finishingFlow(t: Target, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow"): void => void failures.push({ code, text });
  const chat = EX.chat;
  const path = `/c/${chat}`;
  const prompt = pacedPrompt(6000, 150, 150);
  const b = t.booted!;
  let shot: string | undefined;
  try {
    await withPage(vp, "dark", async (page, wire) => {
      const inbox = new Inbox(cdp, page);
      try {
        await page.navigate(t.base + path);
        await waitShown(page, ["chat", "composer"]);
        const epoch0 = (await inbox.waitFor((f) => f.t === "welcome", 5000))?.f.epoch as string | undefined;
        if (!epoch0) return fail("the chat's page got no welcome");
        page.takeIssues();
        if (!(await sendFromBox(page, prompt))) return fail("the chat shows no message box with Send");
        if (!(await untilLook(page, (s) => Object.values(s.texts).some((x) => x.startsWith("Part 1")), 10_000)).ok) return fail("the paced turn did not start");
        // An earlier run on this seed left its own stop line in the history.
        const lines0 = await page.evaluate<number>(LINE_COUNT(STOP_LINE.crash));
        details.stopLinesBefore = lines0;
        // The ledger notes the chat's claude process (R16) a moment after it starts.
        await sleep(1500);
        const before = claudeProcesses(b).alive;
        details.before = before;
        const crashed = await b.crash();
        details.crash = { ...crashed, server: b.pid };
        const w = await inbox.waitFor((f) => f.t === "welcome" && f.epoch !== epoch0, 30_000);
        if (!w) return fail("the page got no welcome from the new server within 30 s of the kill -9");
        const orphans = claudeProcesses(b).alive.filter((p) => before.includes(p));
        details.orphans = orphans;
        if (!orphans.length) warnings.push({ code: "flow", text: "the old Claude Code had already ended when the new server started, so no hold was due" });
        // kitespan's own hold while its old Claude Code finishes the turn.
        const h = await untilHold(page, (x) => x.held !== null, 10_000);
        details.hold = h.s;
        if (h.s.held !== FINISHING_LINE) fail(`after the kill -9 the box's line is ${JSON.stringify(h.s.held)}, not "${FINISHING_LINE}"`);
        if (!h.s.locked) fail("while the old Claude Code finishes, the box takes typing");
        if (!h.s.stop) fail("while the old Claude Code finishes, no Stop shows in Send's place");
        if (h.s.send) fail("while the old Claude Code finishes, Send shows");
        if (h.s.copy) fail("while kitespan's own Claude Code finishes, Continue in a copy shows");
        stateFindings(await page.probe(), vp, failures, "while it finishes, ");
        await typingFindings(page, wire, "while the old Claude Code finishes", fail);
        shot = shotName(t.scene, "finishing", vp, "dark", "held");
        await page.screenshot(shot).catch(() => {});
        // Stop: one interrupt for turn 0; the old process ends; the hold ends; the history is read again.
        const im = inbox.mark();
        const pressAt = Date.now();
        const stop = await pressAndSee(page, wire, '[data-testid="composer-stop"]');
        if (!stop.pressed) return fail("no Stop to press while the old Claude Code finishes");
        details.stop = stop.frames.map((f) => f.frame);
        const intr = stop.frames.find((f) => f.t === "interrupt");
        if (stop.frames.length !== 1 || !intr) fail(`Stop sent ${clipList(stop.frames.map(frameText)) || "nothing"}; expected one interrupt`);
        else {
          if (intr.frame.chat !== chat || intr.frame.turn !== 0) fail(`the interrupt names ${JSON.stringify({ chat: intr.frame.chat, turn: intr.frame.turn })}, not this chat and turn 0`);
          const ack = await inbox.waitFor((f) => f.t === "ack" && f.rid === intr.rid, 8000, im);
          if (!ack?.f.ok) fail(`the interrupt got ${ack ? `a refusal (${ack.f.error?.code})` : "no ack"}`);
        }
        if (orphans.length && !(await untilTrue(() => b.trace().some((l) => l.t === "sigterm" && Number(l.at) >= pressAt), 8000))) fail("the old Claude Code got no SIGTERM after Stop");
        if (orphans.length && !(await untilTrue(() => claudeProcesses(b).alive.every((p) => !orphans.includes(p)), 10_000))) fail("the old Claude Code still runs 10 s after Stop");
        const free = await untilHold(page, (x) => x.held === null && x.send && x.locked === false, 20_000);
        details.afterStop = free.s;
        if (!free.ok) fail(`after Stop the box shows ${JSON.stringify(free.s)}, not the box with Send and no line`);
        // The history comes a moment after the box frees (integration U3: the check read it at once and failed once in
        // a full run): it waits up to 5 s for the snapshot, and records how long it took.
        const freedAt = Date.now();
        const snap = await inbox.waitFor((f) => f.t === "snapshot" && f.chat === chat, 5000, im);
        details.snapshotAfterFreeMs = snap ? Math.max(0, Date.now() - freedAt) : null;
        if (!snap) fail("after the hold ended the page did not read the history again (no snapshot within 5 s)");
        const look = await untilLook(page, (s) => s.stopLine && !s.working && !s.spin, 8000);
        details.end = look.s;
        const n = (await page.evaluate<number>(LINE_COUNT(STOP_LINE.crash))) - lines0;
        if (n !== 1) fail(`after Stop ended the turn that the kill -9 left running, "${STOP_LINE.crash}" shows ${n} more times, not once`);
        quietFindingsAtEnd(look.s, "after Stop", fail);
        await page.reload();
        await waitShown(page, ["chat", "composer"]);
        await untilLook(page, (s) => s.stopLine, 5000);
        const n2 = (await page.evaluate<number>(LINE_COUNT(STOP_LINE.crash))) - lines0;
        if (n2 !== 1) fail(`after a reload the stop line shows ${n2} more times, not once`);
        const h2 = await lookHold(page);
        if (h2.held) fail(`after a reload the box still says ${JSON.stringify(h2.held)}`);
        stateFindings(await page.probe(), vp, failures, "at the end, ");
        issueFindings(notCut(page.takeIssues()), failures);
      } finally {
        inbox.dispose();
      }
    });
  } catch (e) {
    fail(`the check could not run: ${(e as Error).message}`, "run");
  }
  const note = "a kill -9 during a paced turn: the new server holds the chat while the old Claude Code finishes (its line, the box locked, Stop); Stop ends it, the history is read again, the stop line once";
  return finish({ kind: "flow", name: "finishing", route: "chat", scene: t.scene, size: sizeTag(vp), theme: "dark", path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/** The heartbeat's longest time to notice a silent link: a tick every 15 s judges 35 s of silence (web/net/socket.ts). */
const NOTICE_MAX_MS = WIRE.silenceMs + WIRE.pingEveryMs;
/** The black hole's length: past the longest notice, so the page notices while the link is still silent. */
const HOLE_MS = Math.max(GAP_S * 1000, NOTICE_MAX_MS + 10_000);
/** The page's Reconnecting... line: the chat's own, or the list's foot. */
const RECONNECTING_SEL = '[data-testid="chat-reconnecting"], [data-testid="connection"][data-state="reconnecting"]';

/** Chrome reached the server only through the proxy (every page request and socket). */
function viaProxyFindings(inbox: Inbox, proxy: NetProxy, fail: (text: string) => void, details: Record<string, unknown>) {
  const web = inbox.urls.filter((u) => /^(https?|wss?):/.test(u));
  const direct = web.filter((u) => new URL(u).host !== `127.0.0.1:${proxy.port}`);
  details.urls = { total: web.length, direct: direct.slice(0, 5) };
  if (!web.length) fail("the page made no request through the proxy");
  if (direct.length) fail(`the page reached ${clipList([...new Set(direct.map((u) => new URL(u).host))])} without the proxy`);
}

/**
 * DC9 resume-blackhole, at 390x844 (touch) and 1100x800, through the proxy (250 ms each way, 1 Mbit/s): mid-reply the
 * link goes silent (a black hole: nothing moves, nothing closes) for longer than the heartbeat's deadline, and a
 * message is typed into it: on the phone 3 s into the silence (the page may notice by the message's overdue ack), on
 * the laptop only once the page has noticed, so the laptop measures the heartbeat alone (its list foot says
 * Reconnecting... with nothing waiting). The page notices within the deadline (the measured times are reported), says
 * it is reconnecting and draws the message as not sent yet; when the link is back it dials through the proxy, gets the card
 * first and only what it missed (one attached with replay "events", no snapshot), and the message reaches Claude Code
 * exactly once; after Allow once nothing keeps working. Then a message is sent into a second silence and the page
 * reloads in it; the old socket's frames arrive late, after the reload and a Send of whatever the box got back:
 * Claude Code sees the message once.
 */
async function resumeBlackholeFlow(t: Target, proxy: NetProxy, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = { holeMs: HOLE_MS, noticeMaxMs: NOTICE_MAX_MS, link: { ...proxy.profile } };
  const fail = (text: string, code = "flow"): void => void failures.push({ code, text });
  const tag = vp.name === "phone" ? "blackhole-phone" : "blackhole-laptop";
  const turn = resumeTurn(tag);
  const a = `${turn.ids.a}-0`;
  const c = `${turn.ids.c}-0`;
  const typed = `Typed into the silent link ${tag}`;
  const reloaded = `Sent just before a reload in the silence ${tag}-${Date.now().toString(36)}`;
  const chat = EX.chat;
  const via = `http://127.0.0.1:${proxy.port}`;
  const path = `/c/${chat}`;
  const b = t.booted!;
  let shot: string | undefined;
  try {
    await withPage(vp, "dark", async (page, wire) => {
      const inbox = new Inbox(cdp, page);
      try {
        await page.navigate(via + path);
        await waitShown(page, ["chat", "composer"], 30_000);
        page.takeIssues();
        if (!(await sendFromBox(page, turn.text))) return fail("the chat shows no message box with Send");
        if (!(await untilLook(page, (s) => (s.texts[a] ?? "").length > 0, 15_000)).ok) return fail("the reply did not start");
        await page.evaluate(WATCH([{ key: "noticed", sel: RECONNECTING_SEL }, { key: "card", sel: 'section[data-testid="card-permission"]' }, { key: "reply", sel: `[data-testid="item-${a}"] .chat-assistant > div:first-child`, text: fold(RESUME_A) }]));
        const holeAt = Date.now();
        const sockets0 = inbox.wsCount();
        const cutMark = inbox.mark();
        const hole = proxy.silence(HOLE_MS);
        const typeFirst = vp.name === "phone";
        details.typed = typeFirst ? "3 s into the silence" : "once the page noticed";
        if (typeFirst) {
          await sleep(3000);
          if (!(await sendFromBox(page, typed))) fail("during the silence the box shows no Send");
        }
        // The page notices (the heartbeat sees no frame for its deadline, or a message's ack is overdue).
        let noticedAt = 0;
        for (const end = holeAt + HOLE_MS - 1500; !noticedAt && Date.now() < end; await sleep(250)) noticedAt = (JSON.parse(await page.evaluate<string>(SEEN)) as Record<string, number>).noticed ?? 0;
        details.noticeMs = noticedAt ? noticedAt - holeAt : null;
        if (!noticedAt) fail(`the page did not notice the silent link in ${HOLE_MS / 1000} s (the heartbeat's deadline is about ${NOTICE_MAX_MS / 1000} s)`);
        else {
          if (noticedAt - holeAt > NOTICE_MAX_MS + 3000) fail(`the page noticed the silent link after ${((noticedAt - holeAt) / 1000).toFixed(1)} s, past the heartbeat's deadline of about ${NOTICE_MAX_MS / 1000} s`);
          if (!typeFirst && !(await sendFromBox(page, typed))) fail("during the silence the box shows no Send");
          await sleep(600);
          const down = await lookChat(page);
          details.noticed = down;
          if (!down.reconnecting && down.conn !== "reconnecting") fail("once it noticed the silent link, the page does not say it is reconnecting");
          const du = down.users.find((u) => u.text === fold(typed));
          if (!du) fail("the message typed into the silence does not show");
          else if (!du.unsent) fail(`once it noticed, the page draws the message typed into the silence ${du.foot ? `"${du.foot}"` : "as sent"}, not as not sent yet`);
          if (down.field) fail(`during the silence the box still holds ${JSON.stringify(down.field)} after Send`);
          if (down.cards.length) fail("during the silence a card shows (the page cannot know of it)");
          shot = shotName(t.scene, "resume-blackhole", vp, "dark", "noticed");
          await page.screenshot(shot).catch(() => {});
        }
        await hole;
        const backAt = Date.now();
        details.dialsInSilence = inbox.wsCount() - sockets0;
        // The heartbeat's own judgement: the page's first new dial after the link went silent.
        const redial = inbox.dialsAt.find((x) => x > holeAt);
        details.redialMs = redial ? redial - holeAt : null;
        const welcome = await inbox.waitFor((f) => f.t === "welcome", 40_000, cutMark);
        if (!welcome) return fail("no welcome within 40 s after the link came back");
        details.backMs = welcome.at - backAt;
        const settled = await untilLook(page, (s) => s.cards.length > 0 && s.texts[a] === fold(RESUME_A) && s.users.some((u) => u.text === fold(typed) && !u.unsent), 25_000);
        await sleep(1500);
        const s1 = await lookChat(page);
        details.afterHole = s1;
        // Only what the page missed, on the socket it dialled through the proxy.
        const frames = inbox.frames.filter((x) => x.n > welcome.n && x.sock === welcome.sock && x.f.chat === chat).map((x) => x.f);
        const first = frames.find((f) => f.t === "attached" || f.t === "ev" || f.t === "snapshot");
        const attached = frames.filter((f) => f.t === "attached");
        details.attached = attached.map((f) => ({ replay: f.replay, cursor: f.cursor, seq: f.seq, cards: (f.cards ?? []).map((k: { id: string }) => k.id) }));
        if (!first || first.t !== "attached") fail(`after the silence the chat's first frame is ${first?.t ?? "none"}, not attached`);
        else if (!(first.cards ?? []).some((k: { id: string }) => k.id === turn.ids.tool)) fail("after the silence the attached frame does not give the waiting card back first");
        if (attached.length !== 1 || attached[0]!.replay !== "events") fail(`after the silence the chat got ${attached.map((f) => `attached (${f.replay})`).join(", ") || "no attached"}, not one replay of what it missed`);
        const snaps = frames.filter((f) => f.t === "snapshot").length;
        if (snaps) fail(`after the silence the chat got ${snaps} snapshot frame${snaps > 1 ? "s" : ""}`);
        if (!settled.ok) fail("after the silence the card, the whole reply or the typed message did not all show");
        if (s1.reconnecting || s1.conn === "reconnecting") fail(`after the silence the page still says ${JSON.stringify(s1.reconnecting ?? "Reconnecting...")}`);
        rowFindings(s1, { [a]: RESUME_A }, "after the silence", fail);
        for (const m of [turn.text, typed]) oneUser(s1, m, "after the silence", fail);
        // Allow once: the turn ends, the typed message runs once, nothing keeps working.
        if (!(await pressOn(page, '[data-testid="card-permission"] [data-testid="confirm-once"]'))) return fail("the card shows no Allow once after the silence");
        const done = await untilLook(page, (s) => s.texts[c] === fold(RESUME_C) && !s.cards.length && !s.working && !s.spin && s.users.filter((u) => u.text === fold(typed)).every((u) => !u.queued && !u.unsent), 30_000);
        await sleep(1500);
        const s2 = await lookChat(page);
        details.end = s2;
        if (!done.ok) fail("after Allow once the turn and the typed message did not both end");
        rowFindings(s2, { [a]: RESUME_A, [c]: RESUME_C }, "at the end", fail);
        for (const m of [turn.text, typed]) oneUser(s2, m, "at the end", fail);
        quietFindingsAtEnd(s2, "at the end", fail);
        details.claude = { got: claudeSaw(b, typed), ran: claudeRuns(b, typed) };
        if (claudeRuns(b, typed) !== 1) fail(`the fake claude ran the message typed into the silence ${claudeRuns(b, typed)} times, not once (it got it ${claudeSaw(b, typed)} times)`);
        issueFindings(notCut(page.takeIssues()), failures, "around the silence, ");

        // A reload in a second silence; the old socket's frames come 25 s after the link is back (a late retransmit).
        const quiet = proxy.silence(20_000, { lateMs: 25_000 });
        const quietAt = Date.now();
        if (!(await sendFromBox(page, reloaded))) fail("in the second silence the box shows no Send");
        await sleep(1500);
        const load = cdp.expect("Page.loadEventFired", { sessionId: page.session, timeoutMs: 90_000 });
        await page.send("Page.reload", {});
        await quiet;
        if (!(await load.promise)) return fail("the reload in the silence did not load within 70 s of the link's return");
        await page.metrics();
        await waitShown(page, ["chat", "composer"], 30_000);
        const back = await untilLook(page, (s) => s.field === reloaded || s.users.some((u) => u.text === fold(reloaded)), 15_000);
        details.afterReload = { field: back.s.field, bubbles: back.s.users.filter((u) => u.text === fold(reloaded)).length };
        if (back.s.field === reloaded) {
          // The text came back to the box: the owner presses Send before the old socket's copy lands.
          if (!(await pressOn(page, SEND_BUTTON))) fail("after the reload the box holds the message but shows no Send");
          details.sentAgain = true;
        }
        await sleep(Math.max(0, quietAt + 20_000 + 25_000 + 6000 - Date.now()));
        const s3 = await lookChat(page);
        details.afterLate = s3.users.filter((u) => u.text === fold(reloaded));
        const ran = claudeRuns(b, reloaded);
        details.reloadedClaude = { got: claudeSaw(b, reloaded), ran };
        if (ran !== 1) fail(`a message sent into a silent link, a reload in it, then Send on what the box got back: the fake claude ran it ${ran} times, not once (it got it ${claudeSaw(b, reloaded)} times)`);
        oneUser(s3, reloaded, "after the old socket's late frames", fail);
        stateFindings(await page.probe(), vp, failures, "after the reload, ");
        issueFindings(notCut(page.takeIssues()), failures, "after the reload, ");
        const left = await emptyChatBox(page);
        if (left) warnings.push({ code: "flow", text: `the box could not be emptied at the end (${JSON.stringify(left)})` });
        viaProxyFindings(inbox, proxy, fail, details);
        details.proxy = proxy.stats();
      } finally {
        inbox.dispose();
      }
    });
  } catch (e) {
    fail(`the check could not run: ${(e as Error).message}`, "run");
  }
  const noticed = typeof details.noticeMs === "number" ? `${details.typed === "once the page noticed" ? "the heartbeat alone " : "a message waiting, "}noticed after ${((details.noticeMs as number) / 1000).toFixed(1)} s, a new dial after ${typeof details.redialMs === "number" ? `${((details.redialMs as number) / 1000).toFixed(1)} s` : "none"}` : "not noticed";
  const note = `a ${HOLE_MS / 1000} s black hole mid-reply (${noticed}; the deadline about ${NOTICE_MAX_MS / 1000} s): Reconnecting, a replay of what it missed, the typed message once; a reload in a second silence with late frames: once`;
  return finish({ kind: "flow", name: "resume-blackhole", route: "chat", scene: t.scene, size: sizeTag(vp), theme: "dark", path: via + path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/** The two pages' silence: long enough for each page to notice its overdue ack and dial again into it. */
const TWO_PAGES_SILENCE_MS = 15_000;

/**
 * DC9 and D49 resume-two-pages, through the proxy: a laptop page (1100x800) and a phone page (390x844, touch), each in
 * a browser context of its own, on one chat that sleeps; the link goes silent and each page sends a message into the
 * silence. Each page draws its own message as not sent yet and none of the other's, and says it is reconnecting. When
 * the link is back, each message runs once, and both pages, and a reload of the laptop page (the server's history),
 * draw the two messages in the order Claude Code ran them, each with its reply below it, and the same rows in the same
 * order.
 */
async function resumeTwoPagesFlow(t: Target, proxy: NetProxy): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = { silenceMs: TWO_PAGES_SILENCE_MS, link: { ...proxy.profile } };
  const fail = (text: string, code = "flow"): void => void failures.push({ code, text });
  const chat = IDS.chats.parser;
  const via = `http://127.0.0.1:${proxy.port}`;
  const path = `/c/${chat}`;
  const stem = Date.now().toString(36);
  const laptop = VIEWPORTS.find((v) => v.name === "laptop")!;
  const phone = VIEWPORTS.find((v) => v.name === "phone")!;
  const b = t.booted!;
  const pages: FlowPage[] = [];
  let shot: string | undefined;
  const body = async (): Promise<void> => {
    const L = await openFlowPage(laptop, pages);
    const P = await openFlowPage(phone, pages);
    const side = [
      { p: L, name: "laptop", text: `Sent into the silence from the laptop ${stem}` },
      { p: P, name: "phone", text: `Sent into the silence from the phone ${stem}` },
    ];
    for (const x of side) {
      await x.p.page.navigate(via + path);
      await waitShown(x.p.page, ["chat", "composer"], 30_000);
      x.p.page.takeIssues();
    }
    const known = new Set((await lookChat(L.page)).rows);
    const marks = side.map((x) => x.p.inbox.mark());
    const quiet = proxy.silence(TWO_PAGES_SILENCE_MS);
    for (const x of side) {
      await sleep(1000);
      if (!(await sendFromBox(x.p.page, x.text))) fail(`in the silence the ${x.name} page shows no Send`);
    }
    // Each page notices (its message's ack is overdue): its own message not sent yet, the other's not there.
    await sleep(6000);
    for (const [i, x] of side.entries()) {
      const s = await lookChat(x.p.page);
      const other = side[1 - i]!;
      const own = s.users.find((u) => u.text === fold(x.text));
      details[`${x.name}InSilence`] = { reconnecting: s.reconnecting, conn: s.conn, own: own ?? null };
      if (!own) fail(`in the silence the ${x.name} page does not show its message`);
      else if (!own.unsent) fail(`in the silence the ${x.name} page draws its message ${own.foot ? `"${own.foot}"` : "as sent"}, not as not sent yet`);
      if (s.users.some((u) => u.text === fold(other.text))) fail(`in the silence the ${x.name} page shows the ${other.name} page's message`);
      if (!s.reconnecting && s.conn !== "reconnecting") fail(`in the silence the ${x.name} page does not say it is reconnecting`);
      if (s.field) fail(`in the silence the ${x.name} page's box still holds ${JSON.stringify(s.field)} after Send`);
    }
    shot = shotName(t.scene, "resume-two-pages", phone, "dark", "silence");
    await P.page.screenshot(shot).catch(() => {});
    await quiet;
    // Back: each page dials again through the proxy; each message runs once.
    for (const [i, x] of side.entries()) if (!(await x.p.inbox.waitFor((f) => f.t === "welcome", 40_000, marks[i]))) fail(`the ${x.name} page got no welcome within 40 s after the link came back`);
    const texts = side.map((x) => x.text);
    await untilTrue(() => texts.every((m) => claudeRuns(b, m) > 0), 30_000);
    const ranOrder = claudeRanOrder(b, texts);
    const nameOf = (m: string) => side.find((x) => x.text === m)!.name;
    details.claude = { order: ranOrder.map(nameOf), runs: Object.fromEntries(side.map((x) => [x.name, claudeRuns(b, x.text)])) };
    for (const x of side) if (claudeRuns(b, x.text) !== 1) fail(`Claude Code ran the ${x.name} page's message ${claudeRuns(b, x.text)} times, not once`);
    if (ranOrder.length !== 2) return fail(`Claude Code ran ${ranOrder.length} of the two messages`);
    const names = ranOrder.map((m) => `the ${nameOf(m)} page's`);
    const want = names.flatMap((n) => [`${n} message`, "reply"]);
    const ended = (s: ChatLook) => texts.every((m) => s.users.some((u) => u.text === fold(m) && !u.queued && !u.unsent)) && !s.working && !s.spin && turnOrder(s, ranOrder, names, known).filter((x) => x === "reply").length >= 2;
    const looks: ChatLook[] = [];
    for (const x of side) {
      const r = await untilLook(x.p.page, ended, 20_000);
      if (!r.ok) fail(`on the ${x.name} page the two messages and their replies did not all come`);
    }
    await sleep(1500);
    for (const x of side) {
      const s = await lookChat(x.p.page);
      looks.push(s);
      const order = turnOrder(s, ranOrder, names, known);
      details[`${x.name}End`] = { rows: s.rows, order };
      if (order.join() !== want.join()) fail(`the ${x.name} page draws ${order.join(" > ")}, not the server's ${want.join(" > ")}`);
      rowFindings(s, {}, `at the end, on the ${x.name} page`, fail);
      for (const m of texts) oneUser(s, m, `at the end, on the ${x.name} page`, fail);
      quietFindingsAtEnd(s, `at the end, on the ${x.name} page`, fail);
    }
    // The server's order: a reload of the laptop page draws the chat's history as the server holds it.
    await L.page.reload();
    await waitShown(L.page, ["chat", "composer"], 30_000);
    const fresh = (await untilLook(L.page, (s) => texts.every((m) => s.users.some((u) => u.text === fold(m))), 15_000)).s;
    const freshOrder = turnOrder(fresh, ranOrder, names, known);
    details.reloaded = { rows: fresh.rows, order: freshOrder };
    if (freshOrder.join() !== want.join()) fail(`after a reload the laptop page draws ${freshOrder.join(" > ")}, not ${want.join(" > ")}`);
    const ids = fresh.users.filter((u) => texts.map(fold).includes(u.text)).map((u) => u.id);
    const server = rowsFrom(fresh, ids);
    for (const [i, x] of side.entries()) {
      const rows = rowsFrom(looks[i]!, ids);
      if (rows.join() !== server.join()) fail(`from the first of the two messages on, the ${x.name} page drew the rows ${clipList(rows)}, but a reload (the server's order) draws ${clipList(server)}`);
    }
    for (const x of side) {
      stateFindings(await x.p.page.probe(), x.p === L ? laptop : phone, failures, `at the end, the ${x.name} page: `);
      issueFindings(notCut(x.p.page.takeIssues()), failures, `the ${x.name} page: `);
      viaProxyFindings(x.p.inbox, proxy, fail, (details[`${x.name}Urls`] = {}) as Record<string, unknown>);
    }
    details.proxy = proxy.stats();
  };
  try {
    await body();
  } catch (e) {
    fail(`the check could not run: ${(e as Error).message}`, "run");
  } finally {
    await closeFlowPages(pages);
  }
  const first = (details.claude as { order?: string[] } | undefined)?.order?.[0];
  const note = `a laptop and a phone page each send into a ${TWO_PAGES_SILENCE_MS / 1000} s silence: each once, ${first ? `the ${first} page's first, ` : ""}both pages and a reload in the server's order`;
  return finish({ kind: "flow", name: "resume-two-pages", route: "chat", scene: t.scene, size: "laptop", theme: "dark", path: via + path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/** The long reply of the wake flow: about 200,000 characters (the snapshot is about 210 KiB). */
const WAKE_REPLY = pacedPrompt(200_000, 200, 5);

/**
 * DC9 resume-wake, at 390x844 (touch) and 1100x800, through the proxy: a fresh page opens a chat with a long reply in
 * its history (its snapshot takes seconds on the link), and a focus event (the owner coming back to the tab) comes
 * 300 ms after its attached frame: the page keeps its one socket and gets one snapshot, and the reply shows.
 */
async function resumeWakeFlow(t: Target, proxy: NetProxy, vp: Viewport, chat: string): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = { link: { ...proxy.profile } };
  const fail = (text: string, code = "flow"): void => void failures.push({ code, text });
  const via = `http://127.0.0.1:${proxy.port}`;
  const path = `/c/${chat}`;
  let shot: string | undefined;
  try {
    await withPage(vp, "dark", async (page) => {
      const inbox = new Inbox(cdp, page);
      let attachedAt = 0;
      inbox.onFrame = (x) => {
        if (attachedAt || x.f.t !== "attached" || x.f.chat !== chat) return;
        attachedAt = x.at;
        setTimeout(() => void page.evaluate("(window.dispatchEvent(new Event('focus')), true)").catch(() => {}), 300);
      };
      try {
        if (!(await openSlow(page, via + path, 60_000))) return fail("the chat did not load through the proxy within 60 s");
        const snap = await inbox.waitFor((f) => f.t === "snapshot" && f.chat === chat, 40_000);
        if (!snap) return fail("the chat's snapshot did not come within 40 s");
        // Room for a second socket and a second snapshot, had the wake dialled again.
        await sleep(8000);
        const s = await lookChat(page);
        const reply = Math.max(0, ...Object.values(s.texts).map((x) => x.length));
        const snaps = inbox.frames.filter((x) => x.f.t === "snapshot" && x.f.chat === chat);
        details.focusAfterAttachedMs = attachedAt ? 300 : null;
        details.sockets = inbox.wsCount();
        details.snapshots = snaps.map((x) => ({ at: x.at - (attachedAt || x.at), kib: Math.round(x.bytes / 1024) }));
        details.replyChars = reply;
        if (!attachedAt) fail("no attached frame came for the chat, so no focus was sent");
        if (inbox.wsCount() !== 1) fail(`a focus 300 ms after attached, while the snapshot was on its way, left the page with ${inbox.wsCount()} sockets, not one`);
        if (snaps.length !== 1) fail(`the chat's snapshot (${Math.round((snaps[0]?.bytes ?? 0) / 1024)} KiB) came ${snaps.length} times, not once`);
        if (reply < 100_000) fail(`the long reply shows ${reply} characters`);
        if (s.dups.length) fail(`rows drawn twice: ${clipList(s.dups)}`);
        if (s.reconnecting || (s.conn && s.conn !== "connected")) fail(`the page says ${JSON.stringify(s.reconnecting ?? s.conn)}`);
        shot = shotName(t.scene, "resume-wake", vp, "dark");
        await page.screenshot(shot).catch(() => {});
        issueFindings(notCut(page.takeIssues()), failures);
        viaProxyFindings(inbox, proxy, fail, details);
      } finally {
        inbox.dispose();
      }
    });
  } catch (e) {
    fail(`the check could not run: ${(e as Error).message}`, "run");
  }
  const kib = (details.snapshots as { kib: number }[] | undefined)?.[0]?.kib;
  const note = `a fresh page on a chat with a long reply (a ${kib ?? "?"} KiB snapshot) and a focus 300 ms after attached: one socket, one snapshot`;
  return finish({ kind: "flow", name: "resume-wake", route: "chat", scene: t.scene, size: sizeTag(vp), theme: "dark", path: via + path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * In-page, after OFFLINE_SWITCH: a cut at a frame. When sessionStorage's "ui-cut" names a chat as the document starts,
 * the page's socket goes down (window.__uiGoOffline) right after the page has read that chat's snapshot frame and
 * `more` frames of the chat after it, inside the same message event, so no later frame reaches the page; what it
 * passed is in window.__uiCut. A CDP frame event comes too late for that: the tail is in by then.
 */
const CUT_AFTER = `(() => {
  let cut = null;
  try { cut = JSON.parse(sessionStorage.getItem("ui-cut") || "null"); sessionStorage.removeItem("ui-cut"); } catch {}
  if (!cut) return;
  const Inner = window.WebSocket;
  function Cutting(url, protocols) {
    const ws = new Inner(url, protocols);
    if (!ws || typeof ws.addEventListener !== "function") return ws;
    let handler = null;
    Object.defineProperty(ws, "onmessage", { configurable: true, get() { return handler; }, set(fn) { handler = fn; } });
    ws.addEventListener("message", (ev) => {
      if (handler) handler.call(ws, ev);
      if (!cut) return;
      let f = null;
      try { f = JSON.parse(ev.data); } catch {}
      if (!f || f.chat !== cut.chat) return;
      if (cut.passed === undefined) {
        if (f.t !== "snapshot") return;
        cut.passed = 0;
        cut.tail = typeof f.tail === "number" ? f.tail : null;
      } else cut.passed++;
      if (cut.passed < cut.more) return;
      window.__uiCut = { tail: cut.tail, passed: cut.passed };
      cut = null;
      window.__uiGoOffline();
    });
    return ws;
  }
  Cutting.prototype = Inner.prototype;
  for (const k of ["CONNECTING", "OPEN", "CLOSING", "CLOSED"]) Cutting[k] = Inner[k];
  window.WebSocket = Cutting;
})();`;
/** The tail's frames that the page reads before the cut (inside the tail, never at its end). */
const CUT_TAIL_AT = 3;

/**
 * DC9 resume-tail, at 390x844 (touch) and 1100x800, through the proxy: while a long reply streams (about 15 s) the page
 * reloads, so its attach gets a snapshot with a tail of the reply's pieces, and the page's socket goes down inside the
 * tail, right after the page has read the snapshot frame and three frames after it (CUT_AFTER); then back: each
 * reply's text shows exactly once, the card shows, and after Allow once the turn ends with nothing working.
 */
async function resumeTailFlow(t: Target, proxy: NetProxy, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = { link: { ...proxy.profile } };
  const fail = (text: string, code = "flow"): void => void failures.push({ code, text });
  const tag = vp.name === "phone" ? "tail-phone" : "tail-laptop";
  const turn = resumeTurn(tag);
  const reply = resumeReply(tag);
  const a = `${turn.ids.a}-0`;
  const c = `${turn.ids.c}-0`;
  const chat = EX.chat;
  const via = `http://127.0.0.1:${proxy.port}`;
  const path = `/c/${chat}`;
  let shot: string | undefined;
  try {
    await withPage(vp, "dark", async (page) => {
      const inbox = new Inbox(cdp, page);
      try {
        await page.send("Page.addScriptToEvaluateOnNewDocument", { source: OFFLINE_SWITCH });
        await page.send("Page.addScriptToEvaluateOnNewDocument", { source: CUT_AFTER });
        await page.navigate(via + path);
        await waitShown(page, ["chat", "composer"], 30_000);
        page.takeIssues();
        if (!(await sendFromBox(page, turn.text))) return fail("the chat shows no message box with Send");
        if (!(await untilLook(page, (s) => (s.texts[a] ?? "").length > 0, 15_000)).ok) return fail("the reply did not start");
        await sleep(1500);
        // The reload: the new document's attach gets a snapshot and its tail, and the socket goes inside the tail.
        await page.evaluate(`(sessionStorage.setItem("ui-cut", ${JSON.stringify(JSON.stringify({ chat, more: CUT_TAIL_AT }))}), true)`);
        const load = cdp.expect("Page.loadEventFired", { sessionId: page.session, timeoutMs: 30_000 });
        await page.send("Page.reload", {});
        await load.promise;
        let cut: { tail: number | null; passed: number } | null = null;
        for (const end = Date.now() + 20_000; !cut && Date.now() < end; await sleep(100)) cut = await page.evaluate<{ tail: number | null; passed: number } | null>("window.__uiCut || null").catch(() => null);
        if (!cut) return fail("the reloaded page got no snapshot with frames after it within 20 s, so nothing was cut");
        details.cut = { tail: cut.tail, framesAfterTheSnapshot: cut.passed };
        if (cut.tail === null) fail("the snapshot frame carries no tail count");
        else if (cut.passed >= cut.tail) warnings.push({ code: "flow", text: `the cut came after the whole tail (${cut.passed} of ${cut.tail} frames), not inside it` });
        await sleep(1500);
        const back = inbox.mark();
        await page.evaluate("window.__uiGoOnline()");
        const whole = await untilLook(page, (s) => s.texts[a] === fold(reply) && s.cards.length > 0, 40_000);
        await sleep(800);
        const s1 = await lookChat(page);
        details.afterCut = s1;
        details.attached = inbox.since(back, (f) => f.t === "attached" && f.chat === chat).map((f) => ({ replay: f.replay, cursor: f.cursor, seq: f.seq }));
        if (!whole.ok) fail(s1.texts[a] ? `after the cut inside the tail, the reply reads ${s1.texts[a]!.length} characters, not its ${fold(reply).length} once` : "after the cut inside the tail, the reply does not show");
        rowFindings(s1, { [a]: reply }, "after the cut inside the tail", fail);
        oneUser(s1, turn.text, "after the cut inside the tail", fail);
        shot = shotName(t.scene, "resume-tail", vp, "dark", "back");
        await page.screenshot(shot).catch(() => {});
        if (!(await pressOn(page, '[data-testid="card-permission"] [data-testid="confirm-once"]'))) return fail("the card shows no Allow once after the cut");
        const done = await untilLook(page, (s) => s.texts[c] === fold(RESUME_C) && !s.cards.length && !s.working && !s.spin, 30_000);
        await sleep(1000);
        const s2 = await lookChat(page);
        details.end = s2;
        if (!done.ok) fail("after Allow once the turn did not end with its last reply whole");
        rowFindings(s2, { [a]: reply, [c]: RESUME_C }, "at the end", fail);
        quietFindingsAtEnd(s2, "at the end", fail);
        stateFindings(await page.probe(), vp, failures, "at the end, ");
        issueFindings(notCut(page.takeIssues()), failures);
        viaProxyFindings(inbox, proxy, fail, details);
      } finally {
        inbox.dispose();
      }
    });
  } catch (e) {
    fail(`the check could not run: ${(e as Error).message}`, "run");
  }
  const cutAt = details.cut as { tail: number | null; framesAfterTheSnapshot: number } | undefined;
  const note = `a reload mid-reply and a cut inside the snapshot's tail (${cutAt ? `after ${cutAt.framesAfterTheSnapshot} of its ${cutAt.tail ?? "?"} frames` : "no cut"}): each reply's text once`;
  return finish({ kind: "flow", name: "resume-tail", route: "chat", scene: t.scene, size: sizeTag(vp), theme: "dark", path: via + path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/** The round trips of the long-link flow (in-flight Wi-Fi at its worst): 1.2 s and 2.6 s. */
const LONG_RTTS = [1200, 2600] as const;

/**
 * DC9 resume-rtt, at 390x844 (touch) and 1100x800, through the proxy with a round trip of 1.2 s and then 2.6 s (the
 * same 1 Mbit/s): a fresh page on the chat loads and connects (its attach is answered) within 60 s, and keeps that one
 * socket for 3 s more. The dials and the times are reported.
 */
async function resumeRttFlow(t: Target, proxy: NetProxy, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow"): void => void failures.push({ code, text });
  const chat = EX.chat;
  const via = `http://127.0.0.1:${proxy.port}`;
  const path = `/c/${chat}`;
  const was = { ...proxy.profile };
  let shot: string | undefined;
  try {
    for (const rtt of LONG_RTTS) {
      proxy.setLink({ delayMs: rtt / 2 });
      const run: Record<string, unknown> = {};
      details[`${rtt} ms`] = run;
      await withPage(vp, "dark", async (page) => {
        const inbox = new Inbox(cdp, page);
        try {
          const l0 = Date.now();
          if (!(await openSlow(page, via + path, 90_000))) return fail(`at a ${rtt / 1000} s round trip the page did not load within 90 s`);
          run.loadMs = Date.now() - l0;
          const att = await inbox.waitFor((f) => f.t === "attached" && f.chat === chat, 60_000);
          run.dials = inbox.wsCount();
          run.welcomes = inbox.since(0, (f) => f.t === "welcome").length;
          if (!att) return fail(`at a ${rtt / 1000} s round trip the page never connected in 60 s after its load: ${inbox.wsCount()} dials, ${run.welcomes} welcomes`);
          run.connectMs = att.at - l0;
          const dials = inbox.wsCount();
          await sleep(3000);
          run.dialsAfter = inbox.wsCount() - dials;
          if (inbox.wsCount() !== dials) fail(`at a ${rtt / 1000} s round trip the page dialled again within 3 s of its attach (${inbox.wsCount() - dials} more)`);
          const s = await untilLook(page, (x) => x.rows.length > 0, 20_000);
          if (!s.ok) fail(`at a ${rtt / 1000} s round trip the chat shows no row`);
          if (s.s.reconnecting || (s.s.conn && s.s.conn !== "connected")) fail(`at a ${rtt / 1000} s round trip the page says ${JSON.stringify(s.s.reconnecting ?? s.s.conn)}`);
          if (rtt === LONG_RTTS[LONG_RTTS.length - 1]) {
            shot = shotName(t.scene, "resume-rtt", vp, "dark");
            await page.screenshot(shot).catch(() => {});
          }
          issueFindings(notCut(page.takeIssues()), failures, `at ${rtt / 1000} s, `);
          viaProxyFindings(inbox, proxy, fail, run);
        } finally {
          inbox.dispose();
        }
      });
    }
  } catch (e) {
    fail(`the check could not run: ${(e as Error).message}`, "run");
  } finally {
    proxy.setLink(was);
  }
  const parts = LONG_RTTS.map((rtt) => {
    const r = details[`${rtt} ms`] as { connectMs?: number; dials?: number } | undefined;
    return `${rtt / 1000} s: ${r?.connectMs !== undefined ? `connected after ${(r.connectMs / 1000).toFixed(1)} s` : "not connected"}, ${r?.dials ?? 0} dial${r?.dials === 1 ? "" : "s"}`;
  });
  const note = `a fresh page at a long round trip (${parts.join("; ")})`;
  return finish({ kind: "flow", name: "resume-rtt", route: "chat", scene: t.scene, size: sizeTag(vp), theme: "dark", path: via + path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

// ---------------------------------------------------------------------------------------------------------------
// Running

// ---------------------------------------------------------------------------------------------------------------
// Part 2 (iteration 4): worktrees and an environment's variables (row 73 and D60; DESIGN.md 4.4 "A worktree chat's
// folder", 6.7, 6.9 and 6.10; build checklist W2 to W9, E3, E6 and E7). Each size gets the worktree scene's own seed
// (test/click/seed/repos.ts: ~/code/shop with two commits, ~/code/hooks with a WorktreeCreate hook, ~/code/linked
// whose .claude is a symbolic link, and the seed's plain ~/Documents), and the flows run on it in this order, the later
// ones on what the earlier made: worktree-new adds the shop project with Worktree on and two chats (row 100: their
// worktrees in ~/code/shop/.claude/worktrees); worktree-gone removes their worktrees between two starts;
// worktree-archive-delete makes two more chats there; env-editor works on the scratch project's variables; worktree-off
// adds the Documents, hooks and linked projects. Every git call of the flows is seed/repos.ts's, on the seed's own
// repositories, with no user or system git config.

/** The part 2 flows, in the order they run on one seed. */
const PART2_FLOWS = ["worktree-new", "worktree-gone", "worktree-archive-delete", "env-editor", "worktree-off"] as const;
type Part2Flow = (typeof PART2_FLOWS)[number];

/** DESIGN.md's words for part 2 (4.4, 6.7, 6.9, 6.10), as the page must show them. */
const P2_WORDS = {
  notGit: "This folder is not a git repository.",
  hook: "Your Claude Code settings have a WorktreeCreate hook, which kitespan's worktrees would not run.",
  link: "This repository's .claude or .claude/worktrees is a symbolic link or not a folder, so kitespan makes no worktree here.",
  gone: "This chat's worktree is not there any more.",
  again: "Make it again from its branch",
  project: "Continue in the project folder",
  worktreeOf: (folder: string) => `Worktree of ${folder}`,
  archiveKeeps: (n: number) => `Its worktree has changes in ${n} files, so it stays on disk.`,
  kept: (path: string) => `Its worktree stays at ${path}.`,
  deleteClean: (path: string) => `This also removes its worktree, ${path}.`,
  branchStays: (branch: string) => `Its branch ${branch} stays: it holds commits that no other branch has.`,
  envTitle: "Environment variables",
  none: "None for this environment",
  mask: "••••••••",
  pathLine: "Line 3: Set PATH in your shell profile or your start-env file, then restart kitespan.",
  removeAsk: (name: string) => `Remove ${name}? Chats stop getting it from their next start.`,
  refused: "Claude Code would not continue this chat in its worktree.",
  copy: "Continue in a copy",
  without: "Continue without the worktree",
} as const;

/** The variable whose value the env-editor flow plants; the fake claude's trace holds only its SHA-256 (fixture envHash). */
const P2_SECRET = "PAYMENTS_API_KEY";

/** What the part 2 flows share on one seed. */
interface Part2Seed {
  b: Booted;
  /** The shop project's id, once worktree-new added it. */
  project: string | null;
  /** worktree-new's two chats. */
  chats: string[];
}

type P2Ledger = { cwd: string; sessionId: string | null; archivedAt: string | null; worktree?: { path: string; root: string; branch: string; left?: boolean; kept?: boolean } };

/** A chat's ledger on disk (the store writes it soon after a change); null when there is none. */
function p2Ledger(b: Booted, chat: string): P2Ledger | null {
  try {
    return JSON.parse(readFileSync(join(b.seed.state, "chats", `${chat}.json`), "utf8")) as P2Ledger;
  } catch {
    return null;
  }
}

/** The fake claude's starts of one session: the SDK writes `--session-id=<id>` on the first, `--resume=<id>` after. */
function p2Starts(b: Booted, sid: string | null | undefined): TraceLine[] {
  if (!sid) return [];
  return b.trace().filter((l) => l.t === "start" && Array.isArray(l.args) && (l.args as string[]).some((a) => a === sid || a.endsWith(`=${sid}`)));
}
const p2RootArgs = (l: TraceLine | undefined) => ((l?.args as string[] | undefined) ?? []).filter((a) => a.startsWith("--project-config-root"));
/** Where kitespan puts a chat's worktree in the shop project (row 100: its .claude/worktrees) and the branch it makes (L24). */
const p2Path = (b: Booted, chat: string) => join(b.seed.repos.shop, ".claude", "worktrees", chat.slice(0, 8));
/** The shop project's folder in the seed's data folder: kitespan's records of its worktrees in the making (row 100). */
const p2Records = (b: Booted, project: string) => join(b.seed.data, "kitespan", "worktrees", project);
/** The main checkout's git status (`--porcelain`, with untracked files): "" when the user's checkout shows nothing new. */
const p2Status = (b: Booted) => seedGit(b.seed.repos.shop, b.seed.home, ["status", "--porcelain", "--untracked-files=all"]);
const p2Branch = (chat: string) => `kitespan/${chat.slice(0, 8)}`;
const p2IsDir = (p: string) => {
  try {
    return lstatSync(p).isDirectory();
  } catch {
    return false;
  }
};

async function p2Until<T>(read: () => T | Promise<T>, ok: (v: T) => boolean, ms: number, every = 100): Promise<T> {
  const end = Date.now() + ms;
  let v = await read();
  while (!ok(v) && Date.now() < end) {
    await sleep(every);
    v = await read();
  }
  return v;
}

/** The part 2 parts of the page: New environment's rows and options, the editor, the Environment detail, the lines. */
const P2_STATE = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const all = (sel, root) => [...(root || document).querySelectorAll(sel)].filter(shown);
  const one = (sel, root) => all(sel, root)[0] || null;
  const text = (el) => (el ? el.textContent.replace(/\\s+/g, " ").trim() : null);
  const sw = (el) => (el ? { checked: !!el.checked, disabled: !!el.disabled } : null);
  const btn = (el) => (el ? { disabled: !!el.disabled, title: el.getAttribute("title") } : null);
  const value = (el) => (el ? el.value : null);
  const dlg = one('[data-testid="dialog-new-environment"]');
  const form = one('[data-testid="new-chat"]');
  const chip = form ? form.querySelector('[data-pick="project"] .scr-chip-text') : null;
  const editor = one('[data-testid="project-environment"]');
  const detail = one('[data-testid="side-environment"][data-detail="true"]');
  const starts = all('[data-testid="start-line"]');
  const start = starts.length ? starts[starts.length - 1] : null;
  const conv = one('[data-testid="conversation"]');
  return {
    path: location.pathname + location.search,
    chip: chip ? chip.textContent.trim() : null,
    finder: dlg ? {
      rows: all('[data-testid="env-row"]', dlg).map((r) => text(r.querySelector(".scr-pick-name") || r)),
      active: all('[data-testid="env-row"][aria-selected="true"]', dlg).map((r) => text(r.querySelector(".scr-pick-name") || r)),
      worktree: sw(dlg.querySelector('[data-testid="new-env-worktree"]')),
      off: text(one('[data-testid="worktree-off"]', dlg)),
      vars: text(one('[data-testid="new-env-vars"]', dlg)),
      use: btn(dlg.querySelector('[data-testid="confirm-use-folder"]')),
      error: text(one(".scr-env-error", dlg)),
    } : null,
    editor: editor ? {
      worktree: sw(editor.querySelector('[data-testid="worktree-switch"]')),
      off: text(one('[data-testid="worktree-off"]', editor)),
      rows: all('[data-testid="env-row"][data-name]', editor).map((li) => ({ name: li.getAttribute("data-name"), mask: text(li.querySelector(".env-mask")) })),
      none: text(one('[data-testid="env-none"]', editor)),
      notes: all('[data-testid="env-notes"] li', editor).map((li) => ({ text: text(li), bad: li.classList.contains("is-bad") })),
      field: value(editor.querySelector('[data-testid="env-field"]')),
      add: btn(one('[data-testid="env-add"]', editor)),
      addSave: btn(one('[data-testid="confirm-env-add"]', editor)),
      newValue: value(editor.querySelector('[data-testid="env-new-value"]')),
      editSave: btn(one('[data-testid="confirm-env-save"]', editor)),
      ask: text(one('[data-testid="env-remove-ask"] p', editor)),
      refused: all('[data-testid="env-refused"] li', editor).map(text),
    } : null,
    facts: detail ? all(".side-fact", detail).map((li) => ({ label: text(li.querySelector(".side-fact-label")), path: text(li.querySelector(".side-path")), of: text(li.querySelector('[data-testid="worktree-of"]')), value: text(li.querySelector(".side-fact-value")) })) : null,
    start: start ? { code: start.getAttribute("data-code"), text: text(start.querySelector(".wt-start-line")), all: text(start), buttons: all("button", start).map((b) => ({ id: b.getAttribute("data-testid"), text: text(b), disabled: !!b.disabled })) } : null,
    archive: one('[data-testid="dialog-archive"]') ? { line: text(one('[data-testid="worktree-archive-line"]')), archive: !!one('[data-testid="confirm-archive"]'), unarchive: !!one('[data-testid="confirm-unarchive"]') } : null,
    del: one('[data-testid="dialog-delete"]') ? { line: text(one('[data-testid="worktree-delete-line"]')), busy: !!document.querySelector('[data-testid="worktree-delete-line"][aria-busy="true"]'), branch: text(one('[data-testid="worktree-branch-line"]')) } : null,
    kept: text(one('[data-testid="worktree-kept"]')),
    replies: conv ? all(".chat-assistant", conv).filter((r) => r.querySelector('[data-testid="copy-reply"]')).length : 0,
    box: value(document.querySelector('[data-testid="composer"] [data-testid="composer-input"]')),
  };
})())`;

type P2Switch = { checked: boolean; disabled: boolean } | null;
type P2Button = { disabled: boolean; title: string | null } | null;
interface P2Look {
  path: string;
  chip: string | null;
  finder: { rows: string[]; active: string[]; worktree: P2Switch; off: string | null; vars: string | null; use: P2Button; error: string | null } | null;
  editor: {
    worktree: P2Switch;
    off: string | null;
    rows: { name: string; mask: string | null }[];
    none: string | null;
    notes: { text: string; bad: boolean }[];
    field: string | null;
    add: P2Button;
    addSave: P2Button;
    newValue: string | null;
    editSave: P2Button;
    ask: string | null;
    refused: string[];
  } | null;
  facts: { label: string | null; path: string | null; of: string | null; value: string | null }[] | null;
  /** The last refused start's line: its code, its first line's words, all its text (Claude Code's line too) and its buttons. */
  start: { code: string | null; text: string | null; all: string | null; buttons: { id: string | null; text: string | null; disabled: boolean }[] } | null;
  archive: { line: string | null; archive: boolean; unarchive: boolean } | null;
  del: { line: string | null; busy: boolean; branch: string | null } | null;
  kept: string | null;
  replies: number;
  box: string | null;
}

const p2Look = async (page: Page) => JSON.parse(await page.evaluate<string>(P2_STATE)) as P2Look;
const p2Fact = (s: P2Look, label: string) => s.facts?.find((f) => f.label === label) ?? null;

/** Settings > Appearance's looks (6.13); glass is the default, with no data-look on the root. */
const P2_LOOKS = ["glass", "paper", "mono", "editor"] as const;
type P2LookId = (typeof P2_LOOKS)[number];
const P2_OTHER_THEME: Record<Theme, Theme> = { light: "dark", dark: "light" };
/** Two animation frames: the page has drawn a change of its root's attributes or of the emulated colour scheme. */
const P2_DRAWN = `new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(() => r(true))))`;

/** One flow's own record, with its press, type and wait helpers. */
function p2Flow(page: Page, vp: Viewport, failures: Finding[], warnings: Finding[]) {
  const fail = (text: string, code = "flow") => failures.push({ code, text });
  const warn = (text: string, code = "flow") => warnings.push({ code, text });
  /** One finding per problem for the whole flow, with the places it showed (step, theme and look). */
  const layout = new Map<string, { f: Finding; at: string[] }>();
  const place = (list: Finding[], code: string, what: string, at: string) => {
    const key = `${code} ${what}`;
    const had = layout.get(key);
    if (had) {
      had.at.push(at);
      had.f.text = `${what} (${clipList(had.at, 4)})`;
      return;
    }
    const f = { code, text: `${what} (${at})` };
    list.push(f);
    layout.set(key, { f, at: [at] });
  };
  /** The opened states that `opened` checked, with how many controls under 44 px each had. */
  const checked: { step: string; theme: Theme; look: P2LookId; small: number }[] = [];
  /** The page as it is now, in the theme and look it wears: no sideways scroll, nothing past the right edge, no stub, and on touch the controls under 44 px. */
  const probeHere = async (id: string, step: string, theme: Theme, look: P2LookId) => {
    await page.evaluate(P2_DRAWN);
    const s = await page.probe();
    const at = `${step}, ${theme}${look === "glass" ? "" : `, ${look}`}`;
    if (s.scrollWidth > s.clientWidth) place(failures, "overflow", `the page scrolls sideways (scrollWidth ${s.scrollWidth} > clientWidth ${s.clientWidth})`, at);
    for (const o of s.offenders) place(failures, "edge", `past the right edge: ${o.replace(/ right=\d+$/, "")}`, at);
    for (const x of s.stubs) place(failures, "stub", `a data-stub element: ${x}`, at);
    const small = vp.touch ? await page.evaluate<string[]>(SMALL_TARGETS).catch(() => [] as string[]) : [];
    for (const x of small) place(warnings, "target", `under 44 px: ${x}`, at);
    checked.push({ step, theme, look, small: small.length });
    await page.screenshot(shotName("worktree", id, vp, theme, `${step}${look === "glass" ? "" : `-${look}`}`)).catch(() => {});
  };
  /**
   * An opened state of part 2 (a dialog's rows, a field with its problems, an ask, a line with its buttons): the probe
   * in the flow's own light theme and in dark (the emulated colour scheme, as a device's System theme), and at 390 x 844
   * in each look too (data-look on the root, as Settings > Appearance > Look sets it), with a shot of each. Nothing in
   * it acts: the page keeps its state, and the theme and the look are as before at its end.
   */
  const opened = async (id: string, step: string) => {
    const looks: readonly P2LookId[] = vp.name === "phone" ? P2_LOOKS : ["glass"];
    const before = await page.evaluate<string | null>(`document.documentElement.getAttribute("data-look")`);
    try {
      for (const look of looks) {
        await page.evaluate(`(() => { const r = document.documentElement; ${look === "glass" ? `r.removeAttribute("data-look")` : `r.setAttribute("data-look", ${JSON.stringify(look)})`}; return true; })()`);
        for (const theme of [page.theme, P2_OTHER_THEME[page.theme]]) {
          await page.send("Emulation.setEmulatedMedia", { media: "screen", features: [{ name: "prefers-color-scheme", value: theme }] });
          await probeHere(id, step, theme, look);
        }
      }
    } finally {
      await page.send("Emulation.setEmulatedMedia", { media: "screen", features: [{ name: "prefers-color-scheme", value: page.theme }] }).catch(() => {});
      await page.evaluate(`(() => { const r = document.documentElement; ${before === null ? `r.removeAttribute("data-look")` : `r.setAttribute("data-look", ${JSON.stringify(before)})`}; return true; })()`).catch(() => {});
    }
  };
  const look = () => p2Look(page);
  const until = (ok: (s: P2Look) => boolean, ms = 6000) => p2Until(look, ok, ms);
  /** A click on a laptop, a tap on touch, on the first shown match; false (and a finding) when it is not there. */
  const press = async (sel: string, what: string) => {
    const at = await page.locate(sel);
    if (!at) fail(`no ${what} to press`, "shows");
    else if (at.covered) fail(`the ${what} is covered by ${at.covered}`);
    if (!at || at.covered) return false;
    await page.press(at.x, at.y);
    await sleep(300);
    return true;
  };
  /** Type into a field as a user does: a press in it first (on touch, the keyboard's tap), then the text. */
  const type = async (sel: string, text: string, what: string) => {
    if (!(await press(sel, what))) return false;
    await page.send("Input.insertText", { text });
    await sleep(200);
    return true;
  };
  /** Replace a field's whole text, as a select-all and a paste do. */
  const replace = async (sel: string, text: string) => {
    await page.evaluate(`(() => { const el = document.querySelector(${JSON.stringify(sel)}); if (!el) return false; el.focus(); el.select(); return true; })()`);
    await page.send("Input.insertText", { text });
    await sleep(200);
  };
  const shot = async (id: string, step: string) => {
    const file = shotName("worktree", id, vp, "light", step);
    await page.screenshot(file).catch(() => {});
    return file;
  };
  return { fail, warn, look, until, press, type, replace, shot, opened, checked };
}

/** New environment from the form's folder chip, then a typed path; the dialog's state once that folder is the one row. */
async function p2Finder(page: Page, base: string, f: ReturnType<typeof p2Flow>, typed: string, name: string, ok: (s: P2Look) => boolean = () => true): Promise<P2Look | null> {
  await page.navigate(base + "/");
  await waitShown(page, ["new-chat"]);
  if (!(await f.press('[data-testid="new-chat"] [data-pick="project"]', "folder chip"))) return null;
  if (!(await f.press('[data-testid="form-new-environment"]', "New environment... row"))) return null;
  const opened = await f.until((s) => (s.finder?.rows.length ?? 0) > 0);
  if (!opened.finder) {
    f.fail("New environment does not open", "shows");
    return null;
  }
  if (!(await f.type('[data-testid="dialog-new-environment"] [data-testid="env-filter"]', typed, "filter field"))) return null;
  const s = await f.until((x) => JSON.stringify(x.finder?.rows) === JSON.stringify([name]) && JSON.stringify(x.finder?.active) === JSON.stringify([name]) && ok(x), 8000);
  if (JSON.stringify(s.finder?.rows) !== JSON.stringify([name])) f.fail(`"${typed}" leaves the rows ${JSON.stringify(s.finder?.rows)}, not ${name} alone`);
  return s;
}

/**
 * Start a chat from the new-chat form with this first message (the form at /new?project=, unless it shows already),
 * once the form's folder chip names the project: exactly one new_chat goes, for that project, its ack is ok (after the
 * worktree's checkout), the page opens the chat, and the reply comes. The chat's id, or null.
 */
async function p2Start(page: Page, wire: Wire, base: string, f: ReturnType<typeof p2Flow>, project: { id: string; name: string }, text: string, navigate = true): Promise<string | null> {
  if (navigate) {
    await page.navigate(`${base}/new?project=${project.id}`);
    await waitShown(page, ["new-chat"]);
  }
  let chip = await f.until((x) => x.chip === project.name, 4000);
  if (chip.chip !== project.name) {
    // The link opened as a new document fills the project only when the page knows its projects at its first draw
    // (web/screens/Home.tsx NewChat, from iteration 3; reported to the lead). The user's way: the folder picker.
    f.warn(`the link /new?project=${project.id}, opened as a new document, leaves the form's folder at ${JSON.stringify(chip.chip)}, not ${project.name}; picked in the folder picker instead`, "route");
    if (!(await f.press('[data-testid="new-chat"] [data-pick="project"]', "folder chip"))) return null;
    const mark = await page.evaluate<boolean>(`(() => {
      const rows = [...document.querySelectorAll('[data-testid="form-picker-project"] [role="menuitemradio"]')];
      const r = rows.find((x) => (x.querySelector(".scr-pick-name") || x).textContent.trim() === ${JSON.stringify(project.name)});
      if (r) r.setAttribute("data-check", "folder");
      return !!r;
    })()`);
    if (!mark) {
      f.fail(`the form's folder picker has no ${project.name} row`, "shows");
      return null;
    }
    if (!(await f.press('[data-check="folder"]', `${project.name} row in the folder picker`))) return null;
    chip = await f.until((x) => x.chip === project.name, 4000);
    if (chip.chip !== project.name) {
      f.fail(`a pick of ${project.name} in the folder picker leaves the form's folder at ${JSON.stringify(chip.chip)}`);
      return null;
    }
  }
  if (!(await f.type("#scr-prompt", text, "form's prompt field"))) return null;
  const m = wire.mark();
  if (!(await f.press('[data-testid="confirm-start"]', "Start button"))) return null;
  await waitSent(wire, m, 5000);
  const frames = wire.framesSince(m).filter((x) => x.t === "new_chat");
  if (frames.length !== 1 || frames[0]!.frame.text !== text || frames[0]!.frame.project !== project.id) f.fail(`Start sent ${frames.length} new_chat frames (${JSON.stringify(frames.map((x) => ({ text: x.frame.text, project: x.frame.project })))}), not one with ${JSON.stringify(text)} for ${project.id}`, "click");
  const ack = frames[0]?.rid ? await waitAck(wire, frames[0].rid, 30_000) : null;
  if (!ack?.ok) {
    f.fail(`the new_chat for ${JSON.stringify(text)} got ${ack ? `the refusal ${ack.code}` : "no ack"}`, "click");
    return null;
  }
  const at = await p2Until(() => page.evaluate<string>("location.pathname"), (p) => /^\/c\/[a-z2-7]{20}$/.test(p), 8000);
  if (!/^\/c\/[a-z2-7]{20}$/.test(at)) {
    f.fail(`Start left the page at ${at}, not the new chat`, "route");
    return null;
  }
  const done = await f.until((s) => s.replies >= 1, 20_000);
  if (done.replies < 1) f.fail(`the reply to ${JSON.stringify(text)} did not show`);
  return at.slice(3);
}

/** Send in the chat's box and wait for its reply (one more turn); false when the reply does not come. */
async function p2Send(page: Page, f: ReturnType<typeof p2Flow>, text: string): Promise<boolean> {
  const before = (await f.look()).replies;
  if (!(await sendFromBox(page, text))) {
    f.fail("no message box to send from", "shows");
    return false;
  }
  const s = await f.until((x) => x.replies > before, 20_000);
  if (s.replies <= before) f.fail(`the reply to ${JSON.stringify(text)} did not show`);
  return s.replies > before;
}

/** The chat's Environment detail (6.7): its Folder, the worktree's line, its Branch, as the page shows them. */
async function p2Detail(page: Page, base: string, f: ReturnType<typeof p2Flow>, chat: string): Promise<P2Look> {
  await page.navigate(`${base}/c/${chat}/environment`);
  return f.until((s) => !!p2Fact(s, "Folder")?.path);
}

/** The worktree checks of one chat (W3): the ledger, the folder on disk, git's list, and the fake claude's start. */
function p2WorktreeFindings(b: Booted, chat: string, root: string, f: ReturnType<typeof p2Flow>, label: string): Record<string, unknown> {
  const path = p2Path(b, chat);
  const branch = p2Branch(chat);
  const ledger = p2Ledger(b, chat);
  const start = p2Starts(b, ledger?.sessionId)[0];
  if (ledger?.cwd !== path || ledger?.worktree?.path !== path || ledger?.worktree?.branch !== branch || ledger?.worktree?.root !== root) f.fail(`${label}: the ledger has cwd ${ledger?.cwd} and worktree ${JSON.stringify(ledger?.worktree)}, not ${path} on ${branch} of ${root}`, "disk");
  if (!p2IsDir(path)) f.fail(`${label}: no worktree folder at ${path}`, "disk");
  if (branchIn(path, b.seed.home) !== branch) f.fail(`${label}: the worktree is on ${branchIn(path, b.seed.home)}, not ${branch}`, "disk");
  if (!start) f.fail(`${label}: the fake claude never started for the chat's session`, "claude");
  else {
    if (start.cwd !== path) f.fail(`${label}: the fake claude ran in ${start.cwd}, not the worktree ${path}`, "claude");
    if (JSON.stringify(p2RootArgs(start)) !== JSON.stringify([`--project-config-root=${root}`])) f.fail(`${label}: the fake claude's project config arguments are ${JSON.stringify(p2RootArgs(start))}, not the one argument --project-config-root=${root}`, "claude");
  }
  // Row 100: the worktree is inside the main checkout, which ignores it locally, so its git status stays clean.
  const status = p2Status(b);
  if (!status.ok || status.out !== "") f.fail(`${label}: the main checkout's git status after the worktree was made is ${JSON.stringify(status.out)}, not clean`, "disk");
  return { path, branch, cwd: ledger?.cwd, started: start ? { cwd: start.cwd, root: p2RootArgs(start) } : null, status: status.out };
}

/**
 * worktree-new (W2, W3, W6; row 73's New environment): the form's folder chip, New environment..., the typed path
 * ~/code/shop leaves shop as the one row; its Worktree switch is off by default and on to choose (the read for the
 * folder says a worktree can be made); nothing goes out before Use this folder, which sends exactly one POST
 * /api/projects with worktree true, and the form selects shop. Two chats started there each get a worktree of their
 * own: the folder `<shop>/.claude/worktrees/<first 8 of the chat id>` (row 100) and the branch kitespan/<the same 8>,
 * in the ledger, on disk, in `git worktree list` of the scratch repository (its main checkout and the two), and as the
 * fake claude's cwd, with the shop folder as the one argument --project-config-root=<folder>; no record in the making
 * is left in the seed's data folder. The user's checkout keeps no change: its git status is clean after each start
 * (the local ignore: Claude Code's worktrees pattern in its .git/info/exclude; no tracked file changed). The Environment
 * detail of each shows Folder = its worktree, "Worktree of <folder>" and Branch = its branch.
 */
async function worktreeNewFlow(s: Part2Seed, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const { b } = s;
  const { shop } = b.seed.repos;
  const home = b.seed.home;
  let shot: string | undefined;
  try {
    await withPage(vp, "light", async (page, wire) => {
      const inbox = new Inbox(cdp, page);
      const f = p2Flow(page, vp, failures, warnings);
      try {
        const since = wire.mark();
        const picked = await p2Finder(page, b.base, f, "~/code/shop", "shop", (x) => x.finder?.worktree?.disabled === false);
        if (!picked) return;
        details.picked = picked.finder;
        if (!picked.finder?.worktree) return void f.fail("New environment shows no Worktree switch", "shows");
        if (picked.finder.worktree.disabled || picked.finder.off) f.fail(`the Worktree switch is ${picked.finder.worktree.disabled ? "disabled" : "on"} for shop, with the line ${JSON.stringify(picked.finder.off)}`);
        if (picked.finder.worktree.checked) f.fail("the Worktree switch is on before a press (Desktop: off by default)");
        if (!picked.finder.vars?.startsWith(P2_WORDS.envTitle) || !picked.finder.vars.includes(P2_WORDS.none)) f.fail(`the variables row reads ${JSON.stringify(picked.finder.vars)}, not "${P2_WORDS.envTitle}" with "${P2_WORDS.none}"`);
        shot = await f.shot("worktree-new", "picked");
        await f.opened("worktree-new", "picked");
        if (!(await f.press('[data-testid="dialog-new-environment"] [data-testid="new-env-worktree"]', "Worktree switch"))) return;
        const on = await f.until((x) => x.finder?.worktree?.checked === true);
        if (on.finder?.worktree?.checked !== true) f.fail("a press leaves the Worktree switch off");
        quietFindings(wire, since, await recorder(page), failures, "before Use this folder: ");
        const posts0 = inbox.posts.length;
        const m = wire.mark();
        if (!(await f.press('[data-testid="dialog-new-environment"] [data-testid="confirm-use-folder"]', "Use this folder button"))) return;
        const done = await f.until((x) => !x.finder && x.chip === "shop", 8000);
        if (done.finder || done.chip !== "shop") f.fail(`after Use this folder the dialog is ${done.finder ? "open" : "closed"} and the form's folder is ${JSON.stringify(done.chip)}`);
        await sleep(300);
        const http = wire.httpSince(m);
        const posts = inbox.posts.slice(posts0);
        details.useFolder = posts.map((p) => ({ path: p.path, body: p.body }));
        const body = (() => {
          try {
            return JSON.parse(posts[0]?.body ?? "null") as Record<string, unknown> | null;
          } catch {
            return null;
          }
        })();
        if (http.length !== 1 || http[0]!.path !== "/api/projects" || http[0]!.status !== 201) f.fail(`Use this folder sent ${clipList(http.map(httpText))}; expected one POST /api/projects (201)`, "click");
        if (body?.worktree !== true) f.fail(`the POST's body says worktree ${JSON.stringify(body?.worktree)}, not true`, "click");
        if (mutating(wire.framesSince(m)).length) f.fail(`Use this folder also sent ${clipList(mutating(wire.framesSince(m)).map(frameText))}`, "click");
        const projects = ((await (await fetch(`${b.base}/api/projects`)).json()) as { projects: { id: string; cwd: string; worktree?: boolean }[] }).projects;
        const project = projects.find((p) => p.cwd === shop);
        if (!project) return void f.fail(`no project has ${shop} after Use this folder`, "disk");
        if (project.worktree !== true) f.fail("the shop project's Worktree option is off after Use this folder with the switch on", "disk");
        s.project = project.id;

        // Two chats, two worktrees, two branches: the first from the form that Use this folder left, the second at /new.
        for (const [i, text] of ["Add a coupon field to the cart", "Write tests for the tax rounding"].entries()) {
          const chat = await p2Start(page, wire, b.base, f, { id: project.id, name: "shop" }, text, i > 0);
          if (!chat) return;
          s.chats.push(chat);
          details[`chat${i + 1}`] = p2WorktreeFindings(b, chat, shop, f, `chat ${i + 1}`);
        }
        const [a, c] = s.chats as [string, string];
        const listed = worktreeList(shop, home);
        details.worktreeList = listed;
        const want = [{ path: shop, branch: "main" }, ...s.chats.map((x) => ({ path: p2Path(b, x), branch: p2Branch(x) }))];
        const key = (l: { path: string; branch: string | null }[] | null) => JSON.stringify([...(l ?? [])].sort((x, y) => x.path.localeCompare(y.path)));
        if (key(listed) !== key(want)) f.fail(`git worktree list in the scratch repository is ${JSON.stringify(listed)}, not the main checkout and the two worktrees`, "disk");
        if (p2Path(b, a) === p2Path(b, c) || p2Branch(a) === p2Branch(c)) f.fail("the two chats share a worktree or a branch", "disk");
        const list = (dir: string) => {
          try {
            return readdirSync(dir).sort();
          } catch {
            return [];
          }
        };
        // Row 100: the worktrees in the project's .claude/worktrees; the data folder keeps no record once each is made.
        const folders = list(join(shop, ".claude", "worktrees"));
        const records = list(p2Records(b, project.id));
        details.worktreesFolder = folders;
        details.dataFolder = records;
        if (JSON.stringify(folders) !== JSON.stringify(s.chats.map((x) => x.slice(0, 8)).sort())) f.fail(`shop's .claude/worktrees holds ${JSON.stringify(folders)}, not the two chats' folders`, "disk");
        if (records.length) f.fail(`the data folder's worktrees/${project.id} holds ${JSON.stringify(records)}, not nothing`, "disk");
        const status = p2Status(b);
        if (!status.ok || status.out !== "") f.fail(`the user's checkout changed: git status says ${JSON.stringify(status.out)}`, "disk");
        const exclude = (() => {
          try {
            return readFileSync(join(shop, ".git", "info", "exclude"), "utf8").split("\n");
          } catch {
            return [];
          }
        })();
        if (!exclude.includes("**/.claude/worktrees/")) f.fail("the main checkout's .git/info/exclude has no **/.claude/worktrees/ line", "disk");
        const tracked = seedGit(shop, home, ["diff", "--quiet", "HEAD"]);
        if (!tracked.ok) f.fail("a tracked file of the main checkout changed (git diff HEAD is not empty)", "disk");

        // The Environment detail of each (W6).
        for (const [i, chat] of s.chats.entries()) {
          const d = await p2Detail(page, b.base, f, chat);
          const folder = p2Fact(d, "Folder");
          const branch = p2Fact(d, "Branch");
          details[`detail${i + 1}`] = d.facts;
          if (folder?.path !== p2Path(b, chat)) f.fail(`chat ${i + 1}'s Environment detail names the folder ${JSON.stringify(folder?.path)}, not its worktree`);
          if (folder?.of !== P2_WORDS.worktreeOf(shop)) f.fail(`chat ${i + 1}'s Environment detail has the line ${JSON.stringify(folder?.of)}, not "${P2_WORDS.worktreeOf(shop)}"`);
          if (branch?.value !== p2Branch(chat)) f.fail(`chat ${i + 1}'s Environment detail names the branch ${JSON.stringify(branch?.value)}, not ${p2Branch(chat)}`);
          if (i === 0) {
            shot = await f.shot("worktree-new", "detail");
            await f.opened("worktree-new", "detail");
          }
        }
        details.opened = f.checked;
        issueFindings(page.takeIssues(), failures);
      } finally {
        inbox.dispose();
      }
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = "New environment at ~/code/shop with Worktree on: one POST /api/projects; two chats, each in its own worktree in shop/.claude/worktrees on kitespan/<8> (the ledger, the folder, no record left in the data folder, git worktree list, the fake claude's cwd and --project-config-root=<folder>), and shop's git status clean after each; the Environment detail names each";
  return finish({ kind: "flow", name: "worktree-new", route: "new", scene: "worktree", size: sizeTag(vp), theme: "light", path: "/", failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * worktree-gone (W4, L35): the server restarts (a SIGTERM, so both chats sleep), and worktree-new's first chat's worktree
 * is removed with `git worktree remove`, as a user would in a terminal. A message in that chat starts nothing: the
 * chat shows "This chat's worktree is not there any more." with Make it again from its branch and Continue in the
 * project folder, and the fake claude does not start. Make it again sends one worktree frame (act again) with an ok
 * ack, the folder is back on its branch (git's list and the checkout), and the next message resumes the session in it.
 * Then the second chat's worktree is removed: its line's Continue in the project folder sends one worktree frame (act
 * project), the ledger's folder is the project's (its worktree marked left, its branch kept), the next message
 * resumes the session in the project's folder with no --project-config-root, and its Environment detail names that
 * folder with no worktree line.
 */
async function worktreeGoneFlow(s: Part2Seed, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const { b } = s;
  const { shop } = b.seed.repos;
  const home = b.seed.home;
  let shot: string | undefined;
  const path0 = s.chats[0] ? `/c/${s.chats[0]}` : "/";
  try {
    if (!s.project || s.chats.length < 2) throw new Error("worktree-new made no worktree project with two chats on this seed");
    const r = await b.restart();
    details.restart = r;
    if (r.code !== 0) failures.push({ code: "run", text: `the server's SIGTERM ended it with ${r.code}` });
    await withPage(vp, "light", async (page, wire) => {
      const f = p2Flow(page, vp, failures, warnings);
      /** Remove a chat's worktree, send a message, and read its line; null when the line does not come. */
      const goneLine = async (chat: string, label: string, text: string) => {
        const path = p2Path(b, chat);
        const rm = removeWorktree(shop, home, path);
        if (!rm.ok || p2IsDir(path)) f.fail(`${label}: git worktree remove failed (${rm.err}), or the folder stayed`, "disk");
        const sid = p2Ledger(b, chat)?.sessionId;
        const starts0 = p2Starts(b, sid).length;
        await page.navigate(`${b.base}/c/${chat}`);
        await waitShown(page, ["chat", "composer"]);
        page.takeIssues();
        if (!(await sendFromBox(page, text))) {
          f.fail(`${label}: no message box to send from`, "shows");
          return null;
        }
        const seen = await f.until((x) => x.start?.code === "worktree_gone" && (x.start?.buttons.length ?? 0) === 2, 10_000);
        details[`${label}Line`] = { start: seen.start, box: seen.box };
        if (seen.start?.code !== "worktree_gone") f.fail(`${label}: a message to a chat whose worktree is gone shows ${JSON.stringify(seen.start)}, not the worktree_gone line`);
        if (seen.start?.text !== P2_WORDS.gone) f.fail(`${label}: the line reads ${JSON.stringify(seen.start?.text)}, not "${P2_WORDS.gone}"`);
        const names = seen.start?.buttons.map((x) => `${x.id}:${x.text}`);
        if (JSON.stringify(names) !== JSON.stringify([`start-again:${P2_WORDS.again}`, `start-project:${P2_WORDS.project}`])) f.fail(`${label}: the line's buttons are ${JSON.stringify(names)}, not ${P2_WORDS.again} and ${P2_WORDS.project}`);
        await sleep(500);
        if (p2Starts(b, sid).length !== starts0) f.fail(`${label}: the fake claude started for the chat whose worktree is gone`, "claude");
        return seen;
      };
      /** One press on a line's button: exactly one worktree frame with this act, and its ok ack. */
      const act = async (button: string, want: "again" | "project", chat: string, label: string) => {
        const m = wire.mark();
        if (!(await f.press(`[data-testid="start-line"] [data-testid="${button}"]`, `${label}'s ${button} button`))) return false;
        await waitSent(wire, m, 4000);
        const sent = acting(wire.framesSince(m));
        const frame = sent.find((x) => x.t === "worktree");
        if (sent.length !== 1 || !frame || frame.frame.act !== want || frame.frame.chat !== chat) f.fail(`${label}: the press sent ${JSON.stringify(sent.map((x) => ({ t: x.t, act: x.frame.act, chat: x.frame.chat })))}, not one worktree frame with act ${want}`, "click");
        const ack = frame?.rid ? await waitAck(wire, frame.rid, 15_000) : null;
        details[`${label}Ack`] = ack;
        if (!ack?.ok) f.fail(`${label}: the worktree frame got ${ack ? `the refusal ${ack.code}` : "no ack"}`, "click");
        if (wire.httpSince(m).length) f.fail(`${label}: the press also sent ${clipList(wire.httpSince(m).map(httpText))}`, "click");
        return !!ack?.ok;
      };

      // The first chat: Make it again from its branch.
      const [a, c] = s.chats as [string, string];
      const pathA = p2Path(b, a);
      if (await goneLine(a, "first", "Pick up the coupon work")) {
        shot = await f.shot("worktree-gone", "line");
        await f.opened("worktree-gone", "line");
        // A reload before a press: the line comes back with its two buttons on, and the refused message is in the box.
        await page.reload();
        await waitShown(page, ["chat", "composer"]);
        const reloaded = await f.until((x) => x.start?.code === "worktree_gone" && (x.start?.buttons.length ?? 0) === 2 && x.box !== null, 8000);
        details.firstReloaded = { start: reloaded.start, box: reloaded.box };
        const names = reloaded.start?.buttons.map((x) => `${x.id}:${x.disabled ? "off" : "on"}`);
        if (reloaded.start?.code !== "worktree_gone" || JSON.stringify(names) !== JSON.stringify(["start-again:on", "start-project:on"])) f.fail(`after a reload the chat shows ${JSON.stringify(reloaded.start)}, not the gone line with its two buttons on`);
        if (reloaded.box?.trim() !== "Pick up the coupon work") f.fail(`after a reload the box holds ${JSON.stringify(reloaded.box)}, not the refused message`);
        // Without the line, a press of Send brings it back, so the steps below still run.
        if (reloaded.start?.code !== "worktree_gone" && (await sendFromBox(page, reloaded.box?.trim() ? "" : "Pick up the coupon work"))) await f.until((x) => x.start?.code === "worktree_gone" && (x.start?.buttons.length ?? 0) === 2, 10_000);
        if (await act("start-again", "again", a, "first")) {
          const back = await p2Until(() => p2IsDir(pathA), (x) => x, 10_000);
          if (!back) f.fail("Make it again from its branch left no folder at the worktree's path", "disk");
          const listed = worktreeList(shop, home);
          if (!listed?.some((w) => w.path === pathA && w.branch === p2Branch(a))) f.fail(`git worktree list does not list ${pathA} on ${p2Branch(a)} after Make it again: ${JSON.stringify(listed)}`, "disk");
          if (branchIn(pathA, home) !== p2Branch(a)) f.fail(`the worktree made again is on ${branchIn(pathA, home)}, not ${p2Branch(a)}`, "disk");
          const status = p2Status(b);
          if (!status.ok || status.out !== "") f.fail(`after Make it again the main checkout's git status is ${JSON.stringify(status.out)}, not clean`, "disk");
          const after = await f.until((x) => (x.start?.buttons.length ?? 0) === 0);
          if ((after.start?.buttons.length ?? 0) > 0) f.fail(`the line keeps its buttons after Make it again: ${JSON.stringify(after.start?.buttons)}`);
          const sid = p2Ledger(b, a)?.sessionId;
          const n0 = p2Starts(b, sid).length;
          await emptyChatBox(page);
          if (await p2Send(page, f, "Now add the coupon to the total")) {
            const st = p2Starts(b, sid);
            const last = st.at(-1);
            details.firstResumed = last ? { cwd: last.cwd, root: p2RootArgs(last) } : null;
            if (st.length !== n0 + 1) f.fail(`the next message started the fake claude ${st.length - n0} times, not once`, "claude");
            if (last?.cwd !== pathA) f.fail(`after Make it again the fake claude ran in ${last?.cwd}, not the worktree ${pathA}`, "claude");
            if (JSON.stringify(p2RootArgs(last)) !== JSON.stringify([`--project-config-root=${shop}`])) f.fail(`after Make it again the project config arguments are ${JSON.stringify(p2RootArgs(last))}`, "claude");
          }
        }
      }

      // The second chat: Continue in the project folder.
      const pathC = p2Path(b, c);
      if (await goneLine(c, "second", "Pick up the tax tests")) {
        if (await act("start-project", "project", c, "second")) {
          const ledger = await p2Until(() => p2Ledger(b, c), (l) => l?.cwd === shop, 5000);
          details.secondLedger = { cwd: ledger?.cwd, worktree: ledger?.worktree };
          if (ledger?.cwd !== shop) f.fail(`after Continue in the project folder the ledger's folder is ${ledger?.cwd}, not ${shop}`, "disk");
          if (ledger?.worktree?.left !== true) f.fail(`after Continue in the project folder the ledger's worktree is ${JSON.stringify(ledger?.worktree)}, not marked left`, "disk");
          if (p2IsDir(pathC)) f.fail("Continue in the project folder made the worktree again", "disk");
          if (!hasBranch(shop, home, p2Branch(c))) f.fail(`Continue in the project folder took the branch ${p2Branch(c)} away`, "disk");
          const sid = ledger?.sessionId;
          const n0 = p2Starts(b, sid).length;
          await emptyChatBox(page);
          if (await p2Send(page, f, "Run the tax tests here")) {
            const st = p2Starts(b, sid);
            const last = st.at(-1);
            details.secondResumed = last ? { cwd: last.cwd, root: p2RootArgs(last) } : null;
            if (st.length !== n0 + 1) f.fail(`the next message started the fake claude ${st.length - n0} times, not once`, "claude");
            if (last?.cwd !== shop) f.fail(`after Continue in the project folder the fake claude ran in ${last?.cwd}, not ${shop}`, "claude");
            if (p2RootArgs(last).length) f.fail(`in the project's folder the fake claude still got ${JSON.stringify(p2RootArgs(last))}`, "claude");
          }
          const d = await p2Detail(page, b.base, f, c);
          const folder = p2Fact(d, "Folder");
          details.secondDetail = d.facts;
          if (folder?.path !== shop || folder?.of) f.fail(`the Environment detail names ${JSON.stringify(folder?.path)} with the line ${JSON.stringify(folder?.of)}, not ${shop} with no worktree line`);
        }
      }
      details.opened = f.checked;
      issueFindings(page.takeIssues(), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = "after a restart and git worktree remove: the gone line with its two buttons and no start; Make it again brings the folder back on its branch and the next message runs there; Continue in the project folder moves the chat to the shop folder (no --project-config-root, the branch kept)";
  return finish({ kind: "flow", name: "worktree-gone", route: "chat", scene: "worktree", size: sizeTag(vp), theme: "light", path: path0, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * worktree-archive-delete (W7 to W9; L25, L26): two more chats in the shop project; the second's worktree gets
 * changes in 2 files. Archive of the clean one (its dialog has no worktree line) sends one archive frame, and its
 * folder goes while its branch stays; Archive of the changed one says "Its worktree has changes in 2 files, so it
 * stays on disk.", keeps the folder with the changes and the branch, and the archived chat shows "Its worktree stays
 * at <path>."; Unarchive of the clean one makes its worktree again on its branch. Then a commit of its
 * own goes on that branch, and Delete's confirm says "This also removes its worktree, <path>." and "Its branch
 * kitespan/<8> stays: it holds commits that no other branch has."; Delete sends one delete frame, the folder and git's
 * entry go, the branch stays and so does the commit.
 */
async function worktreeArchiveDeleteFlow(s: Part2Seed, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const { b } = s;
  const { shop } = b.seed.repos;
  const home = b.seed.home;
  let shot: string | undefined;
  try {
    if (!s.project) throw new Error("worktree-new made no worktree project on this seed");
    const project = s.project;
    await withPage(vp, "light", async (page, wire) => {
      const f = p2Flow(page, vp, failures, warnings);
      /** One press of a dialog's confirm: exactly one frame of this type for the chat, and its ok ack. */
      const confirm = async (button: string, t: string, chat: string, label: string, check: (fr: Record<string, any>) => string | null = () => null) => {
        const m = wire.mark();
        if (!(await f.press(`[data-testid="${button}"]`, `${label}'s ${button}`))) return false;
        await waitSent(wire, m, 4000);
        const sent = acting(wire.framesSince(m));
        const frame = sent.find((x) => x.t === t && x.frame.chat === chat);
        const wrong = frame ? check(frame.frame) : null;
        if (sent.length !== 1 || !frame || wrong) f.fail(`${label}: the press sent ${JSON.stringify(sent.map((x) => ({ t: x.t, chat: x.frame.chat, on: x.frame.on })))}${wrong ? ` (${wrong})` : ""}, not one ${t} frame`, "click");
        const ack = frame?.rid ? await waitAck(wire, frame.rid, 15_000) : null;
        if (!ack?.ok) f.fail(`${label}: the ${t} frame got ${ack ? `the refusal ${ack.code}` : "no ack"}`, "click");
        if (wire.httpSince(m).length) f.fail(`${label}: the press also sent ${clipList(wire.httpSince(m).map(httpText))}`, "click");
        return !!ack?.ok;
      };
      const clean = await p2Start(page, wire, b.base, f, { id: project, name: "shop" }, "Rename the cart module");
      const changed = await p2Start(page, wire, b.base, f, { id: project, name: "shop" }, "Draft the refund rules");
      if (!clean || !changed) return;
      const pathC = p2Path(b, clean);
      const pathD = p2Path(b, changed);
      const branchC = p2Branch(clean);
      const branchD = p2Branch(changed);
      writeChanges(pathD, { "README.md": "# shop\n\nA small cart service, with refunds.\n", "docs/refunds.md": "# Refunds\n\nWithin 30 days.\n" });
      // Row 100: a worktree's changes never show in the main checkout around it.
      const status = p2Status(b);
      details.statusWithChanges = status.out;
      if (!status.ok || status.out !== "") f.fail(`with changes in a worktree, the main checkout's git status is ${JSON.stringify(status.out)}, not clean`, "disk");

      // Archive, clean: the folder goes, the branch stays.
      await page.navigate(`${b.base}/c/${clean}/archive`);
      const dc = await f.until((x) => x.archive?.archive === true);
      await sleep(800); // the dialog's read of the worktree's state
      const dc2 = await f.look();
      details.archiveClean = dc2.archive;
      if (!dc.archive) f.fail("the clean chat's Archive dialog does not show", "shows");
      if (dc2.archive?.line) f.fail(`the clean worktree's Archive dialog says ${JSON.stringify(dc2.archive.line)}`);
      if (await confirm("confirm-archive", "archive", clean, "archive (clean)", (fr) => (fr.on === true ? null : `on is ${fr.on}`))) {
        const gone = await p2Until(() => p2IsDir(pathC), (x) => !x, 15_000);
        if (gone) f.fail(`Archive left the clean worktree at ${pathC}`, "disk");
        if (!hasBranch(shop, home, branchC)) f.fail(`Archive took the clean worktree's branch ${branchC} away`, "disk");
        if (worktreeList(shop, home)?.some((w) => w.path === pathC)) f.fail("git worktree list still lists the archived clean worktree", "disk");
      }

      // Archive, changed: the dialog's line; the folder and its changes stay, and the archived chat says so.
      await page.navigate(`${b.base}/c/${changed}/archive`);
      const dd = await f.until((x) => x.archive?.line === P2_WORDS.archiveKeeps(2), 8000);
      details.archiveChanged = dd.archive;
      if (dd.archive?.line !== P2_WORDS.archiveKeeps(2)) f.fail(`the changed worktree's Archive dialog says ${JSON.stringify(dd.archive?.line)}, not "${P2_WORDS.archiveKeeps(2)}"`);
      shot = await f.shot("worktree-archive-delete", "archive-line");
      await f.opened("worktree-archive-delete", "archive-line");
      if (await confirm("confirm-archive", "archive", changed, "archive (changed)", (fr) => (fr.on === true ? null : `on is ${fr.on}`))) {
        await sleep(2000);
        if (!p2IsDir(pathD) || !existsSync(join(pathD, "docs", "refunds.md"))) f.fail(`Archive removed the changed worktree at ${pathD}, or its new file`, "disk");
        if (!hasBranch(shop, home, branchD)) f.fail(`Archive took the changed worktree's branch ${branchD} away`, "disk");
        await page.navigate(`${b.base}/c/${changed}`);
        const kept = await f.until((x) => x.kept === P2_WORDS.kept(pathD), 8000);
        details.kept = kept.kept;
        if (kept.kept !== P2_WORDS.kept(pathD)) f.fail(`the archived changed chat shows ${JSON.stringify(kept.kept)}, not "${P2_WORDS.kept(pathD)}"`);
        else await f.opened("worktree-archive-delete", "kept-line");
      }

      // Unarchive the clean one: its worktree is made again on its branch.
      await page.navigate(`${b.base}/c/${clean}/archive`);
      await f.until((x) => x.archive?.unarchive === true);
      if (await confirm("confirm-unarchive", "archive", clean, "unarchive", (fr) => (fr.on === false ? null : `on is ${fr.on}`))) {
        const back = await p2Until(() => p2IsDir(pathC), (x) => x, 15_000);
        details.unarchived = { folder: back, branch: branchIn(pathC, home) };
        if (!back) f.fail(`Unarchive did not make the worktree again at ${pathC}`, "disk");
        else if (branchIn(pathC, home) !== branchC) f.fail(`the worktree made again is on ${branchIn(pathC, home)}, not ${branchC}`, "disk");
      }

      // A commit of its own, then Delete: the confirm's facts, the folder goes, the branch and its commit stay.
      if (!commitIn(pathC, home, { "src/coupon.ts": "export const COUPON = 0.1;\n" }, "Coupon")) f.fail("the flow could not commit in the unarchived worktree", "disk");
      const head = seedGit(pathC, home, ["rev-parse", "HEAD"]).out.trim();
      await page.navigate(`${b.base}/c/${clean}/delete`);
      const del = await f.until((x) => x.del?.line === P2_WORDS.deleteClean(pathC) && x.del?.branch === P2_WORDS.branchStays(branchC), 8000);
      details.deleteConfirm = del.del;
      if (del.del?.line !== P2_WORDS.deleteClean(pathC)) f.fail(`Delete's confirm says ${JSON.stringify(del.del?.line)}, not "${P2_WORDS.deleteClean(pathC)}"`);
      if (del.del?.branch !== P2_WORDS.branchStays(branchC)) f.fail(`Delete's confirm says ${JSON.stringify(del.del?.branch)} of the branch, not "${P2_WORDS.branchStays(branchC)}"`);
      await f.shot("worktree-archive-delete", "delete-confirm");
      await f.opened("worktree-archive-delete", "delete-confirm");
      if (await confirm("confirm-delete", "delete", clean, "delete")) {
        const gone = await p2Until(() => p2IsDir(pathC), (x) => !x, 15_000);
        if (gone) f.fail(`Delete left the worktree at ${pathC}`, "disk");
        if (worktreeList(shop, home)?.some((w) => w.path === pathC)) f.fail("git worktree list still lists the deleted chat's worktree", "disk");
        if (!hasBranch(shop, home, branchC)) f.fail(`Delete took the branch ${branchC} away, with its own commit`, "disk");
        else if (seedGit(shop, home, ["rev-parse", branchC]).out.trim() !== head) f.fail(`the branch ${branchC} no longer points at the chat's commit`, "disk");
      }
      details.worktreeList = worktreeList(shop, home);
      details.opened = f.checked;
      issueFindings(page.takeIssues(), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = "Archive of a clean worktree chat removes the folder and keeps the branch; a changed one says so, keeps the folder and branch, and shows the kept line; Unarchive makes the worktree again; Delete of a chat with a commit of its own names the worktree and the kept branch, removes the folder and keeps the branch";
  return finish({ kind: "flow", name: "worktree-archive-delete", route: "archive", scene: "worktree", size: sizeTag(vp), theme: "light", path: "/", failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/** Every frame that any socket of the page got (its text, as it came), and the /api/ answers it got. */
class P2Heard {
  readonly frames: string[] = [];
  private readonly api = new Map<string, string>();
  private readonly off: () => void;
  constructor(
    c: Cdp,
    private readonly page: Page,
  ) {
    this.off = c.on((e) => {
      if (e.sessionId !== page.session) return;
      const p = e.params ?? {};
      if (e.method === "Network.webSocketFrameReceived") this.frames.push(String(p.response?.payloadData ?? ""));
      else if (e.method === "Network.responseReceived") {
        try {
          const path = new URL(p.response?.url ?? "").pathname;
          if (path.startsWith("/api/")) this.api.set(String(p.requestId), path);
        } catch {}
      }
    });
  }
  /** The bodies of the /api/ answers the browser still holds. */
  async answers(): Promise<{ path: string; body: string }[]> {
    const out: { path: string; body: string }[] = [];
    for (const [requestId, path] of this.api) {
      const r = await this.page.send<{ body: string; base64Encoded: boolean }>("Network.getResponseBody", { requestId }).catch(() => null);
      if (r) out.push({ path, body: r.base64Encoded ? Buffer.from(r.body, "base64").toString("utf8") : r.body });
    }
    return out;
  }
  dispose(): void {
    this.off();
  }
}

/** The page's text: the document with its attributes, every field's value and the title. */
const P2_PAGE_TEXT = `(() => [document.title, document.documentElement.outerHTML, ...[...document.querySelectorAll("input, textarea")].map((el) => el.value)].join("\\n"))()`;
/** The editor as a `?name=` link leaves it (L41): its marked rows, the focus, what is open, and what its text fields hold. */
interface P2Marked {
  path: string;
  marked: string[];
  focus: { id: string | null; row: string | null } | null;
  inView: boolean;
  open: string[];
  expanded: number;
  filled: string[];
}
const P2_MARKED = `JSON.stringify((() => {
  const ed = document.querySelector('[data-testid="project-environment"]');
  const rows = ed ? [...ed.querySelectorAll('[data-testid="env-row"][data-name]')] : [];
  const marked = rows.filter((r) => r.hasAttribute("data-marked"));
  const a = document.activeElement && document.activeElement !== document.body ? document.activeElement : null;
  const box = marked[0] ? marked[0].getBoundingClientRect() : null;
  return {
    path: location.pathname + location.search,
    marked: marked.map((r) => r.getAttribute("data-name")),
    focus: a ? { id: a.getAttribute("data-testid"), row: a.closest('[data-testid="env-row"]') ? a.closest('[data-testid="env-row"]').getAttribute("data-name") : null } : null,
    inView: !!box && box.top >= 0 && box.bottom <= innerHeight,
    open: ed ? ["env-field", "env-new-value", "env-edit-box", "env-remove-ask"].filter((id) => ed.querySelector('[data-testid="' + id + '"]')) : [],
    expanded: ed ? ed.querySelectorAll('[aria-expanded="true"]').length : 0,
    filled: ed ? [...ed.querySelectorAll("textarea, input:not([type=checkbox]):not([type=radio]):not([type=button]):not([type=submit]):not([type=hidden])")].map((el) => el.value).filter((v) => v !== "") : [],
  };
})())`;
const p2Marked = async (page: Page) => JSON.parse(await page.evaluate<string>(P2_MARKED)) as P2Marked;
/** Everything in the page's local and session storage. */
const P2_STORAGE = `JSON.stringify({ local: Object.keys(localStorage).map((k) => [k, localStorage.getItem(k)]), session: Object.keys(sessionStorage).map((k) => [k, sessionStorage.getItem(k)]) })`;

/**
 * env-editor (D60; E3, E6, E7): /p/<scratch project>/environment shows "None for this environment". Add variables
 * takes four KEY=value lines, one of them PATH: before Save the field names that line's problem ("Line 3: Set PATH
 * ...") and Save stays off, and nothing goes out. With the line gone, Save sends one POST and the rows show each name
 * with the one fixed mask; Edit's "New value" field starts empty and its Save sends one POST; Remove asks in place and
 * sends one POST. A reload shows the same two rows. No planted value is in local or session storage, in the URL or any
 * URL the page asked for, in any socket frame the page got, in the /api/ answers it got, or in the page's text (its
 * fields included); the values went only in the POSTs' bodies. A new chat there gets the names (the fake claude's start
 * lists them and gives only the SHA-256 of the planted value, which is the edited one's), never a removed name; the
 * fake's trace, the server's output and last-options.json hold no value, and the chat's Environment detail says
 * "Environment variables: 2". Then (FIX-U6) that row's link opens the editor in the page, and the bar's Back, "Chat",
 * goes one entry back to the chat's detail (the only seed whose chat's project has variables, so the row shows).
 */
async function envEditorFlow(s: Part2Seed, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const { b } = s;
  const project = IDS.projects.scratch;
  const path = `/p/${project}/environment`;
  const hex = (n: number) => [...crypto.getRandomValues(new Uint8Array(n))].map((x) => x.toString(16).padStart(2, "0")).join("");
  const planted = [`pk-live-${hex(12)}`, `pk-live-${hex(12)}`];
  const sha = (v: string) => new Bun.CryptoHasher("sha256").update(v).digest("hex");
  let shot: string | undefined;
  try {
    await withPage(vp, "light", async (page, wire) => {
      const inbox = new Inbox(cdp, page);
      const heard = new P2Heard(cdp, page);
      const f = p2Flow(page, vp, failures, warnings);
      /** Where a planted value shows on the page's side; [] when nowhere. */
      const leaks = async (when: string) => {
        const where: string[] = [];
        const answers = await heard.answers();
        if (!heard.frames.length || !answers.length) f.fail(`${when}: the page got ${heard.frames.length} socket frames and ${answers.length} /api/ answers that the check could read, so it would see no leak there`, "run");
        const has = (text: string) => planted.some((v) => text.includes(v));
        if (has(await page.evaluate<string>(P2_STORAGE))) where.push("local or session storage");
        const history = await page.history();
        if (has(await page.evaluate<string>("location.href")) || history.entries.some((e) => has(e.url))) where.push("the URL or the history");
        if (inbox.urls.some(has)) where.push("a URL the page asked for");
        if (heard.frames.some(has)) where.push("a socket frame the page got");
        if (answers.some((a) => has(a.body))) where.push("an /api/ answer");
        if (has(await page.evaluate<string>(P2_PAGE_TEXT))) where.push("the page's text or a field");
        if (where.length) f.fail(`${when}: a planted value is in ${where.join(", ")}`, "secret");
        return where;
      };
      const envPosts = (from: number) => inbox.posts.slice(from).filter((p) => p.path === `/api/projects/${project}/env`);
      const bodyOf = (body: string | null) => {
        try {
          return JSON.parse(body ?? "null") as { set?: { name: string }[]; remove?: string[] } | null;
        } catch {
          return null;
        }
      };
      /** One Save, Remove or Edit press: exactly one POST to the env route (200), and nothing else that acts. */
      const onePost = async (sel: string, what: string) => {
        const m = wire.mark();
        const p0 = inbox.posts.length;
        if (!(await f.press(sel, what))) return null;
        await waitSent(wire, m, 4000);
        await sleep(400);
        const http = wire.httpSince(m);
        if (http.length !== 1 || http[0]!.path !== `/api/projects/${project}/env` || http[0]!.status !== 200) f.fail(`${what} sent ${clipList(http.map(httpText))}; expected one POST /api/projects/${project}/env (200)`, "click");
        if (acting(wire.framesSince(m)).length) f.fail(`${what} also sent ${clipList(acting(wire.framesSince(m)).map(frameText))}`, "click");
        return bodyOf(envPosts(p0)[0]?.body ?? null);
      };

      await page.navigate(b.base + path);
      await waitShown(page, ["project-environment", "env-section"]);
      const since = wire.mark();
      const first = await f.until((x) => x.editor?.none !== null && x.editor?.none !== undefined);
      if (first.editor?.none !== P2_WORDS.none) f.fail(`the editor shows ${JSON.stringify(first.editor?.none)}, not "${P2_WORDS.none}"`);
      if (!(await f.press('[data-testid="env-add"]', "Add variables button"))) return;
      const lines = ["API_TIMEOUT_MS=30000", `${P2_SECRET}=${planted[0]}`, "PATH=/opt/tools/bin", "SHOP_REGION=eu-west"];
      if (!(await f.type('[data-testid="env-field"]', lines.join("\n"), "KEY=value field"))) return;
      const bad = await f.until((x) => (x.editor?.notes.some((n) => n.bad) ?? false) && x.editor?.addSave?.disabled === true);
      details.badLine = { notes: bad.editor?.notes, save: bad.editor?.addSave };
      const badNotes = bad.editor?.notes.filter((n) => n.bad).map((n) => n.text);
      if (JSON.stringify(badNotes) !== JSON.stringify([P2_WORDS.pathLine])) f.fail(`before Save the field names ${JSON.stringify(badNotes)}, not "${P2_WORDS.pathLine}"`);
      if (bad.editor?.addSave?.disabled !== true) f.fail("Save is on while a line has a problem");
      shot = await f.shot("env-editor", "bad-line");
      await f.opened("env-editor", "bad-line");
      // The page's text check reads the fields: the value typed in the open field is there (else the check is blind).
      if (!(await page.evaluate<string>(P2_PAGE_TEXT)).includes(planted[0]!)) f.fail("the page's text check does not see the value typed in the open field, so it would see no leak", "run");
      quietFindings(wire, since, await recorder(page), failures, "before Save: ");
      await f.replace('[data-testid="env-field"]', [lines[0], lines[1], lines[3]].join("\n"));
      const good = await f.until((x) => x.editor?.addSave?.disabled === false && !(x.editor?.notes.some((n) => n.bad) ?? true));
      if (good.editor?.addSave?.disabled !== false) return void f.fail(`with the PATH line gone Save stays off: ${JSON.stringify(good.editor?.notes)}`);
      const saved = await onePost('[data-testid="confirm-env-add"]', "Save");
      details.save = saved?.set?.map((x) => x.name);
      if (JSON.stringify(saved?.set?.map((x) => x.name)) !== JSON.stringify(["API_TIMEOUT_MS", P2_SECRET, "SHOP_REGION"])) f.fail(`Save's body names ${JSON.stringify(saved?.set?.map((x) => x.name))}`, "click");
      const rows3 = await f.until((x) => (x.editor?.rows.length ?? 0) === 3 && x.editor?.field === null);
      details.rows = rows3.editor?.rows;
      if (JSON.stringify(rows3.editor?.rows) !== JSON.stringify(["API_TIMEOUT_MS", P2_SECRET, "SHOP_REGION"].map((name) => ({ name, mask: P2_WORDS.mask })))) f.fail(`after Save the rows are ${JSON.stringify(rows3.editor?.rows)}, not the three names each with "${P2_WORDS.mask}"`);
      if (rows3.editor?.field !== null) f.fail("the KEY=value field is still open after Save");
      await leaks("after Save");
      shot = await f.shot("env-editor", "saved");
      await f.opened("env-editor", "saved");

      // Edit: an empty New value, one POST.
      if (!(await f.press(`[data-testid="env-row"][data-name="${P2_SECRET}"] [data-testid="env-edit"]`, `${P2_SECRET}'s Edit`))) return;
      const editing = await f.until((x) => x.editor?.newValue !== null);
      if (editing.editor?.newValue !== "") f.fail(`Edit's New value field holds ${JSON.stringify(editing.editor?.newValue)}, not nothing`);
      await f.opened("env-editor", "edit-box");
      if (!(await f.type('[data-testid="env-new-value"]', planted[1]!, "New value field"))) return;
      const edited = await onePost('[data-testid="confirm-env-save"]', "Edit's Save");
      if (JSON.stringify(edited?.set?.map((x) => x.name)) !== JSON.stringify([P2_SECRET]) || edited?.remove?.length) f.fail(`Edit's body is ${JSON.stringify({ set: edited?.set?.map((x) => x.name), remove: edited?.remove })}`, "click");
      const afterEdit = await f.until((x) => x.editor?.newValue === null);
      if (afterEdit.editor?.newValue !== null) f.fail("the New value field is still open after its Save");

      // Remove: it asks in place, then one POST.
      if (!(await f.press('[data-testid="env-row"][data-name="SHOP_REGION"] [data-testid="env-remove"]', "SHOP_REGION's Remove"))) return;
      const ask = await f.until((x) => x.editor?.ask !== null);
      if (ask.editor?.ask !== P2_WORDS.removeAsk("SHOP_REGION")) f.fail(`Remove asks ${JSON.stringify(ask.editor?.ask)}, not "${P2_WORDS.removeAsk("SHOP_REGION")}"`);
      await f.opened("env-editor", "remove-ask");
      const removed = await onePost('[data-testid="confirm-env-remove"]', "Remove's confirm");
      if (JSON.stringify(removed?.remove) !== JSON.stringify(["SHOP_REGION"]) || removed?.set?.length) f.fail(`Remove's body is ${JSON.stringify({ set: removed?.set?.map((x) => x.name), remove: removed?.remove })}`, "click");
      const two = [{ name: "API_TIMEOUT_MS", mask: P2_WORDS.mask }, { name: P2_SECRET, mask: P2_WORDS.mask }];
      const rows2 = await f.until((x) => JSON.stringify(x.editor?.rows) === JSON.stringify(two));
      if (JSON.stringify(rows2.editor?.rows) !== JSON.stringify(two)) f.fail(`after Remove the rows are ${JSON.stringify(rows2.editor?.rows)}`);
      details.posts = envPosts(0).length;
      if (envPosts(0).length !== 3) f.fail(`the editor sent ${envPosts(0).length} POSTs, not 3 (Save, Edit's Save, Remove)`, "click");

      // A reload: the same rows, nothing filled.
      await page.reload();
      const reloaded = await f.until((x) => JSON.stringify(x.editor?.rows) === JSON.stringify(two));
      if (JSON.stringify(reloaded.editor?.rows) !== JSON.stringify(two)) f.fail(`after a reload the rows are ${JSON.stringify(reloaded.editor?.rows)}`);
      await leaks("after the reload");

      // L41 (5.2): a link with a saved name, opened as a new document, then a second one, then Back and Forward.
      const linkMark = wire.mark();
      const linkPosts = inbox.posts.length;
      const links: Record<string, unknown> = {};
      const markedAt = async (name: string, when: string) => {
        const want = `${path}?name=${name}`;
        const m = await p2Until(() => p2Marked(page), (x) => x.marked.length > 0 && x.path === want, 6000);
        links[when] = m;
        if (m.path !== want) f.fail(`${when}: the page is at ${m.path}, not ${want}`, "route");
        if (JSON.stringify(m.marked) !== JSON.stringify([name])) f.fail(`${when}: the marked rows are ${JSON.stringify(m.marked)}, not ${name}'s alone`);
        if (m.focus?.id !== "env-edit" || m.focus.row !== name) f.fail(`${when}: the focus is on ${JSON.stringify(m.focus)}, not ${name}'s Edit`);
        if (!m.inView) f.fail(`${when}: ${name}'s row is not in view`);
        if (m.open.length || m.expanded) f.fail(`${when}: ${clipList(m.open) || `${m.expanded} control(s) marked open`} shows: the link opened something`);
        if (m.filled.length) f.fail(`${when}: the editor's fields hold ${m.filled.length} value(s): the link filled something`);
      };
      await page.navigate(`${b.base}${path}?name=API_TIMEOUT_MS`);
      await markedAt("API_TIMEOUT_MS", "?name=API_TIMEOUT_MS as a new document");
      await f.opened("env-editor", "marked");
      await page.navigate(`${b.base}${path}?name=${P2_SECRET}`);
      await markedAt(P2_SECRET, `?name=${P2_SECRET} as a new document`);
      const hist = await page.history();
      const backTo = hist.entries[hist.currentIndex - 1];
      if (!backTo) f.fail("the history has no entry before the second link", "route");
      else {
        await page.goToEntry(backTo.id);
        await markedAt("API_TIMEOUT_MS", "after Back");
        const now = await page.history();
        const fwd = now.entries[now.currentIndex + 1];
        if (!fwd) f.fail("the history has no entry after Back", "route");
        else {
          await page.goToEntry(fwd.id);
          await markedAt(P2_SECRET, "after Forward");
        }
      }
      details.links = links;
      quietFindings(wire, linkMark, await recorder(page), failures, "the ?name= links: ");
      if (inbox.posts.length !== linkPosts) f.fail(`the ?name= links sent ${inbox.posts.length - linkPosts} POST(s)`, "frames");

      // A new chat in the environment: its Claude Code gets the names, and only a hash of the value.
      const chat = await p2Start(page, wire, b.base, f, { id: project, name: "scratch" }, "Check the payment settings");
      if (chat) {
        const sid = await p2Until(() => p2Ledger(b, chat)?.sessionId ?? null, (x) => x !== null, 5000);
        const start = p2Starts(b, sid)[0];
        details.store = {
          file: (() => {
            try {
              return (JSON.parse(readFileSync(join(b.seed.state, "env", `${project}.json`), "utf8")) as { vars: { name: string }[] }).vars.map((v) => v.name);
            } catch (e) {
              return String(e);
            }
          })(),
          api: ((await (await fetch(`${b.base}/api/projects/${project}/env`)).json()) as { vars?: { name: string }[] }).vars?.map((v) => v.name) ?? null,
          chatProject: (p2Ledger(b, chat) as { project?: string } | null)?.project ?? null,
          starts: p2Starts(b, sid).length,
        };
        const names = (start?.envNames as string[] | undefined) ?? [];
        const hashes = (start?.envHashes as Record<string, string | null> | undefined) ?? {};
        const hashIs = hashes[P2_SECRET] === sha(planted[1]!) ? "the edited value's hash" : hashes[P2_SECRET] === sha(planted[0]!) ? "the first value's hash" : JSON.stringify(hashes[P2_SECRET] ?? null);
        details.claude = { names: names.filter((n) => ["API_TIMEOUT_MS", P2_SECRET, "SHOP_REGION"].includes(n)), hash: hashIs };
        if (!start) f.fail("the fake claude never started for the new chat", "claude");
        else {
          if (!names.includes("API_TIMEOUT_MS") || !names.includes(P2_SECRET)) f.fail(`the fake claude's environment lacks a saved name: ${JSON.stringify(details.claude)}`, "claude");
          if (names.includes("SHOP_REGION")) f.fail("the fake claude got SHOP_REGION, which was removed", "claude");
          if (hashes[P2_SECRET] !== sha(planted[1]!)) f.fail(`the fake claude's ${P2_SECRET} gives ${hashIs}, not the edited value's hash`, "claude");
        }
        const trace = readFileSync(b.fake.tracePath, "utf8");
        const out = b.output();
        const lastOptions = (() => {
          try {
            return readFileSync(join(b.seed.state, "last-options.json"), "utf8");
          } catch {
            return "";
          }
        })();
        if (planted.some((v) => trace.includes(v))) f.fail("the fake claude's trace holds a planted value", "secret");
        if (planted.some((v) => out.out.includes(v) || out.err.includes(v))) f.fail("the server's output holds a planted value", "secret");
        if (planted.some((v) => lastOptions.includes(v))) f.fail("last-options.json holds a planted value", "secret");
        if (!lastOptions.includes(`"${P2_SECRET}":"[set]"`) && !lastOptions.includes(`"${P2_SECRET}": "[set]"`)) warnings.push({ code: "secret", text: `last-options.json does not record ${P2_SECRET} as "[set]"` });
        const d = await p2Detail(page, b.base, f, chat);
        const fact = p2Fact(d, P2_WORDS.envTitle);
        details.detail = fact;
        if (fact?.value !== "2") f.fail(`the chat's Environment detail says ${JSON.stringify(fact)}, not "${P2_WORDS.envTitle}: 2"`);
        await leaks("after the new chat");
        // FIX-U6 (a way back of the page's own): the detail's Environment row opens the editor in this page, and the
        // bar's Back is "Chat", back to that detail (one entry back, as the browser's Back went), not the project page.
        const detailPath = `/c/${chat}/environment`;
        const backFrom: Record<string, unknown> = {};
        details.backFromChat = backFrom;
        if (await f.press(".side-env-link", "Environment row's link")) {
          const atEnv = await p2Until(() => page.probe(), (x) => samePath(x.path, path), 5000);
          const h0 = await page.history();
          const back = await page.evaluate<{ label: string; aria: string | null; href: string | null } | null>(
            `(() => { const a = [...document.querySelectorAll('[data-testid="topbar"] .scr-bar-back')].find((e) => e.getClientRects().length); return a ? { label: a.textContent.trim(), aria: a.getAttribute("aria-label"), href: a.getAttribute("href") } : null; })()`,
          );
          Object.assign(backFrom, { opened: atEnv.path, back });
          if (!samePath(atEnv.path, path)) f.fail(`the Environment row's link went to ${atEnv.path}, not ${path}`, "route");
          else if (back?.label !== "Chat" || back.href !== detailPath || !back.aria?.startsWith("Back to ")) f.fail(`opened from the chat's detail, the bar's Back is ${JSON.stringify(back)}, not "Chat" to ${detailPath}`, "back");
          else if ((await f.shot("env-editor", "from-chat")) && (await f.press('[data-testid="topbar"] .scr-bar-back', "bar's Back"))) {
            const after = await p2Until(() => page.probe(), (x) => samePath(x.path, detailPath), 5000);
            const h1 = await page.history();
            Object.assign(backFrom, { after: after.path, index: [h0.currentIndex, h1.currentIndex], entries: [h0.entries.length, h1.entries.length] });
            if (!samePath(after.path, detailPath)) f.fail(`the bar's Back went to ${after.path}, not ${detailPath}`, "back");
            else if (h1.currentIndex !== h0.currentIndex - 1) f.fail(`the bar's Back moved the history from entry ${h0.currentIndex} to ${h1.currentIndex}, not one entry back`, "back");
          }
        }
      }
      details.opened = f.checked;
      issueFindings(page.takeIssues(), failures);
      inbox.dispose();
      heard.dispose();
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = "Add variables names the PATH line before Save; Save, Edit and Remove each send one POST; each row shows the one mask; a reload shows the same rows; no planted value in storage, URLs, socket frames, /api/ answers or the page; a new chat's fake claude gets the names and the edited value's hash; from its detail the editor's Back is \"Chat\", one entry back";
  return finish({ kind: "flow", name: "env-editor", route: "projectEnvironment", scene: "worktree", size: sizeTag(vp), theme: "light", path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * worktree-off (W2; L29, L33; row 100): in New environment, ~/Documents (not a repository), ~/code/hooks (a
 * WorktreeCreate hook in its project settings) and ~/code/linked (its .claude a symbolic link) each show the Worktree
 * switch off and disabled with its one line ("This folder is not a git repository.", "Your Claude Code settings have a
 * WorktreeCreate hook, which kitespan's worktrees would not run." and "This repository's .claude or .claude/worktrees
 * is a symbolic link or not a folder, so kitespan makes no worktree here."); nothing goes out before Use this folder,
 * which sends one POST /api/projects with no worktree; the new project's editor (/p/<project>/environment) shows the
 * same switch, off and disabled, with the same line, and sends nothing. Nothing is made behind linked's link.
 */
async function worktreeOffFlow(s: Part2Seed, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const { b } = s;
  let shot: string | undefined;
  try {
    await withPage(vp, "light", async (page, wire) => {
      const inbox = new Inbox(cdp, page);
      const f = p2Flow(page, vp, failures, warnings);
      const cases = [
        { typed: "~/Documents", name: "Documents", folder: b.seed.homeFolders.documents, line: P2_WORDS.notGit },
        { typed: "~/code/hooks", name: "hooks", folder: b.seed.repos.hooks, line: P2_WORDS.hook },
        { typed: "~/code/linked", name: "linked", folder: b.seed.repos.linked, line: P2_WORDS.link },
      ];
      for (const c of cases) {
        const since = wire.mark();
        const picked = await p2Finder(page, b.base, f, c.typed, c.name, (x) => x.finder?.off === c.line);
        if (!picked) return;
        details[c.name] = picked.finder;
        if (picked.finder?.off !== c.line) f.fail(`New environment at ${c.typed} says ${JSON.stringify(picked.finder?.off)}, not "${c.line}"`);
        if (!picked.finder?.worktree || picked.finder.worktree.checked || !picked.finder.worktree.disabled) f.fail(`New environment's Worktree switch at ${c.typed} is ${JSON.stringify(picked.finder?.worktree)}, not off and disabled`);
        if (picked.finder?.use?.disabled !== false) f.fail(`Use this folder is off at ${c.typed}`);
        if (c.name === "hooks") shot = await f.shot("worktree-off", "new-environment");
        await f.opened("worktree-off", `new-environment-${c.name.toLowerCase()}`);
        quietFindings(wire, since, await recorder(page), failures, `${c.name}, before Use this folder: `);
        const m = wire.mark();
        const p0 = inbox.posts.length;
        if (!(await f.press('[data-testid="dialog-new-environment"] [data-testid="confirm-use-folder"]', "Use this folder button"))) return;
        await f.until((x) => !x.finder && x.chip === c.name, 8000);
        await sleep(300);
        const http = wire.httpSince(m);
        const body = (() => {
          try {
            return JSON.parse(inbox.posts[p0]?.body ?? "null") as Record<string, unknown> | null;
          } catch {
            return null;
          }
        })();
        if (http.length !== 1 || http[0]!.path !== "/api/projects" || http[0]!.status !== 201) f.fail(`${c.name}: Use this folder sent ${clipList(http.map(httpText))}; expected one POST /api/projects (201)`, "click");
        if (body?.worktree === true) f.fail(`${c.name}: the POST asks for a worktree`, "click");
        const projects = ((await (await fetch(`${b.base}/api/projects`)).json()) as { projects: { id: string; cwd: string; worktree?: boolean; worktreeOff?: string | null }[] }).projects;
        const project = projects.find((p) => p.cwd === c.folder);
        if (!project) {
          f.fail(`no project has ${c.folder} after Use this folder`, "disk");
          continue;
        }
        if (project.worktree) f.fail(`${c.name}: the new project's Worktree option is on`, "disk");
        await page.navigate(`${b.base}/p/${project.id}/environment`);
        await waitShown(page, ["project-environment"]);
        const e0 = wire.mark();
        const ed = await f.until((x) => x.editor?.off === c.line);
        details[`${c.name}Editor`] = { worktree: ed.editor?.worktree, off: ed.editor?.off };
        if (ed.editor?.off !== c.line) f.fail(`${c.name}'s editor says ${JSON.stringify(ed.editor?.off)}, not "${c.line}"`);
        if (!ed.editor?.worktree || ed.editor.worktree.checked || !ed.editor.worktree.disabled) f.fail(`${c.name}'s editor shows the Worktree switch ${JSON.stringify(ed.editor?.worktree)}, not off and disabled`);
        if (c.name === "Documents") await f.shot("worktree-off", "editor");
        await f.opened("worktree-off", `editor-${c.name.toLowerCase()}`);
        quietFindings(wire, e0, null, failures, `${c.name}'s editor: `);
      }
      // The link rule made nothing: no worktrees folder behind linked's .claude link.
      if (existsSync(join(b.seed.repos.linked, "config", "worktrees"))) f.fail("a worktrees folder was made behind linked's .claude link", "disk");
      details.opened = f.checked;
      issueFindings(page.takeIssues(), failures);
      inbox.dispose();
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = "~/Documents, ~/code/hooks and ~/code/linked: New environment's Worktree switch off and disabled with its line; one POST /api/projects with no worktree; the project's editor shows the same switch and line and sends nothing";
  return finish({ kind: "flow", name: "worktree-off", route: "projectEnvironment", scene: "worktree", size: sizeTag(vp), theme: "light", path: "/", failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/** Claude Code's first error line when it will not resume a session in its worktree (the fake claude's, W5). */
const P2_REFUSED_LINE = "Error: cannot resume into worktree /srv/work/app/.claude/worktrees/fix-login: it failed its safety checks.";
/** The fake claude of worktree-refused's seed: every resume is refused as Claude Code refuses one (W5, L34). */
const P2_REFUSED_FIXTURE: Partial<Fixture> = { startupFailure: { reason: "worktree_resume_refused", errors: [P2_REFUSED_LINE], onResume: true } };

/**
 * worktree-refused (W5, L34), on a seed of its own whose fake claude refuses every resume with
 * `startup_failure_reason` worktree_resume_refused: a message in the example chat (which has a transcript, so its start
 * resumes) gets one start and nothing more: the chat shows the line of the refusal ("Claude Code would not continue
 * this chat in its worktree.", with Claude Code's first error line), Continue in a copy and Continue without the
 * worktree, both on, and the message back in the box. After a reload (a new document, which never saw the chat's
 * start) the same line and buttons show, Continue in a copy on; its press sends exactly one continue_session with the
 * fork for the chat's project and session, its ack is ok, and the page opens the copy, whose ledger names the session it
 * copies. The fake claude started once.
 */
async function worktreeRefusedFlow(vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const chat = EX.chat;
  const path0 = `/c/${chat}`;
  const text = "Pick up the login fix";
  let shot: string | undefined;
  let b: Booted | null = null;
  try {
    b = await boot({ scene: "worktree", port: PORT, dist: built!, keep: KEEP, env: SERVER_ENV, fixture: P2_REFUSED_FIXTURE });
    live.add(b);
    const booted = b;
    await withPage(vp, "light", async (page, wire) => {
      const f = p2Flow(page, vp, failures, warnings);
      const want = [`start-copy:${P2_WORDS.copy}:on`, `start-without:${P2_WORDS.without}:on`];
      const buttons = (x: P2Look) => x.start?.buttons.map((y) => `${y.id}:${y.text}:${y.disabled ? "off" : "on"}`) ?? [];
      const lineChecks = (x: P2Look, when: string) => {
        if (x.start?.code !== "worktree_resume_refused") return void f.fail(`${when}: the chat shows ${JSON.stringify(x.start)}, not the worktree_resume_refused line`);
        if (!x.start.all?.includes(P2_WORDS.refused)) f.fail(`${when}: the line reads ${JSON.stringify(x.start.all)}, without "${P2_WORDS.refused}"`);
        if (!x.start.all?.includes(P2_REFUSED_LINE)) f.fail(`${when}: the line reads ${JSON.stringify(x.start.all)}, without Claude Code's first error line`);
        if (JSON.stringify(buttons(x)) !== JSON.stringify(want)) f.fail(`${when}: the line's buttons are ${JSON.stringify(buttons(x))}, not ${P2_WORDS.copy} and ${P2_WORDS.without}, both on`);
        if (x.box?.trim() !== text) f.fail(`${when}: the box holds ${JSON.stringify(x.box)}, not the refused message`);
      };
      const sid = p2Ledger(booted, chat)?.sessionId ?? null;
      if (!sid) throw new Error("the example chat has no session id on this seed");
      await page.navigate(`${booted.base}${path0}`);
      await waitShown(page, ["chat", "composer"]);
      await emptyChatBox(page);
      page.takeIssues();
      const starts0 = p2Starts(booted, sid).length;
      if (!(await sendFromBox(page, text))) return void f.fail("no message box to send from", "shows");
      const seen = await f.until((x) => x.start?.code === "worktree_resume_refused" && (x.start?.buttons.length ?? 0) === 2 && x.box?.trim() === text, 15_000);
      details.line = { start: seen.start, box: seen.box };
      lineChecks(seen, "after the refused start");
      await sleep(1500);
      const starts = p2Starts(booted, sid).length - starts0;
      details.starts = starts;
      if (starts !== 1) f.fail(`the fake claude started ${starts} times for the message, not once (never a retry by itself)`, "claude");
      shot = await f.shot("worktree-refused", "line");
      await f.opened("worktree-refused", "line");

      // A reload: a new document, which knows the chat only from the server.
      await page.reload();
      await waitShown(page, ["chat", "composer"]);
      const again = await f.until((x) => JSON.stringify(buttons(x)) === JSON.stringify(want) && x.box?.trim() === text, 10_000);
      details.reloaded = { start: again.start, box: again.box };
      lineChecks(again, "after a reload");
      const m = wire.mark();
      if (await f.press('[data-testid="start-line"] [data-testid="start-copy"]', `${P2_WORDS.copy} button`)) {
        await waitSent(wire, m, 4000);
        const sent = acting(wire.framesSince(m));
        const frame = sent.find((x) => x.t === "continue_session");
        const got = sent.map((x) => ({ t: x.t, project: x.frame.project, session: x.frame.session, fork: x.frame.fork }));
        details.copyFrames = got;
        if (sent.length !== 1 || !frame || frame.frame.fork !== true || frame.frame.session !== sid || frame.frame.project !== EX.project) f.fail(`${P2_WORDS.copy} sent ${JSON.stringify(got)}, not one continue_session with the fork for ${EX.project} and the chat's session`, "click");
        if (wire.httpSince(m).length) f.fail(`${P2_WORDS.copy} also sent ${clipList(wire.httpSince(m).map(httpText))}`, "click");
        const ack = frame?.rid ? await waitAck(wire, frame.rid, 15_000) : null;
        details.copyAck = ack;
        if (!ack?.ok) f.fail(`the continue_session got ${ack ? `the refusal ${ack.code}` : "no ack"}`, "click");
        const at = await p2Until(() => page.evaluate<string>("location.pathname"), (p) => /^\/c\/[a-z2-7]{20}$/.test(p) && p !== path0, 8000);
        details.copy = at;
        if (!/^\/c\/[a-z2-7]{20}$/.test(at) || at === path0) f.fail(`${P2_WORDS.copy} left the page at ${at}, not the copy`, "route");
        else {
          const copy = (await p2Until(() => p2Ledger(booted, at.slice(3)) as (P2Ledger & { copyOf?: string }) | null, (l) => l !== null, 5000)) as (P2Ledger & { copyOf?: string }) | null;
          if (copy?.copyOf !== sid) f.fail(`the copy's ledger names ${JSON.stringify(copy?.copyOf)} as the session it copies, not ${sid}`, "disk");
        }
      }
      if (p2Starts(booted, sid).length - starts0 !== 1) f.fail(`the fake claude started ${p2Starts(booted, sid).length - starts0} times in all, not once`, "claude");
      details.opened = f.checked;
      issueFindings(page.takeIssues(), failures);
    });
  } catch (e) {
    failures.push({ code: b ? "run" : "seed", text: b ? `the check could not run: ${(e as Error).message}` : `the seed did not boot: ${(e as Error).message}` });
  } finally {
    if (b) {
      const r = await b.stop();
      live.delete(b);
      if (r.code !== 0) warnings.push({ code: "run", text: `the server exited with ${r.code}` });
      if (r.leftovers.length) warnings.push({ code: "run", text: `${r.leftovers.length} process(es) outlived the server and were ended by pid` });
    }
  }
  const note = "a resume that Claude Code refuses (worktree_resume_refused): one start, the line with Claude Code's line and its two buttons, the message back in the box; after a reload Continue in a copy is on and sends one continue_session with the fork, which opens the copy";
  return finish({ kind: "flow", name: "worktree-refused", route: "chat", scene: "worktree", size: sizeTag(vp), theme: "light", path: path0, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/**
 * Row 99 in part 2: Remove's words for a worktree environment with variables (web/dialogs/EnvironmentDialogs.tsx). Row
 * 100: its worktrees are inside its folder, so the first line does not say that the folder is not changed, and a clean
 * one gets Delete's line.
 */
const P2_REMOVE = {
  first: (n: number) => `Its ${n} chats leave kitespan. Their conversations stay in Claude Code.`,
  vars: "Its environment variables are removed.",
  keeps: (path: string, n: number) => `Its worktree at ${path} has changes in ${n} files, so it stays on disk.`,
  goes: (path: string) => `This also removes its worktree, ${path}.`,
} as const;
/** Remove's confirm as the page shows it: its text, the variables line, each worktree line, and Remove. */
const P2_REMOVE_DIALOG = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const box = [...document.querySelectorAll('[data-testid="dialog-remove-project"]')].find(shown);
  const q = (sel) => (box ? [...box.querySelectorAll(sel)].filter(shown) : []);
  const remove = q('[data-testid="confirm-remove"]')[0];
  return {
    open: !!box,
    text: box ? box.textContent.replace(/\\s+/g, " ").trim() : "",
    vars: q('[data-testid="remove-vars-line"]').map((el) => el.textContent.trim()),
    lines: q('[data-testid="remove-worktree-line"]').map((el) => el.textContent.replace(/\\s+/g, " ").trim()),
    reading: q('[data-testid="remove-worktree-line"][aria-busy="true"]').length,
    remove: remove ? (remove.disabled ? "off" : "on") : "none",
    path: location.pathname,
  };
})())`;
type P2RemoveDialog = { open: boolean; text: string; vars: string[]; lines: string[]; reading: number; remove: "on" | "off" | "none"; path: string };

/**
 * env-remove-worktree (row 99 in part 2: L25, D60), at 1280x800 and 390x844 touch, each on a fresh seed of the
 * worktree-env scene (~/code/shop an environment with Worktree on and one variable). Two chats started there get a
 * worktree each (row 100: in shop's .claude/worktrees), and one of them changes in 2 files. The heading's "..." and
 * Remove open /p/<shop>/remove: its first line (2 chats, with no word that the folder is not changed), "Its
 * environment variables are removed.", one line that names the changed worktree's path and its 2 changed files, and
 * Delete's line for the clean one, which Remove takes from the folder; Remove is on once the read is in; the
 * variable's value is nowhere on the page, and nothing went out. The confirm is checked and shot in light and dark (on
 * the phone in each look too). Remove sends exactly one POST /api/projects/<shop>/remove and the page goes to /. On
 * disk: the clean worktree is gone and its branch stays; the changed one stays with its files and its branch; git
 * lists it alone beside the main checkout; the variables file and both ledgers are gone.
 */
async function envRemoveWorktreeFlow(vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const project = { id: PART2_IDS.shop, name: "shop" };
  let path0 = "/";
  let shot: string | undefined;
  let b: Booted | null = null;
  try {
    b = await boot({ scene: "worktree-env", port: PORT, dist: built!, keep: KEEP, env: SERVER_ENV });
    live.add(b);
    const booted = b;
    const { shop } = booted.seed.repos;
    const home = booted.seed.home;
    await withPage(vp, "light", async (page, wire) => {
      const f = p2Flow(page, vp, failures, warnings);
      const dlg = async () => JSON.parse(await page.evaluate<string>(P2_REMOVE_DIALOG)) as P2RemoveDialog;
      const clean = await p2Start(page, wire, booted.base, f, project, "Rename the cart module");
      const changed = await p2Start(page, wire, booted.base, f, project, "Draft the refund rules");
      if (!clean || !changed) return;
      const pathC = p2Path(booted, clean);
      const pathD = p2Path(booted, changed);
      const branchC = p2Branch(clean);
      const branchD = p2Branch(changed);
      writeChanges(pathD, { "README.md": "# shop\n\nA small cart service, with refunds.\n", "docs/refunds.md": "# Refunds\n\nWithin 30 days.\n" });
      const envFile = join(booted.seed.state, "env", `${project.id}.json`);
      if (!existsSync(envFile)) f.fail(`the seed has no variables file at ${envFile}`, "seed");

      // The heading's menu, from a chat's page on the laptop and from the list on touch.
      path0 = vp.touch ? "/chats" : `/c/${changed}`;
      await page.navigate(booted.base + path0);
      await waitShown(page, [vp.touch ? "chat-list" : "conversation"]);
      page.takeIssues();
      const since = wire.mark();
      if (!(await openEnvMenu(page, project.id, f.fail))) return;
      if (!(await pressEnvRow(page, "env-remove", f.fail))) return;
      const c = await p2Until(dlg, (x) => x.open && x.remove === "on" && x.reading === 0 && x.lines.length > 1, 10_000);
      details.confirm = c;
      if (c.path !== `/p/${project.id}/remove`) f.fail(`Remove opened ${c.path}, not /p/${project.id}/remove`, "route");
      if (!c.open) return void f.fail("Remove's confirm does not show", "shows");
      if (!c.text.startsWith(`Remove shop?`) || !c.text.includes(P2_REMOVE.first(2))) f.fail(`the confirm reads ${JSON.stringify(c.text)}, without "Remove shop?" and "${P2_REMOVE.first(2)}"`);
      if (c.text.includes("not changed")) f.fail(`the confirm says the folder is not changed, though Remove takes ${pathC} from it`);
      if (JSON.stringify(c.vars) !== JSON.stringify([P2_REMOVE.vars])) f.fail(`the confirm's variables line is ${JSON.stringify(c.vars)}, not "${P2_REMOVE.vars}"`);
      const want = [P2_REMOVE.keeps(pathD, 2), P2_REMOVE.goes(pathC)];
      if (JSON.stringify(c.lines.slice().sort()) !== JSON.stringify(want.slice().sort())) f.fail(`the confirm's worktree lines are ${JSON.stringify(c.lines)}, not ${JSON.stringify(want)}`);
      if (c.remove !== "on") f.fail(`once the worktrees are read, Remove is ${c.remove}`);
      if ((await page.evaluate<string>(P2_PAGE_TEXT)).includes(PART2_IDS.variable.value)) f.fail("the variable's value is in the page", "secret");
      const early = [...postsSince(wire, since).map(httpText), ...acting(wire.framesSince(since)).map(frameText)];
      if (early.length) f.fail(`the menu and the confirm sent ${clipList(early)}`, "click");
      await f.opened("env-remove-worktree", "confirm");
      shot = shotName("worktree", "env-remove-worktree", vp, "light", "confirm");

      // Remove: one request; the page goes to /.
      const mark = wire.mark();
      if (!(await f.press('[data-testid="dialog-remove-project"] [data-testid="confirm-remove"]', "Remove button"))) return;
      const p = await p2Until(() => pathOf(page), (x) => x === "/", 15_000);
      if (p !== "/") f.fail(`after Remove the page is on ${p}, not /`, "route");
      await sleep(500);
      const sent = postsSince(wire, mark);
      details.sent = sent.map(httpText);
      if (sent.length !== 1 || sent[0]!.path !== `/api/projects/${project.id}/remove` || sent[0]!.status !== 200) f.fail(`Remove sent ${sent.length ? clipList(sent.map(httpText)) : "nothing"}; expected one POST /api/projects/${project.id}/remove (200)`, "click");
      if (acting(wire.framesSince(mark)).length) f.fail(`Remove also sent ${clipList(acting(wire.framesSince(mark)).map(frameText))}`, "click");

      // On disk (L25): the clean worktree went, its branch stays; the changed one stays whole; nothing of D60 is left.
      const goneC = await p2Until(() => p2IsDir(pathC), (x) => !x, 15_000);
      if (goneC) f.fail(`Remove left the clean worktree at ${pathC}`, "disk");
      if (!hasBranch(shop, home, branchC)) f.fail(`Remove took the clean worktree's branch ${branchC} away`, "disk");
      if (!p2IsDir(pathD) || !existsSync(join(pathD, "docs", "refunds.md"))) f.fail(`Remove took the changed worktree at ${pathD}, or its new file`, "disk");
      if (!hasBranch(shop, home, branchD)) f.fail(`Remove took the changed worktree's branch ${branchD} away`, "disk");
      const list = worktreeList(shop, home)?.map((w) => w.path) ?? null;
      details.worktreeList = list;
      if (JSON.stringify(list?.slice().sort()) !== JSON.stringify([shop, pathD].sort())) f.fail(`git worktree list is ${JSON.stringify(list)}, not the main checkout and ${pathD}`, "disk");
      if (existsSync(envFile)) f.fail(`Remove left the variables file ${envFile}`, "disk");
      for (const id of [clean, changed]) if (p2Ledger(booted, id)) f.fail(`Remove left the ledger of ${id}`, "disk");
      const heads = await waitUntil(() => envOrder(page), (o) => !o.includes(project.id));
      if (heads.includes(project.id)) f.fail("the removed environment's heading is still in the list");
      details.opened = f.checked;
      issueFindings(page.takeIssues(), failures);
    });
  } catch (e) {
    failures.push({ code: b ? "run" : "seed", text: b ? `the check could not run: ${(e as Error).message}` : `the seed did not boot: ${(e as Error).message}` });
  } finally {
    if (b) {
      const r = await b.stop();
      live.delete(b);
      if (r.code !== 0) warnings.push({ code: "run", text: `the server exited with ${r.code}` });
      if (r.leftovers.length) warnings.push({ code: "run", text: `${r.leftovers.length} process(es) outlived the server and were ended by pid` });
    }
  }
  const note = "Remove of a worktree environment with variables: the confirm names the variables, the changed worktree that stays (its path, 2 files) and the clean one that goes from the folder (Delete's line), with no word that the folder is not changed; one request; the clean worktree goes and its branch stays, the changed one stays whole, the variables file goes";
  return finish({ kind: "flow", name: "env-remove-worktree", route: "projectRemove", scene: "worktree-env", size: sizeTag(vp), theme: "light", path: path0, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

const PART2_RUN: Record<Part2Flow, (s: Part2Seed, vp: Viewport) => Promise<CheckResult>> = {
  "worktree-new": worktreeNewFlow,
  "worktree-gone": worktreeGoneFlow,
  "worktree-archive-delete": worktreeArchiveDeleteFlow,
  "env-editor": envEditorFlow,
  "worktree-off": worktreeOffFlow,
};

/** The part 2 flows at one size, on a fresh seed of the worktree scene (its fake claude hashes P2_SECRET's value). */
async function part2OnSeed(vp: Viewport, run: readonly Part2Flow[], record: (r: CheckResult) => void, problems: string[]): Promise<void> {
  let b: Booted;
  try {
    b = await boot({ scene: "worktree", port: PORT, dist: built!, keep: KEEP, env: SERVER_ENV, fixture: { envHash: [P2_SECRET] } });
  } catch (e) {
    for (const f of run) record(finish({ kind: "flow", name: f, route: FLOW_ROUTE[f]!, scene: "worktree", size: sizeTag(vp), theme: "light", path: "/", failures: [{ code: "seed", text: `the seed did not boot: ${(e as Error).message}` }], warnings: [], note: "", ms: 0, details: {} }));
    return;
  }
  live.add(b);
  const s: Part2Seed = { b, project: null, chats: [] };
  try {
    for (const f of run) {
      if (cdp.closed) break;
      record(await PART2_RUN[f](s, vp));
    }
  } finally {
    const r = await b.stop();
    live.delete(b);
    if (r.code !== 0) problems.push(`scene worktree (${vp.name}): the server exited with ${r.code}`);
    if (r.leftovers.length) problems.push(`scene worktree (${vp.name}): ${r.leftovers.length} process(es) outlived the server and were ended by pid`);
  }
}

// ---------------------------------------------------------------------------------------------------------------
// FIX-U6, the home-screen app (owner rows 112 and 113; DESIGN-U6):
// - routes: the web app manifest and each icon under /assets/ (app-manifest, app-icon-192, app-icon-512,
//   app-icon-maskable-512, app-apple-touch-icon), asked for as a browser asks, with no cookie: 200, the content type,
//   revalidated, each icon's bytes as web/icons/ keeps them, the manifest as shared/home-screen.ts makes it from the
//   page's title, and the page's head names the manifest and the apple-touch-icon. The manifest's check also asks a
//   page's own Chrome: Page.getAppManifest reads it with no error, and Page.getInstallabilityErrors lists nothing but
//   the check's own notes (CHECK_OWN_INSTALL); the standalone flow asks the app window the same.
// - standalone (390x844, 834x1194 and the large iPad's 1366x1024, touch, dark and light): a Chrome of its own started
//   with --app=<the page>, whose one window is an app window in display-mode standalone (Emulation.setEmulatedMedia
//   takes display-mode and ignores it, DESIGN-U6 9), with a phone's safe areas (59 px at the top, 34 at the bottom) or
//   a tablet's (24 and 20; the large iPad has the laptop's layout). Each of the main screens, sheets, dialogs and
//   panes, opened as a new document in that window: display-mode standalone matches; no control lies under the status
//   bar or the home indicator (with each scroller at its end), and a search field keeps its head's 8 px above it below
//   the status bar; every link that leaves kitespan opens outside the app (target _blank, rel noopener); the body turns
//   pull-to-refresh off; the theme-color meta that matches holds the page's --bg, or with a scrim up (a sheet, a
//   dialog, a drawer) the colour the page shows at its top under the status bar (read from a screenshot's pixel, within
//   2 on each channel); then the page's own control (never history.back()) closes it to its parent. Nothing mutating
//   goes out.
// - theme-color (1100x800 and 390x844, the device dark and light): each of the four looks by its tile in Settings >
//   Appearance (one POST /api/settings each), then the System, Light and Dark themes through a reload: both metas hold
//   shared/home-screen.ts's colours for the look and the theme, the one that matches the device holds the root's --bg,
//   and on the phone the title bar wears it. Glass and System are put back at the end.

/**
 * Installability notes that are the check's own, not the app's: its page sits in a browser context of its own (an
 * incognito one), and kitespan has no service worker on purpose (Chrome installs without one).
 */
const CHECK_OWN_INSTALL = new Set(["in-incognito", "warn-not-offline-capable", "no-matching-service-worker"]);

async function appFileChecks(base: string, scene: SceneName | null): Promise<CheckResult[]> {
  const out: CheckResult[] = [];
  let page = "";
  try {
    page = await (await fetch(base + "/", { signal: AbortSignal.timeout(5000) })).text();
  } catch {}
  const title = /<title>([^<]*)<\/title>/.exec(page)?.[1] ?? null;
  const head = page.slice(0, Math.max(0, page.indexOf("</head>")));
  for (const f of APP_FILES) {
    if (!picked([f.id], null)) continue;
    const t0 = Date.now();
    const failures: Finding[] = [];
    const warnings: Finding[] = [];
    const details: Record<string, unknown> = {};
    const fail = (text: string, code = "asset") => failures.push({ code, text });
    const path = ASSETS_PATH + f.file;
    const manifest = f.id === "app-manifest";
    try {
      // As the browser asks: no cookie; the manifest's fetch is a CORS-mode GET, an icon's an image fetch.
      const res = await fetch(base + path, { headers: { "sec-fetch-site": "same-origin", "sec-fetch-mode": manifest ? "cors" : "no-cors", "sec-fetch-dest": manifest ? "manifest" : "image" }, signal: AbortSignal.timeout(5000) });
      const body = Buffer.from(await res.arrayBuffer());
      Object.assign(details, { status: res.status, type: res.headers.get("content-type"), cache: res.headers.get("cache-control"), bytes: body.length });
      if (res.status !== 200) fail(`${path} answered HTTP ${res.status}`, "url");
      if (res.headers.get("content-type") !== f.type) fail(`${path} goes out as ${res.headers.get("content-type")}, not ${f.type}`);
      if (res.headers.get("cache-control") !== "no-cache") fail(`${path} has cache-control ${res.headers.get("cache-control")}, not no-cache (a stable name revalidates)`);
      if (manifest) {
        if (!title) fail("the page has no <title> to name the manifest by");
        else if (body.toString("utf8") !== JSON.stringify(appManifest(title))) fail(`the manifest is not shared/home-screen.ts's for "${title}": ${clip(body.toString("utf8"), 200)}`);
        if (!head.includes(`<link rel="manifest" href="${path}" crossorigin="use-credentials">`)) fail("the page's head has no link to the manifest that asks for credentials");
        // Chrome's own reading of it, from a page of the app.
        await withPage(VIEWPORTS[0]!, "dark", async (p) => {
          await p.navigate(base + "/");
          const m = await p.send<{ url: string; errors: { message: string; critical: number }[]; data?: string }>("Page.getAppManifest");
          const inst = await p.send<{ installabilityErrors: { errorId: string }[] }>("Page.getInstallabilityErrors").catch((e: Error) => ({ installabilityErrors: [{ errorId: `(not read: ${e.message})` }] }));
          details.chrome = { url: m.url, errors: m.errors, installability: inst.installabilityErrors.map((e) => e.errorId) };
          if (!m.url.endsWith(path)) fail(`Chrome reads the manifest from ${m.url || "nowhere"}`);
          if (m.errors.length) fail(`Chrome finds errors in the manifest: ${clipList(m.errors.map((e) => e.message))}`);
          const ids = inst.installabilityErrors.map((e) => e.errorId);
          const real = ids.filter((id) => !CHECK_OWN_INSTALL.has(id));
          if (real.length) fail(`Chrome would not install the app: ${clipList(real)}`, "install");
          issueFindings(p.takeIssues(), failures);
        });
      } else {
        const kept = readFileSync(join(import.meta.dir, "..", "web", "icons", f.file));
        if (!body.equals(kept)) fail(`${path} is not web/icons/${f.file} (${body.length} B, kept ${kept.length} B)`);
        const w = body.length > 24 ? body.readUInt32BE(16) : 0;
        const h = body.length > 24 ? body.readUInt32BE(20) : 0;
        if (w !== f.size || h !== f.size) fail(`${path} is ${w} x ${h}, not ${f.size} x ${f.size}`);
        if (f.file === APP_ICONS.find((i) => i.purpose === null)!.file && !head.includes(`<link rel="apple-touch-icon" href="${path}">`)) fail("the page's head has no apple-touch-icon link");
      }
    } catch (e) {
      fail(`the check could not run: ${(e as Error).message}`, "run");
    }
    const notes = (details.chrome as { installability?: string[] } | undefined)?.installability ?? [];
    const note = manifest ? `${MANIFEST_TYPE}; Chrome reads it with no error and finds nothing against installing${notes.length ? ` (the check's own: ${notes.join(", ")})` : ""}` : `${f.size} x ${f.size} PNG, as kept in web/icons`;
    out.push(finish({ kind: "route", name: f.id, route: "home", scene, size: "laptop", theme: "dark", path, failures, warnings, note, ms: Date.now() - t0, details }));
  }
  return out;
}

/** In-page helpers of these checks: an element counts as shown when it has a box and is not hidden. */
const U6_HELPERS = `
  const shown = (el) => {
    if (!el.getClientRects().length || el.closest('[hidden="until-found"]')) return false;
    const cs = getComputedStyle(el);
    return cs.visibility !== "hidden" && cs.visibility !== "collapse";
  };
  const describe = (el) => {
    if (!el || !el.tagName) return String(el);
    const id = el.getAttribute("data-testid");
    const label = (el.getAttribute("aria-label") || el.textContent || "").trim().replace(/\\s+/g, " ").slice(0, 24);
    return el.tagName.toLowerCase() + (id ? "[data-testid=" + id + "]" : label ? ' "' + label + '"' : "");
  };
`;

/**
 * The safe areas in standalone mode: an iPhone's status bar and home indicator, an iPad's; the laptop's are a large
 * iPad's (1366x1024 touch, which kitespan lays out as a laptop; the flow runs that size only with touch).
 */
const SAFE_AREAS: Partial<Record<SizeName, { top: number; bottom: number }>> = { phone: { top: 59, bottom: 34 }, medium: { top: 24, bottom: 20 }, laptop: { top: 24, bottom: 20 } };

/** The window that a Chrome started with --app opened: the only target in standalone mode (a new tab is not). */
interface AppWindow {
  chrome: OwnChrome;
  cdp: Cdp;
  targetId: string;
}

async function openAppWindow(base: string): Promise<AppWindow> {
  const binary = args.chrome ?? findChrome();
  if (!binary) throw new Error("no Chrome for Testing found; pass --chrome <binary> or set CHROME_PATH");
  const port = freePort(9341, 9349);
  if (!port) throw new Error("no free port from 9341 to 9349 for the app window's Chrome");
  const chrome = await launchChrome(binary, port, { extraArgs: [`--app=${base}/`] });
  try {
    const c = await Cdp.connect(chrome.wsUrl);
    for (let i = 0; i < 50; i++) {
      const { targetInfos } = await c.send<{ targetInfos: { type: string; targetId: string }[] }>("Target.getTargets");
      const page = targetInfos.find((x) => x.type === "page");
      if (page) return { chrome, cdp: c, targetId: page.targetId };
      await sleep(100);
    }
    c.close();
    throw new Error("the app window has no page target");
  } catch (e) {
    await chrome.stop();
    throw e;
  }
}

/** The app window's Chrome while the standalone flow runs, so an interrupted run stops it too (cleanup). */
let appWindow: AppWindow | null = null;

async function closeAppWindow(w: AppWindow) {
  w.cdp.close();
  await w.chrome.stop();
}

/**
 * Page.open makes a tab in a browser context of its own, which is never in standalone mode, so the flow puts the app
 * window's own target in a Page and gives it the size, touch, colour scheme and safe areas the same way.
 */
const PageOfTarget = Page as unknown as new (cdp: Cdp, session: string, targetId: string, contextId: string, vp: Viewport, theme: Theme) => Page;

async function withAppPage<T>(w: AppWindow, vp: Viewport, theme: Theme, run: (page: Page, wire: Wire) => Promise<T>): Promise<T> {
  const { sessionId } = await w.cdp.send<{ sessionId: string }>("Target.attachToTarget", { targetId: w.targetId, flatten: true });
  const page = new PageOfTarget(w.cdp, sessionId, w.targetId, "", vp, theme);
  const wire = new Wire(w.cdp, page);
  try {
    await Promise.all(["Page.enable", "Runtime.enable", "Log.enable", "Network.enable"].map((m) => page.send(m)));
    await page.send("Emulation.setFocusEmulationEnabled", { enabled: true });
    await page.send("Emulation.setEmulatedMedia", { media: "screen", features: [{ name: "prefers-color-scheme", value: theme }] });
    await page.send("Emulation.setTouchEmulationEnabled", vp.touch ? { enabled: true, maxTouchPoints: 5 } : { enabled: false });
    const inset = SAFE_AREAS[vp.name] ?? { top: 0, bottom: 0 };
    await page.send("Emulation.setSafeAreaInsetsOverride", { insets: { top: inset.top, bottom: inset.bottom, left: 0, right: 0 } });
    await page.metrics();
    return await run(page, wire);
  } finally {
    wire.dispose();
    await page.close(); // its listener; the app window's own context stays
    await w.cdp.send("Target.detachFromTarget", { sessionId }).catch(() => {});
  }
}

/**
 * The page in standalone mode: display-mode, the controls under a safe area (each scroller at its end first), the links
 * that leave kitespan and whether each opens outside the app, the body's overscroll, and the theme-color meta.
 */
const STANDALONE_PROBE = (top: number, bottom: number) => `(async () => {
  ${U6_HELPERS}
  for (const el of document.querySelectorAll("*")) {
    const cs = getComputedStyle(el);
    if ((cs.overflowY === "auto" || cs.overflowY === "scroll") && el.scrollHeight > el.clientHeight + 1) el.scrollTop = el.scrollHeight;
  }
  await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
  const sel = 'a[href], button, input, textarea, select, [role="button"], [role="menuitem"], [role="option"], [role="switch"], [role="tab"], [role="checkbox"], [role="radio"]';
  const under = [];
  for (const el of document.querySelectorAll(sel)) {
    if (!shown(el) || el.disabled || el.closest('[aria-hidden="true"], [inert]')) continue;
    const r = el.getBoundingClientRect();
    if (!r.width || !r.height) continue;
    let t = r.top, b = r.bottom, l = r.left, rr = r.right;
    for (let a = el.parentElement; a && a !== document.documentElement; a = a.parentElement) {
      const cs = getComputedStyle(a);
      if (cs.overflowX === "visible" && cs.overflowY === "visible") continue;
      const ar = a.getBoundingClientRect();
      t = Math.max(t, ar.top); b = Math.min(b, ar.bottom); l = Math.max(l, ar.left); rr = Math.min(rr, ar.right);
    }
    t = Math.max(t, 0); b = Math.min(b, innerHeight); l = Math.max(l, 0); rr = Math.min(rr, innerWidth);
    if (b - t < 1 || rr - l < 1) continue;
    const at = document.elementFromPoint((l + rr) / 2, (t + b) / 2);
    if (at && at !== el && !el.contains(at) && !at.contains(el)) continue; // under another layer there, not reachable
    if (t < ${top} - 0.5 || b > innerHeight - ${bottom} + 0.5) under.push(describe(el) + " " + Math.round(t) + "-" + Math.round(b));
  }
  const out = [];
  for (const a of document.querySelectorAll("a[href]")) {
    let u;
    try { u = new URL(a.getAttribute("href"), location.href); } catch { continue; }
    if (u.origin === location.origin || !/^https?:$/.test(u.protocol)) continue;
    const rel = (a.getAttribute("rel") || "").split(/\\s+/);
    out.push({ href: u.origin + u.pathname, blank: a.getAttribute("target") === "_blank", noopener: rel.includes("noopener") });
  }
  const metas = [...document.querySelectorAll('meta[name="theme-color"]')];
  const on = metas.find((m) => matchMedia(m.getAttribute("media") || "all").matches);
  // A scrim (under a sheet, a dialog or a drawer) dims the whole page: the point under the status bar, above the
  // middle of the title bar, where the flow reads the colour the page shows there (once the scrim has faded in).
  let scrim = null;
  if ([...document.querySelectorAll(".scrim")].some(shown)) {
    const fading = document.getAnimations().filter((a) => a.effect && a.effect.target && a.effect.target.classList && a.effect.target.classList.contains("scrim"));
    await Promise.race([Promise.all(fading.map((a) => a.finished.catch(() => {}))), new Promise((r) => setTimeout(r, 1500))]);
    const bar = [...document.querySelectorAll('[data-testid="topbar"]')].find(shown);
    const br = bar ? bar.getBoundingClientRect() : null;
    // v0.6 touch (DESIGN-T1 3.1): with a drawer open, the scrim's own part is right of the drawer (at 626 the drawer's
    // 320 px reach past the window's middle).
    const drawer = [...document.querySelectorAll(".shell-drawer, .scr-drawer")].find(shown);
    const dr = drawer ? drawer.getBoundingClientRect().right : 0;
    const x = Math.round(dr ? (dr + innerWidth) / 2 : br ? (br.left + br.right) / 2 : innerWidth / 2), y = 2;
    const at = document.elementFromPoint(x, y);
    scrim = { x, y, drawer: dr ? Math.round(dr) : null, top: at && at.classList.contains("scrim") ? null : describe(at) };
  }
  // The search field's room above it in its head (search.css .srch-head: --s2), below the status bar.
  const searchHeads = [...document.querySelectorAll(".srch-head")].filter(shown).map((h) => {
    const f = h.querySelector(".srch-field") || h.querySelector("input");
    return f ? { head: Math.round(h.getBoundingClientRect().top * 10) / 10, field: Math.round(f.getBoundingClientRect().top * 10) / 10 } : null;
  }).filter(Boolean);
  return {
    standalone: matchMedia("(display-mode: standalone)").matches,
    under,
    out,
    overscroll: getComputedStyle(document.body).overscrollBehaviorY,
    bodyOverflow: getComputedStyle(document.body).overflowY,
    meta: on ? on.getAttribute("content") : null,
    bg: getComputedStyle(document.documentElement).getPropertyValue("--bg").trim().toLowerCase(),
    scrim,
    searchHeads,
  };
})()`;
type StandaloneLook = {
  standalone: boolean;
  under: string[];
  out: { href: string; blank: boolean; noopener: boolean }[];
  overscroll: string;
  bodyOverflow: string;
  meta: string | null;
  bg: string;
  scrim: { x: number; y: number; drawer: number | null; top: string | null } | null;
  searchHeads: { head: number; field: number }[];
};

/** The colour the page shows at one CSS pixel (a PNG of that pixel; its first device pixel), as #rrggbb. */
async function pixelAt(page: Page, x: number, y: number): Promise<string> {
  const shot = await page.send<{ data: string }>("Page.captureScreenshot", { format: "png", clip: { x, y, width: 1, height: 1, scale: 1 }, captureBeyondViewport: false });
  const [r, g, b] = readPng(Buffer.from(shot.data, "base64")).at(0, 0);
  return `#${[r, g, b].map((v) => v.toString(16).padStart(2, "0")).join("")}`;
}
/** Two #rrggbb colours within `d` of each other on each channel (a composite's rounding). */
const nearColor = (a: string, b: string, d = 2) => /^#[0-9a-f]{6}$/.test(a) && /^#[0-9a-f]{6}$/.test(b) && [1, 3, 5].every((i) => Math.abs(parseInt(a.slice(i, i + 2), 16) - parseInt(b.slice(i, i + 2), 16)) <= d);

/** The control a screen closes with: a selector, or inside a test id a Back, the phone's chats button, or Done, Cancel or Close. */
const CLOSE_CONTROL = (close: { sel?: string; within?: string }) => `(() => {
  ${U6_HELPERS}
  let el = null;
  if (${JSON.stringify(close.sel ?? null)}) el = [...document.querySelectorAll(${JSON.stringify(close.sel ?? "")})].filter(shown).pop() || null;
  else {
    const boxes = [...document.querySelectorAll('[data-testid="' + ${JSON.stringify(close.within ?? "")} + '"]')].filter(shown);
    const box = boxes[boxes.length - 1];
    if (!box) return null;
    const name = (e) => (e.getAttribute("aria-label") || e.textContent || "").trim().replace(/\\s+/g, " ");
    const els = [...box.querySelectorAll("a[href], button")].filter((e) => shown(e) && !e.disabled);
    el = els.find((e) => e.classList.contains("scr-bar-back") || e.classList.contains("scr-bar-chats")) || els.find((e) => /^(Back|Done|Cancel|Close)\\b/.test(name(e))) || null;
  }
  if (!el) return null;
  const r = el.getBoundingClientRect();
  const x = r.left + r.width / 2, y = r.top + r.height / 2;
  const at = document.elementFromPoint(x, y);
  return { x, y, label: (el.getAttribute("aria-label") || el.textContent || "").trim().replace(/\\s+/g, " "), covered: at && !(at === el || el.contains(at)) ? describe(at) : null };
})()`;

interface StandaloneCase {
  path: string;
  shows: string[];
  /** How the page closes it, or null for a screen at the top (Home, the list). */
  close: { sel?: string; within?: string } | null;
  /** Where the close goes: a path, or any path that is not this one's. */
  to?: string;
  sizes: SizeName[];
  shot?: string;
}

function standaloneCases(): StandaloneCase[] {
  const C = `/c/${EX.chat}`;
  const P = `/p/${EX.project}`;
  const both: SizeName[] = ["phone", "medium"];
  // "laptop" is the large iPad here (1366x1024 touch, the laptop's layout): it closes as a laptop does, by the pane's
  // or the dialog's own control, and keeps Esc and the sidebar where a laptop has no Back.
  const all: SizeName[] = ["phone", "medium", "laptop"];
  const wide: SizeName[] = ["medium", "laptop"];
  return [
    { path: "/", shows: ["home"], close: null, sizes: all, shot: "home" },
    { path: "/chats", shows: ["chat-list"], close: null, sizes: ["phone"] },
    // The tablet's list is a drawer over the page; its scrim closes it.
    { path: "/chats", shows: ["chat-list"], close: { sel: ".scrim" }, sizes: ["medium"] },
    { path: "/chats", shows: ["sidebar"], close: null, sizes: ["laptop"] },
    { path: C, shows: [CARD_OR_COMPOSER], close: { within: "topbar" }, to: "/chats", sizes: ["phone"], shot: "chat" },
    { path: C, shows: [CARD_OR_COMPOSER], close: null, sizes: wide, shot: "chat" },
    { path: `${C}/details`, shows: ["side-environment"], close: { within: "side-panel" }, to: C, sizes: both },
    { path: `${C}/details`, shows: ["side-environment"], close: null, sizes: ["laptop"] },
    { path: `${C}/model`, shows: ["picker-model"], close: { within: "picker-model" }, to: C, sizes: ["phone"] },
    { path: `${C}/rename`, shows: ["dialog-rename"], close: { within: "dialog-rename" }, to: C, sizes: all },
    { path: `${C}/archive`, shows: ["dialog-archive"], close: { within: "dialog-archive" }, to: C, sizes: all },
    { path: `${C}/uploads`, shows: ["uploads|uploads-page"], close: { within: "topbar" }, to: C, sizes: ["phone"] },
    { path: `${C}/uploads`, shows: ["uploads|uploads-page"], close: { sel: ".pane-bar-btn.on" }, to: C, sizes: ["medium"] },
    { path: `${C}/uploads`, shows: ["uploads|uploads-page"], close: null, sizes: ["laptop"] },
    { path: `${C}/search`, shows: ["search"], close: { within: "topbar" }, to: C, sizes: ["phone"] },
    { path: `${C}/search`, shows: ["search"], close: { within: "search" }, to: C, sizes: wide },
    { path: `${C}/shell`, shows: ["terminal-pane"], close: { within: "topbar" }, to: C, sizes: ["phone"] },
    { path: `${C}/shell`, shows: ["terminal-pane"], close: { within: "terminal-pane" }, to: C, sizes: wide },
    { path: "/settings", shows: ["settings"], close: { within: "topbar" }, sizes: ["phone"] },
    { path: "/settings", shows: ["settings"], close: { sel: '[data-testid="settings-done"]' }, sizes: wide },
    { path: "/settings/appearance", shows: ["settings-appearance"], close: { within: "topbar" }, to: "/settings", sizes: ["phone"] },
    { path: "/search", shows: ["search-page"], close: { within: "topbar" }, sizes: both, shot: "search" },
    { path: "/search", shows: ["search-page"], close: null, sizes: ["laptop"], shot: "search" },
    { path: P, shows: ["project"], close: { within: "topbar" }, to: "/chats", sizes: ["phone"] },
    { path: P, shows: ["project"], close: null, sizes: ["laptop"] },
    { path: `${P}/environment`, shows: ["project-environment"], close: { within: "topbar" }, to: P, sizes: all, shot: "environment" },
    { path: `${P}/session/${EX.session}`, shows: ["session-preview"], close: { within: "topbar" }, to: P, sizes: all },
    { path: "/new", shows: ["new-chat"], close: { within: "topbar" }, to: "/chats", sizes: ["phone"] },
  ];
}

async function standaloneFlow(w: AppWindow, base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const steps: Record<string, unknown>[] = [];
  const details: Record<string, unknown> = { steps };
  const inset = SAFE_AREAS[vp.name] ?? { top: 0, bottom: 0 };
  let shot: string | undefined;
  try {
    await withAppPage(w, vp, theme, async (page, wire) => {
      for (const c of standaloneCases().filter((x) => x.sizes.includes(vp.name))) {
        const at = (text: string, code = "flow") => failures.push({ code, text: `${c.path}: ${text}` });
        await page.navigate(base + c.path);
        const s = await waitShown(page, c.shows);
        const missing = c.shows.filter((x) => !shownMatch(x, s.ids));
        if (missing.length) at(`not shown: ${missing.map(describeWant).join(", ")}`, "shows");
        if (!sameUrl(s.path, c.path)) at(`the URL changed to ${s.path}`, "url");
        stateFindings(s, vp, failures, `${c.path}: `);
        issueFindings(page.takeIssues(), failures, `${c.path}: `);
        if (c.shot) {
          const file = shotName(scene, "standalone", vp, theme, vp.name === "laptop" ? `${c.shot}-${vp.width}` : c.shot);
          await page.screenshot(file);
          shot ??= file;
        }
        const look = await page.evaluate<StandaloneLook>(STANDALONE_PROBE(inset.top, inset.bottom));
        const step: Record<string, unknown> = { path: c.path, look };
        steps.push(step);
        if (c.path === "/") {
          // Chrome's own view from the app window (a profile of its own, no incognito context): nothing against installing.
          const inst = await page.send<{ installabilityErrors: { errorId: string }[] }>("Page.getInstallabilityErrors").catch(() => null);
          step.installability = inst?.installabilityErrors.map((e) => e.errorId) ?? null;
          const real = (inst?.installabilityErrors ?? []).map((e) => e.errorId).filter((id) => !CHECK_OWN_INSTALL.has(id));
          if (real.length) at(`Chrome would not install the app: ${clipList(real)}`, "install");
        }
        if (!look.standalone) at("the window does not match (display-mode: standalone)", "standalone");
        if (look.under.length) at(`under the ${inset.top} px status bar or the ${inset.bottom} px home indicator: ${clipList(look.under, 4)}`, "safe-area");
        const inApp = look.out.filter((o) => !o.blank || !o.noopener);
        if (inApp.length) at(`links that leave kitespan but open in the app: ${clipList(inApp.map((o) => o.href), 4)}`, "link");
        if (look.overscroll !== "none" && look.overscroll !== "contain" && look.bodyOverflow !== "hidden") at(`the body allows pull-to-refresh (overscroll-behavior-y ${look.overscroll})`, "refresh");
        if (look.scrim) {
          // A sheet, a dialog or a drawer dims the page: the status bar takes the colour the page shows under it.
          if (look.scrim.top) at(`the top of the page under the status bar is ${look.scrim.top}, not the scrim`, "theme-color");
          const shown = await pixelAt(page, look.scrim.x, look.scrim.y);
          step.underScrim = shown;
          if (!nearColor(hex6(look.meta), shown)) at(`with the scrim up the theme-color meta holds ${look.meta}, the page shows ${shown} at its top`, "theme-color");
        } else if (hex6(look.meta) !== hex6(look.bg)) at(`the theme-color meta holds ${look.meta}, the page's --bg is ${look.bg}`, "theme-color");
        for (const h of look.searchHeads) {
          const room = h.field - Math.max(h.head, inset.top);
          if (room < 7.5) at(`the search field has ${room} px above it below the ${inset.top} px status bar, not the head's 8`, "safe-area");
        }
        if (!c.close) continue;
        const ctl = await page.evaluate<{ x: number; y: number; label: string; covered: string | null } | null>(CLOSE_CONTROL(c.close));
        step.close = ctl;
        if (!ctl) {
          at("no control of the page closes it", "back");
          continue;
        }
        // An open drawer covers the band's chats button where the drawer is wider than half the window: the scrim's own
        // part closes it, as a finger does.
        const viaScrim = !!ctl.covered && !!look.scrim?.drawer;
        if (ctl.covered && !viaScrim) at(`its ${JSON.stringify(ctl.label)} is covered by ${ctl.covered}`, "back");
        if (viaScrim) await page.press(Math.round((look.scrim!.drawer! + vp.width) / 2), Math.round(vp.height / 2));
        else await page.press(ctl.x, ctl.y);
        await sleep(400);
        await page.settle();
        const after = await page.probe();
        step.after = after.path;
        if (c.to ? !samePath(after.path, c.to) : samePath(after.path, c.path) || after.path.startsWith(c.path + "/")) at(`${JSON.stringify(ctl.label)} went to ${after.path}, not ${c.to ?? "out of it"}`, "back");
        issueFindings(page.takeIssues(), failures, `${c.path}, after ${JSON.stringify(ctl.label)}: `);
      }
      quietFindings(wire, 0, await recorder(page), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the flow could not run: ${(e as Error).message}` });
  }
  const n = steps.length;
  const size = `${vp.width}x${vp.height}${vp.touch ? " touch" : ""}`;
  return finish({ kind: "flow", name: "standalone", route: "home", scene, size: sizeTag(vp), theme, path: "/", failures, warnings, note: `${n} screens at ${size} in an app window (display-mode standalone, safe areas ${inset.top} and ${inset.bottom} px); each closed by its own control; with a scrim up the theme-color meta is the page's colour at its top; nothing sent`, shot, ms: Date.now() - t0, details });
}

/** The two metas, the one that matches the device, the root's --bg, and the title bar's colour. */
const THEME_META_PROBE = `(() => {
  const metas = [...document.querySelectorAll('meta[name="theme-color"]')];
  const on = metas.find((m) => matchMedia(m.getAttribute("media") || "all").matches);
  const bar = [...document.querySelectorAll('[data-testid="topbar"]')].find((e) => e.getClientRects().length);
  return {
    light: (metas.find((m) => /light/.test(m.getAttribute("media") || "")) || { getAttribute: () => null }).getAttribute("content"),
    dark: (metas.find((m) => /dark/.test(m.getAttribute("media") || "")) || { getAttribute: () => null }).getAttribute("content"),
    count: metas.length,
    on: on ? on.getAttribute("content") : null,
    bg: getComputedStyle(document.documentElement).getPropertyValue("--bg").trim().toLowerCase(),
    bar: bar ? getComputedStyle(bar).backgroundColor : null,
    look: document.documentElement.getAttribute("data-look") || "glass",
  };
})()`;
type ThemeMeta = { light: string | null; dark: string | null; count: number; on: string | null; bg: string; bar: string | null; look: string };

/** A CSS hex colour in its six-digit lower-case form (the built style sheet writes #fff for #ffffff). */
const hex6 = (c: string | null | undefined) => {
  const v = (c ?? "").trim().toLowerCase();
  return /^#[0-9a-f]{3}$/.test(v) ? `#${[...v.slice(1)].map((d) => d + d).join("")}` : v;
};
const rgbOf = (hex: string) => `rgb(${parseInt(hex.slice(1, 3), 16)}, ${parseInt(hex.slice(3, 5), 16)}, ${parseInt(hex.slice(5, 7), 16)})`;

async function themeColorFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const steps: Record<string, unknown>[] = [];
  const details: Record<string, unknown> = { steps };
  const fail = (text: string, code = "theme-color") => failures.push({ code, text });
  let shot: string | undefined;
  let posts = 0;
  const looks = ["glass", "paper", "mono", "editor"] as const;
  try {
    await withPage(vp, theme, async (page, wire) => {
      const appearance = "/settings/appearance";
      const check = async (look: (typeof looks)[number], chosen: "system" | "light" | "dark", how: string) => {
        const m = await page.evaluate<ThemeMeta>(THEME_META_PROBE);
        steps.push({ want: look, chosen, how, ...m });
        const want = themeColorMetas(look, chosen);
        const where = `${look}, ${chosen === "system" ? "System" : chosen === "light" ? "Light" : "Dark"} on a ${theme} device, ${how}`;
        if (m.look !== look) fail(`${where}: the page wears ${m.look}`);
        if (m.count !== 2 || m.light !== want.light || m.dark !== want.dark) fail(`${where}: the metas hold ${m.light} and ${m.dark}, not ${want.light} and ${want.dark}`);
        if (hex6(m.on) !== hex6(m.bg)) fail(`${where}: the meta that matches holds ${m.on}, the page's --bg is ${m.bg}`);
        if (vp.name === "phone" && m.bar !== rgbOf(hex6(m.bg))) fail(`${where}: the title bar is ${m.bar}, not the --bg ${m.bg}`);
      };
      const wear = async (look: (typeof looks)[number]) => {
        const at = await page.locate(`[data-testid="look-${look}"]`);
        if (!at) return fail(`Settings > Appearance has no ${look} tile`, "shows");
        const mark = wire.mark();
        await page.press(at.x, at.y);
        await sleep(400);
        await page.settle();
        posts += wire.httpSince(mark).filter((h) => h.method === "POST" && h.path === "/api/settings").length;
      };
      await page.navigate(base + appearance);
      await waitShown(page, ["settings-appearance", "look-picker"]);
      await check("glass", "system", "at load");
      for (const look of looks) {
        if (look !== "glass") {
          await wear(look);
          await check(look, "system", "after its tile");
        }
        for (const chosen of ["light", "dark", "system"] as const) {
          await page.evaluate(DEVICE_SETTING("theme", chosen));
          await page.reload();
          await waitShown(page, ["settings-appearance"]);
          await check(look, chosen, "after a reload");
        }
        if (look === "paper" && vp.name === "phone") {
          shot = shotName(scene, "theme-color", vp, theme, look);
          await page.screenshot(shot);
        }
      }
      await wear("glass");
      await check("glass", "system", "back to Glass");
      if (posts !== 4) fail(`the four tile presses sent ${posts} POST /api/settings, not 4`, "frames");
      issueFindings(page.takeIssues(), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the flow could not run: ${(e as Error).message}` });
  }
  return finish({ kind: "flow", name: "theme-color", route: "settingsSection", scene, size: sizeTag(vp), theme, path: "/settings/appearance", failures, warnings: [], note: `the four looks, System, Light and Dark: the theme-color meta holds the page's --bg (${steps.length} states)`, shot, ms: Date.now() - t0, details });
}

function print(r: CheckResult) {
  const tag = r.status === "pass" ? "PASS" : r.status === "warn" ? "WARN" : "FAIL";
  const where = r.scene && r.scene !== "main" ? `${r.name}[${r.scene}]` : r.name;
  const head = `${tag}  ${r.kind.padEnd(7)} ${where.padEnd(24)} ${r.size.padEnd(10)} ${r.theme.padEnd(5)} ${r.path}`;
  const findings = [...r.failures, ...r.warnings].map((f) => f.text);
  console.log(clip(`${head}  ${findings.length ? findings.join("; ") : r.note}`, 700));
}

async function pool<T>(items: T[], jobs: number, run: (item: T) => Promise<void>) {
  let next = 0;
  await Promise.all(
    Array.from({ length: Math.min(jobs, items.length) }, async () => {
      while (next < items.length && !cdp.closed) await run(items[next++]!);
    }),
  );
}

let own: OwnChrome | null = null;
let stopping = false;
/** The built page the harness serves (a scratch folder unless --dist named one). */
let built: string | null = null;
const live = new Set<Booted>();
async function cleanup() {
  if (stopping) return;
  stopping = true;
  for (const b of [...live]) await b.stop().catch(() => {});
  cdp?.close();
  await own?.stop();
  if (appWindow) await closeAppWindow(appWindow).catch(() => {});
  if (built && !args.dist) rmSync(built, { recursive: true, force: true });
}
for (const sig of ["SIGINT", "SIGTERM"] as const)
  process.on(sig, () => {
    console.error(`ui-check: ${sig}, stopping`);
    cleanup().finally(() => process.exit(130));
  });

interface Target {
  base: string;
  scene: RouteSceneName | null;
  booted: Booted | null;
}

/** A target for checks in one scene: a fresh boot of its seed (the harness), or the --base copy. */
async function openTarget(scene: RouteSceneName | null, origins?: string[], fixture?: Partial<Fixture>): Promise<Target> {
  if (BASE) return { base: BASE, scene: null, booted: null };
  const b = await boot({ scene: scene!, port: PORT, dist: built!, keep: KEEP, origins, fixture, env: SERVER_ENV });
  live.add(b);
  return { base: b.base, scene, booted: b };
}

async function closeTarget(t: Target, problems: string[]) {
  if (!t.booted) return;
  const r = await t.booted.stop();
  live.delete(t.booted);
  if (r.code !== 0) problems.push(`scene ${t.scene}: the server exited with ${r.code}`);
  if (r.leftovers.length) problems.push(`scene ${t.scene}: ${r.leftovers.length} process(es) outlived the server and were ended by pid`);
}

// ---------------------------------------------------------------------------------------------------------------
// Row 111: Send now on a queued message (DESIGN.md 6.3, 6.4, 6.11), each on a seed of its own, with the click-through
// fixture's two send-now turns (test/click/seed/fixture.ts SEND_NOW: a story that streams for about 30 s, and a long
// Bash command whose foreground task starts 0.6 s after its call).
//
// - send-now (1280x800, and 390x844 with touch; light and dark): during the story two messages queue. Both are the
//   plain bubble (a sent message's fill and edge), the conversation has no Queued word, and one Send now shows, under
//   the last: right-aligned to the bubble, in the look's --dim at its --fs-meta, with no border, no fill and no
//   shadow, a 44 px target on touch with its text still at the meta size; the same under Reduce motion and, at
//   1280x800 in light, in each of the four looks (a shot of each). Hover (a tap on touch) shows the bubble's menu, Copy
//   and Take back; Take back on the first message sends one take_back and puts its text back in the box. Send now (a
//   double click on the laptop) sends one send_now for the last message, acted "interrupt": the story ends with
//   Interrupted, the message runs next as its own turn (the fake claude starts it once, after one interrupt) and is
//   drawn as sent, with no Send now left. Then during the long command a queued message and Send now: one send_now,
//   acted "background" (one background_tasks request), and Claude reads the message in the same turn (the fake claude
//   takes it in at the tool boundary and starts no turn for it); it is drawn as sent, above the reply that read it.
// - send-now-key (1280x800): Settings' shortcut list names Send now with Ctrl+Enter; Ctrl+Enter with no turn running
//   only sends; during the story Meta+Enter (not the key off macOS) only queues, and Ctrl+Enter in the empty box is
//   Send now alone (one send_now for the queued message, no send, acted "interrupt"); then a queued message and a draft
//   with Ctrl+Enter: one send, then one send_now for the draft's message, the box empty, no Send now under it at any
//   time, and both run next in send order; in `!` mode Ctrl+Enter only queues the command (one bash frame).

/** The messages that the send-now flows queue (each run has a seed of its own). */
const NOW_FIRST = "Use the shorter title in the story.";
const NOW_LAST = "Stop the story and list three kite colours.";
const NOW_READ = "Use the new name for the output file.";
const KEY_PLAIN = "Plain Ctrl Enter with nothing running.";
const KEY_QUEUED = "Queued with Meta Enter, sent now with Ctrl Enter.";
const KEY_BEHIND = "Queued first, before the draft.";
const KEY_DRAFT = "The draft that Ctrl Enter sends now.";

type NowButton = { text: string; w: number; h: number; right: number; top: number; color: string; fontSize: string; bg: string; bgImage: string; border: string; shadow: string; covered: boolean; inView: boolean };
type NowUser = { id: string; text: string; queued: boolean; bubble: { bg: string; shadow: string; right: number; bottom: number; x: number; y: number } | null; now: NowButton | null; takeBack: { shown: boolean; opacity: number } | null; copy: { shown: boolean; opacity: number } | null };
interface NowLook {
  /** The conversation's rows, by item id, in order. */
  rows: string[];
  users: NowUser[];
  /** Send now buttons that show anywhere on the page. */
  nows: number;
  /** The word Queued shows in the conversation. */
  queuedWord: boolean;
  /** The look's own --dim and --fs-meta, as computed. */
  token: { dim: string; meta: string };
  interrupted: number;
  working: number;
  /** Claude's replies, by item id: their text. */
  texts: Record<string, string>;
  field: string | null;
}

const NOW_LOOK = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const fold = (s) => (s || "").replace(/\\s+/g, " ").trim();
  const conv = document.querySelector('[data-testid="conversation"]');
  const items = conv ? [...conv.querySelectorAll('[data-testid^="item-"]')] : [];
  const idOf = (el) => el.getAttribute("data-testid").slice(5);
  const vis = (el) => (el ? { shown: shown(el), opacity: shown(el) ? Number(getComputedStyle(el).opacity) : 0 } : null);
  const button = (el) => {
    if (!shown(el)) return null;
    const r = el.getBoundingClientRect();
    const cs = getComputedStyle(el);
    const at = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
    return {
      text: fold(el.textContent), w: Math.round(r.width), h: Math.round(r.height), right: r.right, top: r.top,
      color: cs.color, fontSize: cs.fontSize, bg: cs.backgroundColor, bgImage: cs.backgroundImage,
      border: [cs.borderTopWidth, cs.borderRightWidth, cs.borderBottomWidth, cs.borderLeftWidth].join(" "), shadow: cs.boxShadow,
      covered: !!at && !(at === el || el.contains(at)),
      inView: r.top >= -0.5 && r.bottom <= innerHeight + 0.5 && r.left >= -0.5 && r.right <= innerWidth + 0.5,
    };
  };
  const users = items.filter((el) => el.querySelector(".chat-user")).map((el) => {
    const u = el.querySelector(".chat-user");
    const b = u.querySelector(".chat-bubble");
    const bs = b ? getComputedStyle(b) : null;
    const br = b ? b.getBoundingClientRect() : null;
    return {
      id: idOf(el), text: fold(b ? b.textContent : ""), queued: u.classList.contains("is-queued"),
      bubble: b ? { bg: bs.backgroundColor, shadow: bs.boxShadow, right: br.right, bottom: br.bottom, x: br.left + br.width / 2, y: br.top + br.height / 2 } : null,
      now: button(u.querySelector('[data-testid="send-now"]')),
      takeBack: vis(u.querySelector('[data-testid="confirm-take-back"]')),
      copy: vis(u.querySelector('[data-testid="copy-message"]')),
    };
  });
  const probe = document.createElement("span");
  probe.style.color = "var(--dim)";
  probe.style.fontSize = "var(--fs-meta)";
  document.body.appendChild(probe);
  const token = { dim: getComputedStyle(probe).color, meta: getComputedStyle(probe).fontSize };
  probe.remove();
  const texts = {};
  for (const el of items) {
    const prose = el.querySelector(".chat-assistant > div:first-child");
    if (prose) texts[idOf(el)] = fold(prose.textContent);
  }
  const box = [...document.querySelectorAll('[data-testid="composer"]')].find(shown);
  const input = box ? box.querySelector('[data-testid="composer-input"]') : null;
  return {
    rows: items.map(idOf),
    users,
    nows: [...document.querySelectorAll('[data-testid="send-now"]')].filter(shown).length,
    queuedWord: /\\bQueued\\b/.test(fold(conv ? conv.textContent : "")),
    token,
    interrupted: [...document.querySelectorAll(".chat-foot-line")].filter((e) => shown(e) && fold(e.textContent) === "Interrupted").length,
    working: [...document.querySelectorAll(".chat-working")].filter(shown).length,
    texts,
    field: input ? input.value : null,
  };
})())`;

/** In-page: every time a Send now shows, the row it is under; window.__uiNowSeen. */
const NOW_SAMPLER = `(() => {
  const seen = (window.__uiNowSeen = []);
  clearInterval(window.__uiNowTimer);
  window.__uiNowTimer = setInterval(() => {
    for (const el of document.querySelectorAll('[data-testid="send-now"]')) {
      if (!el.getClientRects().length) continue;
      const row = el.closest('[data-testid^="item-"]');
      seen.push({ id: row ? row.getAttribute("data-testid").slice(5) : null, at: Date.now() });
    }
  }, 15);
  return true;
})()`;
const NOW_SEEN = `JSON.stringify((() => { clearInterval(window.__uiNowTimer); return window.__uiNowSeen || []; })())`;

const nowLook = async (page: Page) => JSON.parse(await page.evaluate<string>(NOW_LOOK)) as NowLook;
async function untilNow(page: Page, ok: (s: NowLook) => boolean, ms: number): Promise<{ s: NowLook; ok: boolean }> {
  const end = Date.now() + ms;
  for (;;) {
    const s = await nowLook(page).catch(() => null);
    if (s && ok(s)) return { s, ok: true };
    if (Date.now() > end) return { s: s ?? (await nowLook(page)), ok: false };
    await sleep(100);
  }
}
const userOf = (s: NowLook, text: string) => s.users.find((u) => u.text === text) ?? null;
const TRANSPARENT = new Set(["rgba(0, 0, 0, 0)", "transparent"]);

/**
 * The queued bubbles and Send now as the owner's screenshot shows them: each queued bubble is a sent one's (`sent`),
 * one Send now in the page, under `last` only, right-aligned to its bubble, in the look's --dim at --fs-meta, with no
 * border, fill or shadow; on touch a 44 px target. `where` names the theme and look for the findings.
 */
function nowLookFindings(s: NowLook, vp: Viewport, sent: string, queued: string[], last: string, where: string, fail: (text: string) => void) {
  if (s.queuedWord) fail(`${where}, the conversation shows the word Queued`);
  if (s.nows !== 1) fail(`${where}, ${s.nows} Send now buttons show, not one`);
  const plain = userOf(s, sent)?.bubble;
  for (const text of queued) {
    const u = userOf(s, text);
    if (!u) {
      fail(`${where}, the queued message "${text}" does not show`);
      continue;
    }
    if (!u.queued) fail(`${where}, "${text}" is not drawn as queued (no is-queued)`);
    if (plain && u.bubble && (u.bubble.bg !== plain.bg || u.bubble.shadow !== plain.shadow)) fail(`${where}, the queued bubble "${text}" is not the plain bubble (fill ${u.bubble.bg} and edge ${u.bubble.shadow}, a sent one's ${plain.bg} and ${plain.shadow})`);
    if (text !== last && u.now) fail(`${where}, Send now shows under "${text}", which is not the last queued message`);
  }
  const u = userOf(s, last);
  const b = u?.now;
  if (!u || !b) return fail(`${where}, no Send now under the last queued message`);
  if (b.text !== "Send now") fail(`${where}, the button under the last queued message reads ${JSON.stringify(b.text)}`);
  if (u.bubble) {
    if (Math.abs(b.right - u.bubble.right) > 1.5) fail(`${where}, Send now ends at x ${Math.round(b.right)}, not at the bubble's right edge (${Math.round(u.bubble.right)})`);
    if (b.top < u.bubble.bottom - 0.5) fail(`${where}, Send now is not under the bubble`);
  }
  if (b.color !== s.token.dim) fail(`${where}, Send now's colour is ${b.color}, not the look's --dim (${s.token.dim})`);
  if (b.fontSize !== s.token.meta) fail(`${where}, Send now's text is ${b.fontSize}, not the look's --fs-meta (${s.token.meta})`);
  if (b.border !== "0px 0px 0px 0px") fail(`${where}, Send now has a border (${b.border})`);
  if (!TRANSPARENT.has(b.bg) || b.bgImage !== "none") fail(`${where}, Send now has a fill (${b.bg}, ${b.bgImage})`);
  if (b.shadow !== "none") fail(`${where}, Send now has a shadow (${b.shadow})`);
  if (b.covered) fail(`${where}, something covers Send now`);
  if (!b.inView) fail(`${where}, Send now is out of the window`);
  if (vp.touch && (b.w < 44 || b.h < 44)) fail(`${where}, Send now's target is ${b.w}x${b.h} px on touch, under 44 px`);
}

/** The fake claude's trace lines since `at` (its own clock is this machine's). */
const traceSince = (t: Target, at: number) => t.booted!.trace().filter((l) => l.at >= at);
const turnsOf = (t: Target, uuid: string) => t.booted!.trace().filter((l) => l.t === "turn_start" && l.uuid === uuid).length;
const controls = (t: Target, at: number, subtype: string) => traceSince(t, at).filter((l) => l.t === "control" && l.subtype === subtype).length;

/** The CSS transitions that run (a switch of theme fades the composer's colours) have ended, or 2 s went by. */
const TRANSITIONS_DONE = `Promise.race([Promise.all(document.getAnimations().filter((a) => a instanceof CSSTransition).map((a) => a.finished.catch(() => null))), new Promise((r) => setTimeout(r, 2000))]).then(() => true)`;

/** Put the page in a look (glass: no data-look) and a theme (the emulated colour scheme, as a device's System theme). */
async function wearLook(page: Page, look: P2LookId, theme: Theme) {
  await page.evaluate(`(() => { const r = document.documentElement; ${look === "glass" ? `r.removeAttribute("data-look")` : `r.setAttribute("data-look", ${JSON.stringify(look)})`}; return true; })()`);
  await page.send("Emulation.setEmulatedMedia", { media: "screen", features: [{ name: "prefers-color-scheme", value: theme }] });
  await page.evaluate(P2_DRAWN);
  await page.evaluate(TRANSITIONS_DONE);
}

/** Press Send now as a user does: a click (on the laptop, a double click, which must still send one frame) or a tap. */
async function pressSendNow(page: Page, double: boolean): Promise<boolean> {
  const at = await page.locate('[data-testid="send-now"]');
  if (!at) return false;
  if (!double) {
    await page.press(at.x, at.y);
    return true;
  }
  await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: at.x, y: at.y });
  for (const clickCount of [1, 2]) {
    await page.send("Input.dispatchMouseEvent", { type: "mousePressed", x: at.x, y: at.y, button: "left", buttons: 1, clickCount });
    await page.send("Input.dispatchMouseEvent", { type: "mouseReleased", x: at.x, y: at.y, button: "left", buttons: 0, clickCount });
  }
  return true;
}

/** The one send_now that a press sent (or a finding), and its ack's `acted`. */
async function oneSendNow(wire: Wire, inbox: Inbox, since: number, iSince: number, uuid: string, want: string, what: string, fail: (text: string) => void): Promise<string | null> {
  await waitSent(wire, since);
  const sent = acting(wire.framesSince(since));
  const now = sent.filter((f) => f.t === "send_now");
  if (sent.length !== 1 || now.length !== 1) fail(`${what} sent ${clipList(sent.map(frameText)) || "nothing"}; expected one send_now`);
  const f = now[0];
  if (!f) return null;
  if (f.frame.chat !== EX.chat) fail(`${what}: the send_now names the chat ${JSON.stringify(f.frame.chat)}`);
  if (f.frame.uuid !== uuid) fail(`${what}: the send_now names the message ${JSON.stringify(f.frame.uuid)}, not the one under which Send now showed (${uuid})`);
  const ack = await inbox.waitFor((x) => x.t === "ack" && x.rid === f.rid, 10_000, iSince);
  const acted = ack?.f.ok ? String(ack.f.result?.acted ?? "") : null;
  if (!ack) fail(`${what}: the send_now got no ack`);
  else if (!ack.f.ok) fail(`${what}: the send_now was refused (${ack.f.error?.code})`);
  else if (acted !== want) fail(`${what}: the send_now acted ${JSON.stringify(acted)}, not ${JSON.stringify(want)}`);
  return acted;
}

/** The focus in the chat's box, the caret at its end; false when no box shows. */
const focusBox = (page: Page) => page.evaluate<boolean>(`(() => { const el = ${FIELD}; if (!el) return false; el.focus(); el.setSelectionRange(el.value.length, el.value.length); return true; })()`);

/** Type at the end of the chat's box (the focus in the field first), as a user does. */
async function typeInBox(page: Page, text: string): Promise<boolean> {
  if (!(await focusBox(page))) return false;
  await page.send("Input.insertText", { text });
  await sleep(150);
  return true;
}

async function sendNowFlow(t: Target, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow"): void => void failures.push({ code, text });
  const path = `/c/${EX.chat}`;
  let shot: string | undefined;
  try {
    await withPage(vp, "light", async (page, wire) => {
      const inbox = new Inbox(cdp, page);
      const shotOf = async (step: string, theme: Theme, look: P2LookId = "glass") => {
        const file = shotName(t.scene, "send-now", vp, theme, `${step}${look === "glass" ? "" : `-${look}`}`);
        await page.screenshot(file).catch(() => {});
        return file;
      };
      /** A shot in light, then one in dark, and back to light. */
      const shotBoth = async (step: string) => {
        await shotOf(step, "light");
        try {
          await wearLook(page, "glass", "dark");
          await shotOf(step, "dark");
        } finally {
          await wearLook(page, "glass", "light").catch(() => {});
        }
      };
      try {
        await page.navigate(t.base + path);
        await waitShown(page, ["chat", "composer"]);
        page.takeIssues();

        // ---- the story, and two messages queued behind it ----
        if (!(await sendFromBox(page, SEND_NOW.write))) return fail("the chat shows no message box with Send");
        const story = await untilNow(page, (s) => Object.values(s.texts).some((x) => x.startsWith("The send-now story")), 10_000);
        if (!story.ok) return fail("the long story did not start");
        const m0 = wire.mark();
        for (const text of [NOW_FIRST, NOW_LAST]) if (!(await sendFromBox(page, text))) return fail(`no Send to press for "${text}"`);
        const q = await untilNow(page, (s) => !!userOf(s, NOW_FIRST)?.queued && !!userOf(s, NOW_LAST)?.queued && !!userOf(s, NOW_LAST)?.now, 8000);
        details.queued = q.s.users;
        if (!q.ok) return fail(`the two messages sent during the story are not both queued with Send now under the last (${JSON.stringify(q.s.users.map((u) => [u.text, u.queued, !!u.now]))})`);
        const sends = acting(wire.framesSince(m0));
        if (sends.length !== 2 || sends.some((f) => f.t !== "send")) fail(`the two sends went as ${clipList(sends.map(frameText))}`);
        const last = userOf(q.s, NOW_LAST)!.id;
        const first = userOf(q.s, NOW_FIRST)!.id;

        // ---- the look, in light and dark, and at 1280x800 in light in each look; then under Reduce motion ----
        const looks: { look: P2LookId; theme: Theme }[] = vp.touch
          ? [{ look: "glass", theme: "light" }, { look: "glass", theme: "dark" }]
          : [...P2_LOOKS.map((look) => ({ look, theme: "light" as Theme })), { look: "glass", theme: "dark" }];
        const checked: string[] = [];
        try {
          for (const { look, theme } of looks) {
            await wearLook(page, look, theme);
            const where = `${theme}${look === "glass" ? "" : `, ${look}`}`;
            nowLookFindings(await nowLook(page), vp, SEND_NOW.write, [NOW_FIRST, NOW_LAST], NOW_LAST, where, fail);
            stateFindings(await page.probe(), vp, failures, `${where}, `);
            const file = await shotOf("queued", theme, look);
            if (look === "glass" && theme === "light") shot = file;
            checked.push(where);
          }
        } finally {
          await wearLook(page, "glass", "light").catch(() => {});
        }
        await page.evaluate(`(() => { document.documentElement.setAttribute("data-motion", "reduce"); return true; })()`);
        await page.evaluate(P2_DRAWN);
        nowLookFindings(await nowLook(page), vp, SEND_NOW.write, [NOW_FIRST, NOW_LAST], NOW_LAST, "under Reduce motion", fail);
        await shotOf("reduce", "light");
        await page.evaluate(`(() => { document.documentElement.removeAttribute("data-motion"); return true; })()`);
        details.looks = checked;

        // ---- the bubble's menu: Copy and Take back beside it (hover, or a tap on touch) ----
        const openMenu = async (text: string) => {
          const u = userOf(await nowLook(page), text);
          if (!u?.bubble) return null;
          if (vp.touch) await page.press(u.bubble.x, u.bubble.y);
          else await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: u.bubble.x, y: u.bubble.y });
          await sleep(400);
          return userOf(await nowLook(page), text);
        };
        const menu = await openMenu(NOW_LAST);
        details.menu = menu;
        if (!menu?.takeBack?.shown || menu.takeBack.opacity < 1 || !menu.copy?.shown || menu.copy.opacity < 1) fail(`${vp.touch ? "a tap on" : "hover over"} the last queued bubble does not show its menu, Copy and Take back (${JSON.stringify({ copy: menu?.copy, takeBack: menu?.takeBack })})`);
        if (!menu?.now) fail("with the bubble's menu open, Send now does not show");
        await shotBoth("menu");
        const m1 = wire.mark();
        const i1 = inbox.mark();
        const opened = await openMenu(NOW_FIRST);
        if (!opened?.takeBack?.shown) fail(`${vp.touch ? "a tap on" : "hover over"} the first queued bubble does not show Take back`);
        if (!(await pressOn(page, `[data-testid="item-${first}"] [data-testid="confirm-take-back"]`))) return fail("no Take back to press in the first queued message's menu");
        await waitSent(wire, m1);
        const back = acting(wire.framesSince(m1));
        if (back.length !== 1 || back[0]!.t !== "take_back" || back[0]!.frame.uuid !== first) fail(`Take back from the menu sent ${clipList(back.map(frameText)) || "nothing"}; expected one take_back for the first queued message`);
        else {
          const ack = await inbox.waitFor((x) => x.t === "ack" && x.rid === back[0]!.rid, 5000, i1);
          if (!ack?.f.ok || ack.f.result?.cancelled !== true) fail(`Take back got ${JSON.stringify(ack?.f ?? null)}, not cancelled`);
        }
        const gone = await untilNow(page, (s) => !userOf(s, NOW_FIRST) && (s.field ?? "").includes(NOW_FIRST), 5000);
        if (!gone.ok) fail(`after Take back the first message ${userOf(gone.s, NOW_FIRST) ? "still shows" : "went"} and the box holds ${JSON.stringify(gone.s.field)}, not its text`);
        if (!userOf(gone.s, NOW_LAST)?.now) fail("after Take back of the first message, Send now does not show under the last one");
        const left = await emptyChatBox(page);
        if (left) fail(`the box could not be emptied after Take back (${JSON.stringify(left)})`);
        if (!vp.touch) await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: 5, y: 5 });

        // ---- Send now while Claude only writes: one send_now, an interrupt, and the message runs next ----
        const m2 = wire.mark();
        const i2 = inbox.mark();
        const pressedAt = Date.now();
        if (!(await pressSendNow(page, !vp.touch))) return fail("no Send now to press");
        await oneSendNow(wire, inbox, m2, i2, last, "interrupt", `Send now ${vp.touch ? "(a tap)" : "(a double click)"} while Claude writes`, fail);
        const away = await nowLook(page);
        if (away.nows) fail("right after the press Send now still shows");
        const ran = await untilNow(page, (s) => s.interrupted > 0 && userOf(s, NOW_LAST)?.queued === false && s.working === 0, 15_000);
        details.afterInterrupt = { interrupted: ran.s.interrupted, users: ran.s.users.map((u) => [u.text, u.queued]) };
        if (!ran.ok) fail(`after Send now the story ${ran.s.interrupted ? "ended Interrupted" : "shows no Interrupted"}, and the message is ${userOf(ran.s, NOW_LAST)?.queued ? "still queued" : "drawn as sent"}${ran.s.working ? " while a turn still works" : ""}`);
        if (ran.s.nows) fail("after the message ran, Send now still shows");
        if (turnsOf(t, last) !== 1) fail(`Claude Code started ${turnsOf(t, last)} turns for the message, not one`);
        if (controls(t, pressedAt, "interrupt") !== 1) fail(`Claude Code got ${controls(t, pressedAt, "interrupt")} interrupt requests after the press, not one`);
        await shotBoth("sent");

        // ---- Send now during a running Bash call: it moves to the background, and Claude reads the message ----
        if (!(await sendFromBox(page, SEND_NOW.bash))) return fail("no Send for the long command");
        const call = await untilNow(page, (s) => Object.values(s.texts).some((x) => x.startsWith(SEND_NOW_REPLIES.bashStart)), 10_000);
        if (!call.ok) return fail("the long command's turn did not start");
        await sleep(1200);
        if (!(await sendFromBox(page, NOW_READ))) return fail("no Send for the message behind the long command");
        const q2 = await untilNow(page, (s) => !!userOf(s, NOW_READ)?.queued && !!userOf(s, NOW_READ)?.now, 6000);
        if (!q2.ok) return fail("the message sent during the long command is not queued with Send now under it");
        nowLookFindings(q2.s, vp, SEND_NOW.bash, [NOW_READ], NOW_READ, "during the long command", fail);
        const read = userOf(q2.s, NOW_READ)!.id;
        const m3 = wire.mark();
        const i3 = inbox.mark();
        const pressed2 = Date.now();
        if (!(await pressSendNow(page, false))) return fail("no Send now to press during the long command");
        await oneSendNow(wire, inbox, m3, i3, read, "background", "Send now during the long command", fail);
        const took = await untilNow(page, (s) => userOf(s, NOW_READ)?.queued === false && Object.values(s.texts).includes(SEND_NOW_REPLIES.bashRead), 12_000);
        details.afterBackground = { users: took.s.users.map((u) => [u.text, u.queued]), texts: Object.values(took.s.texts) };
        if (!took.ok) fail(`after Send now during the long command the message is ${userOf(took.s, NOW_READ)?.queued ? "still queued" : "drawn as sent"} and Claude's reply that read it ${Object.values(took.s.texts).includes(SEND_NOW_REPLIES.bashRead) ? "came" : "did not come"}`);
        const replyRow = Object.entries(took.s.texts).find(([, x]) => x === SEND_NOW_REPLIES.bashRead)?.[0];
        if (replyRow && took.s.rows.indexOf(read) > took.s.rows.indexOf(replyRow)) fail("the message that Claude read in the turn is drawn below the reply that read it");
        if (took.s.nows) fail("after Claude read the message, Send now still shows");
        if (controls(t, pressed2, "background_tasks") !== 1) fail(`Claude Code got ${controls(t, pressed2, "background_tasks")} background_tasks requests after the press, not one`);
        if (!t.booted!.trace().some((l) => l.t === "fold" && l.uuid === read)) fail("Claude Code did not take the message into the running turn");
        if (turnsOf(t, read) !== 0) fail("Claude Code ran the message as a turn of its own, not inside the running one");
        await shotBoth("background");
        stateFindings(await page.probe(), vp, failures, "at the end, ");
        issueFindings(page.takeIssues(), failures);
      } finally {
        inbox.dispose();
      }
    });
  } catch (e) {
    fail(`the check could not run: ${(e as Error).message}`, "run");
  }
  const note = "the queued bubbles plain with one Send now under the last (its look in each theme and look), Take back from the menu, Send now while Claude writes (one send_now, the turn stopped, the message next) and during a Bash call (moved to the background, read in the same turn)";
  return finish({ kind: "flow", name: "send-now", route: "message", scene: t.scene, size: sizeTag(vp), theme: "light", path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

async function sendNowKeyFlow(t: Target, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow"): void => void failures.push({ code, text });
  const path = `/c/${EX.chat}`;
  let shot: string | undefined;
  try {
    await withPage(vp, "dark", async (page, wire) => {
      const inbox = new Inbox(cdp, page);
      const ctrlEnter = () => pressKey(page, "Enter", { ctrl: true });
      /** One key press in the box and what it sent (its acting frames). */
      const keyAndSee = async (press: () => Promise<void>) => {
        const m = wire.mark();
        const i = inbox.mark();
        await press();
        await waitSent(wire, m);
        return { frames: acting(wire.framesSince(m)), i };
      };
      /** The long story starts (typed and sent with Enter); false, with a finding, when it does not. */
      const story = async (when: string): Promise<boolean> => {
        if (!(await typeInBox(page, SEND_NOW.write))) {
          fail(`${when}: no message box`);
          return false;
        }
        await page.key("Enter");
        const s = await untilNow(page, (x) => x.working > 0 && Object.values(x.texts).some((y) => y.startsWith("The send-now story")), 10_000);
        if (!s.ok) fail(`${when}: the long story did not start`);
        return s.ok;
      };
      /** No turn works and nothing waits any more. */
      const idle = async (when: string) => {
        const r = await untilNow(page, (s) => s.working === 0 && !s.users.some((u) => u.queued), 15_000);
        if (!r.ok) fail(`${when}: the chat did not settle (${r.s.working} working marks; queued: ${clipList(r.s.users.filter((u) => u.queued).map((u) => u.text)) || "none"})`);
      };
      try {
        // ---- Settings' shortcut list ----
        const m0 = wire.mark();
        await page.navigate(`${t.base}/settings/general/shortcuts`);
        await waitShown(page, ["settings"], 6000);
        const rows = JSON.parse(await page.evaluate<string>(`JSON.stringify([...document.querySelectorAll(".set-keys .set-key")].map((r) => ({ words: (r.querySelector("dt")?.firstChild?.textContent || "").trim(), keys: [...r.querySelectorAll(".set-combo")].map((c) => [...c.querySelectorAll("kbd")].map((k) => k.textContent)) })))`)) as { words: string; keys: string[][] }[];
        details.shortcuts = rows;
        const row = rows.find((r) => r.words === "Send now");
        if (!row) fail(`Settings' shortcut list has no Send now row (${clipList(rows.map((r) => r.words))})`);
        else if (JSON.stringify(row.keys) !== JSON.stringify([["Ctrl", "Enter"]])) fail(`Settings names Send now's key ${JSON.stringify(row.keys)}, not Ctrl Enter (this host is not macOS)`);
        // The last row but one: U3's "Jump to the previous or next turn" ({ and }) follows it (DESIGN-U3 7; the
        // turn-rail flow checks that row).
        if (rows.at(-2)?.words !== "Send now" || rows.at(-1)?.words !== "Jump to the previous or next turn") fail(`Send now is not the last row but one of the shortcut list, before "Jump to the previous or next turn" (6.11; ${clipList(rows.map((r) => r.words))})`);
        quietFindings(wire, m0, null, failures, "Settings' shortcut list, ");

        await page.navigate(t.base + path);
        await waitShown(page, ["chat", "composer"]);
        page.takeIssues();

        // ---- (a) no turn running: Ctrl+Enter sends, and nothing more ----
        if (!(await typeInBox(page, KEY_PLAIN))) return fail("the chat shows no message box");
        const a = await keyAndSee(ctrlEnter);
        if (a.frames.length !== 1 || a.frames[0]!.t !== "send" || a.frames[0]!.frame.text !== KEY_PLAIN) fail(`Ctrl+Enter with no turn running sent ${clipList(a.frames.map(frameText)) || "nothing"}; expected one send`);
        await idle("after the plain Ctrl+Enter");

        // ---- (b) the story; Meta+Enter (not the key off macOS) only queues; (c) Ctrl+Enter in the empty box ----
        if (!(await story("the first story"))) return;
        if (!(await typeInBox(page, KEY_QUEUED))) return fail("no message box during the story");
        const b = await keyAndSee(() => pressKey(page, "Enter", { meta: true }));
        if (b.frames.length !== 1 || b.frames[0]!.t !== "send") fail(`Meta+Enter during the story sent ${clipList(b.frames.map(frameText)) || "nothing"}; expected one send and no send_now (Cmd+Enter is the key on macOS only)`);
        const qb = await untilNow(page, (s) => !!userOf(s, KEY_QUEUED)?.queued && !!userOf(s, KEY_QUEUED)?.now, 6000);
        if (!qb.ok) return fail("the message sent with Meta+Enter during the story is not queued with Send now under it");
        const queuedId = userOf(qb.s, KEY_QUEUED)!.id;
        if (qb.s.field !== "") fail(`after the send the box holds ${JSON.stringify(qb.s.field)}`);
        const c0 = Date.now();
        const c = await keyAndSee(async () => {
          await focusBox(page);
          await ctrlEnter();
        });
        const cNow = c.frames.filter((f) => f.t === "send_now");
        if (c.frames.length !== 1 || cNow.length !== 1) fail(`Ctrl+Enter in the empty box sent ${clipList(c.frames.map(frameText)) || "nothing"}; expected Send now alone (one send_now)`);
        else {
          if (cNow[0]!.frame.uuid !== queuedId) fail(`Ctrl+Enter's send_now names ${JSON.stringify(cNow[0]!.frame.uuid)}, not the queued message`);
          const ack = await inbox.waitFor((x) => x.t === "ack" && x.rid === cNow[0]!.rid, 10_000, c.i);
          if (ack?.f.result?.acted !== "interrupt") fail(`Ctrl+Enter's send_now got ${JSON.stringify(ack?.f ?? null)}, not acted "interrupt"`);
        }
        await idle("after Ctrl+Enter in the empty box");
        if (turnsOf(t, queuedId) !== 1) fail(`Claude Code ran the queued message ${turnsOf(t, queuedId)} times, not once`);
        if (controls(t, c0, "interrupt") !== 1) fail(`Ctrl+Enter in the empty box gave Claude Code ${controls(t, c0, "interrupt")} interrupts, not one`);

        // ---- (d) a queued message, then a draft with Ctrl+Enter: the send, then Send now for the draft's message ----
        if (!(await story("the second story"))) return;
        if (!(await typeInBox(page, KEY_BEHIND))) return fail("no message box during the second story");
        await page.key("Enter");
        const qd = await untilNow(page, (s) => !!userOf(s, KEY_BEHIND)?.queued && !!userOf(s, KEY_BEHIND)?.now, 6000);
        if (!qd.ok) return fail("the message sent with Enter during the second story is not queued with Send now under it");
        const behindId = userOf(qd.s, KEY_BEHIND)!.id;
        if (!(await typeInBox(page, KEY_DRAFT))) return fail("no message box for the draft");
        await page.evaluate(NOW_SAMPLER);
        const d0 = Date.now();
        const d = await keyAndSee(ctrlEnter);
        details.ctrlEnter = d.frames.map((f) => f.frame);
        const send = d.frames.find((f) => f.t === "send");
        const dNow = d.frames.filter((f) => f.t === "send_now");
        if (d.frames.length !== 2 || !send || dNow.length !== 1 || d.frames[0] !== send) fail(`Ctrl+Enter with a draft during the story sent ${clipList(d.frames.map(frameText)) || "nothing"}; expected one send, then one send_now`);
        if (send && send.frame.text !== KEY_DRAFT) fail(`Ctrl+Enter sent ${JSON.stringify(send.frame.text)}, not the draft`);
        if (send && dNow[0] && dNow[0].frame.uuid !== send.frame.uuid) fail("Ctrl+Enter's send_now does not name the draft's own message");
        if (dNow[0]) {
          const ack = await inbox.waitFor((x) => x.t === "ack" && x.rid === dNow[0]!.rid, 10_000, d.i);
          if (ack?.f.result?.acted !== "interrupt") fail(`Ctrl+Enter's send_now got ${JSON.stringify(ack?.f ?? null)}, not acted "interrupt"`);
        }
        const after = await nowLook(page);
        if (after.field !== "") fail(`after Ctrl+Enter the box holds ${JSON.stringify(after.field)}`);
        shot = shotName(t.scene, "send-now-key", vp, "dark", "sent");
        await page.screenshot(shot).catch(() => {});
        await idle("after Ctrl+Enter with a draft");
        const seen = (JSON.parse(await page.evaluate<string>(NOW_SEEN)) as { id: string | null; at: number }[]).filter((x) => x.at > d0 + 50);
        const draftId = send ? String(send.frame.uuid) : null;
        if (seen.some((x) => x.id === draftId)) fail("Send now showed under the draft's message after Ctrl+Enter");
        if (seen.some((x) => x.id === behindId && x.at > d0 + 400)) fail("Send now came back under the queued message after Ctrl+Enter");
        const starts = t.booted!.trace().filter((l) => l.t === "turn_start" && (l.uuid === behindId || l.uuid === draftId)).map((l) => l.uuid);
        if (JSON.stringify(starts) !== JSON.stringify([behindId, draftId])) fail(`after Ctrl+Enter Claude Code ran ${JSON.stringify(starts)}, not the queued message and then the draft's, once each`);
        if (controls(t, d0, "interrupt") !== 1) fail(`Ctrl+Enter with a draft gave Claude Code ${controls(t, d0, "interrupt")} interrupts, not one`);

        // ---- (e) in `!` mode Ctrl+Enter only queues the command ----
        if (!(await story("the third story"))) return;
        await typeInBox(page, "!");
        await typeInBox(page, "echo key-check");
        const e = await keyAndSee(ctrlEnter);
        if (e.frames.length !== 1 || e.frames[0]!.t !== "bash" || e.frames[0]!.frame.input !== "echo key-check") fail(`Ctrl+Enter in ! mode during the story sent ${clipList(e.frames.map(frameText)) || "nothing"}; expected one bash frame and no send_now`);
        const stop = await keyAndSee(() => page.key("Escape"));
        if (!stop.frames.some((f) => f.t === "interrupt")) fail("Esc did not stop the third story");
        await untilNow(page, (s) => s.working === 0, 15_000);
        stateFindings(await page.probe(), vp, failures, "at the end, ");
        issueFindings(page.takeIssues(), failures);
        const leftover = await emptyChatBox(page);
        if (leftover) warnings.push({ code: "flow", text: `the box could not be emptied at the end (${JSON.stringify(leftover)})` });
      } finally {
        inbox.dispose();
      }
    });
  } catch (e) {
    fail(`the check could not run: ${(e as Error).message}`, "run");
  }
  const note = "Ctrl+Enter: Settings names it Send now; with no turn it only sends; in the empty box during a turn it is Send now alone; with a draft one send then one send_now for it, queued behind the others; in ! mode it only queues the command; Meta+Enter is not it off macOS";
  return finish({ kind: "flow", name: "send-now-key", route: "chat", scene: t.scene, size: sizeTag(vp), theme: "dark", path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

// ---------------------------------------------------------------------------------------------------------------
// Row 108: the self update. Each flow boots a scratch checkout of its own (test/click/scratch.ts: a clone of this
// checkout's HEAD with its working tree on top, whose origin is another clone with one new commit), with that
// checkout's own bin/kitespan, so that an Update runs only there and never in this checkout. --base runs none of them.
//
// - update-setting (1280x800 dark and light, 390x844 light): Check for updates with its three choices; Daily by
//   default; a pick is one POST /api/settings; a second page and a reload show it; the setting's own path opened
//   directly marks its row and shows the link's value as a draft (Not saved, Save), and nothing goes out before Save;
//   the setting goes back to Daily at the end.
// - update-check-now (1280x800): with origin as the checkout, About says "Checked just now." and has no Update; a new
//   commit on origin, then Check now: one POST /api/update/check, Update available with Update, and the update notice
//   with its Update action on a second page, whose line ("Update available." with Update) is in the docked sidebar's
//   foot there, and above the message box of a chat on a phone page (390x844); both lines still show past the 8 s of
//   a plain notice; in Manually too, Check now is there.
// - update-run (1280x800): Update opens its confirm and sends nothing; its Update is one POST /api/update (202); the
//   step line shows on About and on a second page (Settings > General) while the steps run; then Restart to apply; the
//   running server still serves its own build (/assets/build.json) while the disk holds the new one; with a turn
//   running in the example chat, the restart dialog's Restart now restarts it, and the successor serves the new HEAD,
//   whose page names other scripts.
// - update-refused (1280x800): with a local change in the checkout, the confirm's Update gets its one line, "This
//   checkout has local changes.", and nothing changes in the checkout.

const UPDATE_FLOWS = ["update-setting", "update-check-now", "update-run", "update-refused", "update-install", "update-brew"] as const;
type UpdateFlow = (typeof UPDATE_FLOWS)[number];

/** The scratch checkout of each target that an update flow or an update action check booted. */
const scratchOf = new Map<Target, ScratchApp>();
process.on("exit", () => {
  for (const s of scratchOf.values()) s.remove();
});

/** A target on a scratch checkout of its own: its bin/kitespan, its build folder, no system or global git config. */
async function openScratchTarget(scene: SceneName, o: { next?: "page" | "none"; localChange?: boolean } = {}): Promise<Target> {
  if (BASE) throw new Error("an update check runs only on a scratch checkout, never on --base");
  const s = scratchApp(o);
  try {
    const b = await boot({ scene, port: PORT, dist: s.dist, root: s.app, keep: KEEP, env: { ...SERVER_ENV, ...s.serverEnv } });
    live.add(b);
    const t: Target = { base: b.base, scene, booted: b };
    scratchOf.set(t, s);
    return t;
  } catch (e) {
    s.remove();
    throw e;
  }
}

/** closeTarget, then the target's scratch checkout goes. */
async function closeScratchTarget(t: Target, problems: string[]): Promise<void> {
  try {
    await closeTarget(t, problems);
  } finally {
    scratchOf.get(t)?.remove();
    scratchOf.delete(t);
  }
}

/** A read of the target's API from here (Bun's fetch to 127.0.0.1, with the Host and Origin a page would send). */
async function apiRead<T>(t: Target, path: string): Promise<T> {
  const r = await fetch(t.base + path, { headers: { origin: t.base }, signal: AbortSignal.timeout(10_000) });
  return (await r.json()) as T;
}

/** The commit of the build that the target serves from memory (/assets/build.json), or null. */
async function servedBuild(t: Target): Promise<string | null> {
  try {
    const head = (await apiRead<{ head?: unknown }>(t, "/assets/build.json")).head;
    return typeof head === "string" ? head : null;
  } catch {
    return null;
  }
}

/** The page's module scripts as GET / names them (their names carry the build's hashes). */
async function pageScripts(t: Target): Promise<string[]> {
  const html = await (await fetch(t.base + "/", { signal: AbortSignal.timeout(10_000) })).text();
  return [...html.matchAll(/<script[^>]*type="module"[^>]*src="([^"]+)"/g)].map((m) => m[1]!).sort();
}

/** In-page: Settings > About's update rows (row 108) as the user sees them. */
const UPDATE_LOOK = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const one = (id) => [...document.querySelectorAll('[data-testid="' + id + '"]')].find(shown) || null;
  const t = (el) => (el ? el.textContent.replace(/\\s+/g, " ").trim() : null);
  const row = one("setting-check-for-updates");
  const radios = row ? [...row.querySelectorAll('[role="radio"]')].filter(shown) : [];
  const menu = row ? row.querySelector(".set-menu-value") : null;
  return {
    path: location.pathname + location.search,
    choices: radios.map((r) => t(r)),
    checked: radios.length ? t(radios.find((r) => r.getAttribute("aria-checked") === "true")) : t(menu),
    focused: !!row && row.getAttribute("data-focused") === "true",
    unsaved: !!(row && [...row.querySelectorAll(".set-unsaved")].some(shown)),
    save: !!(row && [...row.querySelectorAll('[data-testid="confirm-save"]')].some(shown)),
    update: t(one("setting-update")),
    updateButton: !!one("update-open"),
    step: t(one("setting-update-step")),
    apply: t(one("setting-restart-to-apply")),
    checkNow: t(one("setting-check-now")),
    checkNowButton: !!one("check-now"),
    dialog: !!one("dialog-update"),
    dialogLine: t(one("dialog-notice")),
    notice: t([...document.querySelectorAll(".set-notice")].find(shown) || null),
    updateLine: t(one("update-line")?.querySelector(".drain-text") ?? null),
    updateLines: [...document.querySelectorAll('[data-testid="update-line"]')].filter(shown).length,
    updateLineButton: !!one("update-line")?.querySelector('[data-testid="update-open"]'),
    scrollWidth: document.documentElement.scrollWidth,
    clientWidth: document.documentElement.clientWidth,
  };
})())`;
interface UpdateLook {
  path: string;
  choices: (string | null)[];
  checked: string | null;
  focused: boolean;
  unsaved: boolean;
  save: boolean;
  update: string | null;
  updateButton: boolean;
  step: string | null;
  apply: string | null;
  checkNow: string | null;
  checkNowButton: boolean;
  dialog: boolean;
  dialogLine: string | null;
  notice: string | null;
  /** The update notice's line on this screen (update/UpdateLine.tsx), how many show, and whether it has Update. */
  updateLine: string | null;
  updateLines: number;
  updateLineButton: boolean;
  scrollWidth: number;
  clientWidth: number;
}
const lookUpdate = async (page: Page): Promise<UpdateLook> => JSON.parse(await page.evaluate<string>(UPDATE_LOOK)) as UpdateLook;
async function untilUpdate(page: Page, ok: (s: UpdateLook) => boolean, ms: number): Promise<{ s: UpdateLook; ok: boolean }> {
  const end = Date.now() + ms;
  for (;;) {
    const s = await lookUpdate(page).catch(() => null);
    if (s && ok(s)) return { s, ok: true };
    if (Date.now() > end) return { s: s ?? (await lookUpdate(page)), ok: false };
    await sleep(100);
  }
}

/** In-page: every distinct update line that shows (About's step row, a section's notice, the list's notice); window.__uiUpdate. */
const UPDATE_SAMPLER = `(() => {
  const seen = (window.__uiUpdate = []);
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const t = (el) => el.textContent.replace(/\\s+/g, " ").trim();
  clearInterval(window.__uiUpdateTimer);
  window.__uiUpdateTimer = setInterval(() => {
    for (const el of document.querySelectorAll('[data-testid="setting-update-step"], [data-testid="setting-update"], [data-testid="setting-restart-to-apply"], .set-notice, .notice')) {
      if (!shown(el)) continue;
      const x = t(el);
      if (x && !seen.includes(x)) seen.push(x);
    }
  }, 20);
  return true;
})()`;
const UPDATE_SEEN = `JSON.stringify(window.__uiUpdate || [])`;

/** Pick a choice of Check for updates as a user does: its segment, or on a narrow section its menu's row. */
async function pickCheck(page: Page, label: string): Promise<boolean> {
  const seg = await page.evaluate<boolean>(`(() => {
    const row = document.querySelector('[data-testid="setting-check-for-updates"]');
    const r = row && [...row.querySelectorAll('[role="radio"]')].find((x) => x.textContent.trim() === ${JSON.stringify(label)});
    if (!r) return false;
    r.setAttribute("data-ui-pick", "1");
    return true;
  })()`);
  if (seg) {
    const ok = await pressOn(page, '[data-ui-pick="1"]');
    await page.evaluate(`document.querySelector('[data-ui-pick="1"]')?.removeAttribute("data-ui-pick")`);
    return ok;
  }
  if (!(await pressOn(page, '[data-testid="setting-check-for-updates-button"]'))) return false;
  await sleep(300);
  const marked = await page.evaluate<boolean>(`(() => {
    const r = [...document.querySelectorAll('[role="menuitemradio"]')].find((x) => x.textContent.trim() === ${JSON.stringify(label)});
    if (!r) return false;
    r.setAttribute("data-ui-pick", "1");
    return true;
  })()`);
  if (!marked) return false;
  const ok = await pressOn(page, '[data-ui-pick="1"]');
  return ok;
}

/** The bodies of the page's POST /api/settings since `mark` (the Inbox's record of each mutating request). */
const settingsPosts = (inbox: Inbox, after: number) => inbox.posts.filter((p) => p.at > after && p.path === "/api/settings").map((p) => p.body);

async function updateSettingFlow(t: Target, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const about = "/settings/about";
  const own = "/settings/about/check-for-updates?value=manual";
  let shot: string | undefined;
  const pages: { page: Page; wire: Wire; inbox: Inbox }[] = [];
  const open = async () => {
    const page = await Page.open(cdp, vp, theme);
    const p = { page, wire: new Wire(cdp, page), inbox: new Inbox(cdp, page) };
    pages.push(p);
    return p;
  };
  const body = async (): Promise<void> => {
    const A = await open();
    await A.page.navigate(t.base + about);
    await waitShown(A.page, ["settings", "settings-about", "setting-check-for-updates", "setting-check-now"], 8000);
    const opened = A.wire.mark();
    const s0 = (await untilUpdate(A.page, (s) => s.checked !== null, 4000)).s;
    details.first = s0;
    if (s0.choices.length && s0.choices.join("|") !== "Manually|Daily|Every 3 hours") fail(`the choices are ${JSON.stringify(s0.choices)}, not Manually, Daily and Every 3 hours`);
    if (s0.checked !== "Daily") fail(`Check for updates shows ${JSON.stringify(s0.checked)} before any pick, not Daily (the default)`);
    if (!s0.checkNowButton) fail("About shows no Check now");
    if (s0.scrollWidth > s0.clientWidth) fail(`About scrolls sideways (${s0.scrollWidth} > ${s0.clientWidth})`, "overflow");
    stateFindings(await A.page.probe(), vp, failures);
    quietFindings(A.wire, opened, await recorder(A.page), failures, "About, opened: ");
    shot = shotName(t.scene, "update-setting", vp, theme, "about");
    await A.page.screenshot(shot).catch(() => {});

    // A pick: one POST /api/settings with the one key.
    const pickAt = Date.now();
    const m1 = A.wire.mark();
    if (!(await pickCheck(A.page, "Every 3 hours"))) return void fail("no Every 3 hours to pick");
    await waitSent(A.wire, m1);
    await sleep(500);
    const sent1 = A.wire.httpSince(m1);
    const bodies1 = settingsPosts(A.inbox, pickAt - 1);
    details.pick = { http: sent1.map(httpText), bodies: bodies1 };
    if (sent1.length !== 1 || sent1[0]!.method !== "POST" || sent1[0]!.path !== "/api/settings" || (sent1[0]!.status ?? 0) >= 400) fail(`the pick sent ${clipList(sent1.map(httpText)) || "nothing"}; expected one POST /api/settings`);
    if (bodies1.length !== 1 || JSON.stringify(JSON.parse(bodies1[0] ?? "null")) !== JSON.stringify({ "updates.check": "3h" })) fail(`the pick's body is ${JSON.stringify(bodies1)}, not {"updates.check":"3h"}`);
    if ((await apiRead<{ settings: Record<string, unknown> }>(t, "/api/settings")).settings["updates.check"] !== "3h") fail("the server's settings do not say Every 3 hours after the pick");

    // A second page, and a reload.
    const B = await open();
    await B.page.navigate(t.base + about);
    await waitShown(B.page, ["settings-about", "setting-check-for-updates"], 8000);
    const sb = (await untilUpdate(B.page, (s) => s.checked === "Every 3 hours", 4000)).s;
    details.second = sb.checked;
    if (sb.checked !== "Every 3 hours") fail(`a second page shows ${JSON.stringify(sb.checked)}, not Every 3 hours`);
    await A.page.reload();
    await waitShown(A.page, ["settings-about", "setting-check-for-updates"], 8000);
    const sr = (await untilUpdate(A.page, (s) => s.checked === "Every 3 hours", 4000)).s;
    details.reloaded = sr.checked;
    if (sr.checked !== "Every 3 hours") fail(`after a reload About shows ${JSON.stringify(sr.checked)}, not Every 3 hours`);

    // The setting's own path, opened directly: the row marked, the link's value a draft; Save saves it.
    const m2 = B.wire.mark();
    await B.page.navigate(t.base + own);
    await waitShown(B.page, ["settings-about", "setting-check-for-updates", "confirm-save"], 8000);
    await sleep(400);
    const so = await lookUpdate(B.page);
    details.own = so;
    if (!so.focused) fail(`${own} does not mark the Check for updates row`);
    if (so.checked !== "Manually") fail(`${own} shows ${JSON.stringify(so.checked)}, not the link's Manually`);
    if (!so.unsaved || !so.save) fail(`${own} shows no Not saved with Save`);
    quietFindings(B.wire, m2, await recorder(B.page), failures, `${own}: `);
    await B.page.screenshot(shotName(t.scene, "update-setting", vp, theme, "own-path")).catch(() => {});
    if ((await apiRead<{ settings: Record<string, unknown> }>(t, "/api/settings")).settings["updates.check"] !== "3h") fail(`opening ${own} changed the setting`);
    const saveAt = Date.now();
    const m3 = B.wire.mark();
    if (!(await pressOn(B.page, '[data-testid="setting-check-for-updates"] [data-testid="confirm-save"]'))) fail("no Save to press");
    await waitSent(B.wire, m3);
    await sleep(500);
    const sent3 = B.wire.httpSince(m3);
    const bodies3 = settingsPosts(B.inbox, saveAt - 1);
    details.save = { http: sent3.map(httpText), bodies: bodies3 };
    if (sent3.length !== 1 || sent3[0]!.path !== "/api/settings") fail(`Save sent ${clipList(sent3.map(httpText)) || "nothing"}; expected one POST /api/settings`);
    if (JSON.stringify(JSON.parse(bodies3[0] ?? "null")) !== JSON.stringify({ "updates.check": "manual" })) fail(`Save's body is ${JSON.stringify(bodies3)}, not {"updates.check":"manual"}`);
    await B.page.navigate(t.base + about);
    await waitShown(B.page, ["settings-about", "setting-check-for-updates"], 8000);
    const sm = (await untilUpdate(B.page, (s) => s.checked === "Manually", 4000)).s;
    if (sm.checked !== "Manually") fail(`after Save About shows ${JSON.stringify(sm.checked)}, not Manually`);
    if (!sm.checkNowButton) fail("in Manually, About shows no Check now");

    // Back to Daily, the default, for what comes after.
    const m4 = B.wire.mark();
    if (!(await pickCheck(B.page, "Daily"))) fail("no Daily to pick");
    await waitSent(B.wire, m4);
    await sleep(400);
    if ((await apiRead<{ settings: Record<string, unknown> }>(t, "/api/settings")).settings["updates.check"] !== "daily") fail("the setting did not go back to Daily");
    for (const p of pages) issueFindings(p.page.takeIssues(), failures);
  };
  try {
    await body();
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  } finally {
    for (const p of pages) {
      p.inbox.dispose();
      p.wire.dispose();
      await p.page.close();
    }
  }
  const note = `${vp.width}x${vp.height}${vp.touch ? " touch" : ""} ${theme}: Check for updates' three choices, Daily first; a pick is one POST /api/settings; a second page and a reload show it; ${own} marks the row with a draft until Save; back to Daily`;
  return finish({ kind: "flow", name: "update-setting", route: "setting", scene: t.scene, size: sizeTag(vp), theme, path: `${about} and ${own}`, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

async function updateCheckNowFlow(t: Target, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const about = "/settings/about";
  const s = scratchOf.get(t);
  let shot: string | undefined;
  const pages: { page: Page; wire: Wire; inbox: Inbox }[] = [];
  const open = async () => {
    const page = await Page.open(cdp, vp, "dark");
    const p = { page, wire: new Wire(cdp, page), inbox: new Inbox(cdp, page) };
    pages.push(p);
    return p;
  };
  const body = async (): Promise<void> => {
    if (!s) return void fail("the flow has no scratch checkout", "run");
    const A = await open();
    await A.page.navigate(t.base + about);
    await waitShown(A.page, ["settings-about", "setting-check-now"], 8000);
    // The check at start (Daily, never checked) found origin as the checkout.
    const s0 = (await untilUpdate(A.page, (x) => !!x.checkNow && x.checkNow.startsWith("Checked"), 15_000)).s;
    details.before = s0;
    if (!s0.checkNow?.startsWith("Checked just now.")) fail(`About's Check now row says ${JSON.stringify(s0.checkNow)}, not "Checked just now." after the check at start`);
    if (s0.update || s0.updateButton) fail(`with origin as the checkout, About shows ${JSON.stringify(s0.update)}${s0.updateButton ? " with Update" : ""}`);
    const B = await open();
    await B.page.navigate(t.base + "/settings/general");
    await waitShown(B.page, ["settings-general"], 8000);
    const bMark = B.inbox.mark();
    // A phone on a chat: no docked sidebar, so the line goes above the message box.
    const phoneVp = VIEWPORTS.find((v) => v.name === "phone")!;
    const C = { page: await Page.open(cdp, phoneVp, "dark") } as { page: Page; wire: Wire; inbox: Inbox };
    C.wire = new Wire(cdp, C.page);
    C.inbox = new Inbox(cdp, C.page);
    pages.push(C);
    await C.page.navigate(`${t.base}/c/${EX.chat}`);
    await waitShown(C.page, ["chat", "composer"], 8000);
    const c0 = await lookUpdate(C.page);
    if (c0.updateLines) fail(`with origin as the checkout, the phone's chat shows the update line ${JSON.stringify(c0.updateLine)}`);

    // One new commit on origin, made there (nothing is pushed); then Check now.
    const g = (args: string[]) => Bun.spawnSync(["git", "-c", "core.hooksPath=/dev/null", "-c", "user.name=kitespan click-through", "-c", "user.email=kitespan-click@example.invalid", ...args], { cwd: s.origin, env: { PATH: "/usr/bin:/bin", HOME: s.tmp, GIT_CONFIG_GLOBAL: "/dev/null", GIT_CONFIG_NOSYSTEM: "1" }, stdout: "pipe", stderr: "pipe" });
    if (g(["commit", "--quiet", "--allow-empty", "--no-verify", "-m", "A new commit for Check now"]).exitCode !== 0) return void fail("could not make origin's new commit", "run");
    const m = A.wire.mark();
    if (!(await pressOn(A.page, '[data-testid="check-now"]'))) return void fail("no Check now to press");
    await waitSent(A.wire, m);
    const sent = A.wire.httpSince(m);
    details.sent = sent.map(httpText);
    if (sent.length !== 1 || sent[0]!.method !== "POST" || sent[0]!.path !== "/api/update/check") fail(`Check now sent ${clipList(sent.map(httpText)) || "nothing"}; expected one POST /api/update/check`);
    const s1 = (await untilUpdate(A.page, (x) => x.updateButton, 15_000)).s;
    details.after = s1;
    if (s1.update !== "Update available Update" && !(s1.update ?? "").startsWith("Update available")) fail(`after Check now About shows ${JSON.stringify(s1.update)}, not Update available`);
    if (!s1.updateButton) fail("after Check now About shows no Update");
    if (!s1.checkNow?.startsWith("Checked just now.")) fail(`after Check now its row says ${JSON.stringify(s1.checkNow)}`);
    shot = shotName(t.scene, "update-check-now", vp, "dark", "available");
    await A.page.screenshot(shot).catch(() => {});
    // The second page: the update notice with its Update action, and its line.
    const n = await B.inbox.waitFor((f) => f.t === "notice" && f.id === "update", 5000, bMark);
    details.notice = n?.f ?? null;
    if (!n) fail("the second page got no update notice");
    else if (n.f.text !== "Update available." || JSON.stringify(n.f.actions) !== JSON.stringify(["update"])) fail(`the second page's update notice is ${JSON.stringify(n.f)}, not "Update available." with the Update action`);
    const shownLine = (x: UpdateLook) => x.updateLine === "Update available." && x.updateLineButton && x.updateLines === 1;
    const lineB = (await untilUpdate(B.page, shownLine, 5000)).s;
    // Origin's standing line shows only in the chat list's foot (principle 0): never above a phone chat's message box.
    await sleep(1_000);
    const lineC = await lookUpdate(C.page);
    details.lines = { second: lineB, phone: lineC };
    if (!shownLine(lineB)) fail(`the second page (the sidebar's foot) shows ${lineB.updateLines} update line(s), ${JSON.stringify(lineB.updateLine)}${lineB.updateLineButton ? " with Update" : " with no Update"}, not one "Update available." with Update`);
    if (lineC.updateLines) fail(`the phone's chat shows the update line ${JSON.stringify(lineC.updateLine)} above its message box; Update available belongs in the chat list's foot`);
    await C.page.screenshot(shotName(t.scene, "update-check-now", phoneVp, "dark", "phone-chat")).catch(() => {});
    // No timer takes it away (a plain notice goes after 8 s).
    await sleep(9_000);
    const later = await lookUpdate(B.page);
    if (!shownLine(later)) fail(`after 9 s the second page shows ${JSON.stringify(later.updateLine)}, not "Update available." with Update`);
    // Nothing started by itself: no job.
    const facts = await apiRead<{ job: { state: string } }>(t, "/api/update");
    if (facts.job.state !== "idle") fail(`a job is ${facts.job.state} with no press of Update`);
    for (const p of pages) issueFindings(p.page.takeIssues(), failures);
  };
  try {
    await body();
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  } finally {
    for (const p of pages) {
      p.inbox.dispose();
      p.wire.dispose();
      await p.page.close();
    }
  }
  const note = "Checked just now after the check at start; a new commit on origin; Check now is one POST /api/update/check; Update available with Update; the second page's update notice with its Update action, its line in the sidebar's foot (none above a phone chat's message box), still there after 9 s; no job by itself";
  return finish({ kind: "flow", name: "update-check-now", route: "setting", scene: t.scene, size: sizeTag(vp), theme: "dark", path: about, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

async function updateRunFlow(t: Target, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const about = "/settings/about";
  const confirm = "/settings/about/update";
  const s = scratchOf.get(t);
  let shot: string | undefined;
  const pages: { page: Page; wire: Wire; inbox: Inbox }[] = [];
  const open = async () => {
    const page = await Page.open(cdp, vp, "dark");
    const p = { page, wire: new Wire(cdp, page), inbox: new Inbox(cdp, page) };
    pages.push(p);
    return p;
  };
  const body = async (): Promise<void> => {
    if (!s?.next) return void fail("the flow has no scratch checkout with a new commit on origin", "run");
    const scripts0 = await pageScripts(t);
    const A = await open();
    await A.page.navigate(t.base + about);
    await waitShown(A.page, ["settings-about"], 8000);
    const epoch0 = (await A.inbox.waitFor((f) => f.t === "welcome", 5000))?.f.epoch as string | undefined;
    const s0 = (await untilUpdate(A.page, (x) => x.updateButton, 15_000)).s;
    details.before = s0;
    if (!s0.updateButton) return void fail(`About shows no Update (${JSON.stringify(s0.update)})`);
    const B = await open();
    await B.page.navigate(t.base + "/settings/general");
    await waitShown(B.page, ["settings-general"], 8000);
    for (const p of [A, B]) await p.page.evaluate(UPDATE_SAMPLER);

    // Update opens the confirm, which alone acts.
    const m0 = A.wire.mark();
    if (!(await pressOn(A.page, '[data-testid="update-open"]'))) return void fail("no Update to press");
    await waitShown(A.page, ["dialog-update", "confirm-update"], 5000);
    await sleep(300);
    const sd = await lookUpdate(A.page);
    if (sd.path !== confirm || !sd.dialog) fail(`Update opened ${sd.path}${sd.dialog ? "" : " with no confirm"}, not ${confirm}`);
    quietFindings(A.wire, m0, await recorder(A.page), failures, "Update's confirm, opened: ");
    await A.page.screenshot(shotName(t.scene, "update-run", vp, "dark", "confirm")).catch(() => {});
    const m1 = A.wire.mark();
    if (!(await pressOn(A.page, '[data-testid="confirm-update"]'))) return void fail("the confirm shows no Update");
    await waitSent(A.wire, m1);
    const sent = A.wire.httpSince(m1);
    details.sent = sent.map(httpText);
    if (sent.length !== 1 || sent[0]!.method !== "POST" || sent[0]!.path !== "/api/update") fail(`the confirm's Update sent ${clipList(sent.map(httpText)) || "nothing"}; expected one POST /api/update`);
    else if (sent[0]!.status !== 202) fail(`POST /api/update answered ${sent[0]!.status}, not 202`);

    // The steps, then Restart to apply.
    const done = await untilUpdate(A.page, (x) => !!x.apply && !x.step, 180_000);
    details.done = done.s;
    if (!done.ok) return void fail(`About never showed Restart to apply after the update (${JSON.stringify(done.s.step ?? done.s.update)})`);
    if (done.s.path !== about) fail(`after the confirm's Update the page is at ${done.s.path}, not ${about}`);
    shot = shotName(t.scene, "update-run", vp, "dark", "restart-to-apply");
    await A.page.screenshot(shot).catch(() => {});
    await sleep(300);
    const seenA = JSON.parse(await A.page.evaluate<string>(UPDATE_SEEN)) as string[];
    const seenB = JSON.parse(await B.page.evaluate<string>(UPDATE_SEEN)) as string[];
    details.lines = { about: seenA, second: seenB };
    const stepLine = (x: string) => /^Updating kitespan: step [1-3] of 3, (fetch|install|build)\.$/.test(x);
    if (!seenA.some(stepLine)) fail(`About never showed the step line (it showed ${clipList(seenA)})`);
    if (!seenB.some(stepLine)) fail(`the second page never showed the step line (it showed ${clipList(seenB)})`);
    const notices = B.inbox.since(0, (f) => f.t === "notice" && f.id === "update").map((f) => f.text as string);
    details.notices = notices;
    if (!notices.some(stepLine)) fail(`the second page got no notice with the step line (${clipList(notices)})`);
    if (notices.at(-1) !== "Restart to apply the update.") fail(`the last update notice is ${JSON.stringify(notices.at(-1))}, not "Restart to apply the update."`);
    // The running server keeps its own build; the disk holds the new one.
    const served = await servedBuild(t);
    details.build = { served, disk: stampHead(s.dist), head: s.head, next: s.next };
    if (served !== s.head) fail("the running server does not serve the build it started with");
    if (stampHead(s.dist) !== s.next) fail("the build folder does not hold the new HEAD's build");
    const facts = await apiRead<{ update: string; build: string; job: { state: string } }>(t, "/api/update");
    details.facts = facts;
    if (facts.build !== "apply" || facts.job.state !== "done") fail(`GET /api/update says ${JSON.stringify(facts)}, not Restart to apply with the job done`);
    if (facts.update !== "none") fail(`after the update origin's line still says ${facts.update}`);

    // A turn runs in the example chat; the restart dialog's Restart now restarts.
    await B.page.navigate(`${t.base}/c/${EX.chat}`);
    await waitShown(B.page, ["chat", "composer"], 8000);
    if (!(await sendFromBox(B.page, pacedPrompt(3000, 120, 150)))) return void fail("the example chat shows no message box with Send");
    if (!(await untilLook(B.page, (x) => x.working > 0, 10_000)).ok) fail("the paced turn did not start");
    if (!(await pressOn(A.page, '[data-testid="setting-restart"] a'))) return void fail("About shows no Restart");
    await waitShown(A.page, ["dialog-restart", "confirm-restart-now"], 8000);
    const m2 = A.wire.mark();
    if (!(await pressOn(A.page, '[data-testid="confirm-restart-now"]'))) return void fail("the restart dialog shows no Restart now");
    await waitSent(A.wire, m2);
    const asked = A.wire.httpSince(m2);
    details.restart = asked.map(httpText);
    if (asked.length !== 1 || asked[0]!.path !== "/api/restart" || asked[0]!.status !== 202) fail(`Restart now sent ${clipList(asked.map(httpText)) || "nothing"}; expected one POST /api/restart (202)`);
    const w = await A.inbox.waitFor((f) => f.t === "welcome" && f.epoch !== epoch0, 60_000);
    if (!w) return void fail("no welcome from the successor within 60 s");
    let head: string | null = null;
    for (let i = 0; i < 40 && head !== s.next; i++) {
      head = await servedBuild(t);
      if (head !== s.next) await sleep(250);
    }
    details.successor = { head, successors: t.booted?.successors() ?? [] };
    if (head !== s.next) fail("the successor does not serve the new HEAD's build");
    const scripts1 = await pageScripts(t);
    details.scripts = { before: scripts0, after: scripts1 };
    if (JSON.stringify(scripts1) === JSON.stringify(scripts0)) fail("the successor's page names the same scripts as before the update");
    const after = await apiRead<{ build: string }>(t, "/api/update");
    if (after.build !== "none") fail(`the successor's About still says ${after.build}`);
    await sleep(1500);
    await A.page.screenshot(shotName(t.scene, "update-run", vp, "dark", "after")).catch(() => {});
    for (const p of pages) issueFindings(p.page.takeIssues().filter((i) => !/ERR_CONNECTION|net::|Failed to fetch|WebSocket/i.test(i.text)), failures);
  };
  try {
    await body();
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  } finally {
    for (const p of pages) {
      p.inbox.dispose();
      p.wire.dispose();
      await p.page.close();
    }
  }
  const note = "Update opens its confirm; one POST /api/update (202); the step line on About and on a second page; Restart to apply; the old build still served; Restart now during a turn; the successor serves the new HEAD with other scripts";
  return finish({ kind: "flow", name: "update-run", route: "setting", scene: t.scene, size: sizeTag(vp), theme: "dark", path: `${about} and ${confirm}`, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

async function updateRefusedFlow(t: Target, vp: Viewport): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const confirm = "/settings/about/update";
  const s = scratchOf.get(t);
  let shot: string | undefined;
  try {
    if (!s) return finish({ kind: "flow", name: "update-refused", route: "setting", scene: t.scene, size: sizeTag(vp), theme: "dark", path: confirm, failures: [{ code: "run", text: "the flow has no scratch checkout" }], warnings, note: "", ms: 0, details });
    const headBefore = Bun.spawnSync(["git", "-C", s.app, "rev-parse", "HEAD"], { env: { PATH: "/usr/bin:/bin", GIT_CONFIG_GLOBAL: "/dev/null", GIT_CONFIG_NOSYSTEM: "1" }, stdout: "pipe" }).stdout.toString().trim();
    await withPage(vp, "dark", async (page, wire) => {
      await page.navigate(t.base + "/settings/about");
      await waitShown(page, ["settings-about"], 8000);
      if (!(await untilUpdate(page, (x) => x.updateButton, 15_000)).ok) return void fail("About shows no Update");
      if (!(await pressOn(page, '[data-testid="update-open"]'))) return void fail("no Update to press");
      await waitShown(page, ["dialog-update", "confirm-update"], 5000);
      const m = wire.mark();
      if (!(await pressOn(page, '[data-testid="confirm-update"]'))) return void fail("the confirm shows no Update");
      await waitSent(wire, m);
      const sent = wire.httpSince(m);
      details.sent = sent.map(httpText);
      if (sent.length !== 1 || sent[0]!.path !== "/api/update") fail(`Update sent ${clipList(sent.map(httpText)) || "nothing"}; expected one POST /api/update`);
      else if (sent[0]!.status !== 409) fail(`POST /api/update answered ${sent[0]!.status}, not 409`);
      const r = await untilUpdate(page, (x) => !!x.dialogLine, 5000);
      details.dialog = r.s;
      if (r.s.dialogLine !== "This checkout has local changes.") fail(`the confirm says ${JSON.stringify(r.s.dialogLine)}, not "This checkout has local changes."`);
      if (r.s.path !== confirm) fail(`after the refusal the page is at ${r.s.path}, not ${confirm}`);
      shot = shotName(t.scene, "update-refused", vp, "dark", "refused");
      await page.screenshot(shot).catch(() => {});
      issueFindings(page.takeIssues().filter((i) => !/409/.test(i.text)), failures);
    });
    const facts = await apiRead<{ job: { state: string } }>(t, "/api/update");
    const headAfter = Bun.spawnSync(["git", "-C", s.app, "rev-parse", "HEAD"], { env: { PATH: "/usr/bin:/bin", GIT_CONFIG_GLOBAL: "/dev/null", GIT_CONFIG_NOSYSTEM: "1" }, stdout: "pipe" }).stdout.toString().trim();
    details.after = { job: facts.job, headBefore, headAfter };
    if (facts.job.state !== "idle") fail(`a refused Update left a job ${facts.job.state}`);
    if (headAfter !== headBefore) fail("a refused Update moved the checkout's HEAD");
    if (stampHead(s.dist) !== s.head) fail("a refused Update changed the build folder");
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = 'a local change in the checkout: the confirm\'s Update is one POST /api/update, 409, "This checkout has local changes."; no job, HEAD and the build as they were';
  return finish({ kind: "flow", name: "update-refused", route: "setting", scene: t.scene, size: sizeTag(vp), theme: "dark", path: confirm, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/** Row 108's flows, each on a scratch checkout of its own (none with --base). */
async function updateFlows(flows: readonly string[], record: (r: CheckResult) => void, problems: string[]): Promise<void> {
  const want = (f: UpdateFlow) => flows.includes(f);
  if (!UPDATE_FLOWS.some(want)) return;
  if (BASE) {
    console.log("ui-check: the update flows boot a scratch checkout of their own, so --base runs none of them");
    return;
  }
  const laptop = CORE.some((v) => v.name === "laptop") ? WIDE_LAPTOP : null;
  const phone = CORE.find((v) => v.name === "phone") ?? null;
  const on = async (name: UpdateFlow, o: { next?: "page" | "none"; localChange?: boolean }, run: (t: Target) => Promise<void>, vps: Viewport[]) => {
    if (!want(name) || !vps.length || cdp.closed) return;
    let t: Target;
    try {
      t = await openScratchTarget("main", o);
    } catch (e) {
      for (const vp of vps) record(finish({ kind: "flow", name, route: "setting", scene: "main", size: sizeTag(vp), theme: "dark", path: "/settings/about", failures: [{ code: "seed", text: `the scratch checkout did not boot: ${(e as Error).message}` }], warnings: [], note: "", ms: 0, details: {} }));
      return;
    }
    try {
      await run(t);
    } finally {
      await closeScratchTarget(t, problems);
    }
  };
  const settingSizes = [laptop, phone].filter((v): v is Viewport => !!v);
  await on("update-setting", { next: "none" }, async (t) => {
    if (laptop) for (const theme of THEMES) record(await updateSettingFlow(t, laptop, theme));
    if (phone) record(await updateSettingFlow(t, phone, THEMES.includes("light") ? "light" : THEMES[0]!));
  }, settingSizes);
  if (laptop) {
    await on("update-check-now", { next: "none" }, async (t) => record(await updateCheckNowFlow(t, laptop)), [laptop]);
    await on("update-run", { next: "page" }, async (t) => record(await updateRunFlow(t, laptop)), [laptop]);
    await on("update-refused", { next: "page", localChange: true }, async (t) => record(await updateRefusedFlow(t, laptop)), [laptop]);
  }
  if (want("update-install") && !cdp.closed) await updateInstallFlow(record, problems);
  if (want("update-brew") && !cdp.closed) await updateBrewFlow(record, problems);
}

// ---------------------------------------------------------------------------------------------------------------
// DESIGN-I1 3.9: Settings > About for an installed kitespan, each on a scratch install of its own (test/click/scratch.ts),
// at 1280x800 and at 390x844 with touch, dark and light, each state of About in a page of its own that sends nothing
// mutating. --base runs none of them.
//
// - update-install: a release install made by its own install.sh (0.1.0, from a local folder of release archives,
//   KITESPAN_INSTALL_FROM, with `bun install` in a network namespace of its own and the user's Bun cache), booted from
//   its version folder; the server's HOME, XDG folders and TMPDIR are inside the scratch folders (checked first), and
//   the installer that its Update runs takes the same offline bun (the first folder of its PATH). About: Version 0.1.0,
//   Check now and no Update. The new release goes out (SHA256SUMS lists 0.1.1); Check now is one POST /api/update/check,
//   then Update available with "Version 0.1.1" and Update; Update opens its confirm, whose Update is one POST
//   /api/update (202); the step lines; Restart to apply with "Version 0.1.1"; Restart is one POST /api/restart (202), and
//   the successor (0.1.1's own bin/kitespan, in its own folder) serves the new page (other scripts) and About says
//   Version 0.1.1. The successor is stopped by the pid its predecessor printed, after kill -0 and a /proc check.
// - update-brew: a Homebrew layout by hand (a keg 0.1.0 with its receipt, opt naming it). About: Version 0.1.0,
//   "Installed with Homebrew" with `brew upgrade kitespan` as a code span that one tap selects whole, no Update, no Check
//   for updates and no Check now; then a keg 0.1.1 and opt moved to it: Restart to apply with "Version 0.1.1".

interface InstallLook {
  path: string;
  version: string | null;
  update: string | null;
  updateButton: boolean;
  step: string | null;
  apply: string | null;
  homebrew: string | null;
  /** The brew row's command: its text, its user-select and its font. */
  code: { text: string; select: string; font: string } | null;
  check: boolean;
  checkNow: string | null;
  checkNowButton: boolean;
  restart: boolean;
}

/** In-page: About's rows for an installed kitespan, as the user sees them. */
const INSTALL_LOOK = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const one = (id) => [...document.querySelectorAll('[data-testid="' + id + '"]')].find(shown) || null;
  const t = (el) => (el ? el.textContent.replace(/\\s+/g, " ").trim() : null);
  const code = one("setting-homebrew")?.querySelector("code") ?? null;
  const cs = code ? getComputedStyle(code) : null;
  return {
    path: location.pathname + location.search,
    version: t(one("setting-version")),
    update: t(one("setting-update")),
    updateButton: !!one("update-open"),
    step: t(one("setting-update-step")),
    apply: t(one("setting-restart-to-apply")),
    homebrew: t(one("setting-homebrew")),
    code: code && cs ? { text: t(code), select: cs.userSelect || cs.webkitUserSelect || "", font: cs.fontFamily } : null,
    check: !!one("setting-check-for-updates"),
    checkNow: t(one("setting-check-now")),
    checkNowButton: !!one("check-now"),
    restart: !!one("setting-restart"),
  };
})())`;
const lookInstall = async (page: Page): Promise<InstallLook> => JSON.parse(await page.evaluate<string>(INSTALL_LOOK)) as InstallLook;
async function untilInstall(page: Page, ok: (s: InstallLook) => boolean, ms: number): Promise<{ s: InstallLook; ok: boolean }> {
  const end = Date.now() + ms;
  for (;;) {
    const s = await lookInstall(page).catch(() => null);
    if (s && ok(s)) return { s, ok: true };
    if (Date.now() > end) return { s: s ?? (await lookInstall(page)), ok: false };
    await sleep(100);
  }
}

type InstallCombo = { vp: Viewport; theme: Theme };
const comboKey = (c: InstallCombo) => `${c.vp.name}|${c.theme}`;

/** The sizes and looks of an install flow: 1280x800 and 390x844 (touch), as --sizes and --themes allow, laptop dark first. */
function installCombos(): InstallCombo[] {
  const vps = [...(CORE.some((v) => v.name === "laptop") ? [WIDE_LAPTOP] : []), ...CORE.filter((v) => v.name === "phone")];
  const themes = [...THEMES].sort((a, b) => (a === "dark" ? -1 : b === "dark" ? 1 : 0));
  return vps.flatMap((vp) => themes.map((theme) => ({ vp, theme })));
}

/** An install flow's findings, one result per size and look. */
class InstallRun {
  readonly failures = new Map<string, Finding[]>();
  readonly warnings = new Map<string, Finding[]>();
  readonly details = new Map<string, Record<string, unknown>>();
  readonly shots = new Map<string, string>();
  readonly t0 = Date.now();
  constructor(
    readonly name: string,
    readonly combos: InstallCombo[],
  ) {
    for (const c of combos) {
      this.failures.set(comboKey(c), []);
      this.warnings.set(comboKey(c), []);
      this.details.set(comboKey(c), {});
    }
  }
  /** A finding of the run itself (its laptop dark result, or its first). */
  fail(text: string, code = "flow") {
    this.failures.get(comboKey(this.combos[0]!))!.push({ code, text });
  }
  /** A finding that leaves every size and look unchecked (no seed, the run broke off). */
  failAll(text: string, code: string) {
    for (const c of this.combos) this.failures.get(comboKey(c))!.push({ code, text });
  }
  record(record: (r: CheckResult) => void, note: string) {
    for (const c of this.combos) {
      const k = comboKey(c);
      record(finish({ kind: "flow", name: this.name, route: "setting", scene: "main", size: sizeTag(c.vp), theme: c.theme, path: "/settings/about", failures: this.failures.get(k)!, warnings: this.warnings.get(k)!, note, shot: this.shots.get(k), ms: Date.now() - this.t0, details: this.details.get(k)! }));
    }
  }
}

/**
 * About at each size and look, in a page of its own: wait until `want` says nothing (null), then the layout's checks,
 * nothing mutating sent, no console error, and a shot named for the step.
 */
async function installLooks(t: Target, run: InstallRun, step: string, want: (x: InstallLook) => string | null): Promise<void> {
  for (const c of run.combos) {
    if (cdp.closed) return;
    const k = comboKey(c);
    const failures = run.failures.get(k)!;
    await withPage(c.vp, c.theme, async (page, wire) => {
      const m = wire.mark();
      await page.navigate(t.base + "/settings/about");
      await waitShown(page, ["settings-about", "setting-version", "setting-restart"], 8000);
      const r = await untilInstall(page, (x) => want(x) === null, 10_000);
      run.details.get(k)![step] = r.s;
      const problem = want(r.s);
      if (problem) failures.push({ code: "flow", text: `${step}: ${problem}` });
      stateFindings(await page.probe(), c.vp, failures, `${step}: `);
      await sleep(300);
      quietFindings(wire, m, await recorder(page), failures, `${step}, About opened: `);
      issueFindings(page.takeIssues(), failures, `${step}: `);
      const shot = shotName("main", run.name, c.vp, c.theme, step);
      await page.screenshot(shot).catch(() => {});
      run.shots.set(k, shot);
    });
  }
}

/** HOME, the XDG folders and TMPDIR of a booted server (Linux: /proc/<pid>/environ), each inside `scratch`; else the problem. */
function scratchEnvProblem(pid: number, scratch: string): string | null {
  let text: string;
  try {
    text = readFileSync(`/proc/${pid}/environ`, "utf8");
  } catch {
    return "the server's environment could not be read (/proc)";
  }
  const env = new Map(text.split("\0").filter(Boolean).map((kv) => [kv.slice(0, kv.indexOf("=")), kv.slice(kv.indexOf("=") + 1)] as const));
  for (const name of ["HOME", "XDG_STATE_HOME", "XDG_CONFIG_HOME", "XDG_DATA_HOME", "TMPDIR"]) {
    const v = env.get(name);
    if (!v || !v.startsWith(`${scratch}/`)) return `the server's ${name} is not inside the scratch folder ${scratch}`;
  }
  return null;
}

/**
 * Stop the successor that a restart of `t` started: the pid its predecessor printed ("kitespan restarted as process
 * <pid>"), only while it lives and its command line is `root`'s server on this port; SIGTERM, then SIGKILL after 15 s.
 */
async function stopSuccessor(t: Target, root: string, problems: string[]): Promise<void> {
  const m = /kitespan restarted as process (\d+);/.exec(t.booted?.output().out ?? "");
  if (!m) return;
  const pid = Number(m[1]);
  const ours = () => {
    try {
      process.kill(pid, 0);
    } catch {
      return false;
    }
    let cl: string[];
    try {
      cl = readFileSync(`/proc/${pid}/cmdline`, "utf8").split("\0");
    } catch {
      return false;
    }
    return cl.includes(join(root, "server", "main.ts")) && cl.some((a, i) => a === "--port" && cl[i + 1] === String(PORT)) && cl.includes("--bind-wait");
  };
  if (!ours()) return;
  process.kill(pid, "SIGTERM");
  for (let i = 0; i < 150 && ours(); i++) await sleep(100);
  if (ours()) {
    process.kill(pid, "SIGKILL");
    problems.push(`update-install: the successor ${pid} did not stop on SIGTERM in 15 s`);
  }
}

async function updateInstallFlow(record: (r: CheckResult) => void, problems: string[]): Promise<void> {
  const run = new InstallRun("update-install", installCombos());
  if (!run.combos.length) return;
  const note =
    "a release install by its own install.sh, offline: Version 0.1.0; the new release out; Check now, then Update available with Version 0.1.1; Update's confirm, one POST /api/update; the step lines; Restart to apply with Version 0.1.1; Restart; the successor serves the new page, Version 0.1.1";
  const skip = releaseProblem();
  if (skip) {
    for (const c of run.combos) run.warnings.get(comboKey(c))!.push({ code: "skip", text: `not run: ${skip}` });
    return run.record(record, note);
  }
  let s: ScratchRelease;
  try {
    s = scratchRelease();
  } catch (e) {
    run.failAll(`the scratch release install could not be made: ${(e as Error).message}`, "seed");
    return run.record(record, note);
  }
  let t: Target | null = null;
  const laptop = run.combos[0]!;
  try {
    const b = await boot({ scene: "main", port: PORT, dist: s.dist, root: s.root, keep: KEEP, env: { ...SERVER_ENV, KITESPAN_INSTALL_FROM: s.releases, BUN_INSTALL_CACHE_DIR: s.cache } });
    live.add(b);
    t = { base: b.base, scene: "main", booted: b };
    // The installer that Update runs finds bun on the server's PATH: its first folder gets the bun with no network.
    offlineBun(b.fake.binDir);
    const scratch = realpathSync(tmpdir());
    const where = scratchEnvProblem(b.pid, scratch) ?? (s.root.startsWith(`${scratch}/`) ? null : `the install ${s.root} is not inside ${scratch}`);
    run.details.get(comboKey(laptop))!.install = { root: s.root, log: s.installLog.split("\n").filter(Boolean).slice(-6) };
    if (where) return void run.failAll(where, "seed");
    const f0 = await apiRead<UpdateFactsReply>(t, "/api/update");
    run.details.get(comboKey(laptop))!.facts0 = f0;
    if (f0.kind !== "release" || !f0.can) run.fail(`GET /api/update says kind ${JSON.stringify(f0.kind)} and can ${f0.can}, not a release install that can update`);

    await installLooks(t, run, "installed", (x) =>
      !x.version?.includes("0.1.0") ? `the Version row says ${JSON.stringify(x.version)}, not 0.1.0` : !x.checkNow?.startsWith("Checked") ? `Check now says ${JSON.stringify(x.checkNow)}, not that it checked` : x.updateButton || x.update ? `About shows ${JSON.stringify(x.update)} before a new release` : !x.check || !x.checkNowButton ? "About has no Check for updates or no Check now" : x.homebrew ? "About shows the Homebrew row" : null,
    );

    // The new release goes out; Check now on the laptop.
    s.publish();
    await withPage(laptop.vp, laptop.theme, async (page, wire) => {
      await page.navigate(t!.base + "/settings/about");
      await waitShown(page, ["settings-about", "setting-check-now"], 8000);
      const m = wire.mark();
      if (!(await pressOn(page, '[data-testid="check-now"]'))) return void run.fail("no Check now to press");
      await waitSent(wire, m);
      const sent = wire.httpSince(m);
      if (sent.length !== 1 || sent[0]!.method !== "POST" || sent[0]!.path !== "/api/update/check") run.fail(`Check now sent ${clipList(sent.map(httpText)) || "nothing"}; expected one POST /api/update/check`);
      const r = await untilInstall(page, (x) => x.updateButton, 15_000);
      if (!r.ok) run.fail(`after Check now About shows ${JSON.stringify(r.s.update)} with no Update`);
    });
    const f1 = await apiRead<UpdateFactsReply>(t, "/api/update");
    run.details.get(comboKey(laptop))!.facts1 = f1;
    if (f1.update !== "available" || f1.latest !== "0.1.1") run.fail(`after Check now GET /api/update says ${JSON.stringify({ update: f1.update, latest: f1.latest })}, not available with 0.1.1`);
    await installLooks(t, run, "available", (x) =>
      !x.update?.startsWith("Update available") || !x.update.includes("Version 0.1.1") ? `the update row says ${JSON.stringify(x.update)}, not Update available with Version 0.1.1` : !x.updateButton ? "no Update" : !x.version?.includes("0.1.0") ? `the Version row says ${JSON.stringify(x.version)}` : null,
    );

    // Update, its confirm, the steps, Restart to apply.
    const A = { page: await Page.open(cdp, laptop.vp, laptop.theme) } as { page: Page; wire: Wire; inbox: Inbox };
    A.wire = new Wire(cdp, A.page);
    A.inbox = new Inbox(cdp, A.page);
    try {
      await A.page.navigate(t.base + "/settings/about");
      await waitShown(A.page, ["settings-about"], 8000);
      const epoch0 = (await A.inbox.waitFor((f) => f.t === "welcome", 5000))?.f.epoch as string | undefined;
      await untilInstall(A.page, (x) => x.updateButton, 10_000);
      await A.page.evaluate(UPDATE_SAMPLER);
      if (!(await pressOn(A.page, '[data-testid="update-open"]'))) return void run.fail("no Update to press");
      await waitShown(A.page, ["dialog-update", "confirm-update"], 5000);
      await sleep(300);
      await A.page.screenshot(shotName("main", run.name, laptop.vp, laptop.theme, "confirm")).catch(() => {});
      const m1 = A.wire.mark();
      if (!(await pressOn(A.page, '[data-testid="confirm-update"]'))) return void run.fail("the confirm shows no Update");
      await waitSent(A.wire, m1);
      const sent = A.wire.httpSince(m1);
      run.details.get(comboKey(laptop))!.updateSent = sent.map(httpText);
      if (sent.length !== 1 || sent[0]!.path !== "/api/update" || sent[0]!.status !== 202) run.fail(`the confirm's Update sent ${clipList(sent.map(httpText)) || "nothing"}; expected one POST /api/update (202)`);
      const done = await untilInstall(A.page, (x) => !!x.apply && !x.step, 300_000);
      const seen = JSON.parse(await A.page.evaluate<string>(UPDATE_SEEN)) as string[];
      run.details.get(comboKey(laptop))!.lines = seen;
      if (!done.ok) return void run.fail(`About never showed Restart to apply (${JSON.stringify(done.s.step ?? done.s.update)})`);
      for (const n of [1, 2, 3]) if (!seen.some((x) => x.startsWith(`Updating kitespan: step ${n} of 3, `))) run.fail(`About never showed step ${n} of 3 (it showed ${clipList(seen)})`);
      const f2 = await apiRead<UpdateFactsReply>(t, "/api/update");
      run.details.get(comboKey(laptop))!.facts2 = f2;
      if (f2.build !== "apply" || f2.next !== "0.1.1" || f2.job.state !== "done" || f2.update !== "none") run.fail(`after the update GET /api/update says ${JSON.stringify({ build: f2.build, next: f2.next, job: f2.job, update: f2.update })}, not Restart to apply 0.1.1 with the job done`);
      await installLooks(t, run, "restart-to-apply", (x) => (!x.apply?.startsWith("Restart to apply") || !x.apply.includes("Version 0.1.1") ? `the row says ${JSON.stringify(x.apply)}, not Restart to apply with Version 0.1.1` : x.updateButton ? "Update still shows" : !x.version?.includes("0.1.0") ? `the Version row says ${JSON.stringify(x.version)}` : null));

      // Restart: the successor is 0.1.1's own.
      const scripts0 = await pageScripts(t);
      if (!(await pressOn(A.page, '[data-testid="setting-restart"] a'))) return void run.fail("About shows no Restart");
      await waitShown(A.page, ["dialog-restart"], 8000);
      const nowButton = (await A.page.probe()).ids.includes("confirm-restart-now") && !(await A.page.probe()).ids.includes("confirm-restart");
      const m2 = A.wire.mark();
      if (!(await pressOn(A.page, nowButton ? '[data-testid="confirm-restart-now"]' : '[data-testid="confirm-restart"]'))) return void run.fail("the restart dialog shows no Restart");
      await waitSent(A.wire, m2);
      const asked = A.wire.httpSince(m2);
      run.details.get(comboKey(laptop))!.restartSent = asked.map(httpText);
      if (asked.length !== 1 || asked[0]!.path !== "/api/restart" || asked[0]!.status !== 202) run.fail(`Restart sent ${clipList(asked.map(httpText)) || "nothing"}; expected one POST /api/restart (202)`);
      const w = await A.inbox.waitFor((f) => f.t === "welcome" && f.epoch !== epoch0, 90_000);
      if (!w) return void run.fail("no welcome from the successor within 90 s");
      const f3 = await apiRead<UpdateFactsReply>(t, "/api/update");
      run.details.get(comboKey(laptop))!.facts3 = f3;
      if (f3.kind !== "release" || f3.build !== "none" || f3.next !== null) run.fail(`the successor's GET /api/update says ${JSON.stringify({ kind: f3.kind, build: f3.build, next: f3.next })}`);
      const scripts1 = await pageScripts(t);
      if (JSON.stringify(scripts1) === JSON.stringify(scripts0)) run.fail("the successor's page names the same scripts as 0.1.0's");
      issueFindings(A.page.takeIssues().filter((i) => !/ERR_CONNECTION|net::|Failed to fetch|WebSocket/i.test(i.text)), run.failures.get(comboKey(laptop))!, "the update's page: ");
    } finally {
      A.inbox.dispose();
      A.wire.dispose();
      await A.page.close();
    }
    await installLooks(t, run, "restarted", (x) => (!x.version?.includes("0.1.1") ? `the Version row says ${JSON.stringify(x.version)}, not 0.1.1` : x.apply || x.updateButton ? `About still shows ${JSON.stringify(x.apply ?? x.update)}` : null));
  } catch (e) {
    run.failAll(`the check could not run: ${(e as Error).message}`, "run");
  } finally {
    if (t) {
      await stopSuccessor(t, join(s.kit, "versions", "0.1.1"), problems).catch(() => {});
      await closeTarget(t, problems).catch(() => {});
    }
    s.remove();
  }
  run.record(record, note);
}

async function updateBrewFlow(record: (r: CheckResult) => void, problems: string[]): Promise<void> {
  const run = new InstallRun("update-brew", installCombos());
  if (!run.combos.length) return;
  const note = "a Homebrew keg by hand: Version 0.1.0, Installed with Homebrew with brew upgrade kitespan as a code span, no Update and no check rows; after a keg 0.1.1 and opt moved to it, Restart to apply with Version 0.1.1; nothing mutating sent";
  let s: ScratchBrew;
  try {
    s = scratchBrew();
  } catch (e) {
    run.failAll(`the scratch Homebrew layout could not be made: ${(e as Error).message}`, "seed");
    return run.record(record, note);
  }
  let t: Target | null = null;
  try {
    const b = await boot({ scene: "main", port: PORT, dist: s.dist, root: s.root, keep: KEEP, env: SERVER_ENV });
    live.add(b);
    t = { base: b.base, scene: "main", booted: b };
    const where = scratchEnvProblem(b.pid, realpathSync(tmpdir()));
    if (where) return void run.failAll(where, "seed");
    const f0 = await apiRead<UpdateFactsReply>(t, "/api/update");
    run.details.get(comboKey(run.combos[0]!))!.facts0 = f0;
    if (f0.kind !== "brew" || f0.can || f0.check.at !== null) run.fail(`GET /api/update says ${JSON.stringify({ kind: f0.kind, can: f0.can, checked: f0.check.at })}, not a Homebrew install that never checks and cannot update`);
    const brewRow = (x: InstallLook) =>
      !x.homebrew?.includes("Installed with Homebrew") || !x.homebrew.includes("Update it with brew upgrade kitespan, then restart kitespan.")
        ? `the Homebrew row says ${JSON.stringify(x.homebrew)}`
        : x.code?.text !== "brew upgrade kitespan" || x.code.select !== "all"
          ? `the command is ${JSON.stringify(x.code)}, not brew upgrade kitespan selected whole`
          : x.check || x.checkNow || x.checkNowButton
            ? "About shows Check for updates or Check now"
            : x.updateButton || x.update
              ? `About shows ${JSON.stringify(x.update)} with Update`
              : !x.restart
                ? "About shows no Restart"
                : null;
    await installLooks(t, run, "installed", (x) => brewRow(x) ?? (!x.version?.includes("0.1.0") ? `the Version row says ${JSON.stringify(x.version)}, not 0.1.0` : x.apply ? `About shows ${JSON.stringify(x.apply)}` : null));
    s.upgrade();
    const f1 = await apiRead<UpdateFactsReply>(t, "/api/update");
    run.details.get(comboKey(run.combos[0]!))!.facts1 = f1;
    if (f1.build !== "apply" || f1.next !== "0.1.1") run.fail(`after opt moved GET /api/update says ${JSON.stringify({ build: f1.build, next: f1.next })}, not Restart to apply 0.1.1`);
    await installLooks(t, run, "upgraded", (x) => brewRow(x) ?? (!x.apply?.startsWith("Restart to apply") || !x.apply.includes("Version 0.1.1") ? `the row says ${JSON.stringify(x.apply)}, not Restart to apply with Version 0.1.1` : null));
  } catch (e) {
    run.failAll(`the check could not run: ${(e as Error).message}`, "run");
  } finally {
    if (t) await closeTarget(t, problems).catch(() => {});
    s.remove();
  }
  run.record(record, note);
}

/** GET /api/update's answer, as the install flows read it. */
interface UpdateFactsReply {
  update: string;
  build: string;
  kind: string;
  latest: string | null;
  next: string | null;
  can: boolean;
  job: { state: string };
  check: { at: string | null };
}

// ---------------------------------------------------------------------------------------------------------------
// Row 116, the four dots (FIX-R116, DESIGN-R116), on the dots scene's seed (test/click/seed/scenes.ts DOT_SCENE): the
// example chat's permission card waits (Needs input), Connect the docs server runs a Bash call (Working), Pick the
// test layers has an end that no page has seen (Unread) and Refactor the query parser's last turn failed unseen
// (Failed). unseen-dot runs at 1280x800 and at 390x844 with touch, dark and light, and at 1280x800 in light and dark in
// each of the four looks (wearLook: the look's attribute on the page's root, as the page's own applyLook sets it):
// - the list (the laptop's sidebar, the phone's /chats) shows the four dots: Working in --ok-fill; Needs input in the
//   look's warm --attn-dot, a gold-amber that is not the accent, with the needs-you pulse (none under the system's
//   Reduce motion or Settings' On, the root's data-motion) and its word in --attn; Unread in the look's accent
//   (--unread-dot: --ring in glass dark), still, with no visible word; Failed in --danger with its word. Each dot is
//   aria-hidden, and each row's name says the state ("Needs input, <title>", "<title> Working", "Failed, <title>", the
//   hidden "Unread, " before an unread row's time). On the laptop a folded heading counts Needs input only;
// - a turn ends on Plan the search index, which no page has open (a setup socket sends the message), and its row's dot
//   shows in the accent; a second page (the other size, in a browser context of its own) opens the chat: it sends an
//   on_screen and nothing that acts, and the first page's unread dot goes. A turn that ends while the second page
//   shows the chat at its end is seen at once: the first page's row never shows the unread dot. The last run opens the
//   failed chat on the second page too, and the first page's red dot goes. Then, through the real driver and the fake
//   claude, a turn that ends in an error result and a Claude Code that exits by itself (FAILS), each on Plan the search
//   index while no page has it on screen, show the red Failed dot with its word, and the second page that opens the
//   chat clears it. Last, a turn ends again with no page on the chat and the first page opens a link to its first
//   message, far above the end: the chat stays unread on the second page (the view is not at the end), Jump to latest
//   shows (DESIGN-R116 9: the bar has no unread dot, and on the phone no list shows), and pressing it clears the dot;
// - screenshots: each list as a JPEG, and the list as a PNG at twice its size (the laptop's sidebar) or at the phone's
//   own scale, after the turn's end, and the second page.

const UD = { waiting: EX.chat, running: IDS.chats.docs, unread: IDS.chats.layers, failed: IDS.chats.parser, live: IDS.chats.search } as const;
const UD_IDS = Object.values(UD);
/** The messages that end turns on Plan the search index (the fake claude's default turn answers "Done."). */
const UD_FIRST = "Note where the index files live (row 116).";
const UD_AGAIN = "One more line on the index size (row 116).";
/** Plan the search index's first message (the seed's transcript: the session's first group, record 1). */
const UD_FIRST_MESSAGE = `${IDS.sessions.search.slice(0, 8)}-0000-4000-8000-${(1).toString(16).padStart(12, "0")}`;
/** In-page: Jump to latest shows, and how far the conversation is from its end (px). */
const UD_JUMP = `(() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const el = [...document.querySelectorAll(".chat-scroll")].find(shown);
  return { jump: [...document.querySelectorAll(".chat-jump")].some(shown), gap: el ? Math.round(el.scrollHeight - el.scrollTop - el.clientHeight) : null, linked: !!document.querySelector('[data-item-id="${UD_FIRST_MESSAGE}"]') };
})()`;

interface UdRow {
  title: string | null;
  dot: string | null;
  ariaHidden: string | null;
  bg: string | null;
  anim: string | null;
  dur: string | null;
  name: string;
  lead: string | null;
  leadColor: string | null;
  metaHidden: string | null;
}
interface UdLook {
  tokens: { needs: string; word: string; unread: string; accent: string; ring: string; text: string; ok: string; danger: string };
  rows: Record<string, UdRow | null>;
  badge: string[];
  look: string;
}

/** In-page: each row's dot, its colour and animation, the row's words, the tokens' colours, and the shown badges. */
const UD_PROBE = `(() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const fold = (s) => (s || "").replace(/\\s+/g, " ").trim();
  const probe = (v) => { const s = document.createElement("span"); s.style.color = v; document.body.appendChild(s); const c = getComputedStyle(s).color; s.remove(); return c; };
  const tokens = { needs: probe("var(--attn-dot)"), word: probe("var(--attn)"), unread: probe("var(--unread-dot)"), accent: probe("var(--accent)"), ring: probe("var(--ring)"), text: probe("var(--text)"), ok: probe("var(--ok-fill)"), danger: probe("var(--danger)") };
  const rows = {};
  for (const id of ${JSON.stringify(UD_IDS)}) {
    const a = [...document.querySelectorAll('a.scr-row[href="/c/' + id + '"]')].find(shown);
    if (!a) { rows[id] = null; continue; }
    const dot = a.querySelector(".dot");
    const cs = dot ? getComputedStyle(dot) : null;
    const lead = a.querySelector(".scr-lead");
    const meta = a.querySelector(".scr-meta .visually-hidden");
    rows[id] = { title: a.getAttribute("title"), dot: dot ? dot.className : null, ariaHidden: dot ? dot.getAttribute("aria-hidden") : null, bg: cs ? cs.backgroundColor : null, anim: cs ? cs.animationName : null, dur: cs ? cs.animationDuration : null, name: fold(a.textContent), lead: lead ? fold(lead.textContent) : null, leadColor: lead ? getComputedStyle(lead).color : null, metaHidden: meta ? meta.textContent : null };
  }
  const badge = [...document.querySelectorAll(".scr-group-needs")].filter(shown).map((b) => fold(b.textContent));
  return { tokens, rows, badge, look: document.documentElement.getAttribute("data-look") || "glass" };
})()`;
const udDot = (chat: string) => `(() => { const a = [...document.querySelectorAll('a.scr-row[href="/c/${chat}"]')].find((el) => el.getClientRects().length > 0); const d = a && a.querySelector(".dot"); return d ? d.className : null; })()`;

const udRgb = (c: string | null): [number, number, number] | null => {
  const m = /rgba?\((\d+), (\d+), (\d+)/.exec(c ?? "");
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
};
/** The hue (degrees) and HSL saturation of a computed rgb() colour. */
function udHue(c: string | null): [number, number] {
  const rgb = udRgb(c);
  if (!rgb) return [0, 0];
  const [r, g, b] = rgb.map((v) => v / 255) as [number, number, number];
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const d = max - min;
  if (d === 0) return [0, 0];
  const l = (max + min) / 2;
  const h = max === r ? ((g - b) / d) % 6 : max === g ? (b - r) / d + 2 : (r - g) / d + 4;
  return [(h * 60 + 360) % 360, d / (1 - Math.abs(2 * l - 1))];
}

async function udUntil(page: Page, ok: (s: UdLook) => boolean, ms: number): Promise<{ ok: boolean; s: UdLook }> {
  const end = Date.now() + ms;
  let s = await page.evaluate<UdLook>(UD_PROBE);
  while (!ok(s) && Date.now() < end) {
    await sleep(100);
    s = await page.evaluate<UdLook>(UD_PROBE);
  }
  return { ok: ok(s), s };
}

/** The four seeded dots, their colours, the pulse (or none under Reduce motion) and each row's words. */
function udFourDots(s: UdLook, theme: Theme, still: boolean, fail: (text: string) => void, at: string) {
  const row = (id: string, what: string) => {
    const r = s.rows[id];
    if (!r) fail(`${at}: the list shows no row for ${what}`);
    return r;
  };
  const t = s.tokens;
  const w = row(UD.waiting, "the chat that needs input");
  if (w) {
    if (w.dot !== "dot waiting") fail(`${at}: the chat that needs input has "${w.dot}", not the needs-you dot`);
    if (w.bg !== t.needs) fail(`${at}: the needs-you dot is ${w.bg}, not --attn-dot (${t.needs})`);
    const [h, sat] = udHue(w.bg);
    if (!(h >= 35 && h <= 55 && sat >= 0.6)) fail(`${at}: the needs-you dot ${w.bg} is not a warm gold-amber (hue ${h.toFixed(0)}, saturation ${sat.toFixed(2)})`);
    if (w.bg === t.accent || w.bg === t.ring) fail(`${at}: the needs-you dot wears the accent (${w.bg})`);
    if (still ? w.anim !== "none" : w.anim !== "needs-you" || w.dur !== "2.4s") fail(`${at}: the needs-you dot's animation is ${w.anim} ${w.dur}, ${still ? "not none under Reduce motion" : "not the 2.4 s needs-you pulse"}`);
    if (w.lead !== "Needs input," || w.leadColor !== t.word) fail(`${at}: the row's lead word is ${JSON.stringify(w.lead)} in ${w.leadColor}, not "Needs input" in --attn (${t.word})`);
    if (w.name !== `Needs input, ${w.title}`) fail(`${at}: the waiting row reads ${JSON.stringify(w.name)}`);
  }
  const r = row(UD.running, "the running chat");
  if (r) {
    if (r.dot !== "dot running" || r.bg !== t.ok) fail(`${at}: the running chat has "${r.dot}" in ${r.bg}, not the running dot in --ok-fill (${t.ok})`);
    if (r.name !== `${r.title}Working`) fail(`${at}: the running row reads ${JSON.stringify(r.name)}`);
  }
  const u = row(UD.unread, "the unread chat");
  if (u) udUnread(u, s, theme, fail, `${at}, Pick the test layers`);
  const f = row(UD.failed, "the failed chat");
  if (f) {
    if (f.dot !== "dot failed" || f.bg !== t.danger) fail(`${at}: the failed chat has "${f.dot}" in ${f.bg}, not the failed dot in --danger (${t.danger})`);
    if (f.name !== `Failed, ${f.title}`) fail(`${at}: the failed row reads ${JSON.stringify(f.name)}`);
  }
  for (const id of [UD.waiting, UD.running, UD.unread, UD.failed]) if (s.rows[id] && s.rows[id]!.ariaHidden !== "true") fail(`${at}: a dot is not aria-hidden (${s.rows[id]!.dot})`);
}

/**
 * An unread row: the accent's still dot (glass dark's --ring, paper's ink --text: its clay accent is too near its Failed
 * red), no visible word, "Unread, " read out before its time.
 */
function udUnread(u: UdRow, s: UdLook, theme: Theme, fail: (text: string) => void, at: string) {
  const want = s.look === "glass" && theme === "dark" ? s.tokens.ring : s.look === "paper" ? s.tokens.text : s.tokens.accent;
  if (u.dot !== "dot unread") return fail(`${at}: the row has "${u.dot}", not the unread dot`);
  if (u.bg !== s.tokens.unread || u.bg !== want) fail(`${at}: the unread dot is ${u.bg}, not the look's unread colour (${want})`);
  if (u.anim !== "none") fail(`${at}: the unread dot moves (${u.anim})`);
  if (u.lead !== null) fail(`${at}: the unread row shows the word ${JSON.stringify(u.lead)}`);
  if (u.metaHidden !== "Unread, " || !/Unread, (now|\d+ (min|h|d))$/.test(u.name)) fail(`${at}: the unread row reads ${JSON.stringify(u.name)}, with no "Unread" before its time`);
}

/** The list as a JPEG, and as a PNG: the laptop's sidebar at twice its size, the phone's screen at its own scale. */
async function udShots(page: Page, vp: Viewport, theme: Theme, step: string): Promise<string> {
  const file = shotName("dots", "unseen-dot", vp, theme, step);
  await page.screenshot(file).catch(() => {});
  const box = vp.touch ? null : await page.evaluate<{ x: number; y: number; width: number; height: number } | null>(`(() => { const r = document.querySelector('[data-testid="sidebar"]')?.getBoundingClientRect(); return r ? { x: r.left, y: r.top, width: r.width, height: r.height } : null; })()`);
  const png = await page.send<{ data: string }>("Page.captureScreenshot", { format: "png", ...(box ? { clip: { ...box, scale: 2 } } : {}) }).catch(() => null);
  if (png) await Bun.write(file.replace(/\.jpg$/, ".png"), Buffer.from(png.data, "base64"));
  return file;
}

/**
 * The last run: the two ends that fail with no Stop (FAILS), each on Plan the search index while no page has it on screen
 * (the second page shows the failed chat): the first page's row shows the red dot with its word; opening the chat on
 * the second page clears it.
 */
async function udFails(t: Target, page: Page, pb: Page, vp: Viewport, theme: Theme, at: string, fail: (text: string, code?: string) => void, details: Record<string, unknown>) {
  for (const [text, end] of [
    [FAILS.turn, "turn_end"],
    [FAILS.exit, "exit"],
  ] as const) {
    await pb.navigate(t.base + `/c/${UD.failed}`);
    await waitShown(pb, ["chat", "conversation"]);
    try {
      await serverTurn(t, UD.live, text, 60_000, end);
    } catch (e) {
      return fail(`the message "${text}" could not run: ${(e as Error).message}`, "run");
    }
    const red = await udUntil(page, (s) => s.rows[UD.live]?.dot === "dot failed", 8000);
    details[`fails-${end}`] = red.s.rows[UD.live];
    const r = red.s.rows[UD.live];
    if (!red.ok || !r) {
      fail(`${at}: after "${text}" on Plan the search index, which no page had on screen, its row shows "${r?.dot}", not the failed dot`);
      continue;
    }
    if (r.bg !== red.s.tokens.danger) fail(`${at}: the failed dot after "${text}" is ${r.bg}, not --danger (${red.s.tokens.danger})`);
    if (r.name !== `Failed, ${r.title}`) fail(`${at}: the failed row after "${text}" reads ${JSON.stringify(r.name)}`);
    if (end === "turn_end") await udShots(page, vp, theme, "turn-failed");
    await pb.navigate(t.base + `/c/${UD.live}`);
    await waitShown(pb, ["chat", "conversation"]);
    const seen = await udUntil(page, (s) => !!s.rows[UD.live]?.dot && s.rows[UD.live]!.dot !== "dot failed", 8000);
    if (!seen.ok) fail(`${at}: the failed dot after "${text}" stays on the first page after the second page opened the chat`);
  }
}

/**
 * The last run: a link far above the end of an unread chat. The view stays at the linked message, so the chat is not
 * seen (the second page's row keeps its unread dot and the first page sends no on); Jump to latest shows, and
 * pressing it brings the end on screen, which clears the dot.
 */
async function udLink(t: Target, page: Page, wire: Wire, pb: Page, vp: Viewport, theme: Theme, other: Viewport, at: string, fail: (text: string, code?: string) => void, details: Record<string, unknown>) {
  await pb.navigate(t.base + (other.touch ? "/chats" : "/"));
  await waitShown(pb, [other.touch ? "chat-list" : "sidebar"]);
  try {
    await serverTurn(t, UD.live, UD_FIRST, 60_000);
  } catch (e) {
    return fail(`the turn on Plan the search index could not run: ${(e as Error).message}`, "run");
  }
  const unread = await udUntil(pb, (s) => s.rows[UD.live]?.dot === "dot unread", 8000);
  if (!unread.ok) return fail(`${at}: before the link, Plan the search index shows "${unread.s.rows[UD.live]?.dot}" on the second page, not the unread dot`);
  const mark = wire.mark();
  await page.navigate(t.base + `/c/${UD.live}/m/${UD_FIRST_MESSAGE}`);
  await waitShown(page, ["chat", "conversation"]);
  const end = Date.now() + 5000;
  let v = await page.evaluate<{ jump: boolean; gap: number | null; linked: boolean }>(UD_JUMP);
  while (!v.jump && Date.now() < end) {
    await sleep(100);
    v = await page.evaluate<{ jump: boolean; gap: number | null; linked: boolean }>(UD_JUMP);
  }
  details.link = v;
  if (!v.linked) return fail(`${at}: the link to Plan the search index's first message drew no such message`);
  if (v.gap === null || v.gap < 300) return fail(`${at}: the linked message is only ${v.gap} px from the end, too near it for this check`);
  await sleep(1500);
  const kept = await udUntil(pb, (s) => s.rows[UD.live]?.dot === "dot unread", 1000);
  if (!kept.ok) fail(`${at}: the link far above the end cleared the unread dot on the second page (it shows "${kept.s.rows[UD.live]?.dot}")`);
  if (wire.framesSince(mark).some((f) => f.t === "on_screen" && f.frame.chat === UD.live && f.frame.on === true)) fail(`${at}: the page at the linked message said the chat is on screen`);
  await page.screenshot(shotName("dots", "unseen-dot", vp, theme, "link")).catch(() => {});
  if (!v.jump) return fail(`${at}: at a linked message ${v.gap} px above the end of an unread chat, no Jump to latest shows`);
  const button = await page.locate(".chat-jump");
  if (!button) return fail(`${at}: Jump to latest could not be found to press`);
  await page.press(button.x, button.y);
  const seen = await udUntil(pb, (s) => !!s.rows[UD.live]?.dot && s.rows[UD.live]!.dot !== "dot unread", 8000);
  details.afterJump = seen.s.rows[UD.live];
  if (!seen.ok) fail(`${at}: Jump to latest did not clear the unread dot on the second page`);
  if (!wire.framesSince(mark).some((f) => f.t === "on_screen" && f.frame.chat === UD.live && f.frame.on === true)) fail(`${at}: after Jump to latest the page sent no on_screen for the chat`);
}

async function unseenDotRun(b: Booted, vp: Viewport, theme: Theme, look: P2LookId, other: Viewport, last: boolean): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = { look };
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const t: Target = { base: b.base, scene: null, booted: b };
  const listPath = vp.touch ? "/chats" : "/";
  const tag = look === "glass" ? "" : `-${look}`;
  const at = `${vp.width}x${vp.height} ${theme}${look === "glass" ? "" : `, ${look}`}`;
  let shot: string | undefined;
  try {
    await withPage(vp, theme, async (page, wire) => {
      await page.navigate(b.base + listPath);
      await waitShown(page, [vp.touch ? "chat-list" : "sidebar"]);
      if (look !== "glass") await wearLook(page, look, theme);
      const four = await udUntil(page, (s) => [UD.waiting, UD.running, UD.unread, UD.failed].every((id) => !!s.rows[id]?.dot), 8000);
      details.list = four.s;
      udFourDots(four.s, theme, false, fail, at);
      shot = await udShots(page, vp, theme, `list${tag}`);

      // Reduce motion: the system's, then Settings' On (the root's data-motion), each stops the pulse.
      await page.send("Emulation.setEmulatedMedia", { media: "screen", features: [{ name: "prefers-color-scheme", value: theme }, { name: "prefers-reduced-motion", value: "reduce" }] });
      await page.evaluate(P2_DRAWN);
      udFourDots(await page.evaluate<UdLook>(UD_PROBE), theme, true, fail, `${at}, the system's Reduce motion`);
      await page.send("Emulation.setEmulatedMedia", { media: "screen", features: [{ name: "prefers-color-scheme", value: theme }] });
      await page.evaluate(`(() => { document.documentElement.dataset.motion = "reduce"; return true; })()`);
      await page.evaluate(P2_DRAWN);
      udFourDots(await page.evaluate<UdLook>(UD_PROBE), theme, true, fail, `${at}, Settings' Reduce motion On`);
      await page.evaluate(`(() => { delete document.documentElement.dataset.motion; return true; })()`);
      await page.evaluate(P2_DRAWN);

      // On the laptop a folded heading counts its chats that need input, and only those (Pick the test layers, unread,
      // is in the same group).
      if (!vp.touch && look === "glass") {
        const fold = await page.locate('button.scr-fold[aria-label="Chats in kitespan"]');
        if (!fold) fail(`${at}: the kitespan heading has no fold button`);
        else {
          await page.press(fold.x, fold.y);
          const folded = await udUntil(page, (s) => s.badge.length > 0, 3000);
          details.badge = folded.s.badge;
          if (folded.s.badge.join(" | ") !== "1 needs input") fail(`${at}: the folded kitespan heading shows ${JSON.stringify(folded.s.badge)}, not one chat that needs input`);
          await page.press(fold.x, fold.y);
          await udUntil(page, (s) => !!s.rows[UD.unread], 3000);
        }
      }

      // A turn ends on a chat that no page has open: its row's dot shows in the accent.
      try {
        await serverTurn(t, UD.live, UD_FIRST, 60_000);
      } catch (e) {
        return fail(`the turn on Plan the search index could not run: ${(e as Error).message}`, "run");
      }
      const ended = await udUntil(page, (s) => s.rows[UD.live]?.dot === "dot unread", 8000);
      details.afterTurn = ended.s.rows[UD.live];
      if (!ended.ok) return fail(`${at}: after a turn ended on Plan the search index, which no page had open, its row shows "${ended.s.rows[UD.live]?.dot}", not the unread dot`);
      udUnread(ended.s.rows[UD.live]!, ended.s, theme, fail, `${at}, Plan the search index`);
      await udShots(page, vp, theme, `turn-ended${tag}`);

      // A second page opens it: it says so (on_screen, not an action), and the first page's dot goes.
      await withPage(other, theme, async (pb, wb) => {
        const mark = wb.mark();
        await pb.navigate(b.base + `/c/${UD.live}`);
        await waitShown(pb, ["chat", "conversation"]);
        const seen = await udUntil(page, (s) => !!s.rows[UD.live]?.dot && s.rows[UD.live]!.dot !== "dot unread", 8000);
        details.afterOpen = seen.s.rows[UD.live];
        if (!seen.ok) fail(`${at}: the unread dot stays on the first page after the second page (${other.width}x${other.height}) opened the chat`);
        const frames = wb.framesSince(mark);
        details.secondPage = frames.map(frameText);
        if (!frames.some((f) => f.t === "on_screen" && f.frame.chat === UD.live && f.frame.on === true)) fail(`${at}: the second page sent no on_screen for the chat (${clipList(frames.map(frameText))})`);
        const acts = acting(frames);
        if (acts.length) fail(`${at}: opening the chat on the second page sent ${clipList(acts.map(frameText))}`, "frames");
        const posts = wb.httpSince(mark).filter((h) => MUTATING_METHODS.has(h.method));
        if (posts.length) fail(`${at}: opening the chat on the second page sent ${clipList(posts.map(httpText))}`, "frames");
        const rec = await recorder(pb);
        if (rec?.length) fail(`${at}: the second page recorded ${clipList(rec)} with no click`, "recorder");

        // A turn that ends while the chat is on screen there is seen at once: the first page never shows the dot.
        const dots: (string | null)[] = [];
        let done = false;
        const turn = serverTurn(t, UD.live, UD_AGAIN, 60_000).then(
          () => null,
          (e: Error) => e.message,
        );
        void turn.then(() => (done = true));
        while (!done) {
          dots.push(await page.evaluate<string | null>(udDot(UD.live)));
          await sleep(100);
        }
        const why = await turn;
        if (why) fail(`the second turn on Plan the search index could not run: ${why}`, "run");
        const settleEnd = Date.now() + 1500;
        while (Date.now() < settleEnd) {
          dots.push(await page.evaluate<string | null>(udDot(UD.live)));
          await sleep(100);
        }
        details.whileOnScreen = [...new Set(dots)];
        if (dots.includes("dot unread")) fail(`${at}: a turn that ended while the second page showed the chat at its end showed the unread dot on the first page`);
        await pb.screenshot(shotName("dots", "unseen-dot", other, theme, `second-page${tag}`)).catch(() => {});

        // The last run: the failed chat opened on the second page loses its red dot on the first.
        if (last) {
          await pb.navigate(b.base + `/c/${UD.failed}`);
          await waitShown(pb, ["chat", "conversation"]);
          const gone = await udUntil(page, (s) => !!s.rows[UD.failed]?.dot && s.rows[UD.failed]!.dot !== "dot failed", 8000);
          details.failedOpened = gone.s.rows[UD.failed];
          if (!gone.ok) fail(`${at}: the failed dot stays on the first page after the second page opened the chat`);
          else if (gone.s.rows[UD.failed]!.name.startsWith("Failed")) fail(`${at}: the seen failed chat still reads ${JSON.stringify(gone.s.rows[UD.failed]!.name)}`);
          await udFails(t, page, pb, vp, theme, at, fail, details);
          await udLink(t, page, wire, pb, vp, theme, other, at, fail, details);
        }
        issueFindings(pb.takeIssues(), failures, "the second page: ");
      });

      issueFindings(page.takeIssues(), failures);
      const acts = acting(wire.framesSince(0));
      if (acts.length) fail(`${at}: the list's page sent ${clipList(acts.map(frameText))}`, "frames");
      const rec = await recorder(page);
      if (rec?.length) fail(`${at}: the list's page recorded ${clipList(rec)} with no click`, "recorder");
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return finish({ kind: "flow", name: "unseen-dot", route: "chats", scene: "dots", size: sizeTag(vp), theme, path: listPath, failures, warnings, note: look === "glass" ? "" : `the ${look} look`, ms: Date.now() - t0, details, shot });
}

/** Row 116's runs on one seed of the dots scene (none with --base): the laptop's, each look's, then the phone's. */
async function unseenDotFlows(record: (r: CheckResult) => void, problems: string[]): Promise<void> {
  if (BASE) {
    console.log("ui-check: unseen-dot boots a seed of its own (the dots scene), so --base runs none of it");
    return;
  }
  const laptop = CORE.some((v) => v.name === "laptop") ? WIDE_LAPTOP : null;
  const phone = CORE.find((v) => v.name === "phone") ?? null;
  const otherPhone = VIEWPORTS.find((v) => v.name === "phone")!;
  const runs: { vp: Viewport; theme: Theme; look: P2LookId; other: Viewport }[] = [];
  if (laptop) for (const theme of THEMES) runs.push({ vp: laptop, theme, look: "glass", other: otherPhone });
  if (laptop) for (const theme of THEMES) for (const look of P2_LOOKS.filter((l) => l !== "glass")) runs.push({ vp: laptop, theme, look, other: otherPhone });
  if (phone) for (const theme of THEMES) runs.push({ vp: phone, theme, look: "glass", other: WIDE_LAPTOP });
  for (const vp of extraAt("unseen-dot")) runs.push({ vp, theme: THEMES[0]!, look: "glass", other: WIDE_LAPTOP });
  if (!runs.length || cdp.closed) return;
  let b: Booted;
  try {
    b = await boot({ scene: "dots", port: PORT, dist: built!, keep: KEEP, env: SERVER_ENV });
  } catch (e) {
    for (const r of runs) record(finish({ kind: "flow", name: "unseen-dot", route: "chats", scene: "dots", size: sizeTag(r.vp), theme: r.theme, path: r.vp.touch ? "/chats" : "/", failures: [{ code: "seed", text: `the seed did not boot: ${(e as Error).message}` }], warnings: [], note: "", ms: 0, details: {} }));
    return;
  }
  live.add(b);
  try {
    for (const [i, r] of runs.entries()) {
      if (cdp.closed) break;
      record(await unseenDotRun(b, r.vp, r.theme, r.look, r.other, i === runs.length - 1));
    }
  } finally {
    const r = await b.stop();
    live.delete(b);
    if (r.code !== 0) problems.push(`scene dots: the server exited with ${r.code}`);
    if (r.leftovers.length) problems.push(`scene dots: ${r.leftovers.length} process(es) outlived the server and were ended by pid`);
  }
}

// ---------------------------------------------------------------------------------------------------------------
// R124 (owner rows 124 and 125): the side chat. side-chat runs on one seed of the side scene (the example chat with
// two kept side questions, seed/side.ts; the fake claude answers each side question by its text, seed/fixture.ts
// SIDE): at 1280x800 and at 390x844 with touch, dark and light, and at 1280x800 light in each other look. Each run opens
// the side chat by its visible control (the title bar's Side chat on the laptop, the session menu's on the phone; only
// `get` frames go out), shows the kept thread (earlier questions folded, the newest open), asks, follows up (the answer
// names the question before it, which it read in the history), asks one that never answers and stops it (one
// side_stop; the question comes back in the box), closes it (Esc on the laptop with the focus back on its opener, Done
// on the phone) and opens it again with the thread kept, then opens a link that only fills the box (nothing goes out,
// "Prompt from an external link" under it) and sends it, and clears the thread (one side_clear). No `send` frame ever
// goes, and the transcript never holds a side question or answer. The first laptop run also checks the key (Ctrl+;
// here), the message box's /btw (the / menu's row, then one side_question and no send), and the other states (a
// failure with Try again under the same id, a refusal fallback's notice, the retry line, an empty answer); the phone's
// light run closes the sheet by a drag down on its grip (a short drag first, which settles back with a transition), the
// dark run with Reduce motion, where the sheet does not follow the finger. On the phone, with the stand-in keyboard
// (336 px) up and the focus in the side box, the sheet rides it at most half the visual viewport high, so part of the
// chat stays in view; and on touch Clear leaves the focus out of the side box (no keyboard comes up), while on the
// laptop it puts the focus there. side-chat-running asks while a main turn runs a long Bash call (1280x800 and 390x844, light): the
// side answer lands while the turn still runs, the fake claude saw the question during the turn, nothing interrupted
// the turn, and when the turn ends the transcript holds its own reply and none of the side chat.

const SC_CHAT = EX.chat;
const SC_SIDE = {
  kept: ["What does the retry rule do?", "Which file holds the size cap?"],
  ask: "Why did the second test time out?",
  followUp: "Where should the listener go, then?",
  link: "Which file holds the cap?",
  slow: "Walk me through every retry, one at a time.",
  retry: "Is the upload server up again?",
  fail: "Which branch has the fix?",
  fallback: "Could the fix break the push command?",
  fallbackNotice: "Opus 5.5 declined to answer, so Sonnet 5.5 answered this question.",
  synthetic: "What did the subagent find?",
  syntheticAnswer: "(No answer available for this side question. Try again, or ask in the main conversation.)",
  empty: "Answer with nothing at all.",
  askAnswer: "The second test waits for the",
  linkAnswer: "MAX_UPLOAD_BYTES",
  longBash: "Run the send-now check's long command.",
  longBashStart: "Running the long command now.",
  longBashEnd: "I read your new message, and I'll do that next.",
} as const;

interface ScState {
  place: string | null;
  path: string;
  earlier: string[];
  newest: string | null;
  state: string | null;
  answer: string | null;
  asking: boolean;
  failed: boolean;
  again: boolean;
  retry: string | null;
  note: string | null;
  copy: boolean;
  box: string | null;
  boxFocused: boolean;
  stop: boolean;
  sendOff: boolean | null;
  clear: boolean;
  linkLine: boolean;
  focus: string;
  rect: { top: number; bottom: number; height: number } | null;
  conversation: string;
  composerStop: boolean;
}

const SC_PROBE = `(() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && !el.closest('[hidden="until-found"]');
  const fold = (s) => (s || "").replace(/\\s+/g, " ").trim();
  const conv = [...document.querySelectorAll('[data-testid="conversation"]')].find(shown);
  const a = document.activeElement;
  const focus = !a || a === document.body ? "body" : (a.getAttribute("data-testid") || a.getAttribute("aria-label") || a.tagName.toLowerCase());
  const base = { path: location.pathname + location.search, conversation: fold(conv ? conv.textContent : ""), focus, composerStop: !![...document.querySelectorAll('[data-testid="composer-stop"]')].find(shown) };
  const root = [...document.querySelectorAll('[data-testid="side-chat"]')].find(shown);
  if (!root) return { place: null, earlier: [], newest: null, state: null, answer: null, asking: false, failed: false, again: false, retry: null, note: null, copy: false, box: null, boxFocused: false, stop: false, sendOff: null, clear: false, linkLine: false, rect: null, ...base };
  const q = (s) => [...root.querySelectorAll(s)].filter(shown);
  const newest = root.querySelector('[data-testid="side-newest"]');
  const answers = q('[data-testid="side-answer"]');
  const box = root.querySelector('[data-testid="side-input"]');
  const send = root.querySelector('[data-testid="side-send"]');
  const r = root.getBoundingClientRect();
  return {
    ...base,
    place: root.getAttribute("data-place"),
    earlier: q('[data-testid="side-earlier"] > .sc-q .sc-q-text').map((e) => fold(e.textContent)),
    newest: newest ? fold(newest.querySelector(".sc-q-text").textContent) : null,
    state: newest ? newest.getAttribute("data-state") : null,
    answer: answers.length ? fold(answers[answers.length - 1].textContent) : null,
    asking: q('[data-testid="side-asking"]').length > 0,
    failed: q('[data-testid="side-failed"]').length > 0,
    again: q('[data-testid="side-again"]').length > 0,
    retry: q(".sc-retry").length ? fold(q(".sc-retry")[0].textContent) : null,
    note: q(".sc-note").length ? fold(q(".sc-note")[0].textContent) : null,
    copy: q('[data-testid="side-copy"]').length > 0,
    box: box ? box.value : null,
    boxFocused: !!box && a === box,
    stop: q('[data-testid="side-stop"]').length > 0,
    sendOff: send ? send.disabled : null,
    clear: q('[data-testid="side-clear"]').length > 0,
    linkLine: q('[data-testid="external-link-line"]').length > 0,
    rect: { top: Math.round(r.top), bottom: Math.round(r.bottom), height: Math.round(r.height) },
  };
})()`;

async function scUntil(page: Page, ok: (s: ScState) => boolean, ms: number): Promise<{ ok: boolean; s: ScState }> {
  const end = Date.now() + ms;
  let s = await page.evaluate<ScState>(SC_PROBE);
  while (!ok(s) && Date.now() < end) {
    await sleep(100);
    s = await page.evaluate<ScState>(SC_PROBE);
  }
  return { ok: ok(s), s };
}

/** Press the first shown element for a selector; false when none shows. */
async function scPress(page: Page, selector: string): Promise<boolean> {
  const at = await page.locate(selector);
  if (!at) return false;
  await page.press(at.x, at.y);
  await sleep(60);
  return true;
}

/** Type into the side box as a user does: a press on the field, then the text (no key events), then Send. */
async function scAsk(page: Page, vp: Viewport, text: string): Promise<boolean> {
  if (!(await scPress(page, '[data-testid="side-chat"] [data-testid="side-input"]'))) return false;
  await page.evaluate(`(() => { const f = [...document.querySelectorAll('[data-testid="side-input"]')].find((e) => e.getClientRects().length); f.select(); return true; })()`);
  await page.send("Input.insertText", { text });
  await sleep(50);
  if (vp.touch) return scPress(page, '[data-testid="side-chat"] [data-testid="side-send"]');
  await page.key("Enter");
  return true;
}

/** Ctrl+; (Cmd+; on macOS, where this check never runs): Desktop's Open side chat. */
async function scSideKey(page: Page) {
  const base = { key: ";", code: "Semicolon", windowsVirtualKeyCode: 186, nativeVirtualKeyCode: 186, modifiers: 2 };
  await page.send("Input.dispatchKeyEvent", { type: "rawKeyDown", ...base });
  await page.send("Input.dispatchKeyEvent", { type: "keyUp", ...base });
}

/** Open the side chat by its visible control: the title bar's Side chat, or the phone's session menu item. */
async function scOpen(page: Page, vp: Viewport): Promise<boolean> {
  // The tablet's pane bar; v0.6 touch: the large tablet's too (the laptop's layout, a pane bar on touch).
  if (vp.name === "medium" || (vp.touch && vp.name === "laptop")) return scPress(page, `nav.pane-bar a[href="/c/${SC_CHAT}/btw"]`);
  if (vp.name !== "phone") return scPress(page, 'header a[aria-label="Side chat"]');
  if (!(await scPress(page, 'header button[aria-label="Session menu"]'))) return false;
  await sleep(300);
  return scPress(page, `[data-testid="session-menu"] a[href="/c/${SC_CHAT}/btw"]`);
}

const scFrames = (wire: Wire, mark: number, t: string) => wire.framesSince(mark).filter((f) => f.t === t);

async function scShot(page: Page, vp: Viewport, theme: Theme, step: string): Promise<string> {
  const file = shotName("side", "side-chat", vp, theme, step);
  await page.evaluate(P2_DRAWN).catch(() => {});
  await page.screenshot(file).catch(() => {});
  return file;
}

/** The transcript never holds a side question or answer. */
function scClean(s: ScState, fail: (text: string) => void, at: string) {
  for (const words of [SC_SIDE.ask, SC_SIDE.followUp, SC_SIDE.link, SC_SIDE.askAnswer, SC_SIDE.linkAnswer, ...SC_SIDE.kept])
    if (s.conversation.includes(words)) fail(`${at}: the transcript holds the side chat's "${words}"`);
}

async function sideChatRun(b: Booted, vp: Viewport, theme: Theme, look: P2LookId, extra: { states: boolean; drag: "motion" | "reduce" | null }): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = { look };
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const tag = look === "glass" ? "" : `-${look}`;
  const at = `${vp.width}x${vp.height} ${theme}${look === "glass" ? "" : `, ${look}`}`;
  const chatPath = `/c/${SC_CHAT}`;
  const sidePath = `${chatPath}/btw`;
  const wantPlace = vp.name === "phone" ? "sheet" : vp.name === "medium" ? "pane" : vp.touch && vp.height > vp.width ? "over" : "column";
  let shot: string | undefined;
  try {
    await withPage(vp, theme, async (page, wire) => {
      if (vp.name === "phone") await page.send("Page.addScriptToEvaluateOnNewDocument", { source: STAND_IN_KEYBOARD });
      await page.navigate(b.base + chatPath);
      await waitShown(page, ["chat", "conversation"], 8000);
      if (look !== "glass") await wearLook(page, look, theme);

      // Open by the visible control: only reads go out.
      let mark = wire.mark();
      if (!(await scOpen(page, vp))) return fail(`${at}: the side chat's control could not be found to press`);
      // The first run finds the seed's kept thread; the others the empty thread that the run before cleared.
      const opened = await scUntil(page, (s) => s.place === wantPlace && (!extra.states || s.newest !== null), 6000);
      details.opened = opened.s;
      if (!opened.ok) return fail(`${at}: the side chat did not open in its ${wantPlace}${extra.states ? " with its kept thread" : ""} (${JSON.stringify(opened.s.place)}, ${opened.s.path})`);
      if (opened.s.path !== sidePath) fail(`${at}: the side chat opened at ${opened.s.path}, not ${sidePath}`);
      const acts = acting(wire.framesSince(mark));
      if (acts.length) fail(`${at}: opening the side chat sent ${clipList(acts.map(frameText))}`, "frames");
      if (!scFrames(wire, mark, "get").some((f) => f.frame.what === "side" && f.frame.chat === SC_CHAT)) fail(`${at}: opening the side chat read no side thread (get side)`);
      if (!vp.touch && !opened.s.boxFocused) fail(`${at}: on the laptop the side box has no first focus (${opened.s.focus})`);
      if (vp.touch && opened.s.boxFocused) fail(`${at}: on touch the side box took the focus as the side chat opened`);
      if (extra.states) {
        // The seed's kept thread: two earlier questions, the newest open.
        if (opened.s.newest !== SC_SIDE.kept[1] || opened.s.earlier.join(" | ") !== SC_SIDE.kept[0]) fail(`${at}: the kept thread shows ${JSON.stringify([...opened.s.earlier, opened.s.newest])}, not the seed's two questions`);
        await scShot(page, vp, theme, `kept${tag}`);
      }
      if (vp.name === "phone" && opened.s.rect && opened.s.rect.height > vp.height / 2 + 2) fail(`${at}: the side sheet is ${opened.s.rect.height} px high, over half the screen`);

      // Ask, then follow up: the follow-up's answer names the question before it (it read the history).
      mark = wire.mark();
      if (!(await scAsk(page, vp, SC_SIDE.ask))) return fail(`${at}: the side box could not be typed in`);
      const asking = await scUntil(page, (s) => s.newest === SC_SIDE.ask && (s.asking || s.state === "answered"), 3000);
      if (!asking.ok) fail(`${at}: the asked question does not show at once (${JSON.stringify(asking.s.newest)})`);
      const answered = await scUntil(page, (s) => s.newest === SC_SIDE.ask && s.state === "answered" && !!s.answer?.includes(SC_SIDE.askAnswer), 10_000);
      details.answered = answered.s;
      if (!answered.ok) fail(`${at}: no answer to the side question (${answered.s.state}, ${JSON.stringify(answered.s.answer)})`);
      const asks = scFrames(wire, mark, "side_question");
      if (asks.length !== 1 || asks[0]!.frame.text !== SC_SIDE.ask || asks[0]!.frame.chat !== SC_CHAT) fail(`${at}: Send sent ${asks.length} side_question frame(s) (${clipList(asks.map((f) => String(f.frame.text)))})`);
      if (answered.s.box !== "") fail(`${at}: the side box holds ${JSON.stringify(answered.s.box)} after Send`);
      if (!answered.s.copy) fail(`${at}: the answer has no Copy`);
      mark = wire.mark();
      await scAsk(page, vp, SC_SIDE.followUp);
      const follow = await scUntil(page, (s) => s.newest === SC_SIDE.followUp && s.state === "answered" && !!s.answer?.includes(SC_SIDE.ask), 10_000);
      details.followUp = follow.s;
      if (!follow.ok) fail(`${at}: the follow-up's answer does not name the question before it, so it read no history (${JSON.stringify(follow.s.answer)})`);
      if (!follow.s.earlier.includes(SC_SIDE.ask)) fail(`${at}: the earlier question is not one folded line above the newest (${JSON.stringify(follow.s.earlier)})`);
      shot = await scShot(page, vp, theme, `answered${tag}`);
      scClean(follow.s, fail, at);

      // R130 Bring back: the answer goes into the message box's draft as a quote, in one draft frame, and nothing is
      // sent; the side chat stays beside the chat, and the phone's sheet closes so the box shows (then it opens again
      // for the steps below). The box is emptied again after.
      mark = wire.mark();
      if (!(await scPress(page, '[data-testid="side-chat"] [data-testid="side-newest"] [data-testid="side-bring-back"]'))) fail(`${at}: Bring back could not be found to press`);
      else {
        // The phone's sheet and (v0.6 touch) the large tablet's layer over the chat close, so the box shows.
        const closes = vp.name === "phone" || wantPlace === "over";
        const brought = await scUntil(page, (s) => (closes ? s.place === null && s.path === chatPath : s.place === wantPlace), 4000);
        await sleep(600);
        const drafts = scFrames(wire, mark, "draft").filter((f) => f.frame.box !== "side");
        const text = String(drafts[0]?.frame.text ?? "");
        details.bringBack = { drafts: drafts.length, text: clip(text, 80), place: brought.s.place, path: brought.s.path };
        if (drafts.length !== 1 || !text.startsWith("> Right after") || !text.endsWith("\n\n")) fail(`${at}: Bring back sent ${drafts.length} draft frame(s) of the message box (${JSON.stringify(clip(text, 80))}), not one with the answer as a quote`);
        if (wire.framesSince(mark).some((f) => f.t === "send" || f.t === "side_question")) fail(`${at}: Bring back sent a send or a side_question`, "frames");
        if (!brought.ok) fail(`${at}: after Bring back the side chat is ${brought.s.place ?? "closed"} at ${brought.s.path}`);
        await scShot(page, vp, theme, `bring-back${tag}`);
        await page.evaluate(`(() => { const f = document.querySelector('[data-testid="composer-input"]'); if (!f) return false; const set = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, "value").set; set.call(f, ""); f.dispatchEvent(new Event("input", { bubbles: true })); return true; })()`);
        await sleep(400);
        if (closes) {
          await scOpen(page, vp);
          await scUntil(page, (s) => s.place === wantPlace, 6000);
          // The sheet rises in: the steps below tap inside it once it stands still.
          await page.evaluate(`Promise.all(document.getAnimations().map((a) => a.finished.catch(() => null))).then(() => true)`);
          await sleep(300);
        }
      }

      if (vp.name === "phone") {
        // The on-screen keyboard (the stand-in, 336 px) with the focus in the side box: the sheet rides it, at most
        // half the visual viewport high, so part of the chat stays in view above it, and the box ends above it.
        await scPress(page, '[data-testid="side-chat"] [data-testid="side-input"]');
        await page.evaluate("window.__standInKeyboard(336)");
        await sleep(400);
        const kb = await page.evaluate<{ visual: number; sheet: [number, number] | null; field: [number, number] | null; focus: boolean }>(`(() => {
          const shown = (el) => !!el && el.getClientRects().length > 0 && !el.closest('[hidden="until-found"]');
          const sheet = [...document.querySelectorAll('[data-testid="side-chat"][data-place="sheet"]')].find(shown);
          const field = sheet ? sheet.querySelector('[data-testid="side-input"]') : null;
          const r = (el) => { if (!el) return null; const b = el.getBoundingClientRect(); return [Math.round(b.top), Math.round(b.bottom)]; };
          return { visual: Math.round(visualViewport.height), sheet: r(sheet), field: r(field), focus: !!field && document.activeElement === field };
        })()`);
        details.keyboard = kb;
        if (!kb.focus) fail(`${at}: a tap in the side box gave it no focus (keyboard check)`);
        else if (!kb.sheet || !kb.field) fail(`${at}: with the keyboard up the side sheet or its box does not show`, "keyboard");
        else {
          if (kb.field[1] > kb.visual + 1) fail(`${at}: with the keyboard up the side box ends at ${kb.field[1]} px, under the keyboard at ${kb.visual} px`, "keyboard");
          if (kb.sheet[1] - kb.sheet[0] > Math.round(kb.visual / 2) + 2) fail(`${at}: riding the keyboard the side sheet is ${kb.sheet[1] - kb.sheet[0]} px high, over half the visual viewport (${kb.visual} px), so too little of the chat shows`, "keyboard");
          if (kb.sheet[0] < 44) fail(`${at}: riding the keyboard the side sheet's top is at ${kb.sheet[0]} px, over the title bar`, "keyboard");
        }
        await scShot(page, vp, theme, `keyboard${tag}`);
        await page.evaluate("window.__standInKeyboard(0)");
        await page.evaluate("document.activeElement && document.activeElement.blur && document.activeElement.blur()");
        await sleep(300);
      }

      // A question that never answers: Stop sends one side_stop, the question leaves and comes back in the box.
      mark = wire.mark();
      await scAsk(page, vp, SC_SIDE.slow);
      const slow = await scUntil(page, (s) => s.newest === SC_SIDE.slow && s.asking && s.stop, 4000);
      details.slow = slow.s;
      if (!slow.ok) fail(`${at}: the running side question shows no working mark and Stop (${JSON.stringify({ asking: slow.s.asking, stop: slow.s.stop })})`);
      else if (slow.s.clear) fail(`${at}: Clear shows while a side question runs`);
      await scShot(page, vp, theme, `asking${tag}`);
      if (!(await scPress(page, '[data-testid="side-chat"] [data-testid="side-stop"]'))) fail(`${at}: Stop could not be found to press`);
      const stopped = await scUntil(page, (s) => s.newest === SC_SIDE.followUp && !s.asking && s.box === SC_SIDE.slow, 6000);
      details.stopped = stopped.s;
      if (!stopped.ok) fail(`${at}: after Stop the thread or the box is not as it was (${JSON.stringify({ newest: stopped.s.newest, asking: stopped.s.asking, box: stopped.s.box })})`);
      const stops = scFrames(wire, mark, "side_stop");
      if (stops.length !== 1) fail(`${at}: Stop sent ${stops.length} side_stop frame(s)`);
      await page.evaluate(`(() => { const f = [...document.querySelectorAll('[data-testid="side-input"]')].find((e) => e.getClientRects().length); const set = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, "value").set; set.call(f, ""); f.dispatchEvent(new Event("input", { bubbles: true })); return true; })()`);

      if (extra.states) {
        // The other states: a failure (Try again asks the same id), a refusal fallback, the retry line, an empty answer.
        mark = wire.mark();
        await scAsk(page, vp, SC_SIDE.fail);
        const failed = await scUntil(page, (s) => s.newest === SC_SIDE.fail && s.failed && s.again, 8000);
        if (!failed.ok) fail(`${at}: a failed side question shows no failure line with Try again`);
        await scShot(page, vp, theme, `failed${tag}`);
        await scPress(page, '[data-testid="side-chat"] [data-testid="side-again"]');
        await scUntil(page, (s) => s.newest === SC_SIDE.fail && s.failed, 8000);
        const tries = scFrames(wire, mark, "side_question");
        if (tries.length !== 2 || tries[0]!.frame.id !== tries[1]!.frame.id || tries[0]!.rid === tries[1]!.rid) fail(`${at}: Try again did not ask the same id with a new rid (${tries.length} frames)`);
        await scAsk(page, vp, SC_SIDE.fallback);
        const fb = await scUntil(page, (s) => s.newest === SC_SIDE.fallback && s.state === "answered", 8000);
        if (fb.s.note !== SC_SIDE.fallbackNotice) fail(`${at}: the refusal fallback's notice reads ${JSON.stringify(fb.s.note)}`);
        await scShot(page, vp, theme, `fallback${tag}`);
        await scAsk(page, vp, SC_SIDE.retry);
        const retry = await scUntil(page, (s) => s.newest === SC_SIDE.retry && s.retry === "Retrying (2 of 10) in 4 s", 8000);
        details.retry = retry.s.retry;
        if (!retry.ok) fail(`${at}: the retry line reads ${JSON.stringify(retry.s.retry)}, not "Retrying (2 of 10) in 4 s"`);
        else await scShot(page, vp, theme, `retry${tag}`);
        await scUntil(page, (s) => s.newest === SC_SIDE.retry && s.state === "answered", 12_000);
        await scAsk(page, vp, SC_SIDE.empty);
        const empty = await scUntil(page, (s) => s.newest === SC_SIDE.empty && s.state === "answered", 8000);
        if (!empty.ok || empty.s.answer !== null || empty.s.copy) fail(`${at}: an empty answer shows ${JSON.stringify(empty.s.answer)}${empty.s.copy ? " with Copy" : ""}`);
      }

      // Close (Esc, the focus back on the title bar's tool; Done on the phone), and open again: the thread is kept.
      const before = (await page.evaluate<ScState>(SC_PROBE)).newest;
      if (vp.name === "phone") {
        if (extra.drag) {
          if (extra.drag === "reduce") await page.send("Emulation.setEmulatedMedia", { media: "screen", features: [{ name: "prefers-color-scheme", value: theme }, { name: "prefers-reduced-motion", value: "reduce" }] });
          const grip = await page.locate('[data-testid="side-grip"]');
          if (grip && extra.drag === "motion") {
            // A short drag that does not close: the sheet settles back with a transition of its translate.
            await page.send("Input.dispatchTouchEvent", { type: "touchStart", touchPoints: [{ x: grip.x, y: grip.y, radiusX: 4, radiusY: 4, force: 1 }] });
            for (const dy of [12, 24, 36]) {
              await page.send("Input.dispatchTouchEvent", { type: "touchMove", touchPoints: [{ x: grip.x, y: grip.y + dy, radiusX: 4, radiusY: 4, force: 1 }] });
              await sleep(80);
            }
            await page.send("Input.dispatchTouchEvent", { type: "touchEnd", touchPoints: [] });
            const settling = await page.evaluate<string[]>(`(() => { const s = document.querySelector('[data-testid="side-chat"][data-place="sheet"]'); return s ? s.getAnimations().map((a) => a.transitionProperty || a.animationName || "?") : ["gone"]; })()`);
            details.settle = settling;
            if (!settling.includes("translate")) fail(`${at}: a short drag that does not close snaps back with no transition (${JSON.stringify(settling)})`);
            await sleep(400);
            if (!(await scUntil(page, (s) => s.place === "sheet", 1000)).ok) fail(`${at}: a short drag on the grip closed the sheet`);
          }
          if (!grip) fail(`${at}: the sheet's grip could not be found`);
          else {
            const moved: string[] = [];
            await page.send("Input.dispatchTouchEvent", { type: "touchStart", touchPoints: [{ x: grip.x, y: grip.y, radiusX: 4, radiusY: 4, force: 1 }] });
            for (const dy of [20, 50, 90, 120]) {
              await page.send("Input.dispatchTouchEvent", { type: "touchMove", touchPoints: [{ x: grip.x, y: grip.y + dy, radiusX: 4, radiusY: 4, force: 1 }] });
              await sleep(60);
              moved.push(await page.evaluate<string>(`(() => { const s = document.querySelector('[data-testid="side-chat"][data-place="sheet"]'); return s ? s.style.translate : "gone"; })()`));
            }
            await page.send("Input.dispatchTouchEvent", { type: "touchEnd", touchPoints: [] });
            details.drag = moved;
            if (extra.drag === "motion" && !moved.some((m) => /px/.test(m))) fail(`${at}: the sheet does not follow the finger (${JSON.stringify(moved)})`);
            if (extra.drag === "reduce" && moved.some((m) => /px/.test(m))) fail(`${at}: with Reduce motion the sheet follows the finger (${JSON.stringify(moved)})`);
          }
        } else await scPress(page, '[data-testid="side-chat"] [data-testid="sheet-done"]');
      } else if (vp.name === "medium") await scPress(page, "nav.pane-bar a.pane-bar-btn.on");
      else {
        await scPress(page, '[data-testid="side-chat"] [data-testid="side-input"]');
        await page.key("Escape");
      }
      const closed = await scUntil(page, (s) => s.place === null && s.path === chatPath, 5000);
      details.closed = closed.s;
      if (!closed.ok) fail(`${at}: closing the side chat left ${closed.s.path} with it ${closed.s.place ?? "gone"}`);
      if (!vp.touch && closed.s.focus !== "composer-input" && closed.s.focus !== "Side chat") fail(`${at}: after Esc the focus is on ${closed.s.focus}, not the side chat's opener`);
      if (closed.s.composerStop && !closed.s.conversation) fail(`${at}: Esc in the side chat touched the chat`);
      if (extra.drag === "reduce") await page.send("Emulation.setEmulatedMedia", { media: "screen", features: [{ name: "prefers-color-scheme", value: theme }] });
      if (!vp.touch && extra.states) {
        // The key opens it, with the focus in its box.
        await scPress(page, '[data-testid="composer-input"]');
        await scSideKey(page);
      } else await scOpen(page, vp);
      const again = await scUntil(page, (s) => s.place === wantPlace && s.newest !== null, 6000);
      details.reopened = again.s;
      if (!again.ok || again.s.newest !== before) fail(`${at}: the side chat opened again with ${JSON.stringify(again.s.newest)}, not the kept ${JSON.stringify(before)}`);
      if (!vp.touch && extra.states && !again.s.boxFocused) fail(`${at}: Ctrl+; opened the side chat with no focus in its box (${again.s.focus})`);

      // A link only fills the box: nothing goes out, the external link's line shows; Send asks and drops the text.
      mark = wire.mark();
      await page.navigate(b.base + `${sidePath}?text=${encodeURIComponent(SC_SIDE.link)}`);
      const filled = await scUntil(page, (s) => s.place === wantPlace && s.box === SC_SIDE.link, 8000);
      // The link is a new document, which drops the look that wearLook put on the old one.
      if (look !== "glass") await wearLook(page, look, theme);
      details.link = filled.s;
      if (!filled.ok) fail(`${at}: the link's text is not in the side box (${JSON.stringify(filled.s.box)})`);
      if (!filled.s.linkLine) fail(`${at}: the link's text has no "Prompt from an external link" line`);
      if (filled.s.sendOff !== false) fail(`${at}: Send is off with the link's text in the box`);
      await sleep(1000);
      const quiet = acting(wire.framesSince(mark));
      if (quiet.length) fail(`${at}: the side chat link sent ${clipList(quiet.map(frameText))} with no press`, "frames");
      const rec = await recorder(page);
      if (rec?.length) fail(`${at}: the link's page recorded ${clipList(rec)} with no press`, "recorder");
      await scShot(page, vp, theme, `link${tag}`);
      mark = wire.mark();
      if (vp.touch) await scPress(page, '[data-testid="side-chat"] [data-testid="side-send"]');
      else {
        await scPress(page, '[data-testid="side-chat"] [data-testid="side-input"]');
        await page.key("Enter");
      }
      const linked = await scUntil(page, (s) => s.newest === SC_SIDE.link && s.state === "answered" && !!s.answer?.includes(SC_SIDE.linkAnswer), 10_000);
      if (!linked.ok) fail(`${at}: the link's question got no answer after Send`);
      if (linked.s.path !== sidePath) fail(`${at}: after Send the URL is ${linked.s.path}, still with the link's text`);
      if (linked.s.linkLine) fail(`${at}: the external link's line stays after Send`);

      if (extra.states && !vp.touch) {
        // The message box's /btw: the / menu's row, then Send asks the side question and sends no prompt.
        await page.navigate(b.base + chatPath);
        await waitShown(page, ["chat", "conversation"], 8000);
        await scPress(page, '[data-testid="composer-input"]');
        await page.send("Input.insertText", { text: "/" });
        await sleep(200);
        const menu = await page.evaluate<string>(`(() => { const m = document.querySelector('[data-testid="composer"] [role="listbox"]'); return m ? m.textContent.replace(/\\s+/g, " ") : ""; })()`);
        details.slashMenu = clip(menu, 300);
        if (!menu.includes("/btw") || !menu.includes("Ask a quick side question without interrupting the main conversation")) fail(`${at}: the / menu has no /btw row with the CLI's words`);
        await page.send("Input.insertText", { text: `btw ${SC_SIDE.synthetic}` });
        await sleep(100);
        mark = wire.mark();
        await page.key("Enter");
        const fromBox = await scUntil(page, (s) => s.place === "column" && s.newest === SC_SIDE.synthetic && s.state === "answered", 10_000);
        details.fromBox = fromBox.s;
        if (!fromBox.ok) fail(`${at}: /btw in the message box did not open the side chat with its answer (${fromBox.s.path}, ${JSON.stringify(fromBox.s.newest)})`);
        else if (fromBox.s.answer !== SC_SIDE.syntheticAnswer) fail(`${at}: the synthetic answer reads ${JSON.stringify(fromBox.s.answer)}`);
        const sent = wire.framesSince(mark);
        if (sent.some((f) => f.t === "send")) fail(`${at}: /btw in the message box sent a prompt`);
        if (sent.filter((f) => f.t === "side_question").length !== 1) fail(`${at}: /btw in the message box sent ${sent.filter((f) => f.t === "side_question").length} side_question frame(s)`);
        const box = await page.evaluate<string>(`(() => { const f = document.querySelector('[data-testid="composer-input"]'); return f ? f.value : "?"; })()`);
        if (box !== "") fail(`${at}: the message box holds ${JSON.stringify(box)} after /btw`);
        await scShot(page, vp, theme, `from-box${tag}`);
      }

      // Clear: one side_clear, and the thread is empty (the box alone).
      mark = wire.mark();
      if (!(await scPress(page, '[data-testid="side-chat"] [data-testid="side-clear"]'))) fail(`${at}: Clear could not be found to press`);
      const cleared = await scUntil(page, (s) => s.newest === null && s.place === wantPlace, 5000);
      if (!cleared.ok) fail(`${at}: Clear left ${JSON.stringify(cleared.s.newest)} in the thread`);
      if (scFrames(wire, mark, "side_clear").length !== 1) fail(`${at}: Clear sent ${scFrames(wire, mark, "side_clear").length} side_clear frame(s)`);
      // On a laptop Clear puts the focus in the box for the next question; on touch nothing takes it (no keyboard).
      if (vp.touch && cleared.s.boxFocused) fail(`${at}: on touch Clear put the focus in the side box, so the keyboard would come up`);
      if (!vp.touch && !cleared.s.boxFocused) fail(`${at}: on the laptop Clear left the focus on ${cleared.s.focus}, not in the side box`);
      if (vp.name === "phone" && cleared.s.rect && cleared.s.rect.height > 200) fail(`${at}: the empty side sheet is ${cleared.s.rect.height} px high, not about the box's height`);
      await scShot(page, vp, theme, `empty${tag}`);
      scClean(cleared.s, fail, at);
      if (wire.framesSince(0).some((f) => f.t === "send")) fail(`${at}: the side chat sent a prompt`, "frames");
      issueFindings(page.takeIssues(), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return finish({ kind: "flow", name: "side-chat", route: "sideChat", scene: "side", size: sizeTag(vp), theme, path: `/c/${SC_CHAT}/btw`, failures, warnings, note: look === "glass" ? "" : `the ${look} look`, ms: Date.now() - t0, details, shot });
}

async function sideChatRunningRun(b: Booted, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const at = `${vp.width}x${vp.height} ${theme}`;
  const t: Target = { base: b.base, scene: null, booted: b };
  const chatPath = `/c/${SC_CHAT}`;
  let shot: string | undefined;
  try {
    await withPage(vp, theme, async (page, wire) => {
      await page.navigate(b.base + chatPath);
      await waitShown(page, ["chat", "conversation"], 8000);
      // The main turn: a long Bash call (about 30 s).
      await scPress(page, '[data-testid="composer-input"]');
      await page.send("Input.insertText", { text: SC_SIDE.longBash });
      await sleep(100);
      if (vp.touch) await scPress(page, '[data-testid="composer-send"]');
      else await page.key("Enter");
      const running = await scUntil(page, (s) => s.composerStop && s.conversation.includes(SC_SIDE.longBashStart), 15_000);
      if (!running.ok) return fail(`${at}: the main turn with the long Bash call did not start`, "run");
      const traceAt = Date.now();
      const transcriptBefore = running.s.conversation;

      await scOpen(page, vp);
      await scUntil(page, (s) => s.place !== null, 6000);
      const mark = wire.mark();
      await scAsk(page, vp, SC_SIDE.ask);
      const answered = await scUntil(page, (s) => s.newest === SC_SIDE.ask && s.state === "answered", 10_000);
      details.answered = answered.s;
      if (!answered.ok) fail(`${at}: the side question got no answer while the main turn ran`);
      shot = await scShot(page, vp, theme, "running");
      const during = await page.evaluate<ScState>(SC_PROBE);
      // The turn still runs (its Stop is there) and its transcript did not take the side question.
      const live = await page.evaluate<boolean>(`(() => !![...document.querySelectorAll('[data-testid="composer-stop"]')].find((e) => e.getClientRects().length) || ${vp.name === "phone" ? "true" : "false"})()`);
      if (!live) fail(`${at}: the main turn is not running any more when the side answer lands`);
      if (!during.conversation.startsWith(transcriptBefore.slice(0, 200))) fail(`${at}: the transcript changed under the side question`);
      scClean(during, fail, at);
      const traced = traceSince(t, traceAt).filter((l) => l.t === "side_question");
      details.trace = traced;
      if (!traced.length || !traced.every((l) => (l as Record<string, unknown>).duringTurn === true)) fail(`${at}: the fake claude did not see the side question during the turn (${JSON.stringify(traced)})`);
      if (wire.framesSince(mark).some((f) => f.t === "send" || f.t === "interrupt")) fail(`${at}: asking the side question sent a send or an interrupt`, "frames");
      if (traceSince(t, traceAt).some((l) => l.t === "control" && (l as Record<string, unknown>).subtype === "interrupt")) fail(`${at}: the main turn was interrupted`);

      // The turn ends as asked; its transcript holds its own reply and none of the side chat.
      if (vp.name === "phone") await scPress(page, '[data-testid="side-chat"] [data-testid="sheet-done"]');
      const ended = await scUntil(page, (s) => !s.composerStop && s.conversation.includes(SC_SIDE.longBashEnd), 60_000);
      details.ended = { ok: ended.ok, composerStop: ended.s.composerStop };
      if (!ended.ok) fail(`${at}: the main turn did not end with its own reply after the side question`);
      scClean(ended.s, fail, at);
      if (vp.name !== "phone") {
        await scPress(page, '[data-testid="side-chat"] [data-testid="side-clear"]');
        await scUntil(page, (s) => s.newest === null, 4000);
      } else {
        await scOpen(page, vp);
        await scUntil(page, (s) => s.place !== null, 6000);
        await scPress(page, '[data-testid="side-chat"] [data-testid="side-clear"]');
        await scUntil(page, (s) => s.newest === null, 4000);
      }
      issueFindings(page.takeIssues(), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return finish({ kind: "flow", name: "side-chat-running", route: "sideChat", scene: "side", size: sizeTag(vp), theme, path: `/c/${SC_CHAT}`, failures, warnings, note: "", ms: Date.now() - t0, details, shot });
}

/** R124's runs on one seed of the side scene (none with --base): side-chat's, then side-chat-running's. */
async function sideChatFlows(flows: readonly string[], record: (r: CheckResult) => void, problems: string[]): Promise<void> {
  if (BASE) {
    console.log("ui-check: side-chat boots a seed of its own (the side scene), so --base runs none of it");
    return;
  }
  const laptop = CORE.some((v) => v.name === "laptop") ? WIDE_LAPTOP : null;
  const phone = CORE.find((v) => v.name === "phone") ?? null;
  const runs: { vp: Viewport; theme: Theme; look: P2LookId; states: boolean; drag: "motion" | "reduce" | null }[] = [];
  if (flows.includes("side-chat")) {
    if (laptop) for (const theme of THEMES) runs.push({ vp: laptop, theme, look: "glass", states: theme === THEMES[0], drag: null });
    if (laptop && THEMES.includes("light")) for (const look of P2_LOOKS.filter((l) => l !== "glass")) runs.push({ vp: laptop, theme: "light", look, states: false, drag: null });
    if (phone) for (const theme of THEMES) runs.push({ vp: phone, theme, look: "glass", states: false, drag: theme === "dark" ? "reduce" : "motion" });
    // The tablet's docked pane, from the pane bar's fifth button.
    const medium = CORE.find((v) => v.name === "medium");
    if (medium && THEMES.includes("light")) runs.push({ vp: medium, theme: "light", look: "glass", states: false, drag: null });
    for (const vp of extraAt("side-chat")) runs.push({ vp, theme: THEMES.includes("light") ? "light" : THEMES[0]!, look: "glass", states: false, drag: null });
  }
  const running: { vp: Viewport; theme: Theme }[] = [];
  if (flows.includes("side-chat-running")) for (const vp of [laptop, phone, ...extraAt("side-chat-running"), ...touchAt("side-chat-running").filter((v) => v.label === "medium")]) if (vp) running.push({ vp, theme: THEMES.includes("light") ? "light" : THEMES[0]! });
  if ((!runs.length && !running.length) || cdp.closed) return;
  let b: Booted;
  try {
    b = await boot({ scene: "side", port: PORT, dist: built!, keep: KEEP, env: SERVER_ENV });
  } catch (e) {
    for (const r of runs) record(finish({ kind: "flow", name: "side-chat", route: "sideChat", scene: "side", size: sizeTag(r.vp), theme: r.theme, path: `/c/${SC_CHAT}/btw`, failures: [{ code: "seed", text: `the seed did not boot: ${(e as Error).message}` }], warnings: [], note: "", ms: 0, details: {} }));
    for (const r of running) record(finish({ kind: "flow", name: "side-chat-running", route: "sideChat", scene: "side", size: sizeTag(r.vp), theme: r.theme, path: `/c/${SC_CHAT}`, failures: [{ code: "seed", text: `the seed did not boot: ${(e as Error).message}` }], warnings: [], note: "", ms: 0, details: {} }));
    return;
  }
  live.add(b);
  try {
    for (const r of runs) {
      if (cdp.closed) break;
      record(await sideChatRun(b, r.vp, r.theme, r.look, { states: r.states, drag: r.drag }));
    }
    for (const r of running) {
      if (cdp.closed) break;
      record(await sideChatRunningRun(b, r.vp, r.theme));
    }
  } finally {
    const r = await b.stop();
    live.delete(b);
    if (r.code !== 0) problems.push(`scene side: the server exited with ${r.code}`);
    if (r.leftovers.length) problems.push(`scene side: ${r.leftovers.length} process(es) outlived the server and were ended by pid`);
  }
}

// FIX-U2 section 2 (D49): the side box's draft on every device. side-draft boots one seed of the side scene of its own
// and opens two pages on the example chat's side chat, each in a browser context of its own: page A on the laptop
// (1280x800, dark) and page B on the phone (390x844 touch, light). Text typed in A's side box goes out as one draft
// frame with `box: "side"` (never the message box's, and nothing that acts); B, opened after it, shows that text in its
// side box and sends nothing; A's next keys reach B's box with no reload, and B's reload shows it again and sends
// nothing. B's Send (a tap) asks it with the rev its box showed: both boxes empty and both threads show the answer. A
// question that A stops goes back into the side box on both pages. Nothing of it reaches the transcript. At the end A
// empties its box and clears the thread, so the seed is as it was.

async function sideDraftRun(b: Booted): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const laptop = WIDE_LAPTOP;
  const phone = VIEWPORTS.find((v) => v.name === "phone")!;
  const sidePath = `/c/${SC_CHAT}/btw`;
  const typed = `Typed on the laptop, read on the phone ${Date.now().toString(36)}`;
  const tail = ", and then some";
  const more = typed + tail;
  const input = '[data-testid="side-chat"] [data-testid="side-input"]';
  let shot: string | undefined;
  try {
    await withPage(laptop, "dark", async (a, wireA) => {
      await a.navigate(b.base + sidePath);
      const openA = await scUntil(a, (s) => s.place === "column" && s.box !== null, 8000);
      if (!openA.ok) return fail(`page A: the side chat did not open in its column (${JSON.stringify(openA.s.place)})`);
      if (openA.s.box !== "") fail(`page A: the seed's side box holds ${JSON.stringify(openA.s.box)}, not nothing`);
      // A types (no key events), and one side draft frame goes out 250 ms later; nothing acts.
      let markA = wireA.mark();
      await scPress(a, input);
      await a.send("Input.insertText", { text: typed });
      await sleep(900);
      const draftsA = scFrames(wireA, markA, "draft");
      details.draftsA = draftsA.map((f) => f.frame);
      if (!draftsA.some((f) => f.frame.box === "side" && f.frame.text === typed && f.frame.chat === SC_CHAT)) fail(`page A sent no side draft frame with the typed text (${draftsA.length} draft frames)`);
      if (draftsA.some((f) => f.frame.box !== "side")) fail("page A's side box sent a draft frame of the message box");
      const actsA = acting(wireA.framesSince(markA));
      if (actsA.length) fail(`typing in page A's side box sent ${clipList(actsA.map(frameText))}`, "frames");

      await withPage(phone, "light", async (p, wireB) => {
        await p.navigate(b.base + sidePath);
        const openB = await scUntil(p, (s) => s.place === "sheet" && s.box === typed, 8000);
        details.openB = openB.s.box;
        if (!openB.ok) fail(`page B's side box holds ${JSON.stringify(openB.s.box)}, not page A's text`);
        const quietB = mutating(wireB.framesSince(0));
        if (quietB.length) fail(`page B sent ${clipList(quietB.map(frameText))} with no press`, "frames");
        // A's next keys reach B with no reload.
        await a.send("Input.insertText", { text: tail });
        const typedAt = Date.now();
        const liveB = await scUntil(p, (s) => s.box === more, 6000);
        details.liveB = liveB.s.box;
        if (!liveB.ok) fail(`page B's side box did not follow page A's typing (it holds ${JSON.stringify(liveB.s.box)})`);
        shot = shotName("side", "side-draft", phone, "light", "page-b");
        await p.evaluate(P2_DRAWN).catch(() => {});
        await p.screenshot(shot).catch(() => {});
        await a.evaluate(P2_DRAWN).catch(() => {});
        await a.screenshot(shotName("side", "side-draft", laptop, "dark", "page-a")).catch(() => {});
        // B's reload: the server's side draft again, and nothing sent.
        let markB = wireB.mark();
        await p.reload();
        const reB = await scUntil(p, (s) => s.place === "sheet" && s.box === more, 8000);
        details.reloadB = reB.s.box;
        if (!reB.ok) fail(`after its reload page B's side box holds ${JSON.stringify(reB.s.box)}, not page A's text`);
        const quietReB = mutating(wireB.framesSince(markB));
        if (quietReB.length) fail(`page B's reload sent ${clipList(quietReB.map(frameText))} with no press`, "frames");
        // B's Send, once A's keys are over 2 s old (a box being typed in holds the server's change until it stops).
        await sleep(Math.max(0, typedAt + 2_200 - Date.now()));
        markB = wireB.mark();
        markA = wireA.mark();
        if (!(await scPress(p, '[data-testid="side-chat"] [data-testid="side-send"]'))) fail("page B's Send could not be found to press");
        const answeredB = await scUntil(p, (s) => s.newest === more && s.state === "answered" && s.box === "", 10_000);
        const answeredA = await scUntil(a, (s) => s.newest === more && s.state === "answered" && s.box === "", 8000);
        details.sent = { a: { box: answeredA.s.box, newest: answeredA.s.newest }, b: { box: answeredB.s.box, newest: answeredB.s.newest } };
        if (!answeredB.ok) fail(`after page B's Send its side chat shows ${JSON.stringify({ box: answeredB.s.box, newest: answeredB.s.newest, state: answeredB.s.state })}`);
        if (!answeredA.ok) fail(`after page B's Send page A's side box holds ${JSON.stringify(answeredA.s.box)} and its thread ${JSON.stringify(answeredA.s.newest)}`);
        const asks = scFrames(wireB, markB, "side_question");
        details.ask = asks.map((f) => f.frame);
        if (asks.length !== 1 || asks[0]!.frame.text !== more || typeof asks[0]!.frame.draftRev !== "number") fail(`page B's Send sent ${asks.length} side_question frame(s) (${JSON.stringify(asks.map((f) => f.frame.draftRev))}); expected one with the rev its box showed`);
        const actsA2 = acting(wireA.framesSince(markA));
        if (actsA2.length) fail(`page A sent ${clipList(actsA2.map(frameText))} while page B asked`, "frames");
        // A stops a question that never answers: it goes back into the side box, on both pages.
        markA = wireA.mark();
        await scAsk(a, laptop, SC_SIDE.slow);
        const running = await scUntil(a, (s) => s.newest === SC_SIDE.slow && s.asking && s.stop && s.box === "", 6000);
        if (!running.ok) fail(`page A's slow question shows no Stop, or its box was not emptied (${JSON.stringify({ asking: running.s.asking, box: running.s.box })})`);
        const emptyB = await scUntil(p, (s) => s.box === "" && s.newest === SC_SIDE.slow, 6000);
        if (!emptyB.ok) fail(`page B's side chat does not show page A's question asking with an empty box (${JSON.stringify({ box: emptyB.s.box, newest: emptyB.s.newest })})`);
        if (!(await scPress(a, '[data-testid="side-chat"] [data-testid="side-stop"]'))) fail("page A's Stop could not be found to press");
        const backA = await scUntil(a, (s) => !s.asking && s.box === SC_SIDE.slow, 6000);
        const backB = await scUntil(p, (s) => s.box === SC_SIDE.slow, 6000);
        details.stopped = { a: backA.s.box, b: backB.s.box };
        if (!backA.ok) fail(`after page A's Stop its side box holds ${JSON.stringify(backA.s.box)}, not the question`);
        if (!backB.ok) fail(`after page A's Stop page B's side box holds ${JSON.stringify(backB.s.box)}, not the question`);
        if (scFrames(wireA, markA, "side_stop").length !== 1) fail(`page A's Stop sent ${scFrames(wireA, markA, "side_stop").length} side_stop frame(s)`);
        await p.screenshot(shotName("side", "side-draft", phone, "light", "stopped")).catch(() => {});
        // Nothing of it is in the transcript.
        for (const s of [backA.s, backB.s]) if (s.conversation.includes(typed) || s.conversation.includes(SC_SIDE.slow)) fail("the transcript holds the side box's text");
        // Back as the seed was: A empties its box (saved, so B's empties too) and clears the thread.
        await a.evaluate(`(() => { const f = [...document.querySelectorAll('[data-testid="side-input"]')].find((e) => e.getClientRects().length); const set = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, "value").set; set.call(f, ""); f.dispatchEvent(new Event("input", { bubbles: true })); return true; })()`);
        const clearedB = await scUntil(p, (s) => s.box === "", 6000);
        if (!clearedB.ok) fail(`page A emptied its side box, and page B's still holds ${JSON.stringify(clearedB.s.box)}`);
        await scPress(a, '[data-testid="side-chat"] [data-testid="side-clear"]');
        await scUntil(a, (s) => s.newest === null, 5000);
        if (wireB.framesSince(0).some((f) => f.t === "send") || wireA.framesSince(0).some((f) => f.t === "send")) fail("the side box sent a prompt", "frames");
        issueFindings(p.takeIssues(), failures, "page B: ");
      });
      issueFindings(a.takeIssues(), failures, "page A: ");
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = "page A's side box (1280x800) on page B's (390x844 touch): live, after a reload, cleared by B's Send, the question back after A's Stop";
  return finish({ kind: "flow", name: "side-draft", route: "sideChat", scene: "side", size: "laptop", theme: "dark", path: sidePath, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/** FIX-U2's side-draft, on one seed of the side scene of its own (none with --base). */
async function sideDraftFlows(record: (r: CheckResult) => void, problems: string[]): Promise<void> {
  if (BASE) {
    console.log("ui-check: side-draft boots a seed of its own (the side scene), so --base runs none of it");
    return;
  }
  if (cdp.closed) return;
  let b: Booted;
  try {
    b = await boot({ scene: "side", port: PORT, dist: built!, keep: KEEP, env: SERVER_ENV });
  } catch (e) {
    record(finish({ kind: "flow", name: "side-draft", route: "sideChat", scene: "side", size: "laptop", theme: "dark", path: `/c/${SC_CHAT}/btw`, failures: [{ code: "seed", text: `the seed did not boot: ${(e as Error).message}` }], warnings: [], note: "", ms: 0, details: {} }));
    return;
  }
  live.add(b);
  try {
    record(await sideDraftRun(b));
  } finally {
    const r = await b.stop();
    live.delete(b);
    if (r.code !== 0) problems.push(`scene side (side-draft): the server exited with ${r.code}`);
    if (r.leftovers.length) problems.push(`scene side (side-draft): ${r.leftovers.length} process(es) outlived the server and were ended by pid`);
  }
}

// ---------------------------------------------------------------------------------------------------------------
// U2 (FIX-U2 section 1, DESIGN-U2): turn-fold, a finished turn folded to one line. It boots one seed of the main scene
// of its own (the example chat's finished turns: the long first turn with its calls, subagent, edits, to-do list and
// workflow, the /context and `!` turns, and the warm-up turn with its task tools) and runs at 1280x800 and at 390x844
// with touch, light and dark, at 834x1194 with touch, light, and at 1280x800 light in each of the other three looks:
// - drawn folded: every turn with work to fold shows one line (a button, aria-expanded false, its words in one sentence
//   with no middle dot), its work hidden until found and taking no room, every input and each answer in sight (after
//   the container that holds a turn's last folded reply comes its last reply, shown); on touch the line is 44 px high
//   and its words end with an ellipsis rather than going past the edge; a screenshot at the end and one at the top;
// - open and close: a press on the line opens the work in place (the line does not move, the chevron turns, the thread
//   in --hairline), Enter on the focused line closes it and opens it again, a reload keeps the reader's choice (session
//   storage), and closing it is kept too; the line in --dim, its chevron in --faint;
// - a link into a folded turn (/m/ and /tool/) opens that turn and shows the row, highlighted and in view; the chat's
//   own path after it draws the turn folded again (a link is not the reader's choice). chatSearch has no conversation
//   text until U5, whose hits are such links. The browser's Find looks inside folded work: a link to a folded reply's
//   words (a text fragment, which goes through Find on Page's own reveal and its beforematch) opens the turn;
// - Verbose draws every row and no line; Thinking folds alike and an open turn shows its thinking row; Reduce motion
//   stops the chevron's turn, which only the reader's own press makes (an automatic fold moves nothing);
// - the timing rule (1280x800 and 390x844, light): a turn that the page watches is not folded while it runs and stays
//   open when it ends, with the keyboard focus that was on its summary row's button still there and its reply where
//   it was (same left edge, same width: the thread is drawn in the gutter); while the reader is scrolled up, a next
//   turn does not fold it and the reader's first row stays where it is; back at the end (Jump to latest) it folds; a
//   turn the reader stops (Stop, its one interrupt) says Interrupted once: with work to fold, its line's quiet tag (open
//   where it was watched, folded at the next turn), else its mark in place (the seed's: one command after its reply,
//   nothing to fold); a view switch
//   (Ctrl+O through Thinking, Verbose and Normal) while scrolled up keeps the reader's first row in place; the next
//   page drawn shows the watched turn folded;
// - nothing else that acts goes out; screenshots, folded and open (and the watched and the stopped turn on the live
//   runs), with the machine's name shown as "this-machine" (tfShot).

const TF_CHAT = EX.chat;
/** A reply inside the first turn's work, its block's id, and a run of its words for the browser's Find. */
const TF_REPLY = "msg_01UploadTable";
const TF_REPLY_ROW = `${TF_REPLY}-0`;
const TF_FIND = "The test fails about one run in five";
/** A call inside a summary inside the first turn's work. */
const TF_TOOL = "toolu_01GrepAttempt";

interface TfTurn {
  id: string;
  expanded: string | null;
  controls: string | null;
  label: string | null;
  tag: string | null;
  hidden: (string | null)[];
  workShown: boolean;
  workHeight: number;
  top: number;
  height: number;
  chev: string | null;
  chevDur: string | null;
  color: string;
  chevColor: string;
  thread: string | null;
  labelCut: boolean;
  labelEllipsis: string | null;
  next: string | null;
  nextShown: boolean;
  /** U2 review: the row after the container that holds the turn's last folded reply (its answer), when it has one. */
  answer?: string | null;
  answerShown: boolean;
}
interface TfState {
  turns: TfTurn[];
  users: number;
  usersShown: boolean;
  rows: number;
  shownRows: number;
  gap: number | null;
  scrollTop: number | null;
  wide: boolean;
  tokens: { dim: string; faint: string; hairline: string };
  jump: boolean;
}

/** In-page: every turn's line and work, the inputs, the rows that show, the scroller, and the look's tokens. */
const TF_PROBE = `(() => {
  const vis = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && el.getBoundingClientRect().height > 0;
  const probe = (prop, v) => { const s = document.createElement("span"); s.style[prop] = v; document.body.appendChild(s); const c = getComputedStyle(s)[prop]; s.remove(); return c; };
  const sc = [...document.querySelectorAll(".chat-scroll")].find((e) => e.getClientRects().length > 0);
  const st = sc ? sc.getBoundingClientRect().top : 0;
  const turns = [...document.querySelectorAll(".chat-turn[data-turn-id]")].map((t) => {
    const id = t.getAttribute("data-turn-id");
    const b = t.querySelector("button.chat-turn-line");
    const works = [...document.querySelectorAll('[data-turn-work="' + CSS.escape(id) + '"]')];
    const label = t.querySelector(":scope > .chat-row-line .chat-row-label");
    const tag = t.querySelector(":scope > .chat-row-line .chat-tag");
    const chevBox = t.querySelector(":scope > .chat-row-line .chat-turn-chev");
    const chev = chevBox ? chevBox.querySelector("svg") : null;
    const r = b.getBoundingClientRect();
    let next = t.nextElementSibling;
    while (next && next.matches(".chat-turn-work")) next = next.nextElementSibling;
    // The turn's answer (its last reply) shows: the row after the container that holds its last folded reply, past
    // the turn's own containers, is a reply in sight.
    const replies = works.flatMap((w) => [...w.querySelectorAll(":scope > .chat-item-assistant[data-item-id]")]);
    const lastReply = replies[replies.length - 1];
    let after = null;
    if (lastReply) {
      const box = lastReply.closest(".chat-turn-work");
      after = (box.parentElement === t ? t : box).nextElementSibling;
      while (after && after.matches('.chat-turn-work[data-turn-work="' + CSS.escape(id) + '"]')) after = after.nextElementSibling;
    }
    return {
      id, expanded: b.getAttribute("aria-expanded"), controls: b.getAttribute("aria-controls"), label: label ? label.textContent : null, tag: tag ? tag.textContent : null,
      hidden: works.map((w) => w.getAttribute("hidden")), workShown: works.some(vis), workHeight: Math.round(works.reduce((n, w) => n + w.getBoundingClientRect().height, 0)),
      top: Math.round(r.top - st), height: Math.round(r.height), chev: chev ? getComputedStyle(chev).transform : null, chevDur: chev ? getComputedStyle(chev).transitionDuration : null,
      color: getComputedStyle(b).color, chevColor: chevBox ? getComputedStyle(chevBox).color : "", thread: works[0] && vis(works[0]) ? getComputedStyle(works[0], "::before").borderLeftColor : null,
      labelCut: !!label && label.scrollWidth > label.clientWidth + 1, labelEllipsis: label ? getComputedStyle(label).textOverflow : null,
      next: next ? (next.getAttribute("data-item-id") || next.getAttribute("data-testid") || next.className) : null, nextShown: vis(next),
      ...(lastReply ? { answer: after ? (after.getAttribute("data-item-id") || after.className) : null } : {}), answerShown: !lastReply || (!!after && after.matches(".chat-item-assistant") && vis(after)),
    };
  });
  const users = [...document.querySelectorAll(".chat-col .chat-item-user")];
  const rows = [...document.querySelectorAll(".chat-col [data-item-id]")];
  return {
    turns, users: users.length, usersShown: users.every(vis), rows: rows.length, shownRows: rows.filter(vis).length,
    gap: sc ? Math.round(sc.scrollHeight - sc.scrollTop - sc.clientHeight) : null, scrollTop: sc ? Math.round(sc.scrollTop) : null,
    wide: document.scrollingElement.scrollWidth > innerWidth + 1,
    tokens: { dim: probe("color", "var(--dim)"), faint: probe("color", "var(--faint)"), hairline: probe("borderLeftColor", "var(--hairline)") },
    jump: [...document.querySelectorAll(".chat-jump")].some(vis),
  };
})()`;

/**
 * In-page, while the watched turn runs: put the keyboard focus on its summary row's button (the newest summary row) and
 * read its first reply's place (the first reply after the newest message). Null until the summary row shows.
 */
interface TfHeld {
  summary: string;
  reply: string | null;
  left: number;
  width: number;
}
const TF_HOLD = `(() => {
  const users = [...document.querySelectorAll(".chat-col > .chat-item-user")];
  const u = users[users.length - 1];
  let r = null, sum = null;
  for (let n = u ? u.nextElementSibling : null; n; n = n.nextElementSibling) {
    if (!r && n.matches(".chat-item-assistant")) r = n;
    if (!sum && n.matches('[data-testid^="summary-"]')) sum = n;
  }
  const b = sum && sum.querySelector("button.chat-row");
  if (!b) return null;
  b.focus();
  const box = r ? r.getBoundingClientRect() : null;
  return { summary: sum.getAttribute("data-testid"), reply: r ? r.getAttribute("data-item-id") : null, left: box ? Math.round(box.left) : 0, width: box ? Math.round(box.width) : 0 };
})()`;

/** In-page, after the watched turn's end: where the focus is (its summary row) and the reply's place now. */
const tfHeld = (reply: string | null) => `(() => {
  const a = document.activeElement;
  const sum = a && a.closest ? a.closest('[data-testid^="summary-"]') : null;
  const r = ${JSON.stringify(reply)} ? document.querySelector('[data-item-id="' + CSS.escape(${JSON.stringify(reply ?? "")}) + '"]') : null;
  const box = r ? r.getBoundingClientRect() : null;
  const up = [];
  for (let n = sum ? sum.parentElement : null; n && up.length < 4; n = n.parentElement) up.push(n.className + (n.getAttribute("data-turn-work") ? "[" + n.getAttribute("data-turn-work") + "]" : ""));
  return { focus: sum ? sum.getAttribute("data-testid") : null, inWork: !!(a && a.closest && a.closest("[data-turn-work]")), up, left: box ? Math.round(box.left) : null, width: box ? Math.round(box.width) : null };
})()`;

/** In-page: the row with this id: whether it shows, its top in the scroller, whether it is highlighted and in view. */
const tfRow = (sel: string) => `(() => {
  const el = document.querySelector(${JSON.stringify(sel)});
  const sc = [...document.querySelectorAll(".chat-scroll")].find((e) => e.getClientRects().length > 0);
  if (!el || !sc) return null;
  const r = el.getBoundingClientRect(), s = sc.getBoundingClientRect();
  return { shown: el.getClientRects().length > 0 && r.height > 0, top: Math.round(r.top - s.top), inView: r.bottom > s.top && r.top < s.bottom, highlight: el.classList.contains("is-highlight") };
})()`;

/** In-page: the reader's first row (the first [data-item-id] or line whose bottom is below the scroller's top). */
const TF_FIRST = `(() => {
  const sc = [...document.querySelectorAll(".chat-scroll")].find((e) => e.getClientRects().length > 0);
  if (!sc) return null;
  const top = sc.getBoundingClientRect().top;
  const el = [...sc.querySelectorAll("[data-item-id], [data-turn-id]")].find((e) => { const r = e.getBoundingClientRect(); return r.height > 0 && r.bottom > top + 1; });
  if (!el) return null;
  return { sel: el.hasAttribute("data-item-id") ? '[data-item-id="' + el.getAttribute("data-item-id") + '"]' : '[data-turn-id="' + el.getAttribute("data-turn-id") + '"]', top: Math.round(el.getBoundingClientRect().top - top) };
})()`;

/**
 * A screenshot with the machine's own name (the Environment card's first row, D54) shown as "this-machine", so no
 * screenshot of this flow carries the host name; the page itself is as it was drawn otherwise.
 */
async function tfShot(page: Page, file: string) {
  // The pointer off the rows, so no hover shows.
  if (!page.vp.touch) await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: page.vp.width - 2, y: Math.round(page.vp.height / 2) });
  await maskMachine(page);
  await page.screenshot(file).catch(() => {});
}

/**
 * The machine's own name, where the page shows it (the Environment panel's machine row), becomes "this-machine" in the
 * page's text before a still is taken, so no screenshot holds it (the stills go to the owner; the reports never do).
 * A check that reads the page's text after it must reload first, as the route check does.
 */
async function maskMachine(page: Page): Promise<void> {
  const name = machineName();
  if (!name) return;
  await page
    .evaluate(`(() => { const w = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT); for (let n = w.nextNode(); n; n = w.nextNode()) if (n.nodeValue.includes(${JSON.stringify(name)})) n.nodeValue = n.nodeValue.split(${JSON.stringify(name)}).join("this-machine"); return true; })()`)
    .catch(() => {});
}

async function tfUntil(page: Page, ok: (s: TfState) => boolean, ms: number): Promise<{ ok: boolean; s: TfState }> {
  const end = Date.now() + ms;
  let s = await page.evaluate<TfState>(TF_PROBE);
  while (!ok(s) && Date.now() < end) {
    await sleep(100);
    s = await page.evaluate<TfState>(TF_PROBE);
  }
  return { ok: ok(s), s };
}

/** The turn with the most work: the example chat's first turn. */
const tfBig = (s: TfState): TfTurn | undefined => s.turns.find((t) => t.label?.includes("subagent")) ?? s.turns[0];

/** Press a turn's line (a click, a tap on touch); false when it cannot be found. */
async function tfPress(page: Page, id: string): Promise<boolean> {
  const at = await page.locate(`[data-turn-id="${id}"] button.chat-turn-line`);
  if (!at) return false;
  await page.press(at.x, at.y);
  return true;
}

/** Put the scroller at `top`, as the reader's own scroll does (the view stops following the end). */
const tfScrollTo = (top: number | "end") =>
  `(() => { const sc = [...document.querySelectorAll(".chat-scroll")].find((e) => e.getClientRects().length > 0); if (!sc) return false; sc.dispatchEvent(new WheelEvent("wheel", { deltaY: ${top === "end" ? 120 : -120}, bubbles: true })); sc.scrollTop = ${top === "end" ? "sc.scrollHeight" : top}; return true; })()`;

/** Put the row at `sel` `at` px under the scroller's top, as a reader's scroll would. */
const tfScrollRow = (sel: string, at: number) =>
  `(() => { const sc = [...document.querySelectorAll(".chat-scroll")].find((e) => e.getClientRects().length > 0); const el = document.querySelector(${JSON.stringify(sel)}); if (!sc || !el) return false; sc.dispatchEvent(new WheelEvent("wheel", { deltaY: -120, bubbles: true })); sc.scrollTop += el.getBoundingClientRect().top - sc.getBoundingClientRect().top - ${at}; return true; })()`;

/** Ctrl+O, the view's own key (Normal, Thinking, Verbose). */
async function tfCtrlO(page: Page) {
  const base = { key: "o", code: "KeyO", windowsVirtualKeyCode: 79, nativeVirtualKeyCode: 79, modifiers: 2 };
  await page.send("Input.dispatchKeyEvent", { type: "keyDown", ...base });
  await page.send("Input.dispatchKeyEvent", { type: "keyUp", ...base });
  await page.evaluate(P2_DRAWN);
}

/** The folded transcript as it is drawn: one line per turn with work, folded, the inputs and answers in sight. */
function tfFolded(s: TfState, vp: Viewport, at: string, fail: (text: string) => void) {
  if (s.turns.length < 2) return fail(`${at}: the example chat shows ${s.turns.length} turn line(s), not one for each of its turns with work (at least 2)`);
  for (const t of s.turns) {
    const name = JSON.stringify(t.label);
    if (t.expanded !== "false") fail(`${at}: the line ${name} is drawn ${t.expanded === "true" ? "open" : `with aria-expanded ${t.expanded}`}, not folded`);
    if (t.hidden.length === 0 || t.hidden.some((h) => h !== "until-found")) fail(`${at}: the work of ${name} is hidden as ${JSON.stringify(t.hidden)}, not until found`);
    if (t.workShown || t.workHeight !== 0) fail(`${at}: the folded work of ${name} still shows (${t.workHeight} px)`);
    if (!t.controls || t.controls.split(" ").length !== t.hidden.length) fail(`${at}: the line ${name} controls ${JSON.stringify(t.controls)}, not its ${t.hidden.length} container(s)`);
    if (!t.label || !/^[A-Z]/.test(t.label) || /[·•|]/.test(t.label)) fail(`${at}: the line's words ${name} are not one capitalized sentence with no middle dot`);
    if (vp.touch && t.height < 44) fail(`${at}: the line ${name} is ${t.height} px high on touch, under 44`);
    if (!vp.touch && t.height < 24) fail(`${at}: the line ${name} is ${t.height} px high`);
    if (t.color !== s.tokens.dim) fail(`${at}: the line ${name} is in ${t.color}, not --dim (${s.tokens.dim})`);
    if (t.chevColor !== s.tokens.faint) fail(`${at}: the chevron of ${name} is in ${t.chevColor}, not --faint (${s.tokens.faint})`);
    if (t.chev !== "none") fail(`${at}: the folded line ${name} has its chevron turned (${t.chev})`);
    if (t.next && !t.nextShown) fail(`${at}: the row after the line ${name} (${t.next}) does not show`);
    if (!t.answerShown) fail(`${at}: the folded turn ${name} shows no answer: after its last folded reply comes ${t.answer === null ? "nothing" : JSON.stringify(t.answer)}, not its last reply in sight`);
    if (t.labelCut && t.labelEllipsis !== "ellipsis") fail(`${at}: the line ${name} is cut with ${t.labelEllipsis}, not an ellipsis`);
  }
  if (!s.usersShown) fail(`${at}: not every message of the chat shows (${s.users} messages)`);
  if (s.wide) fail(`${at}: the page scrolls sideways`);
}

async function turnFoldRun(b: Booted, vp: Viewport, theme: Theme, look: P2LookId, liveRun: boolean): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = { look };
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const t: Target = { base: b.base, scene: null, booted: b };
  const chatPath = `/c/${TF_CHAT}`;
  const tag = look === "glass" ? "" : `-${look}`;
  const at = `${vp.width}x${vp.height} ${theme}${look === "glass" ? "" : `, ${look}`}`;
  let shot: string | undefined;
  try {
    await withPage(vp, theme, async (page, wire) => {
      const draw = async (path: string) => {
        await page.navigate(b.base + path);
        await waitShown(page, ["chat", "conversation"]);
        if (look !== "glass") await wearLook(page, look, theme);
        return tfUntil(page, (s) => s.turns.length > 0, 8000);
      };

      // ---- drawn folded
      const first = await draw(chatPath);
      details.folded = first.s;
      tfFolded(first.s, vp, at, fail);
      shot = shotName("main", "turn-fold", vp, theme, `folded${tag}`);
      await tfShot(page, shot);
      // U2 review: the top of the chat too, where the first turn's answer follows its line.
      await page.evaluate(`(() => { const sc = [...document.querySelectorAll(".chat-scroll")].find((e) => e.getClientRects().length > 0); if (sc) { sc.dispatchEvent(new WheelEvent("wheel", { deltaY: -120, bubbles: true })); sc.scrollTop = 0; } return true; })()`);
      await page.evaluate(P2_DRAWN);
      await tfShot(page, shotName("main", "turn-fold", vp, theme, `folded-top${tag}`));
      const big = tfBig(first.s);
      if (!big) return fail(`${at}: the example chat shows no turn line`);

      // ---- open and close: the line does not move, the chevron turns, the thread shows
      const before = await page.locate(`[data-turn-id="${big.id}"] button.chat-turn-line`);
      const beforeTop = (await page.evaluate<TfState>(TF_PROBE)).turns.find((x) => x.id === big.id)?.top;
      if (!before || !(await tfPress(page, big.id))) return fail(`${at}: the line ${JSON.stringify(big.label)} could not be found to press`);
      await tfUntil(page, (s) => s.turns.find((x) => x.id === big.id)?.expanded === "true", 3000);
      await page.evaluate(TRANSITIONS_DONE);
      const opened = await tfUntil(page, (s) => s.turns.find((x) => x.id === big.id)?.expanded === "true", 1000);
      const o = opened.s.turns.find((x) => x.id === big.id);
      details.opened = o;
      if (!opened.ok || !o) fail(`${at}: a press on the line did not open the turn`);
      else {
        if (!o.workShown || o.hidden.some((h) => h !== null)) fail(`${at}: the open turn's work does not show (hidden ${JSON.stringify(o.hidden)})`);
        if (beforeTop !== undefined && Math.abs(o.top - beforeTop) > 2) fail(`${at}: the line moved from ${beforeTop} to ${o.top} px when it opened`);
        if (o.chev !== "matrix(0, 1, -1, 0, 0, 0)") fail(`${at}: the open line's chevron did not turn a quarter (${o.chev})`);
        if (o.chevDur === "0s") fail(`${at}: the reader's own press turned the chevron with no transition`);
        if (o.thread !== opened.s.tokens.hairline) fail(`${at}: the open work's thread is ${o.thread}, not --hairline (${opened.s.tokens.hairline})`);
      }
      await tfShot(page, shotName("main", "turn-fold", vp, theme, `open${tag}`));
      if (look !== "glass") {
        issueFindings(page.takeIssues(), failures);
        return;
      }

      // Keyboard: Enter on the focused line closes it and opens it again.
      await page.evaluate(`(() => { const b = document.querySelector('[data-turn-id="${big.id}"] button.chat-turn-line'); if (b) b.focus(); return !!b; })()`);
      await page.key("Enter");
      const keyed = await tfUntil(page, (s) => s.turns.find((x) => x.id === big.id)?.expanded === "false", 3000);
      if (!keyed.ok) fail(`${at}: Enter on the focused line did not close the turn`);
      await page.key("Enter");
      if (!(await tfUntil(page, (s) => s.turns.find((x) => x.id === big.id)?.expanded === "true", 3000)).ok) fail(`${at}: Enter again did not open the turn`);

      // A reload keeps the reader's choice; closing it is kept too.
      await page.reload();
      await waitShown(page, ["chat", "conversation"]);
      const kept = await tfUntil(page, (s) => s.turns.some((x) => x.id === big.id), 8000);
      details.reloaded = kept.s.turns.map((x) => `${x.id}:${x.expanded}`);
      if (kept.s.turns.find((x) => x.id === big.id)?.expanded !== "true") fail(`${at}: after a reload the turn the reader opened is ${kept.s.turns.find((x) => x.id === big.id)?.expanded === "false" ? "folded" : "gone"}`);
      if (kept.s.turns.some((x) => x.id !== big.id && x.expanded !== "false")) fail(`${at}: after a reload a turn the reader did not open is open`);
      await tfPress(page, big.id);
      await tfUntil(page, (s) => s.turns.find((x) => x.id === big.id)?.expanded === "false", 3000);
      await page.reload();
      await waitShown(page, ["chat", "conversation"]);
      const closed = await tfUntil(page, (s) => s.turns.some((x) => x.id === big.id), 8000);
      if (closed.s.turns.find((x) => x.id === big.id)?.expanded !== "false") fail(`${at}: after the reader closed the turn and reloaded, it is open`);

      // Reduce motion: the chevron turns at once.
      await page.send("Emulation.setEmulatedMedia", { media: "screen", features: [{ name: "prefers-color-scheme", value: theme }, { name: "prefers-reduced-motion", value: "reduce" }] });
      await page.evaluate(P2_DRAWN);
      await tfPress(page, big.id);
      const still = (await tfUntil(page, (s) => s.turns.find((x) => x.id === big.id)?.expanded === "true", 3000)).s;
      details.reduceMotion = still.turns.map((x) => x.chevDur);
      if (still.turns.some((x) => x.chevDur !== "0s")) fail(`${at}: under Reduce motion the chevron still turns over ${JSON.stringify(still.turns.map((x) => x.chevDur))}`);
      await tfPress(page, big.id);
      await tfUntil(page, (s) => s.turns.find((x) => x.id === big.id)?.expanded === "false", 3000);
      await page.send("Emulation.setEmulatedMedia", { media: "screen", features: [{ name: "prefers-color-scheme", value: theme }] });

      // ---- a link into a folded turn opens it and shows the row; the chat's own path draws it folded again
      for (const [route, sel] of [
        [`${chatPath}/m/${TF_REPLY}`, `[data-item-id="${TF_REPLY_ROW}"]`],
        [`${chatPath}/tool/${TF_TOOL}`, `[data-item-id="${TF_TOOL}"]`],
      ] as const) {
        const linked = await draw(route);
        const row = await page.evaluate<{ shown: boolean; top: number; inView: boolean; highlight: boolean } | null>(tfRow(sel));
        details[`link ${route}`] = { row, turn: tfBig(linked.s)?.expanded };
        if (tfBig(linked.s)?.expanded !== "true") fail(`${at}: the link ${route} left its folded turn closed`);
        if (!row?.shown || !row.inView) fail(`${at}: the link ${route} does not show its row in view (${JSON.stringify(row)})`);
        if (route.includes("/m/") && !row?.highlight) fail(`${at}: the link ${route} does not highlight its row`);
      }
      const again = await draw(chatPath);
      if (tfBig(again.s)?.expanded !== "false") fail(`${at}: after a link, the chat's own path draws the linked turn open (a link is not the reader's choice)`);

      // The browser's Find looks inside folded work (hidden until found): a link to the words (a text fragment) goes
      // through the same reveal as Find on Page, whose beforematch opens the turn, kept as the reader's choice.
      await page.navigate("about:blank");
      const found = await draw(`${chatPath}#:~:text=${encodeURIComponent(TF_FIND)}`);
      const byFind = await tfUntil(page, (s) => tfBig(s)?.expanded === "true", 4000);
      const words = await page.evaluate<{ shown: boolean; inView: boolean } | null>(tfRow(`[data-item-id="${TF_REPLY_ROW}"]`));
      details.find = { open: byFind.ok, words, lines: found.s.turns.length };
      if (!byFind.ok) fail(`${at}: the browser's reveal of words in a folded turn (a text fragment, as Find on Page) did not open the turn`);
      else if (!words?.shown) fail(`${at}: the found words' row does not show`);
      if (byFind.ok) {
        await tfPress(page, big.id);
        await tfUntil(page, (s) => tfBig(s)?.expanded === "false", 3000);
      }

      // ---- Verbose draws every row and no line; Thinking folds alike, and its open turn shows its thinking
      await page.navigate(b.base + `${chatPath}?view=verbose`);
      await waitShown(page, ["chat", "conversation"]);
      const v = await page.evaluate<TfState>(TF_PROBE);
      details.verbose = { lines: v.turns.length, rows: v.rows, shown: v.shownRows };
      if (v.turns.length) fail(`${at}: Verbose shows ${v.turns.length} turn line(s)`);
      if (v.shownRows !== v.rows || v.rows <= first.s.shownRows) fail(`${at}: Verbose shows ${v.shownRows} of ${v.rows} rows (folded Normal showed ${first.s.shownRows})`);
      const thinking = await draw(`${chatPath}?view=thinking`);
      const th = tfBig(thinking.s);
      if (!th) fail(`${at}: Thinking shows no turn line`);
      else {
        await tfPress(page, th.id);
        const shownThinking = await page.evaluate<boolean>(`(() => [...document.querySelectorAll('[data-turn-work="${th.id}"] .chat-item-thinking')].some((e) => e.getClientRects().length > 0))()`);
        if (!shownThinking) fail(`${at}: the open turn in Thinking shows no thinking row`);
        await tfPress(page, th.id);
      }

      // ---- the timing rule, live
      if (liveRun) {
        await draw(chatPath);
        await page.evaluate(tfScrollTo("end"));
        let ran: string | null = null;
        let done = false;
        const turn = serverTurn(t, TF_CHAT, SEND_NOW.bash, 90_000).then(
          () => null,
          (e: Error) => e.message,
        );
        void turn.then((why) => {
          ran = why;
          done = true;
        });
        // While it runs: no line for it. The keyboard focus goes on its summary row's button, and its first reply's place
        // is read (U2 review: at the end the focus stays on that button, and no row moves sideways or wraps again).
        const runningLines = new Set<string>();
        const known = new Set((await page.evaluate<TfState>(TF_PROBE)).turns.map((x) => x.id));
        let held: TfHeld | null = null;
        while (!done) {
          const s = await page.evaluate<TfState>(TF_PROBE);
          for (const x of s.turns) if (!known.has(x.id)) runningLines.add(x.id);
          if (!held) held = await page.evaluate<TfHeld | null>(TF_HOLD);
          await sleep(500);
        }
        if (ran) return fail(`the watched turn could not run: ${ran}`, "run");
        const ended = await tfUntil(page, (s) => s.turns.some((x) => !known.has(x.id)), 5000);
        const watched = ended.s.turns.find((x) => !known.has(x.id));
        const kept = held ? await page.evaluate<{ focus: string | null; inWork: boolean; up: string[]; left: number | null; width: number | null }>(tfHeld(held.reply)) : null;
        details.watched = { line: watched, linesWhileRunning: [...runningLines], held, kept };
        if (!held) fail(`${at}: the running turn showed no summary row to put the focus on`);
        else if (kept) {
          if (kept.focus !== held.summary || !kept.inWork) fail(`${at}: when the watched turn ended, the keyboard focus on its summary row's button went to ${JSON.stringify(kept.focus)}${kept.inWork ? "" : " (outside its work)"}`);
          if (held.reply && (kept.left === null || Math.abs(kept.left - held.left) > 1 || kept.width === null || Math.abs(kept.width - held.width) > 1)) fail(`${at}: when the watched turn ended, its reply moved from ${held.left} px (${held.width} px wide) to ${kept.left} px (${kept.width} px wide)`);
        }
        // The focus leaves the work, so the timing rule may fold the turn below.
        await page.evaluate(`(() => { const a = document.activeElement; if (a && a.blur) a.blur(); return true; })()`);
        if (runningLines.size && watched && runningLines.has(watched.id)) fail(`${at}: the turn showed a line while it ran`);
        if (!watched) return fail(`${at}: the watched turn has no line after its end`);
        if (watched.expanded !== "true") fail(`${at}: the turn this page watched end is drawn folded, not open`);
        if (!/^Worked for \d+s, ran 1 command$/.test(watched.label ?? "")) fail(`${at}: the watched turn's line reads ${JSON.stringify(watched.label)}, not "Worked for <time>, ran 1 command"`);
        await tfShot(page, shotName("main", "turn-fold", vp, theme, "newest-open"));

        // Scrolled up, a next turn does not fold it, and the reader's first row stays where it is.
        await page.evaluate(tfScrollTo(0));
        await page.evaluate(P2_DRAWN);
        const firstRow = await page.evaluate<{ sel: string; top: number } | null>(TF_FIRST);
        try {
          await serverTurn(t, TF_CHAT, "Run the tests again (turn-fold).", 60_000);
        } catch (e) {
          return fail(`the next turn could not run: ${(e as Error).message}`, "run");
        }
        await sleep(600);
        const up = await page.evaluate<TfState>(TF_PROBE);
        const stillOpen = up.turns.find((x) => x.id === watched.id);
        const rowNow = firstRow ? await page.evaluate<{ top: number } | null>(tfRow(firstRow.sel)) : null;
        details.scrolledUp = { firstRow, rowNow, watched: stillOpen?.expanded, jump: up.jump };
        if (stillOpen?.expanded !== "true") fail(`${at}: the watched turn folded while the reader was scrolled up`);
        if (firstRow && rowNow && Math.abs(rowNow.top - firstRow.top) > 2) fail(`${at}: the reader's first row moved from ${firstRow.top} to ${rowNow.top} px while scrolled up`);
        // Back at the end, it folds.
        const jumpAt = await page.locate(".chat-jump");
        if (jumpAt) await page.press(jumpAt.x, jumpAt.y);
        else await page.evaluate(tfScrollTo("end"));
        const folded = await tfUntil(page, (s) => s.turns.find((x) => x.id === watched.id)?.expanded === "false", 4000);
        details.atEnd = folded.s.turns.find((x) => x.id === watched.id);
        if (!folded.ok) fail(`${at}: back at the end, the watched turn did not fold when the next turn had started`);
        else if (details.atEnd && (details.atEnd as TfTurn).chev !== "none") fail(`${at}: the automatic fold turned the chevron with a transition (${(details.atEnd as TfTurn).chev})`);

        // A turn that the reader stops: open where it was watched, with its Interrupted mark at the end of its work and
        // the quiet tag on the line; once the next turn starts it folds, and the tag alone says it.
        const knownNow = new Set((await page.evaluate<TfState>(TF_PROBE)).turns.map((x) => x.id));
        // The Interrupted marks in sight (an earlier run on this seed may have left one).
        const marks = `(() => [...document.querySelectorAll(".chat-col .chat-foot-line")].filter((e) => e.textContent === "Interrupted" && e.getClientRects().length > 0 && !e.closest('[hidden="until-found"]')).length)()`;
        const marksBefore = await page.evaluate<number>(marks);
        const stopped = serverTurn(t, TF_CHAT, SEND_NOW.bash, 90_000).then(
          () => null,
          (e: Error) => e.message,
        );
        const stopAt = Date.now() + 15_000;
        let stopBtn = await page.locate('[data-testid="composer-stop"]');
        while (!stopBtn && Date.now() < stopAt) {
          await sleep(200);
          stopBtn = await page.locate('[data-testid="composer-stop"]');
        }
        await sleep(1500);
        if (!stopBtn) return fail(`${at}: no Stop shows while the long command runs`);
        await page.press(stopBtn.x, stopBtn.y);
        const why = await stopped;
        if (why) return fail(`the turn to stop could not run: ${why}`, "run");
        // The turn's end, then its line: a stopped turn with work to fold gets a line with the tag; one whose only work
        // is one row (the seed's: its reply, then the stopped command) keeps its rows and its Interrupted mark.
        await waitUntil(
          async () => ({ m: await page.evaluate<number>(marks), s: await page.evaluate<TfState>(TF_PROBE) }),
          (v) => v.m > marksBefore || v.s.turns.some((x) => !knownNow.has(x.id)),
          8000,
        );
        const halted = await tfUntil(page, (s) => s.turns.some((x) => !knownNow.has(x.id)), 1500);
        const h = halted.s.turns.find((x) => !knownNow.has(x.id));
        const shownMarks = (await page.evaluate<number>(marks)) - marksBefore;
        details.stopped = { line: h, marks: shownMarks, before: marksBefore };
        if (h) {
          if (h.tag !== "Interrupted") fail(`${at}: the stopped turn's line has the tag ${JSON.stringify(h.tag)}, not Interrupted`);
          if (h.expanded !== "true") fail(`${at}: the stopped turn this page watched end is drawn folded`);
          // U2 review: the line's tag says it; the mark would say it a second time.
          if (shownMarks) fail(`${at}: the open stopped turn shows its Interrupted mark beside its line's tag`);
        } else if (shownMarks !== 1) fail(`${at}: the stopped turn, with no line, shows ${shownMarks} Interrupted marks, not its one`);
        try {
          await serverTurn(t, TF_CHAT, "Run the tests again (turn-fold, after the stop).", 60_000);
        } catch (e) {
          return fail(`the turn after the stop could not run: ${(e as Error).message}`, "run");
        }
        if (h) {
          const after = await tfUntil(page, (s) => s.turns.find((x) => x.id === h.id)?.expanded === "false", 4000);
          const left = (await page.evaluate<number>(marks)) - marksBefore;
          details.stoppedFolded = { line: after.s.turns.find((x) => x.id === h.id), marks: left };
          if (!after.ok) fail(`${at}: the stopped turn did not fold when the next turn started`);
          else if (left) fail(`${at}: the folded stopped turn still shows its Interrupted mark beside its tag`);
          const tagged = await page.locate(`[data-turn-id="${h.id}"] button.chat-turn-line`);
          if (tagged) await tfShot(page, shotName("main", "turn-fold", vp, theme, "interrupted"));
        } else {
          await sleep(600);
          const left = (await page.evaluate<number>(marks)) - marksBefore;
          details.stoppedAfter = { marks: left };
          if (left !== 1) fail(`${at}: after the next turn the stopped turn (no line) shows ${left} Interrupted marks, not its one`);
          await tfShot(page, shotName("main", "turn-fold", vp, theme, "interrupted"));
        }

        // A view switch while scrolled up keeps the reader's row (the first one whose bottom is below the top) in place.
        await tfPress(page, big.id);
        await tfUntil(page, (s) => tfBig(s)?.expanded === "true", 3000);
        await page.evaluate(tfScrollRow(`[data-item-id="${TF_REPLY_ROW}"]`, 4));
        await page.evaluate(P2_DRAWN);
        const anchored = await page.evaluate<{ top: number } | null>(tfRow(`[data-item-id="${TF_REPLY_ROW}"]`));
        const moves: (number | null)[] = [];
        for (let i = 0; i < 3; i++) {
          await tfCtrlO(page);
          await sleep(300);
          moves.push((await page.evaluate<{ top: number } | null>(tfRow(`[data-item-id="${TF_REPLY_ROW}"]`)))?.top ?? null);
        }
        details.viewSwitch = { anchored, moves };
        if (!anchored || moves.some((m) => m === null || Math.abs(m - anchored.top) > 2)) fail(`${at}: the reader's row moved on a view switch (${anchored?.top} px, then ${JSON.stringify(moves)})`);
        await tfPress(page, big.id);

        // The next page drawn shows the watched turn folded.
        const later = await draw(chatPath);
        if (later.s.turns.find((x) => x.id === watched.id)?.expanded !== "false") fail(`${at}: drawn again, the watched turn is not folded`);
      }

      issueFindings(page.takeIssues(), failures);
      // Opening, closing, links, Find and the views send nothing that acts; the live run's one Stop sends its interrupt.
      const acts = acting(wire.framesSince(0));
      const stops = acts.filter((f) => f.t === "interrupt");
      if (acts.length !== stops.length || stops.length !== (liveRun ? 1 : 0)) fail(`${at}: the page sent ${clipList(acts.map(frameText)) || "nothing"}${liveRun ? ", not the one interrupt of its Stop" : ""}`, "frames");
      const posts = wire.httpSince(0).filter((h) => MUTATING_METHODS.has(h.method));
      if (posts.length) fail(`${at}: the page sent ${clipList(posts.map(httpText))}`, "frames");
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return finish({ kind: "flow", name: "turn-fold", route: "chat", scene: "main", size: sizeTag(vp), theme, path: chatPath, failures, warnings, note: look === "glass" ? (liveRun ? "with the timing rule live" : "") : `the ${look} look`, ms: Date.now() - t0, details, shot });
}

/** U2's runs on one seed of the main scene (none with --base): the laptop's, each look's, then the phone's. */
async function turnFoldFlows(record: (r: CheckResult) => void, problems: string[]): Promise<void> {
  if (BASE) {
    console.log("ui-check: turn-fold boots a seed of its own (the main scene), so --base runs none of it");
    return;
  }
  const laptop = CORE.some((v) => v.name === "laptop") ? WIDE_LAPTOP : null;
  const phone = CORE.find((v) => v.name === "phone") ?? null;
  const runs: { vp: Viewport; theme: Theme; look: P2LookId; live: boolean }[] = [];
  if (laptop) for (const theme of THEMES) runs.push({ vp: laptop, theme, look: "glass", live: theme === "light" });
  if (laptop && THEMES.includes("light")) for (const look of P2_LOOKS.filter((l) => l !== "glass")) runs.push({ vp: laptop, theme: "light", look, live: false });
  if (phone) for (const theme of THEMES) runs.push({ vp: phone, theme, look: "glass", live: theme === "light" });
  // The tablet (834x1194 touch), light: the folded draw, open and close, links, Find and the views.
  const tablet = CORE.find((v) => v.name === "medium") ?? null;
  if (tablet && THEMES.includes("light")) runs.push({ vp: tablet, theme: "light", look: "glass", live: false });
  for (const vp of extraAt("turn-fold")) runs.push({ vp, theme: THEMES.includes("light") ? "light" : THEMES[0]!, look: "glass", live: false });
  if (!runs.length || cdp.closed) return;
  let b: Booted;
  try {
    b = await boot({ scene: "main", port: PORT, dist: built!, keep: KEEP, env: SERVER_ENV });
  } catch (e) {
    for (const r of runs) record(finish({ kind: "flow", name: "turn-fold", route: "chat", scene: "main", size: sizeTag(r.vp), theme: r.theme, path: `/c/${TF_CHAT}`, failures: [{ code: "seed", text: `the seed did not boot: ${(e as Error).message}` }], warnings: [], note: "", ms: 0, details: {} }));
    return;
  }
  live.add(b);
  try {
    for (const r of runs) {
      if (cdp.closed) break;
      record(await turnFoldRun(b, r.vp, r.theme, r.look, r.live));
    }
  } finally {
    const r = await b.stop();
    live.delete(b);
    if (r.code !== 0) problems.push(`scene main (turn-fold): the server exited with ${r.code}`);
    if (r.leftovers.length) problems.push(`scene main (turn-fold): ${r.leftovers.length} process(es) outlived the server and were ended by pid`);
  }
}

// ---------------------------------------------------------------------------------------------------------------
// U1 (FIX-U1 section 2, DESIGN-U1): changes-card, the changed-files card at a turn's end and its diffs in the side
// panel. It boots one seed of the main scene of its own, whose example project folder is a git repository, and runs
// one live turn on the example chat (the fixture's resume turn: a reply, a Bash call whose permission card keeps the
// call's run window open, then a reply): while the reply streams, before any tool runs, the flow writes one file in the
// folder (left out of the turn's, counted); while the card waits, it changes three (two edits and a new file), then
// presses Allow once. Runs: 1280x800 dark (the live turn and every step), 1280x800 light, and at 1280x800 light each
// other look; 1194x834 with touch, dark and light; 390x844 with touch, dark and light:
// - the card under the turn's answer, after its last reply (outside the folded work): "3 files changed" and the turn's
//   counts, a row per file in path order with its counts (+N in --ok, -N in --danger, a 0 left blank), each a link; the
//   files changed outside a tool's run (one while the reply streams, one while the permission card waits) are not on it;
// - its head opens the turn's list in the side panel at the Terminal's width (512 px at 1280, the chat 520): "Changes",
//   the counts, Close changes, the three files, and the foot line for the two left out; the head is marked;
// - a file of the list opens its diff in the same place (both line numbers, the signs, the tints, long lines wrapping,
//   no sideways scroll), and the card marks that row; the Terminal opened from the title bar goes below the diff (the
//   URL's below=shell); another row of the card opens its diff above the Terminal; Back gives the first diff again; a
//   reload the same pair; Close changes gives the Terminal the column; the list again, then Esc inside it closes it and
//   the focus goes back to the card's head;
// - the light theme and the looks: the card from history (one chat on every device) and the diff above the Terminal;
// - the tablet: the diff in the docked pane at 40% of the window (478 px), the card's rows 44 px;
// - the phone (row 115): a changes route opens the chat with the card's line in the middle, marked, no link and no row,
//   no changes view; the URL is not rewritten;
// - after the turn nothing that acts goes out (only reads); no console error, no failed request, no sideways scroll.

/** The card, the changes view and the side panel's halves as the page shows them. */
interface CcState {
  path: string;
  cards: {
    id: string;
    head: { words: string; label: string; current: boolean; h: number } | null;
    rows: { path: string; label: string; add: string; del: string; current: boolean; h: number }[];
    more: string | null;
    line: string | null;
    links: number;
    marked: boolean;
    /** The card comes after the turn's last reply, and is in no folded work. */
    afterReply: boolean;
    hidden: boolean;
    mid: number;
  }[];
  view: { mode: string; title: string; width: number; rows: string[]; current: string | null; foot: string[]; say: string[]; diff: number; numbered: number; seams: number; wrap: string | null; overflow: boolean; closeName: string | null } | null;
  halves: { slot: string; kind: string }[];
  side: number | null;
  main: number | null;
  focus: string | null;
  scrollMid: number | null;
  /** The chat's scroller is at its end (its last row cannot come higher). */
  atEnd: boolean;
  notices: string[];
  scrollWidth: number;
  clientWidth: number;
}

const CC_STATE = `JSON.stringify((() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && !el.closest("[hidden]");
  const txt = (el) => (el ? (el.textContent || "").replace(/\\s+/g, " ").trim() : "");
  const cards = [...document.querySelectorAll('[data-testid="changes-card"]')].map((c) => {
    const head = c.querySelector(".chg-head");
    const rows = [...c.querySelectorAll('[data-testid="changes-row"]')].map((r) => ({ path: r.querySelector(".side-pl")?.getAttribute("title") || "", label: r.getAttribute("aria-label") || "", add: txt(r.querySelector(".is-add")), del: txt(r.querySelector(".is-del")), current: r.getAttribute("aria-current") === "page", h: Math.round(r.getBoundingClientRect().height) }));
    const all = [...document.querySelectorAll(".chat-col [data-item-id]")];
    const before = c.previousElementSibling;
    const replies = [...document.querySelectorAll(".chat-col > .chat-item-assistant")];
    const lastReply = replies.filter((x) => x.compareDocumentPosition(c) & Node.DOCUMENT_POSITION_FOLLOWING).pop();
    const b = c.getBoundingClientRect();
    return {
      id: c.getAttribute("data-changes") || "",
      head: head ? { words: txt(head.querySelector(".chg-title")), label: head.getAttribute("aria-label") || "", current: head.getAttribute("aria-current") === "page", h: Math.round(head.getBoundingClientRect().height) } : null,
      rows,
      more: txt(c.querySelector('[data-testid="changes-more"]')) || null,
      line: c.querySelector(".chg-line-phone") ? [txt(c.querySelector(".chg-line-phone .chg-title")), ...[...c.querySelectorAll(".chg-line-phone .chg-count > span")].map(txt)].filter(Boolean).join(" ") : null,
      links: c.querySelectorAll("a").length,
      marked: c.classList.contains("is-highlight"),
      afterReply: !!lastReply && !c.closest("[data-turn-work]") && !!before && all.length > 0,
      hidden: !shown(c),
      mid: Math.round(b.top + b.height / 2),
    };
  });
  const v = [...document.querySelectorAll('[data-testid="changes-view"]')].find(shown) || null;
  const lt = v ? v.querySelector(".chg-lt") : null;
  const view = v ? {
    mode: v.getAttribute("data-view") || "",
    title: v.getAttribute("aria-label") || "",
    width: Math.round(v.getBoundingClientRect().width),
    rows: [...v.querySelectorAll('[data-testid="changes-list-row"]')].map((r) => r.getAttribute("aria-label") || ""),
    current: v.querySelector(".chg-file-name") ? txt(v.querySelector(".chg-file-name")) : null,
    foot: [...v.querySelectorAll(".chg-foot")].map(txt),
    say: [...v.querySelectorAll('[data-testid="changes-line"]')].map(txt),
    diff: v.querySelectorAll(".chg-dl").length,
    numbered: [...v.querySelectorAll(".chg-dl .chg-ln")].filter((n) => txt(n) !== "").length,
    seams: v.querySelectorAll(".chg-hunk.is-seam").length,
    wrap: lt ? getComputedStyle(lt).whiteSpace : null,
    overflow: [...v.querySelectorAll(".chg-scroll")].some((s) => s.scrollWidth > s.clientWidth + 1),
    closeName: v.querySelector('[data-testid="changes-close"]')?.getAttribute("aria-label") || null,
  } : null;
  const side = document.getElementById("fd-side") || document.querySelector(".side-over");
  const main = document.querySelector(".shell > .main-col");
  const sc = [...document.querySelectorAll(".chat-scroll")].find(shown);
  const at = document.activeElement;
  return {
    path: location.pathname + location.search,
    cards,
    view,
    halves: side ? [...side.querySelectorAll(":scope > .split-half[data-half]")].map((h) => ({ slot: h.getAttribute("data-half"), kind: h.getAttribute("data-kind") })) : [],
    side: shown(side) ? Math.round(side.getBoundingClientRect().width) : null,
    main: shown(main) ? Math.round(main.getBoundingClientRect().width) : null,
    focus: at && at !== document.body ? at.getAttribute("data-testid") || at.getAttribute("aria-label") || at.tagName.toLowerCase() : null,
    scrollMid: sc ? Math.round(sc.getBoundingClientRect().top + sc.clientHeight / 2) : null,
    atEnd: sc ? sc.scrollHeight - sc.scrollTop - sc.clientHeight < 2 : false,
    notices: [...document.querySelectorAll('[data-testid="link-notice"]')].filter(shown).map(txt),
    scrollWidth: document.documentElement.scrollWidth,
    clientWidth: document.documentElement.clientWidth,
  };
})())`;

/** The live turn: the fixture's resume turn (a reply, a Bash call with its permission card, a reply). */
const CC_TURN = resumeTurn("changes-laptop");
/**
 * The three files the live turn's Bash call changes after its card's Allow, in path order; the one the user writes
 * while the reply streams, and the one the user writes while the card waits (U1 review: no tool runs then either).
 */
const CC_FILES = ["docs/UPLOAD-RETRIES.md", "src/upload.ts", "test/upload-wait.test.ts"] as const;
const CC_OTHER = "notes/scratch.md";
const CC_WAITING = "notes/while-asked.md";
const CC_EDITED = "src/upload.ts";
/** The tablet in landscape (DESIGN-U1 13.3: the changes pane at 40% of the window). */
const CC_TABLET: Viewport = { name: "medium", width: 1194, height: 834, scale: 2, mobile: true, touch: true };

/** What the live turn found, for the runs after it. */
interface CcFound {
  id: string;
  chat: string;
}

/** The change while the reply streams (no tool runs): left out of the turn's, counted in the list's foot. */
function ccWriteOther(folder: string) {
  mkdirSync(join(folder, "notes"), { recursive: true });
  writeFileSync(join(folder, CC_OTHER), "# Scratch\n\nA note the user wrote while Claude answered.\n");
}

/** The user's change while the Bash call's permission card waits: the call has not run, so it is not the turn's. */
function ccWriteWaiting(folder: string) {
  mkdirSync(join(folder, "notes"), { recursive: true });
  writeFileSync(join(folder, CC_WAITING), "A line the user wrote at the laptop while the card waited.\n");
}

/** The turn's own changes, while its Bash call runs (after the card's Allow): two edits and a new file. */
function ccWriteTurn(folder: string) {
  const up = join(folder, "src", "upload.ts");
  const was = readFileSync(up, "utf8");
  const next = was
    .replace("// Upload one file with up to three tries.", "// Upload one file with up to three tries, the wait between them doubling from RETRY_MS.\nconst RETRY_MS = 200;\n\n//")
    .replace("    await new Promise((r) => setTimeout(r, 200 * 2 ** attempt));", "    // The last try needs no wait after it: the error goes to the caller at once, with the reason of the last failure that came back from the server.\n    if (attempt < 2) await new Promise((r) => setTimeout(r, RETRY_MS * 2 ** attempt));");
  writeFileSync(up, next);
  const doc = join(folder, "docs", "UPLOAD-RETRIES.md");
  writeFileSync(doc, `${readFileSync(doc, "utf8")}\nThe last try has no wait after it: its error goes to the caller at once.\n`);
  mkdirSync(join(folder, "test"), { recursive: true });
  writeFileSync(
    join(folder, "test", "upload-wait.test.ts"),
    'import { expect, test } from "bun:test";\nimport { uploadFile } from "../src/upload";\nimport { fakeFetch } from "./helpers/fake-fetch";\n\ntest("upload > no wait after the last try", async () => {\n  const fetch = fakeFetch({ failFirst: 3 });\n  const started = Date.now();\n  await expect(uploadFile("http://upload.test/file", new Blob(["hello"]).stream())).rejects.toThrow();\n  expect(Date.now() - started).toBeLessThan(700);\n  expect(fetch.bodies.length).toBe(3);\n});\n',
  );
}

/** Wait for a check that reads the page (untilTrue's form for an async check). */
async function ccWait(ok: () => Promise<boolean>, ms: number): Promise<boolean> {
  const end = Date.now() + ms;
  while (!(await ok().catch(() => false))) {
    if (Date.now() > end) return false;
    await sleep(120);
  }
  return true;
}

async function ccUntil(page: Page, ok: (s: CcState) => boolean, ms = 8000): Promise<{ ok: boolean; s: CcState }> {
  const end = Date.now() + ms;
  let s = JSON.parse(await page.evaluate<string>(CC_STATE)) as CcState;
  while (!ok(s) && Date.now() < end) {
    await sleep(120);
    s = JSON.parse(await page.evaluate<string>(CC_STATE)) as CcState;
  }
  return { ok: ok(s), s };
}

/** A still with no hover under the pointer and the machine's name masked. */
async function ccShot(page: Page, file: string) {
  if (!page.vp.touch) await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: 4, y: Math.round(page.vp.height / 2) });
  await sleep(200);
  await maskMachine(page);
  await page.screenshot(file).catch(() => {});
}

async function changesCardFlows(record: (r: CheckResult) => void, problems: string[]): Promise<void> {
  if (BASE) {
    console.log("ui-check: changes-card boots a seed of its own (the main scene), so --base runs none of it");
    return;
  }
  const laptop = CORE.some((v) => v.name === "laptop") ? WIDE_LAPTOP : null;
  const runs: { vp: Viewport; theme: Theme; look: P2LookId; live: boolean }[] = [];
  if (laptop) {
    runs.push({ vp: laptop, theme: THEMES.includes("dark") ? "dark" : "light", look: "glass", live: true });
    if (THEMES.includes("light") && THEMES.includes("dark")) runs.push({ vp: laptop, theme: "light", look: "glass", live: false });
    if (THEMES.includes("light")) for (const look of P2_LOOKS.filter((l) => l !== "glass")) runs.push({ vp: laptop, theme: "light", look, live: false });
  }
  if (CORE.some((v) => v.name === "medium")) for (const theme of THEMES) runs.push({ vp: CC_TABLET, theme, look: "glass", live: false });
  const phone = CORE.find((v) => v.name === "phone") ?? null;
  if (phone) for (const theme of THEMES) runs.push({ vp: phone, theme, look: "glass", live: false });
  for (const vp of extraAt("changes-card")) runs.push({ vp, theme: THEMES[0]!, look: "glass", live: false });
  if (!runs.length || cdp.closed) return;
  // The live turn runs on the laptop; without the laptop size the first run makes it at 1280x800.
  if (!runs.some((r) => r.live)) runs.unshift({ vp: WIDE_LAPTOP, theme: THEMES[0]!, look: "glass", live: true });
  let b: Booted;
  try {
    b = await boot({ scene: "main", port: PORT, dist: built!, keep: KEEP, env: SERVER_ENV });
  } catch (e) {
    for (const r of runs) record(finish({ kind: "flow", name: "changes-card", route: "changesTurn", scene: "main", size: sizeTag(r.vp), theme: r.theme, path: `/c/${EX.chat}`, failures: [{ code: "seed", text: `the seed did not boot: ${(e as Error).message}` }], warnings: [], note: "", ms: 0, details: {} }));
    return;
  }
  live.add(b);
  let found: CcFound | null = null;
  try {
    for (const r of runs) {
      if (cdp.closed) break;
      const res = await changesCardRun(b, r.vp, r.theme, r.look, r.live, found);
      if (r.live) found = res.found;
      record(res.result);
    }
  } finally {
    const r = await b.stop();
    live.delete(b);
    if (r.code !== 0) problems.push(`scene main (changes-card): the server exited with ${r.code}`);
    if (r.leftovers.length) problems.push(`scene main (changes-card): ${r.leftovers.length} process(es) outlived the server and were ended by pid`);
  }
}

async function changesCardRun(b: Booted, vp: Viewport, theme: Theme, look: P2LookId, liveRun: boolean, found: CcFound | null): Promise<{ result: CheckResult; found: CcFound | null }> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = { look };
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const chat = EX.chat;
  const P = (rest: string) => `/c/${chat}/${rest}`;
  const tag = look === "glass" ? "" : `-${look}`;
  const at = `${vp.width}x${vp.height} ${theme}${look === "glass" ? "" : `, ${look}`}`;
  const step = (label: string) => shotName("main", "changes-card", vp, theme, `${label}${tag}`);
  let shot: string | undefined;
  let out: CcFound | null = found;
  let path = `/c/${chat}`;
  const steps: Record<string, unknown>[] = [];
  const note = (label: string, s: CcState) => {
    steps.push({ step: label, path: s.path, cards: s.cards.map((c) => `${c.id} ${c.head?.words ?? c.line ?? ""} ${c.rows.map((r) => `${r.path}${r.current ? "*" : ""}`).join(",")}`), view: s.view ? `${s.view.mode} ${s.view.title} ${s.view.width}px rows ${s.view.rows.length} diff ${s.view.diff}` : null, halves: s.halves.map((h) => `${h.slot} ${h.kind}`), side: s.side, main: s.main, focus: s.focus, notices: s.notices });
    if (s.scrollWidth > s.clientWidth) fail(`${at}, ${label}: the page scrolls sideways (${s.scrollWidth} > ${s.clientWidth})`, "overflow");
    if (s.notices.length) fail(`${at}, ${label}: a 5.4 line shows: ${clipList(s.notices)}`, "notice");
    if (s.view?.overflow) fail(`${at}, ${label}: the changes view scrolls sideways (a long line does not wrap)`, "overflow");
  };
  const ours = (s: CcState) => (out ? s.cards.find((c) => c.id === out!.id) : undefined);
  try {
    await withPage(vp, theme, async (page, wire) => {
      const folder = b.seed.folders.kitespan;
      if (liveRun) {
        // ---- the live turn: one change while the reply streams, one while the Bash call's card waits (both the user's),
        // three after the Allow while the call runs (the turn's)
        await page.navigate(b.base + path);
        await waitShown(page, ["chat", "conversation", "composer"], 8000);
        const before = await ccUntil(page, () => true, 0);
        const had = new Set(before.s.cards.map((c) => c.id));
        details.seededCards = [...had];
        if (!(await sendFromBox(page, CC_TURN.text))) return fail(`${at}: the message box could not send the turn's message`);
        const streaming = await ccWait(() => page.evaluate<boolean>(`!!document.querySelector('[data-item-id="${CC_TURN.ids.a}-0"]')`), 15_000);
        if (!streaming) return fail(`${at}: the turn's first reply never came`);
        await sleep(400);
        ccWriteOther(folder);
        if (!(await ccWait(() => page.evaluate<boolean>(`!!document.querySelector('[data-testid="card-permission"]')`), 20_000))) return fail(`${at}: the turn's Bash call never asked for its permission`);
        await sleep(300);
        ccWriteWaiting(folder);
        await sleep(300);
        if (!(await pressOn(page, '[data-testid="card-permission"] [data-testid="confirm-once"]'))) return fail(`${at}: the card shows no Allow once`);
        // The command runs from the Allow (the card's close reaches the page after the server opened the call's window)
        // to its result 1.5 s later: its files change in that time.
        if (!(await ccWait(() => page.evaluate<boolean>(`!document.querySelector('[data-testid="card-permission"]')`), 5_000))) return fail(`${at}: the card did not close after Allow once`);
        await sleep(150);
        ccWriteTurn(folder);
        const came = await ccUntil(page, (s) => s.cards.some((c) => !had.has(c.id)), 25_000);
        const card = came.s.cards.find((c) => !had.has(c.id));
        details.card = card;
        note("the turn's end", came.s);
        if (!card) return fail(`${at}: no changes card came after the turn's end (25 s)`);
        out = { id: card.id, chat };
        const quiet = wire.mark();
        // The card: under the answer, "3 files changed", one row per file in path order, never the other file.
        if (card.hidden || !card.afterReply) fail(`${at}: the card is ${card.hidden ? "hidden (folded with the work?)" : "not after the turn's last reply"}`);
        if (card.head?.words !== "3 files changed") fail(`${at}: the card's head says ${JSON.stringify(card.head?.words ?? null)}, not "3 files changed"`);
        if (card.rows.map((r) => r.path).join(",") !== CC_FILES.join(",")) fail(`${at}: the card's rows are ${JSON.stringify(card.rows.map((r) => r.path))}, not ${JSON.stringify(CC_FILES)}`);
        for (const p of [CC_OTHER, CC_WAITING]) if (card.rows.some((r) => r.path === p)) fail(`${at}: the card counts ${p}, which changed while no tool ran`);
        const edited = card.rows.find((r) => r.path === CC_EDITED);
        if (!edited || !/^\+\d+$/.test(edited.add) || !/^-\d+$/.test(edited.del)) fail(`${at}: ${CC_EDITED}'s counts read ${JSON.stringify(edited ? [edited.add, edited.del] : null)}`);
        const fresh = card.rows.find((r) => r.path === "test/upload-wait.test.ts");
        if (fresh && fresh.del !== "") fail(`${at}: the new file's removed count shows ${JSON.stringify(fresh.del)}, not blank`);
        if (card.rows.some((r) => r.h < 24 || r.h > 34)) fail(`${at}: the card's rows are ${card.rows.map((r) => r.h).join(", ")} px tall, not the look's row height`);
        shot = step("card");
        await ccShot(page, shot);

        // ---- the head: the turn's list in the side panel at the Terminal's width, the head marked
        if (!(await pressOn(page, `[data-changes="${card.id}"] .chg-head`))) return fail(`${at}: the card has no head to press`);
        // The list draws the card's own files at once, and the summary's foot line when its read comes.
        let s = (await ccUntil(page, (x) => x.view?.mode === "list" && x.view.rows.length > 0 && x.view.foot.length > 0)).s;
        note("list", s);
        if (!sameUrl(s.path, P(`changes/${card.id}`))) fail(`${at}: the head opened ${s.path}, not /c/<chat>/changes/<turn>`, "url");
        if (s.view?.title !== "Changes" || s.view.closeName !== "Close changes") fail(`${at}: the list is named ${JSON.stringify(s.view?.title)} with ${JSON.stringify(s.view?.closeName)}`);
        if ((s.view?.rows.length ?? 0) !== 3) fail(`${at}: the list shows ${s.view?.rows.length ?? 0} files, not 3: ${clipList(s.view?.rows ?? [])}`);
        if (!s.view?.foot.includes("2 other files changed while Claude was not running a tool.")) fail(`${at}: the list's foot says ${JSON.stringify(s.view?.foot ?? [])}, not the two files left out`);
        if (s.side !== 512 || s.main !== 520) fail(`${at}: the column is ${s.side} px and the chat ${s.main} px, not the Terminal's 512 and 520`);
        if (!ours(s)?.head?.current) fail(`${at}: the card's head is not marked while the panel shows its list`);
        if (s.focus !== "changes-view" && s.focus !== "Changes") warnings.push({ code: "focus", text: `${at}: the list's region did not take the focus (${s.focus})` });
        shot = step("list");
        await ccShot(page, shot);

        // ---- a file of the list: its diff in the same place, both numbers, wrapping; the card marks the row
        if (!(await pressOn(page, `[data-testid="changes-view"] [data-testid="changes-list-row"][aria-label^="${CC_EDITED},"]`))) return fail(`${at}: the list has no row for ${CC_EDITED}`);
        s = (await ccUntil(page, (x) => x.view?.mode === "file" && x.view.diff > 0)).s;
        note("diff", s);
        if (!sameUrl(s.path, P(`changes/${card.id}/${CC_EDITED}`))) fail(`${at}: the row opened ${s.path}`, "url");
        if (s.view?.current !== "upload.ts") fail(`${at}: the diff's title is ${JSON.stringify(s.view?.current)}`);
        if (!s.view || s.view.numbered < s.view.diff) fail(`${at}: the diff's lines carry ${s.view?.numbered ?? 0} numbers for ${s.view?.diff ?? 0} lines (both columns expected)`);
        if (s.view?.wrap !== "pre-wrap") fail(`${at}: the diff's lines do not wrap (white-space ${s.view?.wrap})`);
        if (!ours(s)?.rows.find((r) => r.path === CC_EDITED)?.current) fail(`${at}: the card does not mark ${CC_EDITED}'s row while its diff shows`);
        shot = step("diff");
        await ccShot(page, shot);

        // ---- the Terminal (Ctrl+backtick, nothing typed) goes below the diff; another row of the card opens above it.
        // The Terminal is then the URL's own view (the one used last): /c/<chat>/shell?above=changes/<turn>/<path>.
        for (const type of ["rawKeyDown", "keyUp"]) await page.send("Input.dispatchKeyEvent", { type, key: "`", code: "Backquote", windowsVirtualKeyCode: 192, nativeVirtualKeyCode: 192, modifiers: 2 });
        s = (await ccUntil(page, (x) => x.halves.length === 2, 10_000)).s;
        note("diff above the Terminal", s);
        const firstPair = P(`shell?above=changes/${card.id}/${CC_EDITED}`);
        if (s.halves.map((h) => `${h.slot} ${h.kind}`).join() !== "upper changes,lower terminal") fail(`${at}: with the Terminal the halves are ${JSON.stringify(s.halves)}`);
        if (!sameUrl(s.path, firstPair)) fail(`${at}: the pair's URL is ${s.path}, not ${firstPair}`, "url");
        shot = step("diff-term");
        await ccShot(page, shot);
        const other = CC_FILES[2];
        if (!(await pressOn(page, `[data-changes="${card.id}"] [data-testid="changes-row"][aria-label^="${other},"]`))) return fail(`${at}: the card has no row for ${other}`);
        s = (await ccUntil(page, (x) => x.view?.current === "upload-wait.test.ts" && x.view.diff > 0)).s;
        note("another file", s);
        if (!sameUrl(s.path, P(`changes/${card.id}/${other}?below=shell`))) fail(`${at}: the second row opened ${s.path}, not its diff above the Terminal`, "url");
        if (s.halves.map((h) => h.kind).join() !== "changes,terminal") fail(`${at}: the second diff's halves are ${JSON.stringify(s.halves)}`);
        // A new file has one side: one number column (DiffBody's --ln-n).
        const cols = await page.evaluate<string>(`getComputedStyle([...document.querySelectorAll('[data-testid="changes-diff"]')].find((e) => e.getClientRects().length > 0)).getPropertyValue("--ln-n").trim()`);
        if (cols !== "1") fail(`${at}: the new file's diff has ${cols} number columns, not one`);
        await ccShot(page, step("diff-new"));

        // ---- Back, a reload, Close changes
        await page.send("Runtime.evaluate", { expression: "history.back()" });
        s = (await ccUntil(page, (x) => x.view?.current === "upload.ts" && x.view.diff > 0)).s;
        note("Back", s);
        if (!sameUrl(s.path, firstPair)) fail(`${at}: Back gave ${s.path}, not the first diff above the Terminal`, "url");
        await page.reload();
        await waitShown(page, ["chat", "changes-view"], 8000);
        s = (await ccUntil(page, (x) => x.view?.mode === "file" && x.view.diff > 0 && x.halves.length === 2)).s;
        note("reload", s);
        if (!sameUrl(s.path, firstPair) || s.halves.length !== 2) fail(`${at}: after a reload ${s.path} shows ${JSON.stringify(s.halves)}`);
        if (!(await pressOn(page, '[data-testid="changes-view"] [data-testid="changes-close"]'))) return fail(`${at}: the diff has no Close changes`);
        s = (await ccUntil(page, (x) => !x.view)).s;
        note("Close changes", s);
        if (!sameUrl(s.path, P("shell")) || s.halves.length) fail(`${at}: Close changes left ${s.path} with ${JSON.stringify(s.halves)}, not the Terminal alone`);

        // ---- the list again from the head, then Esc inside it: closed, the focus back on the head
        if (!(await pressOn(page, `[data-changes="${card.id}"] .chg-head`))) return fail(`${at}: the card has no head to press again`);
        s = (await ccUntil(page, (x) => x.view?.mode === "list")).s;
        if (!sameUrl(s.path, P(`changes/${card.id}?below=shell`))) fail(`${at}: the head with the Terminal open gave ${s.path}, not the list above the Terminal`, "url");
        await page.evaluate(`(() => { const v = document.querySelector('[data-testid="changes-view"]'); if (v) v.focus(); return !!v; })()`);
        await page.key("Escape");
        s = (await ccUntil(page, (x) => !x.view)).s;
        note("Esc", s);
        if (s.view || !sameUrl(s.path, P("shell"))) fail(`${at}: Esc inside the list left ${s.path}${s.view ? " with the list" : ""}`);
        const focused = await page.evaluate<boolean>(`(() => { const a = document.activeElement; return !!a && !!a.closest('[data-changes="${card.id}"]') && a.classList.contains("chg-head"); })()`);
        if (!focused) fail(`${at}: after Esc the focus is on ${s.focus}, not the card's head that opened the list`, "focus");
        // ---- over the chat (a 1,050 px window with the sidebar docked): the list in the layer, at the Terminal's width
        // for that window (420 px); Esc closes it to the chat.
        await page.navigate(b.base + P(`changes/${card.id}`));
        await waitShown(page, ["chat", "changes-view"], 8000);
        await splitWindow(page, 1050);
        s = (await ccUntil(page, (x) => x.view?.mode === "list" && x.view.rows.length === 3 && x.side === 420)).s;
        note("over the chat", s);
        const over = await page.evaluate<boolean>(`!!document.querySelector('.side-over [data-testid="changes-view"]')`);
        if (!over || s.side !== 420) fail(`${at}: at 1,050 px the list is ${over ? `over the chat at ${s.side} px, not 420` : "not over the chat"}`);
        await ccShot(page, step("over"));
        await page.key("Escape");
        s = (await ccUntil(page, (x) => !x.view)).s;
        if (s.view || !sameUrl(s.path, `/c/${chat}`)) fail(`${at}: Esc over the chat left ${s.path}${s.view ? " with the list" : ""}`);
        await splitWindow(page, vp.width);
        path = P(`changes/${card.id}`);
        details.steps = steps;
        quietFindings(wire, quiet, null, failures, `${at}, after the turn: `);
      } else {
        if (!out) return fail(`${at}: the live turn made no card, so this run has nothing to open`);
        const pair = P(`changes/${out.id}/${CC_EDITED}${vp.name === "laptop" ? "?below=shell" : ""}`);
        path = pair;
        const since = wire.mark();
        await page.navigate(b.base + pair);
        await waitShown(page, ["chat", "conversation"], 8000);
        if (look !== "glass") await wearLook(page, look, theme);
        if (vp.name === "phone") {
          // The phone (row 115): the chat at the card's line, marked; no view, no link; the URL as it was.
          const s = (await ccUntil(page, (x) => !!ours(x)?.marked, 10_000)).s;
          note("phone", s);
          const c = ours(s);
          if (!c) return fail(`${at}: the chat shows no line for the turn's changes`);
          if (s.view) fail(`${at}: the phone shows the changes view (row 115: no diff on the phone)`);
          if (c.links || c.rows.length || c.head) fail(`${at}: the phone's line has ${c.links} links and ${c.rows.length} rows (one plain line expected)`);
          if (!/^3 files changed \+\d+ -\d+$/.test(c.line ?? "")) fail(`${at}: the phone's line reads ${JSON.stringify(c.line)}`);
          if (!c.marked) fail(`${at}: the phone's line is not marked as a linked message is`);
          // In the middle, unless the chat is at its end and the line is its last row (it cannot come higher).
          if (s.scrollMid !== null && Math.abs(c.mid - s.scrollMid) > 80 && !(s.atEnd && c.mid > s.scrollMid)) warnings.push({ code: "place", text: `${at}: the line's middle is ${c.mid - s.scrollMid} px from the chat's middle` });
          if (!sameUrl(s.path, pair)) fail(`${at}: the phone rewrote the link to ${s.path}`, "url");
          shot = step("phone");
          await ccShot(page, shot);
        } else {
          // v0.6 touch: the large tablet in portrait shows the path's view alone, over the chat (DESIGN 7.4).
          const oneView = vp.touch && vp.name === "laptop" && vp.height > vp.width;
          const s = (await ccUntil(page, (x) => x.view?.mode === "file" && x.view.diff > 0 && (vp.name !== "laptop" || oneView || x.halves.length === 2), 10_000)).s;
          note(vp.name === "medium" ? "tablet" : "pair", s);
          const c = ours(s);
          if (!c) fail(`${at}: the card does not come from history (one chat on every device)`);
          else {
            if (!c.rows.find((r) => r.path === CC_EDITED)?.current) fail(`${at}: the card does not mark ${CC_EDITED}'s row`);
            if (vp.touch && c.rows.some((r) => r.h < 44)) fail(`${at}: the card's rows are ${c.rows.map((r) => r.h).join(", ")} px on touch, under 44`);
          }
          if (vp.name === "medium") {
            // v0.6 touch (T-17, Q1's default): under 800 px the changes view opens over the chat beside the pane bar.
            const want = vp.width < 800 ? vp.width - 56 : 478;
            if (s.side === null || Math.abs(s.side - want) > 2) fail(`${at}: the ${vp.width < 800 ? "changes layer" : "docked pane"} is ${s.side} px, not ${vp.width < 800 ? "the width beside the pane bar" : "40% of the window"} (${want})`);
          } else if (oneView) {
            if (s.halves.length) fail(`${at}: over the chat the changes view shows halves ${JSON.stringify(s.halves)}, not its own view alone`);
          } else if (s.halves.map((h) => h.kind).join() !== "changes,terminal") fail(`${at}: the halves are ${JSON.stringify(s.halves)}`);
          shot = step(vp.name === "medium" ? "tablet" : "diff-term");
          await ccShot(page, shot);
          if (look === "glass" && vp.name === "medium") {
            // The list in the tablet's pane too, its rows 44 px.
            await page.navigate(b.base + P(`changes/${out.id}`));
            const l = (await ccUntil(page, (x) => x.view?.mode === "list" && x.view.rows.length > 0, 8000)).s;
            note("tablet list", l);
            await ccShot(page, step("tablet-list"));
          }
        }
        quietFindings(wire, since, null, failures, `${at}: `);
      }
      stateFindings(await page.probe(), { ...vp }, failures);
      issueFindings(page.takeIssues(), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  details.steps ??= steps;
  const noteText = liveRun
    ? `${at}: a live turn's card (3 files changed, the two changed while no tool ran left out: one while the reply streamed, one while the permission card waited), its list at the Terminal's width with the foot line, a file's diff with both numbers, the Terminal below it, another row, Back, a reload, Close changes, Esc back to the head; nothing acts after the turn`
    : vp.name === "phone"
      ? `${at}: a changes link opens the chat at the card's one line, marked, with no link and no view; the URL kept`
      : vp.name === "medium"
        ? `${at}: the diff in the docked pane at 40% of the window, the card's rows 44 px, the list`
        : `${at}: the card from history with its row marked, the diff above the Terminal`;
  return { result: finish({ kind: "flow", name: "changes-card", route: "changesTurn", scene: "main", size: sizeTag(vp), theme, path, failures, warnings, note: noteText, shot, ms: Date.now() - t0, details }), found: out };
}

// U3 (FIX-U3 section 2, DESIGN-U3): turn-rail, the turn rail on the laptop. It boots one seed of the main scene of its
// own and gives "Try the markdown renderer" 24 more turns through the fake claude (25 in all, one of them the fixture's
// upload-test turn, which folds; every third a longer paced reply), so the example chat (under 5 turns) is the short
// one. Runs: 1280x800 and 1100x800, light and dark, and at 1280x800 light each other look; 834x1194 and 390x844 with
// touch, light; and smooth text with the rail shown (1280x800 light):
// - with the session rail docked, the rail shows exactly where the measured strip between the text and the scroller's
//   edge is 32 px or more (a warning where that differs from DESIGN-U3 2.5's table: Glass and Editor at 1280, not Paper
//   or Mono, not at 1100); with Hide session rail it shows in every look at both sizes;
// - its shape: a navigation list named "Turns", one link per turn in order, each to /c/<chat>/m/<the turn's message>
//   and named by it, one current mark (the last while the view follows the end) and one Tab stop; 12 px right of the
//   text, inside the scroller's client area, above the message box, at most 400 px tall; the ticks 8 px in --faint, 14
//   px in --text for the current one, 12 px in --dim under the pointer;
// - hover: the card (role tooltip) with the turn's prompt and its answer in at most three lines, 4 px right of the text
//   and inside the band; it follows the pointer to the next mark, stays while the pointer is on it and goes when the
//   pointer leaves; focus: the roving mark, Up, Home and End move the focus and its card (aria-describedby), the focus
//   ring shows, Esc hides the card and sends nothing;
// - the current mark follows the reader's scroll; a click jumps (the URL is the mark's, the turn's message lands 24 px
//   below the scroller's top, highlighted, the folded turn stays folded) and Back returns to the reader's first row;
//   on the first run also Forward and Back again, the CLI's `}` and `{` (the turn after and before, landing the same
//   way, with no URL change and no history entry; typed in the message box they are text), and no rail on the short
//   chat;
// - on touch no rail, and a /m/ link still lands its turn at the top, folded;
// - smooth text: the 20,000-character paced reply in the long chat with the rail shown: no change in the rail while
//   it streams, and the main thread's time per frame reported, with a warning above 4 ms;
// - nothing that acts goes out (but the smooth-text run's one send); screenshots with the machine's name shown as
//   "this-machine" (trShot).
// Review U3 (the fix round): the card shows on intent (the pointer rests on the rail, TR_REST), a crossing to a Copy
// opens none and the click copies with the URL kept, a click on the card only closes it, a wheel over a mark and over
// the card scrolls the conversation, a reload after Back opens the chat at its end and drops the kept place; then,
// after smooth text: the running tick in each look (turnRailRunning), smooth text again on the chat with
// TR_LONG_MORE more turns (FIX-U3 1's hundreds of turns; with no rail shown it still measures, so an older build's
// page gives the figure to compare), and a partial chat (turnRailPartial).

const TR_CHAT = IDS.chats.markdown;
/** The long chat's added turns, in order: one is the fixture's upload-test turn (it folds), every third a longer reply. */
const TR_TURNS: string[] = [
  "Add a heading of each level to the sample.",
  "Now a nested list three levels deep.",
  "Explain how the footnotes render. fake-stream 900 3 0",
  WARM.main,
  "Check that long words wrap in a table cell.",
  "Describe the quote styles in detail. fake-stream 1400 4 0",
  "Add a horizontal rule between the parts.",
  "Make the task list items clickable.",
  "Walk me through the code highlighting. fake-stream 1100 3 0",
  "Use a smaller font for the footnotes.",
  "Try a link inside a table cell.",
  "Summarize what renders badly on a phone. fake-stream 1600 4 0",
  "Put the code blocks on a darker background.",
  "Show an image with alt text.",
  "List every option the renderer has. fake-stream 1200 3 0",
  "Rename the sample file to demo.md.",
  "Add a strikethrough example.",
  "Compare the two table styles. fake-stream 1000 3 0",
  "Keep the line length under 80 characters.",
  "Add a definition list.",
  "Write the release note for this. fake-stream 1300 4 0",
  "Test it with right-to-left text.",
  "Add emoji to one heading.",
  "Wrap up: what is left to do? fake-stream 900 3 0",
];
/** The long chat's turns: its seeded one, then TR_TURNS. */
const TR_TOTAL = TR_TURNS.length + 1;
/** The mark the click jumps to: the upload-test turn, which folds, with 20 turns after it (so it can land at the top). */
const TR_JUMP = TR_TURNS.indexOf(WARM.main) + 1;

interface TrMark {
  href: string | null;
  name: string | null;
  current: string | null;
  tab: string | null;
  running: boolean;
  described: string | null;
  x: number;
  y: number;
  tickW: string;
  tickBg: string;
  outline: string;
}
interface TrBox {
  left: number;
  right: number;
  top: number;
  bottom: number;
}
interface TrState {
  path: string;
  rail: boolean;
  strip: number | null;
  textRight: number | null;
  clientRight: number | null;
  /** The scroller's visible top: below the glass look's title bar, where the conversation scrolls under it. */
  bandTop: number | null;
  navBox: TrBox | null;
  wrapBox: TrBox | null;
  composerTop: number | null;
  navName: string | null;
  partial: boolean;
  marks: TrMark[];
  users: { id: string; text: string; top: number }[];
  focus: number | null;
  card: { id: string; role: string | null; prompt: string | null; tag: string | null; answer: string; lines: number; box: TrBox } | null;
  scroll: { top: number; gap: number; h: number } | null;
  tokens: { faint: string; dim: string; text: string; accent: string; ok: string; attn: string };
  wide: boolean;
}

/** In-page: the rail, its marks and card, the strip beside the text (measured here, apart from the page's own rule), the messages. */
const TR_PROBE = `(() => {
  const vis = (el) => !!el && el.getClientRects().length > 0 && el.getBoundingClientRect().height > 0;
  const probe = (v) => { const s = document.createElement("span"); s.style.backgroundColor = v; document.body.appendChild(s); const c = getComputedStyle(s).backgroundColor; s.remove(); return c; };
  const box = (el) => { const r = el.getBoundingClientRect(); const k = (n) => Math.round(n * 10) / 10; return { left: k(r.left), right: k(r.right), top: k(r.top), bottom: k(r.bottom) }; };
  const sc = [...document.querySelectorAll(".chat-scroll")].find(vis);
  const col = sc ? sc.querySelector(".chat-col") : null;
  const wrap = sc ? sc.parentElement : null;
  const nav = [...document.querySelectorAll("nav.chat-rail")].find(vis) || null;
  let strip = null, textRight = null, clientRight = null;
  if (sc && col) {
    const bars = sc.offsetWidth - sc.clientWidth;
    clientRight = sc.getBoundingClientRect().right - bars / 2;
    textRight = col.getBoundingClientRect().right - parseFloat(getComputedStyle(col).paddingRight);
    strip = Math.round(clientRight - textRight);
  }
  const bar = sc ? parseFloat(getComputedStyle(sc).scrollPaddingTop) || 0 : 0;
  const st = sc ? sc.getBoundingClientRect().top + bar : 0;
  const marks = nav ? [...nav.querySelectorAll("a.chat-rail-mark")].map((a) => {
    const r = a.getBoundingClientRect(), b = getComputedStyle(a, "::before");
    return { href: a.getAttribute("href"), name: a.getAttribute("aria-label"), current: a.getAttribute("aria-current"), tab: a.getAttribute("tabindex"), running: a.classList.contains("is-running"), described: a.getAttribute("aria-describedby"), x: r.left + r.width / 2, y: r.top + r.height / 2, tickW: b.width, tickBg: b.backgroundColor, outline: getComputedStyle(a).outlineStyle };
  }) : [];
  const card = [...document.querySelectorAll(".chat-rail-card")].find(vis) || null;
  const ans = card ? card.querySelector(".chat-rail-answer") : null;
  const users = col ? [...col.querySelectorAll(":scope > .chat-item-user[data-item-id]")].map((u) => ({ id: u.getAttribute("data-item-id"), text: ((u.querySelector(".chat-bubble") || {}).textContent || "").trim(), top: Math.round(u.getBoundingClientRect().top - st) })) : [];
  const composer = [...document.querySelectorAll('[data-testid="composer"]')].find(vis);
  const f = document.activeElement && document.activeElement.closest ? document.activeElement.closest("a.chat-rail-mark") : null;
  return {
    path: location.pathname + location.search, rail: !!nav, strip, textRight, clientRight, bandTop: sc ? st : null,
    navBox: nav ? box(nav) : null, wrapBox: wrap ? box(wrap) : null, composerTop: composer ? composer.getBoundingClientRect().top : null,
    navName: nav ? nav.getAttribute("aria-label") : null, partial: nav ? !!nav.querySelector(".chat-rail-more") : false, marks, users,
    focus: f ? Number(f.getAttribute("data-i")) : null,
    card: card ? { id: card.id, role: card.getAttribute("role"), prompt: (card.querySelector(".chat-rail-prompt-text") || {}).textContent ?? null, tag: (card.querySelector(".chat-rail-prompt .chat-tag") || {}).textContent ?? null, answer: ans ? ans.textContent : "", lines: ans ? Math.round(ans.getBoundingClientRect().height / parseFloat(getComputedStyle(ans).lineHeight)) : 0, box: box(card) } : null,
    scroll: sc ? { top: Math.round(sc.scrollTop), gap: Math.round(sc.scrollHeight - sc.scrollTop - sc.clientHeight), h: sc.clientHeight - bar } : null,
    tokens: { faint: probe("var(--faint)"), dim: probe("var(--dim)"), text: probe("var(--text)"), accent: probe("var(--accent)"), ok: probe("var(--ok-fill)"), attn: probe("var(--attn-dot)") },
    wide: document.scrollingElement.scrollWidth > innerWidth + 1,
  };
})()`;

async function trUntil(page: Page, ok: (s: TrState) => boolean, ms: number): Promise<{ ok: boolean; s: TrState }> {
  const end = Date.now() + ms;
  let s = await page.evaluate<TrState>(TR_PROBE);
  while (!ok(s) && Date.now() < end) {
    await sleep(100);
    s = await page.evaluate<TrState>(TR_PROBE);
  }
  return { ok: ok(s), s };
}

/** A screenshot with the machine's own name (D54) shown as "this-machine"; unlike tfShot, the pointer stays (a hover card). */
async function trShot(page: Page, file: string) {
  await maskMachine(page);
  await page.screenshot(file).catch(() => {});
}

const trMouse = (page: Page, x: number, y: number) => page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x, y });

/** A key as a hardware keyboard sends it: `{` and `}` with Shift and their text, the arrows, Home, End and Esc. */
async function trKey(page: Page, key: "{" | "}" | "ArrowUp" | "ArrowDown" | "Home" | "End" | "Escape") {
  const def = { "{": ["BracketLeft", 219, 8], "}": ["BracketRight", 221, 8], ArrowUp: ["ArrowUp", 38, 0], ArrowDown: ["ArrowDown", 40, 0], Home: ["Home", 36, 0], End: ["End", 35, 0], Escape: ["Escape", 27, 0] } as const;
  const [code, vk, modifiers] = def[key];
  const text = key.length === 1 ? { text: key, unmodifiedText: key } : {};
  await page.send("Input.dispatchKeyEvent", { type: "keyDown", key, code, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk, modifiers, ...text });
  await page.send("Input.dispatchKeyEvent", { type: "keyUp", key, code, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk, modifiers });
  await page.evaluate(P2_DRAWN);
}

/** In-page: a row's top below the scroller's visible top (under the glass bar, its scroll padding), and its highlight. */
const trRow = (sel: string) => `(() => {
  const el = document.querySelector(${JSON.stringify(sel)});
  const sc = [...document.querySelectorAll(".chat-scroll")].find((e) => e.getClientRects().length > 0);
  if (!el || !sc) return null;
  const top = sc.getBoundingClientRect().top + (parseFloat(getComputedStyle(sc).scrollPaddingTop) || 0);
  return { top: Math.round(el.getBoundingClientRect().top - top), highlight: el.classList.contains("is-highlight") };
})()`;

/** In-page: the folded state of the turn that a message opens (its line after the message), or null when it has none. */
const trFolded = (id: string) => `(() => {
  let n = document.querySelector('[data-item-id="' + CSS.escape(${JSON.stringify(id)}) + '"]');
  n = n ? n.nextElementSibling : null;
  while (n && n.matches(".chat-item-user")) n = n.nextElementSibling;
  const b = n && n.matches(".chat-turn") ? n.querySelector(":scope > .chat-row-line button.chat-turn-line") : null;
  return b ? b.getAttribute("aria-expanded") : null;
})()`;

/** The message's first line as the bubble shows it (the card's prompt and the mark's name start with it). */
const trLine = (text: string) => text.split("\n").find((l) => l.trim())?.replace(/\s+/g, " ").trim() ?? "";
const near = (a: number | null | undefined, b: number, by: number) => typeof a === "number" && Math.abs(a - b) <= by;

/** Give the long chat its turns, through the fake claude (one setup socket per message, each waits for its turn's end). */
async function trSetup(t: Target): Promise<void> {
  for (const text of TR_TURNS) await serverTurn(t, TR_CHAT, text, 60_000);
}

/** The rail's shape and place, its ticks, beside the text and over nothing. */
function trShape(s: TrState, at: string, fail: (text: string) => void) {
  if (s.navName !== "Turns") fail(`${at}: the rail is named ${JSON.stringify(s.navName)}, not "Turns"`);
  if (s.marks.length !== s.users.length || s.marks.length !== TR_TOTAL) fail(`${at}: the rail has ${s.marks.length} marks for ${s.users.length} messages (the long chat has ${TR_TOTAL} turns)`);
  s.marks.forEach((m, i) => {
    const u = s.users[i];
    if (!u) return;
    if (m.href !== `/c/${TR_CHAT}/m/${u.id}`) fail(`${at}: mark ${i} goes to ${m.href}, not /c/${TR_CHAT}/m/${u.id}`);
    if (!m.name || !m.name.startsWith(trLine(u.text).slice(0, 60))) fail(`${at}: mark ${i} is named ${JSON.stringify(m.name)}, not by its message ${JSON.stringify(trLine(u.text))}`);
  });
  const current = s.marks.filter((m) => m.current === "location");
  if (current.length !== 1) fail(`${at}: ${current.length} marks are current, not 1`);
  if (s.marks.filter((m) => m.tab === "0").length !== 1) fail(`${at}: the rail has ${s.marks.filter((m) => m.tab === "0").length} Tab stops, not 1`);
  const nav = s.navBox;
  if (!nav || s.textRight === null || s.clientRight === null || !s.wrapBox) return fail(`${at}: the rail's place could not be read`);
  if (!near(nav.left, s.textRight + 12, 1.5)) fail(`${at}: the rail's left edge is at ${nav.left}, not 12 px right of the text (${s.textRight + 12})`);
  if (nav.right > s.clientRight + 0.5) fail(`${at}: the rail reaches ${nav.right}, past the scroller's client edge ${s.clientRight}`);
  const band = s.bandTop ?? s.wrapBox.top;
  if (nav.top < band - 0.5 || nav.bottom > s.wrapBox.bottom + 0.5) fail(`${at}: the rail (${nav.top} to ${nav.bottom}) is not inside the band below the title bar (${band} to ${s.wrapBox.bottom})`);
  if (s.composerTop !== null && nav.bottom > s.composerTop + 0.5) fail(`${at}: the rail reaches ${nav.bottom}, over the message box (${s.composerTop})`);
  if (nav.bottom - nav.top > 400.5) fail(`${at}: the rail is ${nav.bottom - nav.top} px tall, over 400`);
  const last = s.marks.at(-1);
  if (last && (last.tickW !== "14px" || last.tickBg !== s.tokens.text)) fail(`${at}: the current tick is ${last.tickW} in ${last.tickBg}, not 14px in --text (${s.tokens.text})`);
  const rest = s.marks[0];
  if (rest && (rest.tickW !== "8px" || rest.tickBg !== s.tokens.faint)) fail(`${at}: a tick at rest is ${rest.tickW} in ${rest.tickBg}, not 8px in --faint (${s.tokens.faint})`);
  if (s.wide) fail(`${at}: the page scrolls sideways`);
}

/** The card shown for mark i: its words, its place beside the text and inside the band, and the mark's tick. */
function trCard(s: TrState, i: number, by: string, at: string, fail: (text: string) => void) {
  const c = s.card;
  const u = s.users[i];
  if (!c) return fail(`${at}: ${by} mark ${i} shows no card`);
  if (c.role !== "tooltip") fail(`${at}: the card's role is ${JSON.stringify(c.role)}, not tooltip`);
  if (u && c.prompt !== trLine(u.text)) fail(`${at}: ${by} mark ${i}'s card says ${JSON.stringify(c.prompt)}, not its prompt ${JSON.stringify(trLine(u.text))}`);
  if (!c.answer.trim()) fail(`${at}: ${by} mark ${i}'s card has no answer line`);
  if (c.lines > 3) fail(`${at}: the card's answer runs to ${c.lines} lines, over 3`);
  if (s.textRight !== null && !near(c.box.right, s.textRight + 4, 1.5)) fail(`${at}: the card's right edge is at ${c.box.right}, not 4 px right of the text (${s.textRight + 4})`);
  const band = s.bandTop ?? s.wrapBox?.top ?? 0;
  if (s.wrapBox && (c.box.top < band + 7.5 || c.box.bottom > s.wrapBox.bottom - 7.5)) fail(`${at}: the card (${c.box.top} to ${c.box.bottom}) is not 8 px inside the band below the title bar (${band} to ${s.wrapBox.bottom})`);
  // Under the pointer the tick is 12 px in --dim; with the keyboard focus 12 px in --text (DESIGN-U3 4).
  const m = s.marks[i];
  const [ink, word] = by === "the focus on" ? [s.tokens.text, "--text"] : [s.tokens.dim, "--dim"];
  if (m && m.current !== "location" && (m.tickW !== "12px" || m.tickBg !== ink)) fail(`${at}: ${by} mark ${i}'s tick is ${m.tickW} in ${m.tickBg}, not 12px in ${word} (${ink})`);
}

/** ms: the pointer rests on the rail this long for its card (review U3: the card shows on intent, after 150 ms). */
const TR_REST = 300;

/**
 * Review U3: a wheel over a mark, then over its card, scrolls the conversation as a wheel over the text does (the
 * ladder of 25 marks does not overflow, so the rail passes the wheel on), and the card goes. Before, both took the
 * wheel and the conversation stayed.
 */
async function trWheels(page: Page, s1: TrState, at: string, fail: (text: string) => void): Promise<Record<string, unknown>> {
  const probe = () => page.evaluate<TrState>(TR_PROBE);
  const wheel = async (x: number, y: number, dy: number) => {
    await page.send("Input.dispatchMouseEvent", { type: "mouseWheel", x, y, deltaX: 0, deltaY: dy });
    await sleep(250);
    await page.evaluate(P2_DRAWN);
  };
  const m = s1.marks[10];
  const n = s1.marks[12];
  if (!m || !n) {
    fail(`${at}: no marks 10 and 12 to wheel over`);
    return {};
  }
  await trMouse(page, Math.round(m.x), Math.round(m.y));
  await sleep(TR_REST);
  const a = await probe();
  const t0 = a.scroll?.top ?? 0;
  await wheel(Math.round(m.x), Math.round(m.y), -200);
  await wheel(Math.round(m.x), Math.round(m.y), -200);
  const b = await probe();
  const overMark = { before: t0, after: b.scroll?.top ?? null, cardBefore: !!a.card, cardAfter: !!b.card };
  if ((b.scroll?.top ?? t0) > t0 - 300) fail(`${at}: two wheels of 200 px up over a mark moved the conversation from ${t0} to ${b.scroll?.top}, not 300 px or more up`);
  if (b.card) fail(`${at}: the card stays while a wheel over the rail scrolls the conversation`);
  // The pointer rests on another mark, its card shows, the pointer goes onto the card, and a wheel there.
  await trMouse(page, Math.round(n.x), Math.round(n.y));
  await sleep(TR_REST);
  const c = await probe();
  let overCard: Record<string, unknown> = { card: false };
  if (!c.card) fail(`${at}: after the wheel the pointer rested on mark 12 and no card showed`);
  else {
    const cx = Math.round(c.card.box.left + 30);
    const cy = Math.round((c.card.box.top + c.card.box.bottom) / 2);
    await trMouse(page, cx, cy);
    await sleep(150);
    const t1 = (await probe()).scroll?.top ?? 0;
    await wheel(cx, cy, -200);
    const d = await probe();
    overCard = { before: t1, after: d.scroll?.top ?? null, cardAfter: !!d.card };
    if ((d.scroll?.top ?? t1) > t1 - 150) fail(`${at}: a wheel of 200 px up over the card moved the conversation from ${t1} to ${d.scroll?.top}, not 150 px or more up`);
    if (d.card) fail(`${at}: the card stays while a wheel over it scrolls the conversation`);
  }
  await trMouse(page, Math.round((s1.textRight ?? 600) - 300), Math.round(page.vp.height / 2));
  await sleep(200);
  return { overMark, overCard };
}

/**
 * Review U3: a pointer that crosses the rail on its way into the column (8 px every 16 ms, about 500 px a second, at
 * the height of a code block's Copy) opens no card, and the click reaches the Copy, with the URL kept. Before, the card
 * opened at the first move over a mark, stayed under the pointer, and the click jumped to another turn.
 */
async function trCrossing(page: Page, path: string, at: string, fail: (text: string) => void): Promise<Record<string, unknown>> {
  const placed = await page.evaluate<{ x: number; y: number; railLeft: number; railRight: number; railTop: number; railBottom: number; word: string } | null>(`(() => {
    const sc = [...document.querySelectorAll(".chat-scroll")].find((e) => e.getClientRects().length > 0);
    const nav = document.querySelector("nav.chat-rail");
    if (!sc || !nav) return null;
    const btns = [...sc.querySelectorAll('[data-testid="copy-code"]')].filter((b) => b.getClientRects().length > 0 && !b.closest("[hidden]"));
    const b = btns[Math.floor(btns.length / 2)];
    if (!b) return null;
    const n = nav.getBoundingClientRect();
    sc.dispatchEvent(new WheelEvent("wheel", { deltaY: -120, bubbles: true }));
    sc.scrollTop += b.getBoundingClientRect().top + b.getBoundingClientRect().height / 2 - (n.top + n.bottom) / 2;
    const r = b.getBoundingClientRect(), n2 = nav.getBoundingClientRect();
    return { x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2), railLeft: n2.left, railRight: n2.right, railTop: n2.top, railBottom: n2.bottom, word: b.textContent.trim() };
  })()`);
  await page.evaluate(P2_DRAWN);
  if (!placed) {
    fail(`${at}: no code block's Copy to cross the rail to`);
    return {};
  }
  if (placed.y < placed.railTop + 4 || placed.y > placed.railBottom - 4) {
    fail(`${at}: the code block's Copy (y ${placed.y}) could not be put beside the rail (${placed.railTop} to ${placed.railBottom})`);
    return { placed };
  }
  const h0 = await page.history();
  for (let x = Math.round(placed.railRight + 40); x > placed.x; x -= 8) {
    await trMouse(page, x, placed.y);
    await sleep(16);
  }
  await trMouse(page, placed.x, placed.y);
  await sleep(300);
  const s = await page.evaluate<TrState>(TR_PROBE);
  const under = await page.evaluate<string>(`(() => { const el = document.elementFromPoint(${placed.x}, ${placed.y}); return el ? (el.closest('[data-testid="copy-code"]') ? "copy" : el.closest(".chat-rail-card") ? "card" : el.className || el.tagName) : "none"; })()`);
  if (s.card) fail(`${at}: a pointer that only crossed the rail opened the card ("${s.card.prompt ?? s.card.answer}")`);
  if (under !== "copy") fail(`${at}: after crossing the rail the pointer is over ${JSON.stringify(under)}, not the code block's Copy`);
  await page.press(placed.x, placed.y);
  await sleep(200);
  const after = await page.evaluate<{ path: string; word: string | null }>(`(() => { const el = document.elementFromPoint(${placed.x}, ${placed.y}); const b = el && el.closest('[data-testid="copy-code"]'); return { path: location.pathname + location.search, word: b ? b.textContent.trim() : null }; })()`);
  const h1 = await page.history();
  if (after.path !== path || h1.currentIndex !== h0.currentIndex) fail(`${at}: the click after crossing the rail went to ${after.path} (${h1.currentIndex - h0.currentIndex} history entries), not nowhere`);
  if (after.word === placed.word) fail(`${at}: the click after crossing the rail did not reach the Copy (it still says ${JSON.stringify(after.word)})`);
  await trMouse(page, Math.round(placed.x - 300), placed.y);
  return { placed, card: !!s.card, under, word: after.word, path: after.path };
}

async function turnRailRun(b: Booted, vp: Viewport, theme: Theme, look: P2LookId, full: boolean): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = { look };
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const path = `/c/${TR_CHAT}`;
  const at = `${vp.width}x${vp.height} ${theme}${look === "glass" ? "" : `, ${look}`}`;
  const step = (s: string) => `${vp.width}${look === "glass" ? "" : `-${look}`}-${s}`;
  let shot: string | undefined;
  try {
    await withPage(vp, theme, async (page, wire) => {
      const probe = () => page.evaluate<TrState>(TR_PROBE);
      const drawn = async () => {
        await page.evaluate(P2_DRAWN);
        await page.evaluate(P2_DRAWN);
      };
      await page.navigate(b.base + path);
      await waitShown(page, ["chat", "conversation"]);
      if (look !== "glass") await wearLook(page, look, theme);
      const docked = (await trUntil(page, (s) => s.users.length >= TR_TOTAL, 8000)).s;
      details.docked = { rail: docked.rail, strip: docked.strip, marks: docked.marks.length };
      if (docked.users.length !== TR_TOTAL) return fail(`${at}: the long chat shows ${docked.users.length} messages, not ${TR_TOTAL}`);
      // With the session rail docked: the rail follows the strip measured here.
      if (docked.rail !== (docked.strip !== null && docked.strip >= 32)) fail(`${at}: beside the session rail the strip is ${docked.strip} px and the rail ${docked.rail ? "shows" : "is hidden"}`);
      const table = vp.width >= 1280 && (look === "glass" || look === "editor");
      if (docked.rail !== table) warnings.push({ code: "width", text: `${at}: beside the session rail the rail ${docked.rail ? "shows" : "is hidden"} (strip ${docked.strip} px), where DESIGN-U3 2.5 measured it ${table ? "shown" : "hidden"}` });
      await trShot(page, shotName("main", "turn-rail", vp, theme, step("docked")));

      // Hide session rail: the rail shows in every look at both sizes.
      const toggle = await page.locate('[data-testid="topbar-rail"]');
      if (!toggle) return fail(`${at}: no Hide session rail in the title bar`);
      await page.press(toggle.x, toggle.y);
      await trMouse(page, 4, Math.round(vp.height / 2));
      const open = await trUntil(page, (s) => s.rail && s.marks.length >= TR_TOTAL, 3000);
      await sleep(400); // the pane's slide
      const s1 = await probe();
      details.shown = { strip: s1.strip, nav: s1.navBox, marks: s1.marks.length };
      if (!open.ok || !s1.rail) return fail(`${at}: with Hide session rail the rail does not show (strip ${s1.strip} px)`);
      trShape(s1, at, fail);
      if (s1.marks.at(-1)?.current !== "location") fail(`${at}: following the end, the current mark is not the last`);
      shot = shotName("main", "turn-rail", vp, theme, step("shown"));
      await trShot(page, shot);

      // ---- hover: the card once the pointer rests on the rail (review U3: not on a crossing), following the pointer,
      // staying on the card, closed by a click on it (which goes nowhere), gone when the pointer leaves
      const hi = 3;
      await trMouse(page, Math.round(s1.marks[hi]!.x), Math.round(s1.marks[hi]!.y));
      await sleep(TR_REST);
      await drawn();
      const h1 = await probe();
      trCard(h1, hi, "the pointer on", at, fail);
      await trShot(page, shotName("main", "turn-rail", vp, theme, step("hover")));
      await trMouse(page, Math.round(s1.marks[hi + 1]!.x), Math.round(s1.marks[hi + 1]!.y));
      await drawn();
      const h2 = await probe();
      if (h2.card?.prompt !== trLine(h2.users[hi + 1]?.text ?? "")) fail(`${at}: the card did not follow the pointer to the next mark at once (${JSON.stringify(h2.card?.prompt)})`);
      if (h2.card) {
        const cx = Math.round(h2.card.box.left + 20);
        const cy = Math.round((h2.card.box.top + h2.card.box.bottom) / 2);
        await trMouse(page, cx, cy);
        await sleep(300);
        if (!(await probe()).card) fail(`${at}: the card went while the pointer was on it`);
        const hc = await page.history();
        await page.press(cx, cy);
        await sleep(150);
        await drawn();
        const hk = await probe();
        const hc2 = await page.history();
        if (hk.card) fail(`${at}: a click on the card did not close it`);
        if (hk.path !== path || hc2.currentIndex !== hc.currentIndex) fail(`${at}: a click on the card went to ${hk.path} (${hc2.currentIndex - hc.currentIndex} history entries), not nowhere`);
      }
      await trMouse(page, Math.round((s1.textRight ?? 600) - 300), Math.round(vp.height / 2));
      await sleep(300);
      if ((await probe()).card) fail(`${at}: the card stays 300 ms after the pointer left the rail and the card`);

      // ---- focus: the one Tab stop, the arrows, Home and End, the card it describes, the ring, Esc
      const roving = await page.evaluate<number | null>(`(() => { const a = document.querySelector('nav.chat-rail a.chat-rail-mark[tabindex="0"]'); if (!a) return null; a.focus(); return Number(a.getAttribute("data-i")); })()`);
      if (roving !== TR_TOTAL - 1) fail(`${at}: the rail's Tab stop is mark ${roving}, not the current (last) one`);
      await trKey(page, "ArrowUp");
      const f1 = await probe();
      if (f1.focus !== TR_TOTAL - 2) fail(`${at}: Up moved the focus to mark ${f1.focus}, not ${TR_TOTAL - 2}`);
      trCard(f1, TR_TOTAL - 2, "the focus on", at, fail);
      const fm = f1.marks[TR_TOTAL - 2];
      if (fm && (fm.described !== f1.card?.id || fm.tab !== "0")) fail(`${at}: the focused mark has aria-describedby ${JSON.stringify(fm.described)} and tabindex ${fm.tab}, not the card's id and 0`);
      if (fm && fm.outline !== "solid") fail(`${at}: the focused mark shows no focus ring (outline ${fm.outline})`);
      await trKey(page, "ArrowUp");
      await trShot(page, shotName("main", "turn-rail", vp, theme, step("focus")));
      await trKey(page, "Home");
      if ((await probe()).focus !== 0) fail(`${at}: Home did not move the focus to the first mark`);
      await trKey(page, "End");
      if ((await probe()).focus !== TR_TOTAL - 1) fail(`${at}: End did not move the focus to the last mark`);
      await trKey(page, "Escape");
      const esc = await probe();
      if (esc.card) fail(`${at}: Esc did not hide the card`);
      if (esc.focus !== TR_TOTAL - 1) fail(`${at}: Esc moved the focus off the mark`);
      await page.evaluate(`(() => { if (document.activeElement && document.activeElement.blur) document.activeElement.blur(); return true; })()`);
      await drawn();
      if ((await probe()).card) fail(`${at}: the card stays when the focus leaves the rail`);

      // ---- review U3: a wheel over the rail, and over its card, scrolls the conversation (the ladder does not
      // overflow here), and the card goes; the pointer rests on the rail first, so the card shows
      details.wheel = await trWheels(page, s1, at, fail);
      details.crossing = await trCrossing(page, path, at, fail);

      // ---- the current mark follows the reader's scroll
      // The current turn: the last whose message is at or above the reading line (a fifth of the way down, at most 96 px).
      const follows = async (i: number, top: number) => {
        await page.evaluate(tfScrollRow(`[data-item-id="${s1.users[i]!.id}"]`, top));
        await drawn();
        await drawn();
        const s = await probe();
        const line = Math.min(96, 0.2 * (s.scroll?.h ?? 0));
        const want = s.users.reduce((k, u, n) => (u.top <= line ? n : k), 0);
        const now = s.marks.findIndex((m) => m.current === "location");
        if (want < i || now !== want) fail(`${at}: with message ${i} at ${top} px (reading line ${line} px) the current mark is ${now}, not ${want}`);
      };
      await follows(6, 30);
      await follows(14, 60);

      // ---- a click jumps (the URL, the landing, folded), Back returns to the reader's first row
      const before = await page.evaluate<{ sel: string; top: number } | null>(TF_FIRST);
      const hist0 = await page.history();
      const jumpTo = s1.users[TR_JUMP]!.id;
      const jm = (await probe()).marks[TR_JUMP];
      if (!jm) return fail(`${at}: no mark ${TR_JUMP} to click`);
      await page.press(Math.round(jm.x), Math.round(jm.y));
      await sleep(150);
      await page.settle();
      await drawn();
      const landed = async (label: string) => {
        const s = await probe();
        const row = await page.evaluate<{ top: number; highlight: boolean } | null>(trRow(`[data-item-id="${jumpTo}"]`));
        if (s.path !== `${path}/m/${jumpTo}`) fail(`${at}: ${label}: the URL is ${s.path}, not ${path}/m/${jumpTo}`);
        if (!row || !near(row.top, 24, 2)) fail(`${at}: ${label}: the turn's message is at ${row?.top} px, not 24 px below the scroller's visible top`);
        if (row && !row.highlight) fail(`${at}: ${label}: the turn's message is not highlighted`);
        const folded = await page.evaluate<string | null>(trFolded(jumpTo));
        if (folded !== "false") fail(`${at}: ${label}: the upload-test turn is ${folded === "true" ? "open" : `drawn with no line (${folded})`}, not folded`);
        return s;
      };
      const j1 = await landed("a click");
      // The click closed the card, though the pointer is still on the mark (its turn is now at the top).
      if (j1.card) fail(`${at}: after the click the card still shows`);
      if (j1.marks[TR_JUMP]?.current !== "location") fail(`${at}: after the jump the current mark is not the turn's`);
      const hist1 = await page.history();
      if (hist1.currentIndex !== hist0.currentIndex + 1) fail(`${at}: the click made ${hist1.currentIndex - hist0.currentIndex} history entries, not 1`);
      await trShot(page, shotName("main", "turn-rail", vp, theme, step("jump")));
      const back = async (label: string) => {
        const h = await page.history();
        await page.goToEntry(h.entries[h.currentIndex - 1]!.id);
        await drawn();
        const s = await probe();
        if (s.path !== path) fail(`${at}: ${label}: Back went to ${s.path}, not ${path}`);
        const now = before ? await page.evaluate<{ top: number } | null>(tfRow(before.sel)) : null;
        if (!before || !now || !near(now.top, before.top, 2)) fail(`${at}: ${label}: Back put the reader's first row (${before?.sel}) at ${now?.top} px, not at ${before?.top} px where it was`);
      };
      await back("Back");

      if (full) {
        // Forward lands the jump again, and Back again returns again.
        const h = await page.history();
        await page.goToEntry(h.entries[h.currentIndex + 1]!.id);
        await drawn();
        await landed("Forward");
        await back("Back again");

        // ---- review U3: a reload of the chat's own entry opens it at its end (the route), not at the place the entry
        // kept for Back, and the entry forgets that place; then the reader's place again for the keys
        await page.reload();
        await waitShown(page, ["chat", "conversation"]);
        await trUntil(page, (x) => x.users.length >= TR_TOTAL, 8000);
        await drawn();
        await sleep(300);
        const rl = await probe();
        const keptAfter = await page.evaluate<boolean>(`!!(history.state && history.state.place !== undefined)`);
        details.reload = { path: rl.path, scroll: rl.scroll, kept: keptAfter };
        if (rl.path !== path) fail(`${at}: the reload went to ${rl.path}, not ${path}`);
        if (!rl.scroll || rl.scroll.gap > 2) fail(`${at}: after Back put the place back and a reload of ${path}, the chat opened ${rl.scroll?.gap} px above its end, not at its end`);
        if (keptAfter) fail(`${at}: after a reload the entry still keeps the place for Back`);
        // The reload puts the focus in the message box (a laptop's chat), where `{` and `}` are text.
        await page.evaluate(`(() => { if (document.activeElement && document.activeElement.blur) document.activeElement.blur(); return true; })()`);
        if (before) {
          await page.evaluate(tfScrollRow(before.sel, before.top));
          await drawn();
        }

        // ---- the CLI's `}` and `{`: the turn after or before, landing the same way; no URL change and no entry
        const hk = await page.history();
        const startTop = (await probe()).scroll?.top;
        // Where each key must go, from the tops it starts at: `}` the turn after the one at the landing line (24 px,
        // 4 px of slack), `{` the top of the turn the reader is inside, else the turn before (DESIGN-U3 7).
        const lands = async (key: "{" | "}") => {
          const s0 = await probe();
          const here = s0.users.reduce((k, u, n) => (u.top <= 28 ? n : k), -1);
          const i = key === "}" ? here + 1 : here >= 0 && s0.users[here]!.top < 20 ? here : here - 1;
          await trKey(page, key);
          await drawn();
          const s = await probe();
          const u = s.users[i];
          if (!u || !near(u.top, 24, 2)) fail(`${at}: ${key} put message ${i} at ${u?.top} px, not 24 px below the scroller's visible top`);
          if (s.path !== path) fail(`${at}: ${key} changed the URL to ${s.path}`);
          return i;
        };
        const went = [await lands("}"), await lands("}"), await lands("{"), await lands("{")];
        if (went[1] !== went[0]! + 1 || went[2] !== went[0] || went[3] !== went[0]! - 1) fail(`${at}: } } { { went to the messages ${went.join(", ")}, not one turn at a time`);
        const hk2 = await page.history();
        if (hk2.currentIndex !== hk.currentIndex || hk2.entries.length !== hk.entries.length) fail(`${at}: { and } made history entries`);
        details.keys = { startTop, went };
        // In the message box they are text.
        const sc0 = (await probe()).scroll?.top;
        await page.evaluate(`(() => { const f = ${FIELD}; if (f) f.focus(); return !!f; })()`);
        await trKey(page, "}");
        const typed = await page.evaluate<string>(`(() => { const f = ${FIELD}; return f ? f.value : ""; })()`);
        if (typed !== "}" || (await probe()).scroll?.top !== sc0) fail(`${at}: } in the message box gave ${JSON.stringify(typed)} and moved the view`);
        await clearBox(page);
        await page.evaluate(`(() => { if (document.activeElement && document.activeElement.blur) document.activeElement.blur(); return true; })()`);

        // ---- a ladder taller than the rail (a 440 px high window): it scrolls inside with no scrollbar, a fade at each
        // end that can scroll, and the current mark kept in view (at the end, then at the top)
        // The pointer off the rail first: the rail does not scroll under it.
        await trMouse(page, Math.round((s1.textRight ?? 600) - 300), 200);
        await page.send("Emulation.setDeviceMetricsOverride", { width: vp.width, height: 440, deviceScaleFactor: vp.scale, mobile: false, screenWidth: vp.width, screenHeight: 440 });
        const ladder = async (where: "end" | 0) => {
          await page.evaluate(tfScrollTo(where));
          await sleep(200);
          await drawn();
          return page.evaluate<{ scrolls: boolean; top: boolean; bottom: boolean; inView: boolean; current: number; bar: string } | null>(`(() => {
            const nav = document.querySelector("nav.chat-rail");
            if (!nav) return null;
            const marks = [...nav.querySelectorAll("a.chat-rail-mark")];
            const cur = marks.find((a) => a.getAttribute("aria-current") === "location");
            const n = nav.getBoundingClientRect(), c = cur ? cur.getBoundingClientRect() : null;
            return { scrolls: nav.scrollHeight > nav.clientHeight + 1, top: nav.classList.contains("fade-top"), bottom: nav.classList.contains("fade-bottom"), inView: !!c && c.top >= n.top - 0.5 && c.bottom <= n.bottom + 0.5, current: marks.indexOf(cur), bar: getComputedStyle(nav).scrollbarWidth };
          })()`);
        };
        const atEnd = await ladder("end");
        const atTop = await ladder(0);
        details.ladder = { atEnd, atTop };
        if (!atEnd || !atEnd.scrolls) fail(`${at}: in a 440 px window the rail ${atEnd ? "does not scroll inside" : "is not drawn"}`);
        else {
          if (!atEnd.top || atEnd.bottom || !atEnd.inView || atEnd.current !== TR_TOTAL - 1) fail(`${at}: at the chat's end the tall rail ${JSON.stringify(atEnd)}: not the fade at the top only with the last mark current and in view`);
          if (!atTop || !atTop.bottom || atTop.top || !atTop.inView || atTop.current !== 0) fail(`${at}: at the chat's start the tall rail ${JSON.stringify(atTop)}: not the fade at the bottom only with the first mark current and in view`);
          if (atEnd.bar !== "none") fail(`${at}: the tall rail draws a scrollbar (${atEnd.bar})`);
        }
        await trShot(page, shotName("main", "turn-rail", vp, theme, step("tall")));

        // ---- the short chat (the example chat, under 5 turns): no rail, though there is room
        await page.navigate(b.base + `/c/${EX.chat}`);
        await waitShown(page, ["chat", "conversation"]);
        const short = (await trUntil(page, (s) => s.users.length > 0, 8000)).s;
        details.short = { users: short.users.length, strip: short.strip, rail: short.rail };
        if (short.rail) fail(`${at}: the example chat (${short.users.length} messages) shows the rail`);
        if ((short.strip ?? 0) < 32) warnings.push({ code: "width", text: `${at}: the short chat has no room either (strip ${short.strip} px), so it does not prove the threshold` });
        await trShot(page, shotName("main", "turn-rail", vp, theme, step("short")));

        // ---- Settings' shortcut list names the keys (DESIGN-U3 7), after Send now
        await page.navigate(`${b.base}/settings/general/shortcuts`);
        await waitShown(page, ["settings"], 6000);
        const keys = JSON.parse(await page.evaluate<string>(`JSON.stringify([...document.querySelectorAll(".set-keys .set-key")].map((r) => ({ words: (r.querySelector("dt")?.firstChild?.textContent || "").trim(), note: (r.querySelector(".set-key-note")?.textContent || "").trim(), keys: [...r.querySelectorAll(".set-combo")].map((c) => [...c.querySelectorAll("kbd")].map((k) => k.textContent)) })))`)) as { words: string; note: string; keys: string[][] }[];
        const words = keys.map((r) => r.words);
        const row = keys.find((r) => r.words === "Jump to the previous or next turn");
        details.shortcut = row ?? null;
        if (!row || JSON.stringify(row.keys) !== JSON.stringify([["{"], ["}"]]) || row.note !== "Outside the message box") fail(`${at}: Settings' shortcut list has ${row ? JSON.stringify(row) : "no row"} for { and }, not "Jump to the previous or next turn", { or }, "Outside the message box"`);
        if (words.indexOf("Jump to the previous or next turn") !== words.indexOf("Send now") + 1) fail(`${at}: the { and } row is not right after Send now (${clipList(words)})`);
      }

      issueFindings(page.takeIssues(), failures);
      const acts = acting(wire.framesSince(0));
      if (acts.length) fail(`${at}: the page sent ${clipList(acts.map(frameText))}`, "frames");
      const posts = wire.httpSince(0).filter((h) => MUTATING_METHODS.has(h.method));
      if (posts.length) fail(`${at}: the page sent ${clipList(posts.map(httpText))}`, "frames");
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const note = [look === "glass" ? "" : `the ${look} look`, full ? "with Forward, the keys, a tall rail and the short chat" : ""].filter(Boolean).join("; ");
  return finish({ kind: "flow", name: "turn-rail", route: "chat", scene: "main", size: sizeTag(vp), theme, path: `/c/${TR_CHAT}`, failures, warnings, note, ms: Date.now() - t0, details, shot });
}

/** On touch (834x1194, 390x844): no rail; a /m/ link to a turn still lands it at the top, folded. */
async function turnRailTouch(b: Booted, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const path = `/c/${TR_CHAT}`;
  const at = `${vp.width}x${vp.height} ${theme}`;
  let shot: string | undefined;
  try {
    await withPage(vp, theme, async (page, wire) => {
      await page.navigate(b.base + path);
      await waitShown(page, ["chat", "conversation"]);
      const s = (await trUntil(page, (x) => x.users.length >= TR_TOTAL, 8000)).s;
      details.drawn = { users: s.users.length, rail: s.rail, strip: s.strip };
      if (s.users.length !== TR_TOTAL) return fail(`${at}: the long chat shows ${s.users.length} messages, not ${TR_TOTAL}`);
      if (s.rail || (await page.evaluate<number>(`document.querySelectorAll("nav.chat-rail, .chat-rail-card").length`)) > 0) fail(`${at}: the rail is drawn on touch`);
      shot = shotName("main", "turn-rail", vp, theme, "hidden");
      await trShot(page, shot);
      const id = s.users[TR_JUMP]!.id;
      await page.navigate(b.base + `${path}/m/${id}`);
      await waitShown(page, ["chat", "conversation"]);
      await page.evaluate(P2_DRAWN);
      const row = await page.evaluate<{ top: number } | null>(trRow(`[data-item-id="${id}"]`));
      if (!row || !near(row.top, 24, 2)) fail(`${at}: a /m/ link put the turn's message at ${row?.top} px, not 24 px below the scroller's visible top`);
      const folded = await page.evaluate<string | null>(trFolded(id));
      if (folded !== "false") fail(`${at}: a /m/ link left the upload-test turn ${folded === "true" ? "open" : `with no line (${folded})`}`);
      await trShot(page, shotName("main", "turn-rail", vp, theme, "link"));
      issueFindings(page.takeIssues(), failures);
      const acts = acting(wire.framesSince(0));
      if (acts.length) fail(`${at}: the page sent ${clipList(acts.map(frameText))}`, "frames");
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return finish({ kind: "flow", name: "turn-rail", route: "chat", scene: "main", size: sizeTag(vp), theme, path, failures, warnings, note: "touch: no rail; a /m/ link lands at the top", ms: Date.now() - t0, details, shot });
}

/**
 * Smooth text with the rail shown (FIX-U3 1 and 2): the 20,000-character paced reply (160 pieces, 80 ms apart) on the
 * long chat at 1280x800 with Hide session rail. The rail does not change while the reply streams (a MutationObserver
 * on it), and the main thread's time per frame is reported, with a warning above 4 ms (the smooth-text check's limit).
 */
async function turnRailSmooth(b: Booted, before = TR_TOTAL, label = ""): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const vp = WIDE_LAPTOP;
  const path = `/c/${TR_CHAT}`;
  let shot: string | undefined;
  try {
    await withPage(vp, "light", async (page, wire) => {
      await page.send("Page.addScriptToEvaluateOnNewDocument", { source: REVEAL_SAMPLER });
      await page.navigate(b.base + path);
      await waitShown(page, ["chat", "conversation", "composer"]);
      const drawnAll = await trUntil(page, (s) => s.marks.length >= before || s.users.length >= before, 15_000);
      const toggle = await page.locate('[data-testid="topbar-rail"]');
      if (toggle) await page.press(toggle.x, toggle.y);
      await trMouse(page, 4, Math.round(vp.height / 2));
      const shown = await trUntil(page, (s) => s.rail, 3000);
      await sleep(400);
      details.before = { users: drawnAll.s.users.length, marks: shown.s.marks.length, partial: shown.s.partial };
      // With no rail the reply still streams and its cost is measured: the same flow on a page with no rail (--dist of
      // an older build) gives the figure to compare.
      if (!shown.ok) fail(`with Hide session rail the rail does not show (strip ${shown.s.strip} px)`);
      else if (shown.s.marks.length !== before) fail(`before the reply the rail has ${shown.s.marks.length} marks, not ${before}${shown.s.partial ? " (older turns not loaded)" : ""}`);
      await page.evaluate(`(() => { const nav = document.querySelector("nav.chat-rail"); window.__railMut = []; if (nav) new MutationObserver((list) => { const t = performance.now(); for (const m of list) window.__railMut.push({ t, type: m.type, attr: m.attributeName }); }).observe(nav, { subtree: true, childList: true, attributes: true, characterData: true }); return true; })()`);
      page.takeIssues();
      const run = await streamReply(page, pacedPrompt(20000, 160, 80));
      const { start, end } = replySpan(run);
      const from = run.frames[start]?.t ?? Infinity;
      // Up to the last frame before the turn's end: the end itself changes the new turn's mark once (its name and colour).
      const to = run.frames[Math.min(end, run.frames.length) - 1]?.t ?? -Infinity;
      const muts = await page.evaluate<{ t: number; type: string; attr: string | null }[]>(`window.__railMut`);
      const during = muts.filter((m) => m.t > from && m.t < to);
      const after = await page.evaluate<TrState>(TR_PROBE);
      details.smooth = { pieces: run.deltas.length, shown: run.text.length, cost: run.cost, railChanges: muts.length, railChangesBefore: muts.filter((m) => m.t <= from).length, railChangesWhileStreaming: during.length, railChangesAtTheEnd: muts.filter((m) => m.t >= to).length, marks: after.marks.length };
      if (start < 0) fail("the reply never showed");
      if (run.deltas.length < 100) fail(`the paced stream came in ${run.deltas.length} pieces`);
      if (shown.ok && (!after.rail || after.marks.length !== before + 1)) fail(`after the reply the rail ${after.rail ? `has ${after.marks.length} marks, not ${before + 1}` : "is gone"}`);
      if (during.length) fail(`the rail changed ${during.length} times while the reply streamed (${clipList([...new Set(during.map((m) => `${m.type} ${m.attr ?? ""}`.trim()))])}): per-frame work`);
      if (after.marks.at(-1)?.running) fail("after the turn's end its mark still runs");
      if (run.cost.task > 4) warnings.push({ code: "cost", text: `the main thread took ${run.cost.task} ms per frame while the 20,000-character reply revealed with the rail shown, on a chat of ${before} turns` });
      shot = shotName("main", "turn-rail", vp, "light", label ? `smooth-${label}` : "smooth");
      await trShot(page, shot);
      issueFindings(page.takeIssues(), failures);
      const acts = acting(wire.framesSince(0));
      if (acts.length !== 1 || acts[0]!.t !== "send") fail(`the page sent ${clipList(acts.map(frameText)) || "nothing"}, not the one send`, "frames");
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  const cost = (details.smooth as { cost?: { task: number } } | undefined)?.cost?.task;
  return finish({ kind: "flow", name: "turn-rail", route: "chat", scene: "main", size: sizeTag(vp), theme: "light", path, failures, warnings, note: `smooth text with the rail shown on ${before} turns: ${cost ?? "?"} ms of main thread per frame`, ms: Date.now() - t0, details, shot });
}

/**
 * Review U3 (the design critique): a running turn's tick says it runs in every look, light and dark: the current
 * tick, 14 px, in the chat list's running colour (--ok-fill, base.css .dot.running), never in the text's colour (in
 * Mono and Editor --accent is the text's, so the tick looked like a finished current one). When the turn has ended,
 * the same tick is 14 px in --text. One paced turn on the long chat (`before` turns) at 1280x800, the session rail
 * hidden; one send.
 */
async function turnRailRunning(b: Booted, before: number): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const vp = WIDE_LAPTOP;
  const path = `/c/${TR_CHAT}`;
  let shot: string | undefined;
  try {
    await withPage(vp, "light", async (page, wire) => {
      const probe = () => page.evaluate<TrState>(TR_PROBE);
      await page.navigate(b.base + path);
      await waitShown(page, ["chat", "conversation", "composer"]);
      await trUntil(page, (s) => s.users.length >= before, 15_000);
      const toggle = await page.locate('[data-testid="topbar-rail"]');
      if (toggle) await page.press(toggle.x, toggle.y);
      await trMouse(page, 4, Math.round(vp.height / 2));
      const shown = await trUntil(page, (s) => s.rail && s.marks.length >= before, 3000);
      await sleep(400);
      if (!shown.ok) return fail(`with Hide session rail the rail does not show ${before} marks (${shown.s.marks.length}, strip ${shown.s.strip} px)`);
      page.takeIssues();
      await page.evaluate(`(() => { const f = ${FIELD}; if (f) f.focus(); return !!f; })()`);
      await page.send("Input.insertText", { text: pacedPrompt(8000, 100, 80) });
      await sleep(150);
      await keyCode(page, "Enter", 13, { text: "\r" });
      const run = await trUntil(page, (s) => s.marks.length === before + 1 && !!s.marks.at(-1)?.running, 10_000);
      if (!run.ok) return fail(`after the send the new turn's mark does not run (${run.s.marks.length} marks)`);
      const ticks: Record<string, { w: string; bg: string; text: string; ok: string }> = {};
      for (const look of P2_LOOKS)
        for (const theme of ["light", "dark"] as const) {
          await wearLook(page, look, theme);
          const s = await probe();
          const m = s.marks.at(-1);
          if (!m?.running) {
            warnings.push({ code: "flow", text: `the paced turn ended before the ${look} ${theme} look was read` });
            continue;
          }
          ticks[`${look} ${theme}`] = { w: m.tickW, bg: m.tickBg, text: s.tokens.text, ok: s.tokens.ok };
          if (m.current !== "location" || m.tickW !== "14px" || m.tickBg !== s.tokens.ok) fail(`${look} ${theme}: the running turn's current tick is ${m.tickW} in ${m.tickBg}${m.current ? "" : " and not current"}, not 14px in --ok-fill (${s.tokens.ok})`);
          if (m.tickBg === s.tokens.text) fail(`${look} ${theme}: the running turn's tick is in the text's colour (${s.tokens.text}), as a finished current tick is`);
          if (look === "mono" && theme === "light") {
            shot = shotName("main", "turn-rail", vp, "light", "running-mono");
            await trShot(page, shot);
          }
        }
      details.running = ticks;
      await wearLook(page, "glass", "light");
      const done = await trUntil(page, (s) => s.marks.length === before + 1 && !s.marks.at(-1)?.running, 30_000);
      if (!done.ok) return fail("the paced turn did not end in 30 s");
      const ended: Record<string, { w: string; bg: string }> = {};
      for (const look of P2_LOOKS)
        for (const theme of ["light", "dark"] as const) {
          await wearLook(page, look, theme);
          const s = await probe();
          const m = s.marks.at(-1)!;
          ended[`${look} ${theme}`] = { w: m.tickW, bg: m.tickBg };
          if (m.current !== "location" || m.tickW !== "14px" || m.tickBg !== s.tokens.text) fail(`${look} ${theme}: after the turn's end its current tick is ${m.tickW} in ${m.tickBg}, not 14px in --text (${s.tokens.text})`);
          const r = ticks[`${look} ${theme}`];
          if (r && r.bg === m.tickBg) fail(`${look} ${theme}: the running tick (${r.bg}) looks as the finished current tick does`);
        }
      details.ended = ended;
      await wearLook(page, "glass", "light");
      issueFindings(page.takeIssues(), failures);
      const acts = acting(wire.framesSince(0));
      if (acts.length !== 1 || acts[0]!.t !== "send") fail(`the page sent ${clipList(acts.map(frameText)) || "nothing"}, not the one send`, "frames");
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return finish({ kind: "flow", name: "turn-rail", route: "chat", scene: "main", size: sizeTag(vp), theme: "light", path, failures, warnings, note: "a running turn's tick in each look, light and dark, and after its end", ms: Date.now() - t0, details, shot });
}

/** Review U3 (FIX-U3 1, a chat with hundreds of turns): this many more short turns go into the long chat. */
const TR_LONG_MORE = 200;

/** The long chat's short turns for the long run, through the fake claude. */
async function trLongSetup(b: Booted): Promise<void> {
  for (let i = 0; i < TR_LONG_MORE; i++) await serverTurn({ base: b.base, scene: null, booted: b }, TR_CHAT, `Check the renderer's part ${i + 1} again.`, 60_000);
}

/**
 * Review U3 (the integrator's open item; DESIGN-U3 4): a chat whose history is only partly loaded. Five replies of
 * 60,000 characters, then seven short turns, so the newest history page (256 KiB) holds only part of the chat: the
 * rail shows the loaded turns, with three 2 x 2 px dots 3 px apart above the first mark (aria-hidden) and the sentence
 * "Older turns are not loaded." for screen readers. 1280x800 light, the session rail hidden.
 */
async function turnRailPartial(b: Booted): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const vp = WIDE_LAPTOP;
  const path = `/c/${TR_CHAT}`;
  let shot: string | undefined;
  try {
    const t = { base: b.base, scene: null, booted: b };
    for (let i = 0; i < 5; i++) await serverTurn(t, TR_CHAT, `Big part ${i + 1}. ${pacedPrompt(60000, 4, 0)}`, 60_000);
    for (let i = 0; i < 7; i++) await serverTurn(t, TR_CHAT, `Short turn ${i + 1} after the big parts.`, 60_000);
    await withPage(vp, "light", async (page, wire) => {
      await page.navigate(b.base + path);
      await waitShown(page, ["chat", "conversation"]);
      await trUntil(page, (s) => s.users.length >= 7, 15_000);
      const toggle = await page.locate('[data-testid="topbar-rail"]');
      if (toggle) await page.press(toggle.x, toggle.y);
      await trMouse(page, 4, Math.round(vp.height / 2));
      const shown = await trUntil(page, (s) => s.rail, 3000);
      await sleep(400);
      const s = await page.evaluate<TrState>(TR_PROBE);
      const more = await page.evaluate<{ hidden: string | null; aria: string | null; dots: { w: number; h: number; top: number; left: number }[]; firstMarkTop: number | null } | null>(`(() => {
        const nav = document.querySelector("nav.chat-rail");
        if (!nav) return null;
        const li = nav.querySelector(".chat-rail-more");
        const k = (n) => Math.round(n * 100) / 100;
        const dots = li ? [...li.querySelectorAll("i")].map((i) => { const r = i.getBoundingClientRect(); return { w: k(r.width), h: k(r.height), top: k(r.top), left: k(r.left) }; }) : [];
        const a = nav.querySelector("a.chat-rail-mark");
        return { hidden: (nav.querySelector(".visually-hidden") || {}).textContent || null, aria: li ? li.getAttribute("aria-hidden") : null, dots, firstMarkTop: a ? k(a.getBoundingClientRect().top) : null };
      })()`);
      details.partial = { users: s.users.length, marks: s.marks.length, partial: s.partial, more };
      if (!shown.ok) return fail(`the partial chat shows no rail (${s.users.length} messages loaded, strip ${s.strip} px)`);
      if (!s.partial || !more) return fail(`the chat is not partial: ${s.marks.length} marks and no dots (the newest page held it all)`);
      if (s.marks.length < 5 || s.marks.length > s.users.length + 1) fail(`the rail has ${s.marks.length} marks for ${s.users.length} loaded messages`);
      if (more.hidden !== "Older turns are not loaded.") fail(`the rail's sentence for screen readers is ${JSON.stringify(more.hidden)}`);
      if (more.aria !== "true") fail("the dots are not hidden from screen readers");
      if (more.dots.length !== 3) fail(`${more.dots.length} dots, not 3`);
      more.dots.forEach((d, i) => {
        if (Math.abs(d.w - 2) > 0.05 || Math.abs(d.h - 2) > 0.05) fail(`dot ${i + 1} is ${d.w} x ${d.h} px, not 2 x 2`);
        const prev = more.dots[i - 1];
        if (prev && Math.abs(d.top - (prev.top + prev.h) - 3) > 0.05) fail(`dot ${i + 1} is ${Math.round((d.top - prev.top - prev.h) * 100) / 100} px below dot ${i}, not 3`);
      });
      const last = more.dots.at(-1);
      if (last && more.firstMarkTop !== null && more.firstMarkTop < last.top + last.h) fail(`the first mark (top ${more.firstMarkTop}) overlaps the dots (to ${last.top + last.h})`);
      shot = shotName("main", "turn-rail", vp, "light", "partial");
      await trShot(page, shot);
      issueFindings(page.takeIssues(), failures);
      const acts = acting(wire.framesSince(0));
      if (acts.length) fail(`the page sent ${clipList(acts.map(frameText))}`, "frames");
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return finish({ kind: "flow", name: "turn-rail", route: "chat", scene: "main", size: sizeTag(vp), theme: "light", path, failures, warnings, note: "older turns not loaded: the dots and the sentence", ms: Date.now() - t0, details, shot });
}

/** U3's runs on one seed of the main scene (none with --base): the laptop's, each look's, the touch sizes', then smooth text. */
async function turnRailFlows(record: (r: CheckResult) => void, problems: string[]): Promise<void> {
  if (BASE) {
    console.log("ui-check: turn-rail boots a seed of its own (the main scene), so --base runs none of it");
    return;
  }
  const laptop = CORE.find((v) => v.name === "laptop") ?? null;
  const runs: { vp: Viewport; theme: Theme; look: P2LookId; full: boolean }[] = [];
  if (laptop) {
    const fullTheme: Theme = THEMES.includes("light") ? "light" : THEMES[0]!;
    for (const theme of THEMES) runs.push({ vp: WIDE_LAPTOP, theme, look: "glass", full: theme === fullTheme });
    for (const theme of THEMES) runs.push({ vp: laptop, theme, look: "glass", full: false });
    if (THEMES.includes("light")) for (const look of P2_LOOKS.filter((l) => l !== "glass")) runs.push({ vp: WIDE_LAPTOP, theme: "light", look, full: false });
  }
  const touch = [...CORE.filter((v) => v.touch), ...extraAt("turn-rail")];
  const theme0: Theme = THEMES.includes("light") ? "light" : THEMES[0]!;
  const total = runs.length + touch.length + (laptop ? 1 : 0);
  if (!total || cdp.closed) return;
  const failed = (msg: string) => {
    for (const r of runs) record(finish({ kind: "flow", name: "turn-rail", route: "chat", scene: "main", size: sizeTag(r.vp), theme: r.theme, path: `/c/${TR_CHAT}`, failures: [{ code: "seed", text: msg }], warnings: [], note: "", ms: 0, details: {} }));
  };
  let b: Booted;
  try {
    b = await boot({ scene: "main", port: PORT, dist: built!, keep: KEEP, env: SERVER_ENV });
  } catch (e) {
    failed(`the seed did not boot: ${(e as Error).message}`);
    return;
  }
  live.add(b);
  try {
    try {
      await trSetup({ base: b.base, scene: null, booted: b });
    } catch (e) {
      failed(`the long chat's turns did not run: ${(e as Error).message}`);
      return;
    }
    for (const r of runs) {
      if (cdp.closed) break;
      record(await turnRailRun(b, r.vp, r.theme, r.look, r.full));
    }
    for (const vp of touch) if (!cdp.closed) record(await turnRailTouch(b, vp, theme0));
    if (laptop && !cdp.closed) record(await turnRailSmooth(b));
    // Review U3: the running tick in each look; smooth text on a chat of hundreds of turns; a partial chat.
    if (laptop && !cdp.closed) record(await turnRailRunning(b, TR_TOTAL + 1));
    if (laptop && !cdp.closed) {
      let seeded = true;
      try {
        await trLongSetup(b);
      } catch (e) {
        seeded = false;
        record(finish({ kind: "flow", name: "turn-rail", route: "chat", scene: "main", size: "laptop", theme: "light", path: `/c/${TR_CHAT}`, failures: [{ code: "seed", text: `the long chat's ${TR_LONG_MORE} more turns did not run: ${(e as Error).message}` }], warnings: [], note: "", ms: 0, details: {} }));
      }
      if (seeded && !cdp.closed) record(await turnRailSmooth(b, TR_TOTAL + 2 + TR_LONG_MORE, "long"));
    }
    if (laptop && !cdp.closed) record(await turnRailPartial(b));
  } finally {
    const r = await b.stop();
    live.delete(b);
    if (r.code !== 0) problems.push(`scene main (turn-rail): the server exited with ${r.code}`);
    if (r.leftovers.length) problems.push(`scene main (turn-rail): ${r.leftovers.length} process(es) outlived the server and were ended by pid`);
  }
}

// R127 (owner rows 126, 127 and 129; FIX-R127 3, DESIGN-R127 5 to 12): trust-folder, Trust this folder, on the trust
// scene's seed (the example chat's last turn: two `claude --bg` calls that Claude Code refused with its exact line, one
// in a git repository nested in the project, under the example tool id, and one in a plain folder of the project's
// repository). Each run that presses boots a fresh seed (a press uses the offer up). At 1280x800 and 390x844 touch,
// light and dark: a link to the confirm, opened as a new document, only opens it (Cancel has the first focus, the
// real path in mono and Claude Code's own words show, nothing is sent, also after a reload; under Reduce motion the
// dialog or sheet only fades); Cancel goes back to the chat; the line sits under the folded turn's line (on the laptop
// also under the summary row once the turn opens, and under the row itself in Verbose) with its words, its colours,
// its one button (44 px on touch) and the folder's full path as its title; the line's button opens the confirm and
// Enter on the focused Cancel trusts nothing; Trust this folder (a double click on the laptop, two taps on touch)
// sends exactly one trust_folder with the row and its path, gets the ack `trusted`, the fake claude saw the
// attestation for that folder in that folder, and the line says Trusted while the other folder's still offers. On one
// more seed, read only: each look at 1280x800, light and dark (the line's and the confirm's colours are the look's
// tokens), the tablet's dialog (834x1194), and the confirm's repository line for the folder inside the repository.
// The fallback: Open in terminal's route types `cd <folder> && claude` (one type_trust on /ws/shell naming the row,
// never a path) and the pane says so; with the seed's not-recorded fixture (TRUST_NOT_RECORDED, when the seed exports
// it), the answer Claude Code did not record the trust and its Open in terminal first. Screenshots show the machine's
// name as "this-machine" (tfShot).

const TRF_CHAT = EX.chat;
/** The refused row in the nested repository (the example tool id). */
const TRF_ROW = EX.toolUse;
const TRF_CC_QUESTION =
  "Quick safety check: Is this a project you created or one you trust? (Like your own code, a well-known open source project, or work from your team). If not, take a moment to review what's in this folder first.";
const TRF_CC_ALLOWS = "Claude Code'll be able to read, edit, and execute files here.";
const TRF_PANE_LINE = "The command is at the prompt. Press Enter to run it, then choose Yes, I trust this folder.";

/** The seed's refused folders (test/click/seed/demo.ts), read when the flow runs. */
async function trfSeed(): Promise<{ nested: string; inRepo: string; inRepoRow: string; notRecorded: Partial<Fixture> | null }> {
  const demo = await import("../test/click/seed/demo");
  const fx = (await import("../test/click/seed/fixture")) as Record<string, unknown>;
  const nr = fx.TRUST_NOT_RECORDED;
  return { nested: demo.TRUST_FOLDERS.nested, inRepo: demo.TRUST_FOLDERS.inRepo, inRepoRow: demo.TRUST_IN_REPO_CALL, notRecorded: nr && typeof nr === "object" ? (nr as Partial<Fixture>) : null };
}

interface TrfLine {
  count: number;
  shown: number;
  state?: string | null;
  role?: string | null;
  text?: string;
  said?: string | null;
  title?: string | null;
  wordsTitle?: string | null;
  nameColor?: string | null;
  color?: string;
  button?: string | null;
  href?: string | null;
  btnH?: number | null;
  inHidden?: boolean;
  place?: string;
  dim?: string;
  ink?: string;
  wide?: boolean;
  right?: number;
}

/** In-page: every trust line, and the one of row `id`: its words, state, colours, button and where it sits. */
// The line's words after the folder's name (web/chat/trust.ts TRUST_WORDS; the lead's words after the R127 review).
const TRF_OFFERED = "is not trusted, so Claude Code did not start a background session there.";
const TRF_TRUSTED = "is trusted. Ask Claude to try again.";
const trfLine = (id: string) => `(() => {
  const vis = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && el.getBoundingClientRect().height > 0;
  const probe = (v) => { const s = document.createElement("span"); s.style.color = v; document.body.appendChild(s); const c = getComputedStyle(s).color; s.remove(); return c; };
  const lines = [...document.querySelectorAll('[data-testid^="trust-line-"]')];
  const shown = lines.filter(vis);
  const l = shown.find((e) => e.getAttribute("data-testid") === ${JSON.stringify(`trust-line-${id}`)});
  if (!l) return { count: lines.length, shown: shown.length };
  const words = l.querySelector(".chat-trust-words");
  const name = l.querySelector(".chat-trust-path");
  const said = l.querySelector(".chat-trust-words > .visually-hidden");
  const seen = (el) => { const c = el.cloneNode(true); c.querySelectorAll(".visually-hidden").forEach((h) => h.remove()); return c.textContent.replace(/\\s+/g, " ").trim(); };
  const btn = l.querySelector("a.btn, button");
  const r = btn ? btn.getBoundingClientRect() : null;
  const place = l.closest(".chat-tool") ? "row" : l.closest(".chat-item-summary") ? "summary" : l.closest(".chat-task") ? "block" : l.closest(".chat-turn") ? "turn" : "other";
  return {
    count: lines.length, shown: shown.length, state: l.getAttribute("data-state"), role: l.getAttribute("role"),
    text: seen(l), said: said ? said.textContent : null, title: name ? name.getAttribute("title") : null, wordsTitle: words ? words.getAttribute("title") : null, nameColor: name ? getComputedStyle(name).color : null,
    color: getComputedStyle(words || l).color, button: btn ? btn.textContent.trim() : null, href: btn ? btn.getAttribute("href") : null, btnH: r ? Math.round(r.height) : null,
    inHidden: !!l.closest("[hidden]"), place, dim: probe("var(--dim)"), ink: probe("var(--text)"),
    wide: document.scrollingElement.scrollWidth > innerWidth + 1, right: Math.round(l.getBoundingClientRect().right),
  };
})()`;

interface TrfConfirm {
  kind: string;
  title: string | null;
  focus: string | null;
  path: string | null;
  pathMono: boolean;
  pathColor: string;
  ink: string;
  text: string;
  trust: boolean;
  trustDisabled: boolean;
  close: string | null;
  rootMono: boolean | null;
  rootColor: string | null;
  state: string | null;
  notice: string | null;
  repo: string | null;
  animation: string;
  right: number;
  cancelH: number | null;
  trustH: number | null;
}

/** In-page: the confirm that shows (a dialog or a sheet), its focus, its path and words, and its buttons. */
const TRF_CONFIRM = `(() => {
  const vis = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden";
  const probe = (v) => { const s = document.createElement("span"); s.style.color = v; document.body.appendChild(s); const c = getComputedStyle(s).color; s.remove(); return c; };
  const box = [...document.querySelectorAll('[data-testid="dialog-trust"]')].find(vis);
  if (!box) return null;
  const a = document.activeElement;
  const path = box.querySelector('[data-testid="trust-path"]');
  const t = (sel) => { const el = box.querySelector(sel); return el && vis(el) ? el.textContent.replace(/\\s+/g, " ").trim() : null; };
  const trust = box.querySelector('[data-testid="confirm-trust"]');
  const cancel = box.querySelector('[data-testid="trust-cancel"], [data-testid="sheet-cancel"]');
  const root = box.querySelector(".trust-root");
  return {
    kind: box.classList.contains("sheet") ? "sheet" : box.classList.contains("dialog") ? "dialog" : box.className,
    title: t("h2"), focus: a ? (a.getAttribute("data-testid") || a.tagName.toLowerCase()) : null,
    path: path ? path.textContent : null, pathMono: !!path && /mono|courier|menlo|consol/i.test(getComputedStyle(path).fontFamily),
    pathColor: path ? getComputedStyle(path).color : "", ink: probe("var(--text)"), text: box.textContent.replace(/\\s+/g, " ").trim(),
    trust: !!trust && vis(trust), trustDisabled: !!trust && (trust.disabled || trust.getAttribute("aria-disabled") === "true"),
    close: cancel ? cancel.textContent.trim() : null, rootMono: root ? /mono|courier|menlo|consol/i.test(getComputedStyle(root).fontFamily) : null, rootColor: root ? getComputedStyle(root).color : null,
    state: t('[data-testid="trust-state"]'), notice: t('[data-testid="dialog-notice"]'), repo: t('[data-testid="trust-repo"]'),
    animation: getComputedStyle(box).animationName, right: Math.round(box.getBoundingClientRect().right),
    // The layout height (offsetHeight), which the dialog's opening scale does not shrink while it runs.
    cancelH: cancel ? cancel.offsetHeight : null, trustH: trust ? trust.offsetHeight : null,
  };
})()`;

async function trfUntil<T>(page: Page, expr: string, ok: (v: T) => boolean, ms: number): Promise<T> {
  const end = Date.now() + ms;
  let v = await page.evaluate<T>(expr);
  while (!ok(v) && Date.now() < end) {
    await sleep(100);
    v = await page.evaluate<T>(expr);
  }
  return v;
}

/** A line as each check reads it: its words, state, colours, its button, and 44 px on touch. */
function trfLineFindings(l: TrfLine, vp: Viewport, want: { state: string; text: string; button: string | null; place?: string; lines?: number; path?: string }, at: string, fail: (t: string) => void) {
  if (l.state === undefined) return fail(`${at}: the row's trust line does not show (${l.shown} of ${l.count} lines show)`);
  if (want.lines !== undefined && l.shown !== want.lines) fail(`${at}: ${l.shown} trust lines show, not ${want.lines} (one per refused folder)`);
  if (l.state !== want.state) fail(`${at}: the line's state is ${l.state}, not ${want.state}`);
  if (l.role !== "status") fail(`${at}: the line's role is ${l.role}, not status`);
  const words = want.text + (want.button ? ` ${want.button}` : "");
  if (l.text !== words) fail(`${at}: the line reads ${JSON.stringify(l.text)}, not ${JSON.stringify(words)}`);
  if (want.place && l.place !== want.place) fail(`${at}: the line sits in the ${l.place}, not under the ${want.place}`);
  if (l.inHidden) fail(`${at}: the line is inside hidden work`);
  if (want.state !== "trusted" && want.state !== "already" && l.color !== l.dim) fail(`${at}: the line's words are ${l.color}, not --dim (${l.dim})`);
  if ((want.state === "trusted" || want.state === "already") && l.color !== l.ink) fail(`${at}: ${want.state} is in ${l.color}, not --text (${l.ink})`);
  if (l.title && l.nameColor !== l.ink) fail(`${at}: the folder's name is ${l.nameColor}, not --text (${l.ink})`);
  // Every state names its folder on screen (R127 review, the lead's words), with the full path as its title.
  if (!l.title) fail(`${at}: the line does not name its folder`);
  if (want.path !== undefined && l.title !== want.path) fail(`${at}: the line's title is ${JSON.stringify(l.title)}, not the folder's full path`);
  if (vp.touch && want.button && (l.btnH ?? 0) < 44) fail(`${at}: the line's button is ${l.btnH} px high on touch, under 44`);
  if (l.wide || (l.right ?? 0) > vp.width) fail(`${at}: the line runs past the right edge (${l.right} px of ${vp.width})`);
}

/** The confirm as it opens: Cancel focused, the real path in mono and --text, Claude Code's words, its one action. */
function trfConfirmFindings(c: TrfConfirm | null, vp: Viewport, path: string, at: string, fail: (t: string) => void, opts: { trust: boolean; repo?: string | null }) {
  if (!c) return fail(`${at}: the confirm does not show`);
  const sheet = vp.name === "phone";
  if (c.kind !== (sheet ? "sheet" : "dialog")) fail(`${at}: the confirm is a ${c.kind}, not a ${sheet ? "sheet" : "dialog"}`);
  if (c.title !== "Trust this folder?") fail(`${at}: the confirm's title is ${JSON.stringify(c.title)}`);
  if (c.focus !== (sheet ? "sheet-cancel" : "trust-cancel")) fail(`${at}: the first focus is on ${c.focus}, not Cancel`);
  if (c.path !== path) fail(`${at}: the confirm names ${JSON.stringify(c.path)}, not the real path ${JSON.stringify(path)}`);
  if (!c.pathMono || c.pathColor !== c.ink) fail(`${at}: the path is not in mono and --text (${c.pathColor})`);
  for (const w of [TRF_CC_QUESTION, TRF_CC_ALLOWS]) if (!c.text.includes(w)) fail(`${at}: the confirm lacks Claude Code's words ${JSON.stringify(w.slice(0, 40))}...`);
  if (c.text.includes("Security guide")) fail(`${at}: the confirm shows the Security guide link`);
  if (opts.trust !== c.trust) fail(`${at}: Trust this folder ${c.trust ? "shows" : "does not show"}`);
  if (opts.repo !== undefined && (opts.repo ?? null) !== c.repo) fail(`${at}: the repository line is ${JSON.stringify(c.repo)}, not ${JSON.stringify(opts.repo)}`);
  // The root that Claude Code records the trust on reads as strongly as the path (R127 review).
  if (c.repo && (!c.rootMono || c.rootColor !== c.ink)) fail(`${at}: the repository root is not in mono and --text (${c.rootColor})`);
  // Cancel while there is a press to cancel (R127 review: Close, or Done on the sheet, once there is none).
  if (opts.trust && !c.trustDisabled && c.close !== "Cancel") fail(`${at}: the confirm's close control says ${JSON.stringify(c.close)}, not Cancel`);
  if (c.right > vp.width) fail(`${at}: the confirm runs past the right edge`);
  if (vp.touch && ((c.cancelH ?? 44) < 44 || (c.trustH ?? 44) < 44)) fail(`${at}: a confirm button is under 44 px on touch (Cancel ${c.cancelH}, Trust ${c.trustH})`);
}

/** The shell socket's JSON frames (the pane's control frames), as the browser saw them go out. */
function trfShellFrames(page: Page): { frames: Record<string, any>[]; off: () => void } {
  const sockets = new Set<string>();
  const frames: Record<string, any>[] = [];
  const off = cdp.on((e) => {
    if (e.sessionId !== page.session) return;
    const p = e.params ?? {};
    if (e.method === "Network.webSocketCreated") {
      try {
        if (new URL(p.url).pathname === WIRE.shellPath) sockets.add(p.requestId);
      } catch {}
    } else if (e.method === "Network.webSocketFrameSent" && sockets.has(p.requestId) && p.response?.opcode === 1) {
      try {
        frames.push(JSON.parse(p.response.payloadData) as Record<string, any>);
      } catch {}
    }
  });
  return { frames, off };
}

/** Every running animation (a sheet's rise, a dialog's entrance) is over, or 2 s passed. */
const TRF_STILL = `Promise.race([Promise.all(document.getAnimations().filter((a) => { const t = a.effect && a.effect.getComputedTiming(); return !t || Number.isFinite(t.endTime); }).map((a) => a.finished.catch(() => null))), new Promise((r) => setTimeout(r, 2000))]).then(() => true)`;

/**
 * Press a control once it stands still: a click on a laptop (`double`: a double click), a tap on touch (`double`: a
 * second tap 60 ms later).
 */
async function trfPress(page: Page, sel: string, double = false): Promise<boolean> {
  await page.evaluate(TRF_STILL);
  const at = await page.locate(sel);
  if (!at) return false;
  if (!double) {
    await page.press(at.x, at.y);
    return true;
  }
  if (page.vp.touch) {
    await page.press(at.x, at.y);
    await sleep(60);
    if (await page.evaluate<boolean>(SHOWN_ANY(sel))) await page.press(at.x, at.y);
    return true;
  }
  await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: at.x, y: at.y });
  for (const clickCount of [1, 2]) {
    await page.send("Input.dispatchMouseEvent", { type: "mousePressed", x: at.x, y: at.y, button: "left", buttons: 1, clickCount });
    await page.send("Input.dispatchMouseEvent", { type: "mouseReleased", x: at.x, y: at.y, button: "left", buttons: 0, clickCount });
  }
  return true;
}

const trfName = (p: string) => p.split("/").filter(Boolean).slice(-2).join("/");
const trfShot = (vp: Viewport, theme: Theme, step: string) => shotName("trust", "trust-folder", vp, theme, step);
const trfDone = (r: Omit<CheckResult, "status" | "kind" | "name" | "route" | "scene">) => finish({ kind: "flow", name: "trust-folder", route: "trust", scene: "trust", ...r });

/** The pane after Open in terminal's route: one type_trust naming the row, never the resume command, and the pane's line. */
async function trfPane(page: Page, shell: { frames: Record<string, any>[] }, row: string, at: string, fail: (t: string) => void, details: Record<string, unknown>) {
  await waitShown(page, ["terminal-pane"], 8000);
  const note = () => page.evaluate<string | null>(`(() => { const el = [...document.querySelectorAll('[data-testid="terminal-note"]')].find((e) => e.getClientRects().length); return el ? el.textContent.replace(/\\s+/g, " ").trim() : null; })()`);
  const end = Date.now() + 10_000;
  while (Date.now() < end && !(shell.frames.some((x) => x.t === "type_trust") && (await note()))) await sleep(100);
  await sleep(500);
  const typed = shell.frames.filter((x) => x.t === "type_trust");
  details.shell = { frames: shell.frames.filter((x) => x.t !== "resize"), note: await note() };
  if (typed.length !== 1 || typed[0]!.toolUse !== row || Object.keys(typed[0]!).sort().join(",") !== "t,toolUse") fail(`${at}: the pane sent ${JSON.stringify(typed)}, not one type_trust with the row`);
  if (shell.frames.some((x) => x.t === "type_resume")) fail(`${at}: the pane asked for the resume command too`);
  const line = await note();
  if (line !== TRF_PANE_LINE) fail(`${at}: the pane's line is ${JSON.stringify(line)}, not ${JSON.stringify(TRF_PANE_LINE)}`);
}

/**
 * One fresh seed's run: the link that only opens the confirm (and Reduce motion), Cancel, the line where each view puts
 * it (`full`: the laptop's summary row and Verbose too), the line's button and Enter on Cancel, then Trust this folder's
 * one request and Trusted.
 */
async function trustFolderRun(b: Booted, seed: Awaited<ReturnType<typeof trfSeed>>, vp: Viewport, theme: Theme, full: boolean): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const chatPath = `/c/${TRF_CHAT}`;
  const confirmPath = `${chatPath}/trust/${TRF_ROW}`;
  const at = `${vp.width}x${vp.height} ${theme}`;
  const path = join(b.seed.folders.kitespan, seed.nested);
  const name = trfName(path);
  const offered = { state: "offered", text: `${name} ${TRF_OFFERED}`, button: "Trust this folder", path };
  let shot: string | undefined;
  try {
    await withPage(vp, theme, async (page, wire) => {
      // ---- a link to the confirm, opened as a new document: it only opens it (5.2), also after a reload
      await page.send("Emulation.setEmulatedMedia", { media: "screen", features: [{ name: "prefers-color-scheme", value: theme }, { name: "prefers-reduced-motion", value: "reduce" }] });
      await page.navigate(b.base + confirmPath);
      await waitShown(page, ["chat", "dialog-trust"], 8000);
      const linked = await trfUntil<TrfConfirm | null>(page, TRF_CONFIRM, (c) => !!c, 4000);
      details.linked = linked;
      trfConfirmFindings(linked, vp, path, `${at}, opened by its link`, fail, { trust: true, repo: null });
      // Reduce motion: the dialog and the sheet only fade.
      if (linked && linked.animation !== "fade-in") fail(`${at}: under Reduce motion the confirm's entrance is ${linked.animation}, not the fade`);
      await page.send("Emulation.setEmulatedMedia", { media: "screen", features: [{ name: "prefers-color-scheme", value: theme }] });
      // The motion back on, the entrance runs again: the still waits for it.
      await page.evaluate(P2_DRAWN);
      await page.evaluate(TRF_STILL);
      shot = trfShot(vp, theme, "confirm");
      await tfShot(page, shot);
      const s1 = await page.probe();
      if (!sameUrl(s1.path, confirmPath)) fail(`${at}: the confirm's link became ${s1.path}`, "url");
      if (s1.notices.length) fail(`${at}: a 5.4 line shows over the confirm: ${clipList(s1.notices)}`, "notice");
      quietFindings(wire, 0, await recorder(page), failures, `${at}, the confirm's link: `);
      stateFindings(s1, vp, failures, `${at}, the confirm: `);
      const reloadMark = wire.mark();
      await page.reload();
      await waitShown(page, ["chat", "dialog-trust"], 8000);
      const again = await trfUntil<TrfConfirm | null>(page, TRF_CONFIRM, (c) => !!c, 4000);
      trfConfirmFindings(again, vp, path, `${at}, after a reload of the link`, fail, { trust: true });
      quietFindings(wire, reloadMark, await recorder(page), failures, `${at}, after a reload of the link: `);

      // ---- Cancel goes back to the chat, sending nothing; the line offers Trust this folder under the folded turn
      const cancelMark = wire.mark();
      if (!(await trfPress(page, vp.name === "phone" ? '[data-testid="sheet-cancel"]' : '[data-testid="trust-cancel"]'))) fail(`${at}: no Cancel to press`);
      await trfUntil<TrfConfirm | null>(page, TRF_CONFIRM, (c) => !c, 3000);
      await page.evaluate(P2_DRAWN);
      const back = await page.probe();
      if (!sameUrl(back.path, chatPath)) fail(`${at}: Cancel went to ${back.path}, not the chat`, "url");
      const folded = await trfUntil<TrfLine>(page, trfLine(TRF_ROW), (l) => l.state !== undefined, 6000);
      details.folded = folded;
      trfLineFindings(folded, vp, { ...offered, place: "turn", lines: 2 }, `${at}, the folded turn`, fail);
      if (folded.title !== path) fail(`${at}: the folder's name has the title ${JSON.stringify(folded.title)}, not its full path`);
      if (folded.href !== confirmPath) fail(`${at}: Trust this folder links to ${folded.href}, not the confirm's route`);
      await tfShot(page, trfShot(vp, theme, "line-turn"));
      if (full) {
        // The turn opened: its summary row holds both refused rows (Normal); in Verbose each row holds its own.
        const turnId = await page.evaluate<string | null>(`(() => { const l = [...document.querySelectorAll('[data-testid^="trust-line-"]')].find((e) => e.getClientRects().length); const t = l && l.closest("[data-turn-id]"); return t ? t.getAttribute("data-turn-id") : null; })()`);
        if (!turnId || !(await tfPress(page, turnId))) fail(`${at}: the folded turn's line that holds the line cannot be pressed`);
        const summary = await trfUntil<TrfLine>(page, trfLine(TRF_ROW), (l) => l.place === "summary", 3000);
        details.summary = summary;
        trfLineFindings(summary, vp, { ...offered, place: "summary", lines: 2 }, `${at}, the summary row`, fail);
        await tfShot(page, trfShot(vp, theme, "line-summary"));
        await page.navigate(`${b.base}${chatPath}?view=verbose`);
        await waitShown(page, ["chat", "conversation"]);
        const own = await trfUntil<TrfLine>(page, trfLine(TRF_ROW), (l) => l.place === "row", 6000);
        details.verbose = own;
        trfLineFindings(own, vp, { ...offered, place: "row", lines: 2 }, `${at}, Verbose`, fail);
        if (own.href !== `${confirmPath}?view=verbose`) fail(`${at}: in Verbose the button links to ${own.href}`);
        await page.evaluate(`(() => { const l = document.querySelector('[data-testid="trust-line-${TRF_ROW}"]'); if (l) l.scrollIntoView({ block: "center" }); return true; })()`);
        await tfShot(page, trfShot(vp, theme, "line-row"));
        await page.navigate(b.base + chatPath);
        await waitShown(page, ["chat", "conversation"]);
        await trfUntil<TrfLine>(page, trfLine(TRF_ROW), (l) => l.state !== undefined, 6000);
      }
      quietFindings(wire, cancelMark, await recorder(page), failures, `${at}, Cancel and the views: `);

      // ---- the line's button opens the confirm; Enter on the focused Cancel trusts nothing
      const enterMark = wire.mark();
      if (!(await trfPress(page, `[data-testid="trust-confirm-${TRF_ROW}"]`))) fail(`${at}: the line's Trust this folder cannot be pressed`);
      const opened = await trfUntil<TrfConfirm | null>(page, TRF_CONFIRM, (c) => !!c, 4000);
      trfConfirmFindings(opened, vp, path, `${at}, opened from the line`, fail, { trust: true });
      const viaLine = await page.probe();
      if (!sameUrl(viaLine.path, confirmPath)) fail(`${at}: the line's button opened ${viaLine.path}, not the confirm's route`, "url");
      await page.key("Enter");
      if (await trfUntil<TrfConfirm | null>(page, TRF_CONFIRM, (c) => !c, 3000)) fail(`${at}: Enter on the focused Cancel did not close the confirm`);
      // The focus goes back to the line's button that opened it.
      const backTo = await trfUntil<string | null>(page, `(() => { const a = document.activeElement; return a ? a.getAttribute("data-testid") : null; })()`, (x) => x === `trust-confirm-${TRF_ROW}`, 2000);
      if (backTo !== `trust-confirm-${TRF_ROW}`) fail(`${at}: after the confirm closed the focus is on ${backTo}, not the line's button`);
      quietFindings(wire, enterMark, await recorder(page), failures, `${at}, the line's button, then Enter on Cancel: `);

      // ---- Trust this folder: one request for a double click (or two taps), the ack `trusted`, the line says so
      await trfPress(page, `[data-testid="trust-confirm-${TRF_ROW}"]`);
      await trfUntil<TrfConfirm | null>(page, TRF_CONFIRM, (c) => !!c?.trust, 4000);
      const pressMark = wire.mark();
      const traceBefore = b.trace().length;
      if (!(await trfPress(page, '[data-testid="confirm-trust"]', true))) fail(`${at}: Trust this folder cannot be pressed`);
      const end = Date.now() + 20_000;
      while (Date.now() < end && !wire.acks.some((a) => wire.framesSince(pressMark).some((f) => f.t === "trust_folder" && f.rid === a.rid))) await sleep(100);
      await sleep(300);
      const sent = acting(wire.framesSince(pressMark));
      details.pressed = { sent: sent.map((f) => f.frame), acks: wire.acks.filter((a) => sent.some((f) => f.rid === a.rid)) };
      if (sent.length !== 1 || sent[0]!.t !== "trust_folder") fail(`${at}: Trust this folder sent ${clipList(sent.map(frameText)) || "nothing"}, not one trust_folder`, "frames");
      const f = sent[0]?.frame ?? {};
      if (f.chat !== TRF_CHAT || f.toolUse !== TRF_ROW || f.path !== path || Object.keys(f).sort().join(",") !== "chat,path,rid,t,toolUse") fail(`${at}: the trust_folder frame is ${JSON.stringify(f)}`, "frames");
      const ack = wire.acks.find((a) => a.rid === sent[0]?.rid);
      if (!ack?.ok || (ack.result as { trust?: string } | null)?.trust !== "trusted") fail(`${at}: the ack is ${ack ? (ack.ok ? JSON.stringify(ack.result) : ack.code) : "missing"}, not {trust: "trusted"}`, "ack");
      const rec = (await recorder(page)) ?? [];
      if (rec.filter((t) => t === "trust_folder").length !== 1) fail(`${at}: window.__kitespanFrames holds ${clipList(rec) || "nothing"}, not one trust_folder`, "recorder");
      // Claude Code's own record: the fake claude saw the attestation for that folder, started in that folder.
      const seen = b.trace().slice(traceBefore).filter((l) => l.t === "workspace_trust");
      details.attested = seen;
      if (!seen.some((l) => l.attested === true && l.directory === path)) fail(`${at}: the fake claude saw no attestation for the folder (${JSON.stringify(seen)})`);
      if (await trfUntil<TrfConfirm | null>(page, TRF_CONFIRM, (c) => !c, 5000)) fail(`${at}: the confirm stays open after the answer`);
      const trusted = await trfUntil<TrfLine>(page, trfLine(TRF_ROW), (l) => l.state === "trusted", 5000);
      details.trusted = trusted;
      trfLineFindings(trusted, vp, { state: "trusted", text: `${name} ${TRF_TRUSTED}`, button: null, lines: 2, path }, `${at}, after the answer`, fail);
      // The answer took the line's button away: the focus that opened the confirm comes back to the line (R127 review),
      // not to the page's body. On a laptop, where a keyboard is.
      if (!vp.touch) {
        const focus = await trfUntil<string | null>(page, `(() => { const a = document.activeElement; return a ? a.getAttribute("data-testid") || a.tagName.toLowerCase() : null; })()`, (x) => x === `trust-line-${TRF_ROW}`, 2000);
        if (focus !== `trust-line-${TRF_ROW}`) fail(`${at}: after Trusted the focus is on ${focus}, not the trust line`);
      }
      // The other folder's line still offers: an answer is the folder's own.
      const other = await page.evaluate<TrfLine>(trfLine(seed.inRepoRow));
      if (other.state !== "offered") fail(`${at}: the other folder's line is ${other.state}, not offered`);
      await tfShot(page, trfShot(vp, theme, "trusted"));
      if (vp.name === "phone") await trfOtherDevice(b, seed, page, theme, at, fail, details);
      issueFindings(page.takeIssues(), failures);
      const posts = wire.httpSince(0).filter((h) => MUTATING_METHODS.has(h.method));
      if (posts.length) fail(`${at}: the page sent ${clipList(posts.map(httpText))}`, "frames");
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return trfDone({ size: sizeTag(vp), theme, path: confirmPath, failures, warnings, note: full ? "the link, Reduce motion, the line in the folded turn, the summary row and Verbose, Enter on Cancel, one request, Trusted" : "the link, Reduce motion, the line in the folded turn, Enter on Cancel, one request, Trusted", ms: Date.now() - t0, details, shot });
}

/**
 * The phone's confirm sheet for the other folder stays open while another device (a laptop page) presses Trust this
 * folder (D49): the same sheet element, which does not rise again, with Done at its top right once there is nothing to
 * cancel, the focus still on that button, and the answer's words in the action's place (R127 review).
 */
async function trfOtherDevice(b: Booted, seed: Awaited<ReturnType<typeof trfSeed>>, page: Page, theme: Theme, at: string, fail: (t: string) => void, details: Record<string, unknown>) {
  const route = `/c/${TRF_CHAT}/trust/${seed.inRepoRow}`;
  await page.navigate(b.base + route);
  await waitShown(page, ["chat", "dialog-trust"], 8000);
  await page.evaluate(TRF_STILL);
  const SHEET = `(() => { const s = [...document.querySelectorAll('[data-testid="dialog-trust"]')].find((e) => e.getClientRects().length); if (!s) return null; const top = s.querySelector('[data-testid="sheet-cancel"]'); const a = document.activeElement; return { mark: s.__trfMark || null, word: top ? top.textContent.trim() : null, focus: a ? a.getAttribute("data-testid") || a.tagName.toLowerCase() : null, rising: s.getAnimations().map((x) => x.animationName || "?").filter((n) => n !== "?"), state: (() => { const el = s.querySelector('[data-testid="trust-state"]'); return el ? el.textContent.trim() : null; })() }; })()`;
  await page.evaluate(`(() => { const s = document.querySelector('[data-testid="dialog-trust"]'); if (s) s.__trfMark = "first"; return true; })()`);
  const before = await page.evaluate<Record<string, unknown> | null>(SHEET);
  const laptop = VIEWPORTS.find((v) => v.name === "laptop")!;
  await withPage(laptop, theme, async (other) => {
    await other.navigate(b.base + route);
    await waitShown(other, ["chat", "dialog-trust"], 8000);
    if (!(await trfPress(other, '[data-testid="confirm-trust"]'))) fail(`${at}, another device: its Trust this folder cannot be pressed`);
    await trfUntil<TrfConfirm | null>(other, TRF_CONFIRM, (c) => !c, 8000);
  });
  const after = await trfUntil<Record<string, unknown> | null>(page, SHEET, (x) => !!x && typeof x.state === "string" && x.state.endsWith(` ${TRF_TRUSTED}`), 8000);
  details.otherDevice = { before, after };
  if (!after) return fail(`${at}, another device: the phone's confirm closed`);
  if (after.mark !== "first") fail(`${at}, another device: the phone's sheet was drawn again (a new element)`);
  if ((after.rising as string[]).length) fail(`${at}, another device: the phone's sheet runs ${JSON.stringify(after.rising)} again`);
  if (after.word !== "Done") fail(`${at}, another device: the sheet's top right says ${JSON.stringify(after.word)}, not Done`);
  if (after.focus !== "sheet-cancel") fail(`${at}, another device: the focus is on ${after.focus}, not the sheet's top-right button`);
  if (after.state !== `${trfName(join(b.seed.folders.kitespan, seed.inRepo))} ${TRF_TRUSTED}`) fail(`${at}, another device: the sheet says ${JSON.stringify(after.state)}`);
  await tfShot(page, trfShot(page.vp, theme, "other-device"));
}

/**
 * Read only, on one seed: a look's colours (or the tablet's dialog, or the confirm's repository line for the folder
 * inside the project's repository): the line under the folded turn and the confirm opened by its link; Escape closes it.
 */
async function trustFolderLookRun(b: Booted, seed: Awaited<ReturnType<typeof trfSeed>>, vp: Viewport, theme: Theme, look: P2LookId, repo: boolean): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = { look };
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const chatPath = `/c/${TRF_CHAT}`;
  const tag = repo ? "repo" : look;
  const at = `${vp.width}x${vp.height} ${theme}, ${tag}`;
  const row = repo ? seed.inRepoRow : TRF_ROW;
  const path = join(b.seed.folders.kitespan, repo ? seed.inRepo : seed.nested);
  let shot: string | undefined;
  try {
    await withPage(vp, theme, async (page, wire) => {
      await page.navigate(b.base + chatPath);
      await waitShown(page, ["chat", "conversation"]);
      if (look !== "glass") await wearLook(page, look, theme);
      const l = await trfUntil<TrfLine>(page, trfLine(row), (x) => x.state !== undefined, 6000);
      details.line = l;
      trfLineFindings(l, vp, { state: "offered", text: `${trfName(path)} ${TRF_OFFERED}`, button: "Trust this folder", place: "turn", lines: 2, path }, at, fail);
      await tfShot(page, trfShot(vp, theme, `line-${tag}`));
      await page.navigate(`${b.base}${chatPath}/trust/${row}`);
      await waitShown(page, ["chat", "dialog-trust"], 8000);
      if (look !== "glass") await wearLook(page, look, theme);
      const c = await trfUntil<TrfConfirm | null>(page, TRF_CONFIRM, (x) => !!x, 4000);
      details.confirm = c;
      const root = repo ? `This folder is part of the repository at ${b.seed.folders.kitespan}; trusting it trusts that whole repository, including when you run claude there.` : null;
      trfConfirmFindings(c, vp, path, at, fail, { trust: true, repo: root });
      await page.evaluate(TRF_STILL);
      shot = trfShot(vp, theme, `confirm-${tag}`);
      await tfShot(page, shot);
      await page.key("Escape");
      if (await trfUntil<TrfConfirm | null>(page, TRF_CONFIRM, (x) => !x, 3000)) fail(`${at}: Escape did not close the confirm`);
      quietFindings(wire, 0, await recorder(page), failures, `${at}: `);
      issueFindings(page.takeIssues(), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return trfDone({ size: sizeTag(vp), theme, path: `${chatPath}/trust/${row}`, failures, warnings, note: repo ? "the confirm's repository line" : vp.name === "medium" ? "the tablet's dialog" : `the ${look} look's colours`, ms: Date.now() - t0, details, shot });
}

/**
 * The fallback. With the seed's not-recorded fixture: Trust this folder's answer not_recorded, the line's Open in
 * terminal, then the pane. Without it: Open in terminal's route opened as a link (a pre-fill: the command typed, not run).
 */
async function trustFolderFallbackRun(b: Booted, vp: Viewport, theme: Theme, pressed: boolean): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = { pressed };
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const chatPath = `/c/${TRF_CHAT}`;
  const term = `${chatPath}/shell?type=trust&tool=${TRF_ROW}`;
  const at = `${vp.width}x${vp.height} ${theme}, the fallback`;
  let shot: string | undefined;
  try {
    await withPage(vp, theme, async (page, wire) => {
      const shell = trfShellFrames(page);
      try {
        let mark = 0;
        if (pressed) {
          await page.navigate(b.base + chatPath);
          await waitShown(page, ["chat", "conversation"]);
          await trfUntil<TrfLine>(page, trfLine(TRF_ROW), (x) => x.state !== undefined, 6000);
          await trfPress(page, `[data-testid="trust-confirm-${TRF_ROW}"]`);
          await trfUntil<TrfConfirm | null>(page, TRF_CONFIRM, (c) => !!c?.trust, 4000);
          const pressMark = wire.mark();
          await trfPress(page, '[data-testid="confirm-trust"]');
          const pressedAt = Date.now();
          const l = await trfUntil<TrfLine>(page, trfLine(TRF_ROW), (x) => x.state === "not_recorded", 20_000);
          details.notRecorded = l;
          const sent = acting(wire.framesSince(pressMark));
          const ack = wire.acks.find((a) => a.rid === sent[0]?.rid);
          if (sent.length !== 1 || !ack?.ok || (ack.result as { trust?: string } | null)?.trust !== "not_recorded") fail(`${at}: the press sent ${clipList(sent.map(frameText)) || "nothing"} with the ack ${JSON.stringify(ack ?? null)}, not one trust_folder answered not_recorded`, "frames");
          trfLineFindings(l, vp, { state: "not_recorded", text: `Claude Code did not record ${trfName(l.title ?? "")} as trusted.`, button: "Open in terminal" }, at, fail);
          if (l.href !== term) fail(`${at}: Open in terminal links to ${l.href}, not ${term}`);
          await tfShot(page, trfShot(vp, theme, "not-recorded"));
          // A press of its own, as a reader's: the confirm swallows a second press within 500 ms of Trust this folder
          // (web/ui/secondPress.ts), and on the laptop the line's Open in terminal sits under that button's place.
          await sleep(Math.max(0, pressedAt + 600 - Date.now()));
          mark = wire.mark();
          await trfPress(page, `[data-testid="trust-terminal-${TRF_ROW}"]`);
        } else {
          await page.navigate(b.base + term);
        }
        await trfPane(page, shell, TRF_ROW, at, fail, details);
        const s = await page.probe();
        if (!sameUrl(s.path, term)) fail(`${at}: the pane's URL is ${s.path}, not ${term}`, "url");
        if (s.notices.length) fail(`${at}: a 5.4 line shows: ${clipList(s.notices)}`, "notice");
        quietFindings(wire, mark, ((await recorder(page)) ?? []).filter((t) => t !== "trust_folder"), failures, `${at}, Open in terminal: `);
        shot = trfShot(vp, theme, pressed ? "fallback" : "fallback-link");
        await tfShot(page, shot);
        issueFindings(page.takeIssues(), failures);
      } finally {
        shell.off();
      }
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return trfDone({ size: sizeTag(vp), theme, path: term, failures, warnings, note: pressed ? "not recorded, then Open in terminal: one type_trust and the pane's line" : "Open in terminal's route: one type_trust and the pane's line", ms: Date.now() - t0, details, shot });
}

/** R127's runs, each press on a fresh seed of the trust scene, the read-only ones on one more (none with --base). */
async function trustFolderFlows(record: (r: CheckResult) => void, problems: string[]): Promise<void> {
  if (BASE) {
    console.log("ui-check: trust-folder boots seeds of its own (the trust scene), so --base runs none of it");
    return;
  }
  const laptop = CORE.some((v) => v.name === "laptop") ? WIDE_LAPTOP : null;
  const phone = CORE.find((v) => v.name === "phone") ?? null;
  const tablet = CORE.find((v) => v.name === "medium") ?? null;
  const sizes = [laptop, phone, ...extraAt("trust-folder")].filter((v): v is Viewport => !!v);
  const seed = await trfSeed();
  /** One seed of the trust scene for `run`; a seed that does not boot fails the runs it was for. */
  const onSeed = async (fixture: Partial<Fixture> | undefined, runs: { vp: Viewport; theme: Theme }[], run: (b: Booted) => Promise<void>) => {
    if (cdp.closed || !runs.length) return;
    let b: Booted;
    try {
      b = await boot({ scene: "trust", port: PORT, dist: built!, keep: KEEP, env: SERVER_ENV, ...(fixture ? { fixture } : {}) });
    } catch (e) {
      for (const r of runs) record(trfDone({ size: sizeTag(r.vp), theme: r.theme, path: `/c/${TRF_CHAT}/trust/${TRF_ROW}`, failures: [{ code: "seed", text: `the seed did not boot: ${(e as Error).message}` }], warnings: [], note: "", ms: 0, details: {} }));
      return;
    }
    live.add(b);
    try {
      await run(b);
    } finally {
      const r = await b.stop();
      live.delete(b);
      if (r.code !== 0) problems.push(`scene trust (trust-folder): the server exited with ${r.code}`);
      if (r.leftovers.length) problems.push(`scene trust (trust-folder): ${r.leftovers.length} process(es) outlived the server and were ended by pid`);
    }
  };
  for (const vp of sizes) for (const theme of THEMES) await onSeed(undefined, [{ vp, theme }], async (b) => record(await trustFolderRun(b, seed, vp, theme, vp === laptop)));
  // Read only: each look at the laptop, the tablet's dialog, the repository line; and Open in terminal's route.
  const looks: { vp: Viewport; theme: Theme; look: P2LookId; repo: boolean }[] = [];
  if (laptop) for (const look of P2_LOOKS.filter((l) => l !== "glass")) for (const theme of THEMES) looks.push({ vp: laptop, theme, look, repo: false });
  if (tablet && THEMES.includes("light")) looks.push({ vp: tablet, theme: "light", look: "glass", repo: false });
  for (const vp of sizes) if (THEMES.includes("light")) looks.push({ vp, theme: "light", look: "glass", repo: true });
  const links = seed.notRecorded ? [] : sizes.flatMap((vp) => THEMES.map((theme) => ({ vp, theme })));
  await onSeed(undefined, [...looks, ...links], async (b) => {
    for (const r of looks) if (!cdp.closed) record(await trustFolderLookRun(b, seed, r.vp, r.theme, r.look, r.repo));
    for (const r of links) if (!cdp.closed) record(await trustFolderFallbackRun(b, r.vp, r.theme, false));
  });
  // The fallback after Claude Code recorded nothing: on seeds whose fake claude answers so (the seed's fixture).
  if (seed.notRecorded) for (const vp of sizes) for (const theme of THEMES) await onSeed(seed.notRecorded, [{ vp, theme }], async (b) => record(await trustFolderFallbackRun(b, vp, theme, true)));
  else console.log("ui-check: trust-folder: the seed exports no TRUST_NOT_RECORDED fixture, so the fallback runs from Open in terminal's route only");
}

// R131 (owner row 131; FIX-R131 3, DESIGN-R131 5 to 13): background-session, the background sessions that a chat
// starts with `claude --bg`, on a main scene seed of its own per run. Each run writes into its own booted seed (its
// scratch folder only): the example chat's last turn (one Bash call whose result printed Claude Code's launch lines
// for two sessions, after "Starting background service…"), each session's transcript under its folder's slug (the
// first with Claude Code's permission-mode record, Bypass permissions), a stand-in `sleep` per session with its record
// in the seed's registry of running sessions (kind bg, the short id, status), and the fake claude's `agents --json`
// list (its fixture, which it reads at each start). At 1280x800 and 390x844 touch, light and dark: the lines say
// Working under the folded turn's line (on the laptop also under the summary row once the turn opens, and under the row
// in Verbose), with their dot, words, colours and Open (44 px on touch; on the phone every Open in one column at the
// right edge); Open opens the read-only view (Back "Chat", the head with the name, the folder, the Bypass pill with no
// comma beside it and the start, the session's own rows, no composer, the dock with the state, Stop and Open in
// terminal) and sends nothing; lines added to the session's transcript show in the open view; the second session
// completes while the chat is not on screen and lights the chat's dot (unread, with its words for screen readers),
// which that session's line on screen clears (the chat at its end alone would not), and then the chat's bar marks
// nothing; the first waits for a permission prompt: Needs input with the warm pulse (Reduce motion stops it) on the
// line and in the dock, the chat's dot waiting, the chat's own bar marked with that dot as a link to the session's view
// (44 px on touch), and its open call shows no spinner; Open in terminal types `claude attach <id>` (one type_attach
// naming the id, never Enter) and the pane says how to answer and leave; Stop opens the confirm (Cancel focused first,
// Claude Code's words; on the laptop Enter on Cancel stops nothing), and Stop (a double click, two taps) sends exactly
// one background_stop, the ack says stopped, the fake claude saw one `stop <id>`, and the dock and the line say Stopped,
// with Open in terminal a plain button now; the stop route then opens the not-running confirm (the name and its line,
// no Stop, no word of what a Stop keeps). The fake claude's version is the gate's (2.1.318). On one more seed, read only:
// the line, the view and the confirm in each other look at 1280x800 light, and the tablet's view and dialog
// (834x1194). Screenshots show the machine's name as "this-machine" (tfShot).

const BGS_CHAT = EX.chat;
/** The launch row: one Bash call that started two background sessions. */
const BGS_CALL = "toolu_01StartWorkers";
/** The two sessions the launch row printed (8-hex short ids, as `claude --bg` prints them). */
const BGS_A = { id: "3f9a1c2e", name: "investigate-negative-qty", folder: "worktrees/remove-negative-qty", session: "3f9a1c2e-6d1b-4c55-9a77-2f3a8e9b0c11" } as const;
const BGS_B = { id: "7c5dcf5d", name: "flaky-test-fix", folder: "worktrees/flaky-upload", session: "7c5dcf5d-2a4e-4f1b-8c3d-5e6f7a8b9c0d" } as const;
const BGS_PANE_LINE = "The command is at the prompt. Press Enter to open the session, and answer its prompts there. Ctrl+Z drops back to your shell, and the session keeps running.";
const BGS_KEPT = (id: string) => `Its conversation is kept; resume it later with claude attach ${id}.`;
/** Claude Code's launch block for one session (2.1.318 Xtt): the line, then its four dim hint lines. */
const bgsLaunch = (id: string, name: string) =>
  [`backgrounded · ${id} · ${name}`, "  claude agents             list sessions", `  claude attach ${id}    open in this terminal`, `  claude logs ${id}      show recent output`, `  claude stop ${id}      stop this session`].join("\n");
/** The text the view's newest row adds once the flow appends it to the first session's transcript. */
const BGS_LATER = "The check compares the quantity with the maximum but never with one, so a quantity of -3 passes.";

type BgsTranscript = InstanceType<(typeof import("../test/click/seed/demo"))["Transcript"]>;

interface BgsWorker {
  id: string;
  name: string;
  session: string;
  cwd: string;
  transcript: string;
  t: BgsTranscript;
  written: number;
  startedAt: number;
  pid: number;
  record: string;
  stop(): void;
}
interface BgsWorld {
  project: string;
  fixture: string;
  a: BgsWorker;
  b: BgsWorker;
}

const bgsText = (t: string) => ({ type: "text", text: t });
const bgsTool = (id: string, name: string, input: Record<string, unknown>) => ({ type: "tool_use", id, name, input });

/** Append the transcript lines that `w.t` made since the last write. */
function bgsFlush(w: BgsWorker) {
  const lines = w.t.file().lines;
  const fresh = lines.slice(w.written);
  w.written = lines.length;
  if (fresh.length) writeFileSync(w.transcript, fresh.map((l) => `${l}\n`).join(""), { flag: "a" });
}

/** The session's record in the seed's registry of running sessions, as Claude Code 2.1.318 writes a background one. */
async function bgsRecord(w: BgsWorker, status: "busy" | "waiting" | "idle", waitingFor?: string) {
  const { procStart } = await import("../test/click/seed/running");
  const start = procStart(w.pid);
  if (start === null) throw new Error("the stand-in's start time cannot be read (no /proc)");
  const now = Date.now();
  writeFileSync(
    w.record,
    JSON.stringify({ pid: w.pid, sessionId: w.session, cwd: w.cwd, startedAt: w.startedAt, procStart: start, version: "2.1.318", kind: "bg", entrypoint: "sdk-ts", name: w.name, jobId: w.id, status, ...(waitingFor ? { waitingFor } : {}), updatedAt: now }),
    { mode: 0o600 },
  );
}

/** The fake claude's `agents --json --all` rows (its fixture, read at each start), as Claude Code prints background rows. */
function bgsAgents(world: BgsWorld, a: string, b: string) {
  const fx = JSON.parse(readFileSync(world.fixture, "utf8")) as Record<string, unknown>;
  const row = (w: BgsWorker, state: string) => ({
    ...(state === "working" || state === "blocked" ? { pid: w.pid, status: state === "blocked" ? "waiting" : "busy" } : {}),
    id: w.id,
    cwd: w.cwd,
    kind: "background",
    startedAt: w.startedAt,
    sessionId: w.session,
    name: w.name,
    ...(state === "blocked" ? { waitingFor: "permission prompt" } : {}),
    state,
  });
  fx.agents = [row(world.a, a), row(world.b, b)];
  writeFileSync(world.fixture, JSON.stringify(fx));
}

/** A stand-in process for a background session: `sleep`, ended by its pid only while it is still that sleep. */
function bgsStandIn(): { pid: number; stop(): void } {
  const proc = Bun.spawn(["sleep", "600"], { stdin: "ignore", stdout: "ignore", stderr: "ignore" });
  return {
    pid: proc.pid,
    stop() {
      let cmd = "";
      try {
        cmd = readFileSync(`/proc/${proc.pid}/cmdline`, "utf8").split("\0")[0] ?? "";
      } catch {}
      if (proc.exitCode === null && cmd.endsWith("sleep")) proc.kill("SIGTERM");
    },
  };
}

/**
 * Write this run's world into the booted seed: the two sessions' folders and transcripts, their stand-ins and records,
 * the fake's list, and the example chat's last turn with the launch row (before any page reads the chat's history).
 */
async function bgsWrite(b: Booted): Promise<BgsWorld> {
  const { realpathSync } = await import("node:fs");
  const { Transcript } = await import("../test/click/seed/demo");
  const { projectDirName } = await import("../test/click/seed/write");
  const project = realpathSync(b.seed.folders.kitespan);
  const config = b.seed.claudeConfig;
  const sessions = join(config, "sessions");
  mkdirSync(sessions, { recursive: true, mode: 0o700 });
  const now = Date.now();
  const worker = (s: typeof BGS_A | typeof BGS_B, minutes: number): BgsWorker => {
    const cwd = join(project, s.folder);
    mkdirSync(cwd, { recursive: true, mode: 0o700 });
    const dir = join(config, "projects", projectDirName(cwd));
    mkdirSync(dir, { recursive: true, mode: 0o700 });
    const transcript = join(dir, `${s.session}.jsonl`);
    writeFileSync(transcript, "", { mode: 0o600 });
    const stand = bgsStandIn();
    const startedAt = now - minutes * 60_000;
    return { id: s.id, name: s.name, session: s.session, cwd, transcript, t: new Transcript(s.session, cwd, "sdk-ts", startedAt), written: 0, startedAt, pid: stand.pid, record: join(sessions, `${stand.pid}.json`), stop: stand.stop };
  };
  const a = worker(BGS_A, 4);
  const w2 = worker(BGS_B, 3);
  // The first session: the brief, two reads and a test run whose result has not come (an open call).
  a.t.user("Follow BRIEF-investigate.md for remove-negative-qty: find why a negative quantity passes the cart check, and write what you find to FINDINGS.md.");
  a.t.assistant("msg_01BgaRead", [bgsText("I'll read the brief first, then the cart check."), bgsTool("toolu_01BgaBrief", "Read", { file_path: join(a.cwd, "BRIEF-investigate.md") })]);
  a.t.results([{ id: "toolu_01BgaBrief", content: "# Investigate\nFind why a negative quantity passes the cart check." }]);
  a.t.assistant("msg_01BgaGrep", [bgsTool("toolu_01BgaGrep", "Grep", { pattern: "quantity", path: "src" })]);
  a.t.results([{ id: "toolu_01BgaGrep", content: "src/upload.ts\nsrc/cart.ts" }]);
  a.t.assistant("msg_01BgaTest", [bgsTool("toolu_01BgaTest", "Bash", { command: "bun test test/upload.test.ts", description: "Run the cart test" })]);
  bgsFlush(a);
  // Claude Code writes the session's permission mode with its metadata (the SDK's reader skips the record).
  writeFileSync(a.transcript, `${JSON.stringify({ type: "permission-mode", permissionMode: "bypassPermissions", sessionId: a.session })}\n`, { flag: "a" });
  w2.t.user("Find why the upload test fails one run in five, and fix it.");
  w2.t.assistant("msg_01BgbRun", [bgsText("I'll run the test until it fails."), bgsTool("toolu_01BgbRun", "Bash", { command: "bun test test/upload.test.ts --rerun-each 20", description: "Run the upload test 20 times" })]);
  w2.t.results([{ id: "toolu_01BgbRun", content: "20 pass\n0 fail" }], { stdout: "20 pass\n0 fail", stderr: "", interrupted: false });
  bgsFlush(w2);
  const world: BgsWorld = { project, fixture: b.fake.fixturePath, a, b: w2 };
  bgsAgents(world, "working", "working");
  await bgsRecord(a, "busy");
  await bgsRecord(w2, "busy");

  // The example chat's last turn: the ask, one Bash call that started both sessions, its result, Claude's reply.
  const chatFile = [b.seed.folders.kitespan, project].map((f) => join(config, "projects", projectDirName(f), `${IDS.sessions.upload}.jsonl`)).find((p) => existsSync(p));
  if (!chatFile) throw new Error("the example chat's transcript is not in the seed");
  const old = readFileSync(chatFile, "utf8").trimEnd().split("\n");
  const last = JSON.parse(old[old.length - 1]!) as { uuid: string; cwd?: string; timestamp: string };
  const chatCwd = last.cwd ?? b.seed.folders.kitespan;
  let parent: string = last.uuid;
  let n = 0;
  let at = Math.max(Date.parse(last.timestamp), now - 90_000);
  const push = (type: "user" | "assistant", body: Record<string, unknown>) => {
    const uuid = `b1310000-0000-4000-8000-${(++n).toString(16).padStart(12, "0")}`;
    at += 10_000;
    const line = { parentUuid: parent, isSidechain: false, userType: "external", cwd: chatCwd, sessionId: IDS.sessions.upload, version: "2.1.318", gitBranch: "main", entrypoint: "sdk-ts", type, ...body, uuid, timestamp: new Date(at).toISOString() };
    parent = uuid;
    return JSON.stringify(line);
  };
  const msg = (id: string, block: Record<string, unknown>, stop: string) => ({ message: { id, type: "message", role: "assistant", model: "claude-opus-5-5", content: [block], stop_reason: stop || null, stop_sequence: null, usage: { input_tokens: 120, cache_creation_input_tokens: 0, cache_read_input_tokens: 4200, output_tokens: 80 } }, requestId: `req_${id.slice(-16)}` });
  const cmd = `cd ${BGS_A.folder} && claude --bg -n ${BGS_A.name} "Follow BRIEF-investigate.md" && cd ../.. && cd ${BGS_B.folder} && claude --bg -n ${BGS_B.name} "Fix the flaky upload test"`;
  const out = `Starting background service…\n${bgsLaunch(BGS_A.id, BGS_A.name)}\n${bgsLaunch(BGS_B.id, BGS_B.name)}`;
  const lines = [
    push("user", { message: { role: "user", content: "Start an investigator for the negative quantity bug and a worker for the flaky test, each in the background." } }),
    push("assistant", msg("msg_01BgsPlan", bgsText("I'll start both in the background, each in its own task folder."), "")),
    push("assistant", msg("msg_01BgsPlan", bgsTool(BGS_CALL, "Bash", { command: cmd, description: "Start the two background sessions" }), "tool_use")),
    push("user", { message: { role: "user", content: [{ tool_use_id: BGS_CALL, type: "tool_result", content: out, is_error: false }] }, toolUseResult: { stdout: out, stderr: "", interrupted: false } }),
    push("assistant", msg("msg_01BgsDone", bgsText(`Both run in the background: ${BGS_A.name} and ${BGS_B.name}. I'll check on them when you ask.`), "end_turn")),
  ];
  writeFileSync(chatFile, lines.map((l) => `${l}\n`).join(""), { flag: "a" });
  return world;
}

/** Remove the records and end the stand-ins (by their own pids only). */
function bgsEnd(world: BgsWorld | null) {
  if (!world) return;
  for (const w of [world.a, world.b]) {
    rmSync(w.record, { force: true });
    w.stop();
  }
}

interface BgsLine {
  shown: number;
  state?: string | null;
  role?: string | null;
  name?: string | null;
  title?: string | null;
  word?: string | null;
  why?: string | null;
  said?: string;
  dot?: string;
  anim?: string;
  button?: string | null;
  href?: string | null;
  btnH?: number | null;
  place?: string;
  inHidden?: boolean;
  nameColor?: string;
  wordColor?: string;
  ink?: string;
  dim?: string;
  attn?: string;
  right?: number;
  btnRight?: number | null;
}

/** In-page: every background session's line, and the one of session `id`: its words, dot, colours, button and place. */
const bgsLine = (id: string) => `(() => {
  const vis = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && el.getBoundingClientRect().height > 0;
  const shown = [...document.querySelectorAll('[data-testid^="bg-line-"]')].filter(vis);
  const l = shown.find((e) => e.getAttribute("data-testid") === ${JSON.stringify(`bg-line-${id}`)});
  if (!l) return { shown: shown.length };
  const tone = (name) => { const p = document.createElement("span"); p.style.color = "var(" + name + ")"; l.appendChild(p); const c = getComputedStyle(p).color; p.remove(); return c; };
  const t = (sel) => { const el = l.querySelector(sel); return el ? el.textContent.replace(/\\s+/g, " ").trim() : null; };
  const dot = l.querySelector(".dot");
  const btn = l.querySelector("a.btn");
  const parent = l.parentElement;
  const place = !parent ? "none" : parent.classList.contains("chat-tool") ? "row" : parent.classList.contains("chat-item-summary") ? "summary" : parent.classList.contains("chat-task") ? "agent" : parent.classList.contains("chat-item-turn") ? "turn" : parent.className;
  const r = l.getBoundingClientRect();
  return {
    shown: shown.length, state: l.getAttribute("data-state"), role: l.getAttribute("role"),
    name: t(".chat-bgline-name"), title: l.querySelector(".chat-bgline-name")?.getAttribute("title") ?? null, word: t(".chat-bgline-state"), why: t(".chat-bgline-why"),
    said: l.querySelector(".chat-bgline-words").textContent.replace(/\\s+/g, " ").trim(),
    dot: dot ? [...dot.classList].filter((c) => c !== "dot").join(" ") : "(none)", anim: dot ? getComputedStyle(dot).animationName : "none",
    button: btn ? btn.textContent.trim() : null, href: btn ? btn.getAttribute("href") : null, btnH: btn ? Math.round(btn.getBoundingClientRect().height) : null,
    place, inHidden: !!l.closest('[hidden]'),
    nameColor: getComputedStyle(l.querySelector(".chat-bgline-name")).color, wordColor: getComputedStyle(l.querySelector(".chat-bgline-state")).color,
    ink: tone("--text"), dim: tone("--dim"), attn: tone("--attn"), right: Math.round(r.right), btnRight: btn ? Math.round(btn.getBoundingClientRect().right) : null,
  };
})()`;

interface BgsBar {
  href: string | null;
  label: string | null;
  dot: string;
  anim: string;
  h: number;
}

/** In-page: the chat bar's mark of its background sessions (the list's dot as a link to the session), or null. */
const BGS_BAR = `(() => {
  const vis = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden";
  const bar = [...document.querySelectorAll('[data-testid="topbar"]')].find(vis);
  const m = bar && [...bar.querySelectorAll('[data-testid="bar-bg"]')].find(vis);
  if (!m) return null;
  const dot = m.querySelector(".dot");
  return { href: m.getAttribute("href"), label: m.getAttribute("aria-label"), dot: dot ? [...dot.classList].filter((c) => c !== "dot").join(" ") : "(none)", anim: dot ? getComputedStyle(dot).animationName : "none", h: Math.round(m.getBoundingClientRect().height) };
})()`;

interface BgsView {
  name: string | null;
  meta: string | null;
  folderTitle: string | null;
  mode: string | null;
  modeColor: string | null;
  warn: string;
  texts: string;
  spinners: number;
  state: string | null;
  dot: string;
  anim: string;
  stop: boolean;
  terminal: string | null;
  terminalPrimary: boolean;
  stopH: number | null;
  terminalH: number | null;
  composer: boolean;
  back: string | null;
  heading: string | null;
  right: number;
}

/** In-page: the read-only view: its head, rows, dock, bar and whether a composer shows. */
const BGS_VIEW = `(() => {
  const vis = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden";
  const v = [...document.querySelectorAll('[data-testid="background-view"]')].find(vis);
  if (!v) return null;
  const t = (el) => (el ? el.textContent.replace(/\\s+/g, " ").trim() : null);
  const p = document.createElement("span"); p.style.color = "var(--warn)"; v.appendChild(p); const warn = getComputedStyle(p).color; p.remove();
  const mode = v.querySelector(".bg-mode");
  const dot = v.querySelector('[data-testid="bg-state"] .dot');
  const stop = v.querySelector('[data-testid="bg-stop"]');
  const term = v.querySelector('[data-testid="bg-terminal"]');
  const bar = document.querySelector('[data-testid="topbar"]');
  return {
    name: t(v.querySelector("h1")), meta: t(v.querySelector(".bg-meta")), folderTitle: v.querySelector(".bg-folder")?.getAttribute("title") ?? null,
    mode: t(mode), modeColor: mode ? getComputedStyle(mode).color : null, warn,
    texts: t(v.querySelector(".scr-preview-items")) ?? "", spinners: v.querySelectorAll(".scr-preview-items .chat-spin").length,
    state: t(v.querySelector('[data-testid="bg-state"]')), dot: dot ? [...dot.classList].filter((c) => c !== "dot").join(" ") : "(none)", anim: dot ? getComputedStyle(dot).animationName : "none",
    stop: vis(stop), terminal: term ? term.getAttribute("href") : null, terminalPrimary: !!term && term.classList.contains("primary"),
    stopH: stop ? Math.round(stop.getBoundingClientRect().height) : null, terminalH: term ? Math.round(term.getBoundingClientRect().height) : null,
    composer: [...document.querySelectorAll('[data-testid="composer"]')].some(vis),
    back: t(bar?.querySelector(".scr-bar-back")), heading: t(bar?.querySelector(".scr-bar-heading")),
    right: Math.round(Math.max(...[...v.querySelectorAll("*")].map((e) => e.getBoundingClientRect().right))),
  };
})()`;

/** In-page: the chat's row in the list that shows (the sidebar, the phone's /chats): its dot and its words before the title. */
const BGS_ROW = `(() => {
  const vis = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden";
  // The list's row, or Home's Recent row on a tablet (v0.6 touch: Home at 626), whichever shows the chat's dot.
  const rows = [...document.querySelectorAll('a[href^="/c/${BGS_CHAT}"]')].filter(vis);
  const row = rows.find((r) => r.matches("a.scr-row")) || rows.find((r) => r.querySelector(".dot") && !r.closest('[data-testid="topbar"]'));
  if (!row) return null;
  const dot = row.querySelector(".dot");
  const said = [...row.querySelectorAll(".visually-hidden")].map((e) => e.textContent).join("");
  return { dot: dot ? [...dot.classList].filter((c) => c !== "dot").join(" ") : "(none)", said };
})()`;

interface BgsConfirm {
  kind: "sheet" | "dialog";
  title: string | null;
  text: string;
  focus: string | null;
  stop: boolean;
  stopOff: boolean;
  close: string | null;
  name: string | null;
  right: number;
  cancelH: number | null;
  stopH: number | null;
}

const BGS_CONFIRM = `(() => {
  const vis = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden";
  const box = [...document.querySelectorAll('[data-testid="dialog-bg-stop"]')].find(vis);
  if (!box) return null;
  const t = (el) => (el ? el.textContent.replace(/\\s+/g, " ").trim() : null);
  const stop = box.querySelector('[data-testid="confirm-stop-background"]');
  const cancel = box.querySelector('[data-testid="bg-stop-cancel"], [data-testid="sheet-cancel"]');
  const a = document.activeElement;
  return {
    kind: box.classList.contains("sheet") ? "sheet" : box.classList.contains("dialog") ? "dialog" : box.className,
    title: t(box.querySelector("h2")), text: t(box) ?? "", focus: a ? a.getAttribute("data-testid") : null,
    stop: vis(stop), stopOff: !!stop && stop.getAttribute("aria-disabled") === "true", close: t(cancel), name: t(box.querySelector(".bg-stop-name")),
    right: Math.round(box.getBoundingClientRect().right),
    cancelH: cancel ? cancel.offsetHeight : null, stopH: stop ? stop.offsetHeight : null,
  };
})()`;

const bgsShot = (vp: Viewport, theme: Theme, step: string) => shotName("main", "background-session", vp, theme, step);
const bgsDone = (r: Omit<CheckResult, "status" | "kind" | "name" | "route" | "scene">) => finish({ kind: "flow", name: "background-session", route: "background", scene: "main", ...r });

/** A line as each check reads it: its state, words, dot, colours, its button (44 px on touch) and where it sits. */
function bgsLineFindings(l: BgsLine, vp: Viewport, want: { id: string; name: string; state: string; word: string; why?: string | null; dot: string; place?: string; view?: string }, at: string, fail: (t: string) => void) {
  if (l.state === undefined) return fail(`${at}: the line of ${want.name} does not show (${l.shown} lines show)`);
  if (l.state !== want.state) fail(`${at}: the line's state is ${l.state}, not ${want.state}`);
  if (l.role !== "status") fail(`${at}: the line's role is ${l.role}, not status`);
  if (l.name !== want.name || l.title !== want.name) fail(`${at}: the line names ${JSON.stringify(l.name)} (title ${JSON.stringify(l.title)}), not ${want.name}`);
  if (l.word !== want.word) fail(`${at}: the line's state word is ${JSON.stringify(l.word)}, not ${want.word}`);
  if ((want.why ?? null) !== (l.why ? l.why.replace(/^: /, "") : null)) fail(`${at}: the line's reason is ${JSON.stringify(l.why)}, not ${JSON.stringify(want.why ?? null)}`);
  const said = `Background session ${want.name}, ${want.word}${want.why ? `: ${want.why}` : ""}`;
  if (l.said !== said) fail(`${at}: a screen reader hears ${JSON.stringify(l.said)}, not ${JSON.stringify(said)}`);
  if (l.dot !== want.dot) fail(`${at}: the line's dot is "${l.dot}", not "${want.dot}"`);
  if (l.nameColor !== l.ink) fail(`${at}: the name is ${l.nameColor}, not --text (${l.ink})`);
  const tone = want.state === "needs_input" ? l.attn : want.state === "failed" ? null : l.dim;
  if (tone && l.wordColor !== tone) fail(`${at}: the state word is ${l.wordColor}, not ${want.state === "needs_input" ? "--attn" : "--dim"} (${tone})`);
  if (l.button !== "Open") fail(`${at}: the line's button says ${JSON.stringify(l.button)}, not Open`);
  const href = `/c/${BGS_CHAT}/background/${want.id}${want.view ? `?view=${want.view}` : ""}`;
  if (l.href !== href) fail(`${at}: Open links to ${l.href}, not ${href}`);
  if (vp.touch && (l.btnH ?? 0) < 44) fail(`${at}: the line's button is ${l.btnH} px high on touch, under 44`);
  if (want.place && l.place !== want.place) fail(`${at}: the line sits in the ${l.place}, not under the ${want.place}`);
  if (l.inHidden) fail(`${at}: the line is inside hidden work`);
  if ((l.right ?? 0) > vp.width) fail(`${at}: the line runs past the right edge (${l.right} px of ${vp.width})`);
}

/** Wait for an in-page value, polling every 100 ms. */
async function bgsUntil<T>(page: Page, expr: string, ok: (v: T) => boolean, ms: number): Promise<T> {
  const end = Date.now() + ms;
  let v = await page.evaluate<T>(expr);
  while (!ok(v) && Date.now() < end) {
    await sleep(100);
    v = await page.evaluate<T>(expr);
  }
  return v;
}

/** The view as each check reads it: its bar, head, no composer, the dock's state and its two actions (44 px on touch). */
function bgsViewFindings(v: BgsView | null, vp: Viewport, want: { state: string; dot: string; stop: boolean }, at: string, fail: (t: string) => void) {
  if (!v) return fail(`${at}: the view does not show`);
  if (v.back !== "Chat") fail(`${at}: the view's bar says ${JSON.stringify(v.back)}, not Back "Chat"`);
  // The touch bar is the phone's and the tablet's; the large tablet has the laptop's bar (the laptop's layout).
  const touchBar = vp.touch && vp.name !== "laptop";
  if (touchBar && v.heading !== "Background session") fail(`${at}: the touch bar's heading is ${JSON.stringify(v.heading)}, not "Background session"`);
  if (!touchBar && v.heading) fail(`${at}: the laptop's bar has the heading ${JSON.stringify(v.heading)}`);
  if (v.name !== BGS_A.name) fail(`${at}: the view's head names ${JSON.stringify(v.name)}`);
  // The session started some minutes before the run (its record's startedAt): "started N min ago". No comma next to
  // the Bypass pill: a space on each side.
  const meta = `${BGS_A.folder} Bypass permissions started `;
  if (!v.meta?.startsWith(meta) || !/ [0-9]+ min ago$/.test(v.meta)) fail(`${at}: the head's line reads ${JSON.stringify(v.meta)}, not ${JSON.stringify(`${meta}N min ago`)}`);
  if (!v.folderTitle?.endsWith(`/${BGS_A.folder}`)) fail(`${at}: the folder's title is ${JSON.stringify(v.folderTitle)}, not its full path`);
  if (v.mode !== "Bypass permissions" || v.modeColor !== v.warn) fail(`${at}: the mode is ${JSON.stringify(v.mode)} in ${v.modeColor}, not the Bypass pill in --warn (${v.warn})`);
  if (v.composer) fail(`${at}: the view shows a composer`);
  if (!v.texts.includes("I'll read the brief first, then the cart check.")) fail(`${at}: the view does not show the session's rows`);
  if (v.state !== want.state) fail(`${at}: the dock says ${JSON.stringify(v.state)}, not ${JSON.stringify(want.state)}`);
  if (v.dot !== want.dot) fail(`${at}: the dock's dot is "${v.dot}", not "${want.dot}"`);
  if (v.stop !== want.stop) fail(`${at}: Stop ${v.stop ? "shows" : "does not show"} in the dock`);
  if (v.terminal !== `/c/${BGS_CHAT}/shell?type=attach&bg=${BGS_A.id}`) fail(`${at}: Open in terminal links to ${v.terminal}`);
  // The primary while the session runs (it may wait for the user there); a plain button once it ended.
  if (v.terminalPrimary !== want.stop) fail(`${at}: Open in terminal is ${v.terminalPrimary ? "the primary button" : "a plain button"} while the session ${want.stop ? "runs" : "does not run"}`);
  if (vp.touch && ((v.terminalH ?? 44) < 44 || (want.stop && (v.stopH ?? 0) < 44))) fail(`${at}: a dock button is under 44 px on touch (Stop ${v.stopH}, Open in terminal ${v.terminalH})`);
  if (v.right > vp.width + 1) fail(`${at}: the view runs past the right edge (${v.right} px of ${vp.width})`);
}

/**
 * One fresh seed's run: the lines in each place, Open and the view, a line added to the session's transcript, the
 * second session's completion while the chat is away and its dot, Needs input with the pulse and Reduce motion, Open in
 * terminal, and Stop's confirm with its one request.
 */
async function backgroundSessionRun(b: Booted, vp: Viewport, theme: Theme, full: boolean): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const chatPath = `/c/${BGS_CHAT}`;
  const viewPath = `${chatPath}/background/${BGS_A.id}`;
  const at = `${vp.width}x${vp.height} ${theme}`;
  let shot: string | undefined;
  let world: BgsWorld | null = null;
  try {
    world = await bgsWrite(b);
    const w = world;
    await withPage(vp, theme, async (page, wire) => {
      // ---- the lines: Working under the folded turn's line, then (laptop) under the summary row and the row itself
      await page.navigate(b.base + chatPath);
      await waitShown(page, ["chat", "conversation"], 8000);
      const working = { id: BGS_A.id, name: BGS_A.name, state: "working", word: "Working", dot: "running" };
      const folded = await bgsUntil<BgsLine>(page, bgsLine(BGS_A.id), (l) => l.state === "working", 20_000);
      details.folded = folded;
      bgsLineFindings(folded, vp, { ...working, place: "turn" }, `${at}, the folded turn`, fail);
      if (folded.shown !== 2) fail(`${at}: ${folded.shown} lines show under the folded turn, not 2 (one per session the row started)`);
      const second = await page.evaluate<BgsLine>(bgsLine(BGS_B.id));
      bgsLineFindings(second, vp, { id: BGS_B.id, name: BGS_B.name, state: "working", word: "Working", dot: "running", place: "turn" }, `${at}, the second session's line`, fail);
      // The phone: every line's Open sits at the right edge, so a list of lines keeps its buttons in one column.
      if (vp.name === "phone" && (folded.btnRight == null || folded.btnRight !== second.btnRight)) fail(`${at}: the two lines' Open buttons end at ${folded.btnRight} and ${second.btnRight} px, not in one column`);
      shot = bgsShot(vp, theme, "line-turn");
      await tfShot(page, shot);
      if (full) {
        const turnId = await page.evaluate<string | null>(`(() => { const l = [...document.querySelectorAll('[data-testid^="bg-line-"]')].find((e) => e.getClientRects().length); const t = l && l.closest("[data-turn-id]"); return t ? t.getAttribute("data-turn-id") : null; })()`);
        if (!turnId || !(await tfPress(page, turnId))) fail(`${at}: the folded turn's line that holds the lines cannot be pressed`);
        const summary = await bgsUntil<BgsLine>(page, bgsLine(BGS_A.id), (l) => l.place === "summary", 3000);
        details.summary = summary;
        bgsLineFindings(summary, vp, { ...working, place: "summary" }, `${at}, the summary row`, fail);
        await tfShot(page, bgsShot(vp, theme, "line-summary"));
        await page.navigate(`${b.base}${chatPath}?view=verbose`);
        await waitShown(page, ["chat", "conversation"]);
        const own = await bgsUntil<BgsLine>(page, bgsLine(BGS_A.id), (l) => l.place === "row", 8000);
        details.verbose = own;
        bgsLineFindings(own, vp, { ...working, place: "row", view: "verbose" }, `${at}, Verbose`, fail);
        await page.evaluate(`(() => { const l = document.querySelector('[data-testid="bg-line-${BGS_A.id}"]'); if (l) l.scrollIntoView({ block: "center" }); return true; })()`);
        await tfShot(page, bgsShot(vp, theme, "line-row"));
        await page.navigate(b.base + chatPath);
        await waitShown(page, ["chat", "conversation"]);
        await bgsUntil<BgsLine>(page, bgsLine(BGS_A.id), (l) => l.state !== undefined, 8000);
      }
      quietFindings(wire, 0, await recorder(page), failures, `${at}, the lines: `);

      // Where a line sits from here on: the laptop opened the turn above (its summary row holds the launch row).
      const later = full ? "summary" : "turn";

      // ---- Open: the read-only view, which sends nothing
      const openMark = wire.mark();
      if (!(await trfPress(page, `[data-testid="bg-open-${BGS_A.id}"]`))) fail(`${at}: the line's Open cannot be pressed`);
      await waitShown(page, ["background-view"], 8000);
      const view = await bgsUntil<BgsView | null>(page, BGS_VIEW, (v) => !!v && v.state === "Working" && v.texts.length > 0 && !!v.mode, 10_000);
      details.view = view;
      bgsViewFindings(view, vp, { state: "Working", dot: "running", stop: true }, `${at}, the view`, fail);
      const v1 = await page.probe();
      if (!sameUrl(v1.path, viewPath)) fail(`${at}: Open went to ${v1.path}, not ${viewPath}`, "url");
      if (v1.notices.length) fail(`${at}: a 5.4 line shows over the view: ${clipList(v1.notices)}`, "notice");
      stateFindings(v1, vp, failures, `${at}, the view: `);
      await tfShot(page, bgsShot(vp, theme, "view-working"));

      // ---- lines added to the session's transcript show in the open view (its 2 s re-read)
      w.a.t.assistant("msg_01BgaLater", [bgsText(BGS_LATER)]);
      bgsFlush(w.a);
      const grown = await bgsUntil<BgsView | null>(page, BGS_VIEW, (v) => !!v?.texts.includes(BGS_LATER), 10_000);
      if (!grown?.texts.includes(BGS_LATER)) fail(`${at}: the line added to the session's transcript does not show in the open view within 10 s`);
      quietFindings(wire, openMark, await recorder(page), failures, `${at}, Open and the view: `);

      // ---- the second session completes while no page has the chat on screen: the chat's dot lights, and the chat on
      // screen clears it (R116's seen rule). The list's answer first, then (past the server's 5 s cache) the record.
      await page.navigate(b.base + (vp.name === "phone" ? "/chats" : "/"));
      await waitShown(page, [vp.name === "phone" ? "chat-list" : "home"], 8000);
      bgsAgents(w, "working", "done");
      await sleep(6000);
      await bgsRecord(w.b, "idle");
      const lit = await bgsUntil<{ dot: string; said: string } | null>(page, BGS_ROW, (r) => r?.dot === "unread", 30_000);
      details.doneDot = lit;
      if (lit?.dot !== "unread") fail(`${at}: the chat's dot is "${lit?.dot}" after its session completed unseen, not unread`);
      if (!lit?.said.startsWith("A background session completed, ")) fail(`${at}: before the title a screen reader hears ${JSON.stringify(lit?.said)}, not "A background session completed, "`);
      await tfShot(page, bgsShot(vp, theme, "dot-done"));
      await page.navigate(b.base + chatPath);
      await waitShown(page, ["chat", "conversation"], 8000);
      const done = await bgsUntil<BgsLine>(page, bgsLine(BGS_B.id), (l) => l.state === "completed" && l.dot === "", 15_000);
      details.completed = done;
      bgsLineFindings(done, vp, { id: BGS_B.id, name: BGS_B.name, state: "completed", word: "Completed", dot: "", place: later }, `${at}, the completed session seen`, fail);
      if (vp.name !== "phone") {
        const row = await bgsUntil<{ dot: string } | null>(page, BGS_ROW, (r) => r?.dot !== "unread", 8000);
        if (row?.dot === "unread") fail(`${at}: the chat's dot stays unread with the completed session's line on screen`);
      }
      // Seen, so the bar marks nothing (the other session works).
      const unmarked = await bgsUntil<BgsBar | null>(page, BGS_BAR, (m) => !m, 5000);
      if (unmarked) fail(`${at}: the chat's bar still marks ${JSON.stringify(unmarked.label)} once the completed session's line was seen`);

      // ---- the first session waits for a permission prompt: Needs input with the pulse; Reduce motion stops it; the
      // chat's dot waits too (a live fact, no seen rule)
      await bgsRecord(w.a, "waiting", "permission prompt");
      const needs = { id: BGS_A.id, name: BGS_A.name, state: "needs_input", word: "Needs input", why: "a permission prompt", dot: "waiting", place: later };
      const waiting = await bgsUntil<BgsLine>(page, bgsLine(BGS_A.id), (l) => l.state === "needs_input", 15_000);
      details.needs = waiting;
      bgsLineFindings(waiting, vp, needs, `${at}, Needs input`, fail);
      // The chat's own bar marks it (the list's warm dot), a link to that session's view, 44 px on touch.
      const mark = await bgsUntil<BgsBar | null>(page, BGS_BAR, (m) => m?.dot === "waiting", 8000);
      details.barMark = mark;
      if (!mark) fail(`${at}: the chat's bar has no mark while its session needs input`);
      else {
        if (mark.dot !== "waiting" || mark.anim !== "needs-you") fail(`${at}: the bar's mark is "${mark.dot}" (${mark.anim}), not the waiting dot with its pulse`);
        if (mark.label !== `A background session needs input: ${BGS_A.name}`) fail(`${at}: a screen reader hears the bar's mark as ${JSON.stringify(mark.label)}`);
        if (!mark.href || !sameUrl(mark.href, viewPath)) fail(`${at}: the bar's mark links to ${mark.href}, not ${viewPath}`, "url");
        if (vp.touch && mark.h < 44) fail(`${at}: the bar's mark is ${mark.h} px high on touch, under 44`);
      }
      if (waiting.anim !== "needs-you") fail(`${at}: the waiting dot's animation is ${waiting.anim}, not the needs-you pulse`);
      await tfShot(page, bgsShot(vp, theme, "line-needs"));
      await page.send("Emulation.setEmulatedMedia", { media: "screen", features: [{ name: "prefers-color-scheme", value: theme }, { name: "prefers-reduced-motion", value: "reduce" }] });
      const still = await page.evaluate<BgsLine>(bgsLine(BGS_A.id));
      if (still.anim !== "none") fail(`${at}: under Reduce motion the waiting dot's animation is ${still.anim}, not none`);
      await page.send("Emulation.setEmulatedMedia", { media: "screen", features: [{ name: "prefers-color-scheme", value: theme }] });
      if (vp.name === "phone") {
        await page.navigate(b.base + "/chats");
        await waitShown(page, ["chat-list"], 8000);
      } else if (vp.name === "medium") {
        // v0.6 touch: a tablet's chat list is a drawer; Home lists the chat with its dot.
        await page.navigate(b.base + "/");
        await waitShown(page, ["home"], 8000);
      }
      const row = await bgsUntil<{ dot: string; said: string } | null>(page, BGS_ROW, (r) => r?.dot === "waiting", 8000);
      details.needsDot = row;
      if (row?.dot !== "waiting") fail(`${at}: the chat's dot is "${row?.dot}" while its session needs input, not waiting`);
      if (!row?.said.startsWith("A background session needs input, ")) fail(`${at}: before the title a screen reader hears ${JSON.stringify(row?.said)}, not "A background session needs input, "`);
      if (vp.name === "phone") await tfShot(page, bgsShot(vp, theme, "dot-needs"));
      await page.navigate(b.base + viewPath);
      await waitShown(page, ["background-view"], 8000);
      const vNeeds = await bgsUntil<BgsView | null>(page, BGS_VIEW, (v) => v?.state === "Needs input: a permission prompt" && !!v.mode && v.texts.includes(BGS_LATER), 10_000);
      details.viewNeeds = vNeeds;
      bgsViewFindings(vNeeds, vp, { state: "Needs input: a permission prompt", dot: "waiting", stop: true }, `${at}, the view while it needs input`, fail);
      if (vNeeds && vNeeds.spinners) fail(`${at}: the view shows ${vNeeds.spinners} spinner(s) while the session waits for its prompt`);
      await tfShot(page, bgsShot(vp, theme, "view-needs"));

      // ---- Open in terminal: one type_attach that names the id, never Enter; the pane says how to answer and leave
      const shell = trfShellFrames(page);
      try {
        const termMark = wire.mark();
        if (!(await trfPress(page, '[data-testid="bg-terminal"]'))) fail(`${at}: the dock's Open in terminal cannot be pressed`);
        await waitShown(page, ["terminal-pane"], 8000);
        const note = () => page.evaluate<string | null>(`(() => { const el = [...document.querySelectorAll('[data-testid="terminal-note"]')].find((e) => e.getClientRects().length); return el ? el.textContent.replace(/\\s+/g, " ").trim() : null; })()`);
        const end = Date.now() + 12_000;
        while (Date.now() < end && !(shell.frames.some((x) => x.t === "type_attach") && (await note()))) await sleep(100);
        await sleep(500);
        const typed = shell.frames.filter((x) => x.t === "type_attach");
        details.shell = { frames: shell.frames.filter((x) => x.t !== "resize"), note: await note() };
        if (typed.length !== 1 || typed[0]!.id !== BGS_A.id || Object.keys(typed[0]!).sort().join(",") !== "id,t") fail(`${at}: the pane sent ${JSON.stringify(typed)}, not one type_attach with the id`);
        if (shell.frames.some((x) => x.t === "type_resume" || x.t === "type_trust")) fail(`${at}: the pane asked for another command too`);
        const line = await note();
        if (line !== BGS_PANE_LINE) fail(`${at}: the pane's line is ${JSON.stringify(line)}, not ${JSON.stringify(BGS_PANE_LINE)}`);
        await tfShot(page, bgsShot(vp, theme, "terminal"));
        quietFindings(wire, termMark, await recorder(page), failures, `${at}, Open in terminal: `);
      } finally {
        shell.off();
      }

      // ---- Stop: its confirm only opens (Cancel focused first; on the laptop Enter on Cancel stops nothing), then one
      // background_stop for a double click (two taps), the ack stopped, one `stop <id>` in the fake's trace, Stopped
      await page.navigate(b.base + viewPath);
      await waitShown(page, ["background-view"], 8000);
      await bgsUntil<BgsView | null>(page, BGS_VIEW, (v) => !!v?.stop, 8000);
      const stopMark = wire.mark();
      if (!(await trfPress(page, '[data-testid="bg-stop"]'))) fail(`${at}: the dock's Stop cannot be pressed`);
      const sheet = vp.name === "phone";
      const confirm = await bgsUntil<BgsConfirm | null>(page, BGS_CONFIRM, (c) => !!c && !!c.focus, 4000);
      details.confirm = confirm;
      if (!confirm) fail(`${at}: the Stop confirm does not show`);
      else {
        if (confirm.kind !== (sheet ? "sheet" : "dialog")) fail(`${at}: the confirm is a ${confirm.kind}, not a ${sheet ? "sheet" : "dialog"}`);
        if (confirm.title !== "Stop this session?") fail(`${at}: the confirm's title is ${JSON.stringify(confirm.title)}`);
        if (confirm.focus !== (sheet ? "sheet-cancel" : "bg-stop-cancel")) fail(`${at}: the first focus is on ${confirm.focus}, not Cancel`);
        if (confirm.name !== BGS_A.name) fail(`${at}: the confirm names ${JSON.stringify(confirm.name)}`);
        if (!confirm.text.includes(BGS_KEPT(BGS_A.id))) fail(`${at}: the confirm lacks Claude Code's words ${JSON.stringify(BGS_KEPT(BGS_A.id))}`);
        if (!confirm.stop || confirm.close !== "Cancel") fail(`${at}: the confirm offers Stop ${confirm.stop} with ${JSON.stringify(confirm.close)}, not Stop with Cancel`);
        if (confirm.right > vp.width) fail(`${at}: the confirm runs past the right edge`);
        if (vp.touch && ((confirm.cancelH ?? 44) < 44 || (confirm.stopH ?? 44) < 44)) fail(`${at}: a confirm button is under 44 px on touch (Cancel ${confirm.cancelH}, Stop ${confirm.stopH})`);
      }
      const opened = await page.probe();
      if (!sameUrl(opened.path, `${viewPath}/stop`)) fail(`${at}: Stop opened ${opened.path}, not the stop route`, "url");
      await page.evaluate(TRF_STILL);
      await tfShot(page, bgsShot(vp, theme, "confirm"));
      if (!vp.touch) {
        await page.key("Enter");
        if (await bgsUntil<BgsConfirm | null>(page, BGS_CONFIRM, (c) => !c, 3000)) fail(`${at}: Enter on the focused Cancel did not close the confirm`);
        if (!(await trfPress(page, '[data-testid="bg-stop"]'))) fail(`${at}: the dock's Stop cannot be pressed again`);
        await bgsUntil<BgsConfirm | null>(page, BGS_CONFIRM, (c) => !!c?.stop, 4000);
      }
      quietFindings(wire, stopMark, await recorder(page), failures, `${at}, the Stop confirm: `);
      const pressMark = wire.mark();
      const traceBefore = b.trace().length;
      if (!(await trfPress(page, '[data-testid="confirm-stop-background"]', true))) fail(`${at}: the confirm's Stop cannot be pressed`);
      const end = Date.now() + 25_000;
      while (Date.now() < end && !wire.acks.some((a) => wire.framesSince(pressMark).some((f) => f.t === "background_stop" && f.rid === a.rid))) await sleep(100);
      // Claude Code's stop ends the session's process, and its record goes with it.
      rmSync(w.a.record, { force: true });
      w.a.stop();
      await sleep(300);
      const sent = acting(wire.framesSince(pressMark));
      details.pressed = { sent: sent.map((f) => f.frame), acks: wire.acks.filter((a) => sent.some((f) => f.rid === a.rid)) };
      if (sent.length !== 1 || sent[0]!.t !== "background_stop") fail(`${at}: Stop sent ${clipList(sent.map(frameText)) || "nothing"}, not one background_stop`, "frames");
      const f = sent[0]?.frame ?? {};
      if (f.chat !== BGS_CHAT || f.id !== BGS_A.id || Object.keys(f).sort().join(",") !== "chat,id,rid,t") fail(`${at}: the background_stop frame is ${JSON.stringify(f)}`, "frames");
      const ack = wire.acks.find((a) => a.rid === sent[0]?.rid);
      if (!ack?.ok || (ack.result as { background?: string } | null)?.background !== "stopped") fail(`${at}: the ack is ${ack ? (ack.ok ? JSON.stringify(ack.result) : ack.code) : "missing"}, not {background: "stopped"}`, "ack");
      const rec = (await recorder(page)) ?? [];
      if (rec.filter((t) => t === "background_stop").length !== 1) fail(`${at}: window.__kitespanFrames holds ${clipList(rec) || "nothing"}, not one background_stop`, "recorder");
      const stops = b.trace().slice(traceBefore).filter((l) => l.t === "stop");
      details.stops = stops.map((l) => l.args);
      if (stops.length !== 1 || JSON.stringify(stops[0]!.args) !== JSON.stringify(["stop", BGS_A.id])) fail(`${at}: the fake claude saw ${JSON.stringify(stops.map((l) => l.args))}, not one stop ${BGS_A.id}`);
      if (await bgsUntil<BgsConfirm | null>(page, BGS_CONFIRM, (c) => !c, 5000)) fail(`${at}: the confirm stays open after the answer stopped`);
      const stopped = await bgsUntil<BgsView | null>(page, BGS_VIEW, (v) => v?.state === "Stopped", 15_000);
      details.stopped = stopped;
      if (stopped?.state !== "Stopped") fail(`${at}: the dock says ${JSON.stringify(stopped?.state)} after the stop, not Stopped`);
      else {
        if (stopped.stop) fail(`${at}: Stop still shows for a stopped session`);
        if (stopped.dot !== "(none)") fail(`${at}: the dock shows a dot ("${stopped.dot}") for a stopped session`);
        if (stopped.terminalPrimary) fail(`${at}: Open in terminal is still the primary button for a stopped session`);
      }
      await tfShot(page, bgsShot(vp, theme, "view-stopped"));
      // A link to the stop route of a session that does not run: its name and the not-running line, no Stop, and no
      // word of what a Stop keeps.
      await page.navigate(`${b.base}${viewPath}/stop`);
      await waitShown(page, ["background-view", "dialog-bg-stop"], 8000);
      const idle = await bgsUntil<BgsConfirm | null>(page, BGS_CONFIRM, (c) => !!c && c.text.includes("This session is not running"), 4000);
      details.confirmNotRunning = idle;
      if (!idle) fail(`${at}: the Stop confirm of the stopped session does not say it is not running`);
      else {
        if (idle.stop) fail(`${at}: the confirm of a stopped session offers Stop`);
        if (idle.text.includes("Its conversation is kept")) fail(`${at}: the confirm of a stopped session says what a Stop keeps: ${JSON.stringify(idle.text)}`);
        if (idle.name !== BGS_A.name) fail(`${at}: the not-running confirm names ${JSON.stringify(idle.name)}`);
      }
      await page.evaluate(TRF_STILL);
      await tfShot(page, bgsShot(vp, theme, "confirm-not-running"));
      await page.navigate(b.base + chatPath);
      await waitShown(page, ["chat", "conversation"], 8000);
      const line = await bgsUntil<BgsLine>(page, bgsLine(BGS_A.id), (l) => l.state === "stopped", 10_000);
      bgsLineFindings(line, vp, { id: BGS_A.id, name: BGS_A.name, state: "stopped", word: "Stopped", dot: "", place: later }, `${at}, after the stop`, fail);
      await tfShot(page, bgsShot(vp, theme, "line-stopped"));
      issueFindings(page.takeIssues(), failures);
      const posts = wire.httpSince(0).filter((h) => MUTATING_METHODS.has(h.method));
      if (posts.length) fail(`${at}: the page sent ${clipList(posts.map(httpText))}`, "frames");
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  } finally {
    bgsEnd(world);
  }
  return bgsDone({ size: sizeTag(vp), theme, path: viewPath, failures, warnings, note: full ? "the lines in the folded turn, the summary row and Verbose, the view and a line added to it, a completed session's dot, Needs input and Reduce motion, Open in terminal, Stop's one request" : "the lines in the folded turn, the view and a line added to it, a completed session's dot, Needs input and Reduce motion, Open in terminal, Stop's one request", ms: Date.now() - t0, details, shot });
}

/** Read only, on a seed of its own: the line, the view and the confirm in one look and size (the first session waits). */
async function backgroundSessionLookRun(b: Booted, world: BgsWorld, vp: Viewport, theme: Theme, look: P2LookId): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = { look };
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const chatPath = `/c/${BGS_CHAT}`;
  const viewPath = `${chatPath}/background/${BGS_A.id}`;
  const tag = vp.name === "medium" ? "tablet" : look;
  const at = `${vp.width}x${vp.height} ${theme}, ${tag}`;
  let shot: string | undefined;
  try {
    await withPage(vp, theme, async (page, wire) => {
      await page.navigate(b.base + chatPath);
      await waitShown(page, ["chat", "conversation"], 8000);
      if (look !== "glass") await wearLook(page, look, theme);
      const l = await bgsUntil<BgsLine>(page, bgsLine(BGS_A.id), (x) => x.state === "needs_input", 20_000);
      details.line = l;
      bgsLineFindings(l, vp, { id: BGS_A.id, name: BGS_A.name, state: "needs_input", word: "Needs input", why: "a permission prompt", dot: "waiting", place: "turn" }, at, fail);
      await tfShot(page, bgsShot(vp, theme, `line-${tag}`));
      await page.navigate(b.base + viewPath);
      await waitShown(page, ["background-view"], 8000);
      if (look !== "glass") await wearLook(page, look, theme);
      const v = await bgsUntil<BgsView | null>(page, BGS_VIEW, (x) => !!x && x.state === "Needs input: a permission prompt" && !!x.mode && x.texts.length > 0, 10_000);
      details.view = v;
      bgsViewFindings(v, vp, { state: "Needs input: a permission prompt", dot: "waiting", stop: true }, at, fail);
      await tfShot(page, bgsShot(vp, theme, `view-${tag}`));
      await page.navigate(b.base + `${viewPath}/stop`);
      await waitShown(page, ["background-view", "dialog-bg-stop"], 8000);
      if (look !== "glass") await wearLook(page, look, theme);
      const c = await bgsUntil<BgsConfirm | null>(page, BGS_CONFIRM, (x) => !!x?.stop, 4000);
      details.confirm = c;
      if (!c) fail(`${at}: the Stop confirm does not show`);
      else if (c.kind !== "dialog" || c.focus !== "bg-stop-cancel") fail(`${at}: the confirm is a ${c.kind} with the focus on ${c.focus}, not a dialog with Cancel focused`);
      await page.evaluate(TRF_STILL);
      shot = bgsShot(vp, theme, `confirm-${tag}`);
      await tfShot(page, shot);
      await page.key("Escape");
      if (await bgsUntil<BgsConfirm | null>(page, BGS_CONFIRM, (x) => !x, 3000)) fail(`${at}: Escape did not close the confirm`);
      quietFindings(wire, 0, await recorder(page), failures, `${at}: `);
      issueFindings(page.takeIssues(), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return bgsDone({ size: sizeTag(vp), theme, path: viewPath, failures, warnings, note: vp.name === "medium" ? "the tablet's view and dialog" : `the ${look} look's colours`, ms: Date.now() - t0, details, shot });
}

async function backgroundSessionFlows(record: (r: CheckResult) => void, problems: string[]): Promise<void> {
  if (BASE) {
    console.log("ui-check: background-session boots seeds of its own (the main scene), so --base runs none of it");
    return;
  }
  const laptop = CORE.some((v) => v.name === "laptop") ? WIDE_LAPTOP : null;
  const phone = CORE.find((v) => v.name === "phone") ?? null;
  const tablet = CORE.find((v) => v.name === "medium") ?? null;
  const sizes = [laptop, phone, ...extraAt("background-session")].filter((v): v is Viewport => !!v);
  /** One main scene seed for `run`; a seed that does not boot fails the runs it was for. */
  const onSeed = async (runs: { vp: Viewport; theme: Theme }[], run: (b: Booted) => Promise<void>) => {
    if (cdp.closed || !runs.length) return;
    let b: Booted;
    try {
      // The fake's version is the gate's (BG_CLI_VERSION): below it kitespan never runs `agents` or `stop`.
      b = await boot({ scene: "main", port: PORT, dist: built!, keep: KEEP, env: SERVER_ENV, fixture: { version: (await import("../test/click/seed/background")).BG_CLI_VERSION } });
    } catch (e) {
      for (const r of runs) record(bgsDone({ size: sizeTag(r.vp), theme: r.theme, path: `/c/${BGS_CHAT}/background/${BGS_A.id}`, failures: [{ code: "seed", text: `the seed did not boot: ${(e as Error).message}` }], warnings: [], note: "", ms: 0, details: {} }));
      return;
    }
    live.add(b);
    try {
      await run(b);
    } finally {
      const r = await b.stop();
      live.delete(b);
      if (r.code !== 0) problems.push(`scene main (background-session): the server exited with ${r.code}`);
      if (r.leftovers.length) problems.push(`scene main (background-session): ${r.leftovers.length} process(es) outlived the server and were ended by pid`);
    }
  };
  for (const vp of sizes) for (const theme of THEMES) await onSeed([{ vp, theme }], async (b) => record(await backgroundSessionRun(b, vp, theme, vp === laptop)));
  // Read only: each other look at the laptop, and the tablet's view and dialog, with the first session waiting.
  const looks: { vp: Viewport; theme: Theme; look: P2LookId }[] = [];
  if (laptop && THEMES.includes("light")) for (const look of P2_LOOKS.filter((l) => l !== "glass")) looks.push({ vp: laptop, theme: "light", look });
  if (tablet && THEMES.includes("light")) looks.push({ vp: tablet, theme: "light", look: "glass" });
  await onSeed(looks, async (b) => {
    let world: BgsWorld | null = null;
    try {
      world = await bgsWrite(b);
      bgsAgents(world, "blocked", "working");
      await bgsRecord(world.a, "waiting", "permission prompt");
      for (const r of looks) if (!cdp.closed) record(await backgroundSessionLookRun(b, world, r.vp, r.theme, r.look));
    } catch (e) {
      for (const r of looks) record(bgsDone({ size: sizeTag(r.vp), theme: r.theme, path: `/c/${BGS_CHAT}/background/${BGS_A.id}`, failures: [{ code: "run", text: `the looks could not run: ${(e as Error).message}` }], warnings: [], note: "", ms: 0, details: {} }));
    } finally {
      bgsEnd(world);
    }
  });
}

// ---------------------------------------------------------------------------------------------------------------
// R130 (owner rows 128 and 130; DESIGN-R130 section 3): notifications, with no real push service. notify runs on main
// scene seeds of its own, whose server sends its pushes only to a stub push service in this process on 127.0.0.1
// (test/click/push-stub.ts: it verifies the VAPID token and decrypts with node:crypto, so it shares no code with the
// server), the one test origin the server takes (KITESPAN_PUSH_TEST_ORIGIN, with NO_PROXY=127.0.0.1). Chrome's own push
// service is never used: a script put on each page before it loads replaces PushManager's subscribe and
// getSubscription with the stub's subscription (kept in the page's local storage across loads, with the key the page
// passed). Everything else is real: the switch's click, Notification.requestPermission (granted by CDP), the service
// worker's registration, the server's routes and moments, and the worker's push and notificationclick handlers.
//
// The main scene's seed has the server's key and one other device ("iPhone", at a host the server never sends to;
// seed/push.ts). The full run (1280x800 light): Settings > Notifications reads and sends nothing, with the switch off
// and the iPhone listed with Turn off; the switch's click sends one POST /api/push/devices (and one POST
// /api/push/key only when the read had no key), and the row is on with the device list ("Browser", This device,
// first) and /sw.js registered for "/"; after a reload the switch is still on and the navigation did not go through the
// worker (workerStart 0: it has no fetch handler). With the page on the example chat: a turn that ends on Plan the
// search index sends exactly one push, which decrypts to {"v":1,"title":"Claude finished","body":"","tag":"c:<chat>",
// "url":"/c/<chat>"} with TTL 86400, Urgency normal, Topic the chat id, aes128gcm, a VAPID token for the stub's origin
// and k the server's key; a second turn's end sends none (one per chat until seen); a permission card in it sends one,
// "Claude needs your permission", with the card's path and Urgency high. Both payloads, given to the real worker
// (CDP's ServiceWorker.deliverPushMessage), leave one notification, the newer; a click on it (a notificationclick in the
// worker's own target) opens the card's path in the page with no request, and the page, with the chat on screen,
// closes it. A turn that ends on the chat the page shows sends none. Show chat titles on: the next push's title is the
// chat's title and its body the moment's words. A 410 from the stub removes the device (the server's push_gone line
// names the host and 410, and no line holds the endpoint's path), and Settings shows the switch off; on again and off
// sends the device's remove and leaves no registration. The stills: 1280x800 dark (the denied state first: its line,
// and the seed's other device under it with Turn off, no This device and no Show chat titles), 390x844
// touch light (a link's value=on with its Save, which turns it on) and dark (a second device: its rename, then Turn
// off: the seed's iPhone), each with the list, Show chat titles on, and the 44 px targets on touch.

const NT = {
  /** The page shows this chat. */
  shown: EX.chat,
  /** Plan the search index: its turns end unseen, then a permission card waits in it. */
  away: IDS.chats.search,
  /** Refactor the query parser: its turn's push carries its title. */
  titled: IDS.chats.parser,
  /** Try the markdown renderer: its turn's push gets the stub's 410. */
  gone: IDS.chats.markdown,
  first: "Note where the index files live (row 130).",
  again: "One more line on the index size (row 130).",
  seen: "Say done once more while this chat is on screen (row 130).",
  titledTurn: "List the parser's open questions (row 130).",
  goneTurn: "Name the renderer's slowest step (row 130).",
} as const;

/** In-page, before any load: the stub's subscription in PushManager's place (local storage `__ntPush:*`). */
const NT_STAND_IN = `(() => {
  if (typeof PushManager === "undefined") return;
  const K = "__ntPush";
  const read = (k) => { try { return JSON.parse(localStorage.getItem(K + k) || "null"); } catch (e) { return null; } };
  const put = (k, v) => localStorage.setItem(K + k, JSON.stringify(v));
  const bytes = (s) => { const t = s.replace(/-/g, "+").replace(/_/g, "/"); const b = atob(t + "=".repeat((4 - (t.length % 4)) % 4)); const u = new Uint8Array(b.length); for (let i = 0; i < b.length; i++) u[i] = b.charCodeAt(i); return u.buffer; };
  const b64u = (v) => { const u = v instanceof ArrayBuffer ? new Uint8Array(v) : new Uint8Array(v.buffer, v.byteOffset, v.byteLength); let s = ""; for (const x of u) s += String.fromCharCode(x); return btoa(s).replace(/\\+/g, "-").replace(/\\//g, "_").replace(/=+$/, ""); };
  const note = (s) => { const l = read(":log") || []; l.push(s); put(":log", l); };
  const sub = (j) => ({
    endpoint: j.endpoint,
    expirationTime: null,
    options: { userVisibleOnly: true, applicationServerKey: j.key ? bytes(j.key) : null },
    getKey: (n) => (j.keys[n] ? bytes(j.keys[n]) : null),
    toJSON: () => ({ endpoint: j.endpoint, expirationTime: null, keys: { p256dh: j.keys.p256dh, auth: j.keys.auth } }),
    unsubscribe: async () => { const now = read(":sub"); if (now && now.endpoint === j.endpoint) localStorage.removeItem(K + ":sub"); note("unsubscribe"); return true; },
  });
  PushManager.prototype.subscribe = async function (o) {
    const key = o && o.applicationServerKey ? b64u(o.applicationServerKey) : null;
    note("subscribe " + (!!o && o.userVisibleOnly === true) + " " + key);
    const next = read(":next");
    if (!next) throw new DOMException("the check gave no subscription", "AbortError");
    localStorage.removeItem(K + ":next");
    const j = { endpoint: next.endpoint, keys: next.keys, key };
    put(":sub", j);
    return sub(j);
  };
  PushManager.prototype.getSubscription = async function () { const j = read(":sub"); return j ? sub(j) : null; };
})()`;

interface NtState {
  path: string;
  sw: { on: boolean; busy: boolean } | null;
  titles: boolean | null;
  firstLine: string | null;
  firstText: string;
  devices: { id: string; name: string; you: boolean; off: boolean; failing: boolean; marked: boolean; field: string | null }[];
  save: string | null;
  notice: string[];
}

const NT_PROBE = `(() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden";
  const fold = (s) => (s || "").replace(/\\s+/g, " ").trim();
  const one = (sel, root = document) => [...root.querySelectorAll(sel)].find(shown) || null;
  const sw = one('[data-testid="notify-switch"]');
  const t = one('[data-testid="titles-switch"]');
  const first = one('[data-testid="setting-this-device"]');
  const save = first ? one('[data-testid="confirm-save"]', first) : null;
  return {
    path: location.pathname + location.search,
    sw: sw ? { on: sw.checked, busy: sw.getAttribute("aria-busy") === "true" } : null,
    titles: t ? t.checked : null,
    firstLine: first && first.querySelector(".set-help, .set-row-line") ? fold(first.querySelector(".set-help, .set-row-line").textContent) : null,
    firstText: first ? fold(first.textContent) : "",
    devices: [...document.querySelectorAll('[data-testid^="device-"]')].filter((el) => /^device-[a-z2-7]{16}$/.test(el.getAttribute("data-testid")) && shown(el)).map((el) => ({
      id: el.getAttribute("data-testid").slice(7),
      name: fold((el.querySelector('[data-testid="device-name"]') || {}).textContent || ""),
      you: !!el.querySelector(".nt-you"),
      off: !!el.querySelector('[data-testid="device-turn-off"]'),
      failing: !!el.querySelector(".set-row-line"),
      marked: el.hasAttribute("data-focused"),
      field: el.querySelector('[data-testid="device-name-field"]') ? el.querySelector('[data-testid="device-name-field"]').value : null,
    })),
    save: save ? fold(save.textContent) : null,
    notice: [...document.querySelectorAll('[data-testid="link-notice"]')].filter(shown).map((el) => fold(el.textContent)),
  };
})()`;

async function ntUntil(page: Page, ok: (s: NtState) => boolean, ms: number): Promise<{ ok: boolean; s: NtState }> {
  const end = Date.now() + ms;
  let s = await page.evaluate<NtState>(NT_PROBE);
  while (!ok(s) && Date.now() < end) {
    await sleep(100);
    s = await page.evaluate<NtState>(NT_PROBE);
  }
  return { ok: ok(s), s };
}

async function ntPress(page: Page, selector: string): Promise<boolean> {
  const at = await page.locate(selector);
  if (!at) return false;
  await page.press(at.x, at.y);
  await sleep(60);
  return true;
}

/** A setup socket of the check's own (never a page's): the chat list's titles, and a message whose event it waits for. */
async function ntSocket(base: string) {
  const ws = new WebSocket(`${base.replace(/^http/, "ws")}${WIRE.path}`, { headers: { origin: base } });
  const frames: Record<string, any>[] = [];
  ws.onmessage = (m) => {
    if (typeof m.data !== "string") return;
    try {
      frames.push(JSON.parse(m.data) as Record<string, any>);
    } catch {}
  };
  await new Promise<void>((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error("the setup socket did not open")), 5000);
    ws.onopen = () => (clearTimeout(timer), resolve());
    ws.onerror = () => (clearTimeout(timer), reject(new Error("the setup socket did not open")));
  });
  const wait = async (ok: (f: Record<string, any>) => boolean, what: string, ms = 60_000, from = 0) => {
    const end = Date.now() + ms;
    for (;;) {
      const hit = frames.slice(from).find(ok);
      if (hit) return hit;
      if (Date.now() > end) throw new Error(`the setup socket got no ${what} in ${ms / 1000} s`);
      await sleep(50);
    }
  };
  ws.send(JSON.stringify({ t: "hello", v: PROTOCOL_VERSION, tab: "ui-check-notify" }));
  await wait((f) => f.t === "welcome", "welcome");
  const list = await wait((f) => f.t === "chats", "chat list");
  const titles = new Map<string, string>((list.list as { chat: string; title: string | null }[]).map((r) => [r.chat, r.title ?? ""]));
  const attached = new Set<string>();
  return {
    titles,
    /** Send `text` to `chat` and wait for the event `until` picks; resolves with that event. */
    async turn(chat: string, text: string, until: (e: Record<string, any>) => boolean, what: string): Promise<Record<string, any>> {
      if (!attached.has(chat)) {
        ws.send(JSON.stringify({ t: "attach", chat, since: 0, epoch: null }));
        await wait((f) => f.t === "attached" && f.chat === chat, "attached");
        attached.add(chat);
      }
      const from = frames.length;
      const uuid = crypto.randomUUID();
      ws.send(JSON.stringify({ t: "send", rid: uuid, chat, uuid, text, draftRev: null, uploads: [] }));
      const ack = await wait((f) => f.t === "ack" && f.rid === uuid, "ack", 20_000, from);
      if (!ack.ok) throw new Error(`the setup message was refused: ${ack.error?.code}`);
      const ev = await wait((f) => f.t === "ev" && f.chat === chat && until(f.e ?? {}), what, 60_000, from);
      return ev.e as Record<string, any>;
    },
    close() {
      try {
        ws.close();
      } catch {}
    },
  };
}

/** The server's push read (GET, which makes nothing). */
async function ntRead(base: string): Promise<{ key: string | null; devices: { id: string; name: string; titles: boolean; failing: boolean }[] }> {
  const r = await fetch(`${base}/api/push`, { headers: { accept: "application/json" }, signal: AbortSignal.timeout(5000) });
  if (!r.ok) throw new Error(`GET /api/push answered ${r.status}`);
  return (await r.json()) as { key: string | null; devices: { id: string; name: string; titles: boolean; failing: boolean }[] };
}

/** The page's service worker: its registration id (CDP's ServiceWorker domain on the page's session), or null. */
async function ntRegistration(page: Page, base: string): Promise<string | null> {
  const regs: { registrationId: string; scopeURL: string; isDeleted?: boolean }[] = [];
  const off = cdp.on((e) => {
    if (e.sessionId === page.session && e.method === "ServiceWorker.workerRegistrationUpdated") regs.push(...(e.params.registrations ?? []));
  });
  try {
    await page.send("ServiceWorker.enable");
    for (let i = 0; i < 60 && !regs.some((r) => r.scopeURL === `${base}/` && !r.isDeleted); i++) await sleep(50);
  } finally {
    off();
  }
  return regs.filter((r) => r.scopeURL === `${base}/` && !r.isDeleted).at(-1)?.registrationId ?? null;
}

/** This page's shown notifications (the registration's getNotifications). */
const NT_SHOWN = `(async () => { const r = await navigator.serviceWorker.getRegistration("/"); return r ? (await r.getNotifications()).map((n) => ({ title: n.title, body: n.body, tag: n.tag, url: n.data && n.data.url })) : null; })()`;

/** A click on the shown notification with this tag, in the worker's own target (a synthetic notificationclick). */
async function ntClick(page: Page, base: string, tag: string): Promise<string> {
  const targets = ((await cdp.send("Target.getTargets")).targetInfos ?? []) as { targetId: string; type: string; url: string; browserContextId?: string }[];
  const sw = targets.find((t) => t.type === "service_worker" && t.url === `${base}/sw.js` && (!t.browserContextId || t.browserContextId === page.contextId));
  if (!sw) return "no service worker target";
  const { sessionId } = await cdp.send("Target.attachToTarget", { targetId: sw.targetId, flatten: true });
  try {
    const r = await cdp.send(
      "Runtime.evaluate",
      { expression: `(async () => { const n = (await self.registration.getNotifications()).find((x) => x.tag === ${JSON.stringify(tag)}); if (!n) return "no notification"; self.dispatchEvent(new NotificationEvent("notificationclick", { notification: n })); return "clicked"; })()`, awaitPromise: true, returnByValue: true },
      sessionId,
    );
    return r.exceptionDetails ? `failed: ${r.exceptionDetails.exception?.description ?? r.exceptionDetails.text}` : String(r.result?.value);
  } finally {
    await cdp.send("Target.detachFromTarget", { sessionId }).catch(() => {});
  }
}

/** The stand-in's subscription for the page's next subscribe, and its log. */
const ntNext = (page: Page, sub: unknown) => page.evaluate(`(() => { localStorage.setItem("__ntPush:next", ${JSON.stringify(JSON.stringify(sub))}); return true; })()`);
const ntLog = (page: Page) => page.evaluate<string[]>(`(() => { try { return JSON.parse(localStorage.getItem("__ntPush:log") || "[]"); } catch (e) { return ["unreadable"]; } })()`);

const ntShot = (vp: Viewport, theme: Theme, step: string) => shotName("main", "notify", vp, theme, step);

/** The full run at 1280x800 light: section 3's steps on one seed. */
async function notifyRun(b: Booted, stub: PushStub, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const at = `${vp.width}x${vp.height} ${theme}`;
  const settings = `${b.base}/settings/notifications`;
  let shot: string | undefined;
  let sock: Awaited<ReturnType<typeof ntSocket>> | null = null;
  const pushes = (from: number) => stub.received.slice(from);
  const payload = (p: StubPush | undefined): Record<string, unknown> | null => {
    try {
      return p?.plain ? (JSON.parse(p.plain) as Record<string, unknown>) : null;
    } catch {
      return null;
    }
  };
  try {
    sock = await ntSocket(b.base);
    await withPage(vp, theme, async (page, wire) => {
      await page.send("Page.addScriptToEvaluateOnNewDocument", { source: NT_STAND_IN });
      await cdp.send("Browser.grantPermissions", { origin: b.base, permissions: ["notifications"], browserContextId: page.contextId });

      // 1. The section reads and sends nothing; the switch is off; no Devices group.
      let mark = wire.mark();
      await page.navigate(settings);
      const off = await ntUntil(page, (s) => s.sw !== null, 8000);
      details.off = off.s;
      if (!off.ok || off.s.sw?.on) return fail(`${at}: Settings > Notifications shows no switch that is off (${JSON.stringify(off.s.sw)}; ${off.s.firstText})`);
      const seeded = off.s.devices.find((d) => d.id === EX.device);
      if (off.s.devices.length !== 1 || !seeded?.off || seeded.you) fail(`${at}: with this device off the Devices group shows ${JSON.stringify(off.s.devices)}, not the seed's other device with Turn off`);
      const before = await ntRead(b.base);
      quietFindings(wire, mark, await recorder(page), failures, `${at}: opening Settings > Notifications: `);
      await maskMachine(page);
      await page.screenshot(ntShot(vp, theme, "off"));

      // 2. The switch's click: one POST for the key, one for the device; the row is on with the device list.
      const sub1 = stub.subscribe("laptop1");
      await ntNext(page, sub1);
      mark = wire.mark();
      if (!(await ntPress(page, '[data-testid="notify-switch"]'))) return fail(`${at}: the switch could not be found to press`);
      const onState = await ntUntil(page, (s) => s.sw?.on === true && !s.sw.busy && s.devices.length === 2, 10_000);
      details.on = onState.s;
      const posts = wire.httpSince(mark).map(httpText);
      details.posts = posts;
      if (!onState.ok) return fail(`${at}: after the click the switch is not on with one device (${JSON.stringify(onState.s.sw)}, ${onState.s.devices.length} devices; ${onState.s.firstLine ?? "no line"}; ${clipList(posts)})`);
      const keyPosts = wire.httpSince(mark).filter((h) => h.method === "POST" && h.path === "/api/push/key");
      const devicePosts = wire.httpSince(mark).filter((h) => h.method === "POST" && h.path === "/api/push/devices");
      if (keyPosts.length !== (before.key ? 0 : 1) || devicePosts.length !== 1) fail(`${at}: turning on sent ${clipList(posts)}, not one POST /api/push/devices${before.key ? " (the read had the key)" : " and one POST /api/push/key"}`, "frames");
      const me = onState.s.devices[0]!;
      if (me.name !== "Browser" || !me.you || me.off) fail(`${at}: the device list shows ${JSON.stringify(me)}, not "Browser" as This device`);
      const regs = await page.evaluate<string[]>(`(async () => (await navigator.serviceWorker.getRegistrations()).map((r) => r.scope))()`);
      details.registrations = regs;
      if (regs.length !== 1 || regs[0] !== `${b.base}/`) fail(`${at}: the service worker's registrations are ${JSON.stringify(regs)}, not one for ${b.base}/`);
      const server = await ntRead(b.base);
      const log = await ntLog(page);
      details.standIn = log.map((l) => l.replace(/ [A-Za-z0-9_-]{40,}$/, " <key>"));
      if (!server.key || !log.some((l) => l === `subscribe true ${server.key}`)) fail(`${at}: the page did not subscribe with userVisibleOnly and the server's key (${clipList(details.standIn as string[])})`);
      shot = ntShot(vp, theme, "on");
      await maskMachine(page);
      await page.screenshot(shot);
      // The looks restyle the section with no rule of their own.
      for (const look of P2_LOOKS.filter((l) => l !== "glass")) {
        await wearLook(page, look, theme);
        await page.screenshot(ntShot(vp, theme, `on-${look}`));
      }
      await wearLook(page, "glass", theme);

      // 3. A reload: still on, and the navigation did not go through the worker (it has no fetch handler).
      await page.reload();
      const kept = await ntUntil(page, (s) => s.sw?.on === true && s.devices.length === 2, 8000);
      if (!kept.ok) fail(`${at}: after a reload the switch is ${JSON.stringify(kept.s.sw)}`);
      const nav = await page.evaluate<{ workerStart: number; controlled: boolean }>(`(() => ({ workerStart: performance.getEntriesByType("navigation")[0].workerStart, controlled: !!navigator.serviceWorker.controller }))()`);
      details.navigation = nav;
      if (nav.workerStart !== 0) fail(`${at}: after a reload the navigation went through the service worker (workerStart ${nav.workerStart})`);

      // 4. The page on the example chat; a turn ends on Plan the search index: exactly one push.
      await page.navigate(`${b.base}/c/${NT.shown}`);
      await waitShown(page, ["chat", "conversation"], 8000);
      let n0 = stub.received.length;
      await sock!.turn(NT.away, NT.first, (e) => e.k === "turn_end", "end of the turn");
      await stub.waitFor(n0 + 1, 5000);
      await sleep(800);
      const p1 = pushes(n0);
      details.push1 = p1.map((p) => ({ ...p, claims: p.claims ? { aud: p.claims.aud, sub: p.claims.sub } : null }));
      if (p1.length !== 1) fail(`${at}: the turn that ended unseen sent ${p1.length} push(es), not one`);
      const done = payload(p1[0]);
      const want1 = { v: 1, title: "Claude finished", body: "", tag: `c:${NT.away}`, url: `/c/${NT.away}` };
      if (JSON.stringify(done) !== JSON.stringify(want1)) fail(`${at}: the push decrypts to ${JSON.stringify(p1[0]?.plain ?? null)}, not ${JSON.stringify(want1)}`);
      if (p1[0]) {
        const h = p1[0].headers;
        if (h.ttl !== "86400" || h.urgency !== "normal" || h.topic !== NT.away || h["content-encoding"] !== "aes128gcm") fail(`${at}: the push's headers are ${JSON.stringify({ ttl: h.ttl, urgency: h.urgency, topic: h.topic, encoding: h["content-encoding"] })}`);
        if (p1[0].vapid !== "ok") fail(`${at}: the push's VAPID token: ${p1[0].vapid}`);
        if (p1[0].k !== server.key) fail(`${at}: the push's k is not the server's key`);
        if (p1[0].claims?.aud !== stub.origin) fail(`${at}: the token's aud is ${JSON.stringify(p1[0].claims?.aud)}, not the stub's origin`);
        if (p1[0].padded === null || p1[0].padded % 256 !== 0) fail(`${at}: the plaintext is padded to ${p1[0].padded} octets, not a multiple of 256`);
      }

      // 5. A second turn's end while the chat is still unseen: none (one per chat until seen).
      n0 = stub.received.length;
      await sock!.turn(NT.away, NT.again, (e) => e.k === "turn_end", "end of the second turn");
      await sleep(4000);
      if (pushes(n0).length) fail(`${at}: a second turn's end on the unseen chat sent ${pushes(n0).length} more push(es)`);

      // 6. A permission card in it, still not on screen: one push with the card's path, Urgency high.
      n0 = stub.received.length;
      const opened = await sock!.turn(NT.away, WARM.permission, (e) => e.k === "card_open", "permission card");
      const cardPath = `/c/${NT.away}/permission/${opened.card?.id}`;
      await stub.waitFor(n0 + 1, 5000);
      await sleep(500);
      const p2 = pushes(n0);
      const card = payload(p2[0]);
      details.push2 = card;
      if (p2.length !== 1) fail(`${at}: the waiting card sent ${p2.length} push(es), not one`);
      if (card?.title !== "Claude needs your permission" || card?.url !== cardPath || card?.tag !== `c:${NT.away}`) fail(`${at}: the card's push reads ${JSON.stringify(card)}, not "Claude needs your permission" at ${cardPath}`);
      if (p2[0] && p2[0].headers.urgency !== "high") fail(`${at}: the card's push has Urgency ${p2[0].headers.urgency}, not high`);

      // 7. Both payloads to the real worker: one notification, the newer; its click opens the card's path, sends
      // nothing, and the page that shows the chat closes it.
      const reg = await ntRegistration(page, b.base);
      if (!reg) fail(`${at}: the service worker's registration could not be found over CDP`);
      else {
        for (const p of [p1[0], p2[0]]) if (p?.plain) await page.send("ServiceWorker.deliverPushMessage", { origin: b.base, registrationId: reg, data: p.plain });
        await sleep(800);
        const shownNow = await page.evaluate<{ title: string; tag: string; url: string }[] | null>(NT_SHOWN);
        details.shown = shownNow;
        if (!shownNow || shownNow.length !== 1 || shownNow[0]!.title !== "Claude needs your permission" || shownNow[0]!.url !== cardPath) fail(`${at}: after the two pushes the device shows ${JSON.stringify(shownNow)}, not one notification, the card's`);
        mark = wire.mark();
        const clicked = await ntClick(page, b.base, `c:${NT.away}`);
        details.click = clicked;
        const landed = await ntUntil(page, (s) => s.path === cardPath, 6000);
        if (clicked !== "clicked" || !landed.ok) fail(`${at}: the notification's click (${clicked}) left the page at ${landed.s.path}, not ${cardPath}`);
        await sleep(1500);
        const acts = acting(wire.framesSince(mark)).filter((f) => f.t !== "on_screen");
        if (acts.length || wire.httpSince(mark).length) fail(`${at}: the click sent ${clipList([...acts.map(frameText), ...wire.httpSince(mark).map(httpText)])}`, "frames");
        const left = await page.evaluate<unknown[] | null>(NT_SHOWN);
        if (left?.length) fail(`${at}: with the chat on screen the page left its notification (${JSON.stringify(left)})`);
        await maskMachine(page);
        await page.screenshot(ntShot(vp, theme, "clicked"));
      }

      // 8. A turn that ends on the chat the page shows at its end: none.
      mark = wire.mark();
      await page.navigate(`${b.base}/c/${NT.shown}`);
      await waitShown(page, ["chat", "conversation"], 8000);
      for (let i = 0; i < 40 && !wire.framesSince(mark).some((f) => f.t === "on_screen" && f.frame.chat === NT.shown && f.frame.on === true); i++) await sleep(100);
      n0 = stub.received.length;
      await sock!.turn(NT.shown, NT.seen, (e) => e.k === "turn_end", "end of the turn on screen");
      await sleep(4000);
      if (pushes(n0).length) fail(`${at}: a turn that ended on the chat on screen sent ${pushes(n0).length} push(es)`);

      // 9. Show chat titles on: the next push's title is the chat's title, its body the moment's words.
      await page.navigate(settings);
      await ntUntil(page, (s) => s.titles !== null, 8000);
      mark = wire.mark();
      // With Reduce motion on (Settings > Appearance), the switch's change moves nothing.
      await page.evaluate(`(() => { document.documentElement.dataset.motion = "reduce"; return true; })()`);
      await ntPress(page, '[data-testid="titles-switch"]');
      const moving = await page.evaluate<string[]>(`(() => document.getAnimations().filter((a) => a.playState === "running" && a.effect && a.effect.target && a.effect.target.closest && a.effect.target.closest('[data-testid="settings-notifications"]')).map((a) => a.transitionProperty || a.animationName || "?"))()`);
      details.reduceMotion = moving;
      if (moving.length) fail(`${at}: with Reduce motion the titles switch runs ${clipList(moving)}`);
      await page.evaluate(`(() => { delete document.documentElement.dataset.motion; return true; })()`);
      const titled = await ntUntil(page, (s) => s.titles === true, 4000);
      await sleep(500);
      if (!titled.ok || !wire.httpSince(mark).some((h) => h.method === "POST" && h.path === `/api/push/devices/${me.id}`)) fail(`${at}: Show chat titles did not turn on with one POST /api/push/devices/<device> (${clipList(wire.httpSince(mark).map(httpText))})`);
      await maskMachine(page);
      await page.screenshot(ntShot(vp, theme, "titles"));
      await page.navigate(`${b.base}/c/${NT.shown}`);
      await waitShown(page, ["chat", "conversation"], 8000);
      n0 = stub.received.length;
      await sock!.turn(NT.titled, NT.titledTurn, (e) => e.k === "turn_end", "end of the titled turn");
      await stub.waitFor(n0 + 1, 5000);
      const p3 = payload(pushes(n0)[0]);
      details.push3 = p3;
      const title = sock!.titles.get(NT.titled) ?? "";
      if (!p3 || p3.title !== title || p3.body !== "Claude finished") fail(`${at}: with Show chat titles the push reads ${JSON.stringify(p3)}, not the title ${JSON.stringify(title)} with "Claude finished"`);

      // 10. The stub answers 410: the server removes the device and says so in its log (host and status only).
      stub.answer("laptop1", 410);
      n0 = stub.received.length;
      await sock!.turn(NT.gone, NT.goneTurn, (e) => e.k === "turn_end", "end of the gone turn");
      await stub.waitFor(n0 + 1, 5000);
      let after = await ntRead(b.base);
      for (let i = 0; i < 30 && after.devices.some((d) => d.id === me.id); i++) {
        await sleep(100);
        after = await ntRead(b.base);
      }
      if (after.devices.some((d) => d.id === me.id)) fail(`${at}: after a 410 the server still lists this device`);
      // The server's counts-only log (the state folder's logs/kitespan-<day>.log) and its own output.
      const logs = join(b.seed.state, "logs");
      const logText = existsSync(logs) ? readdirSync(logs).filter((f) => /^kitespan-.*\.log$/.test(f)).map((f) => readFileSync(join(logs, f), "utf8")).join("\n") : "";
      const out = `${logText}\n${b.output().out}\n${b.output().err}`;
      details.pushLines = logText.split("\n").filter((l) => /"push(_gone|_device)?"/.test(l)).length;
      const goneLine = logText.split("\n").find((l) => l.includes('"push_gone"'));
      details.goneLine = goneLine ?? null;
      if (!goneLine || !goneLine.includes("410") || !goneLine.includes("127.0.0.1")) fail(`${at}: the server's log has no push_gone line with the host and 410 (${JSON.stringify(goneLine ?? null)})`);
      if (out.includes("/push/laptop1") || (server.key && out.includes(server.key))) fail(`${at}: the server's log holds the endpoint's path or the key`);
      await page.navigate(settings);
      const goneState = await ntUntil(page, (s) => s.sw !== null, 8000);
      if (goneState.s.sw?.on !== false || goneState.s.devices.some((d) => d.you)) fail(`${at}: after the 410 Settings shows the switch ${JSON.stringify(goneState.s.sw)} with ${JSON.stringify(goneState.s.devices)}`);

      // 11. On again, then off: the device's remove, and no registration left.
      await ntNext(page, stub.subscribe("laptop2"));
      await ntPress(page, '[data-testid="notify-switch"]');
      const again = await ntUntil(page, (s) => s.sw?.on === true && !s.sw.busy && s.devices.some((d) => d.you), 10_000);
      if (!again.ok) fail(`${at}: turning on again left the switch ${JSON.stringify(again.s.sw)}`);
      const id2 = again.s.devices.find((d) => d.you)?.id ?? "";
      mark = wire.mark();
      await ntPress(page, '[data-testid="notify-switch"]');
      const offAgain = await ntUntil(page, (s) => s.sw?.on === false && !s.sw.busy, 10_000);
      await sleep(300);
      const removes = wire.httpSince(mark).filter((h) => h.method === "POST" && h.path === `/api/push/devices/${id2}/remove`);
      if (!offAgain.ok || removes.length !== 1) fail(`${at}: turning off sent ${clipList(wire.httpSince(mark).map(httpText))} and left the switch ${JSON.stringify(offAgain.s.sw)}`);
      const leftRegs = await page.evaluate<number>(`(async () => (await navigator.serviceWorker.getRegistrations()).length)()`);
      if (leftRegs !== 0) fail(`${at}: after turning off ${leftRegs} service worker registration(s) are left`);
      if ((await ntRead(b.base)).devices.some((d) => d.id === id2)) fail(`${at}: after turning off the server still lists this device`);
      // No push went anywhere but the stub; it got none of the sends that a page on screen would have stopped.
      details.pushes = stub.received.length;
      issueFindings(page.takeIssues(), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  } finally {
    sock?.close();
  }
  return finish({ kind: "flow", name: "notify", route: "settingsSection", scene: "main", size: sizeTag(vp), theme, path: "/settings/notifications", failures, warnings, note: `${stub.received.length} pushes to the stub on 127.0.0.1`, ms: Date.now() - t0, details, shot });
}

/**
 * The stills (1280x800 dark, 390x844 touch light and dark): the section in each, with the seed's other device; dark
 * at 1280 first shows the denied state (its line, and the other device with Turn off); the phone's light run turns on by a link's Save (value=on); the phone's dark
 * run renames the other device and turns it off. Each run is on a seed of its own.
 */
async function notifyStillsRun(b: Booted, stub: PushStub, vp: Viewport, theme: Theme, part: "denied" | "link" | "devices"): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = { part };
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const at = `${vp.width}x${vp.height} ${theme}`;
  const settings = `${b.base}/settings/notifications`;
  let shot: string | undefined;
  const other: string = EX.device;
  try {
    await withPage(vp, theme, async (page, wire) => {
      await page.send("Page.addScriptToEvaluateOnNewDocument", { source: NT_STAND_IN });
      if (part === "denied") {
        await cdp.send("Browser.setPermission", { permission: { name: "notifications" }, setting: "denied", origin: b.base, browserContextId: page.contextId });
        await page.navigate(settings);
        // The line, and the server's list under it: the seed's other device, with Turn off, so it can be turned off
        // from a browser that blocked kitespan; no row is this device's.
        const denied = await ntUntil(page, (s) => s.firstLine !== null && s.devices.length > 0, 8000);
        details.denied = denied.s;
        if (denied.s.sw || denied.s.firstLine !== "Notifications from kitespan are blocked here. Allow them in this browser's or this device's settings.") fail(`${at}: a blocked permission shows ${JSON.stringify(denied.s.sw)} with ${JSON.stringify(denied.s.firstLine)}`);
        const listed = denied.s.devices.find((d) => d.id === other);
        if (!listed || !listed.off || denied.s.devices.some((d) => d.you)) fail(`${at}: the denied state lists ${JSON.stringify(denied.s.devices)}, not the other device with Turn off`);
        if (denied.s.titles !== null) fail(`${at}: the denied state shows Show chat titles`);
        await maskMachine(page);
        await page.screenshot(ntShot(vp, theme, "denied"));
      }
      await cdp.send("Browser.grantPermissions", { origin: b.base, permissions: ["notifications"], browserContextId: page.contextId });
      // The stand-in's next subscription lives in the origin's local storage, so the page is on the origin first.
      await page.navigate(settings);
      await ntUntil(page, (s) => s.sw !== null, 8000);
      await ntNext(page, stub.subscribe(`${vp.name}-${theme}`));
      const mark = wire.mark();
      if (part === "link") {
        // A link only pre-fills: Not saved and its named Save; nothing goes out until the Save's tap.
        await page.navigate(`${settings}/this-device?value=on`);
        const linked = await ntUntil(page, (s) => s.save !== null, 8000);
        details.link = linked.s;
        if (linked.s.save !== "Turn on notifications" || linked.s.sw?.on !== true) fail(`${at}: the link's value shows ${JSON.stringify(linked.s.sw)} with the Save ${JSON.stringify(linked.s.save)}`);
        await sleep(800);
        if (wire.httpSince(mark).length || mutating(wire.framesSince(mark)).length) fail(`${at}: the link sent ${clipList(wire.httpSince(mark).map(httpText))} before any tap`, "frames");
        await maskMachine(page);
        await page.screenshot(ntShot(vp, theme, "link"));
        await ntPress(page, '[data-testid="setting-this-device"] [data-testid="confirm-save"]');
      } else await ntPress(page, '[data-testid="notify-switch"]');
      const on = await ntUntil(page, (s) => s.sw?.on === true && !s.sw.busy && s.devices.length >= 2 && s.save === null, 10_000);
      details.on = on.s;
      if (!on.ok) return fail(`${at}: the switch did not turn on with both devices listed (${JSON.stringify(on.s.sw)}, ${on.s.devices.length}; ${on.s.firstLine ?? "no line"})`);
      const mine = on.s.devices[0]!;
      const theirs = on.s.devices.find((d) => d.id === other);
      if (!mine.you || !theirs || !theirs.off || theirs.you || theirs.name !== "iPhone") fail(`${at}: the list reads ${JSON.stringify(on.s.devices)}: this device first with This device, the other with Turn off`);
      await ntPress(page, '[data-testid="titles-switch"]');
      await ntUntil(page, (s) => s.titles === true, 4000);
      await sleep(300);
      shot = ntShot(vp, theme, "on");
      await maskMachine(page);
      await page.screenshot(shot);
      if (vp.touch) {
        const small = (await page.evaluate<string[]>(SMALL_TARGETS).catch(() => [] as string[])).filter((x) => /switch|device|confirm|Turn off|Rename/.test(x));
        if (small.length) warnings.push({ code: "target", text: `${at}: under 44 px: ${clipList(small, 4)}` });
      }
      if (part === "devices") {
        // The other device's name: a tap turns it into a field; the new name saves with Enter... on touch, Save.
        await ntPress(page, `[data-testid="device-${other}"] [data-testid="device-name"]`);
        const field = await ntUntil(page, (s) => s.devices.some((d) => d.id === other && d.field !== null), 3000);
        if (!field.ok) fail(`${at}: a tap on the other device's name did not turn it into a field`);
        await page.evaluate(`(() => { const f = document.querySelector('[data-testid="device-name-field"]'); const set = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set; set.call(f, "Personal iPhone"); f.dispatchEvent(new Event("input", { bubbles: true })); return true; })()`);
        await sleep(100);
        await maskMachine(page);
        await page.screenshot(ntShot(vp, theme, "rename"));
        const m = wire.mark();
        await ntPress(page, '[data-testid="device-save"]');
        const renamed = await ntUntil(page, (s) => s.devices.some((d) => d.id === other && d.name === "Personal iPhone"), 4000);
        if (!renamed.ok || !wire.httpSince(m).some((h) => h.method === "POST" && h.path === `/api/push/devices/${other}`)) fail(`${at}: the rename did not save (${clipList(wire.httpSince(m).map(httpText))})`);
        const m2 = wire.mark();
        await ntPress(page, `[data-testid="device-${other}"] [data-testid="device-turn-off"]`);
        const gone = await ntUntil(page, (s) => !s.devices.some((d) => d.id === other), 4000);
        if (!gone.ok || !wire.httpSince(m2).some((h) => h.method === "POST" && h.path === `/api/push/devices/${other}/remove`)) fail(`${at}: Turn off on the other device did not remove it (${clipList(wire.httpSince(m2).map(httpText))})`);
      }
      // This device off again, so the next run starts from no device of its own.
      await ntPress(page, '[data-testid="notify-switch"]');
      await ntUntil(page, (s) => s.sw?.on === false && !s.sw.busy, 8000);
      issueFindings(page.takeIssues(), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return finish({ kind: "flow", name: "notify", route: "settingsSection", scene: "main", size: sizeTag(vp), theme, path: "/settings/notifications", failures, warnings, note: `stills: ${part}`, ms: Date.now() - t0, details, shot });
}

/** R130's notify, on main scene seeds of its own with the stub push service (none with --base). */
async function notifyFlows(record: (r: CheckResult) => void, problems: string[]): Promise<void> {
  if (BASE) {
    console.log("ui-check: notify boots a seed of its own with a stub push service, so --base runs none of it");
    return;
  }
  const laptop = CORE.some((v) => v.name === "laptop") ? WIDE_LAPTOP : null;
  const phone = CORE.find((v) => v.name === "phone") ?? null;
  const runs: { vp: Viewport; theme: Theme; part: "full" | "denied" | "link" | "devices" }[] = [];
  if (laptop && THEMES.includes("light")) runs.push({ vp: laptop, theme: "light", part: "full" });
  if (laptop && THEMES.includes("dark")) runs.push({ vp: laptop, theme: "dark", part: "denied" });
  if (phone && THEMES.includes("light")) runs.push({ vp: phone, theme: "light", part: "link" });
  if (phone && THEMES.includes("dark")) runs.push({ vp: phone, theme: "dark", part: "devices" });
  for (const vp of extraAt("notify")) runs.push({ vp, theme: THEMES.includes("light") ? "light" : THEMES[0]!, part: "link" });
  if (!runs.length || cdp.closed) return;
  const stub = startPushStub({ listen: true });
  const done = (r: (typeof runs)[number], text: string) =>
    record(finish({ kind: "flow", name: "notify", route: "settingsSection", scene: "main", size: sizeTag(r.vp), theme: r.theme, path: "/settings/notifications", failures: [{ code: "seed", text }], warnings: [], note: "", ms: 0, details: {} }));
  try {
    for (const r of runs) {
      if (cdp.closed) break;
      // A fresh seed per run: the full run's moments mark the chats it pushed for, and each run turns on from none.
      let b: Booted;
      try {
        b = await boot({ scene: "main", port: PORT, dist: built!, keep: KEEP, env: { ...SERVER_ENV, KITESPAN_PUSH_TEST_ORIGIN: stub.origin, NO_PROXY: "127.0.0.1", no_proxy: "127.0.0.1" } });
      } catch (e) {
        done(r, `the seed did not boot: ${(e as Error).message}`);
        continue;
      }
      live.add(b);
      try {
        record(r.part === "full" ? await notifyRun(b, stub, r.vp, r.theme) : await notifyStillsRun(b, stub, r.vp, r.theme, r.part));
      } finally {
        const s = await b.stop();
        live.delete(b);
        if (s.code !== 0) problems.push(`scene main (notify): the server exited with ${s.code}`);
        if (s.leftovers.length) problems.push(`scene main (notify): ${s.leftovers.length} process(es) outlived the server and were ended by pid`);
      }
    }
  } finally {
    stub.stop();
  }
}

// ---------------------------------------------------------------------------------------------------------------
// R130 (owner rows 128 and 130; DESIGN-R130 section 5): Bring back in the side chat. bring-back runs on a side scene
// seed of its own (none with --base). At 1280x800 light: an answer's Bring back (after Copy) puts it into the message
// box after the text typed there, as a Markdown quote with one blank line before it and one after it: exactly one
// `draft` frame of the message box with that text, no `send` and no `side_question`; the side chat stays open beside
// the chat and the box has the focus with the caret at the end. An earlier answer opened in place has its own Bring
// back. With a `!` command in the box nothing changes, no frame goes, and the line above the composer says why until
// the box holds no command. With Reduce motion nothing new moves. Each other look at 1280x800 light, and 1280x800
// dark, show the answer's foot and the box after the press. At 1040x800 the side chat is a layer over the chat: it
// closes, and the box has the focus with the caret at the end. At 390x844 touch, light and dark: the phone's sheet closes
// (the route is the chat's), the box shows the quote, and nothing takes the focus. At 834x1194 touch light: the docked
// pane stays open, and nothing takes the focus.

/** The quote that Bring back makes of an answer (the check's own copy of DESIGN-R130 5's form). */
function bbQuote(answer: string): string {
  return answer
    .replace(/\r\n?/g, "\n")
    .trim()
    .split("\n")
    .map((l) => (l.trim() === "" ? ">" : `> ${l}`))
    .join("\n");
}
const BB = {
  typed: "Fix it so that the test waits for the event.",
  command: "git status",
  line: "To bring that answer back, first run or clear the command in the message box.",
} as const;

interface BbState {
  place: string | null;
  path: string;
  box: string | null;
  /** The message box's field: its scroll, sizes, line height and padding (px). */
  field: { top: number; sh: number; ch: number; lh: number; pt: number; pb: number } | null;
  mode: string | null;
  focus: string;
  caretEnd: boolean;
  line: string | null;
  brings: number;
  answer: string | null;
}

const BB_PROBE = `(() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden";
  const fold = (s) => (s || "").replace(/\\s+/g, " ").trim();
  const root = [...document.querySelectorAll('[data-testid="side-chat"]')].find(shown);
  const box = [...document.querySelectorAll('[data-testid="composer"] [data-testid="composer-input"]')].find(shown) || document.querySelector('[data-testid="composer-input"]');
  const cmp = box ? box.closest('[data-mode]') : null;
  const a = document.activeElement;
  const line = [...document.querySelectorAll('[data-testid="bring-back-wait"]')].find(shown);
  const cs = box ? getComputedStyle(box) : null;
  return {
    place: root ? root.getAttribute("data-place") : null,
    path: location.pathname + location.search,
    box: box ? box.value : null,
    field: box && cs ? { top: box.scrollTop, sh: box.scrollHeight, ch: box.clientHeight, lh: parseFloat(cs.lineHeight) || 0, pt: parseFloat(cs.paddingTop) || 0, pb: parseFloat(cs.paddingBottom) || 0 } : null,
    mode: cmp ? cmp.getAttribute("data-mode") : null,
    focus: !a || a === document.body ? "body" : (a.getAttribute("data-testid") || a.tagName.toLowerCase()),
    caretEnd: !!box && a === box && box.selectionStart === box.value.length && box.selectionEnd === box.value.length,
    line: line ? fold(line.textContent) : null,
    brings: root ? [...root.querySelectorAll('[data-testid="side-bring-back"]')].length : 0,
    answer: root && root.querySelector('[data-testid="side-newest"] [data-testid="side-answer"]') ? fold(root.querySelector('[data-testid="side-newest"] [data-testid="side-answer"]').textContent) : null,
  };
})()`;

async function bbUntil(page: Page, ok: (s: BbState) => boolean, ms: number): Promise<{ ok: boolean; s: BbState }> {
  const end = Date.now() + ms;
  let s = await page.evaluate<BbState>(BB_PROBE);
  while (!ok(s) && Date.now() < end) {
    await sleep(100);
    s = await page.evaluate<BbState>(BB_PROBE);
  }
  return { ok: ok(s), s };
}

/**
 * The newest exchange's question against the Clear row, which stays at the side list's top: when the list scrolls, the
 * question sits whole under that row (R124's rule), never under it.
 */
const BB_UNDER_CLEAR = `(() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden";
  const root = [...document.querySelectorAll('[data-testid="side-chat"]')].find(shown);
  const list = root && root.querySelector('[data-testid="side-list"]');
  const head = root && root.querySelector(".sc-thread-head");
  const q = root && root.querySelector('[data-testid="side-newest"] .sc-q');
  if (!list || !head || !q) return null;
  return { tall: list.scrollHeight > list.clientHeight + 1, headBottom: head.getBoundingClientRect().bottom, qTop: q.getBoundingClientRect().top };
})()`;

/**
 * After Bring back on touch, where nothing takes the focus: the quote's last line is in view as the field's last whole
 * line (the blank line that ends the quote and the caret's line take no whole line of the view), and the field's top
 * line is whole. The field's text ends with those two lines, so its last quote line ends 2 lines above the content's
 * foot. Null when it holds it all.
 */
function bbFieldFindings(f: NonNullable<BbState["field"]>): string | null {
  if (!f.lh || f.sh <= f.ch + 1) return null;
  const quoteEnd = f.sh - f.pb - 2 * f.lh;
  const viewEnd = f.top + f.ch;
  const bad: string[] = [];
  if (quoteEnd > viewEnd + 1 || quoteEnd - f.lh < f.top - 1) bad.push("the quote's last line is out of view");
  else if (viewEnd - quoteEnd >= f.lh + f.pb) bad.push("the blank lines after the quote take a whole line of the view");
  const off = (((f.top - f.pt) % f.lh) + f.lh) % f.lh;
  if (f.top > 1 && off > 1.5 && off < f.lh - 1.5) bad.push(`the top line is cut (${Math.round(off)} of ${Math.round(f.lh)} px above the view)`);
  return bad.length ? `${bad.join("; ")} (scrollTop ${Math.round(f.top)} of ${Math.round(f.sh - f.ch)}, line ${Math.round(f.lh)} px)` : null;
}

/** The message box emptied as a user does (its own input event), so the next step starts from an empty box. */
const BB_CLEAR = `(() => { const f = document.querySelector('[data-testid="composer-input"]'); if (!f) return false; const set = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, "value").set; set.call(f, ""); f.dispatchEvent(new Event("input", { bubbles: true })); return true; })()`;

/** The message box's draft frames (never the side box's) and what else acted, since a mark. */
function bbSent(wire: Wire, mark: number): { drafts: WireFrame[]; acts: string[] } {
  const all = wire.framesSince(mark);
  return { drafts: all.filter((f) => f.t === "draft" && f.frame.box !== "side"), acts: acting(all).map(frameText) };
}

async function bringBackRun(b: Booted, vp: Viewport, theme: Theme, part: "full" | "stills" | "touch" | "over"): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = { part };
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const at = `${vp.width}x${vp.height} ${theme}`;
  const chatPath = `/c/${SC_CHAT}`;
  const sidePath = `${chatPath}/btw`;
  // v0.6 touch: the large tablet in portrait has its side chat over the chat.
  const wantPlace = vp.name === "phone" ? "sheet" : vp.name === "medium" ? "pane" : part === "over" || (vp.touch && vp.height > vp.width) ? "over" : "column";
  /** The phone's sheet and the layer over the chat close; the column and the docked pane stay. */
  const closes = wantPlace === "sheet" || wantPlace === "over";
  const shotOf = (step: string) => shotName("side", "bring-back", vp, theme, `${part === "over" ? "over-" : ""}${step}`);
  let shot: string | undefined;
  try {
    await withPage(vp, theme, async (page, wire) => {
      await page.navigate(b.base + sidePath);
      await waitShown(page, ["chat", "conversation"], 8000);
      const opened = await bbUntil(page, (s) => s.place === wantPlace && s.brings > 0, 8000);
      details.opened = opened.s;
      if (!opened.ok) return fail(`${at}: the side chat did not open in its ${wantPlace} with a Bring back (${opened.s.place}, ${opened.s.brings})`);
      // The newest answer as the seed or an earlier run left it (its markdown source, which the quote keeps).
      const newest = (await scUntil(page, (s) => s.newest !== null, 3000)).s.newest;
      let answer = newest === SC_SIDE.ask ? SIDE_ANSWERS.ask : SIDE_KEPT.find((x) => x.question === newest)?.answer ?? "";
      if (!answer) return fail(`${at}: the newest side question is ${JSON.stringify(newest)}, whose answer the check does not know`);
      let typed = "";
      if (part === "full") {
        // A new answer with paragraphs and a list, and text of the user's own in the box first.
        await scAsk(page, vp, SC_SIDE.ask);
        const asked = await scUntil(page, (s) => s.newest === SC_SIDE.ask && s.state === "answered", 10_000);
        if (!asked.ok) return fail(`${at}: the side question got no answer to bring back`);
        answer = SIDE_ANSWERS.ask;
        await scPress(page, '[data-testid="composer-input"]');
        await page.send("Input.insertText", { text: BB.typed });
        typed = BB.typed;
        await sleep(600);
      }
      const want = `${typed ? `${typed}\n\n` : ""}${bbQuote(answer)}\n\n`;
      if (vp.touch) await page.evaluate("document.activeElement && document.activeElement.blur && document.activeElement.blur()");
      const under = await page.evaluate<{ tall: boolean; headBottom: number; qTop: number } | null>(BB_UNDER_CLEAR);
      details.underClear = under;
      if (under?.tall && under.qTop < under.headBottom - 0.5) fail(`${at}: the newest question's top is ${Math.round(under.headBottom - under.qTop)} px under the Clear row`);
      await maskMachine(page);
      await page.screenshot(shotOf("answer"));
      let mark = wire.mark();
      if (!(await scPress(page, '[data-testid="side-chat"] [data-testid="side-newest"] [data-testid="side-bring-back"]'))) return fail(`${at}: Bring back could not be found to press`);
      const after = await bbUntil(page, (s) => s.box === want && (closes ? s.place === null : s.place === wantPlace), 4000);
      await sleep(600);
      details.after = after.s;
      const sent = bbSent(wire, mark);
      details.frames = { drafts: sent.drafts.map((f) => clip(String(f.frame.text), 80)), acts: sent.acts };
      if (!after.ok) fail(`${at}: after Bring back the box holds ${JSON.stringify(clip(after.s.box ?? "", 120))} with the side chat ${after.s.place ?? "closed"}, not the quote ${closes ? `with the ${wantPlace} closed` : `with the ${wantPlace} open`}`);
      if (sent.drafts.length !== 1 || sent.drafts[0]!.frame.text !== want || sent.drafts[0]!.frame.mode !== "chat") fail(`${at}: Bring back sent ${sent.drafts.length} draft frame(s) of the message box (${clipList(sent.drafts.map((f) => clip(String(f.frame.text), 80)))}), not one with the quote`, "frames");
      if (sent.acts.some((t) => t === "send" || t === "side_question" || t === "bash")) fail(`${at}: Bring back sent ${clipList(sent.acts)}`, "frames");
      if (closes && after.s.path !== chatPath) fail(`${at}: after Bring back the route is ${after.s.path}, not the chat's`);
      if (!closes && after.s.path !== sidePath) fail(`${at}: after Bring back the route is ${after.s.path}, not the side chat's`);
      if (!vp.touch && !after.s.caretEnd) fail(`${at}: on the laptop the box has no focus with the caret at the end (${after.s.focus})`);
      if (vp.touch && after.s.focus === "composer-input") fail(`${at}: on touch Bring back put the focus in the box, so the keyboard would come up`);
      if (vp.touch) {
        // Read again: the field scrolls in the frame after the draft lands.
        const field = (await page.evaluate<BbState>(BB_PROBE)).field;
        details.field = field;
        const cut = field ? bbFieldFindings(field) : null;
        if (cut) fail(`${at}: after Bring back the field shows the quote badly: ${cut}`);
      }
      await page.evaluate(P2_DRAWN);
      shot = shotOf("after");
      await maskMachine(page);
      await page.screenshot(shot);

      if (part === "full") {
        // An earlier answer opened in place has its own Bring back.
        await scPress(page, '[data-testid="side-chat"] [data-testid="side-earlier"] .sc-q');
        const both = await bbUntil(page, (s) => s.brings >= 2, 3000);
        if (!both.ok) fail(`${at}: an earlier answer opened in place has no Bring back (${both.s.brings} in the thread)`);
        // The looks restyle the foot and the box with no rule of their own.
        for (const look of P2_LOOKS.filter((l) => l !== "glass")) {
          await wearLook(page, look, theme);
          await maskMachine(page);
          await page.screenshot(shotOf(`after-${look}`));
        }
        await wearLook(page, "glass", theme);

        // A `!` command in the box: nothing changes, no frame, and the line until the box holds no command.
        await page.evaluate(BB_CLEAR);
        await scPress(page, '[data-testid="composer-input"]');
        await page.send("Input.insertText", { text: "!" });
        await sleep(80);
        await page.send("Input.insertText", { text: BB.command });
        await sleep(600);
        const cmd = await bbUntil(page, (s) => s.mode === "bash" && s.box === BB.command, 2000);
        if (!cmd.ok) fail(`${at}: the box did not take the command in Bash mode (${cmd.s.mode}, ${JSON.stringify(cmd.s.box)})`);
        mark = wire.mark();
        await scPress(page, '[data-testid="side-chat"] [data-testid="side-newest"] [data-testid="side-bring-back"]');
        const refused = await bbUntil(page, (s) => s.line !== null, 3000);
        await sleep(500);
        details.refused = refused.s;
        if (refused.s.line !== BB.line) fail(`${at}: with a command in the box the line reads ${JSON.stringify(refused.s.line)}`);
        if (refused.s.box !== BB.command || refused.s.mode !== "bash") fail(`${at}: the refused Bring back changed the box to ${JSON.stringify(refused.s.box)} (${refused.s.mode})`);
        const quiet = bbSent(wire, mark);
        if (quiet.drafts.length || quiet.acts.length) fail(`${at}: the refused Bring back sent ${quiet.drafts.length} draft frame(s) and ${clipList(quiet.acts)}`, "frames");
        await maskMachine(page);
        await page.screenshot(shotOf("command"));
        await page.evaluate(BB_CLEAR);
        const cleared = await bbUntil(page, (s) => s.line === null, 3000);
        if (!cleared.ok) fail(`${at}: the line stays after the command left the box`);

        // Reduce motion: nothing new moves; the press runs no animation in the box or the side chat.
        await page.send("Emulation.setEmulatedMedia", { media: "screen", features: [{ name: "prefers-color-scheme", value: theme }, { name: "prefers-reduced-motion", value: "reduce" }] });
        await page.evaluate(BB_CLEAR);
        await sleep(300);
        await scPress(page, '[data-testid="side-chat"] [data-testid="side-newest"] [data-testid="side-bring-back"]');
        const moving = await page.evaluate<string[]>(`(() => document.getAnimations().filter((a) => a.playState === "running" && a.effect && a.effect.target && a.effect.target.closest && a.effect.target.closest('[data-testid="composer"], [data-testid="side-chat"]')).map((a) => a.animationName || a.transitionProperty || "?"))()`);
        details.reduceMotion = moving;
        if (moving.length) fail(`${at}: with Reduce motion Bring back runs ${clipList(moving)}`);
        await page.send("Emulation.setEmulatedMedia", { media: "screen", features: [{ name: "prefers-color-scheme", value: theme }] });

        // /c/<chat>/btw/<exchange>: that exchange opened in place and marked, its Bring back focused, nothing sent;
        // an exchange the thread no longer has: one line.
        await page.evaluate(BB_CLEAR);
        await sleep(400);
        mark = wire.mark();
        await page.navigate(`${b.base}${sidePath}/${EX.exchange}`);
        const linked = await page.evaluate<{ marked: string | null; open: boolean; focus: string | null }>(`new Promise((done) => setTimeout(() => {
          const el = document.querySelector('[data-testid="side-chat"] .sc-x.is-marked');
          const a = document.activeElement;
          done({ marked: el ? el.getAttribute("data-exchange") : null, open: !!(el && el.querySelector('[data-testid="side-bring-back"]')), focus: a && a.closest && a.closest(".sc-x.is-marked") ? a.getAttribute("data-testid") : null });
        }, 800))`);
        details.exchangeLink = linked;
        if (linked.marked !== EX.exchange || !linked.open) fail(`${at}: the exchange's link marks ${JSON.stringify(linked.marked)} (open: ${linked.open}), not the earlier exchange opened in place`);
        if (linked.focus !== "side-bring-back") fail(`${at}: on the laptop the exchange's link left the focus on ${JSON.stringify(linked.focus)}, not its Bring back`);
        const linkSent = bbSent(wire, mark);
        if (linkSent.drafts.length || linkSent.acts.length || wire.httpSince(mark).length) fail(`${at}: the exchange's link sent ${clipList([...linkSent.acts, ...wire.httpSince(mark).map(httpText)])} with no press`, "frames");
        await maskMachine(page);
        await page.screenshot(shotOf("exchange"));
        await page.navigate(`${b.base}${sidePath}/00000000-0000-4000-8000-00000000dead`);
        const goneLine = await page.evaluate<string | null>(`new Promise((done) => setTimeout(() => { const n = document.querySelector('[data-testid="side-chat"] [data-testid="link-notice"]'); done(n ? n.textContent.trim() : null); }, 800))`);
        if (goneLine !== "That side question is not in the side chat any more.") fail(`${at}: a link to an exchange the thread does not have shows ${JSON.stringify(goneLine)}`);
      }
      // The box empty again for the next run.
      await page.evaluate(BB_CLEAR);
      await sleep(400);
      issueFindings(page.takeIssues(), failures);
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return finish({ kind: "flow", name: "bring-back", route: "sideChat", scene: "side", size: sizeTag(vp), theme, path: sidePath, failures, warnings, note: part === "full" ? "the quote, the refusal, Reduce motion and the looks" : "", ms: Date.now() - t0, details, shot });
}

/** R130's bring-back, on one side scene seed of its own (none with --base). */
async function bringBackFlows(record: (r: CheckResult) => void, problems: string[]): Promise<void> {
  if (BASE) {
    console.log("ui-check: bring-back boots a seed of its own (the side scene), so --base runs none of it");
    return;
  }
  const laptop = CORE.some((v) => v.name === "laptop") ? WIDE_LAPTOP : null;
  const phone = CORE.find((v) => v.name === "phone") ?? null;
  const medium = CORE.find((v) => v.name === "medium") ?? null;
  const runs: { vp: Viewport; theme: Theme; part: "full" | "stills" | "touch" | "over" }[] = [];
  if (laptop && THEMES.includes("light")) runs.push({ vp: laptop, theme: "light", part: "full" });
  // A laptop window from 1,000 to 1,087 px: the side chat is a layer over the chat, which closes as the sheet does.
  if (laptop && THEMES.includes("light")) runs.push({ vp: { ...WIDE_LAPTOP, width: 1040 }, theme: "light", part: "over" });
  if (laptop && THEMES.includes("dark")) runs.push({ vp: laptop, theme: "dark", part: "stills" });
  if (phone) for (const theme of THEMES) runs.push({ vp: phone, theme, part: "touch" });
  if (medium && THEMES.includes("light")) runs.push({ vp: medium, theme: "light", part: "touch" });
  for (const vp of extraAt("bring-back")) runs.push({ vp, theme: THEMES.includes("light") ? "light" : THEMES[0]!, part: "touch" });
  if (!runs.length || cdp.closed) return;
  let b: Booted;
  try {
    b = await boot({ scene: "side", port: PORT, dist: built!, keep: KEEP, env: SERVER_ENV });
  } catch (e) {
    for (const r of runs) record(finish({ kind: "flow", name: "bring-back", route: "sideChat", scene: "side", size: sizeTag(r.vp), theme: r.theme, path: `/c/${SC_CHAT}/btw`, failures: [{ code: "seed", text: `the seed did not boot: ${(e as Error).message}` }], warnings: [], note: "", ms: 0, details: {} }));
    return;
  }
  live.add(b);
  try {
    for (const r of runs) {
      if (cdp.closed) break;
      record(await bringBackRun(b, r.vp, r.theme, r.part));
    }
  } finally {
    const s = await b.stop();
    live.delete(b);
    if (s.code !== 0) problems.push(`scene side (bring-back): the server exited with ${s.code}`);
    if (s.leftovers.length) problems.push(`scene side (bring-back): ${s.leftovers.length} process(es) outlived the server and were ended by pid`);
  }
}

// ---------------------------------------------------------------------------------------------------------------
// FIX-C1 (DESIGN-C1; DESIGN.md 7.5): the phone's message box with a draft of several lines. composer-lines runs on a
// side scene seed of its own (none with --base), on the example chat, its box emptied first and left empty. At
// 390x844 touch in Glass light (the full run), Glass dark, and Paper, Mono and Editor light: one line typed keeps one
// row (+, @, the field and Send side by side); the sentence typed key by key stacks the box once, at a measured line
// (the text over the box's whole width, inset; +, @ and Send on one row under it), with the focus and the caret kept,
// +, @ and Send where they were (their left edges and their distance from the view's foot), the conversation's end in
// view at the same place, and 44 px targets; deleted back it goes to one row only 2em earlier, and typed again it
// stacks at the same character; a paste of several lines stacks at once; the box's 4-line cap holds and never covers
// the conversation's last item; an emptied box is one row. The full run also checks a caret in the middle, a selection
// through a switch, one character deleted and typed again at the edge six times (no switch), a reader higher up in the
// chat (their place stays), the stand-in keyboard (336 px) with the box riding it, Bash mode (the ! chip on the text's
// first line, Run in Send's place; also in the dark run), and Bring back's quote (R130), which lands stacked with its
// last line the field's last whole line. At 834x1194 touch and 1280x800, light, a long draft keeps the field over the
// bar (no phone form). Nothing acting is sent (draft frames only). Each switch is read two frames later (DESIGN-C1 11).
// From round C1's review: at the cap the field's top edge cuts no line's glyphs (every look); with the box in the flow
// and riding the keyboard, a ResizeObserver on the box and the chat (after the layout, before the paint) reads every
// drawn frame, and in none of them does the box cover the conversation's last item; the phone rotated (844x390 touch,
// Glass light, the keyboard down and a stand-in of 170 px up) keeps one row for every draft, and upright again the
// same draft stacks; and last, on the phone, a reader who scrolled up in a long draft while a turn runs (sent from a
// laptop page) keeps their place in the field when the turn ends, with the caret and the focus kept.

const CL_TEXT = {
  one: "Run it again",
  sentence: "Run the upload test 20 times and tell me which runs fail.",
  paste: "Two things to check:\nthe wait in waitFor,\nand the fake server's event order.",
  long: "Run the upload test 20 times with the fake server, and when a run fails, keep its log and the server's events in order. Then look at the wait in waitFor: I think it misses an event that comes before the listener is added, which would explain the 5 s timeouts we see now and then.",
  bash: "bun test test/upload.test.ts --rerun-each 20 --timeout 10000 --bail",
} as const;

interface ClRect {
  left: number;
  right: number;
  top: number;
  bottom: number;
  width: number;
  height: number;
}
interface ClState {
  stacked: boolean;
  phone: boolean;
  riding: boolean;
  mode: string | null;
  value: string | null;
  sel: [number, number] | null;
  focus: boolean;
  cmp: ClRect | null;
  slab: ClRect | null;
  field: ClRect | null;
  /** The field's line: the mode chip and the field. */
  line: ClRect | null;
  plus: ClRect | null;
  at: ClRect | null;
  key: ClRect | null;
  chip: ClRect | null;
  bar: ClRect | null;
  metrics: { top: number; sh: number; ch: number; lh: number; pt: number; pb: number; fs: number } | null;
  /** The chat's scroller; `max`: how far it scrolls (0: the conversation fits its view). */
  scroller: { top: number; bottom: number; max: number } | null;
  first: { id: string | null; top: number } | null;
  last: { id: string | null; bottom: number } | null;
  visual: number;
}

/** The message box and the conversation as the page lays them out (CSS px). */
const CL_PROBE = `(() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden" && getComputedStyle(el).display !== "none";
  const rect = (el) => { if (!shown(el)) return null; const r = el.getBoundingClientRect(); return { left: r.left, right: r.right, top: r.top, bottom: r.bottom, width: r.width, height: r.height }; };
  const cmp = [...document.querySelectorAll('[data-testid="composer"]')].find(shown) || null;
  const q = (s) => (cmp ? cmp.querySelector(s) : null);
  const field = q('[data-testid="composer-input"]');
  const row = q(".cmp-field");
  const kid = (s) => (row ? [...row.children].find((c) => c.matches(s) && shown(c)) || null : null);
  const scroller = document.querySelector('[data-testid="conversation"] .chat-scroll');
  const sr = scroller ? scroller.getBoundingClientRect() : null;
  const items = scroller ? [...scroller.querySelectorAll("[data-item-id]")].filter(shown) : [];
  const first = sr ? items.find((it) => it.getBoundingClientRect().bottom > sr.top + 1) : null;
  const last = items.length ? items[items.length - 1] : null;
  const cs = field ? getComputedStyle(field) : null;
  const vv = window.visualViewport;
  return {
    stacked: !!cmp && cmp.classList.contains("is-stacked"),
    phone: !!cmp && cmp.classList.contains("is-phone"),
    riding: !!cmp && cmp.classList.contains("is-kb"),
    mode: cmp ? cmp.getAttribute("data-mode") : null,
    value: field ? field.value : null,
    sel: field ? [field.selectionStart, field.selectionEnd] : null,
    focus: !!field && document.activeElement === field,
    cmp: rect(cmp), slab: rect(q(".cmp-slab")), field: rect(field), line: rect(kid(".cmp-line")),
    plus: rect(kid(".cmp-plus-btn")), at: rect(kid(".cmp-at-btn")), key: rect(kid(".cmp-key, .btn.cmp-copy")),
    chip: rect(q(".cmp-line > .cmp-chip")), bar: rect(q(".cmp-bar")),
    metrics: field && cs ? { top: field.scrollTop, sh: field.scrollHeight, ch: field.clientHeight, lh: parseFloat(cs.lineHeight) || 0, pt: parseFloat(cs.paddingTop) || 0, pb: parseFloat(cs.paddingBottom) || 0, fs: parseFloat(cs.fontSize) || 0 } : null,
    scroller: sr ? { top: sr.top, bottom: sr.bottom, max: scroller.scrollHeight - scroller.clientHeight } : null,
    first: first ? { id: first.getAttribute("data-item-id"), top: first.getBoundingClientRect().top } : null,
    last: last ? { id: last.getAttribute("data-item-id"), bottom: last.getBoundingClientRect().bottom } : null,
    visual: vv ? vv.height : innerHeight,
  };
})()`;

type ClFail = (text: string, code?: string) => void;
const clRead = (page: Page) => page.evaluate<ClState>(CL_PROBE);
const clPx = (n: number) => Math.round(n);
const clBox = (r: ClRect | null) => (r ? `${clPx(r.left)},${clPx(r.top)} ${clPx(r.width)}x${clPx(r.height)}` : "none");
/** What a run's details keep of a state. */
const clBrief = (s: ClState) => ({ stacked: s.stacked, length: s.value?.length ?? null, slab: clBox(s.slab), field: clBox(s.field), plus: clBox(s.plus), at: clBox(s.at), key: clBox(s.key), focus: s.focus });

/** One row: the field beside + and @, the end key after it, all on the field's row. */
function clOneRowFindings(s: ClState, at: string, fail: ClFail) {
  if (s.stacked) fail(`${at}: the box is stacked`);
  if (!s.field || !s.plus || !s.key) return fail(`${at}: the row's parts do not show (field ${clBox(s.field)}, + ${clBox(s.plus)}, key ${clBox(s.key)})`, "shows");
  const before = s.at ?? s.plus;
  if (s.field.left < before.right - 0.5) fail(`${at}: in one row the field (left ${clPx(s.field.left)}) starts under + or @ (right ${clPx(before.right)})`, "layout");
  if (s.key.left < s.field.right - 0.5) fail(`${at}: in one row the end key (left ${clPx(s.key.left)}) is under the field (right ${clPx(s.field.right)})`, "layout");
  if (s.key.top >= s.field.bottom || s.plus.top >= s.field.bottom) fail(`${at}: in one row the keys sit under the field (field ${clBox(s.field)}, + ${clBox(s.plus)}, key ${clBox(s.key)})`, "layout");
}

/**
 * Stacked: the line (the mode chip and the field) over the box's whole width, inset, and the field in it to its right
 * edge; +, @ and the end key under it, + at the left, the key at the right.
 */
function clStackedFindings(s: ClState, at: string, fail: ClFail) {
  if (!s.stacked) fail(`${at}: the draft of several lines is not stacked`);
  if (!s.field || !s.line || !s.slab || !s.plus || !s.key) return fail(`${at}: the box's parts do not show (slab ${clBox(s.slab)}, line ${clBox(s.line)}, field ${clBox(s.field)}, + ${clBox(s.plus)}, key ${clBox(s.key)})`, "shows");
  if (s.line.width < 0.95 * s.slab.width) fail(`${at}: stacked, the line is ${clPx(s.line.width)} px of the box's ${clPx(s.slab.width)}`, "layout");
  const inset = s.field.left - s.slab.left;
  const end = s.slab.right - s.field.right;
  // The field starts 16 px inside the box (the slab's padding and the line's --s3), or after the mode chip.
  if (!s.chip && (inset < 8 || inset > 24)) fail(`${at}: stacked, the text starts ${clPx(inset)} px inside the box`, "layout");
  if (s.chip && s.field.left < s.chip.right - 0.5) fail(`${at}: stacked, the field (left ${clPx(s.field.left)}) starts under the mode chip (right ${clPx(s.chip.right)})`, "layout");
  if (end < 8 || end > 24) fail(`${at}: stacked, the text ends ${clPx(end)} px inside the box's right edge`, "layout");
  for (const [name, r] of [["+", s.plus], ["@", s.at], ["the end key", s.key]] as const) if (r && r.top < s.field.bottom - 1) fail(`${at}: stacked, ${name} (top ${clPx(r.top)}) is not under the text (its foot ${clPx(s.field.bottom)})`, "layout");
  if (s.plus.left > s.slab.left + 12) fail(`${at}: stacked, + is not at the box's left (${clBox(s.plus)} in ${clBox(s.slab)})`, "layout");
  if (s.key.right < s.slab.right - 12 || s.key.right > s.slab.right + 0.5) fail(`${at}: stacked, the end key is not at the box's right (${clBox(s.key)} in ${clBox(s.slab)})`, "layout");
}

/** The 44 px targets of the row. */
function clTargetFindings(s: ClState, at: string, fail: ClFail) {
  for (const [name, r] of [["+", s.plus], ["@", s.at], ["the end key", s.key]] as const) if (r && (r.width < 43.5 || r.height < 43.5)) fail(`${at}: ${name} is ${clPx(r.width)}x${clPx(r.height)} px, under 44`, "target");
}

/** +, @ and the end key where they were: the same left edge and the same distance from the view's foot. */
function clKeysFindings(a: ClState, b: ClState, at: string, fail: ClFail) {
  for (const [name, x, y] of [["+", a.plus, b.plus], ["@", a.at, b.at], ["the end key", a.key, b.key]] as const) {
    if (!x || !y) continue;
    const dx = Math.abs(x.left - y.left);
    const dy = Math.abs(a.visual - x.bottom - (b.visual - y.bottom));
    if (dx > 1 || dy > 1) fail(`${at}: ${name} moved with the switch (${clBox(x)} to ${clBox(y)})`, "layout");
  }
}

/** The conversation's last item in view above the box, and at the same place as `before` (a reader at the end). */
function clEndFindings(s: ClState, at: string, fail: ClFail, before?: ClState) {
  if (!s.last || !s.cmp || !s.scroller) return fail(`${at}: the conversation's last item or the box does not show`, "shows");
  const foot = Math.min(s.scroller.bottom, s.cmp.top);
  if (s.last.bottom > foot + 1) fail(`${at}: the box covers the conversation's last item (its foot at ${clPx(s.last.bottom)}, the view's at ${clPx(foot)})`, "layout");
  if (before?.last && before.cmp && before.scroller) {
    const was = Math.min(before.scroller.bottom, before.cmp.top) - before.last.bottom;
    const now = foot - s.last.bottom;
    if (Math.abs(was - now) > 2) fail(`${at}: the conversation's end moved: ${clPx(was)} px above the view's foot before, ${clPx(now)} after`, "layout");
  }
}

/** The field shows its cap of `lines` lines and scrolls inside. */
function clCapFindings(s: ClState, lines: number, at: string, fail: ClFail) {
  const m = s.metrics;
  if (!m || !m.lh) return fail(`${at}: the field's measure could not be read`, "shows");
  if (m.sh <= m.ch + 1) fail(`${at}: the long draft does not scroll inside the field (scrollHeight ${clPx(m.sh)}, height ${clPx(m.ch)})`, "layout");
  const want = lines * m.lh + m.pt + m.pb;
  if (Math.abs(m.ch - want) > 2) fail(`${at}: the field is ${clPx(m.ch)} px high, not its ${lines}-line cap (${clPx(want)} px)`, "layout");
}

/**
 * The field's top edge cuts no line's glyphs: scrolled, the part of the line above the first whole one that shows is at
 * most its half leading (the line height less the font size, halved), as on the laptop. With the phone's 10 px of
 * padding inside the scroll box, a draft scrolled to its end showed the lower 10 px of the line above (C1's review).
 */
function clTopCutFindings(s: ClState, at: string, fail: ClFail) {
  const m = s.metrics;
  if (!m || !m.lh || !m.fs || m.top <= m.pt + 0.5) return;
  const off = (((m.top - m.pt) % m.lh) + m.lh) % m.lh;
  const shows = off < 0.5 || off > m.lh - 0.5 ? 0 : m.lh - off;
  const lead = (m.lh - m.fs) / 2;
  if (shows > lead + 0.5) fail(`${at}: the field's top edge cuts a line: ${clPx(shows)} px of it show above the first whole line (its half leading is ${clPx(lead)} px; scrollTop ${clPx(m.top)})`, "layout");
}

/**
 * The drawn frames' covers (C1's review): one ResizeObserver on the box and on the chat's scroller, whose callback runs
 * after the layout and before the paint (and after ChatView's own, which keeps the end), records how far the
 * conversation's last item reaches under the box's top in each frame that changed a size. A dock that took the box's
 * new height a frame late (a state set from a ResizeObserver) covers the end for one drawn frame, which a read two
 * frames later misses. CL_COVER_OFF stops it and returns the record.
 */
const CL_COVER_ON = `(() => {
  const cmp = [...document.querySelectorAll('[data-testid="composer"]')].find((e) => e.getClientRects().length);
  const sc = document.querySelector('[data-testid="conversation"] .chat-scroll');
  if (!cmp || !sc) return false;
  const rec = { frames: 0, worst: null };
  const ro = new ResizeObserver(() => {
    const items = [...sc.querySelectorAll("[data-item-id]")].filter((e) => e.getClientRects().length);
    if (!items.length) return;
    const over = items[items.length - 1].getBoundingClientRect().bottom - Math.min(sc.getBoundingClientRect().bottom, cmp.getBoundingClientRect().top);
    const f = cmp.querySelector('[data-testid="composer-input"]');
    rec.frames++;
    if (!rec.worst || over > rec.worst.over) rec.worst = { over, length: f ? f.value.length : null, stacked: cmp.classList.contains("is-stacked") };
  });
  ro.observe(cmp);
  ro.observe(sc);
  window.__clCoverOff = () => { ro.disconnect(); return rec; };
  return true;
})()`;
const CL_COVER_OFF = `(window.__clCoverOff ? window.__clCoverOff() : null)`;
interface ClCover {
  frames: number;
  worst: { over: number; length: number | null; stacked: boolean } | null;
}
function clCoverFindings(c: ClCover | null, at: string, fail: ClFail) {
  if (!c || !c.frames) return fail(`${at}: no drawn frame was read while the box changed`, "shows");
  if (c.worst && c.worst.over > 1) fail(`${at}: for a drawn frame the box covered the conversation's last item by ${clPx(c.worst.over)} px (at ${c.worst.length} characters, ${c.worst.stacked ? "stacked" : "one row"})`, "layout");
}

/** The phone rotated (7.1: a coarse pointer's short side, so still a phone). */
const CL_ROTATED: Viewport = { name: "phone", width: 844, height: 390, scale: 3, mobile: true, touch: true };
/** The device's metrics with its orientation, for a rotation inside one page. */
const clTurnTo = (page: Page, w: number, h: number) =>
  page.send("Emulation.setDeviceMetricsOverride", { width: w, height: h, deviceScaleFactor: 3, mobile: true, screenWidth: w, screenHeight: h, screenOrientation: w > h ? { type: "landscapePrimary", angle: 90 } : { type: "portraitPrimary", angle: 0 } });
/** The phone's end key's title: running, Send says when Claude reads it. */
const CL_SEND_TITLE = `(() => { const k = document.querySelector('[data-testid="composer"] [data-testid="composer-send"]'); return k ? k.title : null; })()`;

/** Backspace as a key press (the field deletes the character before the caret). */
async function clBack(page: Page) {
  const base = { key: "Backspace", code: "Backspace", windowsVirtualKeyCode: 8, nativeVirtualKeyCode: 8 };
  await page.send("Input.dispatchKeyEvent", { type: "rawKeyDown", ...base });
  await page.send("Input.dispatchKeyEvent", { type: "keyUp", ...base });
  await sleep(30);
}

/** Two frames (twice that while the box rides the keyboard: its dock follows a ResizeObserver), then the state. */
async function clSettled(page: Page, riding: boolean): Promise<ClState> {
  await page.evaluate(P2_DRAWN);
  if (riding) {
    await page.evaluate(P2_DRAWN);
    await sleep(120);
  }
  return clRead(page);
}

/** `text` typed key by key: each change of form with the states before it and two frames after it. */
/** How far the conversation's last item ends above the view's foot (the box's top, or the chat's foot); null: no read. */
function clGap(s: ClState): number | null {
  if (!s.last || !s.cmp || !s.scroller) return null;
  return Math.min(s.scroller.bottom, s.cmp.top) - s.last.bottom;
}

/**
 * A reader at the end of the chat while the box changes, read two frames after every key: the conversation's last
 * item is never under the box, and while the chat scrolls its end keeps its place (within 2 px of where it was when
 * the chat first scrolled). A conversation shorter than its view stays at its top until the box reaches it. `drift`:
 * the keys where that did not hold.
 */
interface ClKeys {
  switches: { length: number; before: ClState; after: ClState }[];
  end: ClState;
  drift: { length: number; gap: number }[];
  /** The end's place while the chat scrolls (null: it has not scrolled yet). */
  gap0: number | null;
}

const clScrolls = (s: ClState) => (s.scroller?.max ?? 0) > 1;

function clDriftFindings(k: ClKeys, at: string, fail: ClFail) {
  if (!k.drift.length) return;
  const off = (g: number) => (g < -1 ? 1e6 - g : k.gap0 === null ? 0 : Math.abs(g - k.gap0));
  const worst = k.drift.reduce((a, b) => (off(b.gap) > off(a.gap) ? b : a));
  const was = worst.gap < -1 ? "so the box covers it" : `not ${clPx(k.gap0 ?? 0)}`;
  fail(`${at}: the conversation's end left its place after ${k.drift.length} key(s), the worst at ${worst.length} characters (${clPx(worst.gap)} px above the view's foot, ${was})`, "layout");
}

/** One edit as the user makes it (`edit`), then two frames; the state, and the drift of the conversation's end. */
async function clKey(page: Page, edit: () => Promise<void>, k: ClKeys, riding: boolean) {
  const prev = k.end;
  await edit();
  await sleep(20);
  const now = await clSettled(page, riding);
  if (now.stacked !== prev.stacked) k.switches.push({ length: now.value?.length ?? 0, before: prev, after: now });
  const gap = clGap(now);
  if (gap !== null) {
    if (gap < -1) k.drift.push({ length: now.value?.length ?? 0, gap });
    else if (clScrolls(now)) {
      if (k.gap0 === null) k.gap0 = gap;
      else if (Math.abs(gap - k.gap0) > 2) k.drift.push({ length: now.value?.length ?? 0, gap });
    }
  }
  k.end = now;
}

/** `text` typed key by key: each change of form, with the state before it and two frames after it. */
async function clTypeKeys(page: Page, text: string, riding = false): Promise<ClKeys> {
  const start = await clRead(page);
  const k: ClKeys = { switches: [], end: start, drift: [], gap0: clScrolls(start) ? clGap(start) : null };
  for (const ch of text) await clKey(page, () => page.send("Input.insertText", { text: ch }), k, riding);
  return k;
}

async function composerLinesRun(b: Booted, vp: Viewport, theme: Theme, part: "full" | "core" | "wide" | "rotated" | "turn", look: P2LookId): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = { part, look };
  const fail: ClFail = (text, code = "flow") => void failures.push({ code, text });
  const at = `${vp.width}x${vp.height} ${look} ${theme}`;
  const chatPath = `/c/${SC_CHAT}`;
  const INPUT = '[data-testid="composer"] [data-testid="composer-input"]';
  let shot: string | undefined;
  let note = "";
  const still = async (page: Page, step: string) => {
    await page.evaluate(P2_DRAWN);
    await maskMachine(page);
    const file = shotName("side", "composer-lines", vp, theme, look === "glass" ? step : `${look}-${step}`);
    await page.screenshot(file);
    return file;
  };
  try {
    await withPage(vp, theme, async (page, wire) => {
      if (vp.touch) await page.send("Page.addScriptToEvaluateOnNewDocument", { source: STAND_IN_KEYBOARD });
      await page.navigate(b.base + chatPath);
      await waitShown(page, ["chat", "composer"], 8000);
      if (look !== "glass") await wearLook(page, look, theme);
      await page.evaluate("document.fonts.ready.then(() => true)");
      await sleep(400);
      const start = await emptyBox(page);
      if (start.value !== "" || start.mode !== "chat") throw new Error(`could not empty the message box: ${JSON.stringify({ value: start.value, mode: start.mode })}`);
      page.takeIssues();
      const mark = wire.mark();
      const focusField = async () => {
        const f = await page.locate(INPUT);
        if (!f) throw new Error("no message box field");
        await page.press(f.x, f.y);
        await sleep(250);
      };

      if (part === "wide") {
        // The tablet and the laptop: the field over the bar, whatever the draft's length; no phone form. Typed key by
        // key, the conversation keeps its end while the field grows (the grow effect's measure never moves it).
        await focusField();
        const keys = await clTypeKeys(page, CL_TEXT.long);
        clDriftFindings(keys, `${at}, the long draft key by key`, fail);
        if (keys.switches.length) fail(`${at}: the box changed form ${keys.switches.length} time(s)`);
        const s = await clSettled(page, false);
        details.wide = { ...clBrief(s), drift: keys.drift.length };
        if (s.phone || s.stacked) fail(`${at}: the box has the phone's form (${s.stacked ? "stacked" : "one row"})`);
        if (!s.bar || !s.field || !s.slab) fail(`${at}: the field or the bar does not show (field ${clBox(s.field)}, bar ${clBox(s.bar)})`, "shows");
        else {
          if (s.bar.top < s.field.bottom - 1) fail(`${at}: the bar (${clBox(s.bar)}) is not under the field (${clBox(s.field)})`, "layout");
          if (s.field.width < 0.6 * s.slab.width) fail(`${at}: the field is ${clPx(s.field.width)} px of the box's ${clPx(s.slab.width)}`, "layout");
        }
        clEndFindings(s, at, fail);
        shot = await still(page, "long");
        note = "the field over the bar; no phone form";
      } else if (part === "rotated") {
        // The phone rotated: its one-row line is wide already (stack.ts rule 0), so every draft keeps one row, and a row
        // of keys never costs a short view 44 px. Upright again the same draft stacks; rotated back it is one row.
        await focusField();
        const keys = await clTypeKeys(page, CL_TEXT.sentence);
        details.sentence = { switches: keys.switches.length, drift: keys.drift.length, end: clBrief(keys.end) };
        clDriftFindings(keys, `${at}, the sentence key by key`, fail);
        if (keys.switches.length) fail(`${at}: the sentence key by key changed the form ${keys.switches.length} time(s)`);
        clOneRowFindings(keys.end, `${at}, the sentence`, fail);
        clTargetFindings(keys.end, `${at}, the sentence`, fail);
        if (!keys.end.focus) fail(`${at}: typing the sentence took the focus from the field`);
        await clearBox(page);
        await page.send("Input.insertText", { text: CL_TEXT.paste });
        await sleep(200);
        const paste = await clSettled(page, false);
        details.paste = clBrief(paste);
        clOneRowFindings(paste, `${at}, a paste of three lines`, fail);
        await clearBox(page);
        await page.send("Input.insertText", { text: CL_TEXT.long });
        await sleep(200);
        const cap = await clSettled(page, false);
        details.cap = { ...clBrief(cap), metrics: cap.metrics };
        clOneRowFindings(cap, `${at}, at the cap`, fail);
        clCapFindings(cap, 4, `${at}, at the cap`, fail);
        clEndFindings(cap, `${at}, at the cap`, fail);
        clTopCutFindings(cap, `${at}, at the cap`, fail);
        shot = await still(page, "rotated-cap");
        // Upright and back, with the caret in the middle of the draft.
        await page.evaluate(`(() => { const f = ${FIELD}; f.setSelectionRange(10, 10); return true; })()`);
        await clTurnTo(page, 390, 844);
        await sleep(600);
        const upright = await clSettled(page, false);
        await clTurnTo(page, CL_ROTATED.width, CL_ROTATED.height);
        await sleep(600);
        const back = await clSettled(page, false);
        details.rotation = { upright: { ...clBrief(upright), sel: upright.sel }, back: { ...clBrief(back), sel: back.sel } };
        if (!upright.stacked) fail(`${at}: upright again (390x844) the long draft is not stacked`);
        if (back.stacked) fail(`${at}: rotated back the long draft is stacked`);
        for (const [name, x] of [["upright", upright], ["rotated back", back]] as const) {
          if (!x.focus) fail(`${at}, ${name}: the field lost the focus`);
          if (!x.sel || x.sel[0] !== 10 || x.sel[1] !== 10) fail(`${at}, ${name}: the caret is at ${JSON.stringify(x.sel)}, not at 10`);
        }
        // The keyboard up (a stand-in of 170 px: 220 px of visual height, so the field's cap is 2 lines).
        await emptyBox(page);
        await focusField();
        await page.evaluate("window.__standInKeyboard(170)");
        await sleep(500);
        const kb0 = await clRead(page);
        if (!kb0.riding) fail(`${at}: with the keyboard up and the focus in the field the box does not ride it`);
        await page.evaluate(CL_COVER_ON);
        const kbKeys = await clTypeKeys(page, CL_TEXT.sentence, true);
        const kbCover = await page.evaluate<ClCover | null>(CL_COVER_OFF);
        details.keyboard = { switches: kbKeys.switches.length, drift: kbKeys.drift.length, visual: kb0.visual, cover: kbCover };
        clCoverFindings(kbCover, `${at}, the keyboard up, the sentence key by key`, fail);
        clDriftFindings(kbKeys, `${at}, the keyboard up, the sentence key by key`, fail);
        if (kbKeys.switches.length) fail(`${at}, the keyboard up: the sentence changed the form ${kbKeys.switches.length} time(s)`);
        await page.send("Input.insertText", { text: ` ${CL_TEXT.long}` });
        await sleep(150);
        const kbCap = await clSettled(page, true);
        details.keyboardCap = { ...clBrief(kbCap), metrics: kbCap.metrics };
        clOneRowFindings(kbCap, `${at}, the keyboard up, at the cap`, fail);
        clCapFindings(kbCap, kbCap.visual < 400 ? 2 : 4, `${at}, the keyboard up, at the cap`, fail);
        clEndFindings(kbCap, `${at}, the keyboard up, at the cap`, fail);
        if (kbCap.slab && kbCap.slab.bottom > kbCap.visual + 0.5) fail(`${at}, the keyboard up, at the cap: the box's foot is under the keyboard's top`, "layout");
        await still(page, "rotated-kb");
        await page.evaluate("window.__standInKeyboard(0)");
        await sleep(700);
        note = "rotated: one row for every draft; upright the same draft stacks";
      } else if (part === "turn") {
        // A turn that ends measures the field again (the end key's kinds change its column) and must not move it: a
        // reader who scrolled up in a long draft keeps their place, and only an edit scrolls it to the caret (stack.ts
        // pinsEnd). The turn is sent from a laptop page first (the draft is the chat's, D49, so the phone types after).
        const lap = await Page.open(cdp, WIDE_LAPTOP, theme);
        let sent = false;
        try {
          await lap.navigate(b.base + chatPath);
          await waitShown(lap, ["chat", "composer"], 8000);
          sent = await sendFromBox(lap, pacedPrompt(2400, 60, 200));
          await sleep(500);
        } finally {
          await lap.close();
        }
        if (!sent) throw new Error("the laptop page shows no message box with Send");
        let runs = false;
        for (let i = 0; i < 80 && !runs; i++) {
          runs = await page.evaluate<boolean>(`!!document.querySelector('[data-testid="composer"] [data-testid="composer-stop"]')`);
          if (!runs) await sleep(100);
        }
        if (!runs) throw new Error("the turn sent from the laptop page does not run on the phone (no Stop in the empty box)");
        await focusField();
        await page.send("Input.insertText", { text: CL_TEXT.long });
        await sleep(300);
        const typed = await clSettled(page, false);
        const m = typed.metrics;
        if (!m || m.sh <= m.ch + 1) throw new Error("the long draft does not scroll inside the field");
        const want = Math.round((m.sh - m.ch) / 2);
        await page.evaluate(`(() => { const f = ${FIELD}; f.scrollTop = ${want}; return true; })()`);
        await page.evaluate(P2_DRAWN);
        const reading = await clRead(page);
        const during = await page.evaluate<string | null>(CL_SEND_TITLE);
        if (during === "Send (Enter)") throw new Error("the turn ended before the reader scrolled up");
        let title = during;
        for (let i = 0; i < 300 && title !== "Send (Enter)"; i++) {
          await sleep(100);
          title = await page.evaluate<string | null>(CL_SEND_TITLE);
        }
        await sleep(300);
        const after = await clSettled(page, false);
        details.turn = { typed: { ...clBrief(typed), metrics: m }, reading: { top: reading.metrics?.top, sel: reading.sel }, during, ended: title, after: { ...clBrief(after), top: after.metrics?.top, sel: after.sel } };
        if (title !== "Send (Enter)") fail(`${at}: the turn did not end in 30 s (Send's title ${JSON.stringify(title)})`, "run");
        if (!typed.stacked) fail(`${at}: the long draft is not stacked`);
        const len = CL_TEXT.long.length;
        if (!reading.metrics || Math.abs(reading.metrics.top - want) > 1 || !reading.sel || reading.sel[0] !== len) fail(`${at}: the reader's scroll did not take (scrollTop ${reading.metrics?.top}, caret ${JSON.stringify(reading.sel)})`, "run");
        else if (!after.metrics || Math.abs(after.metrics.top - want) > 1) fail(`${at}: when the turn ended the field's scroll moved from ${want} to ${clPx(after.metrics?.top ?? -1)} (of ${clPx(m.sh - m.ch)}), and the reader lost their place in the draft`, "layout");
        if (!after.focus) fail(`${at}: when the turn ended the field lost the focus`);
        if (!after.sel || after.sel[0] !== len || after.sel[1] !== len) fail(`${at}: when the turn ended the caret is at ${JSON.stringify(after.sel)}, not at the end (${len})`);
        if (after.value !== CL_TEXT.long) fail(`${at}: when the turn ended the field holds ${JSON.stringify(clip(after.value ?? "", 80))}`);
        shot = await still(page, "turn-ended");
        note = `the reader's scroll in the draft (${want} px) kept through the turn's end`;
      } else {
        // 1. One line: one row.
        await focusField();
        await insertSlow(page, CL_TEXT.one);
        const one = await clSettled(page, false);
        details.one = clBrief(one);
        if (!one.focus) fail(`${at}: typing one line took the focus from the field`);
        if (one.value !== CL_TEXT.one) fail(`${at}: the field holds ${JSON.stringify(one.value)}, not the line as typed`);
        clOneRowFindings(one, `${at}, one line`, fail);
        clTargetFindings(one, `${at}, one line`, fail);
        await still(page, "one");

        // 2. The sentence key by key: one switch, to stacked, at a measured line; no drawn frame covers the end.
        await clearBox(page);
        await page.evaluate(CL_COVER_ON);
        const typed = await clTypeKeys(page, CL_TEXT.sentence);
        const typedCover = await page.evaluate<ClCover | null>(CL_COVER_OFF);
        const sw = typed.switches;
        details.typed = { switches: sw.map((x) => ({ length: x.length, stacked: x.after.stacked, before: clBrief(x.before), after: clBrief(x.after) })), end: clBrief(typed.end), drift: typed.drift.length, cover: typedCover };
        clDriftFindings(typed, `${at}, the sentence key by key`, fail);
        clCoverFindings(typedCover, `${at}, the sentence key by key`, fail);
        if (sw.length !== 1 || !sw[0]!.after.stacked) fail(`${at}: typing the sentence key by key changed the form ${sw.length} time(s) (${sw.map((x) => `${x.after.stacked ? "stacked" : "one row"} at ${x.length}`).join(", ") || "never"}), not once to stacked`);
        const stackAt = sw[0]?.after.stacked ? sw[0].length : 0;
        if (sw[0]) {
          const { before, after } = sw[0];
          const where = `${at}, at the switch (${stackAt} characters)`;
          if (!after.focus) fail(`${where}: the field lost the focus`);
          if (!after.sel || after.sel[0] !== after.value?.length || after.sel[1] !== after.value?.length) fail(`${where}: the caret is at ${JSON.stringify(after.sel)}, not at the end (${after.value?.length})`);
          clStackedFindings(after, where, fail);
          clKeysFindings(before, after, where, fail);
          clEndFindings(after, where, fail, before);
          clTargetFindings(after, where, fail);
        }
        if (typed.end.value !== CL_TEXT.sentence) fail(`${at}: the field holds ${JSON.stringify(typed.end.value)}, not the sentence as typed`);
        stateFindings(await page.probe(), vp, failures, `${at}, stacked: `);
        await still(page, "two");

        // 3. Deleted back: one row again only 2em before the character that stacked it; typed again, the same character.
        let backAt = -1;
        const back: ClKeys = { switches: [], end: typed.end, drift: [], gap0: typed.gap0 };
        for (let n = 0; n < CL_TEXT.sentence.length && backAt < 0; n++) {
          await clKey(page, () => clBack(page), back, false);
          const turn = back.switches[0];
          if (!turn) continue;
          backAt = turn.length;
          const where = `${at}, back to one row (${backAt} characters)`;
          if (turn.after.stacked) fail(`${where}: deleting changed the form to stacked`);
          if (!turn.after.focus) fail(`${where}: the field lost the focus`);
          clOneRowFindings(turn.after, where, fail);
          clKeysFindings(turn.before, turn.after, where, fail);
          clEndFindings(turn.after, where, fail, turn.before);
        }
        clDriftFindings(back, `${at}, deleting back`, fail);
        details.back = { at: backAt, drift: back.drift.length };
        if (backAt < 0) fail(`${at}: deleting back from the end never brought the one-row form back`);
        else if (stackAt && backAt >= stackAt - 1) fail(`${at}: the box went back to one row at ${backAt} characters, with no band below the ${stackAt} that stacked it`);
        if (backAt >= 0) {
          const again = await clTypeKeys(page, CL_TEXT.sentence.slice(backAt));
          clDriftFindings(again, `${at}, typed again`, fail);
          details.again = again.switches.map((x) => ({ length: x.length, stacked: x.after.stacked }));
          if (again.switches.length !== 1 || again.switches[0]!.length !== stackAt) fail(`${at}: typed again, the box changed form at ${again.switches.map((x) => x.length).join(", ") || "no character"}, not once at ${stackAt}`);
        }
        note = `stacks at ${stackAt} characters, one row again at ${backAt}`;

        // 4. Emptied: one row. A paste of several lines: stacked at once.
        await clearBox(page);
        const empty = await clSettled(page, false);
        if (empty.stacked) fail(`${at}: the emptied box is stacked`);
        await page.send("Input.insertText", { text: CL_TEXT.paste });
        await sleep(200);
        const paste = await clSettled(page, false);
        details.paste = clBrief(paste);
        if (paste.value !== CL_TEXT.paste) fail(`${at}: the paste reads ${JSON.stringify(paste.value)}`);
        clStackedFindings(paste, `${at}, a paste of three lines`, fail);
        clEndFindings(paste, `${at}, a paste of three lines`, fail, empty);

        // 5. The 4-line cap holds, the text scrolls inside, and the box never covers the conversation's last item.
        await clearBox(page);
        await page.send("Input.insertText", { text: CL_TEXT.long });
        await sleep(200);
        const cap = await clSettled(page, false);
        details.cap = { ...clBrief(cap), metrics: cap.metrics };
        clStackedFindings(cap, `${at}, at the cap`, fail);
        clCapFindings(cap, 4, `${at}, at the cap`, fail);
        clEndFindings(cap, `${at}, at the cap`, fail);
        clTopCutFindings(cap, `${at}, at the cap`, fail);
        // The paste stacked the box and wrapped again: the caret's line (at the end) is still the field's last.
        const cm = cap.metrics;
        if (cm && cm.top + cm.ch < cm.sh - cm.pb - 2) fail(`${at}: after the paste the field is not scrolled to the caret's line (scrollTop ${clPx(cm.top)} of ${clPx(cm.sh - cm.ch)})`, "layout");
        shot = await still(page, "cap");

        if (part === "full") {
          // 5b. The long draft key by key, through 2, 3 and 4 lines to the cap: the conversation keeps its end.
          await clearBox(page);
          const longKeys = await clTypeKeys(page, CL_TEXT.long);
          details.longKeys = { switches: longKeys.switches.map((x) => x.length), drift: longKeys.drift.length, end: clBrief(longKeys.end) };
          clDriftFindings(longKeys, `${at}, the long draft key by key`, fail);
          if (longKeys.switches.length !== 1) fail(`${at}: the long draft key by key changed the form ${longKeys.switches.length} time(s), not once`);
          clCapFindings(longKeys.end, 4, `${at}, the long draft key by key, at the cap`, fail);
          if (longKeys.end.sel && longKeys.end.value && longKeys.end.sel[0] !== longKeys.end.value.length) fail(`${at}: after the long draft the caret is at ${longKeys.end.sel[0]}, not at the end`);
          const lm = longKeys.end.metrics;
          // The caret's line in view: the browser reveals the line, not the field's bottom padding under it.
          if (lm && lm.top + lm.ch < lm.sh - lm.pb - 2) fail(`${at}: after the long draft the field is not scrolled to the caret's line (scrollTop ${clPx(lm.top)} of ${clPx(lm.sh - lm.ch)})`, "layout");
          clTopCutFindings(longKeys.end, `${at}, the long draft key by key, at the cap`, fail);
        }

        if (part === "full") {
          // 6. A caret in the middle stays where it types; a selection stays through a switch.
          const edge = CL_TEXT.sentence.slice(0, Math.max(1, stackAt - 1));
          await clearBox(page);
          await page.send("Input.insertText", { text: edge });
          await sleep(120);
          if ((await clRead(page)).stacked) fail(`${at}: one character before the switch, typed at once, the box is already stacked`);
          await page.evaluate(`(() => { const f = ${FIELD}; f.setSelectionRange(8, 8); return true; })()`);
          let mid: ClState | null = null;
          let xs = 0;
          for (; xs < 12 && !mid; ) {
            await page.send("Input.insertText", { text: "x" });
            xs++;
            await sleep(25);
            const s = await clRead(page);
            if (s.stacked) mid = await clSettled(page, false);
          }
          details.midCaret = mid ? { xs, sel: mid.sel, focus: mid.focus } : null;
          if (!mid) fail(`${at}: 12 characters typed in the middle never stacked the box`);
          else {
            if (!mid.focus) fail(`${at}, a caret in the middle: the switch took the focus`);
            if (!mid.sel || mid.sel[0] !== 8 + xs || mid.sel[1] !== 8 + xs) fail(`${at}, a caret in the middle: after the switch the caret is at ${JSON.stringify(mid.sel)}, not at ${8 + xs} where it typed`);
            if (mid.value !== `${edge.slice(0, 8)}${"x".repeat(xs)}${edge.slice(8)}`) fail(`${at}, a caret in the middle: the field holds ${JSON.stringify(mid.value)}`);
          }
          await clearBox(page);
          await page.send("Input.insertText", { text: edge });
          await sleep(120);
          await page.evaluate(`(() => { const f = ${FIELD}; f.setSelectionRange(4, 10); f.setRangeText(${JSON.stringify(CL_TEXT.sentence.slice(edge.length))}, f.value.length, f.value.length, "preserve"); f.dispatchEvent(new Event("input", { bubbles: true })); return true; })()`);
          await sleep(120);
          const sel = await clSettled(page, false);
          details.selection = { stacked: sel.stacked, sel: sel.sel, focus: sel.focus };
          if (!sel.stacked) fail(`${at}: the text added at the end did not stack the box`);
          if (!sel.sel || sel.sel[0] !== 4 || sel.sel[1] !== 10) fail(`${at}: the selection of 4 to 10 reads ${JSON.stringify(sel.sel)} after the switch`);
          if (!sel.focus) fail(`${at}: the switch with a selection took the focus`);

          // 7. One character deleted and typed again at the edge, six times: no switch.
          await clearBox(page);
          await page.send("Input.insertText", { text: edge });
          await sleep(80);
          await page.send("Input.insertText", { text: CL_TEXT.sentence[edge.length]! });
          await sleep(80);
          let form = (await clRead(page)).stacked;
          if (!form) fail(`${at}: the character that stacked the box key by key did not stack it after the rest typed at once`);
          let flips = 0;
          for (let k = 0; k < 6; k++) {
            await clBack(page);
            const s1 = (await clRead(page)).stacked;
            if (s1 !== form) flips++;
            form = s1;
            await page.send("Input.insertText", { text: CL_TEXT.sentence[edge.length]! });
            await sleep(25);
            const s2 = (await clRead(page)).stacked;
            if (s2 !== form) flips++;
            form = s2;
          }
          details.edgeFlips = flips;
          if (flips) fail(`${at}: one character deleted and typed again at the edge six times switched the form ${flips} time(s)`);

          // 8. A reader higher up in the chat: the switch does not move what they read.
          await emptyBox(page);
          const up = await page.evaluate<number>(`(() => { const s = document.querySelector('[data-testid="conversation"] .chat-scroll'); s.scrollTop = Math.max(0, s.scrollHeight - s.clientHeight - 400); return s.scrollHeight - s.clientHeight - s.scrollTop; })()`);
          await sleep(500);
          await focusField();
          const readBefore = await clRead(page);
          await page.send("Input.insertText", { text: CL_TEXT.long });
          await sleep(150);
          const readAfter = await clSettled(page, false);
          details.reader = { above: up, before: readBefore.first, after: readAfter.first, stacked: readAfter.stacked };
          if (up < 100) warnings.push({ code: "flow", text: `${at}: the conversation is too short to read higher up (${up} px)` });
          else if (!readAfter.stacked) fail(`${at}: the reader's long draft is not stacked`);
          else if (!readBefore.first || !readAfter.first || readBefore.first.id !== readAfter.first.id || Math.abs(readBefore.first.top - readAfter.first.top) > 1) fail(`${at}: a reader higher up lost their place: ${JSON.stringify(readBefore.first)} became ${JSON.stringify(readAfter.first)}`, "layout");
          await page.evaluate(`(() => { const s = document.querySelector('[data-testid="conversation"] .chat-scroll'); s.scrollTop = s.scrollHeight; return true; })()`);
          await sleep(500);

          // 9. The stand-in keyboard: the box rides it, stacks the same way, and keeps the conversation's end above it.
          await emptyBox(page);
          await focusField();
          await page.evaluate("window.__standInKeyboard(336)");
          await sleep(500);
          const kbStart = await clRead(page);
          if (!kbStart.riding) fail(`${at}: with the keyboard up and the focus in the field the box does not ride it`);
          await page.evaluate(CL_COVER_ON);
          const kbTyped = await clTypeKeys(page, CL_TEXT.sentence, true);
          const kbCover = await page.evaluate<ClCover | null>(CL_COVER_OFF);
          details.keyboard = { switches: kbTyped.switches.map((x) => ({ length: x.length, stacked: x.after.stacked, before: clBrief(x.before), after: clBrief(x.after) })), visual: kbStart.visual, drift: kbTyped.drift.length, cover: kbCover };
          clDriftFindings(kbTyped, `${at}, the keyboard up, the sentence key by key`, fail);
          clCoverFindings(kbCover, `${at}, the keyboard up, the sentence key by key`, fail);
          if (kbTyped.switches.length !== 1 || !kbTyped.switches[0]!.after.stacked) fail(`${at}, the keyboard up: typing the sentence changed the form ${kbTyped.switches.length} time(s), not once to stacked`);
          else {
            const { before, after } = kbTyped.switches[0]!;
            const where = `${at}, the keyboard up, at the switch`;
            if (!after.focus || !after.riding) fail(`${where}: the field lost the focus or the box left the keyboard (focus ${after.focus}, riding ${after.riding})`);
            clStackedFindings(after, where, fail);
            clKeysFindings(before, after, where, fail);
            clEndFindings(after, where, fail, before);
            if (after.slab && after.slab.bottom > after.visual + 0.5) fail(`${where}: the box's foot (${clPx(after.slab.bottom)}) is under the keyboard's top (${clPx(after.visual)})`, "layout");
          }
          await page.send("Input.insertText", { text: ` ${CL_TEXT.long}` });
          await sleep(150);
          const kbCap = await clSettled(page, true);
          details.keyboardCap = { ...clBrief(kbCap), metrics: kbCap.metrics };
          clCapFindings(kbCap, kbCap.visual < 400 ? 2 : 4, `${at}, the keyboard up, at the cap`, fail);
          clEndFindings(kbCap, `${at}, the keyboard up, at the cap`, fail);
          clTopCutFindings(kbCap, `${at}, the keyboard up, at the cap`, fail);
          if (kbCap.slab && kbCap.slab.bottom > kbCap.visual + 0.5) fail(`${at}, the keyboard up, at the cap: the box's foot is under the keyboard's top`, "layout");
          await still(page, "kb");
          await page.evaluate("window.__standInKeyboard(0)");
          await sleep(700);
        }

        if (part === "full" || theme === "dark") {
          // 10. Bash mode: the ! chip on the text's first line, Run in Send's place.
          await emptyBox(page);
          await focusField();
          await page.send("Input.insertText", { text: "!" });
          await sleep(120);
          await page.send("Input.insertText", { text: CL_TEXT.bash });
          await sleep(200);
          const bash = await clSettled(page, false);
          details.bash = { ...clBrief(bash), mode: bash.mode, chip: clBox(bash.chip) };
          if (bash.mode !== "bash") fail(`${at}: "!" did not pick Bash mode (${bash.mode})`);
          clStackedFindings(bash, `${at}, Bash mode`, fail);
          const m = bash.metrics;
          if (!bash.chip || !bash.field || !m) fail(`${at}, Bash mode: the ! chip does not show`, "shows");
          else if (bash.chip.top < bash.field.top - 1 || bash.chip.bottom > bash.field.top + m.pt + m.lh + 2) fail(`${at}, Bash mode: the ! chip (${clBox(bash.chip)}) is not on the text's first line (the field from ${clPx(bash.field.top)}, its line ${clPx(m.lh)} px)`, "layout");
          if (bash.key && one.key && Math.abs(bash.key.right - one.key.right) > 1) fail(`${at}, Bash mode: Run (${clBox(bash.key)}) is not where Send was (${clBox(one.key)})`, "layout");
          await still(page, "bash");
        }

        if (part === "full") {
          // 11. Bring back's quote (R130) lands stacked, its last line the field's last whole line.
          await emptyBox(page);
          await page.navigate(`${b.base}${chatPath}/btw`);
          await waitShown(page, ["chat", "conversation"], 8000);
          const opened = await bbUntil(page, (s) => s.place === "sheet" && s.brings > 0, 8000);
          const newest = (await scUntil(page, (s) => s.newest !== null, 3000)).s.newest;
          const answer = newest === SC_SIDE.ask ? SIDE_ANSWERS.ask : SIDE_KEPT.find((x) => x.question === newest)?.answer ?? "";
          if (!opened.ok || !answer) fail(`${at}: the side chat's sheet with a Bring back did not open (${opened.s.place}, ${opened.s.brings}, ${JSON.stringify(newest)})`);
          else {
            const want = `${bbQuote(answer)}\n\n`;
            await page.evaluate("document.activeElement && document.activeElement.blur && document.activeElement.blur()");
            await scPress(page, '[data-testid="side-chat"] [data-testid="side-newest"] [data-testid="side-bring-back"]');
            const after = await bbUntil(page, (s) => s.box === want && s.place === null, 4000);
            await sleep(300);
            const q = await clSettled(page, false);
            details.quote = { ...clBrief(q), metrics: q.metrics };
            if (!after.ok) fail(`${at}: after Bring back the box holds ${JSON.stringify(clip(after.s.box ?? "", 120))} with the side chat ${after.s.place ?? "closed"}`);
            clStackedFindings(q, `${at}, Bring back's quote`, fail);
            const cut = q.metrics ? bbFieldFindings(q.metrics) : "the field's measure could not be read";
            if (cut) fail(`${at}, Bring back's quote: ${cut}`);
            if (q.focus) fail(`${at}, Bring back's quote: the field took the focus, so the keyboard would come up`);
            await still(page, "quote");
          }
        }
      }
      noActing(wire, mark, `${at}: the flow`, fail);
      issueFindings(page.takeIssues(), failures);
      if (vp.touch) await page.evaluate("window.__standInKeyboard && window.__standInKeyboard(0)");
      const end = await emptyBox(page);
      if (end.value !== "" || end.mode !== "chat") warnings.push({ code: "flow", text: `${at}: the message box could not be emptied at the end (${JSON.stringify({ value: end.value, mode: end.mode })})` });
    });
  } catch (e) {
    failures.push({ code: "run", text: `the check could not run: ${(e as Error).message}` });
  }
  return finish({ kind: "flow", name: "composer-lines", route: "chat", scene: "side", size: sizeTag(vp), theme, path: chatPath, failures, warnings, note: `${look}: ${note}`, ms: Date.now() - t0, details, shot });
}

/** FIX-C1's composer-lines, on one side scene seed of its own (none with --base). */
async function composerLinesFlows(record: (r: CheckResult) => void, problems: string[]): Promise<void> {
  if (BASE) {
    console.log("ui-check: composer-lines boots a seed of its own (the side scene), so --base runs none of it");
    return;
  }
  const phone = CORE.find((v) => v.name === "phone") ?? null;
  const medium = CORE.find((v) => v.name === "medium") ?? null;
  const laptop = CORE.some((v) => v.name === "laptop") ? WIDE_LAPTOP : null;
  const runs: { vp: Viewport; theme: Theme; part: "full" | "core" | "wide" | "rotated" | "turn"; look: P2LookId }[] = [];
  if (phone && THEMES.includes("light")) runs.push({ vp: phone, theme: "light", part: "full", look: "glass" });
  if (phone && THEMES.includes("dark")) runs.push({ vp: phone, theme: "dark", part: "core", look: "glass" });
  if (phone && THEMES.includes("light")) for (const look of P2_LOOKS.filter((l) => l !== "glass")) runs.push({ vp: phone, theme: "light", part: "core", look });
  if (medium && THEMES.includes("light")) runs.push({ vp: medium, theme: "light", part: "wide", look: "glass" });
  for (const vp of extraAt("composer-lines")) runs.push({ vp, theme: THEMES.includes("light") ? "light" : THEMES[0]!, part: "wide", look: "glass" });
  if (laptop && THEMES.includes("light")) runs.push({ vp: laptop, theme: "light", part: "wide", look: "glass" });
  if (phone && THEMES.includes("light")) runs.push({ vp: CL_ROTATED, theme: "light", part: "rotated", look: "glass" });
  // Last: it sends a turn (from a laptop page), which the runs above must not see in the conversation.
  if (phone && THEMES.includes("light")) runs.push({ vp: phone, theme: "light", part: "turn", look: "glass" });
  if (!runs.length || cdp.closed) return;
  let b: Booted;
  try {
    b = await boot({ scene: "side", port: PORT, dist: built!, keep: KEEP, env: SERVER_ENV });
  } catch (e) {
    for (const r of runs) record(finish({ kind: "flow", name: "composer-lines", route: "chat", scene: "side", size: sizeTag(r.vp), theme: r.theme, path: `/c/${SC_CHAT}`, failures: [{ code: "seed", text: `the seed did not boot: ${(e as Error).message}` }], warnings: [], note: r.look, ms: 0, details: {} }));
    return;
  }
  live.add(b);
  try {
    for (const r of runs) {
      if (cdp.closed) break;
      record(await composerLinesRun(b, r.vp, r.theme, r.part, r.look));
    }
  } finally {
    const s = await b.stop();
    live.delete(b);
    if (s.code !== 0) problems.push(`scene side (composer-lines): the server exited with ${s.code}`);
    if (s.leftovers.length) problems.push(`scene side (composer-lines): ${s.leftovers.length} process(es) outlived the server and were ended by pid`);
  }
}

// U5 (FIX-U5 2, DESIGN-U5 8, 9 and 17): search-text, search inside the conversations' text. It boots one seed of the
// search-text scene of its own (the main scene plus seed/search-text.ts's three chats, each of the flow's words in one
// place) and runs at 1280x800 dark and light, at 1280x800 light in the other three looks, and at 390x844 with touch,
// dark and light:
// - a word that is only in a reply inside a finished turn's work (folded): typed in the chat's search pane (Ctrl+K) on
//   the laptop, in /search (the /chats bar's Search) on the phone; the Messages group comes last, after the pause, with
//   a row for the chat: its title, when, and the line with the word in bold in --text over the line's --dim (inherited
//   on the laptop's active row), one line cut with an ellipsis, the project in the row's name (and its tooltip on the
//   laptop); 44 px rows on touch;
// - a pick opens /c/<chat>/m/<message>?mark=<q>: the row shows, washed and in view, its folded turn open, and the
//   query's words marked in it (CSS.highlights "kitespan-match": every range in that row, none in a button, each the
//   word); Back returns to the search with the query and its Messages row;
// - a phrase in two messages of one chat and in an archived chat: the chat's second row is its line alone (named with
//   the chat's title first), and the archived chat's row says Archived; its pick opens the archived chat there;
// - who said it: the user's own line (the shared phrase's question, the long chat's first message) starts with "You: "
//   in the line's --dim (the row's colour on the laptop's active row), not bold; Claude's replies (the folded turn's,
//   the answer, the archived chat's) have no word before the line;
// - each Messages row's name as Chrome computes it (the Accessibility domain) is its parts with a comma between each
//   (title, project, Archived, when, line; a later row "<chat title>: <line>"; the user's line as "You: <line>"), and
//   the lines of one chat are at one pitch: on touch each is 44 px from the next;
// - a word that is only in a tool's output: once the Messages answer came, no Messages row;
// - a message older than the newest history page: the pick reads the older pages (Loading earlier messages…) until the
//   row is there, marked, with no 5.4 line on the way;
// - on the phone, the chat's own search page (the session menu's Search) has the group too;
// - nothing that acts goes out (D 8.4); screenshots of the group and of the landing, with the machine's name shown as
//   "this-machine".

const ST_WORDS = SEARCH_TEXT.words;
const ST_TITLES = SEARCH_TEXT.titles;
const ST_CHATS = SEARCH_TEXT.chats;

interface StRow {
  active: boolean;
  first: boolean;
  title: string | null;
  when: string | null;
  tag: string | null;
  /** The server's snippet as the line shows it, without the word before it. */
  snippet: string | null;
  /** The word before the line ("You: " for the user's own message), or null. */
  who: string | null;
  whoColor: string;
  whoWeight: string;
  hits: string[];
  name: string;
  tip: string | null;
  height: number;
  snippetColor: string;
  hitColor: string;
  hitWeight: string;
  rowColor: string;
  cut: boolean;
  overflow: string;
  oneLine: boolean;
  /** The vertical centre of the row's line (its snippet), in CSS px. */
  centre: number;
}
interface StState {
  path: string;
  open: boolean;
  value: string | null;
  placeholder: string | null;
  label: string | null;
  q: string | null;
  messages: string | null;
  groups: string[];
  rows: StRow[];
  wait: boolean;
  empty: string | null;
  tokens: { dim: string; text: string };
  wide: boolean;
}

/** In-page: the search pane that shows, its field, its list's state and its Messages rows. */
const ST_PROBE = `(() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden";
  const probe = (prop, v) => { const s = document.createElement("span"); s.style[prop] = v; document.body.appendChild(s); const c = getComputedStyle(s)[prop]; s.remove(); return c; };
  const root = [...document.querySelectorAll('[data-testid="search"]')].find(shown);
  const field = root ? root.querySelector('[data-testid="search-input"]') : null;
  const list = root ? root.querySelector('[data-testid="search-results"]') : null;
  const rows = list ? [...list.querySelectorAll('[role="option"][data-kind="messages"]')] : [];
  const empty = root ? root.querySelector('[data-testid="search-empty"], [data-testid="search-failed"]') : null;
  return {
    path: location.pathname + location.search,
    open: !!root,
    value: field ? field.value : null,
    placeholder: field ? field.getAttribute("placeholder") : null,
    label: field ? field.getAttribute("aria-label") : null,
    q: list ? list.getAttribute("data-q") : null,
    messages: list ? list.getAttribute("data-messages") : null,
    groups: list ? [...list.querySelectorAll('[role="group"]')].map((g) => g.getAttribute("data-kind")) : [],
    rows: rows.map((r) => {
      const sn = r.querySelector(".srch-snippet");
      const hit = sn ? sn.querySelector(".srch-hit") : null;
      const who = sn ? sn.querySelector(".srch-who") : null;
      const lh = sn ? parseFloat(getComputedStyle(sn).lineHeight) || 16 : 16;
      return {
        active: r.getAttribute("aria-selected") === "true",
        first: !r.classList.contains("srch-more"),
        title: r.querySelector(".srch-title") ? r.querySelector(".srch-title").textContent : null,
        when: r.querySelector(".srch-when") ? r.querySelector(".srch-when").textContent : null,
        tag: r.querySelector(".srch-tag") ? r.querySelector(".srch-tag").textContent : null,
        snippet: sn ? [...sn.childNodes].filter((n) => n !== who).map((n) => n.textContent).join("") : null,
        who: who ? who.textContent : null,
        whoColor: who ? getComputedStyle(who).color : "",
        whoWeight: who ? getComputedStyle(who).fontWeight : "",
        hits: sn ? [...sn.querySelectorAll(".srch-hit")].map((s) => s.textContent) : [],
        name: (r.getAttribute("aria-label") || r.textContent).replace(/\\s+/g, " ").trim(),
        tip: r.getAttribute("title"),
        height: Math.round(r.getBoundingClientRect().height),
        snippetColor: sn ? getComputedStyle(sn).color : "",
        hitColor: hit ? getComputedStyle(hit).color : "",
        hitWeight: hit ? getComputedStyle(hit).fontWeight : "",
        rowColor: getComputedStyle(r).color,
        cut: !!sn && sn.scrollWidth > sn.clientWidth + 1,
        overflow: sn ? getComputedStyle(sn).textOverflow : "",
        oneLine: !!sn && sn.getBoundingClientRect().height < lh * 1.5,
        centre: sn ? Math.round((sn.getBoundingClientRect().top + sn.getBoundingClientRect().height / 2) * 10) / 10 : 0,
      };
    }),
    wait: !!list && shown(list.querySelector(".srch-wait")),
    empty: empty && shown(empty) ? empty.textContent.trim() : null,
    tokens: { dim: probe("color", "var(--dim)"), text: probe("color", "var(--text)") },
    wide: document.scrollingElement.scrollWidth > innerWidth + 1,
  };
})()`;

interface StLand {
  path: string;
  row: boolean;
  shown: boolean;
  highlight: boolean;
  inView: boolean;
  inWork: boolean;
  workHidden: string | null;
  text: string;
  api: boolean;
  marks: { text: string; inRow: boolean; inButton: boolean }[] | null;
  markInView: boolean | null;
  others: number;
  notices: string[];
  wide: boolean;
}

/** In-page: the row a /m/ link names, its turn, and the marks of the highlight. */
const stLand = (id: string) => `(() => {
  const shown = (el) => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden";
  const row = document.querySelector('[data-item-id="' + CSS.escape(${JSON.stringify(id)}) + '"]');
  const sc = [...document.querySelectorAll(".chat-scroll")].find((e) => e.getClientRects().length > 0);
  const r = row ? row.getBoundingClientRect() : null;
  const s = sc ? sc.getBoundingClientRect() : null;
  const work = row ? row.closest("[data-turn-work]") : null;
  const api = !!(window.CSS && CSS.highlights);
  const h = api ? CSS.highlights.get("kitespan-match") : null;
  const ranges = h ? [...h] : [];
  const first = ranges.length ? ranges[0].getBoundingClientRect() : null;
  return {
    path: location.pathname + location.search,
    row: !!row,
    shown: shown(row) && !!r && r.height > 0,
    highlight: !!row && row.classList.contains("is-highlight"),
    inView: !!r && !!s && r.bottom > s.top && r.top < s.bottom,
    inWork: !!work,
    workHidden: work ? work.getAttribute("hidden") : null,
    text: row ? row.textContent.slice(0, 4000) : "",
    api,
    marks: h ? ranges.map((g) => { const c = g.commonAncestorContainer; const el = c.nodeType === 1 ? c : c.parentElement; return { text: g.toString(), inRow: !!row && row.contains(c), inButton: !!(el && el.closest("button")) }; }) : null,
    markInView: first && s ? first.top >= s.top && first.bottom <= s.bottom : null,
    others: [...document.querySelectorAll(".chat-item.is-highlight")].filter((e) => e !== row).length,
    notices: [...document.querySelectorAll('[data-testid="link-notice"]')].filter(shown).map((e) => e.textContent.trim()),
    wide: document.scrollingElement.scrollWidth > innerWidth + 1,
  };
})()`;

async function stUntil(page: Page, ok: (s: StState) => boolean, ms: number): Promise<{ ok: boolean; s: StState }> {
  const end = Date.now() + ms;
  let s = await page.evaluate<StState>(ST_PROBE);
  while (!ok(s) && Date.now() < end) {
    await sleep(100);
    s = await page.evaluate<StState>(ST_PROBE);
  }
  return { ok: ok(s), s };
}

async function stLandUntil(page: Page, id: string, ok: (l: StLand) => boolean, ms: number, seen?: Set<string>): Promise<{ ok: boolean; l: StLand }> {
  const end = Date.now() + ms;
  let l = await page.evaluate<StLand>(stLand(id));
  for (const n of l.notices) seen?.add(n);
  while (!ok(l) && Date.now() < end) {
    await sleep(80);
    l = await page.evaluate<StLand>(stLand(id));
    for (const n of l.notices) seen?.add(n);
  }
  return { ok: ok(l), l };
}

/** A still with the machine's name shown as "this-machine" and the pointer off the rows (no hover). */
async function stShot(page: Page, file: string) {
  if (!page.vp.touch) await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: 2, y: page.vp.height - 2 });
  await maskMachine(page);
  await page.evaluate(P2_DRAWN);
  await page.screenshot(file).catch(() => {});
}

/** The Messages row of this chat title (its first row), or undefined. */
const stRowOf = (s: StState, title: string) => s.rows.find((r) => r.first && r.title === title);

/** The checks of one Messages row as drawn (DESIGN-U5 8). */
function stRowChecks(s: StState, row: StRow, word: string, vp: Viewport, project: string, at: string, fail: (t: string) => void) {
  const name = JSON.stringify(row.title);
  if (!row.hits.some((h) => h.toLowerCase() === word)) fail(`${at}: the row ${name} marks ${JSON.stringify(row.hits)} in its line, not "${word}"`);
  if (!row.snippet || !row.snippet.toLowerCase().includes(word)) fail(`${at}: the row ${name}'s line ${JSON.stringify(row.snippet)} does not hold "${word}"`);
  if (!row.when || !/^(now|\d+ (min|h|d))$/.test(row.when)) fail(`${at}: the row ${name} shows when as ${JSON.stringify(row.when)}`);
  if (!row.name.includes(project)) fail(`${at}: the row ${name}'s name ${JSON.stringify(row.name)} does not hold its project ${project}`);
  if (!vp.touch && row.tip !== `${row.title}, ${project}`) fail(`${at}: the row ${name}'s tooltip is ${JSON.stringify(row.tip)}`);
  if (vp.touch && row.tip) fail(`${at}: the row ${name} has a tooltip on touch`);
  if (!row.oneLine) fail(`${at}: the row ${name}'s line takes more than one line`);
  if (row.cut && row.overflow !== "ellipsis") fail(`${at}: the row ${name}'s line is cut with ${row.overflow}, not an ellipsis`);
  if (Number(row.hitWeight) < 600) fail(`${at}: the row ${name}'s marked word is not bold (${row.hitWeight})`);
  if (vp.touch && row.height < 44) fail(`${at}: the row ${name} is ${row.height} px high on touch`);
  if (!vp.touch && row.active) {
    if (row.snippetColor !== row.rowColor || row.hitColor !== row.rowColor) fail(`${at}: on the active row ${name} the line (${row.snippetColor}) and its word (${row.hitColor}) do not take the row's colour (${row.rowColor})`);
  } else {
    if (row.snippetColor !== s.tokens.dim) fail(`${at}: the row ${name}'s line is ${row.snippetColor}, not --dim (${s.tokens.dim})`);
    if (row.hitColor !== s.tokens.text) fail(`${at}: the row ${name}'s marked word is ${row.hitColor}, not --text (${s.tokens.text})`);
  }
  stWhoChecks(s, row, vp, at, fail);
}

/**
 * Who said a row's line: "You: " before the user's own line, quiet (the line's --dim, or the row's colour on the
 * laptop's active row; not bold), and no word before a reply's. `by` null checks only the word's look.
 */
function stWhoChecks(s: StState, row: StRow, vp: Viewport, at: string, fail: (t: string) => void, by: "user" | "agent" | null = null) {
  const name = JSON.stringify(row.title ?? row.snippet?.slice(0, 30));
  if (by === "user" && row.who !== "You: ") fail(`${at}: the user's own line in ${name} starts with ${JSON.stringify(row.who)}, not "You: "`);
  if (by === "agent" && row.who !== null) fail(`${at}: Claude's reply in ${name} starts with ${JSON.stringify(row.who)}`);
  if (row.who === null) return;
  if (row.who !== "You: ") fail(`${at}: the word before ${name}'s line is ${JSON.stringify(row.who)}`);
  const want = !vp.touch && row.active ? row.rowColor : s.tokens.dim;
  if (row.whoColor !== want) fail(`${at}: "You: " in ${name} is ${row.whoColor}, not ${!vp.touch && row.active ? "the row's colour" : "--dim"} (${want})`);
  if (Number(row.whoWeight) >= 600) fail(`${at}: "You: " in ${name} is bold (${row.whoWeight})`);
}

/**
 * Chrome's own accessible names of the shown list's Messages rows, in order (what a screen reader says for each), read
 * with the Accessibility domain: the DOM tests have no layout, and the name of a row's parts depends on their boxes.
 */
async function stNames(page: Page): Promise<string[]> {
  const pick = (i: number) => `(() => { const shown = (el) => !!el && el.getClientRects().length > 0; const root = [...document.querySelectorAll('[data-testid="search"]')].find(shown); return root ? root.querySelectorAll('[data-testid="search-results"] [role="option"][data-kind="messages"]')[${i}] ?? null : null; })()`;
  const names: string[] = [];
  for (let i = 0; i < 40; i++) {
    const r = await page.send<{ result: { objectId?: string; subtype?: string } }>("Runtime.evaluate", { expression: pick(i), objectGroup: "st-names" });
    const objectId = r.result.objectId;
    if (!objectId || r.result.subtype === "null") break;
    const ax = await page.send<{ nodes: { ignored?: boolean; role?: { value?: string }; name?: { value?: string } }[] }>("Accessibility.getPartialAXTree", { objectId, fetchRelatives: false });
    const node = ax.nodes.find((n) => !n.ignored && n.role?.value === "option") ?? ax.nodes[0];
    names.push(node?.name?.value ?? "");
  }
  await page.send("Runtime.releaseObjectGroup", { objectGroup: "st-names" }).catch(() => {});
  return names;
}

/** What a Messages row's name says (DESIGN-U5 8): the first row's parts with a comma between each, a later row's "<title>: <line>". */
function stNameOf(row: StRow, chatTitle: string, project: string): string {
  const line = `${row.who ?? ""}${row.snippet ?? ""}`;
  if (!row.first) return `${chatTitle}: ${line}`;
  return [row.title, project, row.tag, row.when, line].filter((x) => !!x).join(", ");
}

/**
 * The names and, on touch, the line pitch of the rows: every row's computed name is its parts in order with a comma
 * between each (no space before a comma, and the time never runs into the line); inside one chat every line is one
 * row's height from the next on touch (44 px), and at one pitch on a laptop.
 */
async function stNameChecks(page: Page, s: StState, projects: Record<string, string>, vp: Viewport, at: string, fail: (t: string) => void, details: Record<string, unknown>, key: string) {
  const names = await stNames(page);
  details[key] = { names, centres: s.rows.map((r) => r.centre) };
  if (names.length !== s.rows.length) return fail(`${at}: ${names.length} computed names for ${s.rows.length} Messages rows`);
  let title = "";
  let chatLines: number[] = [];
  const pitches = (lines: number[]) => {
    if (lines.length < 2) return;
    const steps = lines.slice(1).map((c, k) => Math.round((c - lines[k]!) * 10) / 10);
    const want = vp.touch ? 44 : steps[0]!;
    if (steps.some((d) => Math.abs(d - want) > 1)) fail(`${at}: the lines of ${JSON.stringify(title)} are ${JSON.stringify(steps)} px apart, not one pitch${vp.touch ? " of 44 px" : ""}`);
  };
  s.rows.forEach((row, i) => {
    if (row.first) {
      pitches(chatLines);
      title = row.title ?? "";
      chatLines = [];
    }
    chatLines.push(row.centre);
    const got = names[i]!.replace(/\s+/g, " ").trim();
    const project = projects[title];
    if (project !== undefined) {
      const want = stNameOf(row, title, project);
      if (got !== want) fail(`${at}: the Messages row ${i + 1}'s computed name is ${JSON.stringify(got)}, not ${JSON.stringify(want)}`);
    } else if (/ ,/.test(got) || !got.startsWith(row.first ? `${title}, ` : `${title}: `)) fail(`${at}: the Messages row ${i + 1}'s computed name is ${JSON.stringify(got)}`);
  });
  pitches(chatLines);
}

/** Type a query into the pane's field (as one replacement on a later query), then wait for the Messages answer. */
async function stAsk(page: Page, q: string, fresh: boolean): Promise<{ ok: boolean; s: StState }> {
  if (fresh) await typeText(page, q);
  else await replaceQuery(page, q);
  return stUntil(page, (s) => s.value === q && s.q === q && (s.messages === "done" || s.messages === "failed"), 12_000);
}

/** Pick the row at the centre of the first Messages row that holds `needle` (a click, a tap on touch). */
async function stPick(page: Page, needle: string): Promise<boolean> {
  const at = await searchRowAt(page, needle, "messages");
  if (!at) return false;
  await page.press(at.x, at.y);
  return true;
}

/** After a pick: the /m/ path's message id, once the URL is a message route of `chat` with `mark`. */
async function stLanded(page: Page, chat: string, word: string, ms = 5000): Promise<string | null> {
  const end = Date.now() + ms;
  for (;;) {
    const path = await page.evaluate<string>("location.pathname + location.search");
    const m = new RegExp(`^/c/${chat}/m/([A-Za-z0-9_-]{1,64})\\?(?:.*&)?mark=${encodeURIComponent(word)}(?:&|$)`).exec(path);
    if (m) return m[1]!;
    if (Date.now() > end) return null;
    await sleep(60);
  }
}

/** The landing's checks: the row shown, washed, in view, its turn open, the word marked in it and nowhere else. */
function stLandChecks(l: StLand, word: string, at: string, fail: (t: string) => void, folded: boolean) {
  if (!l.shown) return fail(`${at}: the linked row does not show (${l.path})`);
  if (!l.highlight) fail(`${at}: the linked row has no wash`);
  if (!l.inView) fail(`${at}: the linked row is not in view`);
  if (folded && !l.inWork) fail(`${at}: the linked row is not in a turn's work (the seed's reply should be)`);
  if (l.inWork && l.workHidden !== null) fail(`${at}: the turn that holds the linked row stays folded (hidden ${l.workHidden})`);
  if (!l.api) return fail(`${at}: this Chrome has no CSS Custom Highlight API`);
  if (!l.marks?.length) return fail(`${at}: no word is marked in the linked row`);
  for (const m of l.marks) {
    if (!m.inRow) fail(`${at}: a mark (${JSON.stringify(m.text)}) is outside the linked row`);
    if (m.inButton) fail(`${at}: a mark is inside a button`);
    if (!m.text.toLowerCase().startsWith(word)) fail(`${at}: a mark holds ${JSON.stringify(m.text)}, not "${word}"`);
  }
  if (l.markInView === false) fail(`${at}: the first mark is not in view`);
  if (l.others) fail(`${at}: ${l.others} other row(s) are washed`);
  if (l.notices.length) fail(`${at}: the landing shows ${JSON.stringify(l.notices)}`);
  if (l.wide) fail(`${at}: the page scrolls sideways`);
}

async function searchTextRun(b: Booted, vp: Viewport, theme: Theme, look: P2LookId): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = { look };
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const tag = look === "glass" ? "" : `-${look}`;
  const at = `${vp.width}x${vp.height}${vp.touch ? " touch" : ""} ${theme}${look === "glass" ? "" : `, ${look}`}`;
  const full = look === "glass";
  let shot: string | undefined;
  const path = vp.touch ? "/chats" : `/c/${EX.chat}`;
  try {
    await withPage(vp, theme, async (page, wire) => {
      const since = wire.mark();
      // ---- open the search: Ctrl+K in the example chat on the laptop; the /chats bar's Search on the phone
      await page.navigate(b.base + path);
      await waitShown(page, vp.touch ? ["chat-list"] : ["chat", "conversation"]);
      if (look !== "glass") await wearLook(page, look, theme);
      if (vp.touch) {
        // The phone's /chats bar; v0.6 touch: the drawer's or the sidebar's head on the tablets (T-11).
        const search = await page.locate('[data-testid="topbar"] a[href="/search"], [data-testid="head-tools"] a[href="/search"]');
        if (!search) return fail(`${at}: neither the /chats bar nor the list head has Search`);
        await page.press(search.x, search.y);
        const opened = await stUntil(page, (s) => s.open && s.path.startsWith("/search"), 4000);
        if (!opened.ok) return fail(`${at}: Search did not open /search (${opened.s.path})`);
        if (opened.s.placeholder !== "Search chats and messages" || opened.s.label !== "Search chats and messages") fail(`${at}: /search's field reads ${JSON.stringify([opened.s.placeholder, opened.s.label])}`);
        const field = await page.locate('[data-testid="search-input"]');
        if (field) await page.press(field.x, field.y);
      } else {
        await searchKey(page);
        const opened = await stUntil(page, (s) => s.open, 4000);
        if (!opened.ok) return fail(`${at}: Ctrl+K did not open the chat's search pane`);
        if (opened.s.placeholder !== "Search" || opened.s.label !== "Search chats, messages, files and commands") fail(`${at}: the pane's field reads ${JSON.stringify([opened.s.placeholder, opened.s.label])}`);
      }

      // ---- a word only in a reply inside a folded turn's work
      const asked = await stAsk(page, ST_WORDS.reply, true);
      details.reply = asked.s;
      if (!asked.ok) return fail(`${at}: no Messages answer for "${ST_WORDS.reply}" (data-messages ${asked.s.messages}, q ${asked.s.q})`);
      if (asked.s.groups[asked.s.groups.length - 1] !== "messages") fail(`${at}: Messages is not the last group: ${JSON.stringify(asked.s.groups)}`);
      const row = stRowOf(asked.s, ST_TITLES.cap);
      if (!row) return fail(`${at}: no Messages row for ${JSON.stringify(ST_TITLES.cap)}: ${JSON.stringify(asked.s.rows.map((r) => r.title))}`);
      stRowChecks(asked.s, row, ST_WORDS.reply, vp, "kitespan", at, fail);
      stWhoChecks(asked.s, row, vp, `${at}, the folded turn's reply`, fail, "agent");
      await stNameChecks(page, asked.s, { [ST_TITLES.cap]: "kitespan", [ST_TITLES.tiles]: "scratch" }, vp, at, fail, details, "replyNames");
      if (asked.s.wide) fail(`${at}: the page scrolls sideways with the Messages group`);

      // ---- the pick: the chat at that message, its folded turn open, the word marked
      if (!(await stPick(page, ST_TITLES.cap))) return fail(`${at}: the Messages row could not be found to pick`);
      const id = await stLanded(page, ST_CHATS.cap, ST_WORDS.reply);
      if (!id) return fail(`${at}: the pick did not open /c/<chat>/m/<message>?mark=${ST_WORDS.reply} (${await page.evaluate<string>("location.pathname + location.search")})`);
      if (id !== SEARCH_TEXT_ROWS.reply) fail(`${at}: the pick opened the message ${id}, not the reply ${SEARCH_TEXT_ROWS.reply}`);
      const land = await stLandUntil(page, id, (l) => l.shown && !!l.marks?.length, 6000);
      details.landing = { ...land.l, text: land.l.text.slice(0, 200) };
      stLandChecks(land.l, ST_WORDS.reply, `${at}, the reply in the folded turn`, fail, true);
      await page.evaluate(TRANSITIONS_DONE);
      shot = shotName("search-text", "search-text", vp, theme, `landing${tag}`);
      await stShot(page, shot);

      // ---- Back returns to the search, with its query and its row
      await goBack(page);
      const back = await stUntil(page, (s) => s.open && s.value === ST_WORDS.reply && !!stRowOf(s, ST_TITLES.cap), 5000);
      details.back = { path: back.s.path, value: back.s.value, rows: back.s.rows.length };
      if (!back.ok) fail(`${at}: Back did not return to the search with "${ST_WORDS.reply}" and its Messages row (${back.s.path}, value ${JSON.stringify(back.s.value)}, ${back.s.rows.length} rows)`);

      // ---- a phrase in two messages of one chat and in an archived chat: a follow-up row, and Archived
      const shared = await stAsk(page, ST_WORDS.shared, false);
      details.shared = shared.s.rows;
      const capRows = shared.s.rows.filter((r) => r.first && r.title === ST_TITLES.cap);
      const capAt = shared.s.rows.findIndex((r) => r.first && r.title === ST_TITLES.cap);
      const more = capAt >= 0 ? shared.s.rows[capAt + 1] : undefined;
      if (!capRows.length) fail(`${at}: no Messages row for ${JSON.stringify(ST_TITLES.cap)} with "${ST_WORDS.shared}"`);
      else if (!more || more.first) fail(`${at}: ${JSON.stringify(ST_TITLES.cap)}'s second match is not a row of its own under it`);
      else {
        if (!more.name.startsWith(`${ST_TITLES.cap}: `)) fail(`${at}: the follow-up row's name starts ${JSON.stringify(more.name.slice(0, 40))}, not the chat's title`);
        if (more.title !== null || more.when !== null) fail(`${at}: the follow-up row shows a title or a time`);
        if (vp.touch && more.height < 44) fail(`${at}: the follow-up row is ${more.height} px high on touch`);
        if (!vp.touch && more.height > (capRows[0]?.height ?? 0)) fail(`${at}: the follow-up row (${more.height} px) is taller than its chat's first row`);
        // The answer (Claude's) and the question (the user's) share the phrase: only the question says "You: ".
        stWhoChecks(shared.s, capRows[0]!, vp, `${at}, the answer`, fail, "agent");
        stWhoChecks(shared.s, more, vp, `${at}, the question`, fail, "user");
        if (!more.oneLine) fail(`${at}: the user's line with "You: " takes more than one line`);
      }
      await stNameChecks(page, shared.s, { [ST_TITLES.cap]: "kitespan", [ST_TITLES.tiles]: "scratch" }, vp, at, fail, details, "sharedNames");
      for (const r of shared.s.rows) {
        const marked = r.hits.join(" ").toLowerCase();
        if (!marked.includes("memory") || !marked.includes("cap")) fail(`${at}: a row marks ${JSON.stringify(r.hits)} for "${ST_WORDS.shared}"`);
      }
      const tiles = stRowOf(shared.s, ST_TITLES.tiles);
      if (!tiles) fail(`${at}: no Messages row for the archived chat ${JSON.stringify(ST_TITLES.tiles)}`);
      else {
        if (tiles.tag !== "Archived") fail(`${at}: the archived chat's row says ${JSON.stringify(tiles.tag)}, not Archived`);
        stWhoChecks(shared.s, tiles, vp, `${at}, the archived chat's reply`, fail, "agent");
      }
      await stShot(page, shotName("search-text", "search-text", vp, theme, `group${tag}`));
      if (!full) return;

      // ---- the archived chat's own word: its pick opens the archived chat at the message
      const arch = await stAsk(page, ST_WORDS.archived, false);
      const archRow = stRowOf(arch.s, ST_TITLES.tiles);
      if (!archRow) fail(`${at}: no Messages row for the archived chat with "${ST_WORDS.archived}": ${JSON.stringify(arch.s.rows.map((r) => r.title))}`);
      else {
        stRowChecks(arch.s, archRow, ST_WORDS.archived, vp, "scratch", `${at}, archived`, fail);
        if (await stPick(page, ST_TITLES.tiles)) {
          const aid = await stLanded(page, ST_CHATS.tiles, ST_WORDS.archived);
          if (aid !== SEARCH_TEXT_ROWS.archived) fail(`${at}: the archived row's pick opened ${JSON.stringify(aid)}, not ${SEARCH_TEXT_ROWS.archived}`);
          if (aid) {
            const al = await stLandUntil(page, aid, (l) => l.shown && !!l.marks?.length, 6000);
            stLandChecks(al.l, ST_WORDS.archived, `${at}, the archived chat`, fail, false);
            await stShot(page, shotName("search-text", "search-text", vp, theme, "archived"));
          }
          await goBack(page);
          await stUntil(page, (s) => s.open && s.value === ST_WORDS.archived, 5000);
        } else fail(`${at}: the archived row could not be picked`);
      }

      // ---- a word only in a tool's output: no Messages row once the answer came
      const tool = await stAsk(page, ST_WORDS.tool, false);
      details.tool = { messages: tool.s.messages, rows: tool.s.rows.map((r) => r.title) };
      if (!tool.ok) fail(`${at}: no Messages answer for "${ST_WORDS.tool}" (${tool.s.messages})`);
      else if (tool.s.rows.length) fail(`${at}: "${ST_WORDS.tool}" (only in a tool's output) found Messages rows: ${JSON.stringify(tool.s.rows.map((r) => r.title))}`);

      // ---- a chat with three rows (the main scene's "upload" chat): every line at one pitch, and every row's name
      const three = await stAsk(page, "upload", false);
      const perChat: number[] = [];
      for (const r of three.s.rows) {
        if (r.first || !perChat.length) perChat.push(1);
        else perChat[perChat.length - 1]!++;
      }
      const widest = Math.max(0, ...perChat);
      details.three = { messages: three.s.messages, rows: three.s.rows.length, widest };
      if (!three.ok) fail(`${at}: no Messages answer for "upload" (${three.s.messages})`);
      else if (widest < 3) warnings.push({ code: "flow", text: `${at}: no chat has three Messages rows for "upload", so the pitch of three lines was not checked` });
      await stNameChecks(page, three.s, { "Fix the flaky upload test": "kitespan", "Pick the test layers": "kitespan" }, vp, at, fail, details, "threeNames");

      // ---- a message older than the newest history page
      const old = await stAsk(page, ST_WORDS.old, false);
      const oldRow = stRowOf(old.s, ST_TITLES.long);
      if (!oldRow) fail(`${at}: no Messages row for the long chat with "${ST_WORDS.old}": ${JSON.stringify(old.s.rows.map((r) => r.title))}`);
      else stWhoChecks(old.s, oldRow, vp, `${at}, the long chat's first message`, fail, "user");
      if (oldRow && (await stPick(page, ST_TITLES.long))) {
        const oid = await stLanded(page, ST_CHATS.long, ST_WORDS.old);
        if (oid !== SEARCH_TEXT_ROWS.old) fail(`${at}: the long chat's pick opened ${JSON.stringify(oid)}, not ${SEARCH_TEXT_ROWS.old}`);
        if (oid) {
          const seen = new Set<string>();
          const t1 = Date.now();
          const ol = await stLandUntil(page, oid, (l) => l.shown && !!l.marks?.length, 20_000, seen);
          details.older = { ms: Date.now() - t1, seen: [...seen] };
          if (seen.has("That message is not in this chat.")) fail(`${at}: the older message's link said "That message is not in this chat." on its way`);
          stLandChecks(ol.l, ST_WORDS.old, `${at}, the message in an older page`, fail, false);
          await stShot(page, shotName("search-text", "search-text", vp, theme, "older"));
        }
        await goBack(page);
      }

      // ---- the phone: the chat's own search page has the group too
      if (vp.touch) {
        await page.navigate(`${b.base}/c/${EX.chat}/search?q=${ST_WORDS.reply}`);
        const inChat = await stUntil(page, (s) => s.open && s.messages === "done" && !!stRowOf(s, ST_TITLES.cap), 10_000);
        if (!inChat.ok) fail(`${at}: the chat's search page has no Messages row for "${ST_WORDS.reply}"`);
        else stRowChecks(inChat.s, stRowOf(inChat.s, ST_TITLES.cap)!, ST_WORDS.reply, vp, "kitespan", `${at}, the chat's search page`, fail);
        await stShot(page, shotName("search-text", "search-text", vp, theme, "in-chat"));
      }
      quietFindings(wire, since, await recorder(page), failures, `${at}: `);
      issueFindings(page.issues, failures, `${at}: `);
    });
  } catch (e) {
    fail(`${at}: ${(e as Error).message}`, "run");
  }
  return finish({ kind: "flow", name: "search-text", route: "search", scene: "search-text", size: sizeTag(vp), theme, path, failures, warnings, note: look === "glass" ? "" : `the ${look} look`, ms: Date.now() - t0, details, shot });
}

/** U5's runs on one seed of the search-text scene (none with --base): the laptop's, each look's, then the phone's. */
async function searchTextFlows(record: (r: CheckResult) => void, problems: string[]): Promise<void> {
  if (BASE) {
    console.log("ui-check: search-text boots a seed of its own (the search-text scene), so --base runs none of it");
    return;
  }
  const laptop = CORE.some((v) => v.name === "laptop") ? WIDE_LAPTOP : null;
  const phone = CORE.find((v) => v.name === "phone") ?? null;
  const runs: { vp: Viewport; theme: Theme; look: P2LookId }[] = [];
  if (laptop) for (const theme of THEMES) runs.push({ vp: laptop, theme, look: "glass" });
  if (laptop && THEMES.includes("light")) for (const look of P2_LOOKS.filter((l) => l !== "glass")) runs.push({ vp: laptop, theme: "light", look });
  if (phone) for (const theme of THEMES) runs.push({ vp: phone, theme, look: "glass" });
  for (const vp of extraAt("search-text")) runs.push({ vp, theme: THEMES[0]!, look: "glass" });
  if (!runs.length || cdp.closed) return;
  let b: Booted;
  try {
    b = await boot({ scene: "search-text", port: PORT, dist: built!, keep: KEEP, env: SERVER_ENV });
  } catch (e) {
    for (const r of runs) record(finish({ kind: "flow", name: "search-text", route: "search", scene: "search-text", size: sizeTag(r.vp), theme: r.theme, path: "/search", failures: [{ code: "seed", text: `the seed did not boot: ${(e as Error).message}` }], warnings: [], note: "", ms: 0, details: {} }));
    return;
  }
  live.add(b);
  try {
    for (const r of runs) {
      if (cdp.closed) break;
      record(await searchTextRun(b, r.vp, r.theme, r.look));
    }
  } finally {
    const s = await b.stop();
    live.delete(b);
    if (s.code !== 0) problems.push(`scene search-text (search-text): the server exited with ${s.code}`);
    if (s.leftovers.length) problems.push(`scene search-text (search-text): ${s.leftovers.length} process(es) outlived the server and were ended by pid`);
  }
}

// ---------------------------------------------------------------------------------------------------------------
// FIX-Q1 3, send-follow: your own send goes to the end (web/chat/ownSend.ts), on a main scene seed of its own with the
// long chat's turns (trSetup). A send from a pinned route follows the end while its reply streams in (a paced reply of
// 2,400 characters, so the chat grows below the linked row), Jump to latest does not show, the linked row's highlight
// and the query's marks go, and a route that only names a row becomes the chat's own by replace (no new history
// entry), so Back returns to where the link came from: a search hit's /c/<chat>/m/<message>?mark= link opened after
// Home (1280x800) and after /chats (390x844); a turn rail's jump (1280x800; Back to the chat's entry); a changes route
// (/c/<chat>/changes/<turn>) opened after Home on the laptop, where the URL stays with the side panel's list, and after
// /chats on the phone, where it is the chat at the turn's card line. And a reader who scrolled far up and sends
// follows the end too (1280x800). Before FIX-Q1 the view stayed at the linked row and Jump to latest showed. Q1 review:
// the rail's jump is opened after Home and its send goes back to the chat's entry (one entry back, so the Back after it
// reaches Home, never an entry that looks the same); a card route whose card was answered (the example chat's
// ANSWERED_CARD, after Home on the laptop) shows its record marked and 5.4's line, and the send replaces it with the
// chat's own, the line and the mark gone; every Back after a send changes the URL.

const SF_CHAT = TR_CHAT;
/** The word that the search hit's link marks in the long chat's first added message. */
const SF_WORD = "heading";
const sfText = (n: number) => `Go on from here (send-follow ${n}). ${pacedPrompt(2400, 24, 40)}`;

interface SfState {
  path: string;
  gap: number | null;
  jump: boolean;
  highlight: string[];
  marks: number;
  working: boolean;
  panel: boolean;
  lastUser: string | null;
  users: { id: string; text: string }[];
  rail: { x: number; y: number }[];
  line: string | null;
}

/** In-page: the scroll's gap from the end, Jump to latest, the marked rows and words, the reply's working mark, the side panel's list. */
const SF_PROBE = `(() => {
  const vis = (el) => !!el && el.getClientRects().length > 0;
  const sc = [...document.querySelectorAll(".chat-scroll")].find(vis);
  const col = sc ? sc.querySelector(".chat-col") : null;
  const users = col ? [...col.querySelectorAll(".chat-item-user[data-item-id]")].map((u) => ({ id: u.getAttribute("data-item-id"), text: ((u.querySelector(".chat-bubble") || {}).textContent || "").trim() })) : [];
  const hl = typeof CSS !== "undefined" && CSS.highlights ? CSS.highlights.get("kitespan-match") : null;
  const nav = [...document.querySelectorAll("nav.chat-rail")].find(vis);
  return {
    path: location.pathname + location.search,
    gap: sc ? Math.round(sc.scrollHeight - sc.scrollTop - sc.clientHeight) : null,
    jump: [...document.querySelectorAll(".chat-jump")].some(vis),
    highlight: col ? [...col.querySelectorAll(".is-highlight")].map((e) => e.getAttribute("data-item-id") || e.className) : [],
    marks: hl ? hl.size : 0,
    working: col ? [...col.querySelectorAll(".chat-working")].some(vis) : false,
    panel: [...document.querySelectorAll('[data-testid="changes-list-row"]')].some(vis),
    lastUser: users.length ? users[users.length - 1].text : null,
    users,
    rail: nav ? [...nav.querySelectorAll("a.chat-rail-mark")].map((a) => { const r = a.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 }; }) : [],
    line: (() => { const n = [...document.querySelectorAll('[data-testid="link-notice"]')].find(vis); return n ? (n.textContent || "").trim() : null; })(),
  };
})()`;

async function sfUntil(page: Page, ok: (s: SfState) => boolean, ms: number): Promise<{ ok: boolean; s: SfState }> {
  const end = Date.now() + ms;
  let s = await page.evaluate<SfState>(SF_PROBE);
  while (!ok(s) && Date.now() < end) {
    await sleep(100);
    s = await page.evaluate<SfState>(SF_PROBE);
  }
  return { ok: ok(s), s };
}

type SfKind = "hit" | "rail" | "changes" | "card" | "up";
const SF_NOTE: Record<SfKind, string> = {
  hit: "a send from a search hit's /m/ link with its marks follows the end; the chat's own URL by replace; Back to where the link came from",
  rail: "a send after a turn rail's jump follows the end; back to the chat's own entry (no dead entry); Back to Home",
  changes: "a send from a changes route follows the end",
  card: "a send from a card route whose card was answered follows the end; its record's mark and 5.4's line go; the chat's own URL by replace; Back to Home",
  up: "a send from a reader scrolled far up follows the end",
};
/** 5.4's line on the answered card's route (DESIGN 5.4; seed/scenes.ts permission-answered). */
const SF_ANSWERED = "That request was already answered.";

async function sendFollowRun(b: Booted, vp: Viewport, theme: Theme, kind: SfKind, n: number): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = { kind };
  const fail = (text: string, code = "flow") => void failures.push({ code, text });
  const at = `${vp.width}x${vp.height}${vp.touch ? " touch" : ""} ${theme}, ${kind}`;
  const changes = ROUTE.changesTurn!.example;
  const card = `/c/${EX.chat}/permission/${ANSWERED_CARD}`;
  const chat = kind === "changes" || kind === "card" ? EX.chat : SF_CHAT;
  const chatPath = `/c/${chat}`;
  // Where Back after the send goes: the page the link was opened from (the chat's own entry is the one the rail's
  // jump left, and the send goes back to it, so Back goes on to Home).
  const from = kind === "up" ? chatPath : vp.touch ? "/chats" : "/";
  // The URL after the send: the chat's own, but for the laptop's changes route, which is the side panel's view.
  // The phone has no changes view (row 115): its changes route is the chat at the card's line; the tablets (v0.6
  // touch) show the view as the laptop does.
  const phone = vp.name === "phone";
  const leaves = !(kind === "changes" && !phone);
  let path = kind === "changes" ? changes : kind === "card" ? card : chatPath;
  let shot: string | undefined;
  try {
    await withPage(vp, theme, async (page) => {
      const probe = () => page.evaluate<SfState>(SF_PROBE);
      const drawn = () => page.evaluate(P2_DRAWN);
      // ---- the pinned place
      if (kind === "hit") {
        await page.navigate(b.base + chatPath);
        await waitShown(page, ["chat", "conversation"]);
        const all = await sfUntil(page, (s) => s.users.length >= TR_TOTAL, 8000);
        const u = all.s.users.find((x) => x.text.startsWith(TR_TURNS[0]!));
        if (!u) return fail(`${at}: the long chat shows no message "${TR_TURNS[0]}" to link to`);
        await page.navigate(b.base + from);
        await waitShown(page, [vp.touch ? "chat-list" : "home"]);
        path = `${chatPath}/m/${u.id}?mark=${SF_WORD}`;
        await page.navigate(b.base + path);
        await waitShown(page, ["chat", "conversation"]);
        const landed = await sfUntil(page, (s) => s.highlight.includes(u.id) && s.marks > 0, 6000);
        if (!landed.ok) return fail(`${at}: the link did not land marked at its message (highlight ${JSON.stringify(landed.s.highlight)}, ${landed.s.marks} marks)`);
      } else if (kind === "rail") {
        await page.navigate(b.base + from);
        await waitShown(page, [vp.touch ? "chat-list" : "home"]);
        await page.navigate(b.base + chatPath);
        await waitShown(page, ["chat", "conversation"]);
        const ready = await sfUntil(page, (s) => s.rail.length >= TR_TOTAL, 8000);
        const m = ready.s.rail[TR_JUMP];
        if (!m) return fail(`${at}: the long chat shows no turn rail with mark ${TR_JUMP} (${ready.s.rail.length} marks)`);
        await page.press(Math.round(m.x), Math.round(m.y));
        await page.settle();
        const landed = await sfUntil(page, (s) => s.path.startsWith(`${chatPath}/m/`) && s.highlight.length > 0, 4000);
        if (!landed.ok) return fail(`${at}: the rail's mark did not jump (${landed.s.path})`);
        path = landed.s.path;
      } else if (kind === "changes") {
        await page.navigate(b.base + from);
        await waitShown(page, [vp.touch ? "chat-list" : "home"]);
        await page.navigate(b.base + changes);
        await waitShown(page, ["chat", "conversation"]);
        const landed = await sfUntil(page, (s) => (phone ? s.highlight.length > 0 : s.panel), 6000);
        if (!landed.ok) return fail(`${at}: the changes route did not land (${phone ? `no card line marked: ${JSON.stringify(landed.s.highlight)}` : "no list in the side panel"})`);
      } else if (kind === "card") {
        await page.navigate(b.base + from);
        await waitShown(page, [vp.touch ? "chat-list" : "home"]);
        await page.navigate(b.base + card);
        await waitShown(page, ["chat", "conversation"]);
        const landed = await sfUntil(page, (s) => s.line === SF_ANSWERED && s.highlight.length > 0, 6000);
        if (!landed.ok) return fail(`${at}: the answered card's route did not show its record marked with its line (line ${JSON.stringify(landed.s.line)}, highlight ${JSON.stringify(landed.s.highlight)})`);
      } else {
        await page.navigate(b.base + chatPath);
        await waitShown(page, ["chat", "conversation"]);
        await sfUntil(page, (s) => s.users.length >= TR_TOTAL, 8000);
        const box = await page.locate(".chat-scroll");
        if (!box) return fail(`${at}: no conversation to scroll`);
        for (let i = 0; i < 6; i++) {
          await page.send("Input.dispatchMouseEvent", { type: "mouseWheel", x: Math.round(box.x), y: Math.round(box.y), deltaX: 0, deltaY: -600 });
          await sleep(60);
        }
        await sleep(300);
        const up = await probe();
        if ((up.gap ?? 0) < 1500) return fail(`${at}: the wheel took the reader only ${up.gap} px above the end`);
      }
      await drawn();
      const before = await probe();
      const h0 = await page.history();
      details.before = { path: before.path, gap: before.gap, jump: before.jump, highlight: before.highlight, marks: before.marks, line: before.line, history: h0.entries.length, at: h0.currentIndex };
      await maskMachine(page);
      await page.screenshot(shotName("main", "send-follow", vp, theme, `${kind}-before`)).catch(() => {});

      // ---- the send, and its reply streaming in below
      if (!(await sendFromBox(page, sfText(n)))) return fail(`${at}: no message box with Send`);
      const mine = `send-follow ${n}`;
      const started = await sfUntil(page, (s) => s.working && !!s.lastUser?.includes(mine), 10_000);
      if (!started.ok) return fail(`${at}: the reply to the send did not start (the last message ${JSON.stringify(started.s.lastUser)})`);
      let worst = 0;
      let s = started.s;
      const end = Date.now() + 15_000;
      while (s.working && Date.now() < end) {
        worst = Math.max(worst, s.gap ?? 0);
        await sleep(120);
        s = await probe();
      }
      await sleep(700);
      await drawn();
      const after = await probe();
      const h1 = await page.history();
      details.after = { path: after.path, gap: after.gap, worstGapWhileStreaming: worst, jump: after.jump, highlight: after.highlight, marks: after.marks, line: after.line, panel: after.panel, history: h1.entries.length, at: h1.currentIndex };
      shot = shotName("main", "send-follow", vp, theme, `${kind}-after`);
      await maskMachine(page);
      await page.screenshot(shot).catch(() => {});
      if (s.working) fail(`${at}: the reply was still streaming after 15 s`);
      if (after.gap === null || after.gap >= NEAR_END) fail(`${at}: after the send the view is ${after.gap} px above the end, not at it (it was ${before.gap} px above before)`);
      if (worst > 300) fail(`${at}: while the reply streamed the view fell ${worst} px behind the end`);
      if (after.jump) fail(`${at}: Jump to latest shows after the send`);
      if (after.highlight.length) fail(`${at}: after the send the linked row is still marked (${clipList(after.highlight)})`);
      if (after.marks) fail(`${at}: after the send the query's words are still marked (${after.marks})`);
      if (after.line) fail(`${at}: after the send 5.4's line still shows ("${after.line}")`);
      const want = leaves ? chatPath : path;
      if (!sameUrl(after.path, want)) fail(`${at}: after the send the URL is ${after.path}, not ${want}`);
      // The rail's jump pushed its entry from the chat's own: the send goes back to that one (no entry like it stays).
      const backBy = kind === "rail" ? 1 : 0;
      if (h1.entries.length !== h0.entries.length || h1.currentIndex !== h0.currentIndex - backBy)
        fail(`${at}: the send made ${h1.entries.length - h0.entries.length} history entries (at ${h0.currentIndex} then ${h1.currentIndex}), not ${backBy ? "one step back" : "a replace"}`);
      if (kind === "changes" && !phone && !after.panel) fail(`${at}: after the send the side panel no longer shows the turn's list`);
      stateFindings(await page.probe(), vp, failures);
      issueFindings(page.takeIssues(), failures);

      // ---- Back returns to where the link came from
      if (kind !== "up") {
        await goBack(page);
        await page.settle();
        const back = await probe();
        details.back = back.path;
        if (sameUrl(back.path, after.path)) fail(`${at}: Back after the send stayed on ${back.path} (an entry that looks the same)`);
        if (!samePath(back.path, from)) fail(`${at}: Back after the send went to ${back.path}, not ${from}`);
      }
    });
  } catch (e) {
    fail(`the check could not run: ${(e as Error).message}`, "run");
  }
  return finish({ kind: "flow", name: "send-follow", route: "message", scene: "main", size: sizeTag(vp), theme, path, failures, warnings, note: SF_NOTE[kind], shot, ms: Date.now() - t0, details });
}

/** px: as near the end as the view's follow rule's own (web/chat/follow.ts NEAR_BOTTOM). */
const NEAR_END = 90;

async function sendFollowFlows(record: (r: CheckResult) => void, problems: string[]): Promise<void> {
  if (BASE) {
    console.log("ui-check: send-follow boots a seed of its own (the main scene), so --base runs none of it");
    return;
  }
  const theme: Theme = THEMES.includes("light") ? "light" : THEMES[0]!;
  const runs: { vp: Viewport; kind: SfKind }[] = [];
  if (CORE.some((v) => v.name === "laptop")) for (const kind of ["hit", "rail", "changes", "card", "up"] as const) runs.push({ vp: WIDE_LAPTOP, kind });
  const phone = CORE.find((v) => v.name === "phone");
  if (phone) for (const kind of ["hit", "changes"] as const) runs.push({ vp: phone, kind });
  // v0.6 touch: under 800 px of a tablet the changes view is a layer over the chat and its box (T-17), so no send goes
  // out from a changes route there: 626 runs the hit only.
  for (const vp of extraAt("send-follow")) for (const kind of vp.name === "medium" && vp.width < 800 ? (["hit"] as const) : (["hit", "changes"] as const)) runs.push({ vp, kind });
  if (!runs.length || cdp.closed) return;
  const failed = (msg: string) => {
    for (const r of runs) record(finish({ kind: "flow", name: "send-follow", route: "message", scene: "main", size: sizeTag(r.vp), theme, path: `/c/${SF_CHAT}`, failures: [{ code: "seed", text: msg }], warnings: [], note: SF_NOTE[r.kind], ms: 0, details: {} }));
  };
  let b: Booted;
  try {
    b = await boot({ scene: "main", port: PORT, dist: built!, keep: KEEP, env: SERVER_ENV });
  } catch (e) {
    failed(`the seed did not boot: ${(e as Error).message}`);
    return;
  }
  live.add(b);
  try {
    try {
      await trSetup({ base: b.base, scene: null, booted: b });
    } catch (e) {
      failed(`the long chat's turns did not run: ${(e as Error).message}`);
      return;
    }
    let n = 0;
    for (const r of runs) {
      if (cdp.closed) break;
      record(await sendFollowRun(b, r.vp, theme, r.kind, ++n));
    }
  } finally {
    const r = await b.stop();
    live.delete(b);
    if (r.code !== 0) problems.push(`scene main (send-follow): the server exited with ${r.code}`);
    if (r.leftovers.length) problems.push(`scene main (send-follow): ${r.leftovers.length} process(es) outlived the server and were ended by pid`);
  }
}

// ---------------------------------------------------------------------------------------------------------------
// Iteration 7 (DESIGN-B1 7.4, page side): the browser pane on a main scene seed of its own, with a browser.json in the
// seed's config folder (Chrome for Testing, a free port from 9341 to 9349, never 9340, loopbackOnly) and the local test
// site on 127.0.0.1 (scripts/lib/browser-flows.ts has the steps). The shared browser that kitespan starts is stopped
// through kitespan's own Stop at the end, and kitespan's quit stops it too (S4). browser-pane's first run starts the
// browser from its off state; without browser-pane the seed starts it at boot. browser-restart runs last: its restart
// leaves a successor of the boot on the port, which the harness's stop ends.

const BROWSER_LOOKS = ["glass", "paper", "mono", "editor"] as const;
// ---------------------------------------------------------------------------------------------------------------
// v0.6 touch (DESIGN-T1 3.3): the new flows. Each runs at the sizes of FLOW_SIZES (DESIGN-T1 3.1's table), with
// touch emulation on the touch sizes, and fails on a console error, an exception, a failed request or a sideways
// scroll, as every flow does. The parts they read: RowMenu.tsx's test ids (row-more, row-menu-<kind>, row-<id>,
// .row-menu-head, .row-menu-note, copy-failed, copy-failed-text), the session menu's menu-stop, menu-phone and
// menu-shortcuts, + > Stop's plus-stop, the card's card-stop, Open on phone's dialog-phone and phone-*, the key bar's
// term-key-*, the list head's head-tools and the title bar's topbar-search.

/** What a v0.6 touch flow's body gets: its page and wire, and the result's lists. */
interface TouchRun {
  page: Page;
  wire: Wire;
  failures: Finding[];
  warnings: Finding[];
  details: Record<string, unknown>;
  fail: (code: string, text: string) => void;
  /** A screenshot with the machine's name masked; the last one is the result's shot. */
  shot: (step?: string) => Promise<void>;
}

/** One v0.6 touch flow at one size and theme: the page, its findings, and the checks every flow has. */
async function touchFlow(o: { name: FlowId; route: string; scene: SeedSceneName | null; vp: Viewport; theme: Theme; path: string; pre?: string[] }, body: (r: TouchRun) => Promise<string>): Promise<CheckResult> {
  const t0 = Date.now();
  const failures: Finding[] = [];
  const warnings: Finding[] = [];
  const details: Record<string, unknown> = {};
  let shot: string | undefined;
  let note = "";
  try {
    await withPage(o.vp, o.theme, async (page, wire) => {
      for (const source of o.pre ?? []) await page.send("Page.addScriptToEvaluateOnNewDocument", { source });
      const r: TouchRun = {
        page,
        wire,
        failures,
        warnings,
        details,
        fail: (code, text) => failures.push({ code, text }),
        shot: async (step) => {
          shot = shotName(o.scene, o.name, o.vp, o.theme, step);
          await maskMachine(page);
          await page.screenshot(shot);
        },
      };
      note = await body(r);
      issueFindings(page.takeIssues(), failures);
      const s = await page.probe().catch(() => null);
      if (s && s.scrollWidth > s.clientWidth) failures.push({ code: "overflow", text: `the page scrolls sideways (scrollWidth ${s.scrollWidth} > clientWidth ${s.clientWidth})` });
      if (s?.offenders.length) failures.push({ code: "edge", text: `past the right edge: ${s.offenders.join(", ")}` });
    });
  } catch (e) {
    failures.push({ code: "run", text: `the flow could not run: ${(e as Error).message}` });
  }
  return finish({ kind: "flow", name: o.name, route: o.route, scene: o.scene, size: sizeTag(o.vp), theme: o.theme, path: o.path, failures, warnings, note, shot, ms: Date.now() - t0, details });
}

/** Press (a tap on touch, a click on a laptop) the first shown element for a selector; false when none shows. */
async function tapOn(page: Page, sel: string, wait = 350): Promise<boolean> {
  const at = await page.locate(sel);
  if (!at) return false;
  await page.press(at.x, at.y);
  await sleep(wait);
  await page.settle();
  return true;
}

/** A long press (a right-click on a laptop) on the first shown element for a selector. */
async function holdOn(page: Page, sel: string, ms = 700): Promise<boolean> {
  // locate() scrolls the target into view, and a press within 300 ms of a scroll never arms (T-1, a stopped fling):
  // so the finger comes down after the scroll has settled.
  if (!(await page.locate(sel))) return false;
  await sleep(450);
  const at = await page.locate(sel);
  if (!at) return false;
  await page.hold(at.x, at.y, ms);
  await sleep(300);
  await page.settle();
  return true;
}

/**
 * R-5: the events of a hold on touch, recorded from just before it (liftWatch) to its end (liftRead): Chrome sends a
 * click:touch after the touchend, which must reach the held target and be swallowed there. R-2: and where the focus is
 * then, which must be inside the menu that the hold opened.
 */
const liftWatch = (page: Page, sel: string) =>
  page.evaluate(`(() => {
    const t = document.querySelector(${JSON.stringify(sel)});
    window.__fdLift = [];
    for (const k of ["pointerup", "touchend", "click"])
      document.addEventListener(k, (e) => {
        const r = { k: k + (e.pointerType ? ":" + e.pointerType : ""), onTarget: !!t && t.contains(e.target), inLayer: !!(e.target && e.target.closest && e.target.closest(".sheet, .scrim, .menu")), prevented: null };
        window.__fdLift.push(r);
        // Read once the event has gone through every handler (a swallowed click also stops there).
        setTimeout(() => (r.prevented = e.defaultPrevented), 0);
      }, true);
    return !!t;
  })()`);
interface LiftRead {
  events: string[];
  click: { onTarget: boolean; inLayer: boolean; prevented: boolean | null } | null;
  focus: string | null;
  focusInside: boolean;
}
/** The hold's events and the focus after it; `layer` names the menu's test id (a prefix). */
const liftRead = (page: Page, layer: string) =>
  page.evaluate<LiftRead>(`(() => {
    const ev = (window.__fdLift || []).map((r) => r.k);
    const c = (window.__fdLift || []).find((r) => r.k.startsWith("click"));
    const m = [...document.querySelectorAll('[data-testid^=${JSON.stringify(layer)}]')].find((e) => e.getClientRects().length);
    const box = m ? m.closest(".sheet, .menu") || m : null;
    const a = document.activeElement;
    return { events: ev, click: c ? { onTarget: c.onTarget, inLayer: c.inLayer, prevented: c.prevented } : null, focus: a ? a.getAttribute("data-testid") || a.getAttribute("aria-label") || a.tagName : null, focusInside: !!box && !!a && box.contains(a) };
  })()`);
/**
 * The checks on a hold's lift on touch: its click reached the target and was swallowed there, or (the phone, where the
 * sheet rises under the finger) landed on the sheet or its scrim, whose guards ignore it (the caller checks that the
 * menu is still open and the URL the same); and the focus is in the menu.
 */
function liftChecks(lift: LiftRead, fail: (code: string, text: string) => void, what: string) {
  if (!lift.click) fail("flow", `${what}: no click came after the hold (${lift.events.join(", ")}), so the guard went unchecked`);
  else if (!lift.click.inLayer) {
    if (!lift.click.onTarget) fail("flow", `${what}: the click after the hold landed off its target`);
    else if (lift.click.prevented !== true) fail("flow", `${what}: the click after the hold was not swallowed`);
  }
  if (!lift.focusInside) fail("focus", `${what}: after the hold the focus is on ${lift.focus}, not in the menu`);
}

/** Poll an in-page expression until it is truthy (its value), or null after ms. */
async function waitTrue<T>(page: Page, expr: string, ms = 3000): Promise<T | null> {
  const end = Date.now() + ms;
  for (;;) {
    const v = await page.evaluate<T>(expr).catch(() => null as T);
    if (v) return v;
    if (Date.now() > end) return null;
    await sleep(80);
  }
}

/** Open the example chat's folded turns and summary rows, so its tool rows show (a setup step, by script). */
const OPEN_WORK = `(async () => {
  for (let i = 0; i < 8; i++) {
    // The folds only: a row's "..." (aria-haspopup) and a tool's head (a long-press target) have aria-expanded too.
    const b = [...document.querySelectorAll('[data-testid^="turn-"] > .chat-row-line > button[aria-expanded="false"], [data-testid^="summary-"] [aria-expanded="false"]')].filter((x) => !x.hasAttribute("aria-haspopup") && !x.hasAttribute("data-row-press") && !x.closest('[data-testid^="item-"]'));
    if (!b.length) return i;
    b.forEach((x) => x.click());
    await new Promise((r) => setTimeout(r, 250));
  }
  return 8;
})()`;

/** A row menu's state: its kind, its rows' test ids and words, its first lines, and whether it is a sheet. */
interface RowMenuState {
  kind: string | null;
  rows: { id: string; label: string }[];
  head: string | null;
  note: string | null;
  sheet: boolean;
  box: { left: number; top: number; right: number; bottom: number } | null;
  scroll: { h: number; sh: number } | null;
}
const ROW_MENU_STATE = `(() => {
  const vis = (e) => e.getClientRects().length > 0 && getComputedStyle(e).visibility !== "hidden";
  const m = [...document.querySelectorAll('[data-testid^="row-menu-"]')].find(vis);
  if (!m) return null;
  const sheet = m.closest(".sheet") || (m.matches(".sheet") ? m : null);
  const box = (sheet || m).getBoundingClientRect();
  const head = m.querySelector(".row-menu-head");
  const note = m.querySelector(".row-menu-note");
  return {
    kind: m.getAttribute("data-testid").slice("row-menu-".length),
    rows: [...m.querySelectorAll('[data-testid^="row-"]')].filter((e) => !/^row-(menu|more)/.test(e.getAttribute("data-testid"))).map((e) => ({ id: e.getAttribute("data-testid"), label: e.textContent.trim() })),
    head: head ? head.textContent : null,
    note: note ? note.textContent.trim() : null,
    sheet: !!sheet,
    box: { left: Math.round(box.left), top: Math.round(box.top), right: Math.round(box.right), bottom: Math.round(box.bottom) },
    scroll: sheet ? { h: sheet.clientHeight, sh: sheet.scrollHeight } : null,
  };
})()`;
const rowMenu = (page: Page) => page.evaluate<RowMenuState | null>(ROW_MENU_STATE);
const waitRowMenu = (page: Page, ms = 2500) => waitTrue<RowMenuState>(page, ROW_MENU_STATE, ms);

/** Give a page the clipboard (as the copy checks do), and read it back. */
async function grantClipboard(page: Page, base: string) {
  await cdp.send("Browser.grantPermissions", { permissions: ["clipboardReadWrite", "clipboardSanitizedWrite"], origin: base, browserContextId: page.contextId }).catch(() => {});
}
const readClipboard = (page: Page) => page.evaluate<string | null>(`navigator.clipboard.readText().catch(() => null)`).catch(() => null);
const writeClipboard = (page: Page, text: string) => page.evaluate<boolean>(`navigator.clipboard.writeText(${JSON.stringify(text)}).then(() => true, () => false)`);

/** Close what is open with Esc (a hardware keyboard's on touch) and let the page settle. */
async function escape(page: Page) {
  await page.key("Escape");
  await sleep(250);
  await page.settle();
}

/** The frames of these kinds that went out since a mark. */
const sentOf = (wire: Wire, since: number, kinds: string[]) => wire.framesSince(since).filter((f) => kinds.includes(f.t));

const TOOL_EDIT = `[data-testid="item-toolu_01AbCdEf"] [data-row-press]`;
const TOOL_BASH = `[data-testid="item-toolu_01BashRerun5"] [data-row-press]`;
const FILE_ROWS = ["row-open", "row-download", "row-attach", "row-copy-path", "row-copy-rel"];
const TITLE_SEL = (vp: Viewport) => (vp.name === "laptop" ? ".scr-bar-title" : ".scr-bar-title-touch");
const SESSION_MENU = `(() => { const m = [...document.querySelectorAll('[data-testid="session-menu"]')].find((e) => e.getClientRects().length); if (!m) return null; return { sheet: !!(m.closest(".sheet") || m.matches(".sheet")), items: [...m.querySelectorAll('[data-testid^="menu-"]')].map((e) => e.getAttribute("data-testid")) }; })()`;

/**
 * longpress-title (T-1, G-2): a hold of 600 ms on the chat title opens the session menu (a sheet at 390, a menu under
 * the title elsewhere) and changes no URL and opens no Rename; Esc closes it; a tap on the title still opens Rename;
 * the title link is not draggable (WebKit's drag lift).
 */
async function longpressTitleFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const path = `/c/${EX.chat}`;
  return touchFlow({ name: "longpress-title", route: "chat", scene, vp, theme, path }, async ({ page, wire, fail, details, shot }) => {
    await page.navigate(base + path);
    await waitShown(page, ["conversation"]);
    const sel = TITLE_SEL(vp);
    const drag = await page.evaluate<string | null>(`(() => { const t = document.querySelector(${JSON.stringify(sel)}); return t ? t.getAttribute("draggable") : "none"; })()`);
    if (drag !== "false") fail("flow", `the title link's draggable is ${drag}, not false`);
    const since = wire.mark();
    if (vp.touch) await liftWatch(page, sel);
    if (!(await holdOn(page, sel, 600))) {
      fail("shows", "no chat title shows");
      return "no title";
    }
    const menu = await waitTrue<{ sheet: boolean; items: string[] }>(page, SESSION_MENU, 2000);
    details.menu = menu;
    if (vp.touch && menu) {
      details.lift = await liftRead(page, "session-menu");
      liftChecks(details.lift as LiftRead, fail, "the title");
    }
    if (!menu) fail("flow", "a hold on the title opens no session menu");
    else if (menu.sheet !== (vp.name === "phone")) fail("flow", `the title's session menu is ${menu.sheet ? "a sheet" : "a menu"} at ${sizeTag(vp)}`);
    const s = await page.probe();
    if (!sameUrl(s.path, path)) fail("url", `the hold changed the URL to ${s.path}`);
    if (s.ids.includes("dialog-rename")) fail("flow", "the hold opened Rename too");
    await shot("menu");
    await escape(page);
    if (await page.evaluate(SESSION_MENU)) fail("flow", "Esc does not close the title's session menu");
    await tapOn(page, sel, 500);
    const r = await page.probe();
    if (!r.path.endsWith("/rename") || !r.ids.includes("dialog-rename")) fail("flow", `a tap on the title gives ${r.path}, not Rename`);
    await escape(page);
    if (mutating(wire.framesSince(since)).length) fail("frames", `the title's menu sent ${clipList(mutating(wire.framesSince(since)).map(frameText))}`);
    return `the hold opens the session menu as ${menu?.sheet ? "a sheet" : "a menu"} with ${menu?.items.length ?? 0} items; a tap renames`;
  });
}

/**
 * longpress-tool (T-1, T-2, T-26): a hold on the Edit row's head opens the file menu's five rows, its first line the
 * file's full path; Copy path writes it exactly; the Bash row's menu holds Copy command and Copy output, and Copy
 * command writes the command; each row's "..." opens the same menu; a hold on a tool's body opens none; a hold 100 ms
 * after a scroll of the conversation (a stopped fling) opens none.
 */
async function longpressToolFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const path = `/c/${EX.chat}`;
  return touchFlow({ name: "longpress-tool", route: "tool", scene, vp, theme, path }, async ({ page, wire, fail, details, shot }) => {
    await page.navigate(base + path);
    await waitShown(page, ["conversation"]);
    await grantClipboard(page, base);
    await page.evaluate(OPEN_WORK);
    await page.settle();
    const since = wire.mark();
    if (vp.touch) await liftWatch(page, TOOL_EDIT);
    await holdOn(page, TOOL_EDIT);
    const file = await waitRowMenu(page);
    details.file = file;
    if (!file) fail("flow", "a hold on the Edit row's head opens no menu");
    else {
      if (vp.touch) {
        details.lift = await liftRead(page, "row-menu-");
        liftChecks(details.lift as LiftRead, fail, "the Edit row");
      }
      if (file.kind !== "file") fail("flow", `the Edit row's menu is ${file.kind}, not the file menu`);
      if (file.rows.map((r) => r.id).join() !== FILE_ROWS.join()) fail("flow", `the file menu's rows are ${file.rows.map((r) => r.id).join(", ")}`);
      if (!file.head?.startsWith("/") || !file.head.endsWith("/src/upload.ts")) fail("flow", `the menu's first line is "${file.head}", not the file's full path`);
      if (file.sheet !== (vp.name === "phone")) fail("flow", `the menu is ${file.sheet ? "a sheet" : "a menu at the row"} at ${sizeTag(vp)}`);
      if (file.scroll && file.scroll.sh > file.scroll.h + 1) fail("flow", `the menu's sheet scrolls (${file.scroll.sh} > ${file.scroll.h})`);
      await shot("file");
      await tapOn(page, '[data-testid="row-copy-path"]');
      const clip1 = await readClipboard(page);
      details.copyPath = clip1;
      if (clip1 !== file.head) fail("copy", `Copy path wrote "${clip1}", not "${file.head}"`);
      if (await rowMenu(page)) fail("flow", "the menu stays open after Copy path");
    }
    if (!sameUrl((await page.probe()).path, path)) fail("url", "the hold changed the URL");
    await holdOn(page, TOOL_BASH);
    const bash = await waitRowMenu(page);
    details.bash = bash;
    if (!bash) fail("flow", "a hold on the Bash row's head opens no menu");
    else {
      if (bash.rows.map((r) => r.id).join() !== "row-copy-command,row-copy-output") fail("flow", `the Bash menu's rows are ${bash.rows.map((r) => r.id).join(", ")}`);
      await tapOn(page, '[data-testid="row-copy-command"]');
      const clip2 = await readClipboard(page);
      details.copyCommand = clip2;
      if (clip2 !== "bun test test/upload.test.ts --rerun-each 5") fail("copy", `Copy command wrote "${clip2}"`);
    }
    if (vp.touch) {
      for (const row of ["toolu_01AbCdEf", "toolu_01BashRerun5"]) {
        const opened = await tapOn(page, `[data-testid="item-${row}"] [data-testid="row-more"]`);
        const m = opened ? await waitRowMenu(page) : null;
        if (!m) fail("opener-touch", `the "..." of ${row} opens no menu`);
        else {
          if (m.kind !== (row === "toolu_01BashRerun5" ? "bash" : "file")) fail("flow", `the "..." of ${row} opens the ${m.kind} menu`);
          // R-3: a menu at the row keeps 8 px from the window's edges.
          const win = await page.evaluate<number>("innerWidth");
          if (!m.sheet && m.box && (m.box.right > win - 8 || m.box.left < 8)) fail("edge", `the "..." of ${row} opens a menu at ${m.box.left}-${m.box.right} in a ${win} px window, not 8 px inside it`);
        }
        await escape(page);
      }
      // The body: the Bash row opened, a hold on its output's text.
      await tapOn(page, TOOL_BASH);
      const body = await page.evaluate<boolean>(`!!document.querySelector('[data-testid="item-toolu_01BashRerun5"] pre')`);
      if (body) {
        await holdOn(page, `[data-testid="item-toolu_01BashRerun5"] pre`);
        if (await rowMenu(page)) fail("flow", "a hold on the tool's body opens a menu (the body's text is the browser's to select)");
        await escape(page);
      } else details.body = "the Bash row shows no body to hold";
      // A stopped fling: the conversation scrolls, and 100 ms later a finger rests on a row.
      const at = await page.evaluate<{ x: number; y: number } | null>(`(() => {
        const t = document.querySelector(${JSON.stringify(TOOL_EDIT)});
        if (!t) return null;
        t.scrollIntoView({ block: "center" });
        let s = t.parentElement;
        while (s && !(s.scrollHeight > s.clientHeight + 1 && /(auto|scroll)/.test(getComputedStyle(s).overflowY))) s = s.parentElement;
        if (s) s.scrollTop += 1;
        const r = t.getBoundingClientRect();
        return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
      })()`);
      if (at) {
        await sleep(100);
        await page.hold(at.x, at.y, 700);
        await sleep(300);
        details.fling = await rowMenu(page);
        if (details.fling) fail("flow", "a hold 100 ms after a scroll opened the row's menu (a stopped fling)");
        await escape(page);
      }
    }
    const out = sentOf(wire, since, ["send", "bash"]);
    if (out.length) fail("frames", `the menus sent ${clipList(out.map(frameText))}`);
    return `file menu ${file?.rows.length ?? 0} rows, Copy path exact; Bash menu Copy command exact; the "..." opens them${vp.touch ? "; no menu from the body or after a fling" : ""}`;
  });
}

/** The Outputs row of docs/UPLOAD-RETRIES.md in Details (the card's row). */
const OUTPUT_ROW = `[data-testid="side-outputs"] [data-row-press]`;

/**
 * longpress-file (T-2, T-31, T-32): a hold on an Outputs file in Details opens its menu (a sheet at 390) whose first
 * line is the full path; Copy relative path writes docs/UPLOAD-RETRIES.md; Attach as context puts its mention chip in
 * the draft and sends nothing (the flow then takes the chip away); the row's link is not draggable; its "..." opens
 * the same menu. On a phone on its side the menu's sheet shows every row with no scroll and Copy relative path takes a
 * tap at its centre.
 */
async function longpressFileFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const path = `/c/${EX.chat}/details`;
  return touchFlow({ name: "longpress-file", route: "outputs", scene, vp, theme, path }, async ({ page, wire, fail, details, shot }) => {
    await page.navigate(base + path);
    await waitShown(page, ["side-outputs"]);
    await grantClipboard(page, base);
    const row = await page.evaluate<{ sel: string; drag: string | null } | null>(`(() => {
      const rows = [...document.querySelectorAll(${JSON.stringify(OUTPUT_ROW)})];
      const i = rows.findIndex((r) => r.textContent.includes("UPLOAD-RETRIES"));
      if (i < 0) return null;
      rows[i].setAttribute("data-fd-row", "");
      const link = rows[i].closest("a") || rows[i].querySelector("a") || rows[i];
      return { sel: "[data-fd-row]", drag: link.tagName === "A" ? link.getAttribute("draggable") : "not a link" };
    })()`);
    if (!row) {
      fail("shows", "Details lists no Outputs row for docs/UPLOAD-RETRIES.md");
      return "no row";
    }
    if (row.drag !== "false" && row.drag !== "not a link") fail("flow", `the Outputs row's link has draggable ${row.drag}`);
    const since = wire.mark();
    if (vp.touch) await liftWatch(page, row.sel);
    await holdOn(page, row.sel);
    const m = await waitRowMenu(page);
    details.menu = m;
    if (!m) {
      fail("flow", "a hold on the Outputs row opens no menu");
      return "no menu";
    }
    if (vp.touch) {
      details.lift = await liftRead(page, "row-menu-");
      liftChecks(details.lift as LiftRead, fail, "the Outputs row");
      if (!sameUrl((await page.probe()).path, path)) fail("url", "the hold's click changed the URL");
    }
    if (!m.head?.endsWith("/docs/UPLOAD-RETRIES.md") || !m.head.startsWith("/")) fail("flow", `the menu's first line is "${m.head}", not the full path`);
    if (m.sheet !== (vp.name === "phone")) fail("flow", `the menu is ${m.sheet ? "a sheet" : "a menu"} at ${sizeTag(vp)}`);
    for (const id of ["row-attach", "row-copy-path", "row-copy-rel"]) if (!m.rows.some((r) => r.id === id)) fail("flow", `the Outputs menu has no ${id}`);
    if (vp.insets) {
      if (m.scroll && m.scroll.sh > m.scroll.h + 1) fail("flow", `on its side the menu's sheet scrolls (${m.scroll.sh} > ${m.scroll.h})`);
      const hit = await page.evaluate<boolean>(`(() => { const b = document.querySelector('[data-testid="row-copy-rel"]'); if (!b) return false; const r = b.getBoundingClientRect(); const at = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2); return !!at && (at === b || b.contains(at)); })()`);
      if (!hit) fail("control-out", "on its side Copy relative path does not take a tap at its centre");
    }
    await shot("menu");
    await tapOn(page, '[data-testid="row-copy-rel"]');
    const rel = await readClipboard(page);
    details.copyRel = rel;
    if (rel !== "docs/UPLOAD-RETRIES.md") fail("copy", `Copy relative path wrote "${rel}"`);
    if (vp.touch && !vp.insets) {
      const opened = await page.evaluate<boolean>(`(() => { const r = document.querySelector("[data-fd-row]"); let p = r; for (let i = 0; i < 5 && p; i++, p = p.parentElement) { const b = p.querySelector('[data-testid="row-more"]'); if (b && b.getClientRects().length) { b.setAttribute("data-fd-more", ""); return true; } } return false; })()`);
      if (!opened) fail("opener-touch", "the Outputs row shows no \"...\"");
      else {
        await tapOn(page, "[data-fd-more]");
        if (!(await waitRowMenu(page))) fail("opener-touch", "the Outputs row's \"...\" opens no menu");
        await escape(page);
      }
    }
    // Attach as context: the chip in the draft, nothing sent; then the chip goes again.
    await holdOn(page, row.sel);
    if (await waitRowMenu(page)) {
      await tapOn(page, '[data-testid="row-attach"]');
      if (vp.name === "phone") {
        await page.navigate(base + `/c/${EX.chat}`);
        await waitShown(page, ["composer"]);
      }
      const chip = await waitTrue<string>(page, `(() => { const c = document.querySelector('[data-testid="mention-chip"]'); return c && c.getAttribute("data-path"); })()`, 3000);
      details.chip = chip;
      if (chip !== "docs/UPLOAD-RETRIES.md") fail("flow", `Attach as context left the chip ${chip}, not docs/UPLOAD-RETRIES.md`);
      const out = sentOf(wire, since, ["send", "bash", "new_chat"]);
      if (out.length) fail("frames", `Attach as context sent ${clipList(out.map(frameText))}`);
      if (chip) {
        await tapOn(page, '[data-testid="mention-chip"] .attach-remove');
        await sleep(600);
        if (await page.evaluate<boolean>(`!!document.querySelector('[data-testid="mention-chip"]')`)) fail("run", "the flow could not take the chip away again");
      }
    } else fail("flow", "the second hold opened no menu");
    return `the menu's first line ${m.head?.length ?? 0} characters; Copy relative path exact; Attach as context adds the chip and sends nothing`;
  });
}

/**
 * longpress-upload (T-1, T-2): in Files a hold on an upload opens its menu (Download, Copy path, Remove); where the
 * pane is under 23em (626) its three buttons fold into the "..." and the "..." opens the menu; at 768 the buttons show.
 * Remove removes the upload: pressed at the last size only, since the seed's uploads are the example chat's.
 */
async function longpressUploadFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme, remove: boolean): Promise<CheckResult> {
  const path = `/c/${EX.chat}/uploads`;
  return touchFlow({ name: "longpress-upload", route: "uploads", scene, vp, theme, path }, async ({ page, wire, fail, details, shot }) => {
    await page.navigate(base + path);
    await waitShown(page, ["uploads|uploads-page"]);
    const rows = await page.evaluate<{ id: string; buttons: number; more: boolean }[]>(`[...document.querySelectorAll('[data-testid="uploads"] .side-up')].map((r) => ({ id: r.getAttribute("data-testid"), buttons: [...r.querySelectorAll(".side-up-tools button")].filter((b) => b.getClientRects().length).length, more: [...r.querySelectorAll('[data-testid="row-more"]')].some((b) => b.getClientRects().length) }))`);
    details.rows = rows;
    if (!rows.length) {
      fail("shows", "Files lists no upload");
      return "no upload";
    }
    const first = rows[0]!;
    if (vp.label === "m626" && (first.buttons || !first.more)) fail("flow", `at 626 the upload row shows ${first.buttons} buttons and ${first.more ? "its" : "no"} "..."`);
    if (vp.label === "m768" && (first.buttons < 2 || first.more)) fail("flow", `at 768 the upload row shows ${first.buttons} buttons and ${first.more ? "a" : "no"} "..."`);
    const sel = `[data-testid="${first.id}"] [data-row-press]`;
    const since = wire.mark();
    await holdOn(page, sel);
    const m = await waitRowMenu(page);
    details.menu = m;
    if (!m) fail("flow", "a hold on the upload opens no menu");
    else if (m.kind !== "upload" || !["row-download", "row-copy-path", "row-remove"].every((id) => m.rows.some((r) => r.id === id))) fail("flow", `the upload's menu is ${m.kind} with ${m.rows.map((r) => r.id).join(", ")}`);
    await shot("menu");
    await escape(page);
    if (first.more) {
      await tapOn(page, `[data-testid="${first.id}"] [data-testid="row-more"]`);
      if (!(await waitRowMenu(page))) fail("opener-touch", "the upload's \"...\" opens no menu");
      await escape(page);
    }
    if (remove && m) {
      await holdOn(page, sel);
      await waitRowMenu(page);
      await tapOn(page, '[data-testid="row-remove"]', 800);
      const gone = await waitTrue<boolean>(page, `!document.querySelector('[data-testid="${first.id}"]')`, 4000);
      if (!gone) fail("flow", "Remove in the upload's menu leaves the upload");
      details.removed = first.id;
    } else if (mutating(wire.framesSince(since)).length || wire.httpSince(since).length) fail("frames", "the upload's menu sent something without Remove");
    return `the upload's menu ${m?.rows.length ?? 0} rows${first.more ? ' by its "..." too' : ""}${remove ? "; Remove removed it" : ""}`;
  });
}

/**
 * stream-hold (the code review's finding 2): while a reply streams and the view follows the end, which scrolls the
 * transcript itself on every frame, a hold on a row in view opens its menu (only a person's scroll ends a press or
 * keeps one from arming); and the view still follows the end after.
 */
async function streamHoldFlow(t: Target, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const path = `/c/${EX.chat}`;
  return touchFlow({ name: "stream-hold", route: "chat", scene: t.scene, vp, theme, path }, async ({ page, fail, details, shot }) => {
    await page.navigate(t.base + path);
    await waitShown(page, ["conversation"]);
    await page.evaluate(OPEN_WORK);
    await page.settle();
    // The user's own send, which puts the view at the end and keeps it there while the reply streams.
    await page.evaluate(`(() => { const f = ${FIELD}; if (f) f.focus(); })()`);
    await page.send("Input.insertText", { text: STREAM_HOLD.prompt });
    await sleep(150);
    await keyCode(page, "Enter", 13, { text: "\r" });
    await page.evaluate(`document.activeElement && document.activeElement.blur()`);
    const turn = waitTrue<boolean>(page, `(document.querySelector('[data-testid="conversation"]')?.textContent ?? "").includes("Retry note 160:") && !document.querySelector('[data-testid="conversation"] .chat-working, [data-testid="conversation"] [data-streaming]')`, 60_000).then((v) => (v ? true : "it did not end in 60 s"));
    const streaming = await waitTrue<boolean>(page, `(document.querySelector('[data-testid="conversation"]')?.textContent ?? "").includes("Retry note 3:")`, 15_000);
    if (!streaming) {
      fail("run", "the reply did not start to stream");
      return "no stream";
    }
    const at = await page.evaluate<{ x: number; y: number; name: string } | null>(`(() => {
      const rows = [...document.querySelectorAll('[data-testid="conversation"] [data-row-press]')].map((e) => [e, e.getBoundingClientRect()]).filter(([, b]) => b.height > 0 && b.top > 80 && b.bottom < innerHeight - 260);
      const p = rows[rows.length - 1];
      if (!p) return null;
      return { x: p[1].left + Math.min(40, p[1].width / 2), y: p[1].top + p[1].height / 2, name: p[0].textContent.trim().slice(0, 40) };
    })()`);
    details.row = at?.name ?? null;
    if (!at) {
      fail("shows", "no row with a menu shows above the streaming reply");
      await turn;
      return "no row";
    }
    await page.evaluate(`(() => { window.__fdScrolls = 0; document.addEventListener("scroll", () => window.__fdScrolls++, { capture: true, passive: true }); })()`);
    await page.send("Input.dispatchTouchEvent", { type: "touchStart", touchPoints: [{ x: at.x, y: at.y, radiusX: 4, radiusY: 4, force: 1 }] });
    await sleep(750);
    const menu = await rowMenu(page);
    await page.send("Input.dispatchTouchEvent", { type: "touchEnd", touchPoints: [] });
    const scrolls = await page.evaluate<number>("window.__fdScrolls");
    details.menu = menu?.kind ?? null;
    details.scrollsDuringHold = scrolls;
    if (scrolls === 0) fail("run", "the view did not scroll while the finger held the row, so the hold met no follow scroll");
    if (!menu) fail("flow", "a hold on a row while the reply streams opens no menu (the view's own follow scrolls ended it)");
    else await shot("menu");
    await escape(page);
    const ended = await turn;
    if (typeof ended === "string") fail("run", `the streaming turn did not end: ${ended}`);
    await sleep(800);
    await page.settle();
    const gap = await page.evaluate<number>(`(() => { const c = document.querySelector('[data-testid="conversation"]'); let s = c; while (s && !(s.scrollHeight > s.clientHeight + 1 && /(auto|scroll)/.test(getComputedStyle(s).overflowY))) s = s.parentElement; return s ? Math.round(s.scrollHeight - s.scrollTop - s.clientHeight) : 0; })()`);
    details.endGap = gap;
    if (gap > 90) fail("flow", `after the hold the view no longer follows the end (${gap} px from it)`);
    return `a hold during ${scrolls} follow scrolls opens the ${menu?.kind ?? "no"} menu; the view follows the end after`;
  });
}

/**
 * cut-output (T-26, G-43; a main scene seed of its own): after a turn whose Bash call printed 7,000 characters, the
 * row's menu says "Output cut at 6,000 of 7,000 characters.", "Copy first 6,000 characters" writes exactly the page's
 * 6,000, and "Download output" answers 200 with the whole 7,000 as an attachment.
 */
async function cutOutputFlow(t: Target, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const path = `/c/${EX.chat}`;
  return touchFlow({ name: "cut-output", route: "tool", scene: t.scene, vp, theme, path }, async ({ page, fail, details, shot }) => {
    await page.navigate(t.base + path);
    await waitShown(page, ["conversation"]);
    await grantClipboard(page, t.base);
    await page.evaluate(OPEN_WORK);
    await page.settle();
    const sel = `[data-testid^="item-toolu_01CutLog"] [data-row-press]`;
    if (!(await holdOn(page, sel))) {
      fail("shows", "the cut Bash row does not show");
      return "no row";
    }
    const m = await waitRowMenu(page);
    details.menu = m;
    if (!m) {
      fail("flow", "a hold on the cut Bash row opens no menu");
      return "no menu";
    }
    if (m.note !== "Output cut at 6,000 of 7,000 characters.") fail("flow", `the menu's cut line is "${m.note}"`);
    const copy = m.rows.find((r) => r.id === "row-copy-output");
    if (copy?.label !== "Copy first 6,000 characters") fail("flow", `the copy row reads "${copy?.label}"`);
    if (!m.rows.some((r) => r.id === "row-download-output")) fail("flow", "the menu has no Download output");
    await shot("menu");
    // Download output probes the result first, then hands its URL to the browser's download (panels/download.ts): the
    // flow takes that hand-off instead of a saved file, and reads the URL itself.
    await page.evaluate(`(() => { window.__fdSaved = []; const own = HTMLAnchorElement.prototype.click; HTMLAnchorElement.prototype.click = function () { if (this.hasAttribute("download")) { window.__fdSaved.push(this.href); return; } return own.call(this); }; })()`);
    await tapOn(page, '[data-testid="row-download-output"]');
    const saved = await waitTrue<string>(page, `window.__fdSaved[0]`, 3000);
    details.saved = saved;
    const got = saved
      ? await page.evaluate<{ status: number; type: string | null; disposition: string | null; text: string }>(`(async () => {
      const r = await fetch(${JSON.stringify(saved)});
      return { status: r.status, type: r.headers.get("content-type"), disposition: r.headers.get("content-disposition"), text: await r.text() };
    })()`)
      : null;
    details.download = got ? { ...got, text: got.text.length } : null;
    if (!got) fail("flow", "Download output started no download");
    else {
      if (got.status !== 200) fail("request", `Download output answered ${got.status}`);
      if (!/attachment/.test(got.disposition ?? "")) fail("flow", `Download output's Content-Disposition is ${got.disposition}`);
      if (got.text !== CUT_OUTPUT.text) fail("flow", `Download output gave ${got.text.length} characters, not the whole 7,000`);
    }
    if (!(await rowMenu(page))) {
      await holdOn(page, sel);
      await waitRowMenu(page);
    }
    await tapOn(page, '[data-testid="row-copy-output"]');
    const clip = await readClipboard(page);
    details.copied = clip?.length ?? null;
    if (clip !== CUT_OUTPUT.text.slice(0, 6000)) fail("copy", `Copy first 6,000 characters wrote ${clip?.length ?? "nothing"} characters${clip && clip.length === 6000 ? " that are not the output's first 6,000" : ""}`);
    return `the cut line, Copy first 6,000 characters exact, Download output ${got?.status} with ${got?.text.length} characters`;
  });
}

/**
 * menus-laptop (T-3, 1100x800): a right-click on the title, a tool row and an Outputs file opens the same menus, the
 * row's at the pointer; with a word of the row selected, and with Shift, no custom menu opens (the browser's own);
 * Shift+F10 on a focused row opens it; an Outputs row's menu has Open in new tab and Copy link, which writes the row's
 * URL.
 */
async function menusLaptopFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const path = `/c/${EX.chat}`;
  return touchFlow({ name: "menus-laptop", route: "chat", scene, vp, theme, path }, async ({ page, fail, details, shot }) => {
    await page.navigate(base + path);
    await waitShown(page, ["conversation"]);
    await grantClipboard(page, base);
    await holdOn(page, ".scr-bar-title");
    if (!(await waitTrue(page, SESSION_MENU, 1500))) fail("flow", "a right-click on the title opens no session menu");
    await escape(page);
    await page.evaluate(OPEN_WORK);
    await page.settle();
    const at = await page.locate(TOOL_EDIT);
    if (!at) {
      fail("shows", "the Edit row does not show");
      return "no row";
    }
    await page.hold(at.x, at.y);
    const m = await waitRowMenu(page);
    details.rowMenu = m;
    if (!m) fail("flow", "a right-click on the Edit row opens no menu");
    else if (!m.box || Math.abs(m.box.left - at.x) > 40 || Math.abs(m.box.top - at.y) > 40) fail("flow", `the menu opens at ${m.box?.left},${m.box?.top}, not at the pointer (${Math.round(at.x)},${Math.round(at.y)})`);
    await escape(page);
    // A word of the head selected: the browser's own menu.
    const at2 = await page.evaluate<{ x: number; y: number } | null>(`(() => {
      const h = document.querySelector(${JSON.stringify(TOOL_EDIT)});
      const w = document.createTreeWalker(h, NodeFilter.SHOW_TEXT);
      let n; while ((n = w.nextNode()) && !n.data.trim()) {}
      if (!n) return null;
      const r = document.createRange();
      r.setStart(n, 0); r.setEnd(n, Math.min(4, n.data.length));
      const s = getSelection(); s.removeAllRanges(); s.addRange(r);
      const b = r.getBoundingClientRect();
      return { x: b.left + b.width / 2, y: b.top + b.height / 2 };
    })()`);
    if (at2) {
      await page.hold(at2.x, at2.y);
      await sleep(300);
      if (await rowMenu(page)) fail("flow", "a right-click on a selected word of the row opens the custom menu");
      await escape(page);
      await page.evaluate(`getSelection().removeAllRanges()`);
    }
    await page.send("Input.dispatchMouseEvent", { type: "mousePressed", x: at.x, y: at.y, button: "right", buttons: 2, clickCount: 1, modifiers: 8 });
    await page.send("Input.dispatchMouseEvent", { type: "mouseReleased", x: at.x, y: at.y, button: "right", buttons: 0, clickCount: 1, modifiers: 8 });
    await sleep(300);
    if (await rowMenu(page)) fail("flow", "Shift and a right-click open the custom menu");
    await escape(page);
    await page.evaluate(`document.querySelector(${JSON.stringify(TOOL_EDIT)}).focus()`);
    const f10 = { key: "F10", code: "F10", windowsVirtualKeyCode: 121, nativeVirtualKeyCode: 121, modifiers: 8 };
    await page.send("Input.dispatchKeyEvent", { type: "rawKeyDown", ...f10 });
    await page.send("Input.dispatchKeyEvent", { type: "keyUp", ...f10 });
    if (!(await waitRowMenu(page, 1500))) fail("flow", "Shift+F10 on the focused row opens no menu");
    await escape(page);
    // Outputs in Details: Open in new tab and Copy link.
    await page.navigate(base + path + "/details");
    await waitShown(page, ["side-outputs"]);
    await holdOn(page, OUTPUT_ROW);
    const o = await waitRowMenu(page);
    details.outputs = o;
    if (!o) fail("flow", "a right-click on an Outputs row opens no menu");
    else {
      for (const id of ["row-tab", "row-copy-link"]) if (!o.rows.some((r) => r.id === id)) fail("flow", `the Outputs row's laptop menu has no ${id}`);
      const want = await page.evaluate<string | null>(`(() => { const r = document.querySelector(${JSON.stringify(OUTPUT_ROW)}); const a = r && (r.closest("a[href]") || r.querySelector("a[href]")); return a ? a.href : null; })()`);
      await shot("outputs");
      await tapOn(page, '[data-testid="row-copy-link"]');
      const clip = await readClipboard(page);
      details.copyLink = { clip, want };
      if (!clip || (want && clip !== want)) fail("copy", `Copy link wrote "${clip}", not the row's URL ${want}`);
    }
    return "right-click menus at the pointer; none with a selection or Shift; Shift+F10 opens it; Copy link exact";
  });
}

/** toast-hold (T-21): a tap on a toast holds it past its time until its Close (a Copy path's "Copied" toast). */
async function toastHoldFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const path = `/c/${EX.chat}`;
  return touchFlow({ name: "toast-hold", route: "chat", scene, vp, theme, path }, async ({ page, fail, details, shot }) => {
    await page.navigate(base + path);
    await waitShown(page, ["conversation"]);
    await grantClipboard(page, base);
    await page.evaluate(OPEN_WORK);
    await holdOn(page, TOOL_EDIT);
    await waitRowMenu(page);
    await tapOn(page, '[data-testid="row-copy-path"]', 100);
    if (!(await waitTrue(page, `!!document.querySelector('[data-testid="toast"]')`, 1500))) {
      fail("shows", "Copy path raises no toast");
      return "no toast";
    }
    const at = await page.locate('[data-testid="toast"] .toast-text');
    details.at = at;
    if (at?.covered) fail("control-out", `the toast is covered where a tap lands, by ${at.covered}`);
    if (at) await page.press(at.x, at.y);
    await sleep(150);
    details.held = await page.evaluate<boolean>(`document.querySelector('[data-testid="toast"]')?.hasAttribute("data-held") ?? false`);
    if (!details.held) fail("flow", "a tap on the toast does not hold it");
    await sleep(9000);
    const still = await page.evaluate<boolean>(`!!document.querySelector('[data-testid="toast"]')`);
    if (!still) fail("flow", "a tapped toast closed after its time");
    await shot("held");
    await tapOn(page, '[data-testid="toast"] .toast-close');
    await sleep(400);
    if (await page.evaluate<boolean>(`!!document.querySelector('[data-testid="toast"]')`)) fail("flow", "the held toast's Close does not close it");
    return "a tapped toast stays 9 s, its Close closes it";
  });
}

/**
 * shortcuts-touch (T-7, T-9): Settings > General has Keyboard shortcuts as a row at every size, which opens the list,
 * with no Tab and Right arrow row; the session menu has Keyboard shortcuts on every size but the phone.
 */
async function shortcutsTouchFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const path = "/settings/general";
  return touchFlow({ name: "shortcuts-touch", route: "settingsSection", scene, vp, theme, path }, async ({ page, fail, details, shot }) => {
    await page.navigate(base + path);
    await waitShown(page, ["settings-general"]);
    if (!(await tapOn(page, '[data-testid="setting-shortcuts"] a'))) fail("shows", "Settings > General has no Keyboard shortcuts row");
    const list = await page.evaluate<{ path: string; text: string }>(`({ path: location.pathname, text: (document.querySelector('[data-testid="settings-general"]') || document.body).textContent })`);
    details.list = { path: list.path };
    if (list.path !== "/settings/general/shortcuts") fail("flow", `the row opens ${list.path}`);
    if (!/Ctrl|Cmd/.test(list.text)) fail("flow", "the shortcuts view lists no keys");
    if (/Right arrow/.test(list.text) && /\bTab\b/.test(list.text)) fail("flow", "the list still has the Tab and Right arrow row");
    await shot("list");
    await page.navigate(base + `/c/${EX.chat}`);
    await waitShown(page, ["conversation"]);
    await tapOn(page, '[aria-label="Session menu"]');
    const menu = await waitTrue<{ items: string[] }>(page, SESSION_MENU, 1500);
    details.menu = menu?.items;
    const has = !!menu?.items.includes("menu-shortcuts");
    if (has !== (vp.name !== "phone")) fail("flow", `the session menu ${has ? "has" : "lacks"} Keyboard shortcuts at ${sizeTag(vp)}`);
    await escape(page);
    return `the Settings row opens the list; the session menu ${has ? "has the item" : "has no item (the phone)"}`;
  });
}

/** The key bar's parts (TerminalPane.tsx KeyBar): its height, the pinned Copy and Paste, Select and the scrolling part. */
const KEY_BAR = `(() => {
  const bar = document.querySelector('[data-testid="terminal-keys"]');
  if (!bar) return null;
  const sc = bar.querySelector(".term-keys-scroll");
  const box = (e) => { if (!e) return null; const r = e.getBoundingClientRect(); return { left: r.left, right: r.right, top: r.top, bottom: r.bottom }; };
  const inView = (e, within) => { const r = box(e), w = box(within); return !!r && r.left >= w.left - 1 && r.right <= w.right + 1 && r.left >= 0 && r.right <= innerWidth + 1 && r.top >= 0 && r.bottom <= innerHeight + 1; };
  const sel = bar.querySelector('[data-testid="term-key-select"]');
  const after = sel ? getComputedStyle(sel, "::after") : null;
  return {
    h: Math.round(bar.getBoundingClientRect().height),
    copy: inView(bar.querySelector('[data-testid="term-key-copy"]'), bar),
    paste: inView(bar.querySelector('[data-testid="term-key-paste"]'), bar),
    select: sel ? inView(sel, sc) : false,
    more: sc ? sc.hasAttribute("data-more") : false,
    scroll: sc ? { left: sc.scrollLeft, w: sc.clientWidth, sw: sc.scrollWidth } : null,
    arrows: inView([...bar.querySelectorAll(".term-arrows > *")].pop(), sc),
    pressed: sel ? sel.getAttribute("aria-pressed") : null,
    ink: after ? after.content !== "none" && after.content !== "normal" && after.display !== "none" : false,
    copyOn: !(bar.querySelector('[data-testid="term-key-copy"]') || {}).disabled,
  };
})()`;
interface KeyBarState {
  h: number;
  copy: boolean;
  paste: boolean;
  select: boolean;
  more: boolean;
  scroll: { left: number; w: number; sw: number } | null;
  arrows: boolean;
  pressed: string | null;
  ink: boolean;
  copyOn: boolean;
}
/** The Terminal's screen as one string: its rows run together, so a word that wraps in a narrow pane is still found. */
const TERM_TEXT = `[...document.querySelectorAll('[data-testid="terminal-pane"] .xterm-rows > div')].map((d) => d.textContent.replace(/\\s+$/, "")).join("")`;

/**
 * key-bar (T-12, Q12's default; G-17, G-46): the Terminal's key bar is one row under 60 px; Copy and Paste are in view
 * at rest; Select is in view at rest, or the scrolling part is marked data-more and one sideways scroll brings it whole
 * into view; it scrolls to the arrows; Select then a drag selects, Copy writes the selection; Paste sends the
 * clipboard's text into the shell (its echo shows it); a pressed key has its ink mark.
 */
async function keyBarFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const path = `/c/${EX.chat}/shell`;
  return touchFlow({ name: "key-bar", route: "shell", scene, vp, theme, path }, async ({ page, fail, details, shot }) => {
    await page.navigate(base + path);
    await waitShown(page, ["terminal-pane", "terminal-keys"]);
    await grantClipboard(page, base);
    await waitTrue(page, `${TERM_TEXT}.trim().length > 0`, 6000);
    const rest = await page.evaluate<KeyBarState | null>(KEY_BAR);
    details.rest = rest;
    if (!rest) {
      fail("shows", "the Terminal shows no key bar");
      return "no key bar";
    }
    if (rest.h >= 60) fail("flow", `the key bar is ${rest.h} px tall, not one row`);
    if (!rest.copy || !rest.paste) fail("flow", `at rest ${!rest.copy ? "Copy" : "Paste"} is not in view`);
    if (vp.name === "phone" && !rest.more) fail("flow", "at 390 the scrolling part is not marked data-more at rest");
    if (!rest.select) {
      if (!rest.more) fail("flow", "Select is out of view at rest and the scrolling part has no data-more");
      // One sideways scroll: the least scroll that shows Select whole must be at most the part's own width.
      const need = await page.evaluate<{ need: number; w: number }>(`(() => { const sc = document.querySelector('[data-testid="terminal-keys"] .term-keys-scroll'); const s = document.querySelector('[data-testid="term-key-select"]'); const need = Math.ceil(s.getBoundingClientRect().right - sc.getBoundingClientRect().right + 1); sc.scrollTo({ left: sc.scrollLeft + need, behavior: "instant" }); return { need, w: sc.clientWidth }; })()`);
      await sleep(400);
      const one = await page.evaluate<KeyBarState>(KEY_BAR);
      details.oneScroll = need;
      if (need.need > need.w || !one.select) fail("flow", `Select needs a scroll of ${need.need} px in a ${need.w} px part, more than one sideways scroll`);
    }
    await shot("rest");
    await page.evaluate(`(() => { const sc = document.querySelector('[data-testid="terminal-keys"] .term-keys-scroll'); sc.scrollTo({ left: sc.scrollWidth, behavior: "instant" }); })()`);
    await sleep(400);
    const end = await page.evaluate<KeyBarState>(KEY_BAR);
    details.end = end;
    if (!end.arrows) fail("flow", "the key bar does not scroll to the arrows");
    if (end.more) fail("flow", "at the scrolling part's end it is still marked data-more");
    await page.evaluate(`document.querySelector('[data-testid="term-key-select"]').scrollIntoView({ inline: "nearest", block: "nearest", behavior: "instant" })`);
    await sleep(400);
    await tapOn(page, '[data-testid="term-key-select"]');
    const on = await page.evaluate<KeyBarState>(KEY_BAR);
    details.select = on;
    if (on.pressed !== "true") fail("flow", "Select does not turn on");
    if (!on.ink) fail("flow", "the pressed Select has no ink mark");
    // A finger's drag over the first rows of the screen.
    const area = await page.evaluate<{ x: number; y: number; x2: number } | null>(`(() => { const r = document.querySelector('[data-testid="terminal-pane"] .xterm-screen'); if (!r) return null; const b = r.getBoundingClientRect(); return { x: b.left + 6, y: b.top + 8, x2: Math.min(b.right - 6, b.left + 220) }; })()`);
    if (area) {
      const pt = (x: number) => [{ x, y: area.y, radiusX: 4, radiusY: 4, force: 1 }];
      await page.send("Input.dispatchTouchEvent", { type: "touchStart", touchPoints: pt(area.x) });
      for (let i = 1; i <= 8; i++) {
        await page.send("Input.dispatchTouchEvent", { type: "touchMove", touchPoints: pt(area.x + ((area.x2 - area.x) * i) / 8) });
        await sleep(30);
      }
      await page.send("Input.dispatchTouchEvent", { type: "touchEnd", touchPoints: [] });
      await sleep(400);
    }
    const sel = await page.evaluate<KeyBarState>(KEY_BAR);
    if (!sel.copyOn) fail("flow", "a drag with Select on selects nothing (Copy stays off)");
    else {
      await tapOn(page, '[data-testid="term-key-copy"]');
      const clip = await readClipboard(page);
      details.copied = clip;
      if (!clip || !clip.trim()) fail("copy", "Copy wrote nothing");
    }
    await tapOn(page, '[data-testid="term-key-select"]');
    const word = `kitespan-paste-${sizeTag(vp)}`;
    await writeClipboard(page, `echo ${word}`);
    await tapOn(page, '[data-testid="term-key-paste"]', 600);
    const echoed = await waitTrue<boolean>(page, `${TERM_TEXT}.includes(${JSON.stringify(word)})`, 4000);
    if (!echoed) fail("flow", "Paste does not type the clipboard's text into the shell");
    await shot("after");
    return `one row of ${rest.h} px; Copy and Paste in view; Select ${rest.select ? "in view" : "one scroll away"}; a drag and Copy; Paste typed`;
  });
}

/** The pane bar's buttons that open a docked pane (the Browser opens over the chat at 834: browser-pane checks it). */
const BAR_PANES = ["Details", "Files", "Terminal", "Search", "Side chat"] as const;
/** The docked pane's and the over-chat panes' boxes, and the shell's marks. */
const PANES_NOW = `(() => {
  const vis = (e) => e.getClientRects().length > 0 && getComputedStyle(e).visibility !== "hidden";
  const box = (e) => { const r = e.getBoundingClientRect(); return { left: Math.round(r.left), right: Math.round(r.right), top: Math.round(r.top), bottom: Math.round(r.bottom), width: Math.round(r.width) }; };
  const panes = [...document.querySelectorAll("aside.side-pane")].filter(vis).filter((p) => !p.closest("[inert]"));
  const slab = [...document.querySelectorAll('[data-testid="composer"] .cmp-slab')].find(vis);
  const dock = [...document.querySelectorAll(".cmp-dock")].find(vis);
  const keys = slab ? [...slab.querySelectorAll(".cmp-keys > *, .cmp-bar-end > *")].filter(vis).map((k) => ({ id: k.getAttribute("data-testid") || k.getAttribute("aria-label") || k.className.split(" ")[0], ...box(k) })) : [];
  const send = document.querySelector('[data-testid="composer-send"]');
  let sendFree = null;
  if (send && vis(send)) { const r = send.getBoundingClientRect(); const at = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2); sendFree = !!at && (at === send || send.contains(at)); }
  return {
    path: location.pathname + location.search,
    panes: panes.map((p) => ({ cls: p.className, over: p.classList.contains("side-over"), split: p.classList.contains("split"), ...box(p) })),
    lit: [...document.querySelectorAll(".pane-bar-btn.on")].map((b) => b.textContent.trim()),
    slab: slab ? box(slab) : null,
    dock: dock ? box(dock) : null,
    keys,
    sendFree,
    over: document.querySelector(".shell")?.getAttribute("data-over") ?? null,
    drawer: (() => { const d = [...document.querySelectorAll(".shell-drawer, .scr-drawer")].find(vis); return d ? box(d) : null; })(),
  };
})()`;
interface PanesNow {
  path: string;
  panes: { cls: string; over: boolean; split: boolean; left: number; right: number; top: number; bottom: number; width: number }[];
  lit: string[];
  slab: { left: number; right: number; top: number; bottom: number; width: number } | null;
  dock: { left: number; right: number; top: number; bottom: number; width: number } | null;
  keys: { id: string; left: number; right: number; top: number; bottom: number }[];
  sendFree: boolean | null;
  over: string | null;
  drawer: { left: number; right: number; width: number } | null;
}
const panesNow = (page: Page) => page.evaluate<PanesNow>(PANES_NOW);
/** The medium pane's width at a window width (web/layout/panes.ts mediumPaneWidth: 40% under 800 px, else 320). */
const mediumPane = (w: number) => (w < 800 ? Math.round(w * 0.4) : 320);

/**
 * d26 (D26, the owner's medium layout; PROBE 4.1): at 626, 768 and 834 each pane bar button opens one docked pane at
 * 250, 307 and 320 px; a second button splits it; a lit button closes its view; the chats button opens the drawer at
 * 320 px, and a tap on its scrim closes it.
 */
async function d26Flow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const path = `/c/${EX.chat}`;
  return touchFlow({ name: "d26", route: "details", scene, vp, theme, path }, async ({ page, fail, details, shot }) => {
    await page.navigate(base + path);
    await waitShown(page, ["conversation"]);
    const want = mediumPane(vp.width);
    const seen: Record<string, number> = {};
    for (const name of BAR_PANES) {
      if (!(await tapOn(page, `.pane-bar-btn[title="${name}"]`, 500))) {
        if (name !== "Side chat") fail("shows", `the pane bar has no ${name}`);
        continue;
      }
      const s = await panesNow(page);
      const docked = s.panes.filter((p) => !p.over);
      seen[name] = docked[0]?.width ?? 0;
      if (docked.length !== 1 || Math.abs(docked[0]!.width - want) > 2) fail("flow", `${name} gives ${docked.length} docked pane(s) of ${docked.map((p) => p.width).join(", ")} px, not one of ${want}`);
      if (!s.lit.includes(name)) fail("flow", `${name} is not lit while its pane shows`);
      await tapOn(page, ".pane-bar-btn.on", 500);
      const after = await panesNow(page);
      if (after.panes.some((p) => !p.over) || !sameUrl(after.path, path)) fail("flow", `the lit ${name} does not close its pane (${after.path})`);
    }
    details.widths = seen;
    // Two buttons: one pane, split in two views.
    await tapOn(page, '.pane-bar-btn[title="Details"]', 500);
    await tapOn(page, '.pane-bar-btn[title="Terminal"]', 700);
    const two = await panesNow(page);
    details.split = two;
    if (!two.panes.some((p) => p.split) || two.lit.length !== 2) fail("flow", `a second button gives ${two.panes.length} pane(s), lit ${two.lit.join(", ")}, not one split pane`);
    await shot("split");
    await tapOn(page, '.pane-bar-btn[title="Close Terminal"]', 500);
    const one = await panesNow(page);
    if (one.lit.join() !== "Details") fail("flow", `closing the Terminal's half leaves ${one.lit.join(", ") || "nothing"} lit`);
    await tapOn(page, '.pane-bar-btn[title="Close Details"]', 500);
    // The chat list as a drawer, and its scrim.
    if (!(await tapOn(page, ".scr-bar-chats", 600))) fail("shows", "the band has no chats button");
    const d = await panesNow(page);
    details.drawer = d.drawer;
    if (!d.drawer || Math.abs(d.drawer.width - 320) > 2) fail("flow", `the chat list drawer is ${d.drawer?.width ?? "not shown"} px, not 320`);
    if (d.drawer) {
      await page.press(Math.round((d.drawer.right + vp.width) / 2), Math.round(vp.height / 2));
      await sleep(500);
      if ((await panesNow(page)).drawer) fail("flow", "a tap on the drawer's scrim does not close it");
    }
    return `panes at ${Object.values(seen).join(", ")} px, a split, the drawer at ${d.drawer?.width ?? 0} px`;
  });
}

/**
 * changes-over (T-17, Q1's default): at 626 and 768 a changes row opens over the chat at the whole width beside the
 * pane bar (570 and 712 px); at 834 it docks at 320 px; Close changes closes it. At 626 with ?below=shell the layer
 * shows the changes view alone, the URL keeps below=shell, and closing it shows the Terminal in the docked pane.
 */
async function changesOverFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const path = ROUTE.changesFile!.example;
  return touchFlow({ name: "changes-over", route: "changesFile", scene, vp, theme, path }, async ({ page, fail, details, shot }) => {
    await page.navigate(base + path);
    await waitShown(page, ["changes-view|changes-card"]);
    const s = await panesNow(page);
    details.opened = s;
    const narrow = vp.width < 800;
    const over = s.panes.find((p) => p.cls.includes("chg-over-chat"));
    if (narrow) {
      if (!over) fail("flow", "the changes view does not open over the chat");
      else if (Math.abs(over.width - (vp.width - 56)) > 2) fail("flow", `the changes layer is ${over.width} px, not ${vp.width - 56}`);
    } else {
      const docked = s.panes.find((p) => !p.over);
      if (over || !docked || Math.abs(docked.width - 320) > 2) fail("flow", `at 834 the changes view is ${over ? "over the chat" : `docked at ${docked?.width}`} px, not docked at 320`);
    }
    await shot("open");
    await tapOn(page, '[aria-label="Close changes"]', 600);
    const closed = await panesNow(page);
    if (closed.panes.some((p) => p.cls.includes("chg"))) fail("flow", "Close changes leaves the changes view");
    if (vp.label === "m626") {
      const pair = `${path}?below=shell`;
      await page.navigate(base + pair);
      await waitShown(page, ["changes-view|changes-card"]);
      const p = await panesNow(page);
      details.pair = p;
      if (!p.path.includes("below=shell")) fail("url", `the pair's URL became ${p.path}`);
      if (!p.panes.some((x) => x.cls.includes("chg-over-chat"))) fail("flow", "with the pair the changes view is not over the chat");
      await tapOn(page, '[aria-label="Close changes"]', 900);
      const term = await page.evaluate<boolean>(`[...document.querySelectorAll('[data-testid="terminal-pane"]')].some((e) => e.getClientRects().length && !e.closest("[inert]"))`);
      if (!term) fail("flow", "closing the pair's changes layer does not show the Terminal in the docked pane");
    }
    return narrow ? `over the chat at ${over?.width} px; Close changes closes it` : "docked at 320 px; Close changes closes it";
  });
}

/**
 * large-composer (T-15, Q8; at large): each pane bar button's pane over the chat ends above the composer's dock at
 * rest and the point at Send's centre is Send; with the Terminal over the chat, three lines typed in the box leave the
 * Terminal's rows as they were.
 */
async function largeComposerFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const path = `/c/${EX.chat}`;
  return touchFlow({ name: "large-composer", route: "details", scene, vp, theme, path }, async ({ page, fail, details, shot }) => {
    await page.navigate(base + path);
    await waitShown(page, ["conversation", "composer"]);
    const seen: Record<string, unknown> = {};
    for (const name of BAR_PANES) {
      if (!(await tapOn(page, `.pane-bar-btn[title="${name}"]`, 600))) continue;
      const s = await panesNow(page);
      const o = s.panes.find((p) => p.over);
      seen[name] = { pane: o?.bottom, dock: s.dock?.top, send: s.sendFree };
      if (!o) fail("flow", `${name} does not open over the chat`);
      else if (s.dock && o.bottom > s.dock.top) fail("flow", `${name}'s pane ends at ${o.bottom} px, under the composer's top at ${s.dock.top}`);
      if (s.sendFree === false) fail("control-out", `with ${name} over the chat the point at Send's centre is not Send`);
      if (name === "Terminal") {
        await shot("terminal");
        const rows = () => page.evaluate<number>(`document.querySelectorAll('[data-testid="terminal-pane"] .xterm-rows > div').length`);
        const before = await rows();
        if (await tapOn(page, '[data-testid="composer-input"]')) {
          for (const line of ["one", "two", "three"]) {
            await page.send("Input.insertText", { text: line });
            await page.send("Input.dispatchKeyEvent", { type: "keyDown", key: "Enter", code: "Enter", windowsVirtualKeyCode: 13, modifiers: 8, text: "\r" });
            await page.send("Input.dispatchKeyEvent", { type: "keyUp", key: "Enter", code: "Enter", windowsVirtualKeyCode: 13, modifiers: 8 });
          }
          await sleep(500);
          const after = await rows();
          seen.rows = [before, after];
          if (after !== before) fail("flow", `three lines in the box changed the Terminal's rows from ${before} to ${after}`);
          // The box empties again (the example chat's draft is the server's).
          await page.evaluate(`(() => { const f = document.querySelector('[data-testid="composer-input"]'); f.select(); })()`);
          await page.send("Input.dispatchKeyEvent", { type: "keyDown", key: "Backspace", code: "Backspace", windowsVirtualKeyCode: 8 });
          await page.send("Input.dispatchKeyEvent", { type: "keyUp", key: "Backspace", code: "Backspace", windowsVirtualKeyCode: 8 });
          await page.evaluate(`document.activeElement && document.activeElement.blur()`);
          await sleep(400);
        }
      }
      await tapOn(page, ".pane-bar-btn.on", 500);
    }
    details.panes = seen;
    return `each pane over the chat ends above the composer; Send free; the Terminal's rows kept`;
  });
}

/**
 * composer-fit (T-16, G-25; 626, 768, 834 and large): with each pane bar button's pane, in each key state the seeds
 * hold (idle: Send, and Run in Bash mode; running, with a draft: Stop and Send, and Stop and Run; held by a session
 * open elsewhere: Continue in a copy), every key of the composer lies inside its slab and left of a docked pane, and
 * control-out finds nothing in the composer. (Send again and the finishing hold's Stop alone: see INTEGRATE.md.)
 */
async function composerFitFlow(base: string, scene: SeedSceneName | null, vp: Viewport, theme: Theme, state: "idle" | "running" | "held" = "idle", chat: string = EX.chat): Promise<CheckResult> {
  const path = `/c/${chat}`;
  return touchFlow({ name: "composer-fit", route: "details", scene, vp, theme, path }, async ({ page, fail, details, shot }) => {
    await page.navigate(base + path);
    await waitShown(page, ["conversation", "composer"]);
    // While a turn runs, a draft brings Send beside Stop (the phone's one key aside: composer-fit is not the phone's).
    if (state === "running" && (await tapOn(page, '[data-testid="composer-input"]'))) {
      await page.send("Input.insertText", { text: "A draft beside Stop" });
      await page.evaluate(`document.activeElement && document.activeElement.blur()`);
      await sleep(400);
    }
    const out: Record<string, unknown> = {};
    const check = async (what: string) => {
      const s = await panesNow(page);
      const m = await page.evaluate<TouchMeasures>(TOUCH_MEASURES);
      const docked = s.panes.find((p) => !p.over);
      const bad: string[] = [];
      for (const k of s.keys) {
        if (s.slab && (k.left < s.slab.left - 1 || k.right > s.slab.right + 1 || k.top < s.slab.top - 1 || k.bottom > s.slab.bottom + 1)) bad.push(`${k.id} (${k.left}-${k.right}) out of the slab (${s.slab.left}-${s.slab.right})`);
        if (docked && k.right > docked.left + 1) bad.push(`${k.id} runs under the pane at ${docked.left}`);
      }
      const co = [...m.controlBox, ...m.controlPoint].filter((x) => /composer|cmp|Model|Permission|Send|Stop|Run/.test(x));
      out[what] = { keys: s.keys.map((k) => `${k.id} ${k.left}-${k.right}`), slab: s.slab, bad, co };
      if (bad.length) fail("control-out", `${what}: ${clipList(bad, 3)}`);
      if (co.length) fail("control-out", `${what}: ${clipList(co, 3)}`);
    };
    for (const name of [null, ...BAR_PANES]) {
      if (name && !(await tapOn(page, `.pane-bar-btn[title="${name}"]`, 600))) continue;
      await check(`${state}${name ? ` beside ${name}` : ""}`);
      if (name === "Details") await shot(state);
      if (name) await tapOn(page, ".pane-bar-btn.on", 500);
    }
    // Bash mode beside Details: "!" in the empty box puts the box in Bash mode with Run in Send's place.
    if (state === "running" && (await tapOn(page, '[data-testid="composer-input"]'))) await emptyField(page);
    if (state !== "held" && (await tapOn(page, '.pane-bar-btn[title="Details"]', 600))) {
      if (await tapOn(page, '[data-testid="composer-input"]')) {
        await page.send("Input.insertText", { text: "!" });
        await sleep(300);
        await check(`${state} in Bash mode beside Details`);
        await page.send("Input.dispatchKeyEvent", { type: "keyDown", key: "Backspace", code: "Backspace", windowsVirtualKeyCode: 8 });
        await page.send("Input.dispatchKeyEvent", { type: "keyUp", key: "Backspace", code: "Backspace", windowsVirtualKeyCode: 8 });
        await page.evaluate(`document.activeElement && document.activeElement.blur()`);
        await sleep(400);
      }
      await tapOn(page, '.pane-bar-btn[title="Close Details"]', 500);
    }
    details.states = out;
    return `${Object.keys(out).length} composer states, every key inside its slab`;
  });
}

/**
 * column-form (T-28, G-47, G-33; the large tablet with Hide sidebar, and 1366x1024): a chat with Details and the
 * Terminal below it shows the side column and its split with the touch divider; the title is whole or has at least
 * 40% of the band; no tool of the title bar lies out of the band; the title bar's Search (where the sidebar is hidden)
 * opens the search view.
 */
async function columnFormFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const path = `/c/${EX.chat}/details?below=shell`;
  return touchFlow({ name: "column-form", route: "shell", scene, vp, theme, path }, async ({ page, fail, details, shot }) => {
    await page.navigate(base + path);
    await waitShown(page, ["side-environment", "terminal-pane"]);
    const st = await page.evaluate<{ col: boolean; divider: boolean; tight: boolean; search: boolean; sidebar: boolean }>(`(() => {
      const vis = (e) => !!e && e.getClientRects().length > 0;
      return {
        col: [...document.querySelectorAll(".side-col.split, .side-pane.split")].some(vis),
        divider: vis(document.querySelector('[data-testid="split-divider"]')),
        tight: !!document.querySelector(".main-col > .topbar[data-tight], .topbar[data-tight]"),
        search: vis(document.querySelector('[data-testid="topbar-search"]')),
        sidebar: vis(document.querySelector('[data-testid="sidebar"]')),
      };
    })()`);
    const m = await page.evaluate<TouchMeasures>(TOUCH_MEASURES);
    details.state = st;
    details.measures = { nameCut: m.nameCut, controlBox: m.controlBox };
    if (!st.col) fail("flow", "Details and the Terminal do not show as the side column's split");
    if (!st.divider) fail("flow", "the split shows no divider");
    const title = m.nameCut.filter((x) => x.startsWith("title"));
    if (title.length) fail("name-cut", `the chat title gives way past T-28's rule: ${title.join(", ")}`);
    const bar = m.controlBox.filter((x) => x.includes("out of topbar"));
    if (bar.length) fail("control-out", `a title bar tool is out of the band: ${clipList(bar, 3)}`);
    await shot("column");
    if (!st.sidebar && !st.search) fail("named-touch", "the sidebar is hidden and the title bar has no Search");
    if (st.search) {
      await tapOn(page, '[data-testid="topbar-search"]', 700);
      if (!(await page.probe()).ids.includes("search")) fail("flow", "the title bar's Search does not open the search view");
    }
    return `the column's split with its divider; the title ${st.tight ? "beside icons (tight)" : "beside named tools"}; Search ${st.search ? "in the title bar" : "in the sidebar"}`;
  });
}

const SESSION_BUTTON = '[aria-label^="Session menu"]';
/** Empty the focused field (select all, then Backspace) and let it go, so a chat's draft stays as the seed has it. */
async function emptyField(page: Page) {
  await page.evaluate(`(() => { const f = document.activeElement; if (f && "select" in f) f.select(); })()`);
  await page.send("Input.dispatchKeyEvent", { type: "keyDown", key: "Backspace", code: "Backspace", windowsVirtualKeyCode: 8 });
  await page.send("Input.dispatchKeyEvent", { type: "keyUp", key: "Backspace", code: "Backspace", windowsVirtualKeyCode: 8 });
  await sleep(300);
  await page.evaluate(`document.activeElement && document.activeElement.blur && document.activeElement.blur()`);
  await sleep(400);
}
const ACTIVE_IN = (sel: string) => `(() => { const a = document.activeElement; const f = [...document.querySelectorAll(${JSON.stringify(sel)})].find((e) => e.getClientRects().length); return !!a && !!f && (a === f || f.contains(a)); })()`;

/** The fields of keyboard-release, each with its page and the selector of the field (or of the part a tap focuses). */
const RELEASE_FIELDS: { id: string; path: string; tap: string; field: string; clean: boolean }[] = [
  { id: "message box", path: `/c/${EX.chat}`, tap: '[data-testid="composer-input"]', field: '[data-testid="composer-input"]', clean: true },
  { id: "new-chat box", path: "/new", tap: '[data-testid="new-chat"] textarea', field: '[data-testid="new-chat"] textarea', clean: true },
  { id: "side chat box", path: `/c/${EX.chat}/btw`, tap: '[data-testid="side-input"]', field: '[data-testid="side-input"]', clean: true },
  { id: "search field", path: `/c/${EX.chat}/search`, tap: '[data-testid="search"] input', field: '[data-testid="search"] input', clean: true },
  { id: "rename", path: `/c/${EX.chat}/rename`, tap: '[data-testid="dialog-rename"] input', field: '[data-testid="dialog-rename"] input', clean: false },
  { id: "Terminal", path: `/c/${EX.chat}/shell`, tap: '[data-testid="terminal-pane"] .xterm-screen', field: '[data-testid="terminal-pane"] .xterm-helper-textarea', clean: false },
];

/**
 * keyboard-release (T-19, G-5, G-7): for each field, with the stand-in keyboard: focus, type, keyboard up, keyboard
 * down: 450 ms later the field has let go; a tap on the field within the 450 ms keeps it. (A waiting card's Deny note
 * and the browser pane's fields need the permission scene and the shared browser: INTEGRATE.md says which runs.)
 */
async function keyboardReleaseFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const kb = vp.name === "phone" ? 336 : 400;
  return touchFlow({ name: "keyboard-release", route: "chat", scene, vp, theme, path: `/c/${EX.chat}`, pre: [STAND_IN_KEYBOARD] }, async ({ page, wire, fail, details, shot }) => {
    const out: Record<string, unknown> = {};
    const since = wire.mark();
    for (const f of RELEASE_FIELDS) {
      await page.navigate(base + f.path);
      await sleep(600);
      if (!(await tapOn(page, f.tap, 300)) || !(await page.evaluate<boolean>(ACTIVE_IN(f.field)))) {
        fail("shows", `the ${f.id} takes no focus from a tap`);
        continue;
      }
      await page.send("Input.insertText", { text: "abc" });
      const cycle = async (keep: boolean) => {
        await page.evaluate(`window.__standInKeyboard(${kb})`);
        await sleep(300);
        await page.evaluate(`window.__standInKeyboard(0)`);
        if (keep) {
          await sleep(200);
          await tapOn(page, f.tap, 50);
        }
        await sleep(900);
        return page.evaluate<boolean>(ACTIVE_IN(f.field));
      };
      const released = !(await cycle(false));
      await tapOn(page, f.tap, 300);
      const kept = await cycle(true);
      out[f.id] = { released, kept };
      if (!released) fail("flow", `the ${f.id} keeps the focus 900 ms after the keyboard went down`);
      if (!kept) fail("flow", `a tap on the ${f.id} within 450 ms does not keep its focus`);
      if (f.id === "message box") await shot("released");
      if (f.clean) await emptyField(page);
      else await page.evaluate(`document.activeElement && document.activeElement.blur && document.activeElement.blur()`);
    }
    details.fields = out;
    const sent = sentOf(wire, since, ["send", "bash", "new_chat", "side_ask"]);
    if (sent.length) fail("frames", `the fields sent ${clipList(sent.map(frameText))}`);
    return `${Object.keys(out).length} fields let go 450 ms after the keyboard; a tap on the field keeps it`;
  });
}

/**
 * ime-touch (T-18, G-9, Q3; a main scene seed of its own, since it sends): "hello " then an input method's marked "ni"
 * and Enter with key code 229 sends nothing and keeps "hello ni"; the commit and Enter send; Enter with 229 and no
 * composition (dictation) sends; in the search pane's field the composing Enter opens no hit and keeps the text.
 */
async function imeTouchFlow(t: Target, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const path = `/c/${EX.chat}`;
  return touchFlow({ name: "ime-touch", route: "send", scene: t.scene, vp, theme, path }, async ({ page, wire, fail, details }) => {
    await page.navigate(t.base + path);
    await waitShown(page, ["composer"]);
    const enter = async (code: number) => {
      await page.send("Input.dispatchKeyEvent", { type: "rawKeyDown", key: "Enter", code: "Enter", windowsVirtualKeyCode: code, nativeVirtualKeyCode: code });
      // No char event: during a composition the input method takes the key, and the app acts on keydown.
      await page.send("Input.dispatchKeyEvent", { type: "keyUp", key: "Enter", code: "Enter", windowsVirtualKeyCode: code, nativeVirtualKeyCode: code });
    };
    const value = () => page.evaluate<string>(`document.querySelector('[data-testid="composer-input"]').value`);
    await tapOn(page, '[data-testid="composer-input"]');
    const m0 = wire.mark();
    await page.send("Input.insertText", { text: "hello " });
    await page.send("Input.imeSetComposition", { text: "ni", selectionStart: 2, selectionEnd: 2 });
    await enter(229);
    await sleep(500);
    const composing = await value();
    details.composing = composing;
    if (sentOf(wire, m0, ["send"]).length) fail("flow", "an Enter during the composition sent the message");
    if (composing !== "hello ni") fail("flow", `during the composition the box holds "${composing}", not "hello ni"`);
    await page.send("Input.insertText", { text: "你" });
    await sleep(250);
    await enter(13);
    await sleep(800);
    const s1 = sentOf(wire, m0, ["send"]);
    details.sent = s1.map((f) => f.frame.text);
    if (s1.length !== 1 || s1[0]!.frame.text !== "hello 你") fail("flow", `after the commit Enter sent ${s1.length} message(s): ${clipList(s1.map((f) => JSON.stringify(f.frame.text)))}`);
    const m1 = wire.mark();
    await tapOn(page, '[data-testid="composer-input"]');
    await page.send("Input.insertText", { text: "dictated words" });
    await sleep(200);
    await enter(229);
    await sleep(800);
    const s2 = sentOf(wire, m1, ["send"]);
    if (s2.length !== 1 || s2[0]!.frame.text !== "dictated words") fail("flow", `a dictated message's Enter (229, no composition) sent ${s2.length} message(s)`);
    // The search pane's field.
    await page.navigate(t.base + `/c/${EX.chat}/search?q=up`);
    await waitShown(page, ["search"]);
    const before = (await page.probe()).path;
    await tapOn(page, '[data-testid="search"] input');
    await page.send("Input.imeSetComposition", { text: "ni", selectionStart: 2, selectionEnd: 2 });
    await enter(229);
    await sleep(500);
    const after = await page.probe();
    const field = await page.evaluate<string>(`document.querySelector('[data-testid="search"] input').value`);
    details.search = { before, after: after.path, field };
    if (!samePath(after.path, before)) fail("flow", `the composing Enter in search opened ${after.path}`);
    if (!field.endsWith("ni")) fail("flow", `the search field holds "${field}" after the composing Enter`);
    await page.send("Input.imeSetComposition", { text: "", selectionStart: 0, selectionEnd: 0 });
    return "a composing Enter waits; the commit's Enter and a dictated one send; search keeps the marked text";
  });
}

/**
 * stop-menu (T-4, G-10, G-11, Q5; a seed per size of the running scene and of the permission scene): while a turn runs
 * Stop is the session menu's first row and opens /c/<chat>/stop, whose Stop ends the turn with the draft kept; at 390 +
 * > Stop does the same (a new turn started from the box); with a permission card waiting the session menu's Stop and
 * the card's foot Stop open the same confirm, and its Stop answers the card.
 */
async function stopMenuFlow(t: Target, vp: Viewport, theme: Theme, kind: "running" | "permission"): Promise<CheckResult> {
  const path = `/c/${EX.chat}`;
  return touchFlow({ name: "stop-menu", route: "stop", scene: t.scene, vp, theme, path }, async ({ page, fail, details, shot }) => {
    await page.navigate(t.base + path);
    await waitShown(page, [kind === "running" ? "composer" : "card-permission"]);
    const draft = async (text: string) => {
      await tapOn(page, '[data-testid="composer-input"]');
      await page.send("Input.insertText", { text });
      await page.evaluate(`document.activeElement && document.activeElement.blur()`);
      await sleep(400);
    };
    const confirm = async (what: string) => {
      const s = await page.probe();
      if (!s.path.startsWith(`/c/${EX.chat}/stop`) || !s.ids.includes("dialog-stop")) {
        fail("flow", `${what} gives ${s.path}, not the Stop confirm`);
        return false;
      }
      await tapOn(page, '[data-testid="confirm-stop"]', 800);
      return true;
    };
    const idle = () => waitTrue<boolean>(page, `!document.querySelector('[data-testid="composer-stop"]') && !document.querySelector('[data-testid="card-permission"]')`, 8000);
    const menuFirst = async () => {
      await tapOn(page, SESSION_BUTTON, 400);
      const m = await waitTrue<{ items: string[] }>(page, SESSION_MENU, 1500);
      details.menu = m?.items;
      if (m?.items[0] !== "menu-stop") fail("flow", `the session menu's first row is ${m?.items[0] ?? "nothing"}, not Stop`);
      await shot(`${kind}-menu`);
      return !!m?.items.includes("menu-stop");
    };
    if (kind === "running") {
      await draft("Keep this draft");
      if (await menuFirst()) {
        await tapOn(page, '[data-testid="menu-stop"]', 600);
        if (await confirm("Session menu > Stop")) {
          if (!(await idle())) fail("flow", "Stop does not end the turn");
          const kept = await page.evaluate<string>(`document.querySelector('[data-testid="composer-input"]')?.value ?? ""`);
          if (kept !== "Keep this draft") fail("flow", `after Stop the box holds "${kept}"`);
        }
      }
      if (vp.name === "phone") {
        await emptyField(page);
        await tapOn(page, '[data-testid="composer-input"]');
        await page.send("Input.insertText", { text: "full upload suite" });
        await tapOn(page, '[data-testid="composer-send"]', 1500);
        await waitTrue(page, `!!document.querySelector('[data-testid="composer-stop"]')`, 6000);
        await draft("Second draft");
        await tapOn(page, '[data-testid="composer-plus"]', 500);
        const first = await page.evaluate<string | null>(`(() => { const r = [...document.querySelectorAll('[data-testid^="plus-"]:not([data-testid="plus-menu"])')].find((e) => e.getClientRects().length); return r ? r.getAttribute("data-testid") : null; })()`);
        details.plusFirst = first;
        if (first !== "plus-stop") fail("flow", `the + sheet's first row is ${first} while a turn runs, not Stop`);
        await shot("plus");
        if (first === "plus-stop") {
          await tapOn(page, '[data-testid="plus-stop"]', 600);
          if (await confirm("+ > Stop")) {
            if (!(await idle())) fail("flow", "+ > Stop does not end the turn");
            const kept = await page.evaluate<string>(`document.querySelector('[data-testid="composer-input"]')?.value ?? ""`);
            if (kept !== "Second draft") fail("flow", `after + > Stop the box holds "${kept}"`);
          }
        }
      }
    } else {
      if (await menuFirst()) {
        await tapOn(page, '[data-testid="menu-stop"]', 600);
        const s = await page.probe();
        if (!s.ids.includes("dialog-stop")) fail("flow", "the session menu's Stop opens no confirm over the card");
        await escape(page);
      }
      if (!(await tapOn(page, '[data-testid="card-stop"]', 600))) fail("shows", "the waiting card has no Stop at its foot");
      else if (await confirm("the card's Stop")) {
        if (!(await idle())) fail("flow", "the card's Stop does not answer the card and end the turn");
      }
    }
    return kind === "running" ? `Stop first in the session menu${vp.name === "phone" ? " and the + sheet" : ""}; the turn stops, the draft stays` : "the session menu's and the card's Stop open the confirm; the card is answered";
  });
}

/** Open on phone's tile: its encoded text, whether it is black on white, and the link and Copy link beside it. */
const PHONE_STATE = `(() => {
  const vis = (e) => !!e && e.getClientRects().length > 0;
  const tile = document.querySelector('[data-testid="phone-code"]');
  const link = document.querySelector('[data-testid="phone-link"]');
  const copy = document.querySelector('[data-testid="phone-copy"]');
  const line = document.querySelector('[data-testid="phone-line"]');
  const sheet = tile ? tile.closest(".sheet") : null;
  const path = tile ? tile.querySelector("svg path") : null;
  const svg = tile ? tile.querySelector("svg") : null;
  const box = (e) => { const r = e.getBoundingClientRect(); return { left: r.left, right: r.right, top: r.top, bottom: r.bottom }; };
  let copyHit = null;
  if (vis(copy)) { const r = copy.getBoundingClientRect(); const at = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2); copyHit = !!at && (at === copy || copy.contains(at)); }
  return {
    text: tile ? tile.getAttribute("data-text") : null,
    link: link ? link.textContent : null,
    line: vis(line) ? line.textContent.trim() : null,
    fill: path ? getComputedStyle(path).fill : null,
    bg: svg ? [getComputedStyle(tile).backgroundColor, getComputedStyle(svg).backgroundColor, (svg.querySelector("rect") || {}).getAttribute ? svg.querySelector("rect").getAttribute("fill") : null] : null,
    tile: vis(tile) ? box(tile) : null,
    linkBox: vis(link) ? box(link) : null,
    sheet: sheet ? { h: sheet.clientHeight, sh: sheet.scrollHeight } : null,
    copyHit,
  };
})()`;
interface PhoneState {
  text: string | null;
  link: string | null;
  line: string | null;
  fill: string | null;
  bg: (string | null)[] | null;
  tile: { left: number; right: number; top: number; bottom: number } | null;
  linkBox: { left: number; right: number; top: number; bottom: number } | null;
  sheet: { h: number; sh: number } | null;
  copyHit: boolean | null;
}
const PHONE_ORIGIN = "https://phone.example.test";
const PHONE_LINK_FORM = "https://open.example.test/?u={url}";

/**
 * open-on-phone (T-14, T-32, G-22; seeds of its own: with a remote origin, with it and a link form, and with none):
 * the item is absent at 390; from Details, Session menu > Open on phone opens /c/<chat>/phone with a tile of black
 * modules on white whose data-text is the origin plus /c/<chat>/details, equal to the link under it, and Copy link
 * writes it; after a reload the same; with the link form the tile holds the filled form and the link the plain one;
 * with no origin the one line; no token and no host path; on a phone on its side, opened directly, the tile is left of
 * the link, the sheet has no scroll and Copy link takes a tap at its centre.
 */
async function openOnPhoneFlow(t: Target, vp: Viewport, theme: Theme, form: "plain" | "template" | "none"): Promise<CheckResult> {
  const details0 = `/c/${EX.chat}/details`;
  const path = `/c/${EX.chat}/phone`;
  return touchFlow({ name: "open-on-phone", route: "phone", scene: t.scene, vp, theme, path }, async ({ page, fail, details, shot }) => {
    await grantClipboard(page, t.base);
    const plain = PHONE_ORIGIN + details0;
    if (vp.insets || form === "none") {
      await page.navigate(t.base + path);
    } else {
      await page.navigate(t.base + details0);
      await waitShown(page, ["side-environment"]);
      await tapOn(page, SESSION_BUTTON, 400);
      const m = await waitTrue<{ items: string[] }>(page, SESSION_MENU, 1500);
      details.menu = m?.items;
      const has = !!m?.items.includes("menu-phone");
      if (vp.name === "phone") {
        if (has) fail("flow", "the phone's session menu has Open on phone");
        await escape(page);
        return "no Open on phone in the phone's session menu";
      }
      if (!has) {
        fail("flow", "the session menu has no Open on phone");
        return "no item";
      }
      await tapOn(page, '[data-testid="menu-phone"]', 600);
    }
    const s = await page.probe();
    if (!s.path.startsWith(path)) fail("url", `Open on phone gives ${s.path}`);
    const st = await waitTrue<PhoneState>(page, `(() => { const s = ${PHONE_STATE}; return s.text || s.line ? s : null; })()`, 5000);
    details.state = st;
    if (!st) {
      fail("flow", "Open on phone shows neither a code nor its line");
      return "nothing";
    }
    await shot(form);
    // R-1: once the code (or the line) has come, the first focus is still Done (the sheet's at the top right).
    const focus = await page.evaluate<string | null>(`(() => { const a = document.activeElement; return a ? a.getAttribute("data-testid") || a.tagName : null; })()`);
    details.focus = focus;
    const doneId = vp.name === "phone" ? "sheet-cancel" : "phone-done";
    if (focus !== doneId) fail("focus", `after the code came the focus is on ${focus}, not Done (${doneId})`);
    if (form === "none") {
      if (st.line !== "No remote address is set up for this host.") fail("flow", `with no origin the dialog says "${st.line}"`);
      return "no origin: the one line";
    }
    const want = vp.insets ? PHONE_ORIGIN + `/c/${EX.chat}` : plain;
    const text = form === "template" ? PHONE_LINK_FORM.replace("{url}", encodeURIComponent(want)) : want;
    if (st.text !== text) fail("flow", `the tile encodes "${st.text}", not "${text}"`);
    if (st.link?.trim() !== want) fail("flow", `the link under the tile is "${st.link}", not "${want}"`);
    if (/token|\/home\/|\/Users\//.test(st.text ?? "")) fail("flow", "the code holds a token or a host path");
    if (st.fill && !/rgb\(0, 0, 0\)|#000/.test(st.fill)) fail("flow", `the code's modules are ${st.fill}, not black`);
    if (vp.insets) {
      if (st.tile && st.linkBox && st.tile.right > st.linkBox.left + 1) fail("flow", "on its side the tile is not left of the link");
      if (st.sheet && st.sheet.sh > st.sheet.h + 1) fail("flow", `on its side the sheet scrolls (${st.sheet.sh} > ${st.sheet.h})`);
      if (st.copyHit === false) fail("control-out", "on its side Copy link does not take a tap at its centre");
    }
    await tapOn(page, '[data-testid="phone-copy"]');
    const clip = await readClipboard(page);
    if (clip !== want) fail("copy", `Copy link wrote "${clip}", not "${want}"`);
    if (!vp.insets) {
      await page.reload();
      const again = await waitTrue<PhoneState>(page, `(() => { const s = ${PHONE_STATE}; return s.text ? s : null; })()`, 5000);
      if (again?.text !== st.text) fail("reload", `after a reload the tile encodes "${again?.text}"`);
    }
    return `the tile encodes ${form === "template" ? "the filled link form" : "the remote link"}; Copy link exact${vp.insets ? "; on its side the code beside the link" : "; the reload keeps it"}`;
  });
}

const MD_CHAT = IDS.chats.markdown;
const MD_REPLY_ITEM = `[data-testid="item-msg_05Markdown-0"]`;

/**
 * copy-paste-touch (DESIGN 7.10; PROBE 5.2 to 5.4 as a flow): Chrome's own long press (its touch emulator from a held
 * mouse press) selects "done" in a reply, and the browser's Copy writes "done"; Copy under the reply writes its
 * markdown source; the code block's Copy writes "echo hello"; three pasted lines go into the message box with their
 * line breaks; a pasted image becomes one pasted.png chip. The box is emptied and the chip taken away after.
 */
async function copyPasteTouchFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const path = `/c/${MD_CHAT}`;
  return touchFlow({ name: "copy-paste-touch", route: "message", scene, vp, theme, path }, async ({ page, wire, fail, details, shot }) => {
    await page.navigate(base + path);
    await waitShown(page, ["conversation"]);
    await grantClipboard(page, base);
    const since = wire.mark();
    const word = await page.evaluate<{ x: number; y: number } | null>(`(() => {
      const r = document.querySelector(${JSON.stringify(MD_REPLY_ITEM)});
      if (!r) return null;
      r.scrollIntoView({ block: "center" });
      const w = document.createTreeWalker(r, NodeFilter.SHOW_TEXT);
      for (let n; (n = w.nextNode()); ) { const i = n.data.indexOf("done"); if (i >= 0) { const g = document.createRange(); g.setStart(n, i); g.setEnd(n, i + 4); const b = g.getBoundingClientRect(); return { x: b.left + b.width / 2, y: b.top + b.height / 2 }; } }
      return null;
    })()`);
    if (!word) fail("shows", "the markdown reply shows no \"done\"");
    else if (vp.touch) {
      await page.send("Emulation.setEmitTouchEventsForMouse", { enabled: true, configuration: "mobile" });
      const down = page.send("Input.dispatchMouseEvent", { type: "mousePressed", x: word.x, y: word.y, button: "left", buttons: 1, clickCount: 1 }).catch(() => {});
      await sleep(1100);
      const up = page.send("Input.dispatchMouseEvent", { type: "mouseReleased", x: word.x, y: word.y, button: "left", buttons: 0, clickCount: 1 }).catch(() => {});
      await Promise.race([Promise.all([down, up]), sleep(3000)]);
      await page.send("Emulation.setEmitTouchEventsForMouse", { enabled: false }).catch(() => {});
      await sleep(300);
      const sel = await page.evaluate<string>(`getSelection().toString()`);
      details.selected = sel;
      if (sel.trim() !== "done") fail("flow", `the long press selects "${sel}", not "done"`);
      const menus = await page.evaluate<number>(`document.querySelectorAll('[data-testid^="row-menu-"], .sheet, .menu').length`);
      if (menus) fail("flow", "the long press on a reply's text opened a menu");
      await page.send("Input.dispatchKeyEvent", { type: "rawKeyDown", key: "c", code: "KeyC", windowsVirtualKeyCode: 67, commands: ["copy"] });
      await page.send("Input.dispatchKeyEvent", { type: "keyUp", key: "c", code: "KeyC", windowsVirtualKeyCode: 67 });
      await sleep(200);
      const clip = await readClipboard(page);
      if (clip?.trim() !== "done") fail("copy", `the browser's Copy of the selection wrote "${clip}"`);
      await page.evaluate(`getSelection().removeAllRanges()`);
    }
    await shot("reply");
    await tapOn(page, `${MD_REPLY_ITEM} [data-testid="copy-reply"]`, 500);
    const reply = await readClipboard(page);
    if (reply !== MARKDOWN_REPLY) fail("copy", `Copy under the reply wrote ${JSON.stringify(clip(reply ?? "", 60))}, not its markdown source`);
    await tapOn(page, `${MD_REPLY_ITEM} [data-testid="copy-code"]`, 500);
    const code = await readClipboard(page);
    if (code !== "echo hello") fail("copy", `the code block's Copy wrote ${JSON.stringify(code)}`);
    // Paste into the box: three lines, then an image.
    const lines = "first line\nsecond line\n  third, indented";
    await writeClipboard(page, lines);
    await tapOn(page, '[data-testid="composer-input"]');
    await page.send("Input.dispatchKeyEvent", { type: "rawKeyDown", key: "v", code: "KeyV", windowsVirtualKeyCode: 86, commands: ["paste"] });
    await page.send("Input.dispatchKeyEvent", { type: "keyUp", key: "v", code: "KeyV", windowsVirtualKeyCode: 86 });
    await sleep(400);
    const value = await page.evaluate<string>(`document.querySelector('[data-testid="composer-input"]').value`);
    details.pasted = value;
    if (value !== lines) fail("flow", `the paste put ${JSON.stringify(value)} in the box`);
    await page.evaluate(`(() => {
      const f = document.querySelector('[data-testid="composer-input"]');
      const dt = new DataTransfer();
      dt.items.add(new File([new Uint8Array([137, 80, 78, 71, 13, 10, 26, 10])], "image.png", { type: "image/png" }));
      f.dispatchEvent(new ClipboardEvent("paste", { clipboardData: dt, bubbles: true, cancelable: true }));
    })()`);
    const chip = await waitTrue<string>(page, `(() => { const c = [...document.querySelectorAll('[data-testid="composer-attachments"] [data-testid^="attach-"]')].map((e) => e.textContent).join(" "); return c.includes("pasted.png") ? c : null; })()`, 4000);
    if (!chip) fail("flow", "a pasted image gives no pasted.png chip");
    await shot("pasted");
    // Put the box back as the seed had it.
    await tapOn(page, '[data-testid="composer-attachments"] .attach-remove', 400);
    await tapOn(page, '[data-testid="composer-input"]');
    await emptyField(page);
    const out = sentOf(wire, since, ["send", "bash"]);
    if (out.length) fail("frames", `copy and paste sent ${clipList(out.map(frameText))}`);
    return `${vp.touch ? "a long press selects one word; " : ""}the reply's and the code's Copy exact; three lines and an image pasted`;
  });
}

/**
 * copy-failed (T-29, G-44): with the clipboard refused (Browser.setPermission denies clipboard-write, and the
 * execCommand fallback stubbed to fail), Copy on a reply and on a code block each say "Copy failed" with the text
 * selected, the code head keeping its label on one line; a menu's Copy path opens Copy failed (a sheet on the phone, a
 * dialog elsewhere) with the exact text selected in its field.
 */
async function copyFailedFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const path = `/c/${MD_CHAT}`;
  return touchFlow({ name: "copy-failed", route: "message", scene, vp, theme, path, pre: ["document.execCommand = () => false;"] }, async ({ page, fail, details, shot }) => {
    await cdp.send("Browser.setPermission", { permission: { name: "clipboard-write" }, setting: "denied", origin: base, browserContextId: page.contextId }).catch(() => {});
    await page.navigate(base + path);
    await waitShown(page, ["conversation"]);
    await tapOn(page, `${MD_REPLY_ITEM} [data-testid="copy-reply"]`, 600);
    const r1 = await page.evaluate<{ says: string; sel: string }>(`({ says: document.querySelector(${JSON.stringify(MD_REPLY_ITEM)} + ' [data-testid="copy-reply"]').closest("div, span").textContent, sel: getSelection().toString() })`);
    details.reply = r1;
    if (!/Copy failed/.test(r1.says)) fail("flow", "a refused Copy under the reply does not say Copy failed");
    if (!r1.sel.includes("a done task")) fail("flow", "a refused Copy under the reply does not select the reply's text");
    await tapOn(page, `${MD_REPLY_ITEM} [data-testid="copy-code"]`, 600);
    const r2 = await page.evaluate<{ says: string; lines: number; sel: string }>(`(() => {
      const b = document.querySelector(${JSON.stringify(MD_REPLY_ITEM)} + ' [data-testid="copy-code"]');
      const head = b.closest(".chat-md-code-head, header, div");
      const lang = head.querySelector(".chat-md-lang");
      const g = document.createRange();
      if (lang) g.selectNodeContents(lang);
      const tops = new Set([...g.getClientRects()].map((r) => Math.round(r.top)));
      return { says: head.textContent, lines: lang ? tops.size : 0, sel: getSelection().toString() };
    })()`);
    details.code = r2;
    if (!/Copy failed/.test(r2.says)) fail("flow", "a refused code Copy does not say Copy failed");
    if (r2.lines !== 1) fail("flow", `the code head's label takes ${r2.lines} lines in the failed state`);
    if (r2.sel.trim() !== "echo hello") fail("flow", `a refused code Copy selects "${r2.sel}"`);
    await shot("code");
    // A menu row's Copy path.
    await page.navigate(base + `/c/${EX.chat}`);
    await waitShown(page, ["conversation"]);
    await page.evaluate(OPEN_WORK);
    await holdOn(page, TOOL_EDIT);
    const m = await waitRowMenu(page);
    if (!m) {
      fail("flow", "the Edit row's menu does not open");
      return "no menu";
    }
    await tapOn(page, '[data-testid="row-copy-path"]', 600);
    const r3 = await waitTrue<{ sheet: boolean; dialog: boolean; value: string; start: number; end: number; focused: boolean }>(page, `(() => {
      const box = [...document.querySelectorAll('[data-testid="copy-failed"]')].find((e) => e.getClientRects().length);
      const f = document.querySelector('[data-testid="copy-failed-text"]');
      if (!box || !f) return null;
      return { sheet: !!(box.closest(".sheet") || box.matches(".sheet")), dialog: !!(box.closest('[role="dialog"]') || box.matches('[role="dialog"]')), value: f.value, start: f.selectionStart, end: f.selectionEnd, focused: document.activeElement === f };
    })()`, 2500);
    details.menu = r3;
    if (!r3) fail("flow", "a refused Copy path opens no Copy failed");
    else {
      if (r3.value !== m.head) fail("flow", `Copy failed's field holds "${r3.value}", not the path`);
      if (r3.start !== 0 || r3.end !== r3.value.length || !r3.focused) fail("flow", "Copy failed's text is not selected in its focused field");
      if (vp.name === "phone" ? !r3.sheet : r3.sheet) fail("flow", `Copy failed is ${r3.sheet ? "a sheet" : "a dialog"} at ${sizeTag(vp)}`);
      await shot("menu");
      await escape(page);
    }
    return "Copy failed on the reply, the code (its label on one line) and a menu's Copy path, the text selected";
  });
}

/**
 * plus-pickers (PT-4, CO-14): at 390 with the stand-in keyboard up the picker row folds into the + sheet, which holds
 * Permission and Model with their values whole, each opening its picker as a sheet; with the keyboard down the + sheet
 * has neither and the chips are in the bar. At 834 with a hardware keyboard (no stand-in rise) the chips stay, + has
 * neither row, and each chip opens its menu. Nothing is sent and the draft stays.
 */
async function plusPickersFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const path = `/c/${EX.chat}`;
  const DRAFT = "A draft for the pickers";
  const chips = `(() => { const vis = (e) => !!e && e.getClientRects().length > 0; const c = document.querySelector('[data-testid="composer"]'); return { mode: vis(c.querySelector('button[aria-label^="Permission mode"]')), model: vis(c.querySelector(${JSON.stringify(MODEL_BUTTON.replace('[data-testid="composer"] ', ""))})) }; })()`;
  const rows = `(() => { const vis = (e) => !!e && e.getClientRects().length > 0; const r = (id) => { const e = document.querySelector('[data-testid="' + id + '"]'); return vis(e) ? { text: e.textContent.trim(), cut: [...e.querySelectorAll("*")].some((x) => x.scrollWidth > x.clientWidth + 1) } : null; }; return { permission: r("plus-permission"), model: r("plus-model") }; })()`;
  return touchFlow({ name: "plus-pickers", route: "add", scene, vp, theme, path, pre: [STAND_IN_KEYBOARD] }, async ({ page, wire, fail, details, shot }) => {
    await page.navigate(base + path);
    await waitShown(page, ["composer"]);
    const since = wire.mark();
    await tapOn(page, '[data-testid="composer-input"]');
    await page.send("Input.insertText", { text: DRAFT });
    const phone = vp.name === "phone";
    if (phone) {
      await page.evaluate(`window.__standInKeyboard(336)`);
      await sleep(400);
      const c = await page.evaluate<{ mode: boolean; model: boolean }>(chips);
      if (c.mode || c.model) fail("flow", "with the keyboard up the picker row is not folded");
      await tapOn(page, '[data-testid="composer-plus"]', 500);
      const r = await page.evaluate<{ permission: { text: string; cut: boolean } | null; model: { text: string; cut: boolean } | null }>(rows);
      details.up = r;
      if (!r.permission || !r.model) fail("flow", "the + sheet with the keyboard up lacks Permission or Model");
      else if (r.permission.cut || r.model.cut) fail("name-cut", "a + sheet row's label or value is cut");
      await shot("plus");
      for (const [id, route, picker] of [["plus-permission", "/mode", "picker-mode"], ["plus-model", "/model", "picker-model"]] as const) {
        if (id !== "plus-permission") await tapOn(page, '[data-testid="composer-plus"]', 500);
        await tapOn(page, `[data-testid="${id}"]`, 600);
        const s = await page.probe();
        if (!s.path.startsWith(path + route) || !s.ids.includes(picker)) fail("flow", `${id} gives ${s.path}, not the ${picker.slice(7)} picker`);
        const cut = await page.evaluate<string[]>(`[...document.querySelectorAll('[data-testid="${picker}"] [role="option"], [data-testid="${picker}"] [role="menuitemradio"], [data-testid="${picker}"] button')].filter((e) => e.getClientRects().length && [...e.querySelectorAll("*")].some((x) => x.scrollWidth > x.clientWidth + 1)).map((e) => e.textContent.trim().slice(0, 30))`);
        if (cut.length) fail("name-cut", `the ${picker.slice(7)} picker cuts ${clipList(cut, 3)}`);
        await escape(page);
      }
      await page.evaluate(`window.__standInKeyboard(0)`);
      await sleep(900);
    }
    await tapOn(page, '[data-testid="composer-plus"]', 500);
    const down = await page.evaluate<{ permission: unknown; model: unknown }>(rows);
    details.down = down;
    if (down.permission || down.model) fail("flow", `with ${phone ? "the keyboard down" : "a hardware keyboard"} the + sheet still holds the pickers`);
    await escape(page);
    const c2 = await page.evaluate<{ mode: boolean; model: boolean }>(chips);
    if (!c2.mode || !c2.model) fail("flow", "the picker chips are not in the bar");
    if (!phone) {
      for (const [sel, picker] of [['[data-testid="composer"] button[aria-label^="Permission mode"]', "picker-mode"], [MODEL_BUTTON, "picker-model"]] as const) {
        await tapOn(page, sel, 500);
        if (!(await page.probe()).ids.includes(picker)) fail("flow", `the chip opens no ${picker.slice(7)} menu`);
        await escape(page);
      }
    }
    const value = await page.evaluate<string>(`document.querySelector('[data-testid="composer-input"]').value`);
    if (value !== DRAFT) fail("flow", `the draft became "${value}"`);
    const out = sentOf(wire, since, ["send", "bash"]);
    if (out.length) fail("frames", `the pickers sent ${clipList(out.map(frameText))}`);
    await tapOn(page, '[data-testid="composer-input"]');
    await emptyField(page);
    return phone ? "with the keyboard up + holds Permission and Model, whole; down, the chips" : "the chips stay in the bar and open their menus; + has no pickers";
  });
}

/**
 * parity-controls (GAP 13; 390, m626, large): a terminal-only command picked from the line-start / menu opens the
 * Terminal with it to type (a page at 390, the docked pane at 626, over the chat at large); each chat row's state or
 * time shows on its own second line in the list (the phone's /chats, the drawer, the sidebar). Take back in a queued
 * bubble's menu (CO-5) is send-now's, which runs at every touch size.
 */
async function parityControlsFlow(base: string, scene: SceneName | null, vp: Viewport, theme: Theme): Promise<CheckResult> {
  const path = `/c/${EX.chat}`;
  return touchFlow({ name: "parity-controls", route: "message", scene, vp, theme, path }, async ({ page, wire, fail, details, shot }) => {
    await page.navigate(base + path);
    await waitShown(page, ["composer"]);
    const since = wire.mark();
    await tapOn(page, '[data-testid="composer-input"]');
    await page.send("Input.insertText", { text: "/doc" });
    const row = await waitTrue<boolean>(page, `[...document.querySelectorAll('[data-testid="slash-menu"] [role="option"]')].some((o) => o.textContent.includes("doctor"))`, 3000);
    if (!row) fail("shows", "the / menu shows no doctor row");
    else {
      await page.evaluate(`[...document.querySelectorAll('[data-testid="slash-menu"] [role="option"]')].find((o) => o.textContent.includes("doctor")).setAttribute("data-fd-pick", "")`);
      await tapOn(page, "[data-fd-pick]", 1200);
      const s = await page.probe();
      details.terminal = s.path;
      const pane = await page.evaluate<boolean>(`[...document.querySelectorAll('[data-testid="terminal-pane"]')].some((e) => e.getClientRects().length)`);
      if (!pane) fail("flow", `the terminal-only pick opens no Terminal (${s.path})`);
      const typed = await waitTrue<boolean>(page, `document.body.textContent.includes("/doctor")`, 4000);
      if (!typed) fail("flow", "the Terminal does not show the command to type");
      await shot("terminal");
    }
    const value = await page.evaluate<string>(`document.querySelector('[data-testid="composer-input"]')?.value ?? ""`);
    if (value) fail("flow", `the terminal-only pick leaves "${value}" in the box`);
    // The list (SL-2: the drawer and the sidebar; the phone's /chats rows set the time beside the title): its rows'
    // second lines.
    if (vp.name === "phone") return "the terminal-only pick opens the Terminal";
    if (vp.name === "medium") {
      await page.navigate(base + path);
      await tapOn(page, ".scr-bar-chats", 600);
    } else await page.navigate(base + path);
    await sleep(500);
    const rows = await page.evaluate<{ title: string; second: boolean; cut: boolean }[]>(`[...document.querySelectorAll(".scr-row")].filter((r) => r.getClientRects().length).map((r) => { const t = r.querySelector(".scr-row-title"); const m = r.lastElementChild; const tb = t.getBoundingClientRect(), mb = m.getBoundingClientRect(); return { title: t.textContent.trim().slice(0, 30), second: m !== t && mb.top >= tb.bottom - 2, cut: m.scrollWidth > m.clientWidth + 1 }; })`);
    details.rows = rows;
    if (!rows.length) fail("shows", "the chat list shows no rows");
    const bad = rows.filter((r) => !r.second || r.cut);
    if (bad.length) fail("flow", `rows whose state is not whole on its own line: ${clipList(bad.map((r) => r.title), 3)}`);
    const out = sentOf(wire, since, ["send", "bash"]);
    if (out.length) fail("frames", `the flow sent ${clipList(out.map(frameText))}`);
    return `the terminal-only pick opens the Terminal; ${rows.length} rows with their state on a line of its own`;
  });
}


async function browserPaneFlows(record: (r: CheckResult) => void, problems: string[], flows: readonly string[]) {
  // The three sizes, and the two where it opens over the chat (1100 x 800, 834 x 1194 with touch).
  const sizes = [...BROWSER_SIZES, ...BROWSER_OVER_SIZES].filter((v) => CORE.some((x) => x.name === v.name));
  const runs = flows.includes("browser-pane") ? [...sizes, ...extraAt("browser-pane")].flatMap((vp) => THEMES.map((theme) => ({ vp, theme }))) : [];
  const looks = flows.includes("browser-looks") && THEMES.includes("light") && CORE.some((v) => v.name === "laptop") ? BROWSER_LOOKS : [];
  const stop = flows.includes("browser-stop") && CORE.some((v) => v.name === "laptop");
  // FIX-B2 2's done line: its three sizes (1280x800, 834x1194 and 390x844), as --sizes allows.
  const done = BROWSER_DONE_SIZES.filter((v) => CORE.some((x) => x.name === v.name));
  const cases = flows.includes("browser-cases") ? [...done, ...extraAt("browser-cases")].flatMap((vp) => THEMES.map((theme) => ({ vp, theme }))) : [];
  const restart = flows.includes("browser-restart") && done.length === BROWSER_DONE_SIZES.length;
  // v0.6 touch: More > Select text and the foot's Copy, at its touch sizes.
  const selects = flows.includes("browser-select") ? touchAt("browser-select").flatMap((vp) => THEMES.map((theme) => ({ vp, theme }))) : [];
  if ((!runs.length && !looks.length && !stop && !cases.length && !restart && !selects.length) || cdp.closed) return;
  const theme1 = THEMES.includes("light") ? "light" : "dark";
  const asCheck = (r: BrowserFlowResult) => finish({ kind: "flow", name: r.name, route: r.route, scene: "main", size: r.size, theme: r.theme, path: r.path, failures: r.failures, warnings: r.warnings, note: r.note, shot: r.shot, ms: r.ms, details: r.details });
  const failed = (msg: string) => {
    const one = (name: string, route: string, vp: Viewport, theme: Theme) => record(finish({ kind: "flow", name, route, scene: "main", size: sizeTag(vp), theme, path: `/c/${EX.chat}/browser`, failures: [{ code: "seed", text: msg }], warnings: [], note: "", ms: 0, details: { viewport: `${vp.width}x${vp.height}` } }));
    for (const x of runs) one("browser-pane", "chatBrowser", x.vp, x.theme);
    for (const x of cases) one("browser-cases", "chatBrowser", x.vp, x.theme);
    if (restart) one("browser-restart", "chatBrowserTab", BROWSER_DONE_SIZES[0]!, theme1);
  };
  const chrome = args.chrome ?? findChrome();
  const port = sharedBrowserPort(portFree);
  if (!chrome || !port) return failed(!chrome ? "no Chrome for Testing for the shared browser" : "no free port from 9341 to 9349 for the shared browser");
  let b: Booted;
  try {
    // The harness writes the seed's browser.json and gives Chrome a TMPDIR that its socket fits under.
    b = await boot({ scene: "main", port: PORT, dist: built!, keep: KEEP, env: SERVER_ENV, browser: { chrome, port, enabled: !runs.length } });
  } catch (e) {
    return failed(`the seed did not boot: ${(e as Error).message}`);
  }
  live.add(b);
  const site = startBrowserSite();
  // 1280x800 and 1100x800 share the size name laptop, 1194x834 and 834x1194 medium: the shots name the pixels.
  const ctx = { cdp, base: b.base, chat: EX.chat, site: site.base, shots: "", files: join(OUT, "browser-files"), sharedPort: port, shotName: (flow: string, vp: Viewport, theme: Theme, extra?: string) => shotName("main", flow, vp, theme, [extra, `${vp.width}x${vp.height}`].filter(Boolean).join("-")) };
  const life: BrowserLife = {
    quit: async () => {
      await b.restart();
    },
    profile: join(b.seed.state, "browser", "profile"),
    cdpPort: port,
    portFree,
  };
  try {
    let first = true;
    for (const x of runs) {
      if (cdp.closed) break;
      record(asCheck(await browserPaneFlow(ctx, x.vp, x.theme, first)));
      first = false;
    }
    for (const look of looks) if (!cdp.closed) record(asCheck(await browserLookFlow(ctx, look)));
    if (stop && !cdp.closed) record(asCheck(await browserStopFlow(ctx, theme1)));
    for (const x of cases) if (!cdp.closed) record(asCheck(await browserCasesFlow(ctx, x.vp, x.theme)));
    for (const x of selects) if (!cdp.closed) record(asCheck(await browserSelectFlow(ctx, x.vp, x.theme)));
    if (restart && !cdp.closed) record(asCheck(await browserRestartFlow(ctx, theme1, life)));
  } finally {
    const stopped = await stopBrowser(b.base);
    if (stopped !== 200) problems.push(`scene main (browser): Stop browser answered ${stopped}`);
    site.stop();
    const r = await b.stop();
    live.delete(b);
    if (r.code !== 0) problems.push(`scene main (browser): the server exited with ${r.code}`);
    if (r.leftovers.length) problems.push(`scene main (browser): ${r.leftovers.length} process(es) outlived the server and were ended by pid`);
  }
}

async function main() {
  mkdirSync(shotsDir, { recursive: true });
  const started = new Date();
  const problems: string[] = [];

  if (BASE) {
    try {
      const res = await fetch(BASE + "/", { signal: AbortSignal.timeout(5000) });
      if (!res.ok) fail(`${BASE}/ answered HTTP ${res.status}`);
    } catch (e) {
      fail(`${BASE}/ does not answer (${(e as Error).message})`);
    }
  } else if (args.dist) built = resolve(args.dist);
  else {
    built = mkdtempSync(join(tmpdir(), "ui-check-page-"));
    const b = await buildPage({ out: built, entry: args.page }).catch((e: Error) => fail(e.message));
    console.log(`ui-check: built ${args.page ?? "web/index.html"} in ${b.ms} ms`);
  }

  let wsUrl: string;
  if (args.cdp) {
    const endpoint = args.cdp;
    wsUrl = await browserWsUrl(endpoint).catch((e: Error) => fail(`--cdp ${endpoint}: ${e.message}`));
  } else {
    const binary = args.chrome ?? findChrome();
    if (!binary) fail("no Chrome for Testing found; pass --chrome <binary> or set CHROME_PATH");
    const port = freePort(9341, 9349);
    if (!port) fail("no free port from 9341 to 9349 for Chrome");
    const launched = await launchChrome(binary, port, { extraArgs: [FINE_POINTER] }).catch((e: Error) => fail(`could not start ${binary}: ${e.message}`));
    own = launched;
    wsUrl = launched.wsUrl;
  }
  cdp = await Cdp.connect(wsUrl);
  cdp.onClose((why) => {
    if (!stopping) console.error(`ui-check: ${why}`);
  });
  const version = await cdp.send<{ product: string }>("Browser.getVersion");

  const cases = CHECKS.includes("routes") ? routeCases() : [];
  // An action check whose press runs a real update (row 108) boots a scratch checkout of its own, so never with --base.
  const specs = CHECKS.includes("actions") ? ACTIONS.filter((a) => (BASE ? a.id === a.route && !a.scratch : true) && picked([a.id, a.route], BASE ? null : a.scene)) : [];
  const mainPicked = Boolean(BASE) || ONLY_SCENES.includes("main");
  const doHistory = CHECKS.includes("history") && mainPicked && picked(["history", "chat"], null);
  const doAppFiles = CHECKS.includes("routes") && mainPicked && APP_FILE_IDS.some((id) => picked([id], null));
  const flows = CHECKS.includes("flows") && mainPicked ? FLOW_IDS.filter((f) => picked([f, FLOW_ROUTE[f] ?? (LIST_FLOWS.has(f) ? "chats" : "add")], null)) : [];
  // The reconnect and restart flows boot a seed of their own (never with --base: they drop, cut and restart).
  const mainFlows = flows.filter((f) => !OWN_BOOT_FLOWS.has(f));
  // The card's keyboard flow needs the elicitation scene's waiting card: a seed of its own (no --base copy has it).
  const cardFlow = CHECKS.includes("flows") && !BASE && ONLY_SCENES.includes("elicitation") && picked(["card-keyboard", FLOW_ROUTE["card-keyboard"]!], null);
  console.log(
    `ui-check: ${BASE ?? `the click-through seed on 127.0.0.1:${PORT}`} with ${version.product} (${own ? `own, port ${own.port}` : "existing endpoint"}); ` +
      `${cases.length} route cases, ${specs.length} action checks, ${flows.length} flows, sizes ${SIZES.join(", ")}, themes ${THEMES.join(", ")}, checks ${CHECKS.join(", ")}`,
  );

  // The laptop runs need a fine pointer that hovers; a Chrome started elsewhere may not give its pages one.
  let pointer = "not checked";

  const results: CheckResult[] = [];
  const record = (r: CheckResult) => {
    results.push(r);
    print(r);
  };
  const bootFailed = (what: { kind: Kind; name: string; route: string; scene: SeedSceneName | null; path: string }, vp: Viewport, theme: Theme, msg: string) =>
    record(finish({ ...what, size: sizeTag(vp), theme, failures: [{ code: "seed", text: `the seed did not boot: ${msg}` }], warnings: [], note: "", ms: 0, details: {} }));

  // Route checks, scene by scene (main last, so the history check and the flows run on its server too); the side
  // scene only for a route case that opens in it (R130's link to one exchange).
  const sideCases = cases.some((c) => c.scene === "side") ? (["side"] as const) : [];
  const scenesInOrder: (RouteSceneName | null)[] = BASE ? [null] : [...SCENES.filter((s) => s !== "main"), ...sideCases, "main"];
  for (const scene of scenesInOrder) {
    if (cdp.closed) break;
    const mine = cases.filter((c) => c.scene === scene);
    const extra = scene === null || scene === "main";
    if (!mine.length && !(extra && (doHistory || mainFlows.length || doAppFiles))) continue;
    let t: Target;
    try {
      t = await openTarget(scene);
    } catch (e) {
      for (const c of mine) for (const vp of VPS) for (const theme of THEMES) bootFailed({ kind: "route", name: c.id, route: c.route.name, scene, path: c.path }, vp, theme, (e as Error).message);
      continue;
    }
    try {
      if (pointer === "not checked") {
        const laptop = VPS.find((v) => !v.touch);
        if (laptop) {
          pointer = await withPage(laptop, "dark", async (p) => {
            await p.navigate(t.base + "/"); // about:blank does not show the setting; a loaded page does
            p.takeIssues();
            return p.evaluate<string>(`matchMedia("(pointer: fine)").matches && matchMedia("(hover: hover)").matches ? "fine" : matchMedia("(pointer: none)").matches ? "none" : "other"`);
          }).catch(() => "unknown");
          if (pointer !== "fine") console.log(`ui-check: warning: the laptop pages report pointer "${pointer}", not a fine pointer that hovers; start that Chrome with ${FINE_POINTER}, or leave out --cdp`);
        }
      }
      const passes = (vp: Viewport): (RoutePass | undefined)[] => [
        undefined,
        ...(PASSES.includes("text-size") && TEXT_PASS_SIZES.includes(vp.label!) ? [TEXT_PASS] : []),
        ...(PASSES.includes("looks") && LOOK_PASS_SIZES.includes(vp.label!) ? LOOK_PASSES : []),
      ];
      const tasks = mine.flatMap((c) => VPS.flatMap((vp) => passes(vp).flatMap((pass) => THEMES.map((theme) => ({ c, vp, theme, pass })))));
      await pool(tasks, JOBS, async (k) => record(await routeCheck(k.c, t.base, k.vp, k.theme, k.pass)));
      if (extra && cases.length && picked(["outside-family"], null)) record(await notFoundCheck(t.base, scene));
      if (extra && doAppFiles) for (const r of await appFileChecks(t.base, scene)) record(r);
      if (extra && doHistory) await pool(CORE, JOBS, async (vp) => record(await historyCheck(t.base, scene, vp)));
      if (extra && doHistory) await pool(CORE.filter((v) => v.name !== "medium"), JOBS, async (vp) => record(await historyReloadCheck(t.base, scene, vp)));
      if (extra && mainFlows.length) {
        const touch = CORE.filter((v) => v.touch);
        for (const f of flows.filter((x) => !OWN_FLOWS.has(x)))
          for (const vp of [...touch.filter((v) => f === "menu-picker-webkit" || v.name === "phone"), ...extraAt(f)]) record(await menuFlow(f, t.base, scene, vp, f === "menu-picker-webkit"));
        if (flows.includes("two-pages")) record(await twoPagesFlow(t, scene));
        if (flows.includes("shell-page")) for (const vp of touch.filter((v) => v.name === "phone")) for (const theme of THEMES) record(await shellPageFlow(t.base, scene, vp, theme));
        if (flows.includes("file-gone")) for (const vp of [...CORE, ...extraAt("file-gone")]) record(await fileGoneFlow(t.base, scene, vp));
        if (flows.includes("bang-message")) for (const vp of [...CORE.filter((v) => v.name !== "medium"), ...extraAt("bang-message")]) record(await bangMessageFlow(t.base, scene, vp));
        if (flows.includes("settings-facts")) for (const vp of [...CORE.filter((v) => v.name === "laptop"), ...touchAt("settings-facts")]) record(await settingsFactsFlow(t.base, scene, vp));
        if (flows.includes("keyboard")) for (const vp of [...touch, ...extraAt("keyboard")]) record(await keyboardFlow(t.base, scene, vp));
        if (flows.includes("files-pane")) for (const vp of touchAt("files-pane")) record(await filesPaneFlow(t.base, scene, vp));
        // Row 82: the panes' handles and Hide sidebar, at 1280x800 and the sizes picked; each page keeps its own choice.
        // v0.6 touch: the large tablet in landscape is large-land (TOUCH_LAPTOP's size), with the other touch sizes.
        if (flows.includes("panes")) for (const vp of [...(CORE.some((v) => v.name === "laptop") ? [WIDE_LAPTOP] : []), ...CORE, ...extraAt("panes")]) record(await panesFlow(t.base, scene, vp));
        // Row 93: the panes slide, at 1280x800 in both themes (with the screenshots) and the sizes picked; row 92: the
        // link to Home on the laptop and in the tablet's drawer.
        if (flows.includes("pane-slide")) {
          if (CORE.some((v) => v.name === "laptop")) for (const theme of THEMES) record(await paneSlideFlow(t.base, scene, WIDE_LAPTOP, theme));
          for (const vp of [...CORE, ...extraAt("pane-slide")]) record(await paneSlideFlow(t.base, scene, vp, "dark"));
        }
        if (flows.includes("logo-link")) for (const vp of [...CORE.filter((v) => v.name !== "phone"), ...extraAt("logo-link")]) record(await logoLinkFlow(t.base, scene, vp));
        // U4: the split side panel at 1280x800 and the tablet (1194x834) in both themes, the four looks at 1280x800 light,
        // 1440x900 in both themes, and the phone (no split).
        if (flows.includes("split-panel")) {
          if (CORE.some((v) => v.name === "laptop")) {
            for (const theme of THEMES) record(await splitPanelFlow(t.base, scene, WIDE_LAPTOP, theme));
            if (THEMES.includes("light")) for (const look of P2_LOOKS) record(await splitPanelFlow(t.base, scene, WIDE_LAPTOP, "light", look));
            for (const theme of THEMES) record(await splitPanelFlow(t.base, scene, SPLIT_WIDE, theme, "glass"));
          }
          if (CORE.some((v) => v.name === "medium")) for (const theme of THEMES) record(await splitPanelFlow(t.base, scene, SPLIT_TABLET, theme));
          for (const vp of CORE.filter((v) => v.name === "phone")) for (const theme of THEMES) record(await splitPanelFlow(t.base, scene, vp, theme));
          // v0.6 touch: 626, 768, the large tablet (one view over the chat) and its column form, and 1366x1024.
          for (const vp of extraAt("split-panel")) for (const theme of THEMES) record(await splitPanelFlow(t.base, scene, vp, theme));
          if (largeCol("split-panel")) for (const theme of THEMES) record(await splitPanelFlow(t.base, scene, LARGE_COL, theme));
        }
        // Review U4: the rules this round fixed, at 1280x800 in both themes and on the tablet.
        if (flows.includes("split-review")) {
          if (CORE.some((v) => v.name === "laptop")) for (const theme of THEMES) record(await splitReviewFlow(t.base, scene, WIDE_LAPTOP, theme));
          if (CORE.some((v) => v.name === "medium")) record(await splitReviewFlow(t.base, scene, SPLIT_TABLET, THEMES.includes("light") ? "light" : THEMES[0]!));
          for (const vp of [...touchAt("split-review"), ...(largeCol("split-review") ? [LARGE_COL] : [])]) record(await splitReviewFlow(t.base, scene, vp, THEMES.includes("light") ? "light" : THEMES[0]!));
        }
        // FIX-U6: standalone mode in an app window of its own Chrome (--app), and the theme colour in the four looks.
        // The large iPad (1366x1024 touch, the laptop's layout) with the tablet, as the panes flow has it.
        const standaloneVps = [...touch, ...extraAt("standalone")];
        if (flows.includes("standalone") && touch.length) {
          const not = (text: string, code: string, status: "fail" | "warn") => {
            for (const vp of standaloneVps) record(finish({ kind: "flow", name: "standalone", route: "home", scene, size: sizeTag(vp), theme: THEMES[0]!, path: "/", failures: status === "fail" ? [{ code, text }] : [], warnings: status === "warn" ? [{ code, text }] : [], note: "", ms: 0, details: {} }));
          };
          if (args.cdp) not("standalone mode needs an app window of a Chrome started here with --app; leave out --cdp", "standalone", "warn");
          else {
            try {
              appWindow = await openAppWindow(t.base);
            } catch (e) {
              not(`the app window did not open: ${(e as Error).message}`, "run", "fail");
            }
            if (appWindow)
              try {
                for (const vp of standaloneVps) for (const theme of THEMES) record(await standaloneFlow(appWindow, t.base, scene, vp, theme));
              } finally {
                await closeAppWindow(appWindow);
                appWindow = null;
              }
          }
        }
        if (flows.includes("theme-color")) for (const vp of [...CORE.filter((v) => v.name !== "medium"), ...extraAt("theme-color")]) for (const theme of THEMES) record(await themeColorFlow(t.base, scene, vp, theme));
        // Row 99: an environment's two paths, then Rename (1280x800 in both themes, with the screenshots) and Move from
        // its menu (and the laptop's drag); each puts the seed's name and order back.
        if (flows.includes("env-routes")) for (const vp of [...CORE.filter((v) => v.name !== "medium"), ...extraAt("env-routes")]) record(await envRoutesFlow(t.base, scene, vp));
        if (flows.includes("env-rename")) {
          if (CORE.some((v) => v.name === "laptop")) for (const theme of THEMES) record(await envRenameFlow(t.base, scene, WIDE_LAPTOP, theme));
          for (const vp of [...CORE.filter((v) => v.name === "medium"), ...extraAt("env-rename")]) record(await envRenameFlow(t.base, scene, vp, "dark"));
          for (const vp of CORE.filter((v) => v.name === "phone")) for (const theme of THEMES) record(await envRenameFlow(t.base, scene, vp, theme));
        }
        if (flows.includes("env-move")) for (const vp of [...CORE, ...extraAt("env-move")]) record(await envMoveFlow(t.base, scene, vp));
        // Row 102: a finger's drag of a heading, on the tablet in dark and on the phone in both themes (the screenshots).
        if (flows.includes("env-move-touch")) {
          for (const vp of [...touch.filter((v) => v.name === "medium"), ...extraAt("env-move-touch")]) record(await envMoveTouchFlow(t.base, scene, vp, "dark"));
          for (const vp of touch.filter((v) => v.name === "phone")) for (const theme of THEMES) record(await envMoveTouchFlow(t.base, scene, vp, theme));
        }
        // Row 107: a mouse's long press on a heading, at 1280x800 (the screenshots) and 1100x800, in both themes.
        if (flows.includes("env-move-longpress")) for (const vp of CORE.some((v) => v.name === "laptop") ? [WIDE_LAPTOP, ...CORE.filter((v) => v.name === "laptop")] : []) for (const theme of THEMES) record(await envMoveLongPressFlow(t.base, scene, vp, theme));
        // Row 97: Settings from the live example chat shows its own facts, no kept line.
        if (flows.includes("settings-kept-live") && CORE.some((v) => v.name === "laptop")) record(await settingsKeptLiveFlow(t.base, scene, WIDE_LAPTOP));
        if (flows.includes("settings-kept-live")) for (const vp of touchAt("settings-kept-live")) record(await settingsKeptLiveFlow(t.base, scene, vp));
        // v0.3 search: the pane and its key on a laptop, the pane on the tablet and the phone. Picks are navigations.
        if (flows.includes("search-pane")) for (const vp of [...CORE.filter((v) => v.name === "laptop"), ...touchAt("search-pane")]) record(await searchPaneFlow(t.base, scene, vp));
        if (flows.includes("palette")) for (const vp of [...CORE.filter((v) => v.name === "laptop"), ...touchAt("palette")]) record(await paletteFlow(t.base, scene, vp));
        if (flows.includes("search-pane-touch")) for (const vp of [...touch, ...extraAt("search-pane-touch")]) record(await searchTouchFlow(t.base, scene, vp));
        // The @ picker: by keyboard on a laptop, by touch on the tablet and the phone. Each flow empties the example
        // chat's message box first and leaves it empty; at-picker's Send adds one turn to the example chat.
        for (const f of ["at-picker", "at-picker-ime", "at-picker-no-match", "at-picker-not-opened"] as const)
          if (flows.includes(f)) for (const vp of [...CORE.filter((v) => v.name === "laptop"), ...touchAt(f)]) record(await atPickerFlow(f, t, scene, vp));
        if (flows.includes("at-picker-touch")) for (const vp of [...touch, ...extraAt("at-picker-touch")]) record(await atPickerTouchFlow(t.base, scene, vp));
        // The / menu at a mid-line / (D57): by keyboard on a laptop (its Send adds one turn to the example chat), by
        // touch on the tablet and the phone. Each empties the example chat's message box first and leaves it empty.
        if (flows.includes("slash-midline")) for (const vp of [...CORE.filter((v) => v.name === "laptop"), ...touchAt("slash-midline")]) record(await slashMidlineFlow(t, scene, vp));
        if (flows.includes("slash-midline-touch")) for (const vp of [...touch, ...extraAt("slash-midline-touch")]) record(await slashMidlineTouchFlow(t.base, scene, vp));
        // Row 76: a mention chip, the long command chip and its arguments in a chat's box, at each size and in a narrow
        // laptop box. Each empties the example chat's message box first and leaves it empty; nothing is sent.
        if (flows.includes("chip-layout")) {
          for (const vp of [...CORE, ...extraAt("chip-layout")]) record(await chipLayoutFlow(t.base, scene, vp));
          if (CORE.some((v) => v.name === "laptop")) record(await chipLayoutFlow(t.base, scene, NARROW_LAPTOP, "narrow"));
          if (CORE.some((v) => v.name === "phone")) record(await chipLayoutFlow(t.base, scene, SMALL_PHONE, "small"));
        }
        // D59: the new-chat form's / menu and @ picker at each size; neither sends anything.
        if (flows.includes("form-slash")) for (const vp of [...CORE, ...extraAt("form-slash")]) record(await formSlashFlow(t.base, scene, vp));
        if (flows.includes("form-at")) for (const vp of [...CORE, ...extraAt("form-at")]) record(await formAtFlow(t.base, scene, vp));
        // The phone's swipe on a chat row: neither flow sends anything (Cancel and a tap elsewhere act on nothing).
        for (const f of ["row-swipe-delete", "row-swipe-heading"] as const)
          if (flows.includes(f)) {
            for (const vp of touch.filter((v) => v.name === "phone")) for (const theme of THEMES) record(await swipeFlow(f, t.base, scene, vp, theme));
            // v0.6 touch: the drawer at medium, the sidebar at large (DESIGN 7.7's "On a touch device").
            for (const vp of [...touch.filter((v) => v.name === "medium"), ...extraAt(f)]) record(await swipeFlow(f, t.base, scene, vp, "dark"));
          }
        // A composer link as a new document after the chat's page, then Send and Run: each reaches the server once.
        if (flows.includes("send-new-document")) for (const vp of [...CORE.filter((v) => v.name !== "medium"), ...extraAt("send-new-document")]) record(await sendNewDocumentFlow(t, scene, vp));
        // A send with the socket down, then a reload before it is back: one place for the text, and it comes back.
        if (flows.includes("offline-send")) for (const vp of [...CORE.filter((v) => v.name !== "medium"), ...extraAt("offline-send")]) record(await offlineSendFlow(t.base, scene, vp));
        // Settings opened as a new document after a chat: Done stays in the document.
        if (flows.includes("settings-new-document")) for (const vp of [...CORE.filter((v) => v.name !== "medium"), ...extraAt("settings-new-document")]) record(await settingsNewDocumentFlow(t.base, scene, vp));
        // Row 77: the two session settings and the lists; it puts both back to their defaults at its end.
        if (flows.includes("session-settings")) for (const vp of [...CORE.filter((v) => v.name === "laptop"), ...touchAt("session-settings")]) record(await sessionSettingsFlow(t, scene, vp));
        // Row 80: a held chat's box at 1280 x 800 and on the phone; Continue in a copy adds one copy of "Summarize the
        // server logs" to the scratch project, and the hold ends before the next flow.
        if (flows.includes("held-box")) {
          const copies: string[] = [];
          for (const vp of [...(CORE.some((v) => v.name === "laptop") ? [WIDE_LAPTOP] : []), ...touchAt("held-box")]) record(await heldBoxFlow(t, scene, vp, copies));
        }
        // Row 79: the paced 20,000-character reply three times on the example chat (the reference, the reveal with a
        // second page, Reduce motion On in Settings); its message box is left empty.
        if (flows.includes("smooth-text")) for (const vp of [...CORE.filter((v) => v.name === "laptop"), ...touchAt("smooth-text")]) record(await smoothTextFlow(t, scene, vp));
        // v0.6 touch (DESIGN-T1 3.3): the new flows on the main scene's seed, each at its sizes in both themes. Each
        // leaves the example chat's draft and the markdown chat's as it found them; before row-menu, whose Archive
        // archives another chat at each of its sizes (the markdown chat among them).
        const both = async (f: FlowId, run: (vp: Viewport, theme: Theme) => Promise<CheckResult>, vps = touchAt(f)) => {
          if (flows.includes(f)) for (const vp of vps) for (const theme of THEMES) record(await run(vp, theme));
        };
        await both("longpress-title", (vp, th) => longpressTitleFlow(t.base, scene, vp, th));
        await both("longpress-tool", (vp, th) => longpressToolFlow(t.base, scene, vp, th));
        await both("longpress-file", (vp, th) => longpressFileFlow(t.base, scene, vp, th));
        await both("menus-laptop", (vp, th) => menusLaptopFlow(t.base, scene, vp, th), CORE.filter((v) => v.name === "laptop"));
        await both("toast-hold", (vp, th) => toastHoldFlow(t.base, scene, vp, th));
        await both("shortcuts-touch", (vp, th) => shortcutsTouchFlow(t.base, scene, vp, th));
        await both("key-bar", (vp, th) => keyBarFlow(t.base, scene, vp, th));
        await both("keyboard-release", (vp, th) => keyboardReleaseFlow(t.base, scene, vp, th));
        await both("changes-over", (vp, th) => changesOverFlow(t.base, scene, vp, th));
        await both("d26", (vp, th) => d26Flow(t.base, scene, vp, th));
        await both("large-composer", (vp, th) => largeComposerFlow(t.base, scene, vp, th));
        await both("composer-fit", (vp, th) => composerFitFlow(t.base, scene, vp, th));
        // The held state: "Summarize the server logs" held by a stand-in terminal's record, as held-box makes it.
        if (flows.includes("composer-fit") && t.booted && touchAt("composer-fit").length) {
          const terminal = standIn();
          const rec = writeRunningRecord(t.booted.seed.claudeConfig, { pid: terminal.pid, sessionId: IDS.sessions.logs, entrypoint: "cli", status: "idle" });
          try {
            await sleep(1500);
            for (const vp of touchAt("composer-fit")) for (const theme of THEMES) record(await composerFitFlow(t.base, scene, vp, theme, "held", IDS.chats.logs));
          } finally {
            removeRunningRecord(rec);
            terminal.stop();
            await sleep(1500);
          }
        }
        await both("column-form", (vp, th) => columnFormFlow(t.base, scene, vp, th), [...(largeCol("column-form") ? [LARGE_COL] : []), ...touchAt("column-form")]);
        await both("copy-paste-touch", (vp, th) => copyPasteTouchFlow(t.base, scene, vp, th));
        await both("copy-failed", (vp, th) => copyFailedFlow(t.base, scene, vp, th));
        await both("plus-pickers", (vp, th) => plusPickersFlow(t.base, scene, vp, th));
        await both("parity-controls", (vp, th) => parityControlsFlow(t.base, scene, vp, th));
        // Last: its Remove takes an upload of the example chat away (at the last size only).
        if (flows.includes("longpress-upload")) {
          const runs = touchAt("longpress-upload").flatMap((vp) => THEMES.map((theme) => ({ vp, theme })));
          for (const [i, r] of runs.entries()) record(await longpressUploadFlow(t.base, scene, r.vp, r.theme, i === runs.length - 1));
        }
        // A chat row's menu in the chat-list drawer: the tablet, and a laptop window under 1,000 px. Last, because its
        // Archive archives a chat (never the example chat, which the flows above use).
        if (flows.includes("row-menu")) {
          const medium = CORE.find((v) => v.name === "medium");
          if (medium) record(await rowMenuFlow(t.base, scene, medium, "medium"));
          // v0.6 touch: the drawer at 626 and 768, the sidebar at large, the phone's /chats screen.
          for (const vp of touchAt("row-menu").filter((v) => v !== medium)) record(await rowMenuFlow(t.base, scene, vp, "medium"));
          if (CORE.some((v) => v.name === "laptop")) record(await rowMenuFlow(t.base, scene, NARROW_LAPTOP, "narrow"));
        }
        // D59: Start from the form with a command chip, then with a mention chip; each adds a chat to the example
        // project, so after the flows that read its chat list.
        if (flows.includes("form-start")) for (const vp of [...CORE.filter((v) => v.name === "laptop"), ...touchAt("form-start")]) for (const variant of ["command", "mention"] as const) record(await formStartFlow(t, scene, vp, variant));
        // New environment adds a project to the seed (website, then infra): after the flows that read the projects.
        if (flows.includes("new-environment")) for (const vp of [...CORE, ...extraAt("new-environment")]) record(await newEnvironmentFlow(t.base, scene, vp));
      }
    } finally {
      await closeTarget(t, problems);
    }
  }

  // R19 and S14: the reconnect flows (a drop, a reload, the slow link's proxy) and the restart, each on a seed of its
  // own: a drop and a reload share one; the proxy's origin is the slow flow's seed's; each restart gets a fresh seed.
  if (!BASE && !cdp.closed && flows.some((f) => OWN_BOOT_FLOWS.has(f) || f === "composer-fit")) {
    const at = (...names: SizeName[]) => names.map((n) => CORE.find((v) => v.name === n)).filter((v): v is Viewport => !!v);
    const onSeed = async (plan: { name: string; route: string; vps: Viewport[] }[], run: (t: Target) => Promise<void>, origins?: string[], fixture?: Partial<Fixture>, scene: SceneName = "main") => {
      const todo = plan.filter((p) => flows.includes(p.name as (typeof FLOW_IDS)[number]) && p.vps.length);
      if (!todo.length || cdp.closed) return;
      let t: Target;
      try {
        t = await openTarget(scene, origins, fixture);
      } catch (e) {
        for (const p of todo) for (const vp of p.vps) bootFailed({ kind: "flow", name: p.name, route: p.route, scene, path: `/c/${EX.chat}` }, vp, "dark", (e as Error).message);
        return;
      }
      try {
        await run(t);
      } finally {
        await closeTarget(t, problems);
      }
    };
    // Row 97: Settings with no chat live shows what the last chat reported, on the archived scene's seed (no warm-up).
    const keptVps = [...(CORE.some((v) => v.name === "laptop") ? [WIDE_LAPTOP] : []), ...at("phone")];
    const keptAll = [...keptVps, ...extraAt("settings-kept")];
    await onSeed([{ name: "settings-kept", route: "settingsSection", vps: keptAll }], async (t) => {
      for (const vp of keptAll) for (const theme of THEMES) record(await settingsKeptFlow(t, vp, theme));
    }, undefined, undefined, "archived");
    // P1 (rows 118, 119): the minimum Claude Code version's line, one boot per version that the fake claude reports,
    // on the archived scene's seed (no warm-up), at 1280x800 and 390x844 in both themes.
    for (const run of CLAUDE_MINIMUM_RUNS) {
      await onSeed([{ name: "claude-minimum", route: "settingsSection", vps: keptVps }], async (t) => {
        for (const vp of keptVps) for (const theme of THEMES) record(await claudeMinimumFlow(t, run, vp, theme));
      }, undefined, { version: run.prints }, "archived");
    }
    // Send again with the socket down, on the not-sent scene's seed: the press uses up its Not sent message, so a
    // fresh seed per size.
    for (const vp of [...at("laptop", "phone"), ...extraAt("offline-send-again")]) await onSeed([{ name: "offline-send-again", route: "message", vps: [vp] }], async (t) => record(await offlineSendAgainFlow(t, vp)), undefined, undefined, "not-sent");
    const drop = [...at("laptop", "phone"), ...extraAt("resume-drop")];
    const reload = [...at("phone", "medium"), ...extraAt("resume-reload")];
    await onSeed([{ name: "resume-drop", route: "chat", vps: drop }, { name: "resume-reload", route: "chat", vps: reload }], async (t) => {
      if (flows.includes("resume-drop")) for (const vp of drop) record(await resumeDropFlow(t, vp));
      if (flows.includes("resume-reload")) for (const vp of reload) record(await resumeReloadFlow(t, vp));
    });
    const slowFlows = ["resume-slow", "resume-blackhole", "resume-two-pages", "resume-wake", "resume-tail", "resume-rtt"] as const;
    if (slowFlows.some((f) => flows.includes(f))) {
      // Chrome reaches this seed's server only through the proxy, whose port the system picks. Each flow has its own
      // turn ids and leaves the link as it found it; resume-wake's long reply goes into a chat that no other flow opens,
      // and resume-two-pages (a laptop and a phone page at once, whatever --sizes says) into another.
      const proxy = startProxy({ to: PORT, ...SLOW_LINK });
      const slow = at("phone", "laptop");
      const bothPages = VIEWPORTS.filter((v) => v.name === "laptop" || v.name === "phone");
      try {
        await onSeed(slowFlows.map((name) => ({ name, route: "chat", vps: name === "resume-two-pages" ? bothPages : slow })), async (t) => {
          if (flows.includes("resume-slow")) for (const vp of slow) record(await resumeSlowFlow(t, proxy, vp));
          if (flows.includes("resume-blackhole")) for (const vp of slow) record(await resumeBlackholeFlow(t, proxy, vp));
          if (flows.includes("resume-two-pages")) record(await resumeTwoPagesFlow(t, proxy));
          if (flows.includes("resume-wake")) {
            const long = IDS.chats.markdown;
            let ready: string | null = null;
            await serverTurn(t, long, WAKE_REPLY, 120_000).catch((e: Error) => (ready = e.message));
            for (const vp of slow) record(ready ? finish({ kind: "flow", name: "resume-wake", route: "chat", scene: t.scene, size: sizeTag(vp), theme: "dark", path: `/c/${long}`, failures: [{ code: "run", text: `the long reply could not be set up: ${ready}` }], warnings: [], note: "", ms: 0, details: {} }) : await resumeWakeFlow(t, proxy, vp, long));
          }
          if (flows.includes("resume-tail")) for (const vp of slow) record(await resumeTailFlow(t, proxy, vp));
          if (flows.includes("resume-rtt")) for (const vp of slow) record(await resumeRttFlow(t, proxy, vp));
        }, [`http://127.0.0.1:${proxy.port}`]);
      } finally {
        proxy.stop();
      }
    }
    for (const vp of at("laptop", "phone")) await onSeed([{ name: "restart", route: "restart", vps: [vp] }], async (t) => record(await restartFlow(t, vp)));
    // S9: Cancel restart twice per size on one seed (no restart happens); S10: Restart now, a fresh seed per size.
    const twoSizes = at("laptop", "phone");
    await onSeed([{ name: "restart-cancel", route: "restart", vps: twoSizes }], async (t) => {
      for (const vp of twoSizes) record(await restartCancelFlow(t, vp));
    });
    for (const vp of twoSizes) await onSeed([{ name: "restart-now", route: "restart", vps: [vp] }], async (t) => record(await restartNowFlow(t, vp)));
    // S16: End it here and copy at the three sizes on one seed (Send again ends each hand-over before the next size).
    const threeSizes = [...at("laptop", "medium", "phone"), ...extraAt("end-here")];
    await onSeed([{ name: "end-here", route: "terminal", vps: threeSizes }], async (t) => {
      for (const vp of threeSizes) record(await endHereFlow(t, vp));
    });
    // Row 99: Remove refused while the example chat runs (the running scene), then notes-api removed: a fresh seed per
    // size, at 1280x800 and on the phone, each in both themes.
    for (const vp of [...(CORE.some((v) => v.name === "laptop") ? [WIDE_LAPTOP] : []), ...at("phone"), ...extraAt("env-remove")])
      await onSeed([{ name: "env-remove", route: "projectRemove", vps: [vp] }], async (t) => record(await envRemoveFlow(t, vp)), undefined, undefined, "running");
    // R16: a kill -9 during a turn, on a seed whose fake claude finishes its turn after its host is gone.
    const finishSizes = [...twoSizes, ...extraAt("finishing")];
    await onSeed([{ name: "finishing", route: "chat", vps: finishSizes }], async (t) => {
      for (const vp of finishSizes) record(await finishingFlow(t, vp));
    }, undefined, { finishTurnOnStdinEnd: true });
    // Row 111: Send now at 1280x800 and on the phone, a fresh seed each (the long command's task goes on in the
    // background after the flow), and Ctrl+Enter at 1280x800 on one more.
    const laptopWide = CORE.some((v) => v.name === "laptop") ? [WIDE_LAPTOP] : [];
    for (const vp of [...laptopWide, ...at("phone"), ...extraAt("send-now")]) await onSeed([{ name: "send-now", route: "message", vps: [vp] }], async (t) => record(await sendNowFlow(t, vp)));
    // A fresh seed per size (v0.6 touch: the large tablet's run after the laptop's would meet its queued messages).
    for (const vp of [...laptopWide, ...touchAt("send-now-key")]) await onSeed([{ name: "send-now-key", route: "chat", vps: [vp] }], async (t) => record(await sendNowKeyFlow(t, vp)));
    // v0.6 touch: a cut tool result (one turn of 7,000 characters, then every size); the composition rule's sends; Stop
    // from the session menu, + and a card's foot (a fresh seed per run, since Stop ends the turn); Open on phone with a
    // remote origin, with a link form and with none.
    const cutVps = touchAt("cut-output");
    await onSeed([{ name: "cut-output", route: "tool", vps: cutVps }], async (t) => {
      let ready: string | null = null;
      await serverTurn(t, EX.chat, CUT_OUTPUT.prompt).catch((e: Error) => (ready = e.message));
      for (const vp of cutVps) for (const theme of THEMES) record(ready ? finish({ kind: "flow", name: "cut-output", route: "tool", scene: t.scene, size: sizeTag(vp), theme, path: `/c/${EX.chat}`, failures: [{ code: "run", text: `the cut turn could not run: ${ready}` }], warnings: [], note: "", ms: 0, details: {} }) : await cutOutputFlow(t, vp, theme));
    });
    // A hold while a reply streams and the view follows the end: a fresh seed per run, since each run adds its turn.
    for (const vp of touchAt("stream-hold"))
      for (const theme of THEMES) await onSeed([{ name: "stream-hold", route: "chat", vps: [vp] }], async (t) => record(await streamHoldFlow(t, vp, theme)));
    // composer-fit while a turn runs (the running scene's turn; nothing here stops it).
    const fitVps = touchAt("composer-fit");
    await onSeed([{ name: "composer-fit", route: "details", vps: fitVps }], async (t) => {
      for (const vp of fitVps) for (const theme of THEMES) record(await composerFitFlow(t.base, t.scene as SeedSceneName, vp, theme, "running"));
    }, undefined, undefined, "running");
    const imeVps = touchAt("ime-touch");
    await onSeed([{ name: "ime-touch", route: "send", vps: imeVps }], async (t) => {
      for (const vp of imeVps) for (const theme of THEMES) record(await imeTouchFlow(t, vp, theme));
    });
    for (const kind of ["running", "permission"] as const)
      for (const vp of touchAt("stop-menu"))
        for (const theme of THEMES) await onSeed([{ name: "stop-menu", route: "stop", vps: [vp] }], async (t) => record(await stopMenuFlow(t, vp, theme, kind)), undefined, undefined, kind);
    const phoneVps = touchAt("open-on-phone");
    const onPhoneSeed = async (form: "plain" | "template" | "none", vps: Viewport[], themes: readonly Theme[]) => {
      if (!flows.includes("open-on-phone") || !vps.length || cdp.closed) return;
      let t: Target;
      try {
        if (BASE) throw new Error("--base boots no seed");
        const b = await boot({ scene: "main", port: PORT, dist: built!, keep: KEEP, env: SERVER_ENV, ...(form === "none" ? {} : { origins: [PHONE_ORIGIN] }), ...(form === "template" ? { phoneLink: PHONE_LINK_FORM } : {}) });
        live.add(b);
        t = { base: b.base, scene: "main", booted: b };
      } catch (e) {
        for (const vp of vps) bootFailed({ kind: "flow", name: "open-on-phone", route: "phone", scene: "main", path: `/c/${EX.chat}/phone` }, vp, themes[0]!, (e as Error).message);
        return;
      }
      try {
        for (const vp of vps) for (const theme of themes) record(await openOnPhoneFlow(t, vp, theme, form));
      } finally {
        await closeTarget(t, problems);
      }
    };
    await onPhoneSeed("plain", phoneVps, THEMES);
    await onPhoneSeed("template", phoneVps.filter((v) => v.label === "m768" || v.label === "phone-land"), [THEMES[0]!]);
    await onPhoneSeed("none", phoneVps.filter((v) => v.label === "medium"), [THEMES[0]!]);
  }

  // Part 2 (row 73, D60): worktree-new to worktree-off at each size, on a fresh seed of the worktree scene each. Picking
  // worktree-gone or worktree-archive-delete runs worktree-new first, since they work on what it makes.
  const part2 = PART2_FLOWS.filter((f) => flows.includes(f) || (f === "worktree-new" && (flows.includes("worktree-gone") || flows.includes("worktree-archive-delete"))));
  if (!BASE && !cdp.closed && part2.length) for (const vp of [...CORE, ...extraAt("worktree-new")]) if (!cdp.closed) await part2OnSeed(vp, part2, record, problems);
  // W5: a refused resume at each size, each on a seed of its own (its fake claude refuses every resume).
  if (!BASE && flows.includes("worktree-refused")) for (const vp of [...CORE, ...extraAt("worktree-refused")]) if (!cdp.closed) record(await worktreeRefusedFlow(vp));
  // Row 99 in part 2: Remove of a worktree environment with variables, at 1280x800 and on the phone, a fresh seed each.
  if (!BASE && flows.includes("env-remove-worktree")) for (const vp of [...(CORE.some((v) => v.name === "laptop") ? [WIDE_LAPTOP] : []), ...CORE.filter((v) => v.name === "phone"), ...extraAt("env-remove-worktree")]) if (!cdp.closed) record(await envRemoveWorktreeFlow(vp));
  if (BASE && (part2.length || flows.includes("worktree-refused") || flows.includes("env-remove-worktree"))) console.log("ui-check: the part 2 flows boot a seed of their own, so --base runs none of them");
  // Row 108: the self update's flows, each on a scratch checkout of its own.
  if (!cdp.closed) await updateFlows(flows, record, problems);
  // Row 116: the four dots and the seen flag, on the dots scene's seed.
  if (flows.includes("unseen-dot") && !cdp.closed) await unseenDotFlows(record, problems);
  // R124: the side chat, on the side scene's seed.
  if ((flows.includes("side-chat") || flows.includes("side-chat-running")) && !cdp.closed) await sideChatFlows(flows, record, problems);
  // FIX-U2: the side box's draft on two pages, on a side scene seed of its own.
  if (flows.includes("side-draft") && !cdp.closed) await sideDraftFlows(record, problems);
  // U2: a finished turn folded to one line, on a main scene seed of its own.
  if (flows.includes("turn-fold") && !cdp.closed) await turnFoldFlows(record, problems);
  // U3: the turn rail on the laptop, on a main scene seed of its own.
  if (flows.includes("turn-rail") && !cdp.closed) await turnRailFlows(record, problems);
  // R127: Trust this folder, on seeds of the trust scene of its own.
  if (flows.includes("trust-folder") && !cdp.closed) await trustFolderFlows(record, problems);
  // R131: background sessions that a chat starts, on main scene seeds of its own.
  if (flows.includes("background-session") && !cdp.closed) await backgroundSessionFlows(record, problems);
  // R130: notifications through a stub push service on 127.0.0.1, on main scene seeds of their own.
  if (flows.includes("notify") && !cdp.closed) await notifyFlows(record, problems);
  // R130: Bring back in the side chat, on a side scene seed of its own.
  if (flows.includes("bring-back") && !cdp.closed) await bringBackFlows(record, problems);
  // FIX-C1: the phone's message box with a draft of several lines, on a side scene seed of its own.
  if (flows.includes("composer-lines") && !cdp.closed) await composerLinesFlows(record, problems);
  // U5: search inside the conversations' text, on a main scene seed of its own.
  if (flows.includes("search-text") && !cdp.closed) await searchTextFlows(record, problems);
  // U1: the changed-files card and its diffs in the side panel, on a main scene seed of its own.
  if (flows.includes("changes-card") && !cdp.closed) await changesCardFlows(record, problems);
  // FIX-Q1: your own send goes to the end, on a main scene seed of its own.
  if (flows.includes("send-follow") && !cdp.closed) await sendFollowFlows(record, problems);
  // Iteration 7: the browser pane, on a main scene seed of its own with the shared browser and the local test site.
  if (flows.some((f) => f.startsWith("browser-")) && !cdp.closed) await browserPaneFlows(record, problems, flows);

  // A waiting card's field and the keyboard, on the elicitation scene's own seed.
  if (cardFlow && !cdp.closed) {
    const touch = [...CORE.filter((v) => v.touch), ...extraAt("card-keyboard")];
    let t: Target | null = null;
    try {
      t = await openTarget("elicitation");
      for (const vp of touch) record(await cardKeyboardFlow(t.base, "elicitation", vp));
    } catch (e) {
      for (const vp of touch) bootFailed({ kind: "flow", name: "card-keyboard", route: "elicitation", scene: "elicitation", path: `/c/${EX.chat}` }, vp, "light", (e as Error).message);
    } finally {
      if (t) await closeTarget(t, problems);
    }
  }

  // Action checks: a fresh seed per check, or per variant when the press leaves what the next size needs.
  for (const spec of specs) {
    if (cdp.closed) break;
    const scene = BASE ? null : spec.scene;
    const path = spec.path ?? ROUTE[spec.route]!.example;
    const what = { kind: "action" as const, name: spec.id, route: spec.route, scene, path };
    const groups: Viewport[][] = spec.fresh === "variant" || BASE ? [VPS] : VPS.map((vp) => [vp]);
    for (const group of groups) {
      if (cdp.closed) break;
      let t: Target;
      try {
        t = spec.scratch ? await openScratchTarget(spec.scene) : await openTarget(scene);
      } catch (e) {
        for (const vp of group) bootFailed(what, vp, "dark", (e as Error).message);
        continue;
      }
      try {
        for (const vp of group) record(await actionCheck(spec, t.base, scene, vp));
      } finally {
        await (spec.scratch ? closeScratchTarget(t, problems) : closeTarget(t, problems));
      }
    }
  }

  const lostBrowser = cdp.closed && !stopping;
  const failed = results.filter((r) => r.status === "fail");
  const warned = results.filter((r) => r.status === "warn");
  const byCode: Record<string, number> = {};
  for (const r of results) for (const f of [...r.failures, ...r.warnings]) byCode[f.code] = (byCode[f.code] ?? 0) + 1;
  const byKind: Record<string, { checks: number; failed: number; warned: number }> = {};
  for (const r of results) {
    const k = (byKind[r.kind] ??= { checks: 0, failed: 0, warned: 0 });
    k.checks++;
    if (r.status === "fail") k.failed++;
    if (r.status === "warn") k.warned++;
  }
  // Per route (and check id): how many of its checks failed, and the reasons with how often each came.
  const byRoute: Record<string, { checks: number; failed: number; reasons: Record<string, number> }> = {};
  for (const r of results) {
    const key = `${r.kind} ${r.scene && r.scene !== "main" ? `${r.name}[${r.scene}]` : r.name}`;
    const e = (byRoute[key] ??= { checks: 0, failed: 0, reasons: {} });
    e.checks++;
    if (r.status === "fail") e.failed++;
    for (const f of r.failures) {
      const reason = `${f.code}: ${clip(f.text.replace(/\b\d+(\.\d+)?\b/g, "N"), 160)}`;
      e.reasons[reason] = (e.reasons[reason] ?? 0) + 1;
    }
  }
  const finished = new Date();
  const report = {
    tool: "ui-check",
    target: BASE ?? `the click-through seed (test/click) on 127.0.0.1:${PORT}`,
    startedAt: started.toISOString(),
    finishedAt: finished.toISOString(),
    seconds: Math.round((finished.getTime() - started.getTime()) / 1000),
    browser: { product: version.product, own: Boolean(own), laptopPointer: pointer },
    matrix: { routes: cases.map((c) => c.id), actions: specs.map((s) => s.id), flows, sizes: VPS, themes: THEMES, checks: CHECKS, actionWaitMs: ACTION_WAIT },
    scenes: BASE ? null : Object.fromEntries(SCENES.map((s) => [s, SCENE[s].about])),
    seedIds: { chat: EX.chat, project: EX.project, session: EX.session, message: EX.message, toolUse: EX.toolUse, request: EX.request, uploads: IDS.uploads },
    summary: { checks: results.length, passed: results.length - failed.length - warned.length, failed: failed.length, warned: warned.length, byKind, findings: byCode, problems, lostBrowser },
    byRoute,
    checks: results.map((r) => ({ ...r, shot: r.shot ? r.shot.slice(OUT.length + 1) : undefined })),
  };
  await Bun.write(join(OUT, "report.json"), JSON.stringify(report, null, 2) + "\n");

  const codes = Object.entries(byCode).sort((a, b) => b[1] - a[1]).map(([k, n]) => `${k} ${n}`).join(", ");
  const kinds = Object.entries(byKind).map(([k, v]) => `${k} ${v.failed} of ${v.checks} failed`).join(", ");
  console.log(
    `ui-check: ${results.length} checks, ${report.summary.passed} passed, ${failed.length} failed, ${warned.length} with warnings only ` +
      `(${kinds})${codes ? `; findings: ${codes}` : ""}; ${report.seconds} s; report ${join(OUT, "report.json")}`,
  );
  for (const p of problems) console.log(`ui-check: ${p}`);
  if (lostBrowser) console.log("ui-check: the browser connection closed before every check ran");
  await cleanup();
  process.exit(failed.length || lostBrowser ? 1 : 0);
}

main().catch(async (e) => {
  console.error(`ui-check: ${(e as Error).stack ?? e}`);
  await cleanup();
  process.exit(2);
});
